(function () {
  "use strict";

  window.CATALOG_TEXTS = {
    tangshi300: [
    [17, "tangshi-ts-191", "public-domain", "花近高楼伤客心万方多难此登临锦江春色来天地玉垒浮云变古今北极朝廷终不改西山寇盗莫相侵可怜后主还祠庙日暮聊为梁甫吟", "繁花靠近高楼却伤了客子之心，万方多难时在此登临。锦江的春色来自天地之间，玉垒的浮云变幻着古今。北极星般的朝廷终究不会改变，西山的寇盗不要来侵扰。可怜那后主还留有祠庙，日暮时姑且吟起《梁甫吟》。"],
    [18, "tangshi-ts-179", "public-domain", "嗟君此别意何如驻马衔杯问谪居巫峡啼猿数行泪衡阳归雁几封书青枫江上秋帆远白帝城边古木疏圣代即今多雨露暂时分手莫踌躇", "唉，你们这一别心情如何，勒住马、举着杯询问贬谪的去处。巫峡的猿啼催人落下几行泪，衡阳的归雁可捎回几封书信。青枫江上秋帆远去，白帝城边古木稀疏。圣明的时代如今多有雨露之恩，暂时分手不必迟疑。"],
    [19, "poems-cz7-19", "academic", "岱宗夫如何齐鲁青未了造化钟神秀阴阳割昏晓荡胸生曾云决眦入归鸟会当凌绝顶一览众山小", "泰山到底怎么样呢？在齐鲁大地上，那青翠的山色望不到尽头。大自然把神奇和秀美都聚集在这里，山南和山北被分割成明亮和昏暗两面。望着层层云气升腾，心胸激荡；睁大眼睛看着归巢的鸟儿飞入山中。一定要登上泰山的顶峰，那时俯瞰群山，都会显得渺小。"],
    [20, "tangshi-ts-79", "public-domain", "车辚辚马萧萧行人弓箭各在腰爷娘妻子走相送尘埃不见咸阳桥牵衣顿足拦道哭哭声直上干云霄道旁过者问行人行人但云点行频或从十五北防河便至四十西营田去时里正与裹头归来头白还戍边边庭流血成海水武皇开边意未已君不闻汉家山东二百州千村万落生荆杞纵有健妇把锄犁禾生陇亩无东西况复秦兵耐苦战被驱不异犬与鸡长者虽有问役夫敢申恨且如今年冬未休关西卒县官急索租租税从何出信知生男恶反是生女好生女犹得嫁比邻生男埋没随百草君不见青海头古来白骨无人收新鬼烦冤旧鬼哭天阴雨湿声啾啾", "车辆辚辚作响，马匹萧萧嘶鸣，出征的人弓箭各自挂在腰间。爹娘妻子跑来相送，尘埃弥漫、看不见咸阳桥。牵着衣裳、跺着脚拦路痛哭，哭声直冲云霄。路旁经过的人询问出征的人，出征的人只说征兵频繁。有的十五岁就去北边防守黄河，到了四十岁还在西边屯田。去时里正给他裹头，回来头发白了还要戍边。边庭流血成海水，武帝开拓边地的心意还没有停止。你没听说汉家山东二百州，千村万落都长满了荆棘杞柳。纵然有健壮的妇人拿着锄犁，庄稼长在田里也分不清东西行列。何况秦地的兵耐得苦战，被驱赶得与狗鸡没有两样。长者虽然发问，役夫怎敢申诉怨恨。就像今年冬天，关西的兵卒还没有休整。县官急着催租，租税从哪里出。确实知道生男孩不好，反倒是生女孩好。生女孩还能嫁给近邻，生男孩就埋没在荒草之中。你没看见吗，青海边上，古来白骨无人收殓。新鬼含冤、旧鬼啼哭，天阴雨湿时哭声啾啾。"],
    [21, "tangshi-ts-7", "public-domain", "人生不相见动如参与商今夕复何夕共此灯烛光少壮能几时鬓发各已苍访旧半为鬼惊呼热中肠焉知二十载重上君子堂昔别君未婚儿女忽成行怡然敬父执问我来何方问答未及已驱儿罗酒浆夜雨剪春韭新炊间黄粱主称会面难一举累十觞十觞亦不醉感子故意长明日隔山岳世事两茫茫", "人生难得相见，动辄就像参星与商星一样此出彼没。今晚是什么好日子，竟能与你共对这灯烛之光。少年壮年能有几时，如今我们两鬓都已斑白。打探故旧，多半已成了鬼，令人惊呼叫喊，心中火热难平。哪里想到过了二十年，我又重新登上你的厅堂。当年分别时你还没结婚，如今儿女忽已成行。他们和悦地敬重父亲的挚友，问我从哪里来。问答还没完，你就催着儿女摆上酒菜。冒着夜雨去剪来春韭，刚煮好的饭里掺着黄粱。你说见面实在太难，一举杯就接连喝了十大杯。十杯也不觉得醉，是感念你情意深长。明天就要隔开重重山岳，世事茫茫，谁也难料。"],
    [22, "tangshi-ts-80", "public-domain", "三月三日天气新长安水边多丽人态浓意远淑且真肌理细腻骨肉匀绣罗衣裳照暮春蹙金孔雀银麒麟头上何所有翠微盍叶垂鬓唇背后何所见珠压腰衱稳称身就中云幕椒房亲赐名大国虢与秦紫驼之峰出翠釜水精之盘行素鳞犀箸厌饫久未下鸾刀缕切空纷纶黄门飞鞚不动尘御厨络绎送八珍箫鼓哀吟感鬼神宾从杂遝实要津后来鞍马何逡巡当轩下马入锦茵杨花雪落覆白苹青鸟飞去衔红巾炙手可热势绝伦慎莫近前丞相嗔", "三月三日天气清新，长安水边有许多美人。姿态秾丽、情意高远，娴淑而自然，肌肤细腻、骨肉匀称。绣罗衣裳映着暮春，用金线绣孔雀、银线绣麒麟。头上有什么，翠羽的叶饰垂到鬓边唇畔。背后见到什么，珍珠压着腰裙、十分合身。其中有云幕椒房的外戚，被赐封为虢国与秦国夫人。紫驼峰从翠釜中取出，水晶盘里盛着细切的鱼。犀角筷子吃腻了久久不下箸，鸾刀细切却空自纷忙。黄门飞马而来不扬尘土，御厨络绎不绝地送来八珍。箫鼓哀吟感动鬼神，宾客随从杂乱众多，都是权要之人。后来鞍马何等逡巡，到轩前下马走进锦茵。杨花如雪落下覆盖白苹，青鸟飞去衔来红巾。气焰炙手可热、势位无与伦比，千万不要靠近，免得丞相发怒。"],
    [23, "tangshi-ts-81", "public-domain", "少陵野老吞声哭春日潜行曲江曲江头宫殿锁千门细柳新蒲为谁绿忆昔霓旌下南苑苑中万物生颜色昭阳殿里第一人同辇随君侍君侧辇前才人带弓箭白马嚼啮黄金勒翻身向天仰射云一笑正坠双飞翼明眸皓齿今何在血污游魂归不得清渭东流剑阁深去住彼此无消息人生有情泪沾臆江水江花岂终极黄昏胡骑尘满城欲往城南望城北", "我少陵野老吞声哭泣，春日里悄悄走在曲江的曲处。江头的宫殿千门紧锁，细柳新蒲为谁而绿。回忆从前霓旌来到南苑，苑中万物都生出颜色。昭阳殿里第一美人，与君王同辇、侍奉在君王身边。辇前的才人带着弓箭，白马咬着黄金勒。翻身向天仰射云中，一笑之间正好射落双飞的鸟。那明眸皓齿如今在哪里，血污了游魂、回不来了。清渭东流、剑阁深远，去的和留的彼此都没有消息。人生有情、泪水沾胸，江水江花岂有尽头。黄昏胡骑扬尘满城，我想去城南却望着城北。"],
    [24, "tangshi-ts-82", "public-domain", "长安城头头白乌夜飞延秋门上呼又向人家啄大屋屋底达官走避胡金鞭断折九马死骨肉不得同驰驱腰下宝玦青珊瑚可怜王孙泣路隅问之不肯道姓名但道困苦乞为奴已经百日窜荆棘身上无有完肌肤高帝子孙尽隆准龙种自与常人殊豺狼在邑龙在野王孙善保千金躯不敢长语临交衢且为王孙立斯须昨夜东风吹血腥东来橐驼满旧都朔方健儿好身手昔何勇锐今何愚窃闻天子已传位圣德北服南单于花门剺面请雪耻慎勿出口他人狙哀哉王孙慎勿疏五陵佳气无时无", "长安城头有白头乌鸦，夜里飞到延秋门上呼号。又向人家啄食大屋，屋下的达官逃走躲避胡人。金鞭折断、九马死去，骨肉不能一同奔驰。腰下挂着宝玦和青珊瑚，可怜王孙在路旁哭泣。问他却不肯说出姓名，只说困苦、乞求做奴。已经有一百天躲藏在荆棘里，身上没有一处完好的肌肤。高帝的子孙都是高鼻，龙种自然与常人不同。豺狼在城里、真龙在野外，王孙你要好好保重千金之躯。不敢在十字路口与你长谈，姑且为王孙稍立片刻。昨夜东风吹来血腥，东来的骆驼挤满旧都。朔方的健儿身手好，从前何等勇锐如今何等愚拙。私下听说天子已经传位，圣德向北使南单于归服。回纥人割面请求雪耻，千万不要说出口、免得他人窥伺。可叹啊王孙你要小心不要疏忽，五陵的佳气无时不在。"],
    [25, "tangshi-ts-8", "public-domain", "绝代有佳人幽居在空谷自云良家子零落依草木关中昔丧乱兄弟遭杀戮官高何足论不得收骨肉世情恶衰歇万事随转烛夫婿轻薄儿新人美如玉合昏尚知时鸳鸯不独宿但见新人笑那闻旧人哭在山泉水清出山泉水浊侍婢卖珠回牵萝补茅屋摘花不插发采柏动盈掬天寒翠袖薄日暮倚修竹", "有一位举世无双的美人，幽居在空寂的山谷里。她说自己本是好人家的女儿，如今流落零落，依傍着草木生活。当年关中遭遇战乱，兄弟都被杀害。官位再高又有什么用，连亲人的尸骨都无法收殓。世态人情厌恶衰落，万事都像转动的烛焰一样变化无常。丈夫是个轻薄的人，新娶的妻子美如白玉。合欢花尚且懂得按时开合，鸳鸯也不会独自过夜。可只见新人欢笑，哪听得见旧人哭泣。山中的泉水是清的，流出山来就浑浊了。侍女卖掉首饰回来，牵着藤萝修补茅屋。摘下花来却不插在发间，采柏树枝叶常常采满一把。天冷了翠袖单薄，黄昏时她倚着高高的竹子。"],
    [28, "tangshi-ts-47", "public-domain", "国初已来画鞍马神妙独数江都王将军得名三十载人间又见真乘黄曾貌先帝照夜白龙池十日飞霹雳内府殷红玛瑙盘婕妤传诏才人索盘赐将军拜舞归轻纨细绮相追飞贵戚权门得笔迹始觉屏障生光辉昔日太宗拳毛騧近时郭家狮子花今之新图有二马复令识者久叹嗟此皆骑战一敌万缟素漠漠开风沙其余七匹亦殊绝迥若寒空动烟雪霜蹄蹴踏长楸间马官厮养森成列可怜九马争神骏顾视清高气深稳借问苦心爱者谁后有韦讽前支遁忆昔巡幸新丰宫翠华拂天来向东腾骧磊落三万匹皆与此图筋骨同自从献宝朝河宗无复射蛟江水中君不见金粟堆前松柏里龙媒去尽鸟呼风", "开国以来画鞍马的名家，神妙首推江都王。曹将军成名三十年，人间又见到真正神骏的良马。他曾画先帝的照夜白，龙池上十日雷鸣电闪。内府里深红的玛瑙盘，婕妤传旨、才人来索取。盘子赐给将军，他拜舞而回，轻薄细软的绫罗追着送来。贵戚权门得到他的墨迹，才觉得屏风生了光辉。从前太宗的拳毛騧，近时郭家的狮子花。如今这幅新图上有两匹马，又让识马的人久久叹赏。这些都是奔驰征战、以一敌万的骏马，白绢上仿佛漠漠扬起风沙。其余七匹也非常出色，远远望去像寒空中飘动的烟雪。霜白的马蹄踏过长楸之间，马官和马夫密密麻麻排成行列。可爱的九匹马争显神骏，顾盼清高、气度深沉稳健。请问苦心爱马的是谁？后有韦讽，前有支遁。回忆当年圣上巡幸新丰宫，翠羽华盖拂天向东而来。腾跃奔放的三万匹马，筋骨都与这图上的马相同。自从献宝朝见河宗之后，再也不见在江水中射蛟。你没看见吗，金粟堆前的松柏里，骏马都已离去，只有鸟儿在风中呼叫。"],
    [29, "tangshi-ts-48", "public-domain", "将军魏武之子孙于今为庶为清门英雄割据虽已矣文采风流今尚存学书初学卫夫人但恨无过王右军丹青不知老将至富贵于我如浮云开元之中常引见承恩数上南薰殿凌烟功臣少颜色将军下笔开生面良相头上进贤冠猛将腰间大羽箭褒公鄂公毛发动英姿飒爽来酣战先帝御马玉花骢画工如山貌不同是日牵来赤墀下迥立阊阖生长风诏谓将军拂绢素意匠惨淡经营中斯须九重真龙出一洗万古凡马空玉花却在御榻上榻上庭前屹相向至尊含笑催赐金圉人太仆皆惆怅弟子韩幹早入室亦能画马穷殊相幹惟画肉不画骨忍使骅骝气凋丧将军善画盖有神必逢佳士亦写真即今漂泊干戈际屡貌寻常行路人途穷反遭俗眼白世上未有如公贫但看古来盛名下终日坎壈缠其身", "曹将军是魏武帝曹操的后代，如今却成了平民百姓、清贫之家。英雄割据的时代虽然已经过去，曹家的文采风流如今还留存着。你学书法最初学卫夫人，只恨没能超过王右军。你专心绘画，不知老年将至，把富贵看得如浮云一般。开元年间你常被引见，承蒙恩宠多次登上南薰殿。凌烟阁的功臣画像已色彩暗淡，将军下笔便另开生面。良相头上戴上进贤冠，猛将腰间佩着大羽箭。褒国公、鄂国公画像上须发都能飘动，英姿飒爽像要前来酣战。先帝的御马玉花骢，画工多如山却画得各不相同。那天牵到殿前红阶下，昂然独立，宫门间顿生长风。下诏叫将军展开白绢，构思时惨淡经营。片刻间九重天上下凡来了真龙，把万古以来的凡马一扫而空。玉花骢仿佛就在御榻之上，榻上与庭前的马屹然相对。皇上含笑催促赐金，马夫、太仆都感到惆怅。你的弟子韩幹早已登堂入室，也能画马穷尽各种形态。但韩幹只画肉不画骨，竟让骏马的神气凋丧。将军善于画马，大概是有神助，遇到佳士也一定为之写真。如今你在战乱中漂泊，常常画些寻常的路人。途穷反而遭世俗的白眼，世上没有像你这样困顿的人。只看古来有盛名的人，往往终生坎坷缠身。"],
    [31, "tangshi-ts-50", "public-domain", "孔明庙前有老柏柯如青铜根如石霜皮溜雨四十围黛色参天二千尺君臣已与时际会树木犹为人爱惜云来气接巫峡长月出寒通雪山白忆昨路绕锦亭东先主武侯同閟宫崔嵬枝干郊原古窈窕丹青户牖空落落盘踞虽得地冥冥孤高多烈风扶持自是神明力正直原因造化功大厦如倾要梁栋万牛回首丘山重不露文章世已惊未辞剪伐谁能送苦心岂免容蝼蚁香叶终经宿鸾凤志士幽人莫怨嗟古来材大难为用", "孔明庙前有一株老柏，枝干如青铜、根如磐石。皮色如霜、沾雨溜滑，粗有四十围；深青的树色参天，高达二千尺。君臣已与时代际会相合，树木尚且为人们所爱惜。云气飘来与巫峡的云气相连，月亮升起寒气通到雪山的洁白。回忆从前路过锦亭东边，先主刘备与武侯诸葛亮同在一座祠庙里。枝干高峻，郊野一片古意；幽深的彩绘，门窗却已空寂。孤傲地盘踞虽然得到了好地方，但孤高幽暗却多受烈风。能扶持它本是神明的力量，它的正直原出于造化的功效。大厦如果倾危就需要梁栋，但它重如山丘，万头牛也拉不动。不显露纹彩已使世人惊叹，不辞砍伐又有谁能运送。苦心经营岂能免于蝼蚁侵蚀，芳香的树叶终究经得起鸾凤栖宿。志士幽人不要怨叹，自古以来大材总是难以被任用。"],
    [33, "tangshi-ts-110", "public-domain", "今夜鄜州月闺中只独看遥怜小儿女未解忆长安香雾云鬟湿清辉玉臂寒何时倚虚幌双照泪痕干", "今夜鄜州的月亮，只有你在闺中独自观看。遥想可怜的小儿女，还不懂得思念长安。香雾沾湿了你的云鬓，清冷的月光使你的玉臂生寒。什么时候才能一同倚在薄帷上，让月光双双照干我们的泪痕。"],
    [34, "tangshi-ts-111", "public-domain", "国破山河在城春草木深感时花溅泪恨别鸟惊心烽火连三月家书抵万金白头搔更短浑欲不胜簪", "国都沦陷山河依旧，城中春天草木深深。感伤时局，看见花也落泪；痛恨离别，听见鸟叫也心惊。战火连着几个月，一封家书抵得上万两黄金。白发越搔越短，简直要插不住簪子。"],
    [35, "tangshi-ts-113", "public-domain", "此道昔归顺西郊胡正繁至今残破胆应有未招魂近得归京邑移官岂至尊无才日衰老驻马望千门", "这条路当年是我归顺朝廷时走过的，那时西郊的胡人正多。至今还心惊胆战，应当有未招回的魂魄。近来得以回到京城，调任外官岂是皇上的本意。我没有才能又日渐衰老，勒住马遥望那千门万户。"],
    [36, "poems-cz9-10", "academic", "戍鼓断人行边秋一雁声露从今夜白月是故乡明有弟皆分散无家问死生寄书长不达况乃未休兵", "戍楼的更鼓断绝了人们的来往，边塞的秋天传来一只大雁的叫声。从今夜起就进入白露节气，月亮还是故乡的最明亮。虽有兄弟但都已离散，没有家可以打听他们的生死。寄出的书信常常不能送到，何况战乱还没有停止。"],
    [38, "tangshi-ts-186", "public-domain", "丞相祠堂何处寻锦官城外柏森森映阶碧草自春色隔叶黄鹂空好音三顾频烦天下计两朝开济老臣心出师未捷身先死长使英雄泪满襟", "丞相的祠堂到哪里去寻找，锦官城外柏树森森。映着台阶的碧草空自呈着春色，隔着树叶的黄鹂徒然叫着好音。三顾茅庐频频询问天下大计，两朝开济、尽老臣之心。出师未捷而身先死去，常使英雄泪满衣襟。"],
    [39, "poems-gz11-20", "academic", "舍南舍北皆春水但见群鸥日日来花径不曾缘客扫蓬门今始为君开盘飧市远无兼味樽酒家贫只旧醅肯与邻翁相对饮隔篱呼取尽余杯", "草堂的南边北边都涨满了春水，只见一群群鸥鸟天天飞来。长满花草的小路从来没有因为客人而打扫，今天这扇蓬门才第一次为你打开。因为离集市太远，盘中的菜肴没有多种美味；家里贫穷，杯中的酒只是旧年的浊酒。如果你愿意和邻居的老翁一起对饮，我就隔着篱笆把他喊来，一起把剩下的酒喝完。"],
    [41, "tangshi-ts-188", "public-domain", "西山白雪三城戍南浦清江万里桥海内风尘诸弟隔天涯涕泪一身遥惟将迟暮供多病未有涓埃答圣朝跨马出郊时极目不堪人事日萧条", "西山白雪下有三城的戍守，南浦清江上有万里桥。海内动荡，兄弟们都相隔异地；天涯遥远，我一人独自流泪。只能用迟暮之身对付多病，没有一丝一毫报答圣朝。骑马出郊时极目远望，不堪人事日渐萧条。"],
    [42, "tangshi-ts-116", "public-domain", "远送从此别青山空复情几时杯重把昨夜月同行列郡讴歌惜三朝出入荣江村独归处寂寞养残生", "远送至此就要分别，青山空自依依有情。什么时候才能重举酒杯，昨夜我们还一同在月下行走。各郡讴歌惋惜你的离去，你三朝出入都很荣显。我独自回到江村，寂寞地度过残生。"],
    [43, "poems-xx5-16", "school", "剑外忽传收蓟北初闻涕泪满衣裳却看妻子愁何在漫卷诗书喜欲狂白日放歌须纵酒青春作伴好还乡即从巴峡穿巫峡便下襄阳向洛阳", "在剑门关外忽然听说官军收复了蓟北，刚听到消息时眼泪沾满了衣裳。回头看妻子儿女的愁容不知哪里去了，随手卷起诗书欢喜得快要发狂。白天要放声高歌，痛饮美酒，趁着春光正好伴我返回故乡。即刻从巴峡穿过巫峡，再顺流而下经过襄阳直奔洛阳。"],
    [44, "poems-gz10-05", "academic", "风急天高猿啸哀渚清沙白鸟飞回无边落木萧萧下不尽长江滚滚来万里悲秋常作客百年多病独登台艰难苦恨繁霜鬓潦倒新停浊酒杯", "风急天高，猿猴哀哀地啼叫；水清沙白，鸟儿在急风中盘旋。无边无际的树木萧萧地落下枯叶，望不到头的长江滚滚奔流而来。悲对秋景，感慨万里漂泊常年作客他乡，一生多病，今日独自登上高台。历尽了艰难苦恨，白发长满了双鬓，穷困潦倒，刚刚又停下了浇愁的酒杯。"],
    [45, "tangshi-ts-117", "public-domain", "他乡复行役驻马别孤坟近泪无干土低空有断云对棋陪谢傅把剑觅徐君惟见林花落莺啼送客闻", "在他乡又要奔波远行，勒住马告别这孤零零的坟。走近坟前，泪水使地上的土没有一处是干的，低空飘着断开的云。当年我曾陪你对棋，如今像季札那样把剑挂在徐君墓树上。只见林中花落，莺啼送客声声入耳。"],
    [46, "tangshi-ts-191", "public-domain", "花近高楼伤客心万方多难此登临锦江春色来天地玉垒浮云变古今北极朝廷终不改西山寇盗莫相侵可怜后主还祠庙日暮聊为梁甫吟", "繁花靠近高楼却伤了客子之心，万方多难时在此登临。锦江的春色来自天地之间，玉垒的浮云变幻着古今。北极星般的朝廷终究不会改变，西山的寇盗不要来侵扰。可怜那后主还留有祠庙，日暮时姑且吟起《梁甫吟》。"],
    [47, "tangshi-ts-192", "public-domain", "清秋幕府井梧寒独宿江城蜡炬残永夜角声悲自语中天月色好谁看风尘荏苒音书绝关塞萧条行路难已忍伶俜十年事强移栖息一枝安", "清秋的幕府里井边梧桐生寒，独自宿在江城、蜡炬将要烧残。长夜的角声悲凉、仿佛自言自语，中天的月色虽好又有谁看。风尘荏苒、音书断绝，关塞萧条、行路艰难。已忍受伶俜漂泊十年的往事，勉强迁就栖息、求得一枝之安。"],
    [48, "tangshi-ts-118", "public-domain", "细草微风岸危樯独夜舟星垂平野阔月涌大江流名岂文章著官应老病休飘飘何所似天地一沙鸥", "微风吹着岸边的细草，高耸的桅杆下夜里独泊着一只船。星星低垂、原野显得开阔，月亮涌起、大江奔流。名声岂是靠文章显著，官职应当因老病而罢休。飘泊不定像什么呢，像天地间一只沙鸥。"],
    [49, "tangshi-ts-193", "public-domain", "岁暮阴阳催短景天涯霜雪霁寒宵五更鼓角声悲壮三峡星河影动摇野哭千家闻战伐夷歌数处起渔樵卧龙跃马终黄土人事音书漫寂寥", "岁暮时日月催逼着短促的光阴，天涯的霜雪在寒夜放晴。五更的鼓角声悲壮，三峡的星河倒影摇动。野外的哭声千家里传来，是听到了战伐的消息；夷人的歌声几处响起，来自渔夫樵夫。卧龙诸葛亮与跃马的公孙述终究都成了黄土，人事与音书都徒然寂寥。"],
    [50, "tangshi-ts-233", "public-domain", "功盖三分国名成八阵图江流石不转遗恨失吞吴", "功业盖过三分的国家，名声成就于八阵图。江水奔流而阵石不移，遗恨的是失计于吞吴。"],
    [56, "poems-cz7-06", "academic", "岐王宅里寻常见崔九堂前几度闻正是江南好风景落花时节又逢君", "当年在岐王的府宅里常常看到你，在崔九的堂前也多次听过你的歌唱。如今正是江南风景最好的时候，在这落花的时节又遇到了你。"],
    [57, "poems-gz10-21", "academic", "昔闻洞庭水今上岳阳楼吴楚东南坼乾坤日夜浮亲朋无一字老病有孤舟戎马关山北凭轩涕泗流", "从前就听说过洞庭湖的盛名，今天终于登上了岳阳楼。吴地和楚地被洞庭湖分割在东南两边，天地日月仿佛都日夜浮在湖中。亲戚朋友没有一封信来，年老多病只有一叶孤舟相伴。北方的关山又在燃起战火，我凭栏远望，涕泪横流。"],
    [59, "tangshi-ts-143", "public-domain", "泉壑带茅茨云霞生薜帷竹怜新雨后山爱夕阳时闲鹭栖常早秋花落更迟家童扫萝径昨与故人期", "泉流山谷围绕着茅屋，云霞从薜荔的帷幕上升起。竹子在新雨后可爱，山在夕阳时最可爱。悠闲的白鹭归栖常早，秋花落得更迟。家童扫着藤萝小径，昨天已与故人相约。"],
    [60, "tangshi-ts-142", "public-domain", "上国随缘住来途若梦行浮天沧海远去世法舟轻水月通禅寂鱼龙听梵声惟怜一灯影万里眼中明", "你随缘在上国居住，来时的路途像梦一样。沧海浮天多么遥远，你离世乘坐的法舟轻快。水月通达禅寂之境，鱼龙也来听你诵经的声音。只怜那一盏孤灯的光影，在万里之外也照得眼中明亮。"],
    [61, "tangshi-ts-202", "public-domain", "二月黄鹂飞上林春城紫禁晓阴阴长乐钟声花外尽龙池柳色雨中深阳和不散穷途恨霄汉常悬捧日心献赋十年犹未遇羞将白发对华簪", "二月里黄鹂飞上林苑，春日的紫禁城清晨阴阴。长乐宫的钟声在花外消尽，龙池的柳色在雨中更深。和暖的阳气驱不散穷途的怨恨，云霄之中常悬着捧日之心。献赋十年仍未遇合，羞于带着白发去面对华簪。"],
    [65, "poems-xx5-07", "school", "月落乌啼霜满天江枫渔火对愁眠姑苏城外寒山寺夜半钟声到客船", "月亮落下，乌鸦啼叫，满天霜气，江边的枫树和渔船上的灯火伴着我的愁绪入睡。姑苏城外的寒山寺，半夜里敲响的钟声传到了客船上。"],
    [66, "tangshi-ts-146", "public-domain", "长簟迎风早空城澹月华星河秋一雁砧杵夜千家节候看应晚心期卧已赊向来吟秀句不觉已鸣鸦", "长竹席迎风早凉，空城里月色淡淡。星河下秋夜里一只孤雁，夜里千家传来砧杵声。看节候应当已晚，心中期盼高卧却已成空。方才吟咏你秀美的诗句，不知不觉已经鸦鸣天晓。"],
    [67, "tangshi-ts-204", "public-domain", "仙台初见五城楼风物凄凄宿雨收山色遥连秦树晚砧声近报汉宫秋疏松影落空坛静细草香闲小洞幽何用别寻方外去人间亦自有丹丘", "在仙台初次见到五城楼，风物凄清、宿雨刚收。山色远远连着秦地的树、已近傍晚，砧声传来、近报汉宫的秋意。稀疏的松影落在空坛上、一片寂静，细草的清香闲淡、小洞清幽。何必到别处去寻找方外之地，人间也自有丹丘仙境。"],
    [68, "poems-xx6-08", "school", "春城无处不飞花寒食东风御柳斜日暮汉宫传蜡烛轻烟散入五侯家", "暮春时节，长安城里处处飞舞着落花，寒食节的东风把皇宫里的柳枝吹得斜斜的。黄昏时分，汉宫里传出赐新火的旨意，轻烟就飘散在权贵人家的门前。"],
    [69, "tangshi-ts-205", "public-domain", "莺啼燕语报新年马邑龙堆路几千家住层城临汉苑心随明月到胡天机中锦字论长恨楼上花枝笑独眠为问元戎窦车骑何时返旆勒燕然", "莺啼燕语报告新年，马邑龙堆的路途有几千里。家住在层城、临近汉苑，心随着明月到了胡天。机中织出锦字诉说长恨，楼上的花枝嘲笑独自成眠。请问主将窦车骑，什么时候才能班师回朝、在燕然山刻石纪功。"],
    [71, "tangshi-ts-267", "public-domain", "纱窗日落渐黄昏金屋无人见泪痕寂寞空庭春欲晚梨花满地不开门", "纱窗外日落、渐近黄昏，金屋里无人看见我的泪痕。寂寞的空庭中春天将要过去，梨花满地却不开门。"],
    [72, "poems-xx2-03", "school", "白日依山尽黄河入海流欲穷千里目更上一层楼", "太阳靠着山头落下，黄河向海里奔流。要想看尽千里之外的风光，就要再登上一层楼。"],
    [74, "tangshi-ts-147", "public-domain", "道由白云尽春与青溪长时有落花至远随流水香闲门向山路深柳读书堂幽映每白日清辉照衣裳", "道路在白云的尽头，春意与青溪一样悠长。时时飘落的花瓣，远远随着流水飘香。闲静的柴门对着山路，深密的柳林中是读书堂。幽暗的树影映着白日的阳光，清辉照在衣裳上。"],
    [76, "tangshi-ts-149", "public-domain", "故关衰草遍离别正堪悲路出寒云外人归暮雪时少孤为客早多难识君迟掩泪空相向风尘何处期", "故乡的关隘衰草遍地，离别正令人悲伤。道路延伸到寒云之外，你归去时正逢暮雪。我年少丧父、很早就作客他乡，历经多难与你相识太迟。掩着泪水空自相对，风尘之中何处才能相会。"],
    [78, "tangshi-ts-269", "public-domain", "玉楼天半起笙歌风送宫嫔笑语和月殿影开闻夜漏水精帘卷近秋河", "玉楼高耸半入天空、响起笙歌，风送来宫嫔们和谐的笑语。月殿的影子散开、听见夜漏的声音，卷起水晶帘、仿佛靠近了秋夜的银河。"],
    [84, "tangshi-ts-206", "public-domain", "云开远见汉阳城犹是孤帆一日程估客昼眠知浪静舟人夜语觉潮生三湘愁鬓逢秋色万里归心对月明旧业已随征战尽更堪江上鼓鼙声", "云开之后远远望见汉阳城，却还有孤帆一天的路程。商人白天睡觉、知道浪已平静，船夫夜里说话、感到潮水上涨。三湘的愁鬓迎着秋色，万里的归心对着明月。旧日的家业已随征战而尽，更哪里受得了江上的战鼓声。"],
    [86, "tangshi-ts-150", "public-domain", "十年离乱后长大一相逢问姓惊初见称名忆旧容别来沧海事语罢暮天钟明日巴陵道秋山又几重", "十年离乱之后，长大成人了才相逢一次。问起姓氏、初见时感到惊讶，说出名字才想起旧日的容貌。分别以来世事沧桑，谈完了已是暮天的钟声。明天你要走上巴陵的道路，又是几重秋山相隔。"],
    [88, "poems-cz7-08", "school", "回乐烽前沙似雪受降城外月如霜不知何处吹芦管一夜征人尽望乡", "回乐峰前的沙地白得像雪，受降城外的月色冷得像霜。不知道哪里吹起了芦管，一夜之间，出征的人都望着故乡。"],
    [89, "tangshi-ts-239", "public-domain", "鸣筝金粟柱素手玉房前欲得周郎顾时时误拂弦", "金粟装饰的筝柱发出鸣响，洁白的手弹在玉房之前。想得到周郎那样的顾盼，便时时故意弹错琴弦。"],
    [90, "tangshi-ts-153", "public-domain", "世乱同南去时清独北还他乡生白发旧国见青山晓月过残垒繁星宿故关寒禽与衰草处处伴愁颜", "世道离乱时一同南去，时局清平后你却独自北还。在他乡生出了白发，回到故国可见青山。晓月下走过残破的营垒，繁星下歇宿在旧日的关隘。寒天的禽鸟与衰败的野草，处处伴随着你愁苦的容颜。"],
    [91, "tangshi-ts-151", "public-domain", "故人江海别几度隔山川乍见翻疑梦相悲各问年孤灯寒照雨深竹暗浮烟更有明朝恨离杯惜共传", "老朋友在江海间分别，几次相隔山川。忽然相见反而疑心是梦，相互悲叹、各自询问年岁。孤灯在寒夜里照着雨，深竹在暗中浮起烟雾。更添明天分别的怅恨，珍惜这离别的酒杯共相传饮。"],
    [92, "tangshi-ts-152", "public-domain", "静夜四无邻荒居旧业贫雨中黄叶树灯下白头人以我独沉久愧君相见频平生自有分况是蔡家亲", "静夜里四邻无人，荒凉的居所、旧业贫寒。雨中是黄叶的树，灯下是白头的人。因为我长久独自沉沦，惭愧你频频来看望。平生本有缘分，何况还是表亲。"],
    [96, "tangshi-ts-53", "public-domain", "山石荦确行径微黄昏到寺蝙蝠飞升堂坐阶新雨足芭蕉叶大栀子肥僧言古壁佛画好以火来照所见稀铺床拂席置羹饭疏粝亦足饱我饥夜深静卧百虫绝清月出岭光入扉天明独去无道路出入高下穷烟霏山红涧碧纷烂漫时见松枥皆十围当流赤足踏涧石水声激激风吹衣人生如此自可乐岂必局束为人鞿嗟哉吾党二三子安得至老不更归", "山石险峻不平，山路狭窄，黄昏时到寺里，蝙蝠飞来飞去。登上殿堂坐在台阶上，刚下过透雨，芭蕉叶肥大、栀子花饱满。僧人说起古壁上佛画很好，举着火来照，看得却不很清楚。铺床扫席摆上饭菜，粗茶淡饭也足以充饥。夜深静静躺卧，各种虫声都停了，清月从山岭升起，月光照进门扉。天明独自离去，没有现成的道路，高高低低地穿行在烟雾之中。山花红艳、涧水碧绿，色彩纷繁烂漫，时时见到松树枥树都有十围粗。对着溪流赤足踏着涧石，水声激荡，风吹动衣裳。人生像这样本来就可乐，何必受拘束被人牵制。唉，我们这几个同道，怎能到老还不归隐呢。"],
    [97, "tangshi-ts-54", "public-domain", "纤云四卷天无河清风吹空月舒波沙平水息声影绝一杯相属君当歌君歌声酸辞且苦不能听终泪如雨洞庭连天九疑高蛟龙出没猩鼯号十生九死到官所幽居默默如藏逃下床畏蛇食畏药海气湿蛰熏腥臊昨者州前捶大鼓嗣皇继圣登夔皋赦书一日行万里罪从大辟皆除死迁者追回流者还涤瑕荡垢清朝班州家申名使家抑坎轲只得移荆蛮判司卑官不堪说未免捶楚尘埃间同时辈流多上道天路幽险难追攀君歌且休听我歌我歌今与君殊科一年明月今宵多人生由命非由他有酒不饮奈明何", "薄云四处消散，天上不见了银河，清风吹过天空，月亮散出波光。沙岸平旷、水面平静，声影都断绝了，我敬你一杯酒，你该唱首歌。你的歌声酸楚、言辞悲苦，我还没听完就泪如雨下。洞庭湖连天，九疑山高耸，蛟龙出没，猩猩和飞鼠哀号。你九死一生才到任所，幽居默默像躲藏的逃犯。下床怕蛇，吃饭怕毒，海气潮湿，蛰虫熏出腥臊之气。昨天州衙前擂响大鼓，新皇继位，起用夔、皋那样的贤臣。赦书一天传行万里，犯死罪的都免去死罪。被贬的追回、流放的放还，洗清污垢、整顿朝班。可州里申报了名字，却被观察使压下，命运坎坷，只调移到荆蛮之地。判司这样的卑官不值一提，免不了在尘埃中被鞭打。同时被贬的人大多已上路，可通向朝廷的天路幽险难以攀登。你别唱了，听我唱，我的歌今天与你不同调。一年中的明月今夜最圆最多，人生由命、不由别的，有酒不喝，怎么对得起这明月呢。"],
    [98, "tangshi-ts-55", "public-domain", "五岳祭秩皆三公四方环镇嵩当中火维地荒足妖怪天假神柄专其雄喷云泄雾藏半腹虽有绝顶谁能穷我来正逢秋雨节阴气晦昧无清风潜心默祷若有应岂非正直能感通须臾静扫众峰出仰见突兀撑青空紫盖连延接天柱石廪腾掷堆祝融森然魄动下马拜松柏一径趋灵宫粉墙丹柱动光彩鬼物图画填青红升阶伛偻荐脯酒欲以菲薄明其衷庙令老人识神意睢盱侦伺能鞠躬手持杯珓导我掷云此最吉余难同窜逐蛮荒幸不死衣食才足甘长终侯王将相望久绝神纵欲福难为功夜投佛寺上高阁星月掩映云朣胧猿鸣钟动不知曙杲杲寒日生于东", "五岳的祭祀规格都等同于三公，四方各有山镇环绕，嵩山居中。南方属火、土地荒僻多有妖怪，上天借给神明权柄让他专擅雄威。衡山喷云吐雾、云雾藏住半山腰，虽有绝顶又有谁能登到尽头。我来时正逢秋雨时节，阴气晦暗没有清风。我潜心默默祈祷，仿佛有应验，难道不是正直之心能够感通神明吗。不一会儿阴云静扫、群峰露出，抬头看见山峰突兀地撑着青天。紫盖峰连绵接着天柱峰，石廪峰腾跃堆叠连着祝融峰。景象森然令人心惊，我下马而拜，沿着松柏夹道的小路走向神庙。粉墙红柱光彩闪动，鬼神图画涂着青红之色。我登阶弯腰献上干肉和酒，想用微薄的祭品表明诚心。庙里的老人懂得神意，瞪着眼察言观色、善于鞠躬。他手持杯珓引导我投掷，说这一卦最吉，别的难以相比。我被贬逐到蛮荒之地侥幸不死，衣食刚够便甘愿在此终老。封侯拜相已不抱指望，神明纵然想赐福也难以奏效。夜里投宿佛寺登上高阁，星月在朦胧的云中掩映。猿鸣钟响不知不觉天已破晓，明亮的寒日从东方升起。"],
    [99, "tangshi-ts-56", "public-domain", "张生手持石鼓文劝我试作石鼓歌少陵无人谪仙死才薄将奈石鼓何周纲陵迟四海沸宣王愤起挥天戈大开明堂受朝贺诸侯剑佩鸣相磨蒐于岐阳骋雄俊万里禽兽皆遮罗镌功勒成告万世凿石作鼓隳嵯峨从臣才艺咸第一拣选撰刻留山阿雨淋日炙野火燎鬼物守护烦撝呵公从何处得纸本毫发尽备无差讹辞严义密读难晓字体不类隶与科年深岂免有缺画快剑斫断生蛟鼍鸾翔凤翥众仙下珊瑚碧树交枝柯金绳铁索锁钮壮古鼎跃水龙腾梭陋儒编诗不收入二雅褊迫无委蛇孔子西行不到秦掎摭星宿遗羲娥嗟余好古生苦晚对此涕泪双滂沱忆昔初蒙博士征其年始改称元和故人从军在右辅为我度量掘臼科濯冠沐浴告祭酒如此至宝存岂多毡包席裹可立致十鼓只载数骆驼荐诸太庙比郜鼎光价岂止百倍过圣恩若许留太学诸生讲解得切磋观经鸿都尚填咽坐见举国来奔波剜苔剔藓露节角安置妥帖平不颇大厦深檐与盖覆经历久远期无佗中朝大官老于事讵肯感激徒媕娿牧童敲火牛砺角谁复著手为摩挲日销月铄就埋没六年西顾空吟哦羲之俗书趁姿媚数纸尚可博白鹅继周八代争战罢无人收拾理则那方今太平日无事柄任儒术崇丘轲安能以此上论列愿借辩口如悬河石鼓之歌止于此呜呼吾意其蹉跎", "张生手里拿着石鼓文的拓本，劝我试作一首石鼓歌。少陵杜甫已不在，谪仙李白也已死去，我才学浅薄，对这石鼓又能怎么办呢。周朝纲纪衰败、四海沸腾，宣王发愤而起挥动天戈。大开明堂接受朝贺，诸侯的宝剑玉佩叮当作响、互相磨擦。在岐阳打猎驰骋雄俊，万里之内的禽兽都被网罗。要刻功记业昭告万世，凿开山石做成石鼓，削平了嵯峨的山崖。随从之臣才艺都是第一流，挑选他们撰写刻石留在山阿。任凭雨淋日晒、野火烧灼，鬼神守护、频频驱呵。你从哪里得到这纸拓本，毫发都完备、毫无差错。文辞严正、含义细密，读起来难以通晓，字体既不像隶书也不像科斗文。年代久远岂能没有缺笔，像快剑砍断的蛟鼍。又像鸾凤飞翔、众仙下降，珊瑚碧树交错着枝柯。像金绳铁索锁钮般雄壮，像古鼎跃出水面、龙腾如梭。浅陋的儒者编《诗》没有收入，《大雅》《小雅》狭隘局促，没有这般的从容舒展。孔子西行没有到秦国，如同拾取星宿而遗漏了日月。可叹我爱好古物却生得太晚，面对它泪如雨下。回忆当初蒙召为博士，那年才改元为元和。老朋友在右辅从军，替我度量挖掘石鼓的坑穴。我洗净冠、沐浴身体禀告祭酒，这样的至宝留存下来的还能有多少。用毡包席裹立刻可以取来，十只石鼓只需几头骆驼运载。进献太庙与郜鼎相比，光价岂止超过百倍。圣恩如果允许留在太学，诸生讲解还能互相切磋。当年在鸿都门观经尚且拥挤，眼看全国都要为此奔波而来。剜去苔藓、剔净藓苔，露出石鼓的棱角，安置得妥帖平稳、不偏不倚。用大厦深檐把它遮盖，经历久远也可望无事。朝中高官老于处事，怎肯激动感慨，只是唯唯诺诺敷衍。牧童在石上敲火，牛在上面磨角，谁还肯动手去摩挲它。日销月蚀，终将埋没，我在西边回望六年，徒然吟哦。王羲之的俗书追求姿媚，几张纸还能换得白鹅。继周之后八代争战结束，无人收拾，理当如此又能怎样。如今太平无事了，朝廷重用儒术、推崇孔孟。怎能把这些上奏论列，愿借你悬河般的辩才。石鼓之歌到此为止，唉，我的心意恐怕要落空了。"],
    [101, "tangshi-ts-87", "public-domain", "桂魄初生秋露微轻罗已薄未更衣银筝夜久殷勤弄心怯空房不忍归", "月亮初升、秋露微凉，轻薄的罗衣已觉寒冷却还没有换衣。夜深了还在殷勤地弹着银筝，心里害怕那空房、不忍回去。"],
    [102, "tangshi-ts-32", "public-domain", "汲井漱寒齿清心拂尘服闲持贝叶书步出东斋读真源了无取妄迹世所逐遗言冀可冥缮性何由熟道人庭宇静苔色连深竹日出雾露余青松如膏沐澹然离言说悟悦心自足", "从井里打水漱一漱寒凉的牙齿，清一清心，拂去衣上的尘土。闲来手持贝叶经书，走出东斋去诵读。真如本源全然无所执取，虚妄的迹象才是世人所追逐的。佛的遗言希望能默默契合，可修治本性又怎能纯熟。道人庭院寂静，苔色连着深深的竹林。太阳出来，雾露还在，青松像刚洗沐过一样。心境淡然，言语道断，悟道之乐使内心自然满足。"],
    [104, "tangshi-ts-33", "public-domain", "久为簪组累幸此南夷谪闲依农圃邻偶似山林客晓耕翻露草夜榜响溪石来往不逢人长歌楚天碧", "长久被官职所牵累，幸而被贬谪到南夷这地方。闲来与农圃为邻，偶然间倒像个山林隐士。清晨耕作，翻动带露的草；夜里撑船，船桨碰响溪中的石头。往来都遇不到人，放声长歌，楚天一片碧蓝。"],
    [105, "poems-xx2-05", "school", "千山鸟飞绝万径人踪灭孤舟蓑笠翁独钓寒江雪", "千山之中鸟儿都飞尽了，条条小路上没有人迹。只有一叶孤舟上披蓑戴笠的老翁，独自在寒冷的江雪中垂钓。"],
    [106, "tangshi-ts-57", "public-domain", "渔翁夜傍西岩宿晓汲清湘燃楚竹烟销日出不见人欸乃一声山水绿回看天际下中流岩上无心云相逐", "渔翁夜里靠着西岩住宿，清晨汲取清湘的水、烧着楚地的竹。烟消日出却不见人影，只听到一声欸乃，山水一片翠绿。回头看天际，船已驶入中流，山岩上无心的白云相互追逐。"],
    [107, "tangshi-ts-154", "public-domain", "天地英雄气千秋尚凛然势分三足鼎业复五铢钱得相能开国生儿不象贤凄凉蜀故妓来舞魏宫前", "天地间的英雄气概，千秋之后仍然凛然。势力形成三足鼎立，要恢复汉室的五铢钱。得到贤相能够开国，生了儿子却不像父亲那样贤明。凄凉的蜀国旧日歌妓，被送来在魏宫前歌舞。"],
    [108, "tangshi-ts-208", "public-domain", "王濬楼船下益州金陵王气黯然收千寻铁锁沉江底一片降幡出石头人世几回伤往事山形依旧枕寒流今逢四海为家日故垒萧萧芦荻秋", "王濬的战船从益州顺流而下，金陵的王气黯然收去。千寻长的铁锁沉入江底，一片投降的旗帜从石头城上举出。人世间几次为往事感伤，山的形状依旧枕着寒流。如今正逢四海一家的日子，旧日的营垒萧萧、芦荻在秋风中摇动。"],
    [112, "poems-xx5-12", "school", "慈母手中线游子身上衣临行密密缝意恐迟迟归谁言寸草心报得三春晖", "慈爱的母亲手里拿着针线，为将要远行的儿子缝制衣服。临行前密密地缝了又缝，担心孩子迟迟不能回来。谁说小草一样微薄的心意，能报答得了春天阳光般的恩情？"],
    [122, "tangshi-ts-155", "public-domain", "前年伐月支城下没全师蕃汉断消息死生长别离无人收废帐归马识残旗欲祭疑君在天涯哭此时", "前年讨伐月支，城下全军覆没。蕃汉之间消息断绝，是生是死都是长久的别离。没有人收拾废弃的营帐，归来的军马认识残破的旗帜。想祭奠你又疑心你还活着，天涯之远、此时唯有痛哭。"],
    [126, "tangshi-ts-243", "public-domain", "寥落古行宫宫花寂寞红白头宫女在闲坐说玄宗", "寥落的古老行宫，宫中的花寂寞地红着。白头宫女还在这里，闲坐谈论着玄宗。"],
    [129, "tangshi-ts-58", "public-domain", "汉皇重色思倾国御宇多年求不得杨家有女初长成养在深闺人未识天生丽质难自弃一朝选在君王侧回眸一笑百媚生六宫粉黛无颜色春寒赐浴华清池温泉水滑洗凝脂侍儿扶起娇无力始是新承恩泽时云鬓花颜金步摇芙蓉帐暖度春宵春宵苦短日高起从此君王不早朝承欢侍宴无闲暇春从春游夜专夜后宫佳丽三千人三千宠爱在一身金屋妆成娇侍夜玉楼宴罢醉和春姊妹弟兄皆列土可怜光彩生门户遂令天下父母心不重生男重生女骊宫高处入青云仙乐风飘处处闻缓歌慢舞凝丝竹尽日君王看不足渔阳鼙鼓动地来惊破霓裳羽衣曲九重城阙烟尘生千乘万骑西南行翠华摇摇行复止西出都门百余里六军不发无奈何宛转蛾眉马前死花钿委地无人收翠翘金雀玉搔头君王掩面救不得回看血泪相和流黄埃散漫风萧索云栈萦纡登剑阁峨嵋山下少人行旌旗无光日色薄蜀江水碧蜀山青圣主朝朝暮暮情行宫见月伤心色夜雨闻铃肠断声天旋日转回龙驭到此踌躇不能去马嵬坡下泥土中不见玉颜空死处君臣相顾尽沾衣东望都门信马归归来池苑皆依旧太液芙蓉未央柳芙蓉如面柳如眉对此如何不泪垂春风桃李花开日秋雨梧桐叶落时西宫南内多秋草落叶满阶红不扫梨园弟子白发新椒房阿监青娥老夕殿萤飞思悄然孤灯挑尽未成眠迟迟钟鼓初长夜耿耿星河欲曙天鸳鸯瓦冷霜华重翡翠衾寒谁与共悠悠生死别经年魂魄不曾来入梦临邛道士鸿都客能以精诚致魂魄为感君王辗转思遂教方士殷勤觅排空驭气奔如电升天入地求之遍上穷碧落下黄泉两处茫茫皆不见忽闻海上有仙山山在虚无缥缈间楼阁玲珑五云起其中绰约多仙子中有一人字太真雪肤花貌参差是金阙西厢叩玉扃转教小玉报双成闻道汉家天子使九华帐里梦魂惊揽衣推枕起徘徊珠箔银屏迤逦开云鬓半偏新睡觉花冠不整下堂来风吹仙袂飘飖举犹似霓裳羽衣舞玉容寂寞泪阑干梨花一枝春带雨含情凝睇谢君王一别音容两渺茫昭阳殿里恩爱绝蓬莱宫中日月长回头下望人寰处不见长安见尘雾惟将旧物表深情钿合金钗寄将去钗留一股合一扇钗擘黄金合分钿但教心似金钿坚天上人间会相见临别殷勤重寄词词中有誓两心知七月七日长生殿夜半无人私语时在天愿作比翼鸟在地愿为连理枝天长地久有时尽此恨绵绵无绝期", "汉皇贪恋美色、想得到倾国倾城的佳人，统治天下多年却求之不得。杨家有个女儿刚刚长大成人，养在深闺中无人知晓。天生的美丽资质难以自弃，一朝被选到君王身边。回头一笑就生出百般妩媚，六宫的妃嫔都黯然失色。春寒时赐她在华清池沐浴，温泉水滑，洗涤着她的肌肤。侍女扶起她时娇弱无力，这正是刚承恩泽的时候。鬓发如云、容颜如花、戴着金步摇，芙蓉帐里暖意融融地度过春宵。春宵苦于太短，日头高高升起，从此君王不再提早上朝。承受欢宠、侍奉宴饮没有空闲，春天随着出游，夜里独享君恩。后宫里美貌的佳丽有三千人，三千宠爱都集中在她一人身上。金屋里梳妆完毕娇娇地侍夜，玉楼宴会散后醉意与春意融合。她的姐妹兄弟都封土赐爵，门户上生出无限光彩。于是使天下做父母的心，不看重生男而看重生女。骊山行宫高高直入青云，仙乐随风飘荡处处可闻。缓歌慢舞与丝竹凝合，君王整日看也看不够。渔阳的鼙鼓震地而来，惊破了《霓裳羽衣曲》。九重城阙升起烟尘，千乘万骑向西南而行。翠羽华盖飘飘摇摇走着又停下，西出都门一百多里。六军不肯进发无可奈何，宛转娥眉死在马前。花钿丢在地上无人收拾，还有翠翘、金雀、玉搔头。君王掩面却救不了她，回头望去血泪交相流淌。黄尘散漫、风声萧索，沿着萦回的栈道登上剑阁。峨嵋山下行人稀少，旌旗没有光彩、日色淡薄。蜀江水碧绿、蜀山青翠，圣主朝朝暮暮满怀思念。在行宫里见月是伤心的颜色，夜雨里听铃是断肠的声音。天旋地转，圣驾回京，到此处踌躇着不忍离去。马嵬坡下的泥土中，不见玉颜，只留着她死去的地方。君臣相顾，泪湿衣襟，向东望着都门，信马而回。回京后池苑都依旧，太液池的芙蓉、未央宫的柳树。芙蓉像她的面容、柳叶像她的眉，面对这些怎么能不落泪。春风里桃李花开的日子，秋雨中梧桐叶落的时候。西宫南内长满秋草，落叶满阶、红色无人打扫。梨园弟子新添了白发，椒房的阿监、宫女都已衰老。傍晚殿中流萤飞过，思念悄然，孤灯挑尽也睡不着。钟鼓迟迟，夜刚开始变长，星河明亮将要天亮。鸳鸯瓦冷、霜花厚重，翡翠被寒，有谁与我共眠。悠悠生死一别已经一年，魂魄不曾进入我的梦中。临邛的道士是鸿都的客人，能以精诚招来魂魄。因为感念君王辗转思念，便叫方士殷勤地寻找。排开长空、驾着云气，奔走如电，升天入地寻遍。上穷碧落下至黄泉，两处茫茫都不见踪影。忽然听说海上有座仙山，山在虚无缥缈之间。楼阁玲珑，五色祥云升起，其中有许多绰约的仙子。其中有一位名叫太真，雪白肌肤、如花容貌，大约就是她。在仙宫金阙西厢轻叩玉门，转叫小玉去通报双成。听说汉家天子的使者到来，九华帐里梦魂惊动。她揽衣推枕起身徘徊，珠帘银屏一道道打开。云鬓半偏、刚睡醒的样子，花冠不整地走下堂来。清风吹动仙袖飘飘高扬，还像当年《霓裳羽衣舞》的样子。玉容寂寞、泪痕纵横，像一枝梨花带着春雨。她含情凝视、拜谢君王，一别之后音容两处渺茫。昭阳殿里的恩爱已经断绝，蓬莱宫中的日月却很漫长。回头向下望人间，看不见长安只见尘雾。只能拿旧物来表明深情，把钿盒金钗寄送回去。钗留一股、盒留一扇，把金钗掰开、把钿盒分半。只要心像金钿一样坚贞，天上人间总会相见。临别时殷勤地再三寄语，话中的誓言两心相知。七月七日长生殿，夜半无人私语的时候。在天愿作比翼鸟，在地愿为连理枝。天长地久也有尽时，这绵绵的遗恨却永无绝期。"],
    [133, "tangshi-ts-212", "public-domain", "时难年荒世业空弟兄羁旅各西东田园寥落干戈后骨肉流离道路中吊影分为千里雁辞根散作九秋蓬共看明月应垂泪一夜乡心五处同", "时世艰难、年成荒歉，家业荡然无存，弟兄们羁旅漂泊、各在西东。田园在干戈之后寥落荒废，骨肉亲人在道路之中流离失散。顾影自怜、像分飞千里的孤雁，辞别故根、像散作九秋的飞蓬。我们一同望着明月应当落泪，一夜的思乡之心五处相同。"],
    [134, "tangshi-ts-244", "public-domain", "绿蚁新醅酒红泥小火炉晚来天欲雪能饮一杯无", "新酿的酒上浮着绿色的泡沫，红泥做的小火炉。傍晚天要下雪了，能来喝一杯吗。"],
    [135, "tangshi-ts-273", "public-domain", "泪湿罗巾梦不成夜深前殿按歌声红颜未老恩先断斜倚薰笼坐到明", "泪水沾湿罗巾、睡不成梦，夜深时前殿传来按拍而歌的声音。红颜还未衰老、恩宠先已断绝，斜倚着薰笼一直坐到天明。"],
    [138, "tangshi-ts-274", "public-domain", "禁门宫树月痕过媚眼惟看宿鹭窠斜拔玉钗灯影畔剔开红焰救飞蛾", "月光越过宫门与宫树，妩媚的眼睛只看着夜宿的白鹭窠。在灯影旁斜拔下发间的玉钗，剔开红焰去救那飞扑的飞蛾。"],
    [141, "tangshi-ts-277", "public-domain", "金陵津渡小山楼一宿行人自可愁潮落夜江斜月里两三星火是瓜州", "金陵渡口的小山楼，住上一宿的行人自然会发愁。潮水退落、夜江斜月在望，两三点星火的地方就是瓜州。"],
    [142, "tangshi-ts-269", "public-domain", "玉楼天半起笙歌风送宫嫔笑语和月殿影开闻夜漏水精帘卷近秋河", "玉楼高耸半入天空、响起笙歌，风送来宫嫔们和谐的笑语。月殿的影子散开、听见夜漏的声音，卷起水晶帘、仿佛靠近了秋夜的银河。"],
    [143, "tangshi-ts-373", "public-domain", "洞房昨夜停红烛待晓堂前拜舅姑妆罢低声问夫婿画眉深浅入时无", "洞房里昨夜点着红烛，等到天明就要到堂前拜见公婆。梳妆完毕低声询问夫婿，画眉的深浅合不合时宜。"],
    [147, "tangshi-ts-281", "public-domain", "折戟沉沙铁未销自将磨洗认前朝东风不与周郎便铜雀春深锁二乔", "折断的兵器沉在沙里、铁还没有销蚀，我把它磨洗一番、认出是前朝的遗物。如果东风不给周郎方便，铜雀台里恐怕已深锁着二乔了。"],
    [148, "tangshi-ts-282", "public-domain", "烟笼寒水月笼沙夜泊秦淮近酒家商女不知亡国恨隔江犹唱后庭花", "烟雾笼罩着寒水、月光笼罩着沙，夜里停泊在秦淮河上、靠近酒家。歌女不懂亡国的遗恨，隔着江还在唱《后庭花》。"],
    [149, "tangshi-ts-283", "public-domain", "青山隐隐水迢迢秋尽江南草未凋二十四桥明月夜玉人何处教吹箫", "青山隐隐、绿水迢迢，秋已尽了江南的草木还没凋零。二十四桥的明月之夜，你这位玉人在何处教人吹箫呢。"],
    [152, "tangshi-ts-284", "public-domain", "落魄江湖载酒行楚腰纤细掌中轻十年一觉扬州梦赢得青楼薄幸名", "落魄江湖、带着酒行走，楚地的腰肢纤细、舞姿轻盈能在掌上起舞。十年一觉、如同扬州的梦，只落得青楼里一个薄情的名声。"],
    [153, "tangshi-ts-285", "public-domain", "银烛秋光冷画屏轻罗小扇扑流萤天阶夜色凉如水卧看牵牛织女星", "银烛的秋光映着清冷的画屏，她拿着轻罗小扇扑打流萤。天阶上的夜色凉如水，躺着看牵牛星与织女星。"],
    [154, "tangshi-ts-286", "public-domain", "繁华事散逐香尘流水无情草自春日暮东风怨啼鸟落花犹似坠楼人", "繁华的往事随着香尘散去，流水无情、春草自绿。日暮时东风吹来、啼鸟哀怨，落花还像是那坠楼的人。"],
    [155, "tangshi-ts-157", "public-domain", "旅馆无良伴凝情自悄然寒灯思旧事断雁警愁眠远梦归侵晓家书到隔年沧江好烟月门系钓鱼船", "旅馆里没有好友相伴，凝神静思、独自悄然。寒灯下回想旧事，失群孤雁的鸣叫惊醒愁眠。远梦归乡直到破晓，家书要到隔年才到。沧江上烟月美好，门前系着钓鱼的船。"],
    [157, "tangshi-ts-158", "public-domain", "红叶晚萧萧长亭酒一瓢残云归太华疏雨过中条树色随关迥河声入海遥帝乡明日到犹自梦渔樵", "红叶在傍晚萧萧作响，长亭里饮下一瓢酒。残云归向太华山，疏雨掠过中条山。树色随着关塞延伸而变得遥远，黄河的水声遥遥流入大海。明天就要到达帝京，我却还在梦里想着渔樵生活。"],
    [158, "poems-gz11-12", "academic", "锦瑟无端五十弦一弦一柱思华年庄生晓梦迷蝴蝶望帝春心托杜鹃沧海月明珠有泪蓝田日暖玉生烟此情可待成追忆只是当时已惘然", "锦瑟啊，你为什么无缘无故地有五十根弦？每一弦每一柱都让我想起美好的年华。庄周在清晨的梦中迷上了蝴蝶，望帝把春心寄托在杜鹃的悲啼上。大海里明月高悬，鲛人的珍珠带着泪光；蓝田的日光温暖，美玉升起轻烟。这些情感哪里是等到日后追忆时才有的呢？只是当时就已经令人惘然若失了。"],
    [159, "tangshi-ts-160", "public-domain", "本以高难饱徒劳恨费声五更疏欲断一树碧无情薄宦梗犹泛故园芜已平烦君最相警我亦举家清", "你本来因为在高处而难以饱腹，徒劳地怨恨、白白费声。五更时叫声稀疏将要断绝，满树碧绿却无情不理。我官职微薄、像桃梗一样漂泊，故乡的田园已经荒芜平没。烦劳你最能给我警醒，我也是举家清贫。"],
    [160, "tangshi-ts-412", "public-domain", "向晚意不适驱车登古原夕阳无限好只是近黄昏", "傍晚时心情不大舒畅，就赶着车登上了乐游原。落日的余晖真是无限美好，只可惜已经接近黄昏了。"],
    [161, "poems-cz7-10", "academic", "君问归期未有期巴山夜雨涨秋池何当共剪西窗烛却话巴山夜雨时", "你问我什么时候回去，我还没有确定的日期；巴山的夜雨下个不停，秋水涨满了池塘。什么时候我们才能在西窗下一起剪烛长谈，再来说说今夜巴山夜雨时我的心情。"],
    [162, "tangshi-ts-60", "public-domain", "元和天子神武姿彼何人哉轩与羲誓将上雪列圣耻坐法宫中朝四夷淮西有贼五十载封狼生貙貙生罴不据山河据平地长戈利矛日可麾帝得圣相相曰度贼斫不死神扶持腰悬相印作都统阴风惨澹天王旗愬武古通作牙爪仪曹外郎载笔随行军司马智且勇十四万众犹虎貔入蔡缚贼献太庙功无与让恩不訾帝曰汝度功第一汝从事愈宜为辞愈拜稽首蹈且舞金石刻画臣能为古者世称大手笔此事不系于职司当仁自古有不让言讫屡颔天子颐公退斋戒坐小阁濡染大笔何淋漓点窜尧典舜典字涂改清庙生民诗文成破体书在纸清晨再拜铺丹墀表曰臣愈昧死上咏神圣功书之碑碑高三丈字如斗负以灵鳌蟠以螭句奇语重喻者少谗之天子言其私长绳百尺拽碑倒粗砂大石相磨治公之斯文若元气先时已入人肝脾汤盘孔鼎有述作今无其器存其辞呜呼圣王及圣相相与烜赫流淳熙公之斯文不示后曷与三五相攀追愿书万本诵万过口角流沫右手胝传之七十有二代以为封禅玉检明堂基", "元和天子有神武的英姿，他是什么样的人啊，如同轩辕与伏羲。发誓要洗雪列祖列宗的耻辱，坐在正殿上接受四夷朝拜。淮西有叛贼割据五十年，像封狼生貙、貙生罴一样世代相承。不凭山河之险，只占据平地，长戈利矛日日可以挥动。皇帝得到贤相名唤裴度，被叛贼砍伤却没有死，是神明在扶持。他腰间悬着相印做都统，阴风惨淡、天王的旗帜飘扬。李愬、韩公武、李道古、李文通做牙爪之将，仪曹外郎载笔随行。行军司马智勇双全，十四万大军如同虎貔。攻入蔡州缚住叛贼献于太庙，功劳无人能与相比，恩赏不可估量。皇帝说你裴度功劳第一，你的从事韩愈应当写一篇碑文。韩愈叩首拜谢、手舞足蹈，说金石刻画的文字臣能胜任。古来世上称为大手笔的，此事并不取决于职位。自古以来当仁不让，说完他屡次点头应承。韩公退朝后斋戒、坐在小阁中，饱蘸大笔、何等淋漓。点窜《尧典》《舜典》的文字，涂改《清庙》《生民》的诗篇。文章写成、以破体书写在纸上，清晨再拜铺在丹墀之上。表文说臣韩愈冒死进上，咏颂神圣之功、书写成碑。碑高三丈、字大如斗，由灵龟背负、螭龙盘绕。语句奇崛、言辞厚重，能理解的人很少，有人在天子面前进谗言说他有私心。用百尺长绳把碑拉倒，用粗砂大石来磨平。韩公这篇文字如同元气，先前已经深入人的肝脾。汤盘孔鼎都有述作，如今器物不存而文辞还在。唉，圣王与圣相，相互辉耀、流布淳厚的德化。韩公这篇文字若不传示后世，如何能与三皇五帝相追随呢。我愿书写万本、诵读万遍，诵得口角流沫、右手生茧。流传七十又二代，作为封禅的玉检、明堂的基石。"],
    [163, "tangshi-ts-161", "public-domain", "凄凉宝剑篇羁泊欲穷年黄叶仍风雨青楼自管弦新知遭薄俗旧好隔良缘心断新丰酒销愁斗几千", "凄凉地吟诵《宝剑篇》，漂泊羁旅将近一年。黄叶还在风雨中飘零，青楼里却自管弦歌舞。新交的朋友遭到浅薄世俗的非议，旧日的知交也隔断了良缘。心灰意冷不再指望新丰的酒，用来消愁一斗又要几千钱。"],
    [164, "tangshi-ts-296", "public-domain", "嵩云秦树久离居双鲤迢迢一纸书休问梁园旧宾客茂陵秋雨病相如", "嵩山的云、秦地的树、我们久已分离两地，你从遥远的地方寄来一封书信。不要问梁园旧日的宾客怎样了，就像茂陵秋雨中卧病的司马相如。"],
    [166, "tangshi-ts-218", "public-domain", "猿鸟犹疑畏简书风云常为护储胥徒令上将挥神笔终见降王走传车管乐有才真不忝关张无命欲何如他年锦里经祠庙梁父吟成恨有余", "猿猴鸟雀仿佛还畏惧军中的文书，风云常常为诸葛亮护卫营垒。徒然让上将挥动神笔筹画，终究还是看见投降的蜀主乘着传车而去。诸葛亮有管仲乐毅之才、真无愧色，关羽张飞命短、又能怎样。从前在锦里经过武侯祠庙，吟成《梁父吟》、遗恨无穷。"],
    [170, "tangshi-ts-162", "public-domain", "高阁客竟去小园花乱飞参差连曲陌迢递送斜晖肠断未忍扫眼穿仍欲归芳心向春尽所得是沾衣", "高阁上的客人终于离去，小园里的花纷纷乱飞。参差不齐地连着曲折的路径，远远地送走斜阳。令人断肠、不忍心打扫，望眼欲穿、仍盼着它归来。芳心随着春天一同消尽，所得的只是泪湿衣裳。"],
    [171, "tangshi-ts-297", "public-domain", "为有云屏无限娇凤城寒尽怕春宵无端嫁得金龟婿辜负香衾事早朝", "因为有着云母屏风后的无限娇美，京城里寒冬已尽、却怕这春宵。无缘无故嫁了个佩金龟的夫婿，辜负了温暖的被褥、去上早朝。"],
    [172, "tangshi-ts-214", "public-domain", "昨夜星辰昨夜风画楼西畔桂堂东身无彩凤双飞翼心有灵犀一点通隔座送钩春酒暖分曹射覆蜡灯红嗟余听鼓应官去走马兰台类转蓬", "昨夜的星辰、昨夜的风，画楼的西畔、桂堂的东边。我身上没有彩凤那样双飞的翅膀，心里却像灵犀一点相通。隔着座位玩送钩、春酒正暖，分组玩射覆、蜡灯正红。可叹我听到更鼓就要去应差，骑马去兰台、像飘转的飞蓬。"],
    [173, "tangshi-ts-299", "public-domain", "瑶池阿母绮窗开黄竹歌声动地哀八骏日行三万里穆王何事不重来", "瑶池的西王母打开绮窗，黄竹的歌声动地哀伤。八匹骏马一天能走三万里，周穆王为了什么事不再重来。"],
    [174, "tangshi-ts-219", "public-domain", "怅卧新春白袷衣白门寥落意多违红楼隔雨相望冷珠箔飘灯独自归远路应悲春晼晚残宵犹得梦依稀玉珰缄札何由达万里云罗一雁飞", "新春里惆怅地卧着、穿着白色夹衣，白门寥落、心意多有不合。隔着雨望那红楼、只觉清冷，珠帘飘着灯光、我独自归去。远路之上应为春暮而悲伤，残夜之中还能依稀入梦。玉珰与书信怎样才能送到，万里云天如罗、一只大雁飞过。"],
    [177, "tangshi-ts-301", "public-domain", "宣室求贤访逐臣贾生才调更无伦可怜夜半虚前席不问苍生问鬼神", "汉文帝在宣室寻求贤才、征访被贬的臣子，贾生的才气更是无与伦比。可惜夜半白白地移席向前，不问百姓生计、只问鬼神之事。"],
    [178, "tangshi-ts-163", "public-domain", "客去波平槛蝉休露满枝永怀当此节倚立自移时北斗兼春远南陵寓使迟天涯占梦数疑误有新知", "客人离去时水波平齐着栏杆，蝉声停息、露水满枝。长久的思念正当这个时节，倚立在那里不知不觉过了许久。北斗星连同春天一样遥远，南陵的使者来得很迟。天涯之远屡屡占梦，疑心你误听而有了新交。"],
    [179, "tangshi-ts-164", "public-domain", "残阳西入崦茅屋访孤僧落叶人何在寒云路几层独敲初夜磬闲倚一枝藤世界微尘里吾宁爱与憎", "残阳向西落入崦嵫山，我到茅屋去拜访独居的僧人。落叶纷纷、人在何处，寒云弥漫、山路有几层。他独自敲着初夜的磬，闲来倚着一枝藤杖。大千世界不过微尘一粒，我何必还要执著于爱与憎。"],
    [180, "tangshi-ts-281", "public-domain", "折戟沉沙铁未销自将磨洗认前朝东风不与周郎便铜雀春深锁二乔", "折断的兵器沉在沙里、铁还没有销蚀，我把它磨洗一番、认出是前朝的遗物。如果东风不给周郎方便，铜雀台里恐怕已深锁着二乔了。"],
    [181, "tangshi-ts-96", "public-domain", "海上生明月天涯共此时情人怨遥夜竟夕起相思灭烛怜光满披衣觉露滋不堪盈手赠还寝梦佳期", "海上生起一轮明月，天各一方的人此时共同遥望。多情的人怨恨这漫长的夜，整个晚上都生出相思。熄了蜡烛怜惜那满屋清光，披上衣裳感到露水沾湿。不能把月光捧满手赠给你，只好回去就寝、在梦中相会。"],
    [183, "tangshi-ts-101", "public-domain", "阳月南飞雁传闻至此回我行殊未已何日复归来江静潮初落林昏瘴不开明朝望乡处应见陇头梅", "十月里南飞的大雁，传闻到这里就折回。我的行程却远未停止，何日才能回去。江面平静、潮水刚退，林中昏暗、瘴气不开。明天早上遥望故乡的地方，应当能看见岭头的梅花。"],
    [184, "tangshi-ts-445", "public-domain", "岭外音书断经冬复历春近乡情更怯不敢问来人", "贬谪在五岭之外，与家中音信断绝，经过了一个冬天又一个春天。越走近家乡，心里越是胆怯，竟不敢向迎面来的人打听家里的消息。"],
    [185, "tangshi-ts-141", "public-domain", "乡心新岁切天畔独潸然老至居人下春归在客先岭猿同旦暮江柳共风烟已似长沙傅从今又几年", "思乡之心在新年更加迫切，天涯边上独自泪流。年老却位居人下，春天归去比我这客子还早。与岭上的猿猴同度早晚，与江边的柳树共受风烟。我已经像被贬长沙的贾谊，从今往后又要几年。"],
    [187, "tangshi-ts-99", "public-domain", "独有宦游人偏惊物候新云霞出海曙梅柳渡江春淑气催黄鸟晴光转绿苹忽闻歌古调归思欲沾巾", "只有宦游在外的人，才特别惊觉物候的变化。云霞从海上透出曙光，梅柳渡过江来带来春意。和暖的气息催促黄鸟鸣叫，晴朗的阳光使绿苹转动。忽然听到你唱起古雅的曲调，归乡的思绪使我泪湿手巾。"],
    [188, "tangshi-ts-269", "public-domain", "玉楼天半起笙歌风送宫嫔笑语和月殿影开闻夜漏水精帘卷近秋河", "玉楼高耸半入天空、响起笙歌，风送来宫嫔们和谐的笑语。月殿的影子散开、听见夜漏的声音，卷起水晶帘、仿佛靠近了秋夜的银河。"],
    [190, "tangshi-ts-166", "public-domain", "灞原风雨定晚见雁行频落叶他乡树寒灯独夜人空园白露滴孤壁野僧邻寄卧郊扉久何年致此身", "灞原上风雨初定，傍晚频频望见雁行。落叶是他乡的树，寒灯下是独夜的人。空园里白露滴落，孤壁边与野僧为邻。寄居在郊外的门扉已久，何年才能有所作为。"],
    [191, "tangshi-ts-290", "public-domain", "玄宗回马杨妃死云雨难忘日月新终是圣明天子事景阳宫井又何人", "玄宗回马时杨妃已死，云雨之情难忘、而日月已新。终究还是圣明天子的行事，那景阳宫井中的陈后主又算什么人呢。"],
    [192, "poems-xx1-10", "school", "松下问童子言师采药去只在此山中云深不知处", "在松树下问小童师父去哪儿了，他说师父采药去了。就在这座山里，云雾深深不知在何处。"],
    [193, "tangshi-ts-220", "public-domain", "澹然空水对斜晖曲岛苍茫接翠微波上马嘶看棹去柳边人歇待船归数丛沙草群鸥散万顷江田一鹭飞谁解乘舟寻范蠡五湖烟水独忘机", "空阔的水面淡然对着斜阳，曲折的岛屿苍茫接着青翠的山色。波浪上马在嘶鸣、看船桨划去，柳边有人歇息、等待船回来。几丛沙草、群鸥惊散，万顷江田、一只白鹭飞翔。谁能懂得乘舟去寻访范蠡，在五湖的烟水中独自忘掉机心。"],
    [194, "tangshi-ts-289", "public-domain", "冰簟银床梦不成碧天如水夜云轻雁声远过潇湘去十二楼中月自明", "冰凉的竹席、银色的床、梦也做不成，碧天如水、夜云轻淡。雁声远远地越过潇湘而去，十二楼中明月自照。"],
    [195, "tangshi-ts-165", "public-domain", "荒戍落黄叶浩然离故关高风汉阳渡初日郢门山江上几人在天涯孤棹还何当重相见樽酒慰离颜", "荒凉的戍楼落下黄叶，你意气浩然地离开故关。高风吹过汉阳渡，初日照着郢门山。江上还有几个人，天涯外一只孤舟归去。什么时候才能重见，举杯慰藉这离别的容颜。"],
    [196, "tangshi-ts-221", "public-domain", "苏武魂销汉使前古祠高树两茫然云边雁断胡天月陇上羊归塞草烟回日楼台非甲帐去时冠剑是丁年茂陵不见封侯印空向秋波哭逝川", "苏武在汉使面前神魂震撼，古祠与高树都一片茫然。云边的雁影断绝在胡天的月下，陇上的羊群归来在塞草的烟雾中。回来时楼台已经不是当年的甲帐，离去时加冠佩剑正当壮年。汉武帝已看不到他封侯的印绶，只能空对着秋水哀哭逝去的岁月。"],
    [197, "tangshi-ts-248", "public-domain", "岭外音书绝经冬复立春近乡情更怯不敢问来人", "岭外与家乡的音信断绝，过了冬天又到立春。越靠近家乡、心情越是怯怯，不敢询问从家乡来的人。"],
    [198, "tangshi-ts-168", "public-domain", "调角断清秋征人倚戍楼春风对青冢白日落梁州大漠无兵阻穷边有客游蕃情似此水长愿向南流", "号角声断断续续地响在清秋，征人倚在戍楼上。春风对着青冢，白日落在梁州。大漠上没有兵阻，极远的边地还有客子游历。蕃人的心意就像这河水，但愿长久地向南流。"],
    [199, "tangshi-ts-354", "public-domain", "蓬门未识绮罗香拟托良媒益自伤谁爱风流高格调共怜时世俭梳妆敢将十指夸针巧不把双眉斗画长苦恨年年压金线为他人作嫁衣裳", "生在蓬门小户，从没见识过绮罗的芳香，想托个好媒人，反而更添感伤。\n有谁赏识风流高雅的格调？人们都喜爱时兴的俭朴梳妆。\n我敢用十指夸耀针线精巧，却不愿描长双眉与人争妍。\n最恨年年压线刺绣，都是替别人做嫁衣。"],
    [200, "tangshi-ts-171", "public-domain", "早被婵娟误欲妆临镜慵承恩不在貌教妾若为容风暖鸟声碎日高花影重年年越溪女相忆采芙蓉", "早年就被美貌所误，想梳妆却对着镜子懒懒的。承受恩宠并不在于容貌，叫我如何打扮才好。风暖、鸟声细碎，日高、花影重叠。年年想起越溪的女子，一同采摘芙蓉的情景。"],
    [203, "tangshi-ts-291", "public-domain", "碧阑干外绣帘垂猩色屏风画折枝八尺龙须方锦褥已凉天气未寒时", "碧色的栏杆外绣帘低垂，猩红色的屏风上画着折枝花。八尺的龙须草席与方形的锦褥，正是天气已凉而未寒的时候。"],
    [204, "tangshi-ts-171", "public-domain", "早被婵娟误欲妆临镜慵承恩不在貌教妾若为容风暖鸟声碎日高花影重年年越溪女相忆采芙蓉", "早年就被美貌所误，想梳妆却对着镜子懒懒的。承受恩宠并不在于容貌，叫我如何打扮才好。风暖、鸟声细碎，日高、花影重叠。年年想起越溪的女子，一同采摘芙蓉的情景。"],
    [205, "tangshi-ts-172", "public-domain", "清瑟怨遥夜绕弦风雨哀孤灯闻楚角残月下章台芳草已云暮故人殊未来乡书不可寄秋雁又南回", "清瑟哀怨地响在长夜，绕着琴弦是风雨般的悲声。孤灯下听到楚地的号角，残月沉下章台。芳草已经衰暮，老朋友却始终不来。家书无法寄出，秋雁又向南飞回。"],
    [206, "tangshi-ts-359", "public-domain", "谁谓伤心画不成画人心逐世人情君看六幅南朝事老木寒云满故城", "谁说伤心的景致画不成？只是画家的心追逐着世俗的人情。\n你看这六幅描绘南朝旧事的画，老树寒云布满整座故城。"],
    [207, "tangshi-ts-292", "public-domain", "江雨霏霏江草齐六朝如梦鸟空啼无情最是台城柳依旧烟笼十里堤", "江上细雨霏霏、江草齐整，六朝的往事如梦、鸟儿空自啼叫。最无情的要数台城的柳树，依旧烟雾笼罩着十里长堤。"],
    [210, "poems-cz7-18", "academic", "前不见古人后不见来者念天地之悠悠独怆然而涕下", "往前看不到古代的贤君，往后也看不到后世的明主。想到天地是这样辽阔久远，我独自悲伤，泪流满面！"],
    [213, "tangshi-ts-250", "public-domain", "北斗七星高哥舒夜带刀至今窥牧马不敢过临洮", "北斗七星高悬，哥舒翰夜里佩刀巡边。至今胡人窥探着牧马，不敢越过临洮。"],
    [222, "poems-cz7-03", "school", "客路青山外行舟绿水前潮平两岸阔风正一帆悬海日生残夜江春入旧年乡书何处达归雁洛阳边", "旅人要走的路在青山之外，船行在绿水中。潮水涨满，两岸顿时开阔；顺风行驶，船帆高高悬起。红日在残夜中升起，江南的春天在旧年未尽时到来。写给家里的信什么时候才能送到？希望北归的大雁把它带到洛阳。"],
    [225, "tangshi-ts-11", "public-domain", "圣代无隐者英灵尽来归遂令东山客不得顾采薇既至金门远孰云吾道非江淮度寒食京洛缝春衣置酒长安道同心与我违行当浮桂棹未几拂荆扉远树带行客孤城当落晖吾谋适不用勿谓知音稀", "清明盛世没有隐逸的人，俊杰之士都来归附朝廷。这便使你这隐居东山的高士，也无暇再去采薇隐居了。既然来到京城却未能入选，谁能说你我的主张不对呢。你将在江淮一带度过寒食，在京城洛阳缝制春衣。我在长安道上设酒送别，志同道合的你却要与我分离。你即将乘船远行，不久就要叩响家乡的柴门。远处的树木映带着行客，孤零零的城郭对着落日余晖。我的主张只是暂时不被采用，不要说知音稀少。"],
    [227, "tangshi-ts-14", "public-domain", "斜阳照墟落穷巷牛羊归野老念牧童倚杖候荆扉雉雊麦苗秀蚕眠桑叶稀田夫荷锄立相见语依依即此羡闲逸怅然吟式微", "斜阳照着村庄，深巷里牛羊回来了。老人惦记着放牧的孩子，拄着拐杖在柴门前等候。野鸡鸣叫，麦苗正在抽穗；蚕儿休眠，桑叶已经稀疏。农夫扛着锄头站立，彼此相见话语依依。看到这些，我羡慕这种闲适安逸，惆怅地吟起《式微》来。"],
    [228, "tangshi-ts-15", "public-domain", "艳色天下重西施宁久微朝为越溪女暮作吴宫妃贱日岂殊众贵来方悟稀邀人傅香粉不自著罗衣君宠益娇态君怜无是非当时浣纱伴莫得同车归持谢邻家子效颜安可希", "美色为天下人所看重，西施怎能长久微贱呢。早晨她还是越溪边浣纱的女子，傍晚就成了吴王宫中的宠妃。贫贱时她与众人有什么不同，显贵之后才让人感到她的稀罕。她要别人给她搽香粉，自己连罗衣都不动手穿。君王的宠爱使她更加娇态百出，君王的怜爱让她没有是非的顾虑。当年一起浣纱的伙伴，没有一个能与她同车而归。我借这话奉告邻家的姑娘，想要效仿她的美貌又怎能指望得上呢。"],
    [229, "tangshi-ts-69", "public-domain", "少年十五二十时步行夺得胡马骑射杀山中白额虎肯数邺下黄须儿一身转战三千里一剑曾当百万师汉兵奋迅如霹雳虏骑崩腾畏蒺藜卫青不败由天幸李广无功缘数奇自从弃置便衰朽世事蹉跎成白首昔时飞箭无全目今日垂杨生左肘路旁时卖故侯瓜门前学种先生柳苍茫古木连穷巷寥落寒山对虚牖誓令疏勒出飞泉不似颍川空使酒贺兰山下阵如云羽檄交驰日夕闻节使三河募年少诏书五道出将军试拂铁衣如雪色聊持宝剑动星文愿得燕弓射大将耻令越甲鸣吾君莫嫌旧日云中守犹堪一战取功勋", "少年十五二十岁的时候，步行夺过胡人的马骑。射杀山中的白额猛虎，哪肯把邺下的黄须儿曹操放在眼里。一身转战三千里，一把剑曾抵挡百万大军。汉兵奋迅如霹雳，敌骑崩溃奔逃、畏惧蒺藜。卫青不败是因为天幸，李广无功是因为命运不好。自从被弃置不用便衰朽了，世事蹉跎，已成白头。从前神箭能射中飞鸟的眼，如今左肘上长了瘤如垂柳。在路旁时时卖着故侯的瓜，在门前学陶渊明种着柳树。苍茫的古木连着深巷，寥落的寒山对着空窗。发誓要如耿恭让疏勒涌出飞泉，不像颍川的灌夫那样空自使酒骂座。贺兰山下军阵如云，插羽毛的紧急军书日夜交驰。节度使在三河招募少年，诏书分五道出兵、将军出征。我试着拂拭铁甲如雪的颜色，姑且持起宝剑、剑上星文晃动。愿得到燕地的良弓去射敌将，以让越国的甲兵惊扰我的君王为耻。不要嫌弃旧日的云中太守，他还能一战去夺取功勋。"],
    [230, "tangshi-ts-70", "public-domain", "渔舟逐水爱山春两岸桃花夹古津坐看红树不知远行尽青溪不见人山口潜行始隈隩山开旷望旋平陆遥看一处攒云树近入千家散花竹樵客初传汉姓名居人未改秦衣服居人共住武陵源还从物外起田园月明松下房栊静日出云中鸡犬喧惊闻俗客争来集竞引还家问都邑平明闾巷扫花开薄暮渔樵乘水入初因避地去人间及至成仙遂不还峡里谁知有人事世中遥望空云山不疑灵境难闻见尘心未尽思乡县出洞无论隔山水辞家终拟长游衍自谓经过旧不迷安知峰壑今来变当时只记入山深青溪几曲到云林春来遍是桃花水不辨仙源何处寻", "渔船顺着溪水前行，喜爱山中的春色，两岸桃花夹着古老的渡口。坐着看红树不知走了多远，行遍青溪也不见人影。从山口悄悄前行进入曲折的深处，山势开阔、豁然望见一片平地。远远看见一处云树攒聚，走近了是千家散落着花竹。打柴的人初次听说汉朝的姓名，居民还没有改变秦代的衣装。居民们共同住在武陵源，从世外建起了田园。月明时松下房舍静寂，日出云中鸡犬喧闹。惊闻有世俗的客人，争先聚集，争相引他还家询问故乡。天明时里巷扫净、打开门，傍晚渔人樵夫乘船进来。当初为躲避乱世离开人间，等到成了仙便不再回去。峡谷里谁知道有人间的事，世人遥遥望去只见空蒙的云山。他不疑这样的灵境难以遇见，只是尘心未尽、思念家乡。出洞后不论隔着山水，辞别家人终究打算长久地游历。自以为经过的地方不会迷路，哪里知道山峰沟壑如今已经改变。当时只记得进入山中很深，青溪几曲就通到云林。春天来时遍地是桃花水，分不清仙源在哪里去寻找。"],
    [231, "tangshi-ts-71", "public-domain", "洛阳女儿对门居才可颜容十五余良人玉勒乘骢马侍女金盘脍鲤鱼画阁朱楼尽相望红桃绿柳垂檐向罗帏送上七香车宝扇迎归九华帐狂夫富贵在青春意气骄奢剧季伦自怜碧玉亲教舞不惜珊瑚持与人春窗曙灭九微火九微片片飞花琐戏罢曾无理曲时妆成只是薰香坐城中相识尽繁华日夜经过赵李家谁怜越女颜如玉贫贱江头自浣纱", "洛阳的女儿住在对门，容貌才十五有余。丈夫戴着玉勒、骑着骢马，侍女用金盘盛着细切的鲤鱼。画阁朱楼处处相望，红桃绿柳垂向屋檐。用罗帏送上七香车，用宝扇迎回九华帐。丈夫富贵正当青春，意气骄奢超过石崇。自怜妻子美好而亲自教她舞蹈，不惜把珊瑚拿去送人。春窗破晓时熄了九微灯，灯花片片飞落。嬉戏过后不曾整理乐曲，梳妆好了只是熏香端坐。城中相识的都是繁华人家，日夜来往于赵李之家。谁怜惜那越地的女子容颜如玉，却贫贱地在江头独自浣纱。"],
    [232, "tangshi-ts-120", "public-domain", "寒山转苍翠秋水日潺湲倚杖柴门外临风听暮蝉渡头余落日墟里上孤烟复值接舆醉狂歌五柳前", "寒山转成苍翠，秋水日日潺潺流淌。我拄着拐杖站在柴门之外，迎着风听傍晚的蝉鸣。渡头还留着落日，村落里升起一缕孤烟。又遇上像接舆一样醉酒的裴迪，在五柳前放声狂歌。"],
    [233, "tangshi-ts-124", "public-domain", "晚年惟好静万事不关心自顾无长策空知返旧林松风吹解带山月照弹琴君问穷通理渔歌入浦深", "晚年只喜欢清静，万事都不关心。自思没有好的计策，只知道回归旧日的山林。松风吹来解开衣带，山月照着弹琴。你问穷困与通达的道理，渔歌正传入那深深的浦口。"],
    [235, "tangshi-ts-294", "public-domain", "近寒食雨草萋萋著麦苗风柳映堤等是有家归未得杜鹃休向耳边啼", "临近寒食、细雨绵绵、春草萋萋，风吹麦苗、柳树映着长堤。同样是有家却回不去，杜鹃啊不要在我耳边啼叫。"],
    [236, "tangshi-ts-169", "public-domain", "迢递三巴路羁危万里身乱山残雪夜孤烛异乡人渐与骨肉远转于僮仆亲那堪正飘泊明日岁华新", "三巴的道路多么遥远，羁旅艰危、身在万里之外。乱山残雪的除夕之夜，一支孤烛伴着异乡人。渐渐与骨肉亲人远离，转而与僮仆亲近。哪里受得了正漂泊无依，明天又是新的一年。"],
    [237, "tangshi-ts-125", "public-domain", "不知香积寺数里入云峰古木无人径深山何处钟泉声咽危石日色冷青松薄暮空潭曲安禅制毒龙", "不知香积寺在何处，走了几里进入云雾缭绕的山峰。古木森森没有人的路径，深山里不知从哪里传来钟声。泉声在危石间呜咽，日色在青松间显得清冷。傍晚在空潭的弯曲处，坐禅入定、制伏心中的毒龙。"],
    [238, "poems-xx5-06", "school", "空山新雨后天气晚来秋明月松间照清泉石上流竹喧归浣女莲动下渔舟随意春芳歇王孙自可留", "空旷的山中刚下过一场新雨，傍晚的天气带来了秋意。明月从松林间照下来，清泉在山石上流淌。竹林里传来洗衣女子的笑语，莲叶摇动是渔船顺流而下。任凭春天的花草凋谢吧，我留在山中正可以长久栖居。"],
    [239, "tangshi-ts-127", "public-domain", "中岁颇好道晚家南山陲兴来每独往胜事空自知行到水穷处坐看云起时偶然值林叟谈笑无还期", "中年时颇喜好佛道，晚年安家在南山边上。兴致来时常常独自出游，美好的事情只有自己知道。走到水流的尽头，坐着看云升起的时候。偶然遇到林中的老人，谈笑之间忘了回去的时候。"],
    [240, "tangshi-ts-122", "public-domain", "清川带长薄车马去闲闲流水如有意暮禽相与还荒城临古渡落日满秋山迢递嵩高下归来且闭关", "清澈的河川环绕着长长的草木丛，车马悠然自在地离去。流水仿佛有情意，傍晚的鸟儿与我一同归还。荒凉的城池临着古老的渡口，落日的余晖洒满秋山。在高远的嵩山脚下，我归来姑且闭门隐居。"],
    [241, "tangshi-ts-123", "public-domain", "太乙近天都连山接海隅白云回望合青霭入看无分野中峰变阴晴众壑殊欲投人处宿隔水问樵夫", "终南山靠近天帝的都城，山峦连绵一直连接到海边。回头望去白云已合拢，走近看青色的雾气又不见了。中峰把星野划分开来，各个山谷或阴或晴各不相同。想找个有人烟的地方投宿，隔着溪水询问樵夫。"],
    [243, "tangshi-ts-180", "public-domain", "渭水自萦秦塞曲黄山旧绕汉宫斜銮舆迥出千门柳阁道回看上苑花云里帝城双凤阙雨中春树万人家为乘阳气行时令不是宸游玩物华", "渭水依旧萦绕着秦地的关塞弯曲而流，黄山依然斜斜地绕着汉宫。天子的车驾远远地出了千门杨柳，在阁道上回头看皇家园林的花。云里帝京耸立着双凤阙，雨中的春树掩映着万户人家。这是顺应阳气来施行时令，不是天子游乐玩赏美景。"],
    [249, "tangshi-ts-225", "public-domain", "红豆生南国春来发几枝愿君多采撷此物最相思", "红豆生长在南方，春天来时发出几枝。愿你多多采摘，这东西最能寄托相思。"],
    [250, "poems-xx3-16", "school", "独在异乡为异客每逢佳节倍思亲遥知兄弟登高处遍插茱萸少一人", "独自在他乡做客，每到佳节就更加思念亲人。遥想兄弟们登高的地方，插茱萸时唯独少了我一个。"],
    [251, "poems-xx5-23", "school", "渭城朝雨浥轻尘客舍青青柳色新劝君更尽一杯酒西出阳关无故人", "渭城清晨的细雨润湿了轻尘，客舍旁柳色青青，格外鲜亮。劝你再干一杯酒，向西出了阳关就再没有老朋友了。"],
    [253, "tangshi-ts-20", "public-domain", "绝顶一茅茨直上三十里扣关无僮仆窥室唯案几若非巾柴车应是钓秋水差池不相见黾勉空仰止草色新雨中松声晚窗里及兹契幽绝自足荡心耳虽无宾主意颇得清净理兴尽方下山何必待之子", "高高的山顶上有一间茅屋，一直往上要走三十里。敲门却没有童仆应答，窥看屋内只有几案。主人若不是驾着柴车外出，就该是在秋水里垂钓。阴差阳错没能相见，徒然辛劳地仰慕他。新雨过后草色青青，傍晚的窗外传来松涛声。置身这幽绝的境地，已足以涤荡我的心胸与耳目。虽然没有宾主酬答的情意，却也颇得清净的道理。兴致尽了便下山去，何必一定要等到见到他呢。"],
    [254, "poems-cz8-06", "academic", "昔人已乘黄鹤去此地空余黄鹤楼黄鹤一去不复返白云千载空悠悠晴川历历汉阳树芳草萋萋鹦鹉洲日暮乡关何处是烟波江上使人愁", "传说中的仙人已经乘着黄鹤飞走了，这个地方只留下空空的黄鹤楼。黄鹤一去再也没有回来，千百年来只有白云在空中飘飘荡荡。晴日里，汉阳的树木清晰可数，鹦鹉洲上芳草长得十分茂盛。天色已晚，故乡在什么地方呢？江上的烟波使人愁绪满怀。"],
    [255, "tangshi-ts-174", "public-domain", "岧峣太华俯咸京天外三峰削不成武帝祠前云欲散仙人掌上雨初晴河山北枕秦关险驿路西连汉畤平借问路旁名利客何如此处学长生", "高峻的太华山俯视着咸阳，天外的三峰像是刀削不成。武帝祠前的云将要散去，仙人掌峰上的雨刚刚转晴。山河北枕秦关之险，驿路西连着平坦的汉畤。请问路旁追逐名利的人，何不像这样在这里学长生之道。"],
    [258, "tangshi-ts-175", "public-domain", "燕台一去客心惊笳鼓喧喧汉将营万里寒光生积雪三边曙色动危旌沙场烽火侵胡月海畔云山拥蓟城少小虽非投笔吏论功还欲请长缨", "一到燕台客子便心惊，笳鼓喧闹的是汉将的军营。万里寒光从积雪中生出，三边的曙光使高悬的旌旗飘动。沙场的烽火侵扰着胡地的月亮，海边的云山簇拥着蓟城。我年少时虽不是投笔从戎的班超，论功却还想请缨杀敌。"],
    [259, "tangshi-ts-228", "public-domain", "终南阴岭秀积雪浮云端林表明霁色城中增暮寒", "终南山北面的山岭秀丽，积雪浮在云端。树林梢头露出晴后的天色，城中更添傍晚的寒意。"],
    [260, "tangshi-ts-73", "public-domain", "白日登山望烽火黄昏饮马傍交河行人刁斗风沙暗公主琵琶幽怨多野云万里无城郭雨雪纷纷连大漠胡雁哀鸣夜夜飞胡儿眼泪双双落闻道玉门犹被遮应将性命逐轻车年年战骨埋荒外空见蒲桃入汉家", "白天登山瞭望烽火，黄昏在交河边饮马。行人打着刁斗，风沙昏暗，公主的琵琶声里幽怨很多。野云万里不见城郭，雨雪纷纷连接着大漠。胡雁哀鸣夜夜飞翔，胡儿的眼泪双双落下。听说玉门关还被遮断，只能拼着性命跟随轻车将军。年年战死的尸骨埋在荒外，只看见葡萄传入了汉家。"],
    [261, "tangshi-ts-35", "public-domain", "主人有酒欢今夕请奏鸣琴广陵客月照城头乌半飞霜凄万树风入衣铜炉华烛烛增辉初弹渌水后楚妃一声已动物皆静四座无言星欲稀清淮奉使千余里敢告云山从此始", "主人备酒，今夜欢聚，请来善弹琴的广陵客为我奏一曲。月光照着城头，乌鸦半飞；霜气凄冷万树，寒风吹入衣裳。铜炉香料、华美蜡烛使烛光更亮，先弹《渌水》，后弹《楚妃》。琴声一起，万物都静了下来，满座无言，直到天将亮、星星稀疏。我奉命出使清淮，路远千里，从此要辞别云山开始了。"],
    [262, "tangshi-ts-37", "public-domain", "四月南风大麦黄枣花未落桐叶长青山朝别暮还见嘶马出门思旧乡陈侯立身何坦荡虬须虎眉仍大颡腹中贮书一万卷不肯低头在草莽东门酤酒饮我曹心轻万事如鸿毛醉卧不知白日暮有时空望孤云高长河浪头连天黑津吏停舟渡不得郑国游人未及家洛阳行子空叹息闻道故林相识多罢官昨日今如何", "四月南风吹来大麦金黄，枣花未落桐叶已长。青山早晨一别傍晚又见，马嘶着走出家门便思念故乡。陈侯为人何等坦荡，胡须卷曲、眉毛如虎、额头宽阔。腹中藏着一万卷书，却不肯低头埋没在草野之中。他在东门买酒请我们喝，心里把万事看得轻如鸿毛。醉卧时不知白日已暮，有时空自遥望孤云高飞。长河浪头连天昏黑，渡口官吏停船不能渡。郑国的游子还没到家，洛阳的行人徒然叹息。听说故乡旧识很多，你昨日罢官，如今他们会怎样待你呢。"],
    [263, "tangshi-ts-38", "public-domain", "南山截竹为觱篥此乐本自龟兹出流传汉地曲转奇凉州胡人为我吹傍邻闻者多叹息远客思乡皆泪垂世人解听不解赏长飙风中自来往枯桑老柏寒飕飗九雏鸣凤乱啾啾龙吟虎啸一时发万籁百泉相与秋忽然更作渔阳掺黄云萧条白日暗变调如闻杨柳春上林繁花照眼新岁夜高堂列明烛美酒一杯声一曲", "从南山截下竹子做成觱篥，这种乐器本出自龟兹。流传到汉地曲调变得更加奇妙，凉州的胡人为我吹奏。旁边的邻人听了都叹息，远方的旅客思念家乡都流下泪来。世人只懂得听却不懂得欣赏，乐声像长风在风中自来自往。像枯桑老柏在寒风里飕飗作响，又像九只雏凤鸣叫，细细啾啾。忽然如龙吟虎啸一齐迸发，又像万种声响与百道泉流共奏秋声。忽然又转为《渔阳掺》的曲调，黄云萧条，白日昏暗。变调时仿佛听到杨柳迎春，上林苑繁花照眼一新。除夕之夜高堂上点起明烛，美酒一杯、乐曲一支。"],
    [264, "tangshi-ts-36", "public-domain", "男儿事长征少小幽燕客赌胜马蹄下由来轻七尺杀人莫敢前须如猬毛磔黄云陇底白云飞未得报恩不能归辽东小妇年十五惯弹琵琶解歌舞今为羌笛出塞声使我三军泪如雨", "男儿当兵去远征，从小是幽燕一带的健儿。在马蹄下争夺胜负，向来把性命看得轻。杀人时勇猛没人敢上前，胡须像刺猬毛一样张开。陇山下黄云弥漫，白云飞卷，未报答国恩就不能回家。辽东有个十五岁的小妇，惯于弹琵琶、善歌舞。如今她用羌笛吹起出塞的曲调，使我们三军将士泪如雨下。"],
    [266, "tangshi-ts-177", "public-domain", "朝闻游子唱离歌昨夜微霜初渡河鸿雁不堪愁里听云山况是客中过关城树色催寒近御苑砧声向晚多莫见长安行乐处空令岁月易蹉跎", "早晨听到你唱起离别的歌，昨夜微霜刚刚渡过黄河。鸿雁的鸣声在愁中不堪听，云山更是在客旅中所经过的。关城的树色催促寒气临近，御苑的砧声到傍晚更多。不要只看见长安是行乐的地方，白白地让岁月蹉跎。"],
    [267, "tangshi-ts-21", "public-domain", "幽意无断绝此去随所偶晚风吹行舟花路入溪口际夜转西壑隔山望南斗潭烟飞溶溶林月低向后生事且弥漫愿为持竿叟", "幽居的意趣没有断绝，此番出行随遇而安。晚风吹着行船，沿着花径进入溪口。入夜后船转入西边的山谷，隔着山望见南斗星。潭上雾气溶溶飘飞，林中月影低低地向后移去。人生世事茫茫无边，我愿做个持竿垂钓的老翁。"],
    [272, "tangshi-ts-257", "public-domain", "昨夜风开露井桃未央前殿月轮高平阳歌舞新承宠帘外春寒赐锦袍", "昨夜春风吹开了露井边的桃花，未央宫前殿月轮高悬。平阳家的歌女新受恩宠，帘外春寒、赐下锦袍。"],
    [276, "tangshi-ts-256", "public-domain", "闺中少妇不知愁春日凝妆上翠楼忽见陌头杨柳色悔教夫婿觅封侯", "闺中的少妇不知道愁，春日里盛妆登上翠楼。忽然看见路边的杨柳春色，后悔当初让丈夫去求取封侯。"],
    [278, "tangshi-ts-22", "public-domain", "清溪深不测隐处唯孤云松际露微月清光犹为君茅亭宿花影药院滋苔纹余亦谢时去西山鸾鹤群", "清清的溪水深不可测，隐居之处只有一片孤云。松林间露出淡淡的月亮，清朗的月光仿佛还在为你而照。茅亭里停宿着花的影子，种药的院子里滋生了青苔的纹路。我也要辞别时俗而去，到西山与鸾鹤为群。"],
    [279, "tangshi-ts-236", "public-domain", "泠泠七弦上静听松风寒古调虽自爱今人多不弹", "冷冷清清的七弦琴上，静静地听出松风般的寒意。古调虽然我自己喜爱，如今的人却多不弹了。"],
    [282, "tangshi-ts-141", "public-domain", "乡心新岁切天畔独潸然老至居人下春归在客先岭猿同旦暮江柳共风烟已似长沙傅从今又几年", "思乡之心在新年更加迫切，天涯边上独自泪流。年老却位居人下，春天归去比我这客子还早。与岭上的猿猴同度早晚，与江边的柳树共受风烟。我已经像被贬长沙的贾谊，从今往后又要几年。"],
    [286, "tangshi-ts-139", "public-domain", "望君烟水阔挥手泪沾巾飞鸟没何处青山空向人长江一帆远落日五湖春谁见汀洲上相思愁白苹", "望着你远入烟水茫茫，挥手之间泪水沾湿手巾。飞鸟消失在哪里，青山空自对着人。长江上一片孤帆远去，落日下五湖正逢春天。谁看见我在汀洲之上，因相思而对着白苹发愁。"],
    [287, "tangshi-ts-199", "public-domain", "生涯岂料承优诏世事空知学醉歌江上月明胡雁过淮南木落楚山多寄身且喜沧洲近顾影无如白发何今日龙钟人共老愧君犹遣慎风波", "一生哪料承蒙优诏，世事也只空知学着醉歌。江上明月、胡雁飞过，淮南叶落、楚山众多。寄身此地、且喜离水边沧洲很近，自顾身影、对白发无可奈何。如今老态龙钟、大家都已衰老，惭愧你还要派我要小心风波。"],
    [288, "poems-cz9-11", "school", "三年谪宦此栖迟万古惟留楚客悲秋草独寻人去后寒林空见日斜时汉文有道恩犹薄湘水无情吊岂知寂寂江山摇落处怜君何事到天涯", "贾谊被贬长沙三年，在这里栖身，万古以来只留下楚客的悲哀。秋草之中，我独自寻找他离去后的踪迹，寒冷的树林里只看到夕阳西下。汉文帝虽然贤明，对他的恩遇尚且如此微薄；湘水无情，凭吊贾谊又怎么知道呢？寂寥冷落的江山，草木摇落的时节，可怜你为什么要来到这天涯之地！"],
    [289, "tangshi-ts-201", "public-domain", "汀洲无浪复无烟楚客相思益渺然汉口夕阳斜渡鸟洞庭秋水远连天孤城背岭寒吹角独戍临江夜泊船贾谊上书忧汉室长沙谪去古今怜", "汀洲上没有波浪也没有烟雾，楚客的相思更加渺茫。汉口的夕阳斜照渡鸟，洞庭的秋水远远连着天。孤城背靠山岭、寒风中吹起号角，独戍临江、夜里停泊着船只。贾谊上书忧虑汉室，被贬长沙、古今都为之怜惜。"],
    [293, "tangshi-ts-16", "public-domain", "北山白云里隐者自怡悦相望始登高心随雁飞灭愁因薄暮起兴是清秋发时见归村人沙行渡头歇天边树若荠江畔洲如月何当载酒来共醉重阳节", "北山的白云里，隐居的人自得其乐。为了遥望你我才登上高处，心随着大雁飞去直到看不见。忧愁因傍晚而生，兴致因清秋而发。时时看见回村的人，在沙滩上行走、在渡口歇息。天边的树木细得像荠菜，江边的沙洲弯得像月亮。什么时候你带着酒来，我们一同醉在重阳节。"],
    [294, "tangshi-ts-17", "public-domain", "山光忽西落池月渐东上散发乘夕凉开轩卧闲敞荷风送香气竹露滴清响欲取鸣琴弹恨无知音赏感此怀故人中宵劳梦想", "山上的日色忽然向西落下，池上的月亮渐渐从东边升起。我披散开头发乘着傍晚的凉意，打开窗户闲适地躺卧在敞亮的屋中。荷风送来阵阵香气，竹叶上的露水滴落发出清脆的声响。想取出琴来弹奏，可惜没有知音来欣赏。感念于此，怀念起老朋友，半夜里还在梦中苦苦思念。"],
    [295, "tangshi-ts-18", "public-domain", "夕阳度西岭群壑倏已暝松月生夜凉风泉满清听樵人归欲尽烟鸟栖初定之子期宿来孤琴候萝径", "夕阳越过西边的山岭，各条山谷忽然间已经昏暗。松间的月亮带来夜的凉意，风声泉声充满了清幽的听觉。砍柴的人差不多都回家了，暮烟中的鸟儿也刚刚安歇。你约定今晚来过夜，我抱着孤琴在藤萝小径上等候。"],
    [296, "tangshi-ts-39", "public-domain", "山寺钟鸣昼已昏渔梁渡头争渡喧人随沙岸向江村余亦乘舟归鹿门鹿门月照开烟树忽到庞公栖隐处岩扉松径长寂寥惟有幽人自来去", "山寺钟声响起，白昼已经昏暮，渔梁渡头人们争着渡河，一片喧闹。行人沿着沙岸走向江村，我也乘船回鹿门山。鹿门的月光照着烟雾散开的树林，忽然来到庞公当年隐居的地方。岩洞的门、松间的小路，长年寂寥，只有我这个幽人自来自去。"],
    [299, "tangshi-ts-134", "public-domain", "山暝听猿愁沧江急夜流风鸣两岸叶月照一孤舟建德非吾土维扬忆旧游还将两行泪遥寄海西头", "山色昏暗、听着猿啼发愁，青苍的江水夜里湍急地流。风吹响两岸的树叶，月光照着一只孤舟。建德不是我的故乡，我怀念扬州的旧友。只好把两行眼泪，远远地寄到大海的西头。"],
    [300, "tangshi-ts-136", "public-domain", "木落雁南度北风江上寒我家襄水曲遥隔楚云端乡泪客中尽孤帆天际看迷津欲有问平海夕漫漫", "树叶飘落、大雁南飞，北风吹得江上寒冷。我的家在襄水的弯曲处，远远隔着楚地的云端。思乡的泪在客旅中流尽，孤帆向天边望去。迷失了渡口想问路，平阔的海面傍晚茫茫无边。"],
    [303, "tangshi-ts-129", "public-domain", "人事有代谢往来成古今江山留胜迹我辈复登临水落鱼梁浅天寒梦泽深羊公碑尚在读罢泪沾襟", "人事有新陈代谢，往来之间便成了古今。江山留下名胜古迹，我们又来登临。水落下去鱼梁洲显得浅，天气寒冷云梦泽显得深。羊公碑还在，读完之后泪水沾湿了衣襟。"],
    [304, "poems-xx6-17", "school", "故人具鸡黍邀我至田家绿树村边合青山郭外斜开轩面场圃把酒话桑麻待到重阳日还来就菊花", "老友准备了饭菜，邀我到农家做客。绿树环绕着村庄，青山在城郭外斜卧。打开窗子面对谷场菜园，端着酒谈说庄稼。等到重阳节，还要再来赏菊。"],
    [305, "tangshi-ts-131", "public-domain", "北阙休上书南山归敝庐不才明主弃多病故人疏白发催年老青阳逼岁除永怀愁不寐松月夜窗虚", "不再到北阙去上书，回到南山的旧屋。没有才能被明主弃置，身体多病故人也疏远。白发催人老去，春天逼近岁末。长怀愁绪睡不着，松间月色照着空寂的夜窗。"],
    [307, "poems-xx1-07", "school", "春眠不觉晓处处闻啼鸟夜来风雨声花落知多少", "春天睡得香甜，不知不觉天就亮了，处处听到鸟儿的鸣叫。回想夜里风雨的声音，不知落了多少花。"],
    [308, "poems-xx6-01", "school", "移舟泊烟渚日暮客愁新野旷天低树江清月近人", "我把船停靠在烟雾迷蒙的小洲边，日暮时分，旅人的愁绪又添了一层。旷野无边无际，天比树还低；江水清澈，月影仿佛离人更近了。"],
    [309, "tangshi-ts-74", "academic", "噫吁嚱危乎高哉蜀道之难难于上青天蚕丛及鱼凫开国何茫然尔来四万八千岁不与秦塞通人烟西当太白有鸟道可以横绝峨眉巅地崩山摧壮士死然后天梯石栈相钩连上有六龙回日之高标下有冲波逆折之回川黄鹤之飞尚不得过猿猱欲度愁攀援青泥何盘盘百步九折萦岩峦扪参历井仰胁息以手抚膺坐长叹问君西游何时还畏途巉岩不可攀但见悲鸟号古木雄飞雌从绕林间又闻子规啼夜月愁空山蜀道之难难于上青天使人听此凋朱颜连峰去天不盈尺枯松倒挂倚绝壁飞湍瀑流争喧豗砯崖转石万壑雷其险也如此嗟尔远道之人胡为乎来哉剑阁峥嵘而崔嵬一夫当关万夫莫开所守或匪亲化为狼与豺朝避猛虎夕避长蛇磨牙吮血杀人如麻锦城虽云乐不如早还家蜀道之难难于上青天侧身西望长咨嗟", "唉呀呀，多么危险多么高峻！蜀道的艰难，比上青天还难！蚕丛和鱼凫开国的年代多么遥远茫昧。从那时以来四万八千年，不与秦地互通人烟。西面对着太白山只有鸟飞的路径，可以横越峨眉山顶。山崩地裂壮士死去，然后才有天梯石栈互相钩连。上面有六龙驾日都要回旋的高峰，下面有波涛冲击、回旋倒流的河川。黄鹤高飞尚且飞不过去，猿猱想过也愁于攀援。青泥岭多么曲折，百步之内九次折转萦绕着山峦。手摸参星、身历井宿，仰头屏息，抚胸而坐、长声叹息。问你西游何时回来，可怕的道路、险峻的山岩不可攀登。只见悲鸟在古木上号叫，雄飞雌随绕在林间。又听见子规在月夜里啼叫，愁满空山。蜀道的艰难，比上青天还难，使人听了这消息都容颜憔悴。连绵的山峰离天不到一尺，枯松倒挂着倚在绝壁上。飞流瀑布争相喧腾，撞击山崖、转动巨石，万壑轰鸣如雷。它如此险要，可叹你这远道之人为什么到这里来呢。剑阁峥嵘而高峻，一人把关，万人也攻不开。守关的若不是亲信，就会变成豺狼。早上要躲避猛虎，晚上要躲避长蛇。它们磨牙吸血，杀人如麻。锦城虽说快乐，不如早些回家。蜀道的艰难，比上青天还难，侧身向西望去，长声叹息。"],
    [310, "poems-gz11-06", "academic", "君不见黄河之水天上来奔流到海不复回君不见高堂明镜悲白发朝如青丝暮成雪人生得意须尽欢莫使金樽空对月天生我材必有用千金散尽还复来烹羊宰牛且为乐会须一饮三百杯岑夫子丹丘生将进酒杯莫停与君歌一曲请君为我倾耳听钟鼓馔玉不足贵但愿长醉不愿醒古来圣贤皆寂寞惟有饮者留其名陈王昔时宴平乐斗酒十千恣欢谑主人何为言少钱径须沽取对君酌五花马千金裘呼儿将出换美酒与尔同销万古愁", "你没有看见吗？黄河之水从天上奔腾而来，滚滚东流入海再也不回还。你没有看见吗？在高堂明镜前悲叹白发，早晨还是满头青丝，傍晚就变成了白雪。人生得意时就应当尽情欢乐，不要让金杯空对着明月。上天生下我这人才一定有用，千金散尽也还会再来。烹羊宰牛暂且尽情享乐，要喝就应当一饮三百杯。岑夫子，丹丘生，快喝酒，不要停下杯子。我为你们唱一首歌，请你们侧耳为我倾听。那些豪华的宴饮不值得珍贵，只愿长醉不愿醒来。自古以来的圣贤都很寂寞，只有善于饮酒的人才留下了名声。陈王曹植当年在平乐观设宴，斗酒万钱，尽情欢乐。主人为什么说钱少呢？只管去买酒来，让我与你们共饮。这名贵的五花马，这价值千金的裘皮衣，叫我的儿子拿出去换成美酒，让我们一同来消解这万古的愁绪！"],
    [315, "tangshi-ts-63", "public-domain", "明月出天山苍茫云海间长风几万里吹度玉门关汉下白登道胡窥青海湾由来征战地不见有人还戍客望边色思归多苦颜高楼当此夜叹息未应闲", "明月从天山升起，出没在苍茫的云海之间。长风吹过几万里，一直吹过玉门关。汉朝出兵白登道，胡人窥视青海湾。自古以来征战的地方，不见有人生还。守边的将士望着边地的景色，思归的脸上多是苦色。高楼上的妻子在这夜里，叹息声大约也不曾停歇。"],
    [317, "tangshi-ts-93", "public-domain", "玉阶生白露夜久侵罗袜却下水晶帘玲珑望秋月", "玉石台阶上生出白露，夜深了露水浸湿了罗袜。只好放下水晶帘，隔着玲珑的帘子望着秋月。"],
    [321, "tangshi-ts-5", "public-domain", "燕草如碧丝秦桑低绿枝当君怀归日是妾断肠时春风不相识何事入罗帏", "燕地的草绿得像碧丝，秦地的桑树压低绿枝。当你想着回家的时候，正是我肝肠寸断的时候。春风素不相识，为什么吹进我的罗帐？"],
    [325, "tangshi-ts-105", "public-domain", "吾爱孟夫子风流天下闻红颜弃轩冕白首卧松云醉月频中圣迷花不事君高山安可仰徒此揖清芬", "我喜爱孟夫子，他的风流潇洒天下闻名。年轻时就抛弃了官爵车马，白头时高卧在松云之间。醉于明月频频称圣，迷恋花草而不去侍奉君王。像高山一样怎么能够仰望，只好在此拱手敬仰他清高的品德。"],
    [326, "tangshi-ts-40", "public-domain", "我本楚狂人凤歌笑孔丘手持绿玉杖朝别黄鹤楼五岳寻仙不辞远一生好入名山游庐山秀出南斗傍屏风九叠云锦张影落明湖青黛光金阙前开二峰长银河倒挂三石梁香炉瀑布遥相望回崖沓嶂凌苍苍翠影红霞映朝日鸟飞不到吴天长登高壮观天地间大江茫茫去不还黄云万里动风色白波九道流雪山好为庐山谣兴因庐山发闲窥石镜清我心谢公行处苍苔没早服还丹无世情琴心三叠道初成遥见仙人彩云里手把芙蓉朝玉京先期汗漫九垓上愿接卢敖游太清", "我本是楚国的狂人接舆，唱着凤歌嘲笑孔丘。手拿绿玉杖，清晨辞别黄鹤楼。寻访五岳的仙人不怕路远，一生就喜欢到名山去游历。庐山秀丽地耸立在南斗星旁，像九叠屏风张开的云锦，山影落入明净的湖中，泛着青黛色的光。金阙岩前两座山峰长耸，三石梁上瀑布如银河倒挂。香炉峰与瀑布遥遥相望，回环的山崖、层叠的山嶂凌驾于苍茫之上。翠影红霞映着朝阳，鸟儿也飞不到吴地那辽阔的天空。登高远望，天地间景色壮观，大江茫茫东去不回。万里黄云随风变色，九道白波如雪山奔流。我喜爱作这首庐山谣，诗兴因庐山而发。闲来窥看石镜以清我心，谢灵运走过的地方已被苍苔埋没。早服仙丹便无世俗之情，琴心三叠，道行初成。远远望见仙人在彩云里，手把芙蓉朝拜玉京。我预先约好在九天之上相会，愿与你卢敖一同遨游太清。"],
    [327, "tangshi-ts-41", "academic", "海客谈瀛洲烟涛微茫信难求越人语天姥云霞明灭或可睹天姥连天向天横势拔五岳掩赤城天台四万八千丈对此欲倒东南倾我欲因之梦吴越一夜飞度镜湖月湖月照我影送我至剡溪谢公宿处今尚在渌水荡漾清猿啼脚著谢公屐身登青云梯半壁见海日空中闻天鸡千岩万转路不定迷花倚石忽已暝熊咆龙吟殷岩泉栗深林兮惊层巅云青青兮欲雨水澹澹兮生烟列缺霹雳丘峦崩摧洞天石扉訇然中开青冥浩荡不见底日月照耀金银台霓为衣兮风为马云之君兮纷纷而来下虎鼓瑟兮鸾回车仙之人兮列如麻忽魂悸以魄动恍惊起而长嗟惟觉时之枕席失向来之烟霞世间行乐亦如此古来万事东流水别君去兮何时还且放白鹿青崖间须行即骑访名山安能摧眉折腰事权贵使我不得开心颜", "航海的人谈起瀛洲，烟波渺茫实在难以寻求。越地的人说起天姥山，云霞明灭之间或许还能看见。天姥山连着天向天横亘，山势超出五岳，遮蔽了赤城。天台山高四万八千丈，对着它也要向东南倾倒。我想因此梦游吴越，一夜之间飞过月光下的镜湖。湖月照着我的影子，把我送到剡溪。谢灵运当年住宿的地方如今还在，绿水荡漾，清猿啼叫。我脚穿谢公的木屐，身登直上青云的石梯。半山腰看见海上日出，半空中听到天鸡啼鸣。千岩万壑峰回路转，路径不定，迷恋山花倚着石头，忽然天色已暮。熊在咆哮、龙在吟啸，震动岩石与泉水；使深林战栗，令层巅惊骇。云青青的将要下雨，水澹澹的生起烟雾。闪电霹雳，山峦崩裂。仙洞的石门，轰然从中打开。青天浩荡看不到底，日月照耀着金银台。以彩虹为衣、以风为马，云中的神仙纷纷降下。老虎鼓瑟、鸾鸟驾车，仙人们排列得像麻一样多。忽然心惊魄动，恍然惊醒而长声叹息。身边只有醒来时的枕席，失去了刚才的烟霞仙境。世间行乐也当如此，古来万事都如东流之水。告别你离去何时才回来，暂且把白鹿放养在青崖之间，要走时就骑上它去访名山。怎能低眉弯腰去侍奉权贵，使我不能舒心畅意。"],
    [328, "tangshi-ts-42", "public-domain", "风吹柳花满店香吴姬压酒唤客尝金陵子弟来相送欲行不行各尽觞请君试问东流水别意与之谁短长", "风吹着柳花，满店都是香气，吴地的姑娘压出酒来招呼客人品尝。金陵的子弟们前来相送，要走未走之间各自饮尽杯中的酒。请你问问那向东流去的江水，这离别的深情与它相比谁短谁长。"],
    [330, "poems-cz8-08", "school", "渡远荆门外来从楚国游山随平野尽江入大荒流月下飞天镜云生结海楼仍怜故乡水万里送行舟", "我乘船远渡到荆门之外，来到楚地漫游。山峦随着平坦的原野的出现而渐渐消失，江水奔流进入辽远无际的原野。月亮倒映在水中，像天上飞下来一面明镜；云气升起，结成了海市蜃楼。我还是怜爱故乡的水，它不远万里送我的行舟。"],
    [331, "poems-cz8-27", "academic", "青山横北郭白水绕东城此地一为别孤蓬万里征浮云游子意落日故人情挥手自兹去萧萧班马鸣", "青山横亘在城北，白水环绕着城东。我们在这里分别，你像孤单的蓬草随风飘转，踏上万里征程。浮云飘忽不定，正如游子的心意；落日不忍落下，正如故人的情谊。挥手告别，从此离去，只听见马儿萧萧的嘶鸣。"],
    [332, "tangshi-ts-43", "public-domain", "弃我去者昨日之日不可留乱我心者今日之日多烦忧长风万里送秋雁对此可以酣高楼蓬莱文章建安骨中间小谢又清发俱怀逸兴壮思飞欲上青天揽明月抽刀断水水更流举杯消愁愁更愁人生在世不称意明朝散发弄扁舟", "弃我而去的，昨天的时光已不可挽留；扰乱我心的，今天的日子又有许多烦忧。长风万里送走秋雁，面对这样的景色正可以在高楼上痛饮。你的文章有蓬莱阁的气象、建安的风骨，其间谢朓又清新秀发。我们都怀有飘逸的兴致、雄壮的思绪飞扬，想登上青天去揽取明月。抽刀去砍水，水反而流得更急；举杯消愁，愁反而更愁。人生在世既不能称心如意，不如明天就披散头发，泛一叶小舟而去。"],
    [333, "tangshi-ts-3", "public-domain", "暮从碧山下山月随人归却顾所来径苍苍横翠微相携及田家童稚开荆扉绿竹入幽径青萝拂行衣欢言得所憩美酒聊共挥长歌吟松风曲尽河星稀我醉君复乐陶然共忘机", "傍晚从青山下来，山间的月亮一路随着我归来。回头望望走过的山路，只见苍苍茫茫横着一片青翠的山色。与友人相携来到田家，孩童为我们打开柴门。绿竹夹着幽静的小路，青藤拂过行人的衣裳。欢谈之间找到了歇息的好地方，姑且举杯共饮美酒。放声长歌吟咏松林的风，唱完时天上银河里的星星已经稀疏。我醉了你也高兴，乐陶陶地把世俗的机巧之心全都忘掉。"],
    [334, "tangshi-ts-178", "public-domain", "凤凰台上凤凰游凤去台空江自流吴宫花草埋幽径晋代衣冠成古丘三山半落青天外二水中分白鹭洲总为浮云能蔽日长安不见使人愁", "凤凰台上曾有凤凰来游，凤凰飞去、台子空留、江水自流。吴宫的花草埋没了幽径，晋代的衣冠成了古坟。三山一半落在青天之外，二水被白鹭洲从中分开。总是因为浮云能够遮蔽太阳，望不见长安使人发愁。"],
    [335, "poems-xx3-08", "school", "朝辞白帝彩云间千里江陵一日还两岸猿声啼不住轻舟已过万重山", "清晨告别彩云缭绕的白帝城，千里之外的江陵一天就能到达。两岸猿猴的叫声还没停，轻快的小船已驶过万重山。"],
    [336, "tangshi-ts-109", "public-domain", "牛渚西江夜青天无片云登舟望秋月空忆谢将军余亦能高咏斯人不可闻明朝挂帆席枫叶落纷纷", "牛渚的西江之夜，青天没有一片云。我登船遥望秋月，徒然怀念谢尚将军。我也能高声吟咏，只是这样的人已经听不到了。明天早上就扬帆而去，枫叶纷纷落下。"],
    [338, "tangshi-ts-108", "public-domain", "蜀僧抱绿绮西下峨嵋峰为我一挥手如听万壑松客心洗流水余响入霜钟不觉碧山暮秋云暗几重", "蜀地的僧人抱着绿绮琴，从西边的峨嵋峰下来。为我挥手一弹，像听到万壑的松涛。客子之心被流水般的琴声洗净，余音融入霜天的钟声。不知不觉碧山已暮，秋云暗了好几重。"],
    [339, "tangshi-ts-232", "public-domain", "美人卷珠帘深坐颦蛾眉但见泪痕湿不知心恨谁", "美人卷起珠帘，久坐皱眉。只见她泪痕沾湿，却不知她心里怨恨的是谁。"],
    [341, "tangshi-ts-25", "public-domain", "兵卫森画戟宴寝凝清香海上风雨至逍遥池阁凉烦疴近消散嘉宾复满堂自惭居处崇未睹斯民康理会是非遣性达形迹忘鲜肥属时禁蔬果幸见尝俯饮一杯酒仰聆金玉章神欢体自轻意欲凌风翔吴中盛文史群彦今汪洋方知大藩地岂曰财赋强", "卫兵林立，画戟森然，宴饮的寝室里凝聚着清雅的香气。海上的风雨袭来，池阁之间逍遥自在、一片清凉。烦闷的疾病近来将要消散，嘉宾又坐满了厅堂。我惭愧自己居处高显，却未能看到百姓安康。道理通了是非就自然排遣，性情通达就连形迹也忘了。荤腥鲜美的食物正逢时禁，好在蔬菜瓜果还能请大家品尝。低头饮一杯酒，抬头聆听金玉般的美文。心神欢畅身体自然轻快，真想凌风飞翔。吴中之地文史兴盛，众多才俊如今济济一堂。这才知道大藩之地，岂止是财物赋税强盛而已。"],
    [342, "tangshi-ts-26", "public-domain", "凄凄去亲爱泛泛入烟雾归棹洛阳人残钟广陵树今朝此为别何处还相遇世事波上舟沿洄安得住", "凄凄然地离开亲爱的人，飘飘荡荡驶进烟雾之中。我这是要乘船回洛阳去的人，耳边还萦绕着广陵树影传来的残钟声。今天在这里与你分别，何处才能再相逢。世事就像波涛上的小船，顺流逆流哪里能停得住。"],
    [343, "tangshi-ts-203", "public-domain", "去年花里逢君别今日花开又一年世事茫茫难自料春愁黯黯独成眠身多疾病思田里邑有流亡愧俸钱闻道欲来相问讯西楼望月几回圆", "去年花开时与你相逢又分别，今日花开又是一年。世事茫茫难以预料，春愁黯淡、独自成眠。身体多病、思念田园，县里有流亡的百姓、愧领俸钱。听说你要来看望我，我在西楼望月、月已圆了几回。"],
    [344, "tangshi-ts-27", "public-domain", "今朝郡斋冷忽念山中客涧底束荆薪归来煮白石欲持一瓢酒远慰风雨夕落叶满空山何处寻行迹", "今天郡斋里清冷，忽然想起山中修行的朋友。他在山涧底下捆些柴草，回来煮那白色的石头为食。我想带着一瓢酒，远道去慰问这风雨的夜晚。可落叶铺满了空旷的山野，到哪里去寻找他的踪迹呢。"],
    [345, "tangshi-ts-145", "public-domain", "楚江微雨里建业暮钟时漠漠帆来重冥冥鸟去迟海门深不见浦树远含滋相送情无限沾襟比散丝", "楚江笼罩在微雨里，正是建业敲响晚钟的时候。江面漠漠、船帆沉重，天色冥冥、鸟儿迟归。海门深远望不见，水边的树木远远含着水汽。相送的情意无穷无尽，泪水沾湿衣襟，比散乱的雨丝还多。"],
    [346, "tangshi-ts-31", "public-domain", "永日方戚戚出行复悠悠女子今有行大江溯轻舟尔辈苦无恃抚念益慈柔幼为长所育两别泣不休对此结中肠义往难复留自小阙内训事姑贻我忧赖兹托令门任恤庶无尤贫俭诚所尚资从岂待周孝恭遵妇道容止顺其猷别离在今晨见尔当何秋居闲始自遣临感忽难收归来视幼女零泪缘缨流", "整天都在悲戚，出行又是那么遥远。女儿今天要出嫁，要逆着大江乘轻舟而去。你们自幼丧母，我抚育思念，更加慈爱温柔。妹妹是你这做姐姐的抚养大的，今朝分别，两人哭个不停。面对此情我心中郁结，可女儿应当出嫁，难以再留。你从小缺少母亲的教诲，侍奉婆婆让我担忧。好在托身到好人家，但愿能受到信任体恤，不致有什么过失。安贫节俭本是我所崇尚的，嫁妆哪里需要置办周全。要孝顺恭敬，遵守为妇之道，仪容举止都要合乎规矩。离别就在今晨，再见你不知是哪个秋天。平日闲暇时还能自我排遣，临到别时这感情忽然难以收住。回来后看着小女儿，眼泪顺着帽带直往下流。"],
    [347, "tangshi-ts-28", "public-domain", "客从东方来衣上灞陵雨问客何为来采山因买斧冥冥花正开飏飏燕新乳昨别今已春鬓丝生几缕", "客人从东方来，衣上还带着灞陵的雨痕。我问客人为何而来，他说要为开山采薪来买斧头。花在幽暗中正开着，燕子翩翩飞舞，雏燕刚刚育出。上次分别到如今已是春天，你两鬓又添了几缕白发呢。"],
    [348, "tangshi-ts-29", "public-domain", "落帆逗淮镇停舫临孤驿浩浩风起波冥冥日沉夕人归山郭暗雁下芦洲白独夜忆秦关听钟未眠客", "落下风帆停泊在淮水边的城镇，停船靠近一座孤零零的驿站。浩浩荡荡的风掀起波浪，天色昏暗太阳沉入暮色。人们回到山边的城郭，暮色四合；大雁飞落芦洲，一片银白。孤独的夜里思念着秦关故土，我是个听着钟声难以入眠的旅人。"],
    [349, "tangshi-ts-30", "public-domain", "吏舍跼终年出郊旷清曙杨柳散和风青山澹吾虑依丛适自憩缘涧还复去微雨霭芳原春鸠鸣何处乐幽心屡止遵事迹犹遽终罢斯结庐慕陶直可庶", "终年在官署里拘束，出到郊外才感到清晨的空旷清朗。杨柳在和风中舒展，青山使我的思虑淡泊下来。依着树丛正好独自歇息，沿着山涧信步又归去。微雨笼罩着芬芳的原野，春鸠在何处鸣叫。我喜爱幽静，屡屡停下脚步，可公务在身行迹还是匆匆。终究要辞官在此结庐而居，仰慕陶渊明大概能够相近。"],
    [350, "poems-xx3-17", "school", "独怜幽草涧边生上有黄鹂深树鸣春潮带雨晚来急野渡无人舟自横", "我独爱涧边幽静的青草，岸上有黄鹂在深树中鸣叫。春潮带着夜雨来得急，荒野渡口无人，小船自在地横着。"],
    [351, "tangshi-ts-99", "public-domain", "独有宦游人偏惊物候新云霞出海曙梅柳渡江春淑气催黄鸟晴光转绿苹忽闻歌古调归思欲沾巾", "只有宦游在外的人，才特别惊觉物候的变化。云霞从海上透出曙光，梅柳渡过江来带来春意。和暖的气息催促黄鸟鸣叫，晴朗的阳光使绿苹转动。忽然听到你唱起古雅的曲调，归乡的思绪使我泪湿手巾。"],
    [353, "tangshi-ts-46", "public-domain", "北风卷地白草折胡天八月即飞雪忽如一夜春风来千树万树梨花开散入珠帘湿罗幕狐裘不暖锦衾薄将军角弓不得控都护铁衣冷难著瀚海阑干百丈冰愁云惨淡万里凝中军置酒饮归客胡琴琵琶与羌笛纷纷暮雪下辕门风掣红旗冻不翻轮台东门送君去去时雪满天山路山回路转不见君雪上空留马行处", "北风卷地而来，白草都吹折了，塞外八月就飞起雪花。忽然像是一夜之间春风吹来，千树万树梨花盛开。雪花飘进珠帘沾湿罗幕，狐皮袍不暖、锦被也显薄。将军的角弓冻得拉不开，都护的铁甲冷得穿不上。沙漠纵横着百丈坚冰，愁云惨淡凝结万里。中军帐里摆酒饯别归京的客人，奏起胡琴、琵琶和羌笛。傍晚大雪纷纷落在辕门外，风扯着红旗冻得不能飘动。我在轮台东门送你离去，走时雪已铺满天山路。山回路转，看不见你的身影，雪地上只留下马蹄的印迹。"],
    [354, "tangshi-ts-45", "public-domain", "轮台城头夜吹角轮台城北旄头落羽书昨夜过渠黎单于已在金山西戍楼西望烟尘黑汉兵屯在轮台北上将拥旄西出征平明吹笛大军行四边伐鼓雪海涌三军大呼阴山动虏塞兵气连云屯战场白骨缠草根剑河风急雪片阔沙口石冻马蹄脱亚相勤王甘苦辛誓将报主静边尘古来青史谁不见今见功名胜古人", "轮台城头夜里吹起号角，轮台城北的旄头星坠落。插羽毛的紧急军书昨夜越过渠黎，单于已经到了金山西边。从戍楼上向西望去，烟尘一片昏黑，汉朝兵马驻扎在轮台北面。上将手持旄节向西出征，天刚亮就吹笛出发、大军开拔。四边擂鼓震得雪海翻涌，三军齐声呐喊使阴山动摇。敌营兵气连云屯聚，战场上白骨缠着草根。剑河风急雪片大，沙口石头冻硬，马蹄都冻得脱落。亚相为国勤劳，甘心吃苦，发誓要报答君王、扫清边尘。自古以来青史留名谁没看见，如今你的功名将胜过古人。"],
    [356, "tangshi-ts-104", "public-domain", "联步趋丹陛分曹限紫微晓随天仗入暮惹御香归白发悲花落青云羡鸟飞圣朝无阙事自觉谏书稀", "我们并肩快步走上红色的台阶，分属不同官署、相隔在紫微省左右。早晨随着天子的仪仗入朝，傍晚沾着御香归来。白发的人悲叹花落，望着青云羡慕鸟飞。圣明的朝廷没有缺失之事，自己觉得进谏的奏书也少了。"],
    [357, "tangshi-ts-185", "public-domain", "银烛朝天紫陌长禁城春色晓苍苍千条弱柳垂青琐百啭流莺绕建章剑佩声随玉墀步衣冠身惹御炉香共沐恩波凤池里朝朝染翰侍君王", "银烛照着上朝的路、紫陌漫长，宫城的春色在晨光中苍苍。千条柔柳垂在宫门两侧，黄莺百啭绕着建章宫。剑佩的响声随着走上玉阶的脚步，衣冠上沾着御炉的香气。我们一同沐浴皇恩在凤凰池里，天天挥毫侍奉君王。"],
    [358, "poems-cz7-16", "school", "故园东望路漫漫双袖龙钟泪不干马上相逢无纸笔凭君传语报平安", "向东望着故乡，路途遥远漫长，两只袖子沾满泪水，擦也擦不干。在马上与你相遇，没有纸笔写信，只好请你捎个口信，告诉我的家人我一切平安。"]
    ],
    songci300: [
    [1, "songci-sc-3", "public-domain", "碧云天黄叶地秋色连波波上寒烟翠山映斜阳天接水芳草无情更在斜阳外黯乡魂追旅思夜夜除非好梦留人睡明月楼高休独倚酒入愁肠化作相思泪", "碧蓝的天，枯黄的地，秋色连着水波，波上笼着翠色的寒烟。远山映着斜阳，水天相接；无情的芳草，一直铺到斜阳之外。\n思乡的心黯然销魂，羁旅的愁绪缠着不放，除非夜夜有好梦留人安睡。明月当空，不要独自倚在高楼上；酒入愁肠，只会化作相思的眼泪。"],
    [2, "songci-sc-34", "public-domain", "陇首云飞江边日晚烟波满目凭阑久一望关河萧索千里清秋忍凝眸杳杳神京盈盈仙子别来锦字终难偶断雁无凭冉冉飞下汀洲思悠悠暗想当初有多少幽欢佳会岂知聚散难期翻成雨恨云愁阻追游每登山临水惹起平生心事一场消黯永日无言却下层楼", "山顶云飞，江边日落，满眼烟波，我倚着栏杆站了很久。望出去关山河川一片萧索，千里清秋，怎忍心一直看下去。遥远的京城，那位盈盈的佳人，别后连书信也难得相通。失群的孤雁没有凭据，缓缓飞下汀洲，我的思念悠悠无尽。\n暗自回想当初，有多少幽会欢聚，哪里知道聚散难以预期，反而变成云雨般的愁恨。想追寻旧游而不可得。每次登山临水，都惹起平生心事，一场黯然消魂，整天说不出一句话，只好走下高楼。"],
    [3, "songci-sc-37", "public-domain", "月华收云淡霜天曙西征客此时情苦翠娥执手送临歧轧轧开朱户千娇面盈盈伫立无言有泪断肠争忍回顾一叶兰舟便恁急桨凌波去贪行色岂知离绪万般方寸但饮恨脉脉同谁语更回首重城不见寒江天外隐隐两三烟树", "月华收尽，云淡霜天，天将破晓。西行的旅人，此时心里最苦。她握着我的手送到岔路口，朱红门户轧轧打开。千娇百媚的脸，盈盈地站着，说不出话，只有泪；我肝肠寸断，怎忍回头再看。\n一叶兰舟，就这样飞快地划桨凌波而去。只顾着赶路，哪里懂得离愁别绪；千般滋味堵在心口，只能含恨，脉脉之情向谁诉说。再回头，重重城郭已看不见，寒江之外，天边隐隐只有两三株烟树。"],
    [5, "songci-sc-39", "public-domain", "自春来惨绿愁红芳心是事可可日上花梢莺穿柳带犹压香衾卧暖酥消腻云亸终日厌厌倦梳裹无那恨薄情一去音书无个早知恁么悔当初不把雕鞍锁向鸡窗只与蛮笺象管拘束教吟课镇相随莫抛躲针线闲拈伴伊坐和我免使年少光阴虚过", "自从春天来了，绿叶凄惨、红花含愁，我心里对什么事都提不起劲。太阳升上花梢，黄莺在柳条间穿飞，我还赖在香被里躺着。肌肤消瘦，鬓发松垂，整天懒懒地不愿梳妆。无可奈何，只恨那薄情的人一去，连一封信也没有。\n早知如此，后悔当初没有把他的马鞍锁住。让他在书房里，只用纸笔，拘着让他吟诗作文。要一直相随，不许躲开；闲时拈着针线陪他坐着。与我在一起，免得把这青春的年少光阴白白虚度。"],
    [6, "songci-sc-40", "public-domain", "长安古道马迟迟高柳乱蝉嘶夕阳岛外秋风原上目断四天垂归云一去无踪迹何处是前期狎兴生疏酒徒萧索不似少年时", "长安古道上，马儿慢吞吞地走，高柳上乱蝉嘶鸣。夕阳在岛屿之外，秋风起在原野上，望到天边，四面天幕低垂。\n归云一去没有踪迹，从前的约期又在哪里？冶游的兴致已生疏，酒友也已零落，再不像少年时候了。"],
    [7, "songci-sc-41", "public-domain", "晚秋天一霎微雨洒庭轩槛菊萧疏井梧零乱惹残烟凄然望江关飞云黯淡夕阳闲当时宋玉悲感向此临水与登山远道迢递行人凄楚倦听陇水潺湲正蝉吟败叶蛩响衰草相应喧喧孤馆度日如年风露渐变悄悄至更阑长天净绛河清浅皓月婵娟思绵绵夜永对景那堪屈指暗想从前未名未禄绮陌红楼往往经岁迁延帝里风光好当年少日暮宴朝欢况有狂朋怪侣遇当歌对酒竞留连别来迅景如梭旧游似梦烟水程何限念利名憔悴长萦绊追往事空惨愁颜漏箭移稍觉轻寒渐呜咽画角数声残对闲窗畔停灯向晓抱影无眠", "晚秋天气，一阵小雨洒在庭院。栏杆旁的菊花稀疏，井边的梧桐零乱，惹起残烟。心里凄然，望向江关，飞云黯淡，夕阳悠闲。当年宋玉的悲感，正是在这样的地方临水登山。远路迢迢，行人凄楚，听厌了陇头流水的潺潺声。正当蝉在败叶间鸣，蟋蟀在衰草里叫，相互应和，一片喧闹。\n独宿孤馆，度日如年；风露渐渐变冷，悄悄到了更深夜尽。长空澄净，银河清浅，皓月美好。思绪绵绵，长夜对着这景致，怎堪扳着指头回想从前。没有功名，没有俸禄，只在绮陌红楼里，往往一混就是一年。\n京城风光好，当年年少时，朝朝暮暮宴饮欢乐。何况有一群狂放的朋友，遇到当歌对酒的场合就争着留连。别来光阴快得像梭子，旧游如梦，烟水茫茫，路程哪里有个尽头。想那名利，把人熬得憔悴，长久地缠住不放。追想往事，只是白白地满面愁惨。漏箭移动，渐渐觉得有些轻寒。画角声渐次呜咽，几声之后断了。对着闲窗，熄了灯守到天亮，抱着影子无法入睡。"],
    [8, "songci-sc-42", "public-domain", "冻云黯淡天气扁舟一叶乘兴离江渚渡万壑千岩越溪深处怒涛渐息樵风乍起更闻商旅相呼片帆高举泛画鹢翩翩过南浦望中酒旆闪闪一簇烟村数行霜树残日下渔人鸣榔归去败荷零落衰杨掩映岸边两两三三浣纱游女避行客含羞笑相语到此因念绣阁轻抛浪萍难驻叹后约丁宁竟何据惨离怀空恨岁晚归期阻凝泪眼杳杳神京路断鸿声远长天暮", "寒云黯淡的天气，一叶小舟乘兴离开江边。渡过万壑千岩，到了越溪深处。怒涛渐渐平息，顺风忽然吹起，又听见商旅互相招呼。一片船帆高高扬起，画着鹢鸟的船翩翩驶过南浦。\n远望中酒旗闪闪，一簇烟村，几行霜树。残阳下，渔人敲着船舷归去。败荷零落，衰柳掩映，岸边三三两两，是浣纱的游女。她们避开行人，含羞地笑着说话。\n看到这里，就想起自己轻易抛下了绣阁，像浮萍一样漂泊难停。可叹临别时千叮万嘱的约期，究竟有什么凭据。离怀凄惨，白白怨恨岁暮归期受阻。含着泪眼，望那遥远的京城路。孤雁声远去，长天已暮。"],
    [9, "songci-sc-44", "public-domain", "对潇潇暮雨洒江天一番洗清秋渐霜风凄紧关河冷落残照当楼是处红衰翠减苒苒物华休惟有长江水无语东流不忍登高临远望故乡渺邈归思难收叹年来踪迹何事苦淹留想佳人妆楼颙望误几回天际识归舟争知我倚阑干处正恁凝愁", "面对着潇潇暮雨洒遍江天，一番雨把清秋洗得更净。霜风渐渐凄紧，关河冷落，残阳照在楼上。到处红花衰败、绿叶凋减，美好的景物渐渐消歇。只有长江水，默默地向东流。\n不忍登高望远，望故乡渺茫遥远，归思难以收住。可叹这些年来的行踪，为什么苦苦滞留他乡？想那佳人正在妆楼上抬头凝望，多少次把天边的船误认作我的归舟。她怎知道，我在倚栏的地方，正这样凝着愁。"],
    [11, "songci-sc-45", "public-domain", "一叶扁舟轻帆卷暂泊楚江南岸孤城暮角引胡笳怨水茫茫平沙雁旋惊散烟敛寒林簇画屏展天际遥山小黛眉浅旧赏轻抛到此成游宦觉客程劳年光晚异乡风物忍萧索当愁眼帝城赊秦楼阻旅魂乱芳草连空阔残照满佳人无消息断云远", "一片轻帆卷起，小舟暂泊在楚江南岸。孤城响起暮角，引出胡笳哀怨。江水茫茫，平沙上的大雁转眼被惊散。烟雾收敛，寒林成簇，像展开的画屏。天边的远山很小，像浅浅的黛眉。\n轻易抛下了从前的欢赏，到这里做了游宦。觉得客途劳顿，年光已晚。异乡的风物，怎忍心在这愁眼前一片萧索。京城遥远，秦楼阻隔，旅人的心魂纷乱。芳草连着辽阔的天空，残照洒满。佳人没有消息，像断云一样远去了。"],
    [12, "songci-sc-8", "public-domain", "双蝶绣罗裙东池宴初相见朱粉不深匀闲花淡淡春细看诸处好人人道柳腰身昨日乱山昏来时衣上云", "罗裙上绣着一对蝴蝶，那是在东池的宴席上初次相见。脸上的脂粉抹得很淡，像闲花淡淡地开着，自有一段春意。\n细细看去，处处都好；人人都说，她的腰身像柳枝一样细。昨日黄昏乱山模糊，她来时衣上仿佛带着云彩。"],
    [13, "songci-sc-10", "public-domain", "水调数声持酒听午醉醒来愁未醒送春春去几时回临晚镜伤流景往事后期空记省沙上并禽池上暝云破月来花弄影重重帘幕密遮灯风不定人初静明日落红应满径", "端着酒听了几声《水调》，午间醉倒，醒来后愁还没醒。送走了春天，春天什么时候再回来？傍晚对镜，感伤时光流逝，往事与日后的约期都白白记在心里。\n沙上成双的水鸟栖息，池边天色昏暝；云开月出，花在月下摆弄影子。层层帘幕密密遮住灯光，风还在吹，人刚刚静下来，料想明天落花该铺满小径了。"],
    [14, "songci-sc-6", "public-domain", "数声鶗鴂又报芳菲歇惜春更选残红折雨轻风色暴梅子青时节永丰柳无人尽日花飞雪莫把幺弦拨怨极弦能说天不老情难绝心似双丝网中有千千结夜过也东窗未白凝残月", "几声杜鹃啼叫，又报告春天已经过去。因惜春，我特意挑一枝残花折下。雨点轻而风力猛，正是梅子发青的时节。永丰坊的柳树无人过问，整日飘着如雪的柳絮。\n不要拨动那根细弦，怨到极处时，琴弦会把心事都说出来。天不会老，情也难断绝。心像双丝结成的网，中间有千千万万个结。夜已经过去了，东窗未白，只留着一弯残月。"],
    [21, "songci-sc-25", "public-domain", "群芳过后西湖好狼籍残红飞絮濛濛垂柳阑干尽日风笙歌散尽游人去始觉春空垂下帘栊双燕归来细雨中", "百花凋谢之后，西湖反而更好看：落花狼藉，柳絮迷蒙，垂柳拂着栏杆，整天吹着风。\n笙歌散尽，游人离去，这才觉得春天空了。放下帘子，看一双燕子在细雨中归来。"],
    [22, "songci-sc-26", "public-domain", "清晨帘幕卷轻霜呵手试梅妆都缘自有离恨故画作远山长思往事惜流芳易成伤拟歌先敛欲笑还颦最断人肠", "清晨卷起帘幕，外面落着轻霜；呵暖手，试着画梅花妆。都因为心中自有离恨，所以把眉画得像远山一样长。\n回想往事，惋惜流逝的芳华，最容易伤心。想唱歌先收起笑意，要笑又皱起眉头，最叫人断肠。"],
    [23, "songci-sc-27", "public-domain", "候馆梅残溪桥柳细草薰风暖摇征辔离愁渐远渐无穷迢迢不断如春水寸寸柔肠盈盈粉泪楼高莫近危阑倚平芜尽处是春山行人更在春山外", "驿馆旁梅花凋残，溪桥边柳丝细长，草香风暖，他摇着马缰上路。离愁随着路程渐远而无穷无尽，像春水一样迢迢不断。\n一寸寸柔肠，一行行粉泪；楼虽高，也别靠近栏杆去倚。平坦的原野尽头是春山，而远行的人还在春山之外。"],
    [26, "songci-sc-32", "public-domain", "把酒祝东风且共从容垂杨紫陌洛城东总是当时携手处游遍芳丛聚散苦匆匆此恨无穷今年花胜去年红可惜明年花更好知与谁同", "举酒向东风祝愿：暂且从容一些。洛阳城东的垂杨大道上，都是当年我们携手同游、走遍花丛的地方。\n聚散总是匆匆，这恨没有尽头。今年的花比去年红；可惜明年花更好，又知道能与谁一同观赏！"],
    [30, "songci-sc-9", "public-domain", "伤高怀远几时穷无物似情浓离愁正引千丝乱更东陌飞絮濛濛嘶骑渐遥征尘不断何处认郎踪双鸳池沼水溶溶南北小桡通梯横画阁黄昏后又还是斜月帘栊沉恨细思不如桃杏犹解嫁东风", "登高伤怀、思念远人，什么时候才到尽头？没有什么比情更浓的东西了。离愁正引得千丝万缕纷乱，何况东边路上，飞絮迷蒙。嘶鸣的马越走越远，扬起的尘土不断，我到哪里去认他的行踪？\n池水溶溶，有双鸳鸯嬉戏，南北的小船相通。黄昏后，画阁上梯子横放着，又还是那一钩斜月照着窗帘。深恨之中细细想来，还不如桃花杏花——它们还懂得嫁给东风。"],
    [32, "songci-sc-38", "public-domain", "梦觉透窗风一线寒灯吹息那堪酒醒又闻空阶夜雨频滴嗟因循久作天涯客负佳人几许盟言便忍把从前欢会陡顿翻成忧戚愁极再三追思洞房深处几度饮散歌阑香暖鸳鸯被岂暂时疏散费伊心力殢云尤雨有万般千种相怜相惜恰到如今天长漏永无端自家疏隔知何时却拥秦云态愿低帏昵枕轻轻细说与江乡夜夜数寒更思忆", "梦醒时一线风透进窗来，把寒灯吹灭了。更难受的是酒醒之后，又听见空台阶上夜雨滴滴答答。可叹我因循蹉跎，长久在外做天涯客，辜负了佳人多少盟誓，竟忍心把从前的欢会，一下子翻成忧愁。\n愁到极处，再三追想：在洞房深处，有好几次饮罢歌残，香暖的鸳鸯被里。哪里是暂时的分别，实在费了她的心力。那时如云似雨，千种万般，互相怜惜。\n到了如今，天长夜永，无缘无故地自己疏远了。不知何时才能重新拥着那如云的情态，愿在低垂的帷幕、贴身的枕上，轻轻地细细说给她听：在江乡的每一夜，我数着寒更思念你。"],
    [36, "songci-sc-14", "public-domain", "一向年光有限身等闲离别易销魂酒筵歌席莫辞频满目山河空念远落花风雨更伤春不如怜取眼前人", "一年的时光有限，人的身体也有限，寻常的离别最叫人伤感。酒席歌筵，不要嫌它太频繁。\n满眼山河，白白地思念远方；落花风雨，更添伤春之情。不如好好珍惜眼前的人。"],
    [38, "songci-sc-7", "public-domain", "哀筝一弄湘江曲声声写尽湘波绿纤指十三弦细将幽恨传当筵秋水慢玉柱斜飞雁弹到断肠时春山眉黛低", "古筝哀怨地弹起一支湘江曲，声声都化作湘江的绿水。纤细的手指按着十三根弦，细细地把深藏的幽恨传出来。\n筵席上，她的目光像秋水一样缓缓流动，弦柱像斜飞的雁行。弹到最伤心的地方，双眉微低，像笼着春山的黛色。"],
    [39, "songci-sc-23", "public-domain", "锁离愁连绵无际来时陌上初熏绣帏人念远暗垂珠露泣送征轮长行长在眼更重重远水孤云但望极楼高尽日目断王孙销魂池塘别后曾行处绿妒轻裙恁时携素手乱花飞絮里缓步香茵朱颜空自改向年年芳意长新遍绿野嬉游醉眼莫负青春", "芳草锁住离愁，连绵无边；来时路上，草香初起。绣帘中的人思念远行的人，暗暗垂下露珠般的泪，哭着送走远行的车轮。车马走远了，仍在眼中，更有重重远水和孤云。只能登上高楼极目远望，整日望到看不见行人。\n伤心啊。池塘一别之后，她走过的地方，绿草都嫉妒她轻软的罗裙。那时牵着她的素手，在乱花飞絮中缓步走在香草地上。如今红颜白白地改变，而芳草年年依旧新绿。让它绿遍原野吧，纵情游乐、醉眼相看，不要辜负了青春。"],
    [40, "songci-sc-24", "public-domain", "东城渐觉风光好縠皱波纹迎客棹绿杨烟外晓寒轻红杏枝头春意闹浮生长恨欢娱少肯爱千金轻一笑为君持酒劝斜阳且向花间留晚照", "城东的风光渐渐好起来，像绉纱一样的水波迎着游船。绿杨笼在轻烟里，清晨的寒意很轻；红杏枝头上，春意热闹非凡。\n人生浮沉，常恨欢乐太少，怎肯吝惜千金而看轻一笑？我为你端着酒去劝斜阳：暂且留在花间，多照一会儿吧。"],
    [44, "poems-gz10-18", "school", "登临送目正故国晚秋天气初肃千里澄江似练翠峰如簇归帆去棹残阳里背西风酒旗斜矗彩舟云淡星河鹭起画图难足念往昔繁华竞逐叹门外楼头悲恨相续千古凭高对此谩嗟荣辱六朝旧事随流水但寒烟衰草凝绿至今商女时时犹唱后庭遗曲", "登上高处向远处眺望，正是故都金陵的晚秋时节，天气开始变得肃杀。千里澄澈的长江像一条白练，青翠的山峰像箭簇一样聚集。江中归来的船帆和离去的船桨沐浴在残阳里，背着西风，酒旗斜斜地竖着。彩绘的船只在淡云中，银河般的长江上白鹭飞起，这样的美景图画也难以画尽。回想往昔，人们竞相追逐繁华，可叹隋兵已临城下，陈后主还在楼头寻欢作乐，悲恨接连不断。千古以来登高凭吊，徒然感叹荣辱兴亡。六朝的旧事已随流水逝去，只剩寒烟衰草凝着一片绿色。至今歌女还时时唱着《玉树后庭花》那亡国之音。"],
    [45, "songci-sc-48", "public-domain", "别馆寒砧孤城画角一派秋声入寥廓东归燕从海上去南来雁向沙头落楚台风庾楼月宛如昨无奈被些名利缚无奈被他情担阁可惜风流总闲却当初谩留华表语而今误我秦楼约梦阑时酒醒后思量着", "别馆里的寒砧声，孤城上的画角声，一派秋声散入空阔的天空。东归的燕子从海上飞去，南来的大雁落在沙头。楚王的兰台之风、庾亮的南楼之月，宛然如昨。\n无奈被那点名利缠住，无奈被那点人情耽搁，可惜风流都白白闲却了。当初白白留下华表上的话，如今又误了我秦楼的约会。梦醒的时候，酒醒以后，反复思量着。"],
    [46, "songci-sc-49", "public-domain", "留春不住费尽莺儿语满地残红宫锦污昨夜南园风雨小怜初上琵琶晓来思绕天涯不肯画堂朱户春风自在杨花", "留不住春天，白白费尽黄莺的啼叫。满地落花像弄脏了的宫锦——昨夜南园下了风雨。\n小怜刚刚弹起琵琶，天亮时思绪已绕着天涯飞。它不肯待在画堂朱户里，春风中只有杨花自在地飞。"],
    [47, "songci-sc-50", "public-domain", "梦后楼台高锁酒醒帘幕低垂去年春恨却来时落花人独立微雨燕双飞记得小蘋初见两重心字罗衣琵琶弦上说相思当时明月在曾照彩云归", "梦醒后楼台高锁，酒醒后帘幕低垂。去年的春恨又在此时涌上心头。落花中我独自站立，微雨里燕子双双飞过。\n记得初次见到小蘋时，她穿着绣有两重心字的罗衣。琵琶弦上诉说着相思。当时的明月还在，曾照着她像彩云一样归去。"],
    [49, "songci-sc-53", "public-domain", "彩袖殷勤捧玉钟当年拚却醉颜红舞低杨柳楼心月歌尽桃花扇底风从别后忆相逢几回魂梦与君同今宵剩把银釭照犹恐相逢是梦中", "她穿着彩袖殷勤地捧起玉杯，当年我甘愿喝得满脸通红。舞到杨柳楼头的月亮低下去，唱到桃花扇底的清风停息。\n自从分别以后，回想相逢，多少回梦魂与你相同。今夜只管举着银灯照了又照，还怕这次相逢也是梦里。"],
    [50, "songci-sc-54", "public-domain", "关山魂梦长鱼雁音尘少两鬓可怜青只为相思老归梦碧纱窗说与人人道真个别离难不似相逢好", "关山阻隔，魂梦悠长；书信稀少，音信难通。两鬓原本可爱的黑发，只因为相思而变白。\n梦里回到碧纱窗前，对那人说：离别真是难，不如相逢好。"],
    [52, "songci-sc-57", "public-domain", "留人不住醉解兰舟去一棹碧涛春水路过尽晓莺啼处渡头杨柳青青枝枝叶叶离情此后锦书休寄画楼云雨无凭", "留不住人，他醉中解开兰舟离去。一桨划进碧涛春水，驶过所有黄莺啼叫的地方。\n渡头的杨柳青青，枝枝叶叶都是离情。从今以后不必再寄书信了，画楼里的欢会本来就没有凭据。"],
    [54, "songci-sc-61", "public-domain", "街南绿树春饶絮雪满游春路树头花艳杂娇云树底人家朱户北楼闲上疏帘高卷直见街南树阑干倚尽犹慵去几度黄昏雨晚春盘马踏青苔曾傍绿阴深驻落花犹在香屏空掩人面知何处", "街南绿树成荫，春天柳絮很多，像雪铺满游春的路。树梢上繁花与娇云相杂，树下有人家的朱门。闲来登上北楼，把疏帘高高卷起，一直望见街南的树。\n把栏杆倚遍还懒得离开，几番黄昏都下着雨。晚春时曾骑马踏过青苔，在绿荫下久久停留。如今落花还在，香屏空掩，那张熟悉的脸不知去了何处。"],
    [55, "songci-sc-62", "public-domain", "曲阑干外天如水昨夜还曾倚初将明月比佳期长向月圆时候望人归罗衣着破前香在旧意谁教改一春离恨懒调弦犹有两行闲泪宝筝前", "曲栏杆外天色如水，昨夜我还曾倚在这里。起初把明月比作佳期，总在月圆的时候盼望人归来。\n罗衣穿破了，从前的香气还在；旧日的情意，是谁教它改的？一春的离恨，懒得去调弦，却还有两行无端的热泪，落在宝筝前面。"],
    [56, "songci-sc-63", "public-domain", "画屏天畔梦回依约十洲云水手捻红笺寄人书写无限伤春事别浦高楼曾漫倚对江南千里楼下分流水声中有当日凭高泪", "画屏上远接天边，梦醒时依稀还在十洲的云水之间。手里捻着红笺给人写信，写不尽伤春的心事。\n在离别的江边高楼上曾随意倚过，面对着千里江南。楼下分流的水声里，还留着当日登高洒下的眼泪。"],
    [57, "songci-sc-64", "public-domain", "红叶黄花秋意晚千里念行客飞云过尽归鸿无信何处寄书得泪弹不尽临窗滴就砚旋研墨渐写到别来此情深处红笺为无色", "红叶黄花，秋意已晚，我思念千里之外的行人。飞云过尽，归雁也不带信，书信能寄到哪里去？\n眼泪弹不尽，临窗滴落，就着砚台随即研墨。渐渐写到别后的事，情深处，红笺都褪了颜色。"],
    [58, "songci-sc-65", "public-domain", "明月几时有把酒问青天不知天上宫阙今夕是何年我欲乘风归去又恐琼楼玉宇高处不胜寒起舞弄清影何似在人间转朱阁低绮户照无眠不应有恨何事长向别时圆人有悲欢离合月有阴晴圆缺此事古难全但愿人长久千里共婵娟", "明月是什么时候才有的？我端起酒杯问青天。不知道天上的宫殿，今夜是哪一年。我想乘风回去，又怕琼楼玉宇太高，受不住那份寒冷。起身起舞，戏弄自己的影子，哪里比得上人间。\n月光转过朱红楼阁，低低地照进雕花窗户，照着不能入睡的人。明月不该有什么怨恨，为什么总在离别时团圆？人有悲欢离合，月有阴晴圆缺，这种事自古难以周全。只愿人长久平安，虽隔千里，也能共赏这轮明月。"],
    [60, "songci-sc-69", "public-domain", "冰肌玉骨自清凉无汗水殿风来暗香满绣帘开一点明月窥人人未寝欹枕钗横鬓乱起来携素手庭户无声时见疏星渡河汉试问夜如何夜已三更金波淡玉绳低转但屈指西风几时来又不道流年暗中偷换", "冰一样的肌肤、玉一样的骨，自然清凉无汗。水殿上风吹来，暗暗满是香气。绣帘掀开，一点明月来窥人；人还未睡，斜靠着枕头，金钗横斜、鬓发零乱。\n起身牵着她的素手，庭院寂静无声，不时看见稀疏的星子渡过银河。试问夜到什么时辰了？已过三更，月光淡了，玉绳星低低转动。只是扳着手指算西风几时来，却没料到流年已在暗中偷偷换了。"],
    [61, "songci-sc-71", "public-domain", "三年枕上吴中路遣黄耳随君去若到松江呼小渡莫惊鸥鹭四桥尽是老子经行处辋川图上看春暮常记高人右丞句作个归期天已许春衫犹是小蛮针线曾湿西湖雨", "三年梦里都想着回吴中的路。派黄犬随你归去。若到松江叫小渡船，不要惊动鸥鹭；四桥一带，都是我走过的地方。\n在《辋川图》上看春暮的景致，常记得王维那样高人写的句子。定下归期，老天已经答应了。身上的春衫还是小蛮亲手缝的，曾被西湖的雨打湿过。"],
    [62, "songci-sc-72", "public-domain", "夜饮东坡醒复醉归来仿佛三更家童鼻息已雷鸣敲门都不应倚杖听江声长恨此身非我有何时忘却营营夜阑风静縠纹平小舟从此逝江海寄余生", "夜里在东坡饮酒，醒了又醉，回来时仿佛已三更。家童鼾声如雷，敲门都不应，只好拄着拐杖听江声。\n常恨这身子不属于自己，什么时候才能忘掉那些营营碌碌？夜深风静，水面像绉纱一样平。就乘一叶小舟从此远去，把余生寄托在江海之间。"],
    [63, "songci-sc-73", "public-domain", "莫听穿林打叶声何妨吟啸且徐行竹杖芒鞋轻胜马谁怕一蓑烟雨任平生料峭春风吹酒醒微冷山头斜照却相迎回首向来萧瑟处归去也无风雨也无晴", "不要去听那穿林打叶的雨声，不妨一边吟诗长啸一边慢慢走。竹杖草鞋比骑马还轻快，怕什么？披一件蓑衣，任凭一生风雨。\n料峭的春风吹醒了酒意，有些微冷；山头的斜阳却迎面照来。回头看看方才风雨萧瑟的地方——回去吧，也无所谓风雨，也无所谓晴。"],
    [64, "songci-sc-76", "public-domain", "霜余已失长淮阔空听潺潺清颍咽佳人犹唱醉翁词四十三年如电抹草头秋露流珠滑三五盈盈还二八与余同是识翁人惟有西湖波底月", "霜降之后，淮河已失了宽阔的气象，只听见清颍河潺潺如咽。歌女还在唱醉翁的词，四十三年像闪电一抹就过去了。\n草尖上的秋露像滚动的珠，月儿十五圆满、十六也还圆。与我一样认识醉翁的人，只有西湖水底的月亮。"],
    [65, "songci-sc-74", "public-domain", "乳燕飞华屋悄无人桐阴转午晚凉新浴手弄生绡白团扇扇手一时似玉渐困倚孤眠清熟帘外谁来推绣户枉教人梦断瑶台曲又却是风敲竹石榴半吐红巾蹙待浮花浪蕊都尽伴君幽独秾艳一枝细看取芳心千重似束又恐被秋风惊绿若待得君来向此花前对酒不忍触共粉泪两簌簌", "小燕飞过华屋，悄无人声，桐荫转过午后，傍晚凉爽，她刚沐浴过。手里把着生绡白团扇，扇子与手一时都像玉。渐渐困倦，斜倚着独自睡熟。帘外是谁来推绣户？白白教人从瑶台的仙梦里惊醒——却又只是风敲竹子。\n石榴花半开，像蹙起的红巾。等那些浮花浪蕊都谢尽，它来陪伴你的幽独。细看那一枝浓艳，芳心千重，像被束住。又怕被秋风惊落绿叶。若等到你来时，面对花前饮酒也不忍触碰；那时花与粉泪，一同簌簌落下。"],
    [66, "songci-sc-85", "public-domain", "梅英疏淡冰澌溶泄东风暗换年华金谷俊游铜驼巷陌新晴细履平沙长记误随车正絮翻蝶舞芳思交加柳下桃蹊乱分春色到人家西园夜饮鸣笳有华灯碍月飞盖妨花兰苑未空行人渐老重来是事堪嗟烟暝酒旗斜但倚楼极目时见栖鸦无奈归心暗随流水到天涯", "梅花稀疏淡了，冰块溶化流去，东风暗暗换了年华。金谷园的名胜、铜驼街的巷陌，新晴时细步走在平沙上。常记得错跟了别人的车。那时柳絮翻飞、蝴蝶飞舞，芳心交杂。柳下桃径，把春色乱分到各家。\n西园夜里饮酒吹笳。华灯挡住月亮，飞驰的车盖妨碍看花。兰苑还没有空，行人却渐渐老了，重来这里事事可叹！烟雾昏暝，酒旗斜挂。只能倚楼极目，不时看见栖鸦。无奈归心，暗暗随流水到天涯。"],
    [68, "songci-sc-90", "public-domain", "漠漠轻寒上小楼晓阴无赖似穷秋淡烟流水画屏幽自在飞花轻似梦无边丝雨细如愁宝帘闲挂小银钩", "漠漠的轻寒漫上小楼，清晨的阴天无赖得像深秋。淡烟流水，画屏幽静。\n自在的飞花轻得像梦，无边的丝雨细得像愁。宝帘闲挂在小银钩上。"],
    [69, "songci-sc-91", "public-domain", "湘天风雨破寒初深沉庭院虚丽谯吹罢小单于迢迢清夜徂乡梦断旅魂孤峥嵘岁又除衡阳犹有雁传书郴阳和雁无", "湘天的风雨冲破寒意之初，深沉的庭院空寂。丽谯楼上吹罢《小单于》，迢迢清夜流去。\n乡梦断了，旅魂孤单，年岁峥嵘又到除夕。衡阳还有大雁传书，郴阳连雁也没有。"],
    [70, "songci-sc-92", "public-domain", "枝上流莺和泪闻新啼痕间旧啼痕一春鱼鸟无消息千里关山劳梦魂无一语对芳尊安排肠断到黄昏甫能炙得灯儿了雨打梨花深闭门", "枝上流莺的啼声和着泪听，新的泪痕夹着旧的泪痕。一春没有鱼雁消息，千里关山白白劳烦梦魂。\n一句话也没有，对着酒杯，安排着断肠直到黄昏。刚把灯点上，雨就打梨花，只好把门深深关上。"],
    [72, "songci-sc-106", "public-domain", "新绿小池塘风帘动碎影舞斜阳羡金屋去来旧时巢燕土花缭绕前度莓墙绣阁里凤帏深几许听得理丝簧欲说又休虑乖芳信未歌先噎愁近清觞遥知新妆了开朱户应自待月西厢最苦梦魂今宵不到伊行问甚时说与佳音密耗寄将秦镜偷换韩香天便教人霎时厮见何妨", "小池塘一片新绿，风吹帘动，碎影在斜阳里舞。羡慕那金屋中来去的旧巢燕，羡慕那绕着旧日莓墙的苔花。绣阁里，凤帐深到什么程度？只听得她调理乐器。想说话又停住，怕误了佳音；还没唱就先哽住，愁绪贴近清酒。\n远远想她新妆已就，打开朱门，该在西厢待月。最苦的是梦魂今夜也到不了她身边。问什么时候才能把好消息密告她，送去秦镜、偷换韩香。老天既然让人相见，哪怕只是片刻又何妨！"],
    [73, "songci-sc-95", "public-domain", "问春何苦匆匆带风伴雨如驰骤幽葩细萼小园低槛壅培未就吹尽繁红占春长久不如垂柳算春常不老人愁春老愁只是人间有春恨十常八九忍轻孤芳醪经口那知自是桃花结子不因春瘦世上功名老来风味春归时候纵樽前痛饮狂歌似旧情难依旧", "问春为什么这样匆匆，带着风伴着雨像疾驰一般。幽静的花、细小的萼，小园低栏里，培土还没培好。吹尽了繁花，能长久占住春天的，不如垂柳。算来春永远不会老，是人愁春老，这愁只在人间有。\n春恨十次里常有八九次。怎忍心轻易辜负了杯中美酒。哪知道桃花结子，并不是因为春去而消瘦。世上的功名，老来的滋味，都在春归的时候。纵然在杯前痛饮、狂歌如旧，情却难以依旧。"],
    [75, "songci-sc-69", "public-domain", "冰肌玉骨自清凉无汗水殿风来暗香满绣帘开一点明月窥人人未寝欹枕钗横鬓乱起来携素手庭户无声时见疏星渡河汉试问夜如何夜已三更金波淡玉绳低转但屈指西风几时来又不道流年暗中偷换", "冰一样的肌肤、玉一样的骨，自然清凉无汗。水殿上风吹来，暗暗满是香气。绣帘掀开，一点明月来窥人；人还未睡，斜靠着枕头，金钗横斜、鬓发零乱。\n起身牵着她的素手，庭院寂静无声，不时看见稀疏的星子渡过银河。试问夜到什么时辰了？已过三更，月光淡了，玉绳星低低转动。只是扳着手指算西风几时来，却没料到流年已在暗中偷偷换了。"],
    [76, "songci-sc-98", "public-domain", "忆昔西池池上饮年年多少欢娱别来不寄一行书寻常相见了犹道不如初安稳锦屏今夜梦月明好渡江湖相思休问定何如情知春去后管得落花无", "回想当年在西池池上饮酒，年年有多少欢乐。别后连一行书信也不寄。即使寻常相见，还说不像当初。\n今夜锦屏里安睡入梦，月明正好渡过江湖。相思不必问究竟怎样。明知春天去后，还管得了落花吗。"],
    [77, "songci-sc-99", "public-domain", "泪湿阑干花著露愁到眉峰碧聚此恨平分取更无言语空相觑断雨残云无意绪寂寞朝朝暮暮今夜山深处断魂分付潮回去", "泪水打湿栏杆，花瓣上挂着露珠；愁到极处，眉毛像碧峰聚拢。这恨两人平分，再没有话说，只是空对着看。\n断雨残云，毫无意绪，寂寞朝朝暮暮。今夜在山深处，把断了魂交给潮水带回去。"],
    [78, "songci-sc-100", "public-domain", "赤阑桥尽香街直笼街细柳娇无力金碧上青空花晴帘影红黄衫飞白马日日青楼下醉眼不逢人午香吹暗尘", "红栏杆的桥尽头，飘香的街道笔直；笼着街道的细柳娇柔无力。金碧楼台伸向青空，花开天晴，帘影泛红。\n穿黄衫的人骑着白马飞驰，天天在青楼下。醉眼朦胧看不见人，午间的香气吹起暗尘。"],
    [79, "songci-sc-69", "public-domain", "冰肌玉骨自清凉无汗水殿风来暗香满绣帘开一点明月窥人人未寝欹枕钗横鬓乱起来携素手庭户无声时见疏星渡河汉试问夜如何夜已三更金波淡玉绳低转但屈指西风几时来又不道流年暗中偷换", "冰一样的肌肤、玉一样的骨，自然清凉无汗。水殿上风吹来，暗暗满是香气。绣帘掀开，一点明月来窥人；人还未睡，斜靠着枕头，金钗横斜、鬓发零乱。\n起身牵着她的素手，庭院寂静无声，不时看见稀疏的星子渡过银河。试问夜到什么时辰了？已过三更，月光淡了，玉绳星低低转动。只是扳着手指算西风几时来，却没料到流年已在暗中偷偷换了。"],
    [80, "songci-sc-103", "public-domain", "我住长江头君住长江尾日日思君不见君共饮长江水此水几时休此恨何时已只愿君心似我心定不负相思意", "我住在长江的源头，你住在长江的末尾。天天想你却见不到你，好在共饮一江之水。\n这水什么时候流尽？这恨什么时候了结？只愿你的心像我的心，就绝不辜负这份相思。"],
    [81, "songci-sc-105", "public-domain", "章台路还见褪粉梅梢试花桃树愔愔坊陌人家定巢燕子归来旧处黯凝伫因念个人痴小乍窥门户侵晨浅约宫黄障风映袖盈盈笑语前度刘郎重到访邻寻里同时歌舞惟有旧家秋娘声价如故吟笺赋笔犹记燕台句知谁伴名园露饮东城闲步事与孤鸿去探春尽是伤离意绪官柳低金缕归骑晚纤纤池塘飞雨断肠院落一帘风絮", "章台路上，又看见梅梢褪了粉、桃树初绽花。街坊里人家安静，归巢的燕子回到旧处。\n我黯然凝立，想起她当初痴小，刚在门边偷看。清早淡淡地抹着宫黄，用袖子挡风，盈盈地笑着说话。\n前度刘郎重来，访邻寻里，当年一同歌舞的人。只有旧家的秋娘，声价还如从前。吟诗作赋，还记得那些燕台诗句。可知谁陪我在名园露下饮酒、在东城闲步。往事已随孤雁远去。探春所见，尽是伤离的情绪。官柳低垂着金丝般的柳条。暮色中骑马归来，池塘上飘着纤细的雨。断肠的院落，一帘风絮。"],
    [82, "songci-sc-106", "public-domain", "新绿小池塘风帘动碎影舞斜阳羡金屋去来旧时巢燕土花缭绕前度莓墙绣阁里凤帏深几许听得理丝簧欲说又休虑乖芳信未歌先噎愁近清觞遥知新妆了开朱户应自待月西厢最苦梦魂今宵不到伊行问甚时说与佳音密耗寄将秦镜偷换韩香天便教人霎时厮见何妨", "小池塘一片新绿，风吹帘动，碎影在斜阳里舞。羡慕那金屋中来去的旧巢燕，羡慕那绕着旧日莓墙的苔花。绣阁里，凤帐深到什么程度？只听得她调理乐器。想说话又停住，怕误了佳音；还没唱就先哽住，愁绪贴近清酒。\n远远想她新妆已就，打开朱门，该在西厢待月。最苦的是梦魂今夜也到不了她身边。问什么时候才能把好消息密告她，送去秦镜、偷换韩香。老天既然让人相见，哪怕只是片刻又何妨！"],
    [83, "songci-sc-104", "public-domain", "柳阴直烟里丝丝弄碧隋堤上曾见几番拂水飘绵送行色登临望故国谁识京华倦客长亭路年去岁来应折柔条过千尺闲寻旧踪迹又酒趁哀弦灯照离席梨花榆火催寒食愁一箭风快半篙波暖回头迢递便数驿望人在天北凄恻恨堆积渐别浦萦回津堠岑寂斜阳冉冉春无极念月榭携手露桥闻笛沉思前事似梦里泪暗滴", "柳荫笔直，烟雾中丝丝柳条摆弄碧色。在隋堤上，曾见过多少次它拂着水面、飘着柳絮送人远行。登高远望故国，谁能理解我这京城倦客？长亭路上，年去年来，折下的柳条该有千尺了。\n闲来寻觅旧日踪迹，又趁着哀弦饮酒，灯火照着离别的酒席。梨花与榆火催促寒食到来。愁那一帆风顺、一篙水暖，回头就已过了几个驿站，望见的人远在天北。\n凄恻，恨堆积！送别的江口曲折回环，渡口冷冷清清，斜阳缓缓移动，春色无边。回想月下楼台携手、露桥听笛。沉思往事，像在梦里，眼泪暗暗滴落。"],
    [84, "songci-sc-116", "public-domain", "暗柳啼鸦单衣伫立小帘朱户桐花半亩静锁一庭愁雨洒空阶夜阑未休故人剪烛西窗语似楚江暝宿风灯零乱少年羁旅迟暮嬉游处正店舍无烟禁城百五旗亭唤酒付与高阳俦侣想东园桃李自春小唇秀靥今在否到归时定有残英待客携尊俎", "暗柳上乌鸦啼叫，我穿着单衣久立，面前是小帘朱户。半亩桐花，静静地锁住一庭愁雨。雨洒在空台阶上，到夜深还没停，我和故人剪烛在西窗下说话。像在楚江夜宿，风灯零乱，那是少年的羁旅。\n已到迟暮之年。回想游乐的地方。正是店舍无烟、京城过寒食的时候。在旗亭唤酒，交给高阳酒徒那样的伙伴。想东园的桃李自在地开着春色，那小巧的嘴唇、秀美的酒窝如今还在吗？等我回去时，一定还有残花，等着我带着酒菜去赏。"],
    [85, "songci-sc-117", "public-domain", "水浴清蟾叶喧凉吹巷陌马声初断闲依露井笑扑流萤惹破画罗轻扇人静夜久凭阑愁不归眠立残更箭叹年华一瞬人今千里梦沉书远空见说鬓怯琼梳容销金镜渐懒趁时匀染梅风地溽虹雨苔滋一架舞红都变谁信无聊为伊才减江淹情伤荀倩但明河影下还看稀星数点", "月光在水里洗过，树叶被凉风吹得喧响，街巷里的马蹄声刚刚断绝。她闲来靠着露井，笑着扑打流萤，把画罗轻扇都弄破了。夜深人静，我倚着栏杆，愁得不想回去睡，站到更漏将尽。可叹年华只是一瞬，人如今相隔千里，梦沉书远。\n只听说她两鬓怕用玉梳，容颜在镜中消瘦，渐渐懒得按时梳妆。梅雨时节地上潮湿，虹雨后青苔滋长，一架红花都变了样。谁信我这样无聊是为了她，才思比江淹还减，情深如荀奉倩。只是银河影下，还看着几点稀疏的星。"],
    [86, "songci-sc-118", "public-domain", "粉墙低梅花照眼依然旧风味露痕轻缀疑净洗铅华无限佳丽去年胜赏曾孤倚冰盘同燕喜更可惜雪中高树香篝熏素被今年对花最匆匆相逢似有恨依依愁悴吟望久青苔上旋看飞坠相将见脆丸荐酒人正在空江烟浪里但梦想一枝潇洒黄昏斜照水", "粉墙低矮，梅花照眼，依旧是旧日的风味。露痕轻轻缀着，像洗净了脂粉，无限佳丽。去年尽兴赏花时曾独自倚树，与冰盘一同欢宴。更可惜雪中的高树，香笼熏着素被。\n今年对花最是匆匆，相逢似乎带着恨意，依依地愁瘦了。吟望久了，青苔上不时看见花瓣飞坠。不久将见梅子脆丸佐酒，而我正在空江烟浪里。只能梦想那一枝潇洒的梅花，在黄昏里斜照水面。"],
    [88, "songci-sc-121", "public-domain", "月皎惊乌栖不定更漏将阑轳辘牵金井唤起两眸清炯炯泪花落枕红绵冷执手霜风吹鬓影去意徊徨别语愁难听楼上阑干横斗柄露寒人远鸡相应", "月色皎洁，惊得乌鸦栖息不定；更漏将尽，井上辘轳在响。唤她起身，两只眼睛清亮有神，泪花落在枕上，红绵都冷了。\n握着手，霜风吹动鬓影；要走又迟疑，离别的话愁得听不下去。楼上栏杆外横着北斗的斗柄，露冷人远，鸡声相互应和。"],
    [89, "songci-sc-110", "public-domain", "怨怀无托嗟情人断绝信音辽邈纵妙手能解连环似风散雨收雾轻云薄燕子楼空暗尘锁一床弦索想移根换叶尽是旧时手种红药汀洲渐生杜若料舟依岸曲人在天角谩记得当日音书把闲语闲言待总烧却水驿春回望寄我江南梅萼拚今生对花对酒为伊泪落", "怨怀无处寄托，可叹情人断绝，音信遥远。纵有妙手能解开连环，也像风散雨收、雾轻云薄。燕子楼已空，暗尘锁住一床琴弦。想那草木移根换叶，都是旧时她亲手种的红芍药。\n汀洲上渐渐长出杜若。料想船停泊在弯曲的岸边，人远在天角。白白记得当日的书信，把那些闲言闲语，打算统统烧掉。水边驿站春回，盼望寄我一枝江南梅萼。拼了这辈子，对花对酒，为她落泪。"],
    [90, "songci-sc-125", "public-domain", "夜色催更清尘收露小曲幽坊月暗竹槛灯窗识秋娘庭院笑相遇似觉琼枝玉树相倚暖日明霞光烂水盼兰情总平生稀见画图中旧识春风面谁知道自到瑶台畔眷恋雨润云温苦惊风吹散念荒寒寄宿无人馆重门闭败壁秋虫叹怎奈向一缕相思隔溪山不断", "夜色催着更鼓，清尘收去露水，小巷深处月色暗淡。竹栏灯窗下，认得是秋娘的庭院。笑着相逢，仿佛琼枝玉树相依，暖日明霞光灿。水样的眼波、兰样的情意，一生中难得见到。\n像在画里见过那春风般的面容。谁知道，自从到了这瑶台畔，贪恋那雨润云温，却被惊风吹散。想我如今在荒寒的无人馆舍寄宿。重门紧闭，破壁下秋虫叹息。怎奈那一缕相思，隔着溪山也断不了。"],
    [93, "songci-sc-126", "public-domain", "隋堤路渐日晚密霭生深树阴阴淡月笼沙还宿河桥深处无情画舸都不管烟波隔前浦等行人醉拥重衾载将离恨归去因思旧客京华长偎傍疏林小槛欢聚冶叶倡条俱相识仍惯见珠歌翠舞如今向渔村水驿夜如岁焚香独自语有何人念我无憀梦魂凝想鸳侣", "隋堤路上，天色渐晚，浓雾从深树里生出。淡淡的月色阴暗地笼着沙岸，我还在河桥深处投宿。无情的画船，全不管烟波把前浦隔断。等行人醉拥厚被，就载着离恨归去。\n于是想起当年客居京城，常常偎傍疏林，在小栏杆边欢聚。那些冶叶倡条都相识，也惯见珠歌翠舞。如今却在渔村水驿，夜长得像一年，焚着香独自说话。有谁念我这般无聊，梦魂凝想着鸳鸯伴侣。"],
    [94, "songci-sc-131", "public-domain", "淡妆多态更的的频回眄睐便认得琴心先许欲绾合欢双带记画堂风月逢迎轻颦浅笑娇无奈向睡鸭炉边翔鸳屏里羞把香罗暗解自过了烧灯后都不见踏青挑菜几回凭双燕叮咛深意往来却恨重帘碍约何时再正春浓酒困人闲昼永无聊赖厌厌睡起犹有花梢日在", "她淡妆多态，又频频回头顾盼。便知道她已先许下琴心，想结起合欢的双带。记得在画堂里风月相迎，她轻蹙双眉、浅浅一笑，娇得无可奈何。在睡鸭炉边、翔鸳屏风里，羞怯地暗暗解下香罗。\n自从灯节过后，都不见踏青挑菜的约会。几次托双燕，叮咛深意，往来却恨重重帘幕阻隔。约好何时再见？正当春浓酒困，人闲昼长，无聊赖。懒懒地睡起，花梢上还挂着日影。"],
    [96, "songci-sc-135", "public-domain", "牛渚天门险限南北七雄豪占清雾敛与闲人登览待月上潮平波滟滟塞管轻吹新阿滥风满槛历历数西州更点", "牛渚天门形势险要，隔开南北，七国豪杰都曾占据。清雾收敛，让闲人登临观赏。\n等到月出潮平，波光滟滟，塞管轻吹新曲《阿滥堆》。风满栏杆，清晰地数着西州的更点。"],
    [97, "songci-sc-136", "public-domain", "烟络横林山沉远照迤逦黄昏钟鼓烛映帘栊蛩催机杼共苦清秋风露不眠思妇齐应和几声砧杵惊动天涯倦宦骎骎岁华行暮当年酒狂自负谓东君以春相付流浪征骖北道客樯南浦幽恨无人晤语赖明月曾知旧游处好伴云来还将梦去", "烟雾缠绕横林，远山沉入夕照，黄昏的钟鼓声连绵不断。烛光映着帘栊，蟋蟀催人纺织，一同受着清秋风露之苦。不眠的思妇，几声砧杵齐相应和。惊动了天涯倦宦，岁月匆匆将暮。\n当年以酒狂自负，以为春神会把春天交给我。如今却流浪在北道征鞍、南浦客舟。幽恨无人可以面谈。幸赖明月曾知旧游之处。好伴着云来，再把梦带去。"],
    [98, "songci-sc-137", "public-domain", "厌莺声到枕花气动帘醉魂愁梦相半被惜余薰带惊剩眼几许伤春春晚泪竹痕鲜佩兰香老湘天浓暖记小江风月佳时屡约非烟游伴须信鸾弦易断奈云和再鼓曲中人远认罗袜无踪旧处弄波清浅青翰棹舣白苹洲畔尽目临皋飞观不解寄一字相思幸有归来双燕", "厌听莺声传到枕边，花香拂动帘子，醉魂与愁梦各占一半。怜惜被上残留的香气，惊见腰带宽出许多孔，多少伤春之情，春天已晚。湘妃竹的泪痕还新，佩兰的香气已老，湘天浓暖。记得在江边风月最好的时候，多次约她同游。\n要知道鸾弦容易断，奈何重新鼓瑟，曲中人已远。认那罗袜的踪迹已无，旧日她戏水的清浅之处。乘着青翰船靠岸，停在白苹洲边。极目望那临皋的高楼。不会寄一个字来诉相思，幸有一双归燕。"],
    [101, "songci-sc-142", "public-domain", "落花已作风前舞又送黄昏雨晓来庭院半残红惟有游丝千丈罥晴空殷勤花下同携手更尽杯中酒美人不用敛歌眉我亦多情无奈酒阑时", "落花已在风前飞舞，又送走黄昏的雨。清晨庭院里一半是残花，只有千丈游丝挂在晴空。\n我们殷勤地在花下携手，把杯中酒喝干。美人不必皱起歌眉，我也是多情的人，只是无奈酒阑人散的时候。"],
    [103, "songci-sc-145", "public-domain", "频听银签重燃绛蜡年华衮衮惊心饯旧迎新能消几刻光阴老来可惯通宵饮待不眠还怕寒侵掩清尊多谢梅花伴我微吟邻娃已试春妆了更蜂腰簇翠燕股横金勾引东风也知芳思难禁朱颜那有年年好逞艳游赢取如今恣登临残雪楼台迟日园林", "频频听着更签，重新点上红烛，年华滚滚令人心惊。送旧迎新，能消磨几刻光阴？老了哪还习惯通宵饮酒？想不睡，又怕寒气侵入。放下酒杯，多谢梅花，陪我低声吟咏。\n邻家女孩已试过春妆，蜂腰般的发饰簇着翠，燕尾般的金钗横着。她勾引东风，也知道芳心难禁。红颜哪能年年都好，趁艳游赢得如今吧。尽情登临，看残雪的楼台、迟日的园林。"],
    [104, "poems-cz9-23", "academic", "忆昔午桥桥上饮坐中多是豪英长沟流月去无声杏花疏影里吹笛到天明二十余年如一梦此身虽在堪惊闲登小阁看新晴古今多少事渔唱起三更", "回忆当年在午桥桥上饮酒，在座的大多是英雄豪杰。长长的水沟里月影流动，悄无声息。在杏花稀疏的影子里，我们吹笛吹到天亮。二十多年过去了，就像一场梦，此身虽然还在，回想起来却令人心惊。如今闲来登上小阁，看看新晴的景色。古往今来多少兴亡之事，都化作三更时渔人的歌唱。"],
    [105, "songci-sc-148", "public-domain", "雁落平沙烟笼寒水古垒鸣笳声断青山隐隐败叶萧萧天际暝鸦零乱楼上黄昏片帆千里归程年华将晚望碧云空暮佳人何处梦魂俱远忆旧游邃馆朱扉小园香径尚想桃花人面书盈锦轴恨满金徽难写寸心幽怨两地离愁一尊芳酒凄凉危阑倚遍尽迟留凭仗西风吹干泪眼", "大雁落在平沙，烟雾笼着寒水，古垒的胡笳声断绝。青山隐约，败叶萧萧，天边暮鸦零乱。楼上已是黄昏，一片孤帆千里归程，年华将晚。望碧云笼着空暮，佳人在哪里？梦魂都远了。\n回忆旧游，深馆朱门，小园香径，还记得桃花般的面容。书信写满锦轴，怨恨充满琴徽，也难写尽心中幽怨。两地离愁，一尊美酒，凄凉地把危栏倚遍。久久停留，全靠西风，吹干泪眼。"],
    [106, "songci-sc-149", "public-domain", "数声鶗鴂可怜又是春归时节满院东风海棠铺绣梨花飘雪丁香露泣残枝算未比愁肠寸结自是休文多情多感不干风月", "几声杜鹃啼叫，可怜又是春归的时节。满院东风，海棠铺成锦绣，梨花飘如雪。\n丁香在残枝上泣露，算来也比不上我愁肠寸结。本是我像沈约那样多情多感，与风月无关。"],
    [107, "songci-sc-150", "public-domain", "一点残红欲尽时乍凉秋气满屏帏梧桐叶上三更雨叶叶声声是别离调宝瑟拨金猊那时同唱鹧鸪词如今风雨西楼夜不听清歌也泪垂", "一点残灯将尽的时候，初凉的秋气充满屏帏。梧桐叶上三更的雨，每一叶每一声都是别离。\n那时调宝瑟，拨香炉，一同唱《鹧鸪词》。如今风雨西楼之夜，不听清歌也落泪。"],
    [108, "songci-sc-151", "public-domain", "情似游丝人如飞絮泪珠阁定空相觑一溪烟柳万丝垂无因系得兰舟住雁过斜阳草迷烟渚如今已是愁无数明朝且做莫思量如何过得今宵去", "情像游丝，人如飞絮。泪珠含住，只是空对着看。一溪烟柳垂下万丝，却没有办法系住兰舟。\n大雁飞过斜阳，青草迷住烟渚。如今已是愁无数。明天的事暂且不去想，可今夜怎么捱得过去？"],
    [109, "songci-sc-152", "public-domain", "芳草碧色萋萋遍南陌暖絮乱红也知人春愁无力忆得盈盈拾翠侣共携赏凤城寒食到今来海角逢春天涯为客愁旋释还似织泪暗拭又偷滴谩伫立遍倚危阑尽黄昏也只是暮云凝碧拚则而今已拚了忘则怎生便忘得又还问鳞鸿试重寻消息", "芳草碧绿，茂盛地长满南边小路。暖絮乱红，也知道人春愁无力。记得那盈盈的拾翠伴侣，一同到京城赏寒食。到如今，在海角逢春，在天涯作客。\n愁刚解开，又像织起来；泪暗暗擦去，又偷偷滴下。白白地伫立，把危栏倚遍，直到黄昏，也只是暮云凝着碧色。舍弃既然已经舍弃了，要忘又怎么忘得掉。又去问鱼雁，试着重新打听消息。"],
    [112, "songci-sc-157", "public-domain", "洗妆真态不作铅华御竹外一枝斜想佳人天寒日暮黄昏院落无处著清香风细细雪垂垂何况江头路月边疏影梦到消魂处结子欲黄时又须作廉纤小雨孤芳一世供断有情愁消瘦损东阳也试问花知否", "洗去妆饰的本真态度，不用脂粉来修饰。竹外一枝斜出，想那佳人，在天寒日暮的时候。黄昏的院落，清香无处安放；风细细，雪垂垂，何况江头的路上。\n月边的疏影，梦到消魂的地方。等结子将要黄时，又该下起纤细的小雨。孤芳一世，供尽了有情人的愁，人瘦损如沈约，试问花知道吗？"],
    [113, "songci-sc-158", "public-domain", "篆缕销金鼎醉沉沉庭阴转午画堂人静芳草王孙知何处惟有杨花糁径渐玉枕腾腾春醒帘外残红春已透镇无聊殢酒厌厌病云鬓乱未忺整江南旧事休重省遍天涯寻消问息断鸿难倩月满西楼凭阑久依旧归期未定又只恐瓶沉金井嘶骑不来银烛暗枉教人立尽梧桐影谁伴我对鸾镜", "香炉里的篆烟消散。醉意沉沉，庭中树荫转过午后，画堂里人声寂静。芳草萋萋，那远行的人在哪里？只有杨花散在小径上。玉枕上渐渐从春睡中醒来。帘外残红，春天已过；整日无聊，被酒困着，恹恹成病。云鬓散乱，也懒得整理。\n江南的旧事不要再回想。走遍天涯寻消息，孤雁也难以托付。月满西楼，我倚栏很久，归期依旧未定。又只怕像瓶沉金井，音信全无。嘶鸣的马不来，银烛已暗，白白教人站到梧桐影尽。谁来陪我，面对鸾镜？"],
    [114, "songci-sc-159", "public-domain", "霭霭春空画楼森耸凌云渚紫薇登览最关情绝妙夸能赋惆怅相思迟暮记当日朱阑共语塞鸿难问岸柳何穷别愁纷絮催促年光旧来流水知何处断肠何必更残阳极目伤平楚晚霁波声带雨悄无人舟横野渡数峰江上芳草天涯参差烟树", "春空云气弥漫，画楼高耸直入云中的洲渚。登楼览景最牵动感情，前人绝妙的赋作值得称夸。惆怅相思已到迟暮，记得当日同在朱栏边说话。塞雁难问，岸柳无穷，别愁像纷乱的柳絮。\n年光被催促，旧日的流水如今在哪里？断肠何必再对着残阳，极目望去，平野令人伤心。晚晴后波声带着雨意。悄无人影，孤舟横在野渡。江上几座山峰，天涯一片芳草，参差的烟树。"],
    [117, "songci-sc-162", "public-domain", "风悲画角听单于三弄落谯门投宿骎骎征骑飞雪满孤村酒市渐阑灯火正敲窗乱叶舞纷纷送数声惊雁乍离烟水嘹唳度寒云好在半胧淡月到如今无处不消魂故国梅花归梦愁损绿罗裙为问暗香闲艳也相思万点付啼痕算翠屏应是两眉余恨倚黄昏", "风中画角悲鸣，听《单于》三弄从谯门落下。投宿的征骑匆匆赶路，飞雪落满孤村。酒市的灯火渐渐阑珊，正是乱叶敲窗、纷纷飞舞的时候。送走几声惊雁，它们刚离开烟水，嘹唳着飞过寒云。\n半朦胧的淡月还好，到如今无处不令人消魂。故国的梅花入归梦，愁坏了她绿罗裙。试问那暗香闲艳，是否也在相思，万点落成啼痕。算来翠屏里的人应是两眉含着余恨，倚到黄昏。"],
    [119, "songci-sc-164", "public-domain", "双阙中天凤楼十二春寒浅去年元夜奉宸游曾侍瑶池宴玉殿珠帘尽卷拥群仙蓬壶阆苑五云深处万烛光中揭天丝管驰隙流年恍如一瞬星霜换今宵谁念泣孤臣回首长安远可是尘缘未断谩惆怅华胥梦短满怀幽恨数点寒灯几声归雁", "双阙耸立天际，十二座凤楼间春寒尚浅。去年元宵夜随驾出游，曾侍瑶池之宴。玉殿上珠帘尽卷，拥着群仙，如在蓬壶阆苑。五色云深处，万烛光中，丝管之声震天。\n流年如白驹过隙，恍惚一瞬星霜就换了。今夜谁念我这泣泪的孤臣？回首长安已远。难道是尘缘未断？白白惆怅，华胥梦太短。满怀幽恨，几点寒灯，几声归雁。"],
    [120, "songci-sc-165", "public-domain", "夜来风雨匆匆故园定是花无几愁多怨极等闲孤负一年芳意柳困桃慵杏青梅小对人容易算好春长在好花长见原只是人憔悴回首池南旧事恨星星不堪重记如今但有看花老眼伤时清泪不怕逢花瘦只愁怕老来风味待繁红乱处留云借月也须拚醉", "夜里风雨匆匆，故园的花一定不剩多少了。愁多怨极，轻易辜负了一年芳意。柳困桃惰，杏青梅小，对人都不在意。算来好春长在，好花常开，只是人憔悴了。\n回望池南旧事，恨白发星星，不堪再记。如今只有看花的老眼、伤时的清泪。不怕见花憔悴，只愁老来的心境。等到繁红纷乱的时候，留住云借来月，也要拼着一醉。"],
    [121, "songci-sc-166", "public-domain", "长淮望断关塞莽然平征尘暗霜风劲悄边声黯销凝追想当年事殆天数非人力洙泗上弦歌地亦膻腥隔水毡乡落日牛羊下区脱纵横看名王宵猎骑火一川明笳鼓悲鸣遣人惊念腰间箭匣中剑空埃蠹竟何成时易失心徒壮岁将零渺神京干羽方怀远静烽燧且休兵冠盖使纷驰骛若为情闻道中原遗老常南望翠葆霓旌使行人到此忠愤气填膺有泪如倾", "望断淮河，关塞一片荒草平铺。征尘暗淡，霜风强劲，边地悄无声音。黯然神伤。追想当年的事，大概是天数，不是人力；洙水泗水之上，本是弦歌礼乐之地，如今也沾了膻腥。隔水就是毡帐之乡，落日里牛羊下来，敌人的哨所纵横。看那敌军首领夜间打猎，骑兵的火把照亮一川。胡笳战鼓悲鸣，令人心惊。\n想腰间的箭、匣中的剑，白白地积尘生蠹，终究成了什么！时机容易错过，心虽壮，年岁将尽。京城渺远。朝廷正以礼乐怀柔远人，熄灭烽火，暂且休兵。使者车马纷纷奔驰，叫人何以堪受！听说中原的遗民，常常向南盼望皇帝的仪仗。让行人来到这里，忠愤之气填满胸膛，泪如雨下。"],
    [122, "songci-sc-166", "public-domain", "长淮望断关塞莽然平征尘暗霜风劲悄边声黯销凝追想当年事殆天数非人力洙泗上弦歌地亦膻腥隔水毡乡落日牛羊下区脱纵横看名王宵猎骑火一川明笳鼓悲鸣遣人惊念腰间箭匣中剑空埃蠹竟何成时易失心徒壮岁将零渺神京干羽方怀远静烽燧且休兵冠盖使纷驰骛若为情闻道中原遗老常南望翠葆霓旌使行人到此忠愤气填膺有泪如倾", "望断淮河，关塞一片荒草平铺。征尘暗淡，霜风强劲，边地悄无声音。黯然神伤。追想当年的事，大概是天数，不是人力；洙水泗水之上，本是弦歌礼乐之地，如今也沾了膻腥。隔水就是毡帐之乡，落日里牛羊下来，敌人的哨所纵横。看那敌军首领夜间打猎，骑兵的火把照亮一川。胡笳战鼓悲鸣，令人心惊。\n想腰间的箭、匣中的剑，白白地积尘生蠹，终究成了什么！时机容易错过，心虽壮，年岁将尽。京城渺远。朝廷正以礼乐怀柔远人，熄灭烽火，暂且休兵。使者车马纷纷奔驰，叫人何以堪受！听说中原的遗民，常常向南盼望皇帝的仪仗。让行人来到这里，忠愤之气填满胸膛，泪如雨下。"],
    [123, "songci-sc-168", "public-domain", "凝碧旧池头一听管弦凄切多少梨园声在总不堪华发杏花无处避春愁也傍野烟发惟有御沟声断似知人呜咽", "在凝碧池边，一听管弦就觉得凄切。梨园的旧曲还有多少在？总叫人受不了这满头白发。\n杏花无处躲避春愁，也只能靠着野烟开放。只有御沟的水声断绝，像知道人在呜咽。"],
    [124, "songci-sc-169", "public-domain", "郊原初过雨见败叶零乱风定犹舞斜阳挂深树映浓愁浅黛遥山眉妩来时旧路尚岩花娇黄半吐到而今唯有溪边流水见人如故无语邮亭深静下马还寻旧曾题处无聊倦旅伤离恨最愁苦纵收香藏镜他年重到人面桃花在否念沉沉小阁幽窗有时梦去", "郊野刚下过雨，见败叶零乱，风停了还在飞舞。斜阳挂在深树间，映出浓愁般的浅黛，远山像美人的眉。来时的旧路，还有岩上的花娇黄半开。到如今，只有溪边的流水，见了人还如故。\n无语。邮亭深静，下马再去寻找旧日题字的地方。无聊的倦旅，伤离恨，最是愁苦。纵然收起香、藏起镜，他年重来时，那人面桃花还在吗？想那沉沉的小阁幽窗，有时在梦里去。"],
    [125, "songci-sc-170", "public-domain", "夜来雨赖倩得东风吹住海棠正妖娆处且留取悄庭户试细听莺啼燕语分明共人愁绪怕春去佳树翠阴初转午重帘未卷乍睡起寂寞看风絮偷弹清泪寄烟波见江头故人为言憔悴如许彩笺无数去却寒暄到了浑无定据断肠落日千山暮", "夜里的雨，幸得东风把它吹住。海棠正妖娆的时候，且留住它。庭院悄悄，试着细听莺啼燕语。分明和人一样有愁绪，怕春天归去。\n美好的树，绿荫初转过午后。重帘未卷，刚睡起，寂寞地看风中的柳絮。偷偷弹去清泪寄给烟波，若见到江头的故人，替我说我憔悴成这样。彩笺无数，除去寒暄，到头来全无准信。断肠时落日下千山已暮。"],
    [126, "songci-sc-171", "public-domain", "弱柳千丝缕嫩黄匀遍鸦啼处寒入罗衣春尚浅过一番风雨问燕子来时绿水桥边路曾画楼见个人人否料静掩云窗尘满哀弦危柱庾信愁如许为谁都著眉端聚独立东风弹泪眼寄烟波东去念永昼春闲人倦如何度闲傍枕百啭黄鹂语唤觉来厌厌残照依然花坞", "柔弱的柳丝千缕，嫩黄匀在乌鸦啼叫的地方。寒气侵入罗衣，春意还浅，又经过一番风雨。问燕子来时，绿水桥边的路上，可曾在画楼见过那个人？料想她静静掩着云窗，灰尘落满琴柱。\n庾信那样的愁有多少，为了谁聚在眉端？独自站在东风里弹去泪眼，托烟波向东带去。想那长长的春日闲人倦，怎么捱过？闲靠着枕头，听黄鹂百啭。被唤醒后恹恹无绪，残照依然照着花坞。"],
    [127, "songci-sc-172", "public-domain", "脸霞红印枕睡觉来冠儿还是不整屏间麝煤冷但眉峰压翠泪珠弹粉堂深昼永燕交飞风帘露井恨无人说与相思近日带围宽尽重省残灯朱幌淡月纱窗那时风景阳台路迥云雨梦便无准待归来先指花梢教看却把心期细问问因循过了青春怎生意稳", "脸上的红霞印在枕上，睡醒来，冠儿还是不整。屏风间的香墨冷了，只见眉峰压着翠色，泪珠冲下脂粉。堂深昼长，燕子交错飞过风帘露井。恨无人可以诉说：近日相思，衣带都宽尽了。\n重新回想，残灯朱帐、淡月纱窗，那时的风景。阳台的路遥远，云雨之梦便无准信。等他回来，先指着花梢让他看，再把心中期望细细追问。问他为什么因循蹉跎过了青春，怎么就能心安？"],
    [128, "songci-sc-103", "public-domain", "我住长江头君住长江尾日日思君不见君共饮长江水此水几时休此恨何时已只愿君心似我心定不负相思意", "我住在长江的源头，你住在长江的末尾。天天想你却见不到你，好在共饮一江之水。\n这水什么时候流尽？这恨什么时候了结？只愿你的心像我的心，就绝不辜负这份相思。"],
    [131, "songci-sc-168", "public-domain", "凝碧旧池头一听管弦凄切多少梨园声在总不堪华发杏花无处避春愁也傍野烟发惟有御沟声断似知人呜咽", "在凝碧池边，一听管弦就觉得凄切。梨园的旧曲还有多少在？总叫人受不了这满头白发。\n杏花无处躲避春愁，也只能靠着野烟开放。只有御沟的水声断绝，像知道人在呜咽。"],
    [132, "songci-sc-178", "public-domain", "绿树听鹈鴂更那堪鹧鸪声住杜鹃声切啼到春归无寻处苦恨芳菲都歇算未抵人间离别马上琵琶关塞黑更长门翠辇辞金阙看燕燕送归妾将军百战身名裂向河梁回头万里故人长绝易水萧萧西风冷满座衣冠似雪正壮士悲歌未彻啼鸟还知如许恨料不啼清泪长啼血谁共我醉明月", "在绿树间听鹈鴂啼叫。更哪堪鹧鸪声刚停，杜鹃又叫得凄切。啼到春天归去无处可寻，苦恨百花都歇了。算来还比不上人间的离别。昭君骑在马上弹琵琶，关塞昏黑；还有陈皇后乘翠辇辞别金阙。看燕子飞，送走远嫁的人。\n李陵将军百战之身落得身败名裂。在河梁上回头万里，与故人永诀。易水萧萧，西风冷，满座衣冠白如雪。正是壮士悲歌未终。啼鸟还知道这些恨，料想它不啼清泪而长啼血。谁来陪我，在明月下醉倒。"],
    [134, "songci-sc-184", "public-domain", "更能消几番风雨匆匆春又归去惜春长怕花开早何况落红无数春且住见说道天涯芳草无归路怨春不语算只有殷勤画檐蛛网尽日惹飞絮长门事准拟佳期又误蛾眉曾有人妒千金纵买相如赋脉脉此情谁诉君莫舞君不见玉环飞燕皆尘土闲愁最苦休去倚危阑斜阳正在烟柳断肠处", "还能经得几番风雨，春天又匆匆归去。惜春总怕花开得太早，何况落红无数。春天你且留下！听说天涯芳草，没有归路。怨春不语。算来只有画檐上的蛛网殷勤，整日粘着飞絮。\n长门宫的事，本预计好的佳期又被误了。美人总有人嫉妒。纵然花千金买来相如的赋，这脉脉情意向谁诉说？你不要舞！你没看见杨玉环、赵飞燕都成了尘土。闲愁最苦。不要去倚危栏，斜阳正照在烟柳断肠之处。"],
    [140, "songci-sc-187", "public-domain", "燕燕轻盈莺莺娇软分明又向华胥见夜长争得薄情知春初早被相思染别后书辞别时针线离魂暗逐郎行远淮南皓月冷千山冥冥归去无人管", "像燕子一样轻盈，像黄莺一样娇软，分明又在梦里相见。夜长怎么让薄情的人知道？春天刚开始就已被相思染上。\n别后的书信，别时的针线，离魂暗暗随着郎的行踪远去。淮南的皓月冷照千山，她幽幽地归去，无人照管。"],
    [141, "songci-sc-188", "public-domain", "庾郎先自吟愁赋凄凄更闻私语露湿铜铺苔侵石井都是曾听伊处哀音似诉正思妇无眠起寻机杼曲曲屏山夜凉独自甚情绪西窗又吹暗雨为谁频断续相和砧杵候馆迎秋离宫吊月别有伤心无数豳诗漫与笑篱落呼灯世间儿女写入琴丝一声声更苦", "庾信先自吟起愁赋，凄凄地又听见蟋蟀私语。露水湿了铜铺首，青苔侵上石井，都是曾听它鸣叫的地方。哀音像在诉说。正是思妇无法入睡，起身去找机杼。曲曲屏风，夜凉里独自是什么情绪？\n西窗又被暗雨吹打。它为谁频频断续，与砧杵相应和？候馆迎秋，离宫吊月，另有无数伤心。豳诗随意写成。可笑篱落间呼灯捉蟋蟀，那是世间的儿女。把它写入琴弦，一声声更苦。"],
    [142, "songci-sc-189", "public-domain", "双桨来时有人似旧曲桃根桃叶歌扇轻约飞花蛾眉正奇绝春渐远汀洲自绿更添了几声啼鴂十里扬州三生杜牧前事休说又还是宫烛分烟奈愁里匆匆换时节都把一襟芳思与空阶榆荚千万缕藏鸦细柳为玉尊起舞回雪想见西出阳关故人初别", "双桨划来，船上有人像旧曲里的桃根桃叶。歌扇轻轻约住飞花，蛾眉正奇绝。春天渐渐远了，汀洲自绿，又添了几声杜鹃啼。十里扬州，三生杜牧，前事不必再说！\n又还是宫中传烛分烟的时候，怎奈在愁里匆匆换了时节。把一襟芳思，都交给了空阶上的榆荚。千万缕可以藏鸦的细柳，为玉杯起舞，像回风旋雪。想见西出阳关时，故人初别的情景。"],
    [143, "songci-sc-191", "public-domain", "闹红一舸记来时尝与鸳鸯为侣三十六陂人未到水佩风裳无数翠叶吹凉玉容消酒更洒菰蒲雨嫣然摇动冷香飞上诗句日暮青盖亭亭情人不见争忍凌波去只恐舞衣寒易落愁入西风南浦高柳垂阴老鱼吹浪留我花间住田田多少几回沙际归路", "在喧闹的荷花中乘一舸，记得来时曾与鸳鸯为伴。三十六处池塘人迹未到，无数荷叶如水的佩、风的裳。翠叶吹出凉意，娇容消去酒意，又洒下一阵菰蒲的雨。它嫣然摇动，冷香飞上我的诗句。\n日暮，青色的荷叶亭亭而立，情人不见，怎忍心凌波而去？只恐舞衣遇寒容易零落，愁绪随着西风飘向南浦。高柳垂下绿荫，老鱼吹起波浪，留我在花间住下。田田的荷叶有多少，几次在沙岸边找归路。"],
    [144, "poems-gz11-19", "academic", "淮左名都竹西佳处解鞍少驻初程过春风十里尽荠麦青青自胡马窥江去后废池乔木犹厌言兵渐黄昏清角吹寒都在空城杜郎俊赏算而今重到须惊纵豆蔻词工青楼梦好难赋深情二十四桥仍在波心荡冷月无声念桥边红药年年知为谁生", "扬州是淮河东边著名的都会，在竹西亭这美好的去处，我解下马鞍稍作停留。走过当年春风十里的繁华街道，如今却长满了青青的荠菜和野麦。自从金兵进犯长江流域撤走以后，废弃的池塘、高大的树木，至今还厌恶谈论战争。渐渐到了黄昏，清冷的号角声在寒冷中吹响，回荡在这座空城里。杜牧曾经那样善于游赏，料想他如今重游此地也一定会感到吃惊。纵然他写「豆蔻」的词句精工，写「青楼」的美梦美好，也难以表达此刻深沉的感情。二十四桥依然还在，水波荡漾，冷月无声。遥想桥边的红芍药，年复一年，不知道是为谁开放？"],
    [145, "songci-sc-193", "public-domain", "渐吹尽枝头香絮是处人家绿深门户远浦萦回暮帆零乱向何许阅人多矣谁得似长亭树树若有情时不会得青青如此日暮望高城不见只见乱山无数韦郎去也怎忘得玉环分付第一是早早归来怕红萼无人为主算空有并刀难剪离愁千缕", "枝头的香絮渐渐吹尽，到处人家，绿荫深掩门户。远处江浦萦回，暮色中船帆零乱，要驶向哪里？长亭的树见过的人多了，谁能比得上它？树若是有情，就不会这样青青！\n日暮，望不见高城，只见乱山无数。韦郎一去，怎么忘得了她的嘱托：第一是早早归来，怕红花无人做主。算来空有利剪，也难剪断千缕离愁。"],
    [146, "songci-sc-194", "public-domain", "空城晓角吹入垂杨陌马上单衣寒恻恻看尽鹅黄嫩绿都是江南旧相识正岑寂明朝又寒食强携酒小桥宅怕梨花落尽成秋色燕燕飞来问春何在唯有池塘自碧", "空城清晨的号角声，吹进垂杨覆盖的街路。马上单衣，寒意恻恻。看尽鹅黄嫩绿，都是江南旧相识。\n正是岑寂，明天又是寒食。勉强带着酒，到她小桥边的住处。怕梨花落尽，就成了秋色。燕子飞来，问春天在哪里——只有池塘自碧。"],
    [147, "songci-sc-195", "public-domain", "旧时月色算几番照我梅边吹笛唤起玉人不管清寒与攀摘何逊而今渐老都忘却春风词笔但怪得竹外疏花香冷入瑶席江国正寂寂叹寄与路遥夜雪初积翠尊易泣红萼无言耿相忆长记曾携手处千树压西湖寒碧又片片吹尽也几时见得", "旧时的月色，算来几次照着我，在梅边吹笛？唤起玉人，不管清寒也要攀折。何逊如今渐渐老了，都忘了春风的词笔。只怪竹外那几枝疏花，冷香飘入瑶席。\n江南水乡，正是寂寂。可叹路远难寄，夜雪初积。翠杯容易惹泪，红萼无言，耿耿相忆。常记得曾携手的地方，千树梅花压着西湖的寒碧。又一片片吹尽了，什么时候才能再见？"],
    [148, "songci-sc-196", "public-domain", "苔枝缀玉有翠禽小小枝上同宿客里相逢篱角黄昏无言自倚修竹昭君不惯胡沙远但暗忆江南江北想佩环月夜归来化作此花幽独犹记深宫旧事那人正睡里飞近蛾绿莫似春风不管盈盈早与安排金屋还教一片随波去又却怨玉龙哀曲等恁时重觅幽香已入小窗横幅", "苔痕斑驳的枝上缀着玉一般的花，有小翠鸟在枝上同宿。客途中相逢，篱角黄昏，它无言地倚着修竹。昭君不惯胡地的风沙遥远，只暗暗思念江南江北。想她佩环叮咚、月夜归来，化作这枝幽独的花。\n还记得深宫旧事，那人正在睡梦中，梅花飞近她的蛾眉。不要像春风那样，不管它盈盈可爱，早该为它安排金屋。还教一片随波流去，却又怨玉笛的哀曲。等到那时再觅幽香，它已进了小窗上的横幅画里。"],
    [149, "songci-sc-197", "public-domain", "月冷龙沙尘清虎落今年汉酺初赐新翻胡部曲听毡幕元戎歌吹层楼高峙看槛曲萦红檐牙飞翠人姝丽粉香吹下夜寒风细此地宜有词仙拥素云黄鹤与君游戏玉梯凝望久叹芳草萋萋千里天涯情味仗酒祓清愁花销英气西山外晚来还卷一帘秋霁", "月色冷照着龙沙，尘埃扫清在虎落，今年朝廷初次赐酺。新翻的胡部乐曲，从毡幕里传出元戎的歌吹。层楼高高耸立。看栏杆回曲萦着红色，檐牙飞着翠色。人儿美丽，粉香从楼上吹下，夜寒风细。\n这地方，该有词仙，拥着素云黄鹤，与你同游。在玉梯上凝望久了，可叹芳草萋萋千里。天涯的滋味。只能靠酒来除清愁，靠花来销磨英气。西山之外，傍晚时又卷起一帘秋晴。"],
    [153, "songci-sc-198", "public-domain", "柳暗花明春事深小阑红芍药已抽簪雨余风软碎鸣禽迟迟日犹带一分阴往事莫沉吟身闲时序好且登临旧游无处不堪寻无寻处惟有少年心", "柳暗花明，春事已深；小栏杆边的红芍药已经抽出簪一样的花苞。雨后风软，鸣禽声碎；日头迟迟，还带着一分阴。\n往事不要沉吟；身闲时序又好，且去登临。旧游之处没有一处不能寻访，寻不到的，只有那颗少年心。"],
    [154, "songci-sc-199", "public-domain", "芦叶满汀洲寒沙带浅流二十年重过南楼柳下系船犹未稳能几日又中秋黄鹤断矶头故人曾到否旧江山浑是新愁欲买桂花同载酒终不似少年游", "芦叶长满汀洲，寒沙带着浅流。二十年后重过南楼。柳下系船还没系稳，能过几天，又到中秋。\n黄鹤矶头，故人来过没有？旧日江山全是新愁。想买桂花、载着酒同游，终究不像少年时那样了。"],
    [155, "songci-sc-200", "public-domain", "春风只在园西畔荠菜花繁蝴蝶乱冰池晴绿照还空香径落红吹已断意长翻恨游丝短尽日相思罗带缓宝奁明月不欺人明日归来君试看", "春风只在园子西边，荠菜花开得繁盛，蝴蝶纷乱。冰池晴日的绿光映照还是空的，香径上的落花已被吹尽。\n情意深长反倒恨游丝太短，整日相思，罗带都松了。梳妆镜的明月不骗人，明天你归来时试着看看。"],
    [160, "songci-sc-206", "public-domain", "月波疑滴望玉壶天近了无尘隔翠眼圈花冰丝织练黄道宝光相直自怜诗酒瘦难应接许多春色最无赖是随香趁烛曾伴狂客踪迹漫记忆老了杜郎忍听东风笛柳院灯疏梅厅雪在谁与细倾春碧旧情拘未定犹自学当年游历怕万一误玉人夜寒帘隙", "月波像要滴下，望那玉壶般的天空近在眼前，一点尘埃也没有。翠色的灯圈、冰丝织成的绢，与黄道宝光相照。自怜诗酒消磨得人瘦，难以应接这许多春色。最无赖的是随着香、趁着烛，曾经陪伴狂客。\n踪迹，空自记忆，杜郎已老，怎忍听东风的笛声。柳院灯光疏落，梅厅还有积雪，谁来为我细斟春酒？旧情拘束未定，还在学当年的游历。怕万一误了玉人，在夜寒的帘缝间等待。"],
    [161, "songci-sc-207", "public-domain", "烟光摇缥瓦望晴檐多风柳花如洒锦瑟横床想泪痕尘影凤弦常下倦出犀帷频梦见王孙骄马讳道相思偷理绡裙自惊腰衩惆怅南楼遥夜记翠箔张灯枕肩歌罢又入铜驼遍旧家门巷首询声价可惜东风将恨与闲花俱谢记取崔徽模样归来暗写", "烟光在青瓦上摇动，望晴日屋檐多风，柳花像洒下来。锦瑟横在床上，想那泪痕尘影，弦柱常常卸下。她懒得出犀帐，频频梦见王孙的骄马。讳言相思，偷偷整理绡裙，自己惊觉腰身瘦了。\n惆怅南楼的遥夜。记得翠帘张灯，枕肩歌罢。又来到铜驼街，走遍旧日的门巷，先打听她的声价。可惜东风，把恨与闲花一起吹谢。记住崔徽的模样，回来后暗暗描画。"],
    [162, "songci-sc-208", "public-domain", "江水苍苍望倦柳愁荷共感秋色废阁先凉古帘空暮雁程最嫌风力故园信息爱渠入眼南山碧念上国谁是脍鲈江汉未归客还又岁晚瘦骨临风夜闻秋声吹动岑寂露蛩悲清灯冷屋翻书愁上鬓毛白年少俊游浑断得但可怜处无奈冉冉魂惊采香南浦剪梅烟驿", "江水苍茫，望那倦柳愁荷，一同感到秋色。废阁先凉，旧帘空垂到暮色，雁飞的路最怕风力。故园的消息，爱它入眼的南山碧色。想京城里，谁是那想脍鲈鱼却未能归江汉的客？\n又到岁晚，瘦骨临风，夜里听秋声，吹动一片岑寂。露中蟋蟀悲鸣，清灯冷屋，翻书时愁得鬓毛都白了。年少的俊游全然断绝。只有可怜之处，无奈心魂冉冉惊动，在南浦采香，在烟驿剪梅。"],
    [163, "songci-sc-209", "public-domain", "柳锁莺魂花翻蝶梦自知愁染潘郎轻衫未揽犹将泪点偷藏念前事怯流光早春窥酥雨池塘向消凝里梅开半面情满徐妆风丝一寸柔肠曾在歌边惹恨烛底萦香芳机瑞锦如何未织鸳鸯人扶醉月依墙是当初谁敢疏狂把闲言语花房夜久各自思量", "柳锁住黄莺的魂，花翻起蝴蝶的梦，自己知道愁已染上潘岳那样的白发。轻衫还没穿好，还把泪点偷偷藏起。想从前的事，怕流光，早春窥看酥雨后的池塘。在消凝之中，梅花开了半面，情意满是徐妃的半妆。\n风丝一寸柔肠，曾经在歌边惹恨，在烛底萦香。芳机的瑞锦，怎么还没织出鸳鸯？有人扶醉，月亮靠着墙；当初谁敢这样疏狂！把那些闲言碎语，留在花房夜深时，各自思量。"],
    [165, "songci-sc-190", "public-domain", "芳莲坠粉疏桐吹绿庭院暗雨乍歇无端抱影销魂处还见筱墙萤暗藓阶蛩切送客重寻西去路问水面琵琶谁拨最可惜一片江山总付与啼鴂长恨相从未款而今何事又对西风离别渚寒烟淡棹移人远缥缈行舟如叶想文君望久倚竹愁生步罗袜归来后翠尊双饮下了珠帘玲珑闲看月", "芳莲坠落粉瓣，疏桐吹着绿叶，庭院里暗雨刚停。无端抱着影子消魂的地方，又看见竹墙上萤火暗淡，苔阶上蟋蟀声凄切。送客重寻西去的路，问水面上是谁在拨琵琶？最可惜一片江山，都交给了杜鹃啼。\n长恨相跟随从不能尽意，如今又为什么，对着西风离别？洲渚寒、烟雾淡，船移人远，缥缈的行舟像一片叶。想她久望，倚着竹子发愁，罗袜生尘。归来后，双饮翠杯，放下珠帘，悠闲地看玲珑的月。"],
    [167, "songci-sc-211", "public-domain", "湛湛长空黑更那堪斜风细雨乱愁如织老眼平生空四海赖有高楼百尺看浩荡千崖秋色白发书生神州泪尽凄凉不向牛山滴追往事去无迹少年自负凌云笔到而今春华落尽满怀萧瑟常恨世人新意少爱说南朝狂客把破帽年年拈出若对黄花孤负酒怕黄花也笑人岑寂鸿北去日西匿", "长空一片深黑。更哪堪斜风细雨，乱愁像织。我这双老眼平生空看四海，赖有百尺高楼。看那浩荡的千崖秋色。白发书生为神州落泪，尽管凄凉，也不像齐景公那样在牛山滴泪。追想往事，去无踪迹。\n少年时自负凌云之笔。到如今春花落尽，满怀萧瑟。常恨世人新意太少，爱说南朝的狂客，把破帽年年拈出来说。若对着菊花辜负了酒，怕菊花也要笑人寂寞。鸿雁北去，太阳西落。"],
    [169, "songci-sc-216", "public-domain", "绣幄鸳鸯柱红情密腻云低护秦树芳根兼倚花梢钿合锦屏人妒东风睡足交枝正梦枕瑶钗燕股障滟蜡满照欢丛嫠蟾冷落羞度人间万感幽单华清惯浴春盎风露连鬟并暖同心共结向承恩处凭谁为歌长恨暗殿锁秋灯夜语叙旧期不负春盟红朝翠暮", "绣帐上鸳鸯交柱，红情密处，浓云低低护着海棠。香根相依，花梢如钿盒相合，锦屏里的人见了也嫉妒。东风里睡足，枝条相交，正像枕上梦着瑶钗燕股。挡住滟滟的蜡烛，照着满丛的欢意，孤月冷落羞于照过。\n人间万种感慨都落在孤独上；华清池惯于沐浴，春意盎然的春风露水。双鬟并暖，同心共结，在那承恩的地方。靠谁来唱《长恨歌》？暗殿锁着，秋灯下夜语。叙述旧日的期约，不辜负春天的盟誓，红朝翠暮。"],
    [171, "songci-sc-215", "public-domain", "断烟离绪关心事斜阳红隐霜树半壶秋水荐黄花香噀西风雨纵玉勒轻飞迅羽凄凉谁吊荒台古记醉踏南屏彩扇咽寒蝉倦梦不知蛮素聊对旧节传杯尘笺蠹管断阕经岁慵赋小蟾斜影转东篱夜冷残蛩语早白发缘愁万缕惊飙从卷乌纱去漫细将茱萸看但约明年翠微高处", "断烟中一片离绪，最关心的事，是斜阳的红光隐在霜树里。半壶秋水供着黄花，香气喷向秋风秋雨。纵然策马轻飞如迅羽，凄凉中谁来凭吊荒台古迹？记得醉踏南屏，彩扇声中寒蝉凄咽，倦梦不知小蛮、樊素。\n姑且对着旧节传杯，尘封的信笺、生蠹的笔管，断了的词稿经年懒得再赋。小月斜影转过东篱，夜冷中残蟋蟀在叫。早已白了头，都因万缕愁。狂风且卷走乌纱帽。慢慢细看茱萸，只约定明年，在青山高处。"],
    [172, "songci-sc-216", "public-domain", "绣幄鸳鸯柱红情密腻云低护秦树芳根兼倚花梢钿合锦屏人妒东风睡足交枝正梦枕瑶钗燕股障滟蜡满照欢丛嫠蟾冷落羞度人间万感幽单华清惯浴春盎风露连鬟并暖同心共结向承恩处凭谁为歌长恨暗殿锁秋灯夜语叙旧期不负春盟红朝翠暮", "绣帐上鸳鸯交柱，红情密处，浓云低低护着海棠。香根相依，花梢如钿盒相合，锦屏里的人见了也嫉妒。东风里睡足，枝条相交，正像枕上梦着瑶钗燕股。挡住滟滟的蜡烛，照着满丛的欢意，孤月冷落羞于照过。\n人间万种感慨都落在孤独上；华清池惯于沐浴，春意盎然的春风露水。双鬟并暖，同心共结，在那承恩的地方。靠谁来唱《长恨歌》？暗殿锁着，秋灯下夜语。叙述旧日的期约，不辜负春天的盟誓，红朝翠暮。"],
    [173, "songci-sc-217", "public-domain", "烟波桃叶西陵路十年断魂潮尾古柳重攀轻鸥聚别陈迹危亭独倚凉飔乍起渺烟碛飞帆暮山横翠但有江花共临秋镜照憔悴华堂烛暗送客眼波回盼处芳艳流水素骨凝冰柔葱蘸雪犹忆分瓜深意清尊未洗梦不湿行云漫沾残泪可惜秋宵乱蛩疏雨里", "烟波中桃叶渡、西陵路，十年来魂断在潮尾。古柳再次攀折，轻鸥聚散，旧迹里独倚危亭。凉风忽起，烟碛上远帆缥缈，暮山横着翠色。只有江花，一同临着秋镜照我的憔悴。\n华堂烛暗送客，她眼波回盼的地方，芳艳如流水。素骨凝冰，柔指蘸雪，还记得分瓜时的深意。清酒杯还没洗，梦不能湿行云，只白沾残泪。可惜这秋宵，在乱蟋蟀和疏雨里。"],
    [174, "songci-sc-219", "public-domain", "门隔花深梦旧游夕阳无语燕归愁玉纤香动小帘钩落絮无声春堕泪行云有影月含羞东风临夜冷于秋", "门隔着深花，梦里回到旧游之处；夕阳无语，燕子归去带着愁。她的纤手带着香气，拨动小帘钩。\n落絮无声，是春天在落泪；行云有影，是月儿含羞。东风入夜，比秋天还冷。"],
    [175, "songci-sc-220", "public-domain", "卷尽愁云素娥临夜新梳洗暗尘不起酥润凌波地辇路重来仿佛灯前事情如水小楼熏被春梦笙歌里", "愁云卷尽，嫦娥在夜里刚梳洗过。暗尘不起，地面酥润，是她凌波走过的地方。\n重来御街，仿佛还是灯前旧事。情意如水；小楼里熏着被子，春梦在笙歌里。"],
    [176, "songci-sc-221", "public-domain", "剪红情裁绿意花信上钗股残日东风不放岁华去有人添烛西窗不眠侵晓笑声转新年莺语旧尊俎玉纤曾擘黄柑柔香系幽素归梦湖边还迷镜中路可怜千点吴霜寒销不尽又相对落梅如雨", "剪出红情，裁出绿意，花信插上钗股。残日东风，不肯放岁华归去。有人在西窗添烛，不睡到天明，笑声转为新年的莺语。\n旧日的酒席。她的纤手曾剖开黄柑，柔香系着幽素。归梦到湖边，还迷在镜般的路上。可怜千点吴地的霜，寒气销不尽，又相对看着落梅如雨。"],
    [177, "songci-sc-222", "public-domain", "听风听雨过清明愁草瘗花铭楼前绿暗分携路一丝柳一寸柔情料峭春寒中酒交加晓梦啼莺西园日日扫林亭依旧赏新晴黄蜂频扑秋千索有当时纤手香凝惆怅双鸳不到幽阶一夜苔生", "听着风、听着雨过了清明，愁闷中写下葬花的铭文。楼前绿荫暗暗，是分手时的路；一丝柳条，就是一寸柔情。料峭春寒里喝醉了酒，交加的晓梦被黄莺啼醒。\n西园天天打扫林亭，依旧去赏新晴。黄蜂频频扑着秋千索，那里有她当时纤手留下的香。惆怅那双鸳鸯鞋不再来，幽静的台阶一夜就生了青苔。"],
    [178, "songci-sc-223", "public-domain", "残寒正欺病酒掩沉香绣户燕来晚飞入西城似说春事迟暮画船载清明过却晴烟冉冉吴宫树念羁情游荡随风化为轻絮十载西湖傍柳系马趁娇尘软雾溯红渐招入仙溪锦儿偷寄幽素倚银屏春宽梦窄断红湿歌纨金缕暝堤空轻把斜阳总还鸥鹭幽兰旋老杜若还生水乡尚寄旅别后访六桥无信事往花委瘗玉埋香几番风雨长波妒盼遥山羞黛渔灯分影春江宿记当时短楫桃根渡青楼仿佛临分败壁题诗泪墨惨淡尘土危亭望极草色天涯叹鬓侵半苎暗点检离痕欢唾尚染鲛绡亸凤迷归破鸾慵舞殷勤待写书中长恨蓝霞辽海沉过雁漫相思弹入哀筝柱伤心千里江南怨曲重招断魂在否", "残寒正欺负病酒的人，我掩上沉香木的绣户。燕子来得晚，飞入西城，像在说春事已近迟暮。画船载着，清明已经过去了；晴烟冉冉，笼着吴宫的树。想那羁旅之情，随风游荡，化作轻絮。\n十年前在西湖，傍着柳树系马，趁着娇尘软雾。沿着花丛渐渐被招入仙溪，锦儿偷偷送来幽情。靠着银屏，春夜宽而梦短；断红打湿了歌扇金缕衣。暮色中堤上空空，轻轻把斜阳都还给了鸥鹭。\n幽兰转眼就老，杜若又生，我还在水乡寄旅。别后访遍六桥也没有消息，往事已去，花也凋萎；葬玉埋香，经过几番风雨。长波嫉妒她的眼波，远山羞于比她的眉黛。渔灯分影，曾在春江夜宿，记得当时短桨划向桃根渡。青楼仿佛还在，临别时在败壁上题诗，泪墨惨淡，已落满尘土。\n在高亭上极目远望，草色直到天涯，可叹鬓边已白了一半。暗暗点检旧物：离别的泪痕、欢笑的唾痕，还染在鲛绡上；凤钗斜垂，鸾镜残破懒得再舞。想殷勤写书，写尽长恨，可蓝天大海雁信沉没；只能白白相思，弹入哀筝的弦柱。伤心啊，千里江南；重唱怨曲招魂，那断了的魂还在吗？"],
    [181, "songci-sc-228", "public-domain", "润玉笼绡檀樱倚扇绣圈犹带脂香浅榴心空叠舞裙红艾枝应压愁鬟乱午梦千山窗阴一箭香瘢新褪红丝腕隔江人在雨声中晚风菰叶生秋怨", "润玉般的手腕笼着绡纱，檀红的樱桃小口靠着扇子。绣圈上还带着浅淡的脂香。石榴花心白白叠成舞裙的红，艾枝该压住了愁乱的鬓发。\n午梦里越过千山，窗下光阴只在一箭之间。红丝线般的手腕上香瘢刚褪。隔着江的人在雨声里，晚风吹着菰叶，生出秋怨。"],
    [182, "songci-sc-229", "public-domain", "晴丝牵绪乱对沧江斜日花飞人远垂杨暗吴苑正旗亭烟冷河桥风暖兰情蕙盼惹相思春根酒畔又争知吟骨萦销渐把旧衫重剪凄断流红千浪缺月孤楼总难留燕歌尘凝扇待凭信拌分钿试挑灯欲写还依不忍笺幅偷和泪卷寄残云剩雨蓬莱也应梦见", "晴丝牵得心绪纷乱。对着沧江斜日，花飞人远。垂杨暗暗遮住吴苑，正是旗亭烟冷、河桥风暖。兰样的情、蕙样的眼，惹起相思，在春根酒边。她又怎知，我因吟咏消瘦，渐渐要把旧衫重新裁剪。\n凄断。流红千重浪，缺月照着孤楼，总难留住燕子。歌尘凝在扇上。想凭书信，拼着分钿。试着挑亮灯要写，还是依恋不忍，偷偷把笺纸和泪卷起。寄到残云剩雨的蓬莱，她也该梦见。"],
    [183, "songci-sc-231", "public-domain", "人去西楼雁杳叙别梦扬州一觉云澹星疏楚山晓听啼乌立河桥话未了雨外蛩声早细织就霜丝多少说与萧娘未知道向长安对秋灯几人老", "人已离开西楼，雁信渺茫；叙别之梦，像扬州一觉。云淡星疏，楚山泛晓。听乌鸦啼叫，立在河桥上，话还没说完。\n雨外的蟋蟀叫得早，细细织成了多少霜丝般的白发？说给她听，她还不知道。向着长安，对着秋灯，有多少人就这样老了？"],
    [185, "songci-sc-199", "public-domain", "芦叶满汀洲寒沙带浅流二十年重过南楼柳下系船犹未稳能几日又中秋黄鹤断矶头故人曾到否旧江山浑是新愁欲买桂花同载酒终不似少年游", "芦叶长满汀洲，寒沙带着浅流。二十年后重过南楼。柳下系船还没系稳，能过几天，又到中秋。\n黄鹤矶头，故人来过没有？旧日江山全是新愁。想买桂花、载着酒同游，终究不像少年时那样了。"],
    [186, "songci-sc-232", "public-domain", "近清明翠禽枝上消魂可惜一片清歌都付与黄昏欲共柳花低诉怕柳花轻薄不解伤春念楚乡旅宿柔情别绪谁与温存空樽夜泣青山不语残月当门翠玉楼前惟是有一波湘水摇荡湘云天长梦短问甚时重见桃根这次第算人间没个并刀剪断心上愁痕", "将近清明，翠鸟在枝上叫得令人消魂。可惜一片清越的歌声，都交给了黄昏。想对着柳花低声诉说，又怕柳花轻薄，不懂伤春。想我在楚乡旅宿，柔情别绪，谁来温存？\n空杯在夜里像在哭泣，青山不语，残月当门。翠玉楼前，只有一波湘水，摇荡着湘云。天长梦短，问什么时候能重见桃根？这般情景，算来人间没有一把并州剪刀，能剪断心上的愁痕。"],
    [189, "songci-sc-184", "public-domain", "更能消几番风雨匆匆春又归去惜春长怕花开早何况落红无数春且住见说道天涯芳草无归路怨春不语算只有殷勤画檐蛛网尽日惹飞絮长门事准拟佳期又误蛾眉曾有人妒千金纵买相如赋脉脉此情谁诉君莫舞君不见玉环飞燕皆尘土闲愁最苦休去倚危阑斜阳正在烟柳断肠处", "还能经得几番风雨，春天又匆匆归去。惜春总怕花开得太早，何况落红无数。春天你且留下！听说天涯芳草，没有归路。怨春不语。算来只有画檐上的蛛网殷勤，整日粘着飞絮。\n长门宫的事，本预计好的佳期又被误了。美人总有人嫉妒。纵然花千金买来相如的赋，这脉脉情意向谁诉说？你不要舞！你没看见杨玉环、赵飞燕都成了尘土。闲愁最苦。不要去倚危栏，斜阳正照在烟柳断肠之处。"],
    [193, "songci-sc-236", "public-domain", "朱钿宝玦天上飞琼比人间春别江南江北曾未见漫拟梨云梅雪淮山春晚问谁识芳心高洁消几番花落花开老了玉关豪杰金壶剪送琼枝看一骑红尘香度瑶阙韶华正好应自喜初识长安蜂蝶杜郎老矣想旧事花须能说记少年一梦扬州二十四桥明月", "红钿宝玦，天上飞下的琼花，与人间的春色不同。江南江北，未曾见过，只能空比作梨云梅雪。淮山春暮，问谁能懂得它芳心的高洁？经过几番花开花落，玉关的豪杰也老了。\n用金壶剪送琼枝，看一骑红尘，香气度入瑶阙。韶华正好，该自喜初次认识长安的蜂蝶。杜郎已老，想旧事，花应该还能说。记得少年时一梦扬州，二十四桥的明月。"],
    [194, "songci-sc-237", "public-domain", "烟水阔高林弄残照晚蜩凄切碧砧度韵银床飘叶衣湿桐阴露冷采凉花时赋秋雪叹轻别一襟幽事砌蛩能说客思吟商还怯怨歌长琼壶暗缺翠扇恩疏红衣香褪翻成消歇玉骨西风恨最恨闲却新凉时节楚箫咽谁寄西楼淡月", "烟水空阔。高林摆弄着残照，晚蝉叫声凄切。碧绿的捣衣声传来韵味，井栏上飘下落叶。桐荫里露冷水湿衣裳，采着凉花，不时咏叹秋雪。可叹轻易离别，一襟幽事，只有台阶下的蟋蟀能说。\n客愁吟起商调还觉胆怯。怨歌悠长，玉壶暗暗敲缺。翠扇的恩情疏了，红衣的香气褪了，反而成了消歇。玉骨迎着西风，最恨的是白白荒废了新凉的时节。楚箫呜咽，谁寄西楼那淡月。"],
    [195, "songci-sc-238", "public-domain", "禁苑东风外飏暖丝晴絮春思如织燕约莺期恼芳情偏在翠深红隙漠漠香尘隔沸十里乱弦丛笛看画船尽入西泠闲却半湖春色柳陌新烟凝碧映帘底宫眉堤上游勒轻暝笼寒怕梨云梦冷杏香愁幂歌管酬寒食奈蝶怨良宵岑寂正满湖碎月摇花怎生去得", "宫苑东风之外，暖风扬起游丝晴絮，春思像织。燕子黄莺的约会，恼人的芳情偏偏在翠绿深处、红花缝里。漠漠香尘隔断。十里内沸腾着乱弦丛笛。看画船都驶入西泠，把半湖春色空了出来。\n柳陌上，新烟凝着碧色。映着帘下的宫样眉，堤上游人的马络头。轻暮笼着寒意，怕梨云梦冷、杏香愁浓。歌管酬答寒食。怎奈蝴蝶怨良宵岑寂。正当满湖碎月摇花，怎么舍得离去？"],
    [196, "songci-sc-239", "public-domain", "楚江湄湘娥乍见无言洒清泪淡然春意空独倚东风芳思谁寄凌波路冷秋无际香云随步起谩记得汉宫仙掌亭亭明月底冰弦写怨更多情骚人恨枉赋芳兰幽芷春思远谁叹赏国香风味相将共岁寒伴侣小窗净沉烟熏翠袂幽梦觉涓涓清露一枝灯影里", "楚江边上，湘妃忽然相见，无言地洒下清泪。淡然的春意。空自独倚东风，芳心寄给谁？凌波之路清冷，秋意无边；香云随着脚步升起。白白记得汉宫的仙掌，亭亭立在明月底下。\n冰弦写怨更多情，骚人的恨，白白赋写芳兰幽芷。春思遥远，谁来叹赏这国色的风味？要结为岁寒的伴侣，小窗洁净，沉香熏着翠袖。幽梦醒来，涓涓清露，一枝花在灯影里。"],
    [198, "songci-sc-241", "public-domain", "孤峤蟠烟层涛蜕月骊宫夜采铅水汛远槎风梦深薇露化作断魂心字红瓷候火还乍识冰环玉指一缕萦帘翠影依稀海天云气几回殢娇半醉剪春灯夜寒花碎更好故溪飞雪小窗深闭荀令如今顿老总忘却尊前旧风味谩惜余薰空篝素被", "孤岛上烟雾盘旋，层层波涛退出月光，骊宫夜里采来铅水。远汛的槎风，深梦里蔷薇露水，化做断魂的心字香。红瓷守着火候，才初次认识冰环玉指。一缕香萦绕帘上的翠影，依稀是海天的云气。\n几回她娇困半醉，剪着春灯，夜寒里灯花碎落。更好的是故溪飞雪，小窗深深关闭。荀令如今忽然老了，都忘了杯前旧日的风味。白白怜惜余香，空着香笼和素被。"],
    [203, "songci-sc-253", "public-domain", "薄雾浓云愁永昼瑞脑消金兽佳节又重阳玉枕纱厨半夜凉初透东篱把酒黄昏后有暗香盈袖莫道不销魂帘卷西风人比黄花瘦", "薄雾浓云，整日发愁；龙脑香在铜兽香炉里渐渐烧尽。又到重阳佳节，玉枕纱帐，半夜里凉意初透。\n黄昏后在东篱下举杯，有暗香盈袖。不要说不会消魂——西风卷起帘子，人比菊花还瘦。"],
    [204, "poems-gz10-09", "academic", "寻寻觅觅冷冷清清凄凄惨惨戚戚乍暖还寒时候最难将息三杯两盏淡酒怎敌他晚来风急雁过也正伤心却是旧时相识满地黄花堆积憔悴损如今有谁堪摘守着窗儿独自怎生得黑梧桐更兼细雨到黄昏点点滴滴这次第怎一个愁字了得", "苦苦地寻找寻觅，四处冷冷清清，心中凄凄惨惨悲悲戚戚。天气忽暖忽冷的时候，最难调养身体。三杯两盏淡酒，怎么能抵挡傍晚的急风！大雁飞过，正令人伤心，却原来是旧时相识。满地菊花堆积，我如此憔悴，如今有谁还能采摘？守着窗子，独自一个人怎么才能挨到天黑！梧桐树又加上细雨，到黄昏时分，点点滴滴。这情景，一个愁字怎么能说得尽！"],
    [205, "songci-sc-250", "public-domain", "萧条庭院又斜风细雨重门须闭宠柳娇花寒食近种种恼人天气险韵诗成扶头酒醒别是闲滋味征鸿过尽万千心事难寄楼上几日春寒帘垂四面玉阑干慵倚被冷香消新梦觉不许愁人不起清露晨流新桐初引多少游春意日高烟敛更看今日晴未", "庭院萧条，又是斜风细雨，重门该关上了。宠柳娇花，寒食将近，种种恼人的天气。险韵的诗写成，扶头的酒醒来，另有一番闲滋味。征鸿过尽，万千心事难以寄去。\n楼上几日春寒，四面垂帘，玉栏杆也懒得去倚。被子冷了、香气消了，新梦醒来，不许愁人不起身。清露在晨光里流，新桐刚抽芽，有多少游春的意兴！太阳升高、雾气收敛，再看看今天晴不晴？"],
    [206, "songci-sc-251", "public-domain", "落日熔金暮云合璧人在何处染柳烟浓吹梅笛怨春意知几许元宵佳节融和天气次第岂无风雨来相召香车宝马谢他酒朋诗侣中州盛日闺门多暇记得偏重三五铺翠冠儿捻金雪柳簇带争济楚如今憔悴风鬟霜鬓怕见夜间出去不如向帘儿底下听人笑语", "落日像熔化的金子，暮云如合拢的璧玉，人在哪里？柳色被浓烟染过，笛声吹着《梅花落》的怨曲，春意能有多少？元宵佳节，天气融和，难道就不会有风雨？有人用香车宝马来相邀，我谢绝了酒朋诗侣。\n中州盛时的日子，闺中多有闲暇，记得特别看重正月十五。铺翠的冠儿、捻金的雪柳，簇带争着齐整。如今憔悴，风鬟霜鬓，怕在夜里出去。不如守在帘子底下，听别人笑语。"]
    ],
    gwgz: [
    [1, "guwen-gwj-1", "public-domain", "初郑武公娶于申曰武姜生庄公及共叔段庄公寤生惊姜氏故名曰「寤生」遂恶之爱共叔段欲立之亟请于武公公弗许及庄公即位为之请制公曰「制岩邑也虢叔死焉佗邑唯命」请京使居之谓之京城大叔祭仲曰「都城过百雉国之害也先王之制大都不过参国之一中五之一小九之一今京不度非制也君将不堪」公曰「姜氏欲之焉辟害」对曰「姜氏何厌之有不如早为之所无使滋蔓蔓难图也蔓草犹不可除况君之宠弟乎」公曰「多行不义必自毙子姑待之」既而大叔命西鄙北鄙贰于己公子吕曰「国不堪贰君将若之何欲与大叔臣请事之若弗与则请除之无生民心」公曰「无庸将自及」大叔又收贰以为己邑至于廪延子封曰「可矣厚将得众」公曰「不义不昵厚将崩」大叔完聚缮甲兵具卒乘将袭郑夫人将启之公闻其期曰「可矣」命子封帅车二百乘以伐京京叛大叔段段入于鄢公伐诸鄢五月辛丑大叔出奔共书曰「郑伯克段于鄢」段不弟故不言弟如二君故曰克称郑伯讥失教也谓之郑志不言出奔难之也遂寘姜氏于城颍而誓之曰「不及黄泉无相见也」既而悔之颍考叔为颍谷封人闻之有献于公公赐之食食舍肉公问之对曰「小人有母皆尝小人之食矣未尝君之羹请以遗之」公曰「尔有母遗繄我独无」颍考叔曰「敢问何谓也」公语之故且告之悔对曰「君何患焉若阙地及泉隧而相见其谁曰不然」公从之公入而赋「大隧之中其乐也融融」姜出而赋「大隧之外其乐也泄泄」遂为母子如初君子曰「颍考叔纯孝也爱其母施及庄公诗曰『孝子不匮永锡尔类』其是之谓乎」", "当初，郑武公从申国娶了妻子，名叫武姜。她生了庄公和共叔段。庄公是倒着生下来的，惊了姜氏，所以取名「寤生」，姜氏因此讨厌他。她偏爱共叔段，想立他为太子，多次向武公请求，武公没有答应。\n到庄公即位后，姜氏替共叔段请求把制地封给他。庄公说：「制是险要的地方，虢叔就死在那里。别的城邑，唯命是从。」姜氏又请求京城，庄公让共叔段住在那里，人们称他为京城太叔。\n祭仲说：「都邑的城墙超过三百丈，是国家的祸害。先王的制度：大城不超过国都的三分之一，中等的不超过五分之一，小的不超过九分之一。如今京城的规模不合制度，您将受不了。」庄公说：「姜氏要这样，怎能避开祸害？」祭仲答道：「姜氏哪里会满足？不如早点安排他，别让祸患蔓延。一蔓延就难对付了。野草蔓延尚且难以清除，何况您受宠的弟弟呢？」庄公说：「多做不义的事，必定自取灭亡。你暂且等着看。」\n不久太叔命令西部和北部的边邑也听命于自己。公子吕说：「国家不能有两个君主，您打算怎么办？要把君位让给太叔，我就去侍奉他；如果不给，就请除掉他，别让百姓生二心。」庄公说：「不必，他会自食其果。」\n太叔又把两属的地方收作自己的城邑，一直扩展到廪延。子封说：「可以动手了，他的地盘大了就会得到更多人心。」庄公说：「对君不义、对兄不亲，地盘大了也会崩溃。」\n太叔修治城郭、聚集百姓，整治铠甲兵器，备好步兵战车，准备偷袭郑国国都。姜氏将为他打开城门。庄公得知了他动手的日期，说：「可以了！」命子封率领战车二百乘去攻打京城。京城的人背叛了太叔段，段逃到鄢地。庄公又攻打鄢。五月辛丑日，太叔逃奔到共国。\n《春秋》记作「郑伯克段于鄢」：段不守弟弟的本分，所以不说「弟」；如同两个国君相争，所以用「克」；称「郑伯」，是讥讽他没有尽到教诲之责；说这是郑伯的本意，不写段「出奔」，是因为难以措辞。\n于是庄公把姜氏安置在城颍，并对她发誓说：「不到黄泉，不再相见！」不久又后悔了。\n颍考叔是颍谷管理疆界的官，听说了这件事，就献给庄公一些礼物。庄公赐他吃饭。他吃的时候把肉留下。庄公问他为什么，他答道：「小人有母亲，小人的食物她都尝过，只是没有尝过您赏的肉羹。请让我带回去给她。」庄公说：「你有母亲可以送，我偏偏没有！」颍考叔说：「敢问这是什么意思？」庄公把缘故告诉他，并说自己后悔了。颍考叔答道：「您忧虑什么呢？如果挖地挖到泉水，在隧道里相见，谁会说不行呢？」庄公听从了。庄公进入隧道赋诗：「大隧之中，其乐也融融。」姜氏出来赋诗：「大隧之外，其乐也泄泄。」于是母子像当初一样。\n君子说：「颍考叔是纯正的孝子。爱他的母亲，又推及庄公。《诗经》说：『孝子的孝心没有穷尽，永远赐给你的同类。』说的就是这样的事吧！」"],
    [2, "guwen-gwj-2", "public-domain", "郑武公庄公为平王卿士王贰于虢郑伯怨王王曰「无之」故周郑交质王子狐为质于郑郑公子忽为质于周王崩周人将畀虢公政四月郑祭足帅师取温之麦秋又取成周之禾周郑交恶君子曰「信不由中质无益也明恕而行要之以礼虽无有质谁能间之苟有明信涧溪沼沚之毛苹蘩蕴藻之菜筐筥锜釜之器潢汙行潦之水可荐于鬼神可羞于王公而况君子结二国之信行之以礼又焉用质风有采蘩采苹雅有行苇泂酌昭忠信也」", "郑武公、庄公父子相继做周平王的卿士。平王想把一部分权力分给西虢公，郑庄公因此怨恨平王。平王说：「没有这回事。」于是周王室与郑国交换人质：王子狐到郑国做人质，郑公子忽到周王室做人质。\n平王去世后，周王室打算把政权交给西虢公。四月，郑国的祭足领兵割取温地的麦子。秋天，又割取成周的谷子。周王室与郑国从此互相结怨。\n君子说：「信用若不发自内心，交换人质也没有用。如果能明白、体谅地行事，用礼来约束，即使没有人质，谁能离间他们呢？倘若有光明正大的信用，山涧溪流、池塘水洼边的野草，苹、蘩、蕴、藻一类的野菜，方筐圆筥、有足无足的鼎器，积水与路上的流水，都可以进献给鬼神，可以进奉给王公，何况君子缔结两国的信义，依礼而行，又哪里用得着人质？《诗经》国风里有《采蘩》《采苹》，大雅里有《行苇》《泂酌》，都是为了表明忠信啊。」"],
    [3, "guwen-gwj-3", "public-domain", "卫庄公娶于齐东宫得臣之妹曰庄姜美而无子卫人所为赋硕人也又娶于陈曰厉妫生孝伯蚤死其娣戴妫生桓公庄姜以为己子公子州吁嬖人之子也有宠而好兵公弗禁庄姜恶之石碏谏曰「臣闻爱子教之以义方弗纳于邪骄奢淫泆所自邪也四者之来宠禄过也将立州吁乃定之矣若犹未也阶之为祸夫宠而不骄骄而能降降而不憾憾而能眕者鲜矣且夫贱妨贵少陵长远间亲新间旧小加大淫破义所谓六逆也君义臣行父慈子孝兄爱弟敬所谓六顺也去顺效逆所以速祸也君人者将祸是务去而速之无乃不可乎」弗听其子厚与州吁游禁之不可桓公立乃老", "卫庄公从齐国娶了太子得臣的妹妹，名叫庄姜。庄姜容貌美丽却没有儿子，卫国人因此为她作了《硕人》这首诗。庄公又从陈国娶了妻子，名叫厉妫，生下孝伯，孝伯很早就死了。厉妫的妹妹戴妫生下桓公，庄姜把桓公当作自己的儿子。公子州吁是庄公宠妾的儿子，受到宠爱又喜好武事，庄公不加禁止，庄姜厌恶他。\n石碏劝谏说：「我听说爱护儿子，要用道义规矩来教导他，不让他走上邪路。骄傲、奢侈、纵欲、放荡，正是走上邪路的由来。这四种毛病的产生，都是因为宠爱和俸禄太过分。如果打算立州吁为太子，就赶快定下来；如果还没有决定，就会埋下他作乱的根子。受宠爱而不骄傲，骄傲而能安于地位下降，地位下降而不怨恨，怨恨而能克制自重，这样的人太少了。况且卑贱的妨害尊贵的，年少的欺凌年长的，疏远的离间亲近的，新宠的离间旧人，小国欺压大国，淫邪破坏道义，这是所谓六种违背常理的事。国君行事合宜，臣下奉行，父亲慈爱，儿子孝顺，兄长友爱，弟弟恭敬，这是所谓六种顺理的事。抛弃顺理而效法背理，这是招致祸患的做法。做百姓君主的人，应当努力除掉祸患，如今却加速它的到来，恐怕不可以吧？」庄公不听。石碏的儿子石厚与州吁交往，石碏禁止他，没有禁住。桓公即位后，石碏就告老退休了。"],
    [4, "guwen-gwj-4", "public-domain", "春公将如棠观鱼者臧僖伯谏曰「凡物不足以讲大事其材不足以备器用则君不举焉君将纳民于轨物者也故讲事以度轨量谓之轨取材以章物采谓之物不轨不物谓之乱政乱政亟行所以败也故春蒐夏苗秋狝冬狩皆于农隙以讲事也三年而治兵入而振旅归而饮至以数军实昭文章明贵贱辨等列顺少长习威仪也鸟兽之肉不登于俎皮革齿牙骨角毛羽不登于器则君不射古之制也若夫山林川泽之实器用之资皂隶之事官司之守非君所及也」公曰「吾将略地焉」遂往陈鱼而观之僖伯称疾不从书曰「公矢鱼于棠」非礼也且言远地也", "春天，隐公准备到棠地观看捕鱼。臧僖伯劝谏说：「凡是物品不能用来讲习祭祀和军事这样的大事，它的材料不能用来制作礼器和兵器的，君主就不该去动它。君主是要把百姓纳入法度与礼制中的人。所以讲习大事以衡量法度叫做『轨』，选取材料以彰明器物文采叫做『物』。不合乎轨、物，就叫做乱政。乱政屡次施行，就是败亡的原因。因此春蒐、夏苗、秋狝、冬狩这四种打猎的仪式，都是在农闲时讲习大事。每三年演习一次军事，进入国都就整顿军队，回来后祭祀告庙饮酒，清点军用器物。这是为了彰明文采，表明贵贱，辨别等级，理顺长幼，熟悉威仪。鸟兽的肉不摆上祭器，皮革、齿牙、骨角、毛羽不用到礼器上，君主就不射它，这是自古以来的制度。至于山林川泽的物产，一般器用的材料，那是差役们的事，官吏的职责，不是君主所该管的。」\n隐公说：「我是要去巡视边境。」于是前往，让人陈列捕鱼的器具来观看，僖伯称病没有随行。《春秋》记作：「公矢鱼于棠。」这是指责隐公不合礼法，并且说他跑到远地去了。"],
    [5, "guwen-gwj-5", "public-domain", "郑伯将伐许五月甲辰授兵于大宫公孙阏与颍考叔争车颍考叔挟辀以走子都拔棘以逐之及大逵弗及子都怒秋七月公会齐侯郑伯伐许庚辰傅于许颍考叔取郑伯之旗蝥弧以先登子都自下射之颠瑕叔盈又以蝥弧登周麾而呼曰「君登矣」郑师毕登壬午遂入许许庄公奔卫齐侯以许让公公曰「君谓许不共故从君讨之许既伏其罪矣虽君有命寡人弗敢与闻」乃与郑人郑伯使许大夫百里奉许叔以居许东偏曰「天祸许国鬼神实不逞于许君而假手于我寡人寡人唯是一二父兄不能共亿其敢以许自为功乎寡人有弟不能和协而使糊其口于四方其况能久有许乎吾子其奉许叔以抚柔此民也吾将使获也佐吾子若寡人得没于地天其以礼悔祸于许无宁兹许公复奉其社稷唯我郑国之有请谒焉如旧昏媾其能降以相从也无滋他族实逼处此以与我郑国争此土也吾子孙其覆亡之不暇而况能禋祀许乎寡人之使吾子处此不唯许国之为亦聊以固吾圉也」乃使公孙获处许西偏曰「凡而器用财贿无置于许我死乃亟去之吾先君新邑于此王室而既卑矣周之子孙日失其序夫许大岳之胤也天而既厌周德矣吾其能与许争乎」君子谓「郑庄公于是乎有礼礼经国家定社稷序人民利后嗣者也许无刑而伐之服而舍之度德而处之量力而行之相时而动无累后人可谓知礼矣」", "郑庄公准备攻打许国。五月甲辰日，在祖庙里分发兵器。公孙阏与颍考叔争夺兵车，颍考叔挟起车辕就跑，子都拔出戟去追他，追到大路上也没有追上，子都因此怀恨。\n秋天七月，隐公会同齐侯、郑伯攻打许国。庚辰日，军队逼近许国都城。颍考叔拿着郑伯的旗帜「蝥弧」抢先登城，子都从下面射他，颍考叔摔了下来。瑕叔盈又举着「蝥弧」登城，向四面挥旗喊道：「国君登城了！」郑国军队全部登上城墙。壬午日，于是攻入许国。许庄公逃奔卫国。\n齐侯把许国让给隐公。隐公说：「您说许国不恭敬，所以我随您讨伐它。许国既已认罪，虽然您有命令，我也不敢过问。」于是把许国给了郑国。\n郑庄公派许国大夫百里奉许叔住在许国东部边境，说：「上天降祸给许国，鬼神确实对许君不满，借我的手来惩罚他。我连一两个父兄都不能和睦相处，岂敢把讨伐许国当作自己的功劳？我有个弟弟，不能和睦，让他四处糊口，何况能长久占有许国呢？您就奉许叔来安抚这里的百姓吧，我派公孙获来帮助您。如果我得以善终，上天或许会依礼撤回对许国的惩罚，让许公重新主持他的国家。那时如果我们郑国有所请求，如同旧日的婚姻之国一样，希望许国能委屈相从。不要让别的族类逼近这里居住，来同我们郑国争夺这块土地。我的子孙连挽救自己的危亡都来不及，哪里还能祭祀许国的山川呢？我让您留在这里，不只是为了许国，也是暂且借此巩固我的边境。」于是派公孙获住在许国西部边境，说：「凡是你的器用财宝，不要放在许国。我死后，你就赶快离开。我的先君在这里新建城邑，周王室已经衰微，周室子孙一天天失去应有的地位。许国，是太岳的后代。上天既已厌弃周朝的德行，我们哪里还能同许国相争呢？」\n君子说：「郑庄公在这件事上是合乎礼的。礼，是用来治理国家、安定社稷、使百姓有序、有利于后代的。许国不守法度就讨伐它，服罪了就赦免它，衡量德行来处置，估量力量来行事，看准时机再行动，不给后人留下祸患，可以说是懂得礼了。」"],
    [6, "guwen-gwj-6", "public-domain", "夏四月取郜大鼎于宋戊申纳于大庙非礼也臧哀伯谏曰「君人者将昭德塞违以临照百官犹惧或失之故昭令德以示子孙是以清庙茅屋大路越席大羹不致粢食不凿昭其俭也衮冕黻珽带裳幅舄衡紞纮綖昭其度也藻率鞞鞛鞶厉游缨昭其数也火龙黼黻昭其文也五色比象昭其物也钖鸾和铃昭其声也三辰旂旗昭其明也夫德俭而有度登降有数文物以纪之声明以发之以临照百官百官于是乎戒惧而不敢易纪律」「今灭德立违而寘其赂器于大庙以明示百官百官象之其又何诛焉国家之败由官邪也官之失德宠赂章也郜鼎在庙章孰甚焉武王克商迁九鼎于雒邑义士犹或非之而况将昭违乱之赂器于大庙其若之何」公不听周内史闻之曰「臧孙达其有后于鲁乎君违不忘谏之以德」", "夏天四月，桓公从宋国取得郜国的大鼎。戊申日，把它安放在太庙里。这是不合礼的。\n臧哀伯劝谏说：「做人民君主的人，应当昭明德行、阻塞邪恶，来给百官做榜样，还怕有所失误，所以要宣扬美德来垂示子孙。因此太庙用茅草盖顶，祭祀用车用蒲草席铺垫，肉汁不加调味，主食不精细舂治，这是为了昭明节俭。礼服、礼帽、蔽膝、玉笏，腰带、下裳、绑腿、鞋子，冠上的衡、紞、纮、綖，这是为了昭明制度。垫玉的木板、佩巾、刀鞘、刀饰，大带、带饰、旌旗的飘带、马颈上的缨络，这是为了昭明数量。火焰、游龙、斧形、亚形花纹，这是为了昭明文饰。五色绘成各种物象，这是为了昭明器物。马额上的钖、车上的鸾、车前的和、旗上的铃，这是为了昭明声音。画着日月星的旌旗，这是为了昭明光明。所谓德行，就是节俭而有制度，增减而有定数，用文饰和器物来记录它，用声音和光彩来显扬它，以此照临百官。百官因此戒惧，而不敢轻慢纲纪。\n「如今却要泯灭德行、树立邪恶，把别国贿赂来的器物放在太庙里，明确地展示给百官看。百官若照着做，又怎么能责罚他们呢？国家的败亡，是由官吏的邪恶引起的。官吏丧失德行，是由于受宠和贿赂公然横行。郜鼎放在太庙里，还有比这更公然的吗？周武王战胜商朝，把九鼎迁到雒邑，义士尚且有人非议，何况把显示邪恶悖乱的贿赂之器放在太庙里，那该怎么办呢？」\n桓公不听。周朝的内史听说了这件事，说：「臧孙达在鲁国一定会后继有人吧！国君违背礼法，他仍不忘用德行来劝谏。」"],
    [7, "guwen-gwj-7", "public-domain", "楚武王侵随使薳章求成焉军于瑕以待之随人使少师董成斗伯比言于楚子曰「吾不得志于汉东也我则使然我张吾三军而被吾甲兵以武临之彼则惧而协以谋我故难间也汉东之国随为大随张必弃小国小国离楚之利也少师侈请羸师以张之」熊率且比曰「季梁在何益」斗伯比曰「以为后图少师得其君」王毁军而纳少师少师归请追楚师随侯将许之季梁止之曰「天方授楚楚之羸其诱我也君何急焉臣闻小之能敌大也小道大淫所谓道忠于民而信于神也上思利民忠也祝史正辞信也今民馁而君逞欲祝史矫举以祭臣不知其可也」公曰「吾牲牷肥腯粢盛丰备何则不信」对曰「夫民神之主也是以圣王先成民而后致力于神故奉牲以告曰『博硕肥腯』谓民力之普存也谓其畜之硕大蕃滋也谓其不疾瘯蠡也谓其备腯咸有也奉盛以告曰『洁粢丰盛』谓其三时不害而民和年丰也奉酒醴以告曰『嘉栗旨酒』谓其上下皆有嘉德而无违心也所谓馨香无谗慝也故务其三时修其五教亲其九族以致其禋祀于是乎民和而神降之福故动则有成今民各有心而鬼神乏主君虽独丰其何福之有君姑修政而亲兄弟之国庶免于难」随侯惧而修政楚不敢伐", "楚武王侵犯随国，先派薳章去请求讲和，军队驻扎在瑕地等待结果。随国派少师主持和谈。\n斗伯比对楚武王说：「我们在汉水以东不能得志，是我们自己造成的。我们扩张三军、披挂甲兵，用武力去威胁他们，他们害怕，就联合起来对付我们，所以难以离间。汉水以东的国家，以随国最大。随国若自高自大，必定抛弃小国。小国离心，是楚国的利益。少师这个人骄傲自大，请让我们把军队装成疲弱的样子来助长他的傲气。」熊率且比说：「有季梁在，有什么用？」斗伯比说：「这是为以后打算，少师会得到随侯的信任。」武王于是故意毁损军容来接待少师。\n少师回去后，请求追击楚军。随侯准备答应。季梁劝阻说：「上天正把好运授予楚国，楚军的疲弱，是在诱骗我们，您急什么呢？我听说小国能抵挡大国，是因为小国有道而大国淫乱。所谓道，就是对百姓忠心、对神灵诚信。国君思念着有利于百姓，就是忠；祝史祭祀时言辞真实，就是信。如今百姓饥饿而国君放纵私欲，祝史虚报功德来祭祀，我不知道这样怎么行。」随侯说：「我祭祀用的牲口毛色纯正、膘肥体壮，黍稷丰盛完备，为什么不能取信于神？」季梁答道：「百姓是神灵的主人。因此圣明的君主先成就百姓的事，然后才致力于神。所以奉献牲口时祝告说『牲口又大又肥』，是说百姓的财力普遍充裕，是说牲畜肥大繁殖，是说没有病疫，是说各种牲口都齐备肥壮；奉献黍稷时祝告说『洁净的黍稷丰盛』，是说春夏秋三季没有灾害而百姓和睦、年成丰收；奉献甜酒时祝告说『美酒甘甜』，是说上下都有美好的德行而没有背离之心。所谓芳香远闻，是说没有谗言邪念。所以专心办好农时，修明五教，亲睦九族，然后才献上祭祀。于是百姓和睦而神灵降福，所以行动就有成效。如今百姓各有异心，鬼神没有主人，国君虽然独自丰足，又能有什么福气呢？您暂且修明政事，亲近兄弟国家，也许可以免于祸难。」\n随侯害怕，因而修明政事，楚国不敢来攻打。"],
    [8, "guwen-gwj-8", "public-domain", "十年春齐师伐我公将战曹刿请见其乡人曰「肉食者谋之又何间焉」刿曰「肉食者鄙未能远谋」乃入见问「何以战」公曰「衣食所安弗敢专也必以分人」对曰「小惠未遍民弗从也」公曰「牺牲玉帛弗敢加也必以信」对曰「小信未孚神弗福也」公曰「小大之狱虽不能察必以情」对曰「忠之属也可以一战战则请从」公与之乘战于长勺公将鼓之刿曰「未可」齐人三鼓刿曰「可矣」齐师败绩公将驰之刿曰「未可」下视其辙登轼而望之曰「可矣」遂逐齐师既克公问其故对曰「夫战勇气也一鼓作气再而衰三而竭彼竭我盈故克之夫大国难测也惧有伏焉吾视其辙乱望其旗靡故逐之」", "鲁庄公十年的春天，齐国的军队攻打鲁国。庄公准备迎战，曹刿请求进见。他的同乡人说：「当权的人自会谋划，你又何必参与？」曹刿说：「当权的人目光短浅，不能深谋远虑。」于是入宫进见。\n曹刿问：「凭什么作战？」庄公说：「衣食这类养人的东西，我不敢独自享用，一定分给别人。」曹刿答道：「小恩小惠不能遍及百姓，百姓不会跟从您。」庄公说：「祭祀用的牲口玉帛，我不敢虚报，一定诚实守信。」曹刿答道：「小信用不能使人信服，神不会保佑您。」庄公说：「大大小小的案件，虽不能一一明察，也一定按实情处理。」曹刿答道：「这是尽职于民的一类事，可以凭借它一战。作战时请让我跟随。」\n庄公与他同乘一辆战车，在长勺交战。庄公将要击鼓进军。曹刿说：「还不行。」齐军三次击鼓。曹刿说：「可以了。」齐军大败。庄公将要追击。曹刿说：「还不行。」他下车察看齐军的车辙，登上车前横木远望，说：「可以了。」于是追击齐军。\n战胜之后，庄公问他缘故。曹刿答道：「作战靠的是勇气。第一次击鼓振作勇气，第二次就衰减，第三次就消尽了。敌方勇气消尽而我方饱满，所以能战胜。大国难以揣测，怕有埋伏。我看他们的车辙乱了，望见他们的旗子倒了，所以追击他们。」"],
    [10, "guwen-gwj-10", "public-domain", "晋侯复假道于虞以伐虢宫之奇谏曰「虢虞之表也虢亡虞必从之晋不可启寇不可玩一之谓甚其可再乎谚所谓『辅车相依唇亡齿寒』者其虞虢之谓也」公曰「晋吾宗也岂害我哉」对曰「大伯虞仲大王之昭也大伯不从是以不嗣虢仲虢叔王季之穆也为文王卿士勋在王室藏于盟府将虢是灭何爱于虞且虞能亲于桓庄乎其爱之也桓庄之族何罪而以为戮不唯逼乎亲以宠逼犹尚害之况以国乎」公曰「吾享祀丰洁神必据我」对曰「臣闻之鬼神非人实亲惟德是依故周书曰『皇天无亲惟德是辅』又曰『黍稷非馨明德惟馨』又曰『民不易物惟德繄物』如是则非德民不和神不享矣神所冯依将在德矣若晋取虞而明德以荐馨香神其吐之乎」弗听许晋使宫之奇以其族行曰「虞不腊矣在此行也晋不更举矣」冬晋灭虢师还馆于虞遂袭虞灭之执虞公", "晋献公又向虞国借路去攻打虢国。宫之奇劝谏说：「虢国是虞国的屏障。虢国灭亡，虞国必定跟着灭亡。不能启发晋国的贪心，不能轻视入侵的敌寇，一次借路已经过分了，怎么可以再来第二次？谚语所说的『面颊与牙床互相依存，嘴唇没有了牙齿就会受寒』，说的就是虞国和虢国吧。」\n虞公说：「晋国是我的同宗，难道会害我吗？」宫之奇答道：「太伯、虞仲都是太王的儿子。太伯没有跟从在侧，所以没有继承王位。虢仲、虢叔都是王季的儿子，做周文王的卿士，功勋记载在王室，盟书收藏在盟府。晋国连虢国都要灭掉，对虞国又有什么爱惜？况且虞国能比桓叔、庄伯的家族更亲近吗？晋献公爱惜他们吗？桓叔、庄伯的家族有什么罪，却被杀戮，不就是因为感到逼迫吗？至亲因为受宠而使人感到逼迫，尚且要加害，何况是国家呢？」\n虞公说：「我的祭品丰盛洁净，神灵必定依从我。」宫之奇答道：「我听说，鬼神并不亲近某个人，只依从有德的人。所以《周书》上说：『上天没有亲疏，只辅助有德的人。』又说：『黍稷不算芳香，只有光明的德行才芳香。』又说：『百姓不会改变祭品，只有德行才是真正的祭品。』照这样说，如果没有德行，百姓就不和睦，神灵也就不来享用。神灵所依从的，就在于德行了。如果晋国占取了虞国，而修明德行来献上芳香的祭品，神灵难道会吐出来吗？」\n虞公不听，答应了晋国的使者。宫之奇带领他的家族离开虞国，说：「虞国等不到年终腊祭了。就在这次行动中，晋国不必再出兵了。」冬天，晋国灭掉虢国。军队返回，驻扎在虞国，于是袭击虞国，把它灭掉，俘虏了虞公。"],
    [11, "guwen-gwj-11", "public-domain", "王使宰孔赐齐侯胙曰「天子有事于文武使孔赐伯舅胙」齐侯将下拜孔曰「且有后命天子使孔曰『以伯舅耋老加劳赐一级无下拜』」对曰「天威不违颜咫尺小白余敢贪天子之命无下拜恐陨越于下以遗天子羞敢不下拜」下拜登受", "周襄王派宰孔赐给齐桓公祭肉，说：「天子祭祀文王、武王，派孔来赐给伯舅祭肉。」齐桓公将要下阶跪拜。宰孔说：「还有后面的命令。天子派孔来说：『因为伯舅年事已高，又加上劳苦，赐进爵一级，不必下拜。』」齐桓公答道：「上天的威严就在眼前，离我的脸不到咫尺，我小白怎敢贪图天子的命令而不下拜？恐怕跌倒在下面，给天子留下羞辱。怎敢不下拜？」于是走下台阶，跪拜；再登上台阶，接受祭肉。"],
    [12, "guwen-gwj-12", "public-domain", "十月晋阴饴甥会秦伯盟于王城秦伯曰「晋国和乎」对曰「不和小人耻失其君而悼丧其亲不惮征缮以立圉也曰『必报仇宁事戎狄』君子爱其君而知其罪不惮征缮以待秦命曰『必报德有死无二』以此不和」秦伯曰「国谓君何」对曰「小人戚谓之不免君子恕以为必归小人曰『我毒秦秦岂归君』君子曰『我知罪矣秦必归君贰而执之服而舍之德莫厚焉刑莫威焉服者怀德贰者畏刑此一役也秦可以霸纳而不定废而不立以德为怨秦不其然』」秦伯曰「是吾心也」改馆晋侯馈七牢焉", "十月，晋国的阴饴甥会见秦穆公，在王城订立盟约。秦穆公问：「晋国上下和睦吗？」阴饴甥答道：「不和睦。小人以失掉国君为耻，又哀悼死去的亲人，不怕征税练兵来拥立公子圉，说：『一定要报仇，宁可事奉戎狄。』君子爱戴他们的国君，也知道他的罪过，不怕征税练兵来等待秦国的命令，说：『一定要报答恩德，死也没有二心。』因此不和睦。」秦穆公问：「晋国人认为国君会怎么样？」阴饴甥答道：「小人忧愁，认为他不会得到赦免；君子宽恕，认为他一定会回来。小人说：『我们毒害了秦国，秦国怎么会放回国君？』君子说：『我们知罪了，秦国一定会放回国君。有二心就把他抓起来，服罪了就放了他，恩德没有比这更厚的，刑罚没有比这更威严的。服罪的人怀念恩德，有二心的人畏惧刑罚。就这一件事，秦国就可以称霸。送回去而不安定他，废掉他而不立他，把恩德变成怨恨，秦国不会这样做。』」秦穆公说：「这正是我的心意。」于是把晋惠公改换到更好的馆舍，送给他七牢的馈赠。"],
    [13, "guwen-gwj-13", "public-domain", "宋公及楚人战于泓宋人既成列楚人未既济司马曰「彼众我寡及其未既济也请击之」公曰「不可」既济而未成列又以告公曰「未可」既陈而后击之宋师败绩公伤股门官歼焉国人皆咎公公曰「君子不重伤不禽二毛古之为军也不以阻隘也寡人虽亡国之余不鼓不成列」子鱼曰「君未知战勍敌之人隘而不列天赞我也阻而鼓之不亦可乎犹有惧焉且今之勍者皆吾敌也虽及胡耇获则取之何有于二毛明耻教战求杀敌也伤未及死如何勿重若爱重伤则如勿伤爱其二毛则如服焉三军以利用也金鼓以声气也利而用之阻隘可也声盛致志鼓儳可也」", "宋襄公与楚军在泓水边交战。宋军已经摆好阵势，楚军还没有完全渡河。司马子鱼说：「他们人多我们人少，趁他们没有全部渡河，请下令攻击。」宋襄公说：「不行。」楚军渡河完毕但还没有摆好阵势，子鱼又提出请求。宋襄公说：「还不行。」等楚军摆好阵势后才攻击，宋军大败。宋襄公伤了大腿，他的侍卫全部被歼灭。\n国人都责怪宋襄公。宋襄公说：「君子不伤害已经受伤的人，不俘虏头发花白的人。古时用兵，不凭借险隘来取胜。我虽然是亡国之君的后代，也不击鼓进攻没有摆好阵势的敌人。」子鱼说：「您不懂作战。强大的敌人，因为地形险隘而没有摆好阵势，这是上天在帮助我们。趁险阻而击鼓进攻，不也可以吗？这样做还怕不能取胜呢。况且如今的强敌，都是我们的敌人。即使是老人，能俘获就抓回来，对头发花白的又有什么可顾惜的？让将士明白什么是耻辱，教他们作战，是为了杀敌。伤了还没有死，为什么不能再伤他？如果怜惜受伤的人，那就不如不要伤他；怜惜头发花白的人，那就不如向他们投降。三军是凭借有利时机来行动的，金鼓是用来鼓舞士气的。有利就用，趁险隘攻击是可以的；鼓声大振、士气旺盛，攻击没有摆好阵势的敌人也是可以的。」"],
    [14, "guwen-gwj-14", "public-domain", "吕郤畏逼将焚公宫而弑晋侯寺人披请见公使让之且辞焉曰「蒲城之役君命一宿女即至其后余从狄君以田渭滨女为惠公来求杀余命女三宿女中宿至虽有君命何其速也夫袪犹在女其行乎」对曰「臣谓君之入也其知之矣若犹未也又将及难君命无二古之制也除君之恶唯力是视蒲人狄人余何有焉今君即位其无蒲狄乎齐桓公置射钩而使管仲相君若易之何辱命焉行者甚众岂唯刑臣」公见之以难告三月晋侯潜会秦伯于王城己丑晦公宫火瑕甥郤芮不获公乃如河上秦伯诱而杀之", "吕甥、郤芮害怕受到迫害，准备焚烧晋侯的宫室并杀死晋侯。寺人披请求进见，晋文公派人斥责他，并且拒绝接见，说：「蒲城那次事件，国君命令你一夜之后到达，你立刻就到了。后来我跟随狄君在渭水边打猎，你为惠公来杀我，命令你三夜之后到达，你第二夜就到了。虽然是有国君的命令，为什么那样快呢？那只被割下的衣袖还在，你还是走吧！」寺人披答道：「我以为您回国即位，已经懂得做国君的道理了。如果还不懂，又将遭遇祸难。国君的命令不能有贰心，这是自古以来的制度。除去国君所厌恶的人，只看自己的力量。蒲人、狄人，对我来说有什么关系呢？如今您即位为君，难道就没有蒲、狄那样的人吗？齐桓公放下射钩之仇而让管仲做相，您如果改变这种做法，何必劳您下命令呢？要走的人很多，岂只我一个受过刑的臣子。」\n晋文公接见了他，他把祸难告诉了文公。三月，晋文公秘密地在王城会见秦穆公。己丑月末，晋侯宫室起火。瑕甥、郤芮没有抓到晋侯，就赶到黄河边上，秦穆公把他们诱骗过河杀掉。"],
    [15, "guwen-gwj-15", "public-domain", "晋侯赏从亡者介之推不言禄禄亦弗及推曰「献公之子九人唯君在矣惠怀无亲外内弃之天未绝晋必将有主主晋祀者非君而谁天实置之而二三子以为己力不亦诬乎窃人之财犹谓之盗况贪天之功以为己力乎下义其罪上赏其奸上下相蒙难与处矣」其母曰「盍亦求之以死谁怼」对曰「尤而效之罪又甚焉且出怨言不食其食」其母曰「亦使知之若何」对曰「言身之文也身将隐焉用文之是求显也」其母曰「能如是乎与女偕隐」遂隐而死晋侯求之不获以绵上为之田曰「以志吾过且旌善人」", "晋文公赏赐跟随他流亡的人，介之推不谈论俸禄，俸禄也没有轮到他。介之推说：「献公有九个儿子，只有国君还在。惠公、怀公没有亲近的人，国外国内都抛弃了他们。上天没有断绝晋国的国运，必定会有君主。主持晋国祭祀的人，不是国君又是谁？这是上天安排的，而那几个随从却认为是自己的力量，不是太荒谬吗？偷窃别人的财物，还叫做盗贼，何况贪取上天的功劳当作自己的力量呢？下面的人把罪过当作道义，上面的人赏赐他们的奸诈，上下互相蒙骗，难以同他们相处了。」他的母亲说：「何不也去求取俸禄呢？这样苦死，又怨恨谁？」介之推答道：「明知是错的又去效法，罪过就更重了。况且我已说出怨言，就不吃他的俸禄。」母亲说：「也让他知道一下，怎么样？」介之推答道：「言语是身体的文饰。身体将要隐藏起来，哪里用得着文饰？这是求显达。」母亲说：「你能这样做吗？我和你一起隐居。」于是隐居到死。晋文公寻找他没有找到，就把绵上的田地作为他的祭田，说：「用来记住我的过错，并且表彰好人。」"],
    [16, "guwen-gwj-16", "public-domain", "夏齐孝公伐我北鄙公使展喜犒师使受命于展禽齐侯未入竟展喜从之曰「寡君闻君亲举玉趾将辱于敝邑使下臣犒执事」齐侯曰「鲁人恐乎」对曰「小人恐矣君子则否」齐侯曰「室如县罄野无青草何恃而不恐」对曰「恃先王之命昔周公大公股肱周室夹辅成王成王劳之而赐之盟曰『世世子孙无相害也』载在盟府太师职之桓公是以纠合诸侯而谋其不协弥缝其阙而匡救其灾昭旧职也及君即位诸侯之望曰『其率桓之功』我敝邑用不敢保聚曰『岂其嗣世九年而弃命废职其若先君何君必不然』恃此以不恐」齐侯乃还", "夏天，齐孝公攻打鲁国北部边境。僖公派展喜去犒劳齐军，让他先向展禽领受辞令。齐孝公还没有进入鲁国国境，展喜就迎上去，说：「我们国君听说您亲自举步，将要屈尊光临敝国，派我来犒劳您的随从。」齐孝公说：「鲁国人害怕吗？」展喜答道：「小人害怕了，君子却不害怕。」齐孝公说：「屋子里像挂着磬一样空无一物，田野里连青草都没有，凭什么不害怕？」展喜答道：「凭先王的命令。从前周公、太公是周王室的股肱之臣，辅佐成王。成王慰劳他们，赐给他们盟约，说：『世世代代的子孙，不要互相伤害。』盟书藏在盟府，由太师掌管。齐桓公因此纠合诸侯，商讨他们之间的不和，弥补他们的缺失，匡救他们的灾祸，这是彰明太公旧日的职责。到了您即位，诸侯都盼望说：『他会继承桓公的功业。』我们敝国因此不敢聚集兵力守城，说：『难道他继承君位九年，就抛弃先王的命令、废弃自己的职责？那怎么对得起先君？您一定不会这样。』凭这一点，所以不害怕。」\n齐孝公于是撤兵回国。"],
    [17, "guwen-gwj-17", "public-domain", "晋侯秦伯围郑以其无礼于晋且贰于楚也晋军函陵秦军氾南佚之狐言于郑伯曰「国危矣若使烛之武见秦君师必退」公从之辞曰「臣之壮也犹不如人今老矣无能为也已」公曰「吾不能早用子今急而求子是寡人之过也然郑亡子亦有不利焉」许之夜缒而出见秦伯曰「秦晋围郑郑既知亡矣若亡郑而有益于君敢以烦执事越国以鄙远君知其难也焉用亡郑以陪邻邻之厚君之薄也若舍郑以为东道主行李之往来共其乏困君亦无所害且君尝为晋君赐矣许君焦瑕朝济而夕设版焉君之所知也夫晋何厌之有既东封郑又欲肆其西封若不阙秦将焉取之阙秦以利晋唯君图之」秦伯说与郑人盟使杞子逢孙杨孙戍之乃还子犯请击之公曰「不可微夫人之力不及此因人之力而敝之不仁失其所与不知以乱易整不武吾其还也」亦去之", "晋文公和秦穆公围攻郑国，因为郑国曾对晋文公无礼，而且亲近楚国。晋军驻扎在函陵，秦军驻扎在氾水之南。\n佚之狐对郑文公说：「国家危险了！如果派烛之武去见秦君，秦军一定会退。」郑文公听从了他。烛之武推辞说：「臣壮年时，还比不上别人；如今老了，更做不了什么了。」郑文公说：「我不能早任用你，如今情况紧急才来求你，这是我的过错。然而郑国灭亡，对你也不利。」烛之武答应了。\n夜里用绳子把他从城墙上放下去。他见到秦伯说：「秦、晋围攻郑国，郑国已经知道要亡了。如果灭亡郑国对您有好处，那就敢劳您动手。越过别国把远地作为边邑，您知道那是很难的。哪里用得着灭亡郑国来增加邻国的土地？邻国强大了，您就削弱了。如果放过郑国让它做东方道路上的主人，秦国使者往来，郑国可以供给他们所缺的东西，对您也没有害处。况且您曾对晋君有恩，他答应给您焦、瑕两地，却早上渡河回国、晚上就筑城防备，这是您知道的。晋国哪里会满足？向东把郑国作为边邑之后，又要扩张西边的疆界。如果不损害秦国，又到哪里去取得土地？损害秦国来使晋国得利，望您考虑。」\n秦伯高兴了，与郑国结盟，派杞子、逢孙、杨孙留守郑国，就撤军回国了。\n子犯请求攻击秦军。晋文公说：「不行。没有那个人的力量到不了今天。依靠过别人的力量又去损害他，是不仁；失掉自己的同盟，是不智；用混乱去代替整齐，是不武。我们还是回去吧。」晋军也撤离了。"],
    [18, "guwen-gwj-18", "public-domain", "杞子自郑使告于秦曰「郑人使我掌其北门之管若潜师以来国可得也」穆公访诸蹇叔蹇叔曰「劳师以袭远非所闻也师劳力竭远主备之无乃不可乎师之所为郑必知之勤而无所必有悖心且行千里其谁不知」公辞焉召孟明西乞白乙使出师于东门之外蹇叔哭之曰「孟子吾见师之出而不见其入也」公使谓之曰「尔何知中寿尔墓之木拱矣」蹇叔之子与师哭而送之曰「晋人御师必于殽殽有二陵焉其南陵夏后皋之墓也其北陵文王之所辟风雨也必死是间余收尔骨焉」秦师遂东", "杞子从郑国派人报告秦国说：「郑国人让我掌管他们北门的钥匙，如果偷偷派兵来，就可以取得郑国。」秦穆公向蹇叔咨询。蹇叔说：「使军队疲劳去偷袭远方的国家，我没有听说过。军队疲劳、力量耗尽，远方的主人已有防备，恐怕不行吧？军队的行动，郑国一定会知道。劳苦而无所得，士兵必有怨恨之心。况且行军千里，谁会不知道？」穆公不听他的。召见孟明、西乞、白乙，命令他们从东门外出兵。蹇叔哭着送他们，说：「孟明啊！我看到军队出去，却看不到它回来！」穆公派人责备他说：「你知道什么？如果你只活到中寿，你坟上的树已经合抱粗了！」\n蹇叔的儿子也在军中，蹇叔哭着送他，说：「晋国人一定在殽山阻击我军。殽山有两座山陵：南陵是夏后皋的坟墓，北陵是周文王避过风雨的地方。你一定会死在这两山之间，我到那里收拾你的尸骨。」秦军于是东进了。"],
    [19, "guwen-gwj-85", "school", "臣密言臣以险衅夙遭闵凶生孩六月慈父见背行年四岁舅夺母志祖母刘愍臣孤弱躬亲抚养臣少多疾病九岁不行零丁孤苦至于成立既无伯叔终鲜兄弟门衰祚薄晚有儿息外无期功强近之亲内无应门五尺之僮茕茕孑立形影相吊而刘夙婴疾病常在床蓐臣侍汤药未曾废离逮奉圣朝沐浴清化前太守臣逵察臣孝廉后刺史臣荣举臣秀才臣以供养无主辞不赴命诏书特下拜臣郎中寻蒙国恩除臣洗马猥以微贱当侍东宫非臣陨首所能上报臣具以表闻辞不就职诏书切峻责臣逋慢郡县逼迫催臣上道州司临门急于星火臣欲奉诏奔驰则刘病日笃欲苟顺私情则告诉不许臣之进退实为狼狈伏惟圣朝以孝治天下凡在故老犹蒙矜育况臣孤苦特为尤甚且臣少仕伪朝历职郎署本图宦达不矜名节今臣亡国贱俘至微至陋过蒙拔擢宠命优渥岂敢盘桓有所希冀但以刘日薄西山气息奄奄人命危浅朝不虑夕臣无祖母无以至今日祖母无臣无以终余年母孙二人更相为命是以区区不能废远臣密今年四十有四祖母今年九十有六是臣尽节于陛下之日长报养刘之日短也乌鸟私情愿乞终养臣之辛苦非独蜀之人士及二州牧伯所见明知皇天后土实所共鉴愿陛下矜愍愚诚听臣微志庶刘侥幸保卒余年臣生当陨首死当结草臣不胜犬马怖惧之情谨拜表以闻", "臣李密上言：我因为命运不好，早年就遭遇不幸。生下来六个月，慈父就去世了；长到四岁，舅舅逼母亲改嫁。祖母刘氏怜惜我孤苦弱小，亲自抚养我。我小时候多病，九岁还不能走路，孤苦零丁，直到成年。既没有伯叔，也少有兄弟，门庭衰微、福分浅薄，很晚才有儿子。外面没有关系较近的亲戚，家里没有照应门户的僮仆，孤孤单单，只有自己的身子和影子互相安慰。而刘氏一向患病，常年卧床，我侍奉汤药，从来没有停止离开过。\n到了圣朝，我受到清明政治的浸润。先前太守逵考察我推举为孝廉，后来刺史荣选拔我为秀才。我因为无人供养祖母，辞谢不接受任命。诏书特地颁下，任命我为郎中，不久又蒙受国恩，任命我为洗马。以我这样卑微低贱的人，担当侍奉太子的职务，不是我杀身所能报答的。我把这些详细写成表章上奏，辞谢不去就职。诏书急切严厉，责备我逃避怠慢。郡县长官逼迫，催我上路；州官上门，比星火还急。我想奉诏奔走，但刘氏的病情一天天沉重；想姑且顺从私情，但申诉不被允许。我的进退，实在狼狈。\n我想到圣朝以孝治理天下，凡是年老的人，尚且受到怜惜养育，何况我孤苦的情况，特别严重。况且我年轻时曾在伪朝做官，历任郎官之职，本来就图仕途显达，并不看重名誉节操。如今我是亡国的卑贱俘虏，极其卑微浅陋，过分地受到提拔，恩宠优厚，怎敢迟疑徘徊，另有希图。只因为刘氏像落日迫近西山，气息微弱，生命危险，朝不保夕。我没有祖母，就没有今天；祖母没有我，就无法度过余年。祖孙二人，相依为命，所以我不能舍弃她而远离。\n我李密今年四十四岁，祖母今年九十六岁，这样我向陛下尽忠的日子长，报答养育刘氏的日子短。像乌鸦反哺一样的私情，希望求得让我把祖母奉养到最后。我的苦衷，不只是蜀地的人士和两州的长官所看见明白的，天地神明实在都共同鉴察。希望陛下怜惜我愚拙的诚心，听从我微小的愿望，或许刘氏能侥幸保全，度过余年。我活着当杀身报效，死了也要结草报恩。我怀着犬马般不胜恐惧的心情，恭敬地呈上表章让陛下知道。"],
    [20, "guwen-gwj-86", "public-domain", "永和九年岁在癸丑暮春之初会于会稽山阴之兰亭修禊事也群贤毕至少长咸集此地有崇山峻岭茂林修竹又有清流激湍映带左右引以为流觞曲水列坐其次虽无丝竹管弦之盛一觞一咏亦足以畅叙幽情是日也天朗气清惠风和畅仰观宇宙之大俯察品类之盛所以游目骋怀足以极视听之娱信可乐也夫人之相与俯仰一世或取诸怀抱悟言一室之内或因寄所托放浪形骸之外虽趣舍万殊静躁不同当其欣于所遇暂得于己快然自足不知老之将至及其所之既倦情随事迁感慨系之矣向之所欣俯仰之间已为陈迹犹不能不以之兴怀况修短随化终期于尽古人云「死生亦大矣」岂不痛哉每览昔人兴感之由若合一契未尝不临文嗟悼不能喻之于怀固知一死生为虚诞齐彭殇为妄作后之视今亦犹今之视昔悲夫故列叙时人录其所述虽世殊事异所以兴怀其致一也后之览者亦将有感于斯文", "永和九年，年岁在癸丑，暮春之初，我们在会稽山阴的兰亭聚会，举行修禊之事。众多贤士都到了，年少的年长的都聚集在一起。这里有高峻的山岭、茂密的树林和修长的竹子，又有清澈湍急的溪流，辉映环绕在左右，引来作为流觞的曲水，大家依次坐在水边。虽然没有丝竹管弦的热闹，但一边饮酒一边赋诗，也足以畅快地抒发幽深的情怀。\n这一天，天空晴朗、空气清朗，微风和暖。仰头观看宇宙的广大，低头细察万物的繁盛，借以放眼远望、开畅胸怀，足以穷尽视听的乐趣，实在是快乐啊。\n人们相互交往，转眼就度过一生。有的人把自己的胸怀抱负，在一室之内面对面交谈；有的人就着自己所爱好的事物寄托情怀，放纵形体之外。虽然取舍千差万别，性情安静与浮躁各不相同，但当他们对所遇到的事物感到欣喜，暂时得到满足，就愉快地自我陶醉，不知道老年将要到来；等到对所追求的东西已经厌倦，感情随着事物变化，感慨就随之而生了。从前所欣喜的，转眼之间已成为旧迹，尚且不能不因此引发感慨，何况寿命长短听凭造化，最终归于消亡！古人说：「死生也是大事啊。」怎能不令人悲痛！\n每当看到前人产生感慨的缘由，像符契一样相合，没有不面对文章叹息哀伤，心里又不能明白是什么缘故。本来就知道把死生看作一样是虚妄的，把长寿和短命看作等同是胡说的。后人看现在，也像现在的人看从前，可悲啊！所以我一一记下当时与会的人，录下他们所作的诗。虽然时代不同、事情各异，但引起感慨的原因，是一样的。后世的读者，也将对这次集会的诗文有所感慨。"],
    [21, "guwen-gwj-87", "school", "归去来兮田园将芜胡不归既自以心为形役奚惆怅而独悲悟已往之不谏知来者之可追实迷途其未远觉今是而昨非舟遥遥以轻飏风飘飘而吹衣问征夫以前路恨晨光之熹微乃瞻衡宇载欣载奔僮仆欢迎稚子候门三径就荒松菊犹存携幼入室有酒盈樽引壶觞以自酌眄庭柯以怡颜倚南窗以寄傲审容膝之易安园日涉以成趣门虽设而常关策扶老以流憩时矫首而遐观云无心以出岫鸟倦飞而知还景翳翳以将入抚孤松而盘桓归去来兮请息交以绝游世与我而相违复驾言兮焉求悦亲戚之情话乐琴书以消忧农人告余以春及将有事于西畴或命巾车或棹孤舟既窈窕以寻壑亦崎岖而经丘木欣欣以向荣泉涓涓而始流善万物之得时感吾生之行休已矣乎寓形宇内复几时曷不委心任去留胡为乎遑遑欲何之富贵非吾愿帝乡不可期怀良辰以孤往或植杖而耘耔登东皋以舒啸临清流而赋诗聊乘化以归尽乐夫天命复奚疑", "回去吧，田园快要荒芜了，为什么还不回去！既然自己让心志被形体所驱使，为什么还惆怅独自悲伤？觉悟到过去的事已无法挽回，知道将来的事还可以补救。其实走入迷途还不算远，已经明白今天是对的、昨天是错的。船在水上轻轻地飘荡，风飘飘地吹动衣裳。向行人打听前面的路，只恨晨光还很微弱。\n终于望见自家的屋檐，一边欣喜一边奔跑。僮仆前来迎接，幼儿在门口等候。院中的小路快要荒芜，松树菊花还依然存在。牵着幼儿走进屋内，酒已盛满酒樽。拿起酒壶酒杯自斟自饮，看着院中的树枝和悦地露出笑容。靠着南窗寄托傲然的情怀，深知这仅容膝盖的小屋反而容易安适。天天到园中散步成了乐趣，门虽设着却常常关着。拄着手杖走走停停，时时抬头远望。云无意地从山峰间飘出，鸟飞倦了就知道回巢。日光昏暗将要落山，我抚着孤松徘徊不去。\n回去吧，请让我断绝与世俗的交游。世俗与我相违背，再驾车出去又追求什么呢？喜欢与亲戚说知心话，乐于弹琴读书来消解忧愁。农人告诉我春天到了，将要到西边的田地去耕作。有时驾着有帷幕的车，有时划着孤舟。既曲折地探寻山壑，也崎岖地经过山丘。树木欣欣向荣，泉水涓涓开始流动。羡慕万物得到好时节，感叹我的一生将要结束。\n算了吧！寄身天地间还能多久，为什么不随心任其去留？为什么惶惶不安地想要到哪里去？富贵不是我的愿望，仙界不可期望。趁着好时光独自出游，或者把手杖插在田边除草培土。登上东边的高地放声长啸，面对清流赋诗。姑且顺着自然的造化走到尽头，乐天知命还有什么可怀疑的！"],
    [22, "poems-cz8-14", "school", "晋太元中武陵人捕鱼为业缘溪行忘路之远近忽逢桃花林夹岸数百步中无杂树芳草鲜美落英缤纷渔人甚异之复前行欲穷其林林尽水源便得一山山有小口仿佛若有光便舍船从口入初极狭才通人复行数十步豁然开朗土地平旷屋舍俨然有良田美池桑竹之属阡陌交通鸡犬相闻其中往来种作男女衣着悉如外人黄发垂髫并怡然自乐见渔人乃大惊问所从来具答之便要还家设酒杀鸡作食村中闻有此人咸来问讯自云先世避秦时乱率妻子邑人来此绝境不复出焉遂与外人间隔问今是何世乃不知有汉无论魏晋此人一一为具言所闻皆叹惋余人各复延至其家皆出酒食停数日辞去此中人语云不足为外人道也既出得其船便扶向路处处志之及郡下诣太守说如此太守即遣人随其往寻向所志遂迷不复得路南阳刘子骥高尚士也闻之欣然规往未果寻病终后遂无问津者", "东晋太元年间，武陵郡有个人以打鱼为生。他沿着溪水划船前行，忘记了路程的远近。忽然遇到一片桃花林，生长在溪水两岸，长达几百步，中间没有别的树，芳草鲜嫩美丽，落花纷纷。渔人非常惊奇，继续往前走，想走到那片林子的尽头。桃林在溪水发源的地方就到头了，便出现一座山，山上有个小洞口，里面隐隐约约好像有光亮。渔人就丢下船，从洞口进去。起初洞口很狭窄，仅容一个人通过。又走了几十步，突然变得开阔明亮了。这里土地平坦开阔，房屋整整齐齐，有肥沃的田地、美丽的池塘和桑树竹子之类。田间小路交错相通，村落间鸡鸣狗吠之声处处可以听到。人们在田野里来来往往耕种劳作，男女的穿戴都和桃花源外面的人一样。老人和小孩都悠闲愉快、自得其乐。村里的人见到渔人，就非常惊奇，问他从哪里来。渔人详细地回答了他们。村里人便邀请他到自己家里去，摆酒杀鸡做饭来款待他。村里的人听说来了这样一个人，都来打听消息。他们自己说祖先为了躲避秦朝时的战乱，带领妻子儿女和乡邻来到这个与人世隔绝的地方，不再从这里出去，于是就和外面的人断绝了来往。他们问现在是什么朝代，竟不知道有过汉朝，更不必说魏朝和晋朝了。渔人把自己知道的事一一详细地告诉了他们，村里人都感叹惋惜。其余的人各自又把渔人请到自己家中，都拿出酒饭来招待他。渔人停留了几天，就告辞离去。村里人嘱咐他说：这里的情况不值得对外面的人说啊。渔人出来以后，找到了他的船，就顺着旧路回去，处处做了标记。到了郡城，去拜见太守，报告了这件事。太守立即派人跟着他去，寻找先前所做的标记，最终迷失了方向，再也找不到通往桃花源的路了。南阳的刘子骥，是个志向高洁的隐士，听说了这件事，高兴地计划前往。还没有实现，不久就因病去世了。此后就再也没有探寻桃花源的人了。"],
    [23, "guwen-gwj-89", "public-domain", "先生不知何许人也亦不详其姓字宅边有五柳树因以为号焉闲静少言不慕荣利好读书不求甚解每有会意便欣然忘食性嗜酒家贫不能常得亲旧知其如此或置酒而招之造饮辄尽期在必醉既醉而退曾不吝情去留环堵萧然不蔽风日短褐穿结箪瓢屡空晏如也常著文章自娱颇示己志忘怀得失以此自终赞曰黔娄之妻有言「不戚戚于贫贱不汲汲于富贵」其言兹若人之俦乎衔觞赋诗以乐其志无怀氏之民欤葛天氏之民欤", "这位先生不知是什么地方的人，也不清楚他的姓名。住宅旁边有五棵柳树，因此就以此为号。他闲静少言，不羡慕荣华利禄。喜好读书，不追求字字句句都深入理解；每当有体会，便高兴得忘了吃饭。生性嗜酒，家里贫穷不能常常得到。亲戚故旧知道他这样，有时置办酒食来邀请他。他去了就喝光，希望一定要醉；醉了就退席，从不顾惜去留。四壁空空，不能遮蔽风雨阳光，粗布短衣破烂打结，饭篮水瓢常常空着，他却安然自若。常写文章自娱，也颇能表达自己的志趣。忘怀得失，就这样度过一生。\n赞曰：黔娄的妻子有话说：「不因贫贱而忧愁，不因富贵而汲汲追求。」这话大概说的就是这一类人吧？饮酒赋诗，来使自己的心志快乐。他是无怀氏时代的百姓呢？还是葛天氏时代的百姓呢？"],
    [24, "guwen-gwj-90", "public-domain", "钟山之英草堂之灵驰烟驿路勒移山庭夫以耿介拔俗之标萧洒出尘之想度白雪以方洁干青云而直上吾方知之矣若其亭亭物表皎皎霞外芥千金而不眄屣万乘其如脱闻凤吹于洛浦值薪歌于延濑固亦有焉岂期终始参差苍黄反复泪翟子之悲恸朱公之哭乍回迹以心染或先贞而后黩何其谬哉呜呼尚生不存仲氏既往山阿寂寥千载谁赏世有周子隽俗之士既文既博亦玄亦史然而学遁东鲁习隐南郭偶吹草堂滥巾北岳诱我松桂欺我云壑虽假容于江皋乃缨情于好爵其始至也将欲排巢父拉许由傲百氏蔑王侯风情张日霜气横秋或叹幽人长往或怨王孙不游谈空空于释部核玄玄于道流务光何足比涓子不能俦及其鸣驺入谷鹤书赴陇形驰魄散志变神动尔乃眉轩席次袂耸筵上焚芰制而裂荷衣抗尘容而走俗状风云凄其带愤石泉咽而下怆望林峦而有失顾草木而如丧至其纽金章绾墨绶跨属城之雄冠百里之首张英风于海甸驰妙誉于浙右道帙长摈法筵久埋敲扑喧嚣犯其虑牒诉倥偬装其怀琴歌既断酒赋无续常绸缪于结课每纷纶于折狱笼张赵于往图架卓鲁于前箓希踪三辅豪驰声九州牧使我高霞孤映明月独举青松落阴白云谁侣涧户摧绝无与归石径荒凉徒延伫至于还飙入幕写雾出楹蕙帐空兮夜鹤怨山人去兮晓猿惊昔闻投簪逸海岸今见解兰缚尘缨于是南岳献嘲北陇腾笑列壑争讥攒峰竦诮慨游子之我欺悲无人以赴吊故其林惭无尽涧愧不歇秋桂遣风春萝罢月骋西山之逸议驰东皋之素谒今又促装下邑浪栧上京虽情投于魏阙或假步于山扃岂可使芳杜厚颜薜荔蒙耻碧岭再辱丹崖重滓尘游躅于蕙路污渌池以洗耳宜扃岫幌掩云关敛轻雾藏鸣湍截来辕于谷口杜妄辔于郊端于是丛条瞋胆叠颖怒魄或飞柯以折轮乍低枝而扫迹请回俗士驾为君谢逋客", "钟山的英秀，草堂的神灵，腾烟驾雾在驿路上奔驰，把这篇移文刻在山庭：\n以耿介脱俗的风标，潇洒出尘的意想，与白雪比洁，直上青云，我是知道的。至于亭亭卓立于物外，皎皎明亮于霞外，把千金看作草芥而不顾，把万乘之位看作脱鞋一样抛弃，在洛水边听凤鸣，在延濑遇到唱薪歌的人，本来也是有的。哪料到有人始终不一，苍黄反复，使翟公为之悲伤流泪，使朱公为之恸哭。刚才还隐迹山林而心已被沾染，或者先守贞而后污浊，多么荒谬啊！唉，尚长不在，仲长统已去，山阿寂寥，千年以来谁来赏识！\n世间有位周先生，是俊逸脱俗的士人，既有文采又博学，既通玄学又通史学。然而他学东鲁的隐遁，效南郭的隐居，偶然在草堂吹竽，滥竽充数在北岳。引诱我的松桂，欺骗我的云壑。虽然在江边装出隐士的样子，心里却系念着高官厚禄。\n他刚来的时候，将要排斥巢父，拉住许由，傲视百家，蔑视王侯。风情张扬蔽日，霜气横贯秋空。有时感叹幽人长往不返，有时埋怨王孙不来游赏。在佛书中谈论空空，在道流中考核玄玄。务光哪里值得相比，涓子也不能为俦。\n等到前呼后拥的骑士进入山谷，诏书送到陇上，他就形驰魄散，志变神动。于是在席间眉飞色舞，在筵上挥舞衣袖，烧掉菱叶制的衣裳、撕裂荷叶制的衣裳，露出尘俗的面容、奔走向俗态。风云凄然含愤，石泉呜咽悲怆，望林峦而若有所失，顾草木而如有所丧。\n至于他系上金印，绾上墨绶，位居属城之长，为百里之首。在海边张扬英风，在浙右驰骋美誉。道家的书卷长久被摈弃，讲法的筵席长久被埋没。敲打鞭扑的喧嚣扰乱他的思虑，公文诉讼的繁忙装满他的胸怀。琴歌已经断绝，酒赋无从继续。常常忙于考核赋税，每每纷乱于判决狱讼。笼络张敞、赵广汉于旧图，超越卓茂、鲁恭于前录。希图追随三辅的豪杰，驰名声于九州的州牧。\n使我高霞孤独映照，明月独自高悬，青松落下阴影，白云谁来为伴？涧边的门户崩塌无人归来，石径荒凉空自久立。至于回风入幕，雾气出楹，蕙帐空寂啊夜鹤哀怨，山人离去啊晨猿惊啼。从前听说有人弃官归隐海岸，如今却见有人解开兰佩系上尘世的冠缨。\n于是南岳献上嘲笑，北陇腾起讥笑，众壑争相非议，群峰耸立讥诮。慨叹游子欺骗了我，悲伤没有人来吊唁。所以山林惭愧无尽，涧水羞愧不歇，秋桂遣散清风，春萝罢去明月。驰骋西山的逸议，传布东皋的素谒。\n如今他又急忙整装离开下邑，泛舟前往京城，虽然心意投向朝廷，也许还会借道山门。怎能使芳杜厚着脸皮，薜荔蒙受羞耻，碧岭再次受辱，丹崖重新玷污，在蕙路上留下尘土的足迹，弄污清池来洗耳？应当关闭山穴的帷幔，掩上云关，收敛轻雾，藏起鸣湍，在谷口截住他的来车，在郊外堵住他妄行的马缰。于是丛竹怒张肝胆，叠草愤怒魂魄，有的飞起枝条折断车轮，有的低下枝头扫去踪迹。请世俗之士掉转车驾，替山灵谢绝这位逃客。"],
    [25, "guwen-gwj-91", "school", "臣闻求木之长者必固其根本欲流之远者必浚其泉源思国之安者必积其德义源不深而望流之远根不固而求木之长德不厚而思国之安臣虽下愚知其不可而况于明哲乎人君当神器之重居域中之大将崇极天之峻永保无疆之休不念居安思危戒奢以俭德不处其厚情不胜其欲斯亦伐根以求木茂塞源而欲流长者也凡百元首承天景命莫不殷忧而道著功成而德衰有善始者实繁能克终者盖寡岂其取之易而守之难乎昔取之而有余今守之而不足何也夫在殷忧必竭诚以待下既得志则纵情以傲物竭诚则胡越为一体傲物则骨肉为行路虽董之以严刑振之以威怒终苟免而不怀仁貌恭而不心服怨不在大可畏惟人载舟覆舟所宜深慎奔车朽索其可忽乎君人者诚能见可欲则思知足以自戒将有作则思知止以安人念高危则思谦冲而自牧惧满溢则思江海下百川乐盘游则思三驱以为度忧懈怠则思慎始而敬终虑壅蔽则思虚心以纳下想谗邪则思正身以黜恶恩所加则思无因喜以谬赏罚所及则思无因怒而滥刑总此十思宏兹九德简能而任之择善而从之则智者尽其谋勇者竭其力仁者播其惠信者效其忠文武并用垂拱而治何必劳神苦思代百司之职役哉", "我听说想要树木生长得高，一定要使它的根稳固；想要水流得远，一定要疏浚它的源头；想要国家安定，一定要积聚德行仁义。水源不深却希望水流得远，树根不牢却要求树木长得高，德行不厚却想国家安定，我虽然愚昧，也知道这是不可能的，何况明智的人呢！君主承担着帝位的重任，处在天地间重要的位置上，将要追求像天一样的高峻，永远保持无穷的福禄，如果不考虑居安思危、戒除奢侈而厉行节俭，德行不能保持深厚，情感不能战胜欲望，这也就像砍断树根却要求树木茂盛、堵塞水源却想要水流长远一样。\n凡是古代的君主，承受上天的大命，没有不是在深重忧患中道德显著、功业成就后德行衰败的。有良好开端的人实在很多，能坚持到底的大概很少。难道是取得天下容易而守住天下难吗？从前取得天下还有余力，如今守住天下却力不从心，为什么？因为在深重忧患中，一定竭尽诚心来对待下属；一旦得志，就放纵情欲、傲视他人。竭尽诚心，那么胡越这样疏远的人也能结为一体；傲视他人，那么骨肉之亲也会变成路人。即使用严酷的刑罚督察他们，用威严怒气震慑他们，最终也只是苟且免于刑罚而不怀念仁德，表面恭敬而内心不服。怨恨不在于大小，可怕的只有人心；水能载舟也能覆舟，这是应该深切谨慎对待的。奔车拉着朽索，怎么能忽视呢！\n做君主的，如果真能做到：看见引起欲望的东西，就想到知足来自我警戒；将要兴建土木，就想到适可而止来使百姓安定；想到高位危险，就想到谦虚自守；害怕自满，就想到江海位居百川之下；喜欢游玩，就想到三面驱围、留一面的限度；担忧懈怠，就想到慎始慎终；忧虑耳目被蒙蔽，就想到虚心接纳下属意见；想到谗邪之人，就想到端正自身、斥退邪恶；施恩的时候，就想到不要因一时高兴而错赏；惩罚的时候，就想到不要因一时恼怒而滥用刑罚。总括这十思，弘扬这九种品德，选拔有才能的人任用他们，择取好的意见听从它，那么聪明的人会竭尽谋略，勇敢的人会竭尽全力，仁爱的人会传播恩惠，诚信的人会献出忠心。文臣武将都得到任用，君主就可以垂衣拱手而天下大治。何必劳神苦思，代替百官去处理事务呢！"],
    [27, "guwen-gwj-93", "school", "豫章故郡洪都新府星分翼轸地接衡庐襟三江而带五湖控蛮荆而引瓯越物华天宝龙光射牛斗之墟人杰地灵徐孺下陈蕃之榻雄州雾列俊采星驰台隍枕夷夏之交宾主尽东南之美都督阎公之雅望棨戟遥临宇文新州之懿范襜帷暂驻十旬休假胜友如云千里逢迎高朋满座腾蛟起凤孟学士之词宗紫电青霜王将军之武库家君作宰路出名区童子何知躬逢胜饯时维九月序属三秋潦水尽而寒潭清烟光凝而暮山紫俨骖騑于上路访风景于崇阿临帝子之长洲得天人之旧馆层峦耸翠上出重霄飞阁流丹下临无地鹤汀凫渚穷岛屿之萦回桂殿兰宫即冈峦之体势披绣闼俯雕甍山原旷其盈视川泽纡其骇瞩闾阎扑地钟鸣鼎食之家舸舰弥津青雀黄龙之舳云销雨霁彩彻区明落霞与孤鹜齐飞秋水共长天一色渔舟唱晚响穷彭蠡之滨雁阵惊寒声断衡阳之浦遥襟甫畅逸兴遄飞爽籁发而清风生纤歌凝而白云遏睢园绿竹气凌彭泽之樽邺水朱华光照临川之笔四美具二难并穷睇眄于中天极娱游于暇日天高地迥觉宇宙之无穷兴尽悲来识盈虚之有数望长安于日下目吴会于云间地势极而南溟深天柱高而北辰远关山难越谁悲失路之人萍水相逢尽是他乡之客怀帝阍而不见奉宣室以何年嗟乎时运不齐命途多舛冯唐易老李广难封屈贾谊于长沙非无圣主窜梁鸿于海曲岂乏明时所赖君子见机达人知命老当益壮宁移白首之心穷且益坚不坠青云之志酌贪泉而觉爽处涸辙以犹欢北海虽赊扶摇可接东隅已逝桑榆非晚孟尝高洁空余报国之情阮籍猖狂岂效穷途之哭勃三尺微命一介书生无路请缨等终军之弱冠有怀投笔慕宗悫之长风舍簪笏于百龄奉晨昏于万里非谢家之宝树接孟氏之芳邻他日趋庭叨陪鲤对今兹捧袂喜托龙门杨意不逢抚凌云而自惜钟期既遇奏流水以何惭呜呼胜地不常盛筵难再兰亭已矣梓泽丘墟临别赠言幸承恩于伟饯登高作赋是所望于群公敢竭鄙怀恭疏短引一言均赋四韵俱成请洒潘江各倾陆海云尔", "这里是汉代的豫章旧郡，如今是洪州的新府。星空的分野属于翼、轸两宿，地势连接着衡山和庐山。以三江为衣襟、以五湖为衣带，控制着楚地、连接着瓯越。物类的精华是上天的珍宝，宝剑的光芒直射牛斗二宿的所在；人中有英杰、地有灵气，徐孺子使陈蕃为他放下床榻。雄伟的州城像雾一般涌起，杰出的人才像流星般飞驰。城池依凭着中原与南夷的交界，宾客与主人都是东南一带的俊杰。都督阎公有崇高的声望，仪仗远远地来到；新州的宇文刺史有美好的风范，车驾在此暂时停驻。正值十日一休的假期，好友如云；千里之外的宾客前来相会，高朋满座。文辞如蛟龙腾起、凤凰飞舞，是孟学士这样的文章宗师；宝剑如紫电青霜，是王将军这样的武库。家父在外地做县令，我因探望路过这名胜之地；我年幼无知，却有幸亲身遇到了这场盛大的宴会。\n时当九月，季节属于深秋。积水消尽而寒潭清澄，烟霭凝集而暮山发紫。驾着车马在高高的路上前行，到高丘上寻访风景；来到滕王曾经游宴的长洲，见到仙人住过的旧馆。层层山峦耸起翠绿，向上直出云霄；凌空的楼阁涂饰鲜红，向下俯视不见地面。白鹤栖息的水滨、小鸭聚集的小洲，极尽岛屿曲折回环的情致；桂木兰木的殿堂宫室，都依着山冈的形势而建。\n推开雕花的阁门，俯视雕饰的屋脊，山岭平原辽阔得充满视野，河流湖泽纡回得令人惊叹。里巷房舍遍地，尽是钟鸣鼎食的富贵人家；船只塞满渡口，船头画着青雀黄龙。云散雨停，阳光普照、天空明净。落霞与孤雁一同飞舞，秋水与长空浑然一色。渔舟在傍晚唱起歌，歌声传遍彭蠡之滨；雁阵因寒意而惊飞，叫声消失在衡阳的水边。\n远望的胸怀刚刚畅快，飘逸的兴致急速飞升。排箫奏起而清风生，细歌凝聚而白云停。像睢园的绿竹，气概超过彭泽的酒樽；像邺水的红莲，光彩照耀临川的笔。音乐、美景、佳宾、盛宴四美俱全，贤主、嘉宾二难并具。极目远望天空，尽情游乐在这闲暇之日。天高地远，感到宇宙的无穷；兴尽悲来，认识到盛衰自有定数。遥望长安在日下，远眺吴会在云间。地势尽于南方而南海深，天柱高耸而北极星遥远。关山难以逾越，谁来悲悯迷路的人？萍水相逢，都是他乡之客。怀念朝廷宫门却不能见到，什么时候才能像贾谊那样被召入宣室？\n唉！时运不齐，命运多有坎坷。冯唐容易衰老，李广难以封侯。使贾谊屈居长沙，并非没有圣明的君主；让梁鸿逃隐海边，难道不是太平盛世？所依靠的是君子能见机行事，通达的人知道天命。年老应当更加壮健，怎么能改变白首之心？处境困窘应当更加坚定，不能坠落青云之志。饮了贪泉之水仍觉清爽，处在干涸的车辙中仍然欢畅。北海虽然遥远，乘着旋风可以到达；早晨的时光已经逝去，日落时的收成还不算晚。孟尝君品行高洁，白白留下报国的热情；阮籍放纵不羁，我怎能学他穷途之哭！\n我王勃，不过是三尺微命的一个书生。没有门路请缨报国，与终军二十岁的年纪相同；有心投笔从戎，仰慕宗悫乘风破浪的志向。舍弃一生的功名仕途，到万里之外去侍奉父母的晨昏起居。虽不是谢家那样的宝树，却也接近孟氏那样的芳邻。将来在父亲庭前侍立，有幸陪侍父亲聆听教诲；如今手持衣袖，高兴地登上了龙门。没有遇到杨得意那样引荐的人，只能抚着自己的文章自惜；既然遇到了钟子期这样的知音，弹一曲流水又有什么可羞愧的？\n唉！美好的地方不会永远，盛大的宴会难以再逢；兰亭的集会已成往事，金谷园也成了废墟。临别赠言，有幸承受这盛大的饯行之恩；登高作赋，是希望仰赖在座诸公。我大胆竭尽浅陋的心怀，恭敬地写下这篇短序；大家一同赋诗，四韵都已完成。请诸位挥洒像潘岳、陆机那样的文采吧。"],
    [28, "guwen-gwj-94", "public-domain", "白闻天下谈士相聚而言曰「生不用封万户侯但愿一识韩荆州」何令人之景慕一至于此耶岂不以有周公之风躬吐握之事使海内豪俊奔走而归之一登龙门则声价十倍所以龙蟠凤逸之士皆欲收名定价于君侯愿君侯不以富贵而骄之寒贱而忽之则三千之中有毛遂使白得颖脱而出即其人焉白陇西布衣流落楚汉十五好剑术遍干诸侯三十成文章历抵卿相虽长不满七尺而心雄万夫皆王公大人许与气义此畴曩心迹安敢不尽于君侯哉君侯制作侔神明德行动天地笔参造化学究天人幸愿开张心颜不以长揖见拒必若接之以高宴纵之以清谈请日试万言倚马可待今天下以君侯为文章之司命人物之权衡一经品题便作佳士而君侯何惜阶前盈尺之地不使白扬眉吐气激昂青云耶昔王子师为豫州未下车即辟荀慈明既下车又辟孔文举山涛作冀州甄拔三十余人或为侍中尚书先代所美而君侯亦荐一严协律入为秘书郎中间崔宗之房习祖黎昕许莹之徒或以才名见知或以清白见赏白每观其衔恩抚躬忠义奋发以此感激知君侯推赤心于诸贤腹中所以不归他人而愿委身国士倘急难有用敢效微躯且人非尧舜谁能尽善白谟猷筹画安能自矜至于制作积成卷轴则欲尘秽视听恐雕虫小技不合大人若赐观刍荛请给纸墨兼之书人然后退扫闲轩缮写呈上庶青萍结绿长价于薛卞之门幸惟下流大开奖饰惟君侯图之", "李白听说天下善谈的士人聚在一起说：「生不用封万户侯，但愿一识韩荆州。」为什么使人景仰羡慕，竟到这种地步呢！难道不是因为您有周公的风范，亲身实行吐哺握发之事，使海内的豪杰俊才，奔走而归附您，一登龙门，就声价十倍。所以像龙蟠凤逸的士人，都想在君侯这里收取名声、确定身价。希望君侯不因富贵而对他们骄傲，不因寒贱而忽视他们，那么在三千门客之中就有毛遂，让李白得以脱颖而出，就是那个人了。\n李白是陇西的平民，流落在楚、汉之地。十五岁喜好剑术，遍访诸侯；三十岁成就文章，逐一拜访卿相。虽然身高不满七尺，而心雄万夫。都被王公大人赞许为有气义。这些往日的心迹，怎么敢不全部向君侯陈述呢！\n君侯的著作比拟神明，德行感动天地，文笔参合造化，学问穷究天人。希望您开颜相见，不要因为长揖而不接见。如果一定要用盛宴接待我，让我纵情清谈，请让我一天试写万言，倚马可待。如今天下把君侯看作文章的司命、人物的权衡，一经品评，便成为佳士。而君侯何必吝惜阶前盈尺的地方，不让李白扬眉吐气、激昂青云呢？\n从前王子师做豫州，还没有下车，就征召荀慈明；下车之后，又征召孔文举。山涛做冀州，甄拔三十多人，有的做了侍中、尚书，为前代所称美。而君侯也推荐过一位严协律，入朝做秘书郎；中间崔宗之、房习祖、黎昕、许莹这些人，有的以才名被赏识，有的以清白被嘉许。李白每每看到他们感念恩德、抚躬自省，忠义奋发，因此感动，知道君侯向诸位贤者推心置腹，所以不归附别人，而愿意委身于国士。倘若急难时有用，敢献出微贱之躯。\n况且人不是尧舜，谁能尽善？李白的谋略筹划，怎么能自夸？至于著作，积累成卷轴，就想拿来玷污您的视听，只怕是雕虫小技，不合大人的意。如果赐予观看草野之见，请给我纸墨，并派抄写的人，然后退下打扫空屋，誊写呈上。或许青萍剑、结绿玉，能在薛烛、卞和的门下增值。希望您垂念下流，大开奖饰，请君侯考虑。"],
    [29, "guwen-gwj-95", "public-domain", "夫天地者万物之逆旅也光阴者百代之过客也而浮生若梦为欢几何古人秉烛夜游良有以也况阳春召我以烟景大块假我以文章会桃花之芳园序天伦之乐事群季俊秀皆为惠连吾人咏歌独惭康乐幽赏未已高谈转清开琼筵以坐花飞羽觞而醉月不有佳咏何伸雅怀如诗不成罚依金谷酒数", "天地是万物的旅舍；光阴是百代的过客。而浮生如梦，为欢能有多少？古人手持蜡烛夜间出游，确实有道理。何况温暖的春天用烟景召唤我，大地把文采借给我。相聚在桃花的芳园，叙说天伦的乐事。诸位弟弟俊秀，都是谢惠连；我吟咏歌唱，独愧不如谢康乐。幽赏还没有结束，高谈转向清雅。摆开琼筵坐在花间，飞传羽觞醉于月下。没有佳作，怎么能抒发高雅的情怀？如果作诗不成，就按金谷园的罚酒之数来罚。"],
    [30, "guwen-gwj-96", "public-domain", "浩浩乎平沙无垠敻不见人河水萦带群山纠纷黯兮惨悴风悲日曛蓬断草枯凛若霜晨鸟飞不下兽铤亡群亭长告余曰「此古战场也常覆三军往往鬼哭天阴则闻」伤心哉秦欤汉欤将近代欤吾闻夫齐魏徭戍荆韩召募万里奔走连年暴露沙草晨牧河冰夜渡地阔天长不知归路寄身锋刃腷臆谁诉秦汉而还多事四夷中州耗斁无世无之古称戎夏不抗王师文教失宣武臣用奇奇兵有异于仁义王道迂阔而莫为呜呼噫嘻吾想夫北风振漠胡兵伺便主将骄敌期门受战野竖旄旗川回组练法重心骇威尊命贱利镞穿骨惊沙入面主客相搏山川震眩声析江河势崩雷电至若穷阴凝闭凛冽海隅积雪没胫坚冰在须鸷鸟休巢征马踟蹰缯纩无温堕指裂肤当此苦寒天假强胡凭陵杀气以相剪屠径截辎重横攻士卒都尉新降将军覆没尸填巨港之岸血满长城之窟无贵无贱同为枯骨可胜言哉鼓衰兮力尽矢竭兮弦绝白刃交兮宝刀折两军蹙兮生死决降矣哉终身夷狄战矣哉暴骨沙砾鸟无声兮山寂寂夜正长兮风淅淅魂魄结兮天沉沉鬼神聚兮云幂幂日光寒兮草短月色苦兮霜白伤心惨目有如是耶吾闻之牧用赵卒大破林胡开地千里遁逃匈奴汉倾天下财殚力痡任人而已其在多乎周逐猃狁北至太原既城朔方全师而还饮至策勋和乐且闲穆穆棣棣君臣之间秦起长城竟海为关荼毒生灵万里朱殷汉击匈奴虽得阴山枕骸遍野功不补患苍苍蒸民谁无父母提携捧负畏其不寿谁无兄弟如足如手谁无夫妇如宾如友生也何恩杀之何咎其存其没家莫闻知人或有言将信将疑悁悁心目寤寐见之布奠倾觞哭望天涯天地为愁草木凄悲吊祭不至精魂何依必有凶年人其流离呜呼噫嘻时耶命耶从古如斯为之奈何守在四夷", "浩瀚啊平坦的沙原无边无际，辽远看不见人。河水像带子环绕，群山交错纠纷。暗淡啊凄惨憔悴，风悲日昏。蓬草断折草木枯干，凛冽如同霜晨。鸟儿飞过不落，野兽狂奔失群。亭长告诉我说：「这是古战场，常常覆没三军。往往有鬼哭，天阴时就能听到。」伤心啊！是秦呢汉呢？还是近代呢？\n我听说齐国魏国征发戍役，楚国韩国招募兵士。万里奔走，连年暴露在野外。沙草中早晨放牧，河冰上夜里渡河。地阔天长，不知归路。寄身于锋刃之间，郁结的心情向谁诉说？秦汉以来，多与四夷有事。中原损耗败坏，没有一代没有。古人称戎夏各族，不抗拒王师。文教失去宣扬，武臣使用奇计。奇兵不同于仁义，王道迂阔而无人去做。唉呀！\n我想那北风震荡沙漠，胡兵窥伺机会。主将轻敌，在期门接受挑战。田野竖起旄旗，河边回绕组练。军法严重心惊胆战，威权尊贵性命低贱。利箭穿骨，惊沙扑脸。主客相搏，山川震动昏眩。声音撕裂江河，气势崩塌雷电。至于严冬阴云凝结，凛冽在海边，积雪没到小腿，坚冰结在胡须。猛禽休巢，战马踟蹰。丝绵没有温暖，冻掉手指、冻裂皮肤。在这苦寒之时，上天帮助强胡，凭借杀气，来互相屠宰。径直截击辎重，横击士卒。都尉刚刚投降，将军已经覆没。尸体填满巨港的岸边，鲜血流满长城下的洞穴。无论贵贱，同样成为枯骨。哪里说得完呢！鼓声衰弱啊力气用尽，箭矢枯竭啊弓弦断绝，白刃相交啊宝刀折断，两军迫近啊生死决于一旦。投降吧？终身做夷狄。作战吧？尸骨暴露在沙砾。鸟无声啊山寂寂，夜正长啊风淅淅。魂魄凝结啊天沉沉，鬼神聚集啊云幂幂。日光寒冷啊草短，月色凄苦啊霜白。伤心惨目，有像这样的吗！\n我听说：李牧用赵国的士卒，大破林胡，开辟千里土地，使匈奴逃遁。汉朝倾尽天下之力，财尽力疲。在于用人而已，哪里在于多呢？周朝驱逐猃狁，北到太原。既已筑城朔方，全军而还。饮酒记功，和乐安闲。肃穆雍容，君臣之间。秦朝修筑长城，直到海边设立关塞。荼毒生灵，万里血红。汉朝攻打匈奴，虽然得到阴山，却枕骸遍野，功不补患。\n苍苍众民，谁没有父母？提携捧抱，怕他不长寿。谁没有兄弟？如同手足。谁没有夫妇？如同宾客朋友。活着有什么恩，杀死有什么罪？他们活着还是死去，家里都不知道。有人传说，将信将疑。忧闷在心，日夜梦见。摆酒祭奠，望天涯痛哭。天地为之忧愁，草木为之凄悲。吊祭不到，精魂依附什么？必定有凶年，人们将要流离。唉呀！是时运呢命运呢？从古如此！怎么办？只有守在四夷。"],
    [31, "poems-cz7-23", "school", "山不在高有仙则名水不在深有龙则灵斯是陋室惟吾德馨苔痕上阶绿草色入帘青谈笑有鸿儒往来无白丁可以调素琴阅金经无丝竹之乱耳无案牍之劳形南阳诸葛庐西蜀子云亭孔子云何陋之有", "山不在于高，有了神仙就有名。水不在于深，有了龙就显灵。这是简陋的屋子，只因我的品德高尚就不觉得简陋了。苔痕蔓延到台阶上，一片碧绿；草色映入竹帘，满眼青翠。说笑谈天的都是博学的人，来往的没有浅薄的人。可以弹奏不加装饰的琴，阅读珍贵的佛经。没有嘈杂的音乐扰乱耳朵，没有官府公文使身体劳累。南阳诸葛亮的草庐，西蜀扬子云的亭子。孔子说：有什么简陋的呢？"],
    [32, "guwen-gwj-98", "school", "六王毕四海一蜀山兀阿房出覆压三百余里隔离天日骊山北构而西折直走咸阳二川溶溶流入宫墙五步一楼十步一阁廊腰缦回檐牙高啄各抱地势钩心斗角盘盘焉囷囷焉蜂房水涡矗不知其几千万落长桥卧波未云何龙复道行空不霁何虹高低冥迷不知西东歌台暖响春光融融舞殿冷袖风雨凄凄一日之内一宫之间而气候不齐妃嫔媵嫱王子皇孙辞楼下殿辇来于秦朝歌夜弦为秦宫人明星荧荧开妆镜也绿云扰扰梳晓鬟也渭流涨腻弃脂水也烟斜雾横焚椒兰也雷霆乍惊宫车过也辘辘远听杳不知其所之也一肌一容尽态极妍缦立远视而望幸焉有不见者三十六年燕赵之收藏韩魏之经营齐楚之精英几世几年剽掠其人倚叠如山一旦不能有输来其间鼎铛玉石金块珠砾弃掷逦迤秦人视之亦不甚惜嗟乎一人之心千万人之心也秦爱纷奢人亦念其家奈何取之尽锱铢用之如泥沙使负栋之柱多于南亩之农夫架梁之椽多于机上之工女钉头磷磷多于在庾之粟粒瓦缝参差多于周身之帛缕直栏横槛多于九土之城郭管弦呕哑多于市人之言语使天下之人不敢言而敢怒独夫之心日益骄固戍卒叫函谷举楚人一炬可怜焦土呜呼灭六国者六国也非秦也族秦者秦也非天下也嗟夫使六国各爱其人则足以拒秦使秦复爱六国之人则递三世可至万世而为君谁得而族灭也秦人不暇自哀而后人哀之后人哀之而不鉴之亦使后人而复哀后人也", "六国灭亡，天下统一，蜀地的山林被砍光，阿房宫建了起来。它覆盖三百多里，遮蔽了天日。从骊山北面建起，曲折向西，一直通到咸阳。渭水、樊川浩浩荡荡，流入宫墙。五步一座楼，十步一座阁；走廊像丝绸一样回环曲折，屋檐像鸟嘴一样向高处啄去；各随地势而建，屋角互相对峙如钩心斗角。盘旋曲折，像蜂房、像水涡，高高矗立，不知有几千万座。长桥横卧在水波上，没有云怎么会有龙？复道凌空而行，没有雨过天晴怎么会有虹？高低迷蒙，分不清东西南北。歌台上歌声温暖，春光融融；舞殿里舞袖生寒，风雨凄凄。一天之内，一宫之中，气候却不一样。\n六国的妃嫔媵嫱、王子皇孙，辞别了自己的楼阁宫殿，被用车送到秦国。早晚唱歌弹琴，成为秦国的宫人。明星闪烁，是她们打开了梳妆的镜子；绿云纷乱，是她们早晨在梳头；渭水涨起一层油腻，是她们倒掉的脂水；烟雾斜飞横绕，是她们在烧椒兰香料。雷霆忽然惊响，是宫车经过；车声辘辘远远听去，不知驶向何处。每一处肌肤、每一种姿容，都极尽娇媚，久久地站着远望，盼望皇帝临幸。有的三十六年都没有见过皇帝。\n燕国赵国的收藏，韩国魏国的经营，齐国楚国的精华，多少世代多少年，从人民那里掠夺来，堆积如山。一旦不能保有，都运到这里来。宝鼎被当作铁锅，美玉被当作石头，黄金被当作土块，珍珠被当作沙砾，丢弃得连续不断，秦人看着它们，也不很爱惜。\n唉！一个人的心，就是千万人的心。秦始皇喜爱繁华奢侈，别人也顾念自己的家。为什么搜刮时一分一厘都不放过，使用时却像泥沙一样？使得支撑大梁的柱子，比田里的农夫还多；架梁的椽子，比织机上的女工还多；钉头闪闪，比粮仓里的谷粒还多；瓦缝参差，比全身衣服的丝线还多；栏杆纵横，比九州的城郭还多；管弦嘈杂，比集市上人的言语还多。使天下的人，不敢说话却敢愤怒。独夫的心，一天比一天骄傲顽固。戍卒一声呼号，函谷关就被攻下，楚人一把火，可怜的阿房宫化成焦土！\n唉！灭亡六国的是六国自己，不是秦国；灭掉秦国的是秦国自己，不是天下人。唉！如果六国各自爱护自己的人民，就足以抵抗秦国；如果秦国又能爱护六国的人民，就可以传位三代直到万世做君主，谁能灭掉它呢？秦人来不及哀叹自己，而后人哀叹他们；后人哀叹却不引以为鉴，也会使更后的人再哀叹后人啊。"],
    [33, "guwen-gwj-99", "public-domain", "博爱之谓仁行而宜之之谓义由是而之焉之谓道足乎己无待于外之谓德仁与义为定名道与德为虚位故道有君子小人而德有凶有吉老子之小仁义非毁之也其见者小也坐井而观天曰天小者非天小也彼以煦煦为仁孑孑为义其小之也则宜其所谓道道其所道非吾所谓道也其所谓德德其所德非吾所谓德也凡吾所谓道德云者合仁与义言之也天下之公言也老子之所谓道德云者去仁与义言之也一人之私言也周道衰孔子没火于秦黄老于汉佛于晋魏梁隋之间其言道德仁义者不入于杨则入于墨不入于老则入于佛入于彼必出于此入者主之出者奴之入者附之出者污之噫后之人其欲闻仁义道德之说孰从而听之老者曰「孔子吾师之弟子也」佛者曰「孔子吾师之弟子也」为孔子者习闻其说乐其诞而自小也亦曰「吾师亦尝师之」云尔不惟举之于口而又笔之于书噫后之人虽欲闻仁义道德之说其孰从而求之甚矣人之好怪也不求其端不讯其末惟怪之欲闻古之为民者四今之为民者六古之教者处其一今之教者处其三农之家一而食粟之家六工之家一而用器之家六贾之家一而资焉之家六奈之何民不穷且盗也古之时人之害多矣有圣人者立然后教之以相生相养之道为之君为之师驱其虫蛇禽兽而处之中土寒然后为之衣饥然后为之食木处而颠土处而病也然后为之宫室为之工以赡其器用为之贾以通其有无为之医药以济其夭死为之葬埋祭祀以长其恩爱为之礼以次其先后为之乐以宣其湮郁为之政以率其怠倦为之刑以锄其强梗相欺也为之符玺斗斛权衡以信之相夺也为之城郭甲兵以守之害至而为之备患生而为之防今其言曰「圣人不死大盗不止剖斗折衡而民不争」呜呼其亦不思而已矣如古之无圣人人之类灭久矣何也无羽毛鳞介以居寒热也无爪牙以争食也是故君者出令者也臣者行君之令而致之民者也民者出粟米麻丝作器皿通货财以事其上者也君不出令则失其所以为君臣不行君之令而致之民则失其所以为臣民不出粟米麻丝作器皿通货财以事其上则诛今其法曰「必弃而君臣去而父子禁而相生相养之道以求其所谓清净寂灭者」呜呼其亦幸而出于三代之后不见黜于禹汤文武周公孔子也其亦不幸而不出于三代之前不见正于禹汤文武周公孔子也帝之与王其号虽殊其所以为圣一也夏葛而冬裘渴饮而饥食其事虽殊其所以为智一也今其言曰「曷不为太古之无事」是亦责冬之裘者曰「曷不为葛之之易也」责饥之食者曰「曷不为饮之之易也」传曰「古之欲明明德于天下者先治其国欲治其国者先齐其家欲齐其家者先修其身欲修其身者先正其心欲正其心者先诚其意」然则古之所谓正心而诚意者将以有为也今也欲治其心而外天下国家灭其天常子焉而不父其父臣焉而不君其君民焉而不事其事孔子之作春秋也诸侯用夷礼则夷之进于中国则中国之经曰「夷狄之有君不如诸夏之亡」诗曰「戎狄是膺荆舒是惩」今也举夷狄之法而加之先王之教之上几何其不胥而为夷也夫所谓先王之教者何也博爱之谓仁行而宜之之谓义由是而之焉之谓道足乎己无待于外之谓德其文诗书易春秋其法礼乐刑政其民士农工贾其位君臣父子师友宾主昆弟夫妇其服麻丝其居宫室其食粟米果蔬鱼肉其为道易明而其为教易行也是故以之为己则顺而祥以之为人则爱而公以之为心则和而平以之为天下国家无所处而不当是故生则得其情死则尽其常郊焉而天神假庙焉而人鬼飨曰斯道也何道也曰斯吾所谓道也非向所谓老与佛之道也尧以是传之舜舜以是传之禹禹以是传之汤汤以是传之文武周公文武周公传之孔子孔子传之孟轲轲之死不得其传焉荀与扬也择焉而不精语焉而不详由周公而上上而为君故其事行由周公而下下而为臣故其说长然则如之何而可也曰不塞不流不止不行人其人火其书庐其居明先王之道以道之鳏寡孤独废疾者有养也其亦庶乎其可也", "博爱叫做仁，实行得恰当叫做义，由此而前行叫做道，自身充足而不依赖外物叫做德。仁和义是有确定内容的名称，道和德是空泛的位置。所以道有君子之道有小人之道，德有凶德有吉德。老子轻视仁义，不是诋毁它，而是他所见的太小。坐在井里看天，说天小，不是天小。他把和颜悦色当作仁，把孤行独立当作义，他轻视仁义也就可以理解了。他所说的道，是把他所认为的道当作道，不是我们所说的道；他所说的德，是把他所认为的德当作德，不是我们所说的德。凡是我们所说的道德，是合仁与义而言的，是天下公有的说法；老子所说的道德，是去掉仁与义而言的，是一个人的私言。\n周道衰微，孔子去世，秦朝焚书，汉朝崇尚黄老，晋、魏、梁、隋之间崇尚佛教。讲道德仁义的人，不归入杨朱，就归入墨翟；不归入老子，就归入佛家。归入那边，必定背离这边。归入的以之为主，背离的以之为奴；归入的就附和，背离的就污损。唉！后世之人想要听到仁义道德的说法，跟谁去听呢？道家的说：「孔子是我们老师的弟子。」佛家的说：「孔子是我们老师的弟子。」学孔子的人，听惯了这些说法，喜欢它的荒诞而自我轻视，也说「我们老师也曾向他学习」之类。不但说出口，还写在书上。唉！后世之人即使想听仁义道德的说法，又跟谁去探求呢？\n人的喜好怪异真是厉害啊，不探求它的开端，不追问它的末端，只想听怪异之说。古代为民的有四类，如今为民的有六类。古代从事教化的居其一，如今从事教化的居其三。农家一家，而吃粮的有六家；工家一家，而用器的有六家；商家一家，而靠它供给的有六家。怎么能使百姓不穷困而为盗呢？\n古时候，人的祸害很多。有圣人出来，然后教给他们互相生养的道理。为他们立君，为他们立师，驱除虫蛇禽兽使他们住在中原。寒冷才给他们做衣服，饥饿才给他们做食物。在树上住会摔下来，在洞里住会生病，然后给他们造宫室。给他们设工匠来供给器用，给他们设商人来流通有无，给他们设医药来救治夭死，给他们设葬埋祭祀来增长恩爱，给他们设礼来排列先后，给他们设乐来宣泄郁结，给他们设政来督促怠惰，给他们设刑来铲除强横。互相欺骗，就为他们用符玺斗斛权衡来取信；互相争夺，就为他们用城郭甲兵来守卫。祸害到来就为他们防备，患难产生就为他们预防。如今有人说：「圣人不死，大盗不止。剖开斗、折断秤，百姓就不争。」唉！这也是不加思考罢了！如果古代没有圣人，人类早就灭绝了。为什么呢？因为人没有羽毛鳞甲来适应寒暑，没有爪牙来争夺食物。\n所以君主是发布命令的；臣子是执行君主的命令而传达到百姓的；百姓是生产粟米麻丝、制作器皿、流通财货来事奉在上者的。君主不发布命令，就失去作为君主的意义；臣子不执行君主的命令而传达到百姓，就失去作为臣子的意义；百姓不生产粟米麻丝、制作器皿、流通财货来事奉在上者，就要受诛罚。如今他们的法说：「一定要抛弃你们的君臣，去掉你们的父子，禁绝你们互相生养之道，来求得他们所谓的清净寂灭。」唉！他们也是侥幸出于三代之后，不被禹、汤、文、武、周公、孔子所贬黜。他们也是不幸而不出于三代之前，不被禹、汤、文、武、周公、孔子所纠正。\n帝和王，称号虽然不同，他们之所以为圣是一样的。夏天穿葛衣冬天穿皮裘，渴了喝水饿了吃饭，事情虽然不同，他们之所以为智是一样的。如今有人说：「为什么不像太古那样无为无事？」这就好比责问冬天穿皮裘的人说：「为什么不做那简单的葛衣呢？」责问饿了吃饭的人说：「为什么不喝那简单的水呢？」古书上说：「古代想要在天下彰明美德的人，先治理他的国家；想要治理他的国家，先整齐他的家族；想要整齐他的家族，先修养他自身；想要修养他自身，先端正他的心意；想要端正他的心意，先使他的意念真诚。」那么古代所谓正心诚意，是要有所作为的。如今却想只治他的心而把天下国家排除在外，灭绝他的天常，做儿子的不把父亲当父亲，做臣子的不把君主当君主，做百姓的不干自己的事。孔子作《春秋》，诸侯用了夷礼就把它当夷狄看待，进于中国的就以中国看待。经上说：「夷狄之有君，不如诸夏之亡。」《诗经》说：「戎狄是膺，荆舒是惩。」如今却推举夷狄的教法，把它加在先王的教化之上，几乎要不都变成夷狄了吗？\n所谓先王的教化，是什么呢？博爱叫做仁，实行得恰当叫做义，由此而前行叫做道，自身充足而不依赖外物叫做德。它的典籍是《诗》《书》《易》《春秋》；它的法度是礼、乐、刑、政；它的百姓是士、农、工、贾；它的名位是君臣、父子、师友、宾主、昆弟、夫妇；它的衣服是麻、丝；它的居处是宫、室；它的食物是粟米、果蔬、鱼肉。它作为道容易明白，它作为教化容易施行。所以用它来修养自己，就顺遂而吉祥；用它来待人，就博爱而公正；用它来正心，就和谐而平正；用它来治理天下国家，无处不恰当。所以活着能合乎情理，死了能尽其常道，郊祭而天神降临，庙祭而人鬼享用。有人问：这个道，是什么道呢？答：这是我们所说的道，不是前面所说的老子和佛家的道。尧把它传给舜，舜把它传给禹，禹把它传给汤，汤把它传给文王、武王、周公，文王、武王、周公传给孔子，孔子传给孟轲，孟轲死后，就得不到传承了。荀子和扬雄，有所选择而不精，有所论说而不详。从周公以上，在上的是君主，所以他们的政事得以施行；从周公以下，在下的是臣子，所以他们的学说流传久远。那么怎么办才可以呢？答：不堵塞就不流动，不禁止就不施行。使他们成为真正的人，烧掉他们的书，把他们的寺观改成民居，彰明先王之道来引导他们，使鳏寡孤独残废有病的人都有供养，那也就差不多了。"],
    [34, "guwen-gwj-100", "public-domain", "古之君子其责己也重以周其待人也轻以约重以周故不怠轻以约故人乐为善闻古之人有舜者其为人也仁义人也求其所以为舜者责于己曰「彼人也予人也彼能是而我乃不能是」早夜以思去其不如舜者就其如舜者闻古之人有周公者其为人也多才与艺人也求其所以为周公者责于己曰「彼人也予人也彼能是而我乃不能是」早夜以思去其不如周公者就其如周公者舜大圣人也后世无及焉周公大圣人也后世无及焉是人也乃曰「不如舜不如周公吾之病也」是不亦责于身者重以周乎其于人也曰「彼人也能有是是足为良人矣能善是是足为艺人矣」取其一不责其二即其新不究其旧恐恐然惟惧其人之不得为善之利一善易修也一艺易能也其于人也乃曰「能有是是亦足矣」曰「能善是是亦足矣」不亦待于人者轻以约乎今之君子则不然其责人也详其待己也廉详故人难于为善廉故自取也少己未有善曰「我善是是亦足矣」己未有能曰「我能是是亦足矣」外以欺于人内以欺于心未少有得而止矣不亦待其身者已廉乎其于人也曰「彼虽能是其人不足称也彼虽善是其用不足称也」举其一不计其十究其旧不图其新恐恐然惟惧其人之有闻也是不亦责于人者已详乎夫是之谓不以众人待其身而以圣人望于人吾未见其尊己也虽然为是者有本有原怠与忌之谓也怠者不能修而忌者畏人修吾尝试之矣尝试语于众曰「某良士某良士」其应者必其人之与也不然则其所疏远不与同其利者也不然则其畏也不若是强者必怒于言懦者必怒于色矣又尝语于众曰「某非良士某非良士」其不应者必其人之与也不然则其所疏远不与同其利者也不然则其畏也不若是强者必说于言懦者必说于色矣是故事修而谤兴德高而毁来呜呼士之处此世而望名誉之光道德之行难已将有作于上者得吾说而存之其国家可几而理欤", "古代的君子，他们要求自己严格而周全，他们对待别人宽容而简约。严格而周全，所以不懈怠；宽容而简约，所以别人乐于做好事。听说古人有舜，他的为人，是仁义之人。探求他之所以成为舜的原因，要求自己说：「他是人，我也是人。他能这样，而我却不能这样！」早晚思考，去掉不如舜的地方，靠近像舜的地方。听说古人有周公，他的为人，是多才多艺之人。探求他之所以成为周公的原因，要求自己说：「他是人，我也是人。他能这样，而我却不能这样！」早晚思考，去掉不如周公的地方，靠近像周公的地方。舜是大圣人，后世没有能赶上的；周公是大圣人，后世没有能赶上的。这个人却说：「不如舜，不如周公，是我的毛病。」这不就是要求自己严格而周全吗！他对待别人，说：「那个人能这样，就足以成为好人了；能擅长这个，就足以成为有技艺的人了。」取他的一点，不责备他的第二点；就他的现在，不追究他的过去。诚惶诚恐地只怕那个人得不到做好事的益处。一件好事容易做到，一门技艺容易学会，他对待别人，却说：「能这样，也就够了。」说：「能擅长这个，也就够了。」这不就是对待别人宽容而简约吗？\n如今的君子却不是这样。他们要求别人详尽，对待自己简略。详尽，所以别人难以做好事；简略，所以自己所得很少。自己没有善行，却说：「我擅长这个，这就够了。」自己没有才能，却说：「我能这样，这就够了。」对外欺骗别人，对内欺骗自己，还没有一点收获就停止了。这不就是对待自己太简略了吗？他们对待别人，说：「他虽然能这样，但这个人不值得称道；他虽然擅长这个，但这用途不值得称道。」举出他的一点，不计他的十点；追究他的过去，不考虑他的现在。诚惶诚恐地只怕那个人有名声。这不就是要求别人太详尽了吗？这就叫做不用对待众人的标准对待自己，而用圣人的标准要求别人，我看不出这是尊重自己。\n虽然如此，这样做的人是有根源的，就是怠惰和嫉妒。怠惰的人不能修养，嫉妒的人害怕别人修养。我曾经试过，试着对众人说：「某人是良士，某人是良士。」那些应和的人，必定是那个人的朋友；不然，就是他所疏远、与他没有共同利益的人；不然，就是畏惧他的人。如果不是这样，刚强的人必定在言语上发怒，懦弱的人必定在脸色上发怒。又曾经对众人说：「某人不是良士，某人不是良士。」那些不应和的人，必定是那个人的朋友；不然，就是他所疏远、与他没有共同利益的人；不然，就是畏惧他的人。如果不是这样，刚强的人必定在言语上喜悦，懦弱的人必定在脸色上喜悦。所以事业有成就诽谤就兴起，德行高尚诋毁就到来。唉！士人处在这个世上，而希望名誉显耀、道德施行，难啊！\n将要有所作为的在上位者，听到我的说法而记住它，他的国家大概可以治理好了吧！"],
    [35, "guwen-gwj-101", "public-domain", "麟之为灵昭昭也咏于诗书于春秋杂出于传记百家之书虽妇人小子皆知其为祥也然麟之为物不畜于家不恒有于天下其为形也不类非若马牛犬豕豺狼麋鹿然然则虽有麟不可知其为麟也角者吾知其为牛鬣者吾知其为马犬豕豺狼麋鹿吾知其为犬豕豺狼麋鹿惟麟也不可知不可知则其谓之不祥也亦宜虽然麟之出必有圣人在乎位麟为圣人出也圣人者必知麟麟之果不为不祥也又曰麟之所以为麟者以德不以形若麟之出不待圣人则谓之不祥也亦宜", "麒麟作为灵物，是明白显著的。它被歌咏于《诗经》，被记载于《春秋》，杂见于传记百家的书中，即使是妇孺都知道它是吉祥的。\n然而麒麟作为一种动物，不畜养在家里，不常存在于天下。它的形状不伦不类，不像马牛犬猪豺狼麋鹿那样。那么即使有麒麟，也不能知道它是麒麟。有角的我知道它是牛，有鬣的我知道它是马，犬猪豺狼麋鹿，我知道它们是犬猪豺狼麋鹿。只有麒麟，不能知道。不能知道，那么说它不吉祥也就可以理解了。\n虽然如此，麒麟的出现，必定有圣人在位。麒麟是为圣人而出现的。圣人必定知道麒麟。麒麟果然不是不吉祥的。\n又说：麒麟之所以为麒麟，在于德行而不在于形状。如果麒麟的出现不等待圣人，那么说它不吉祥也就可以理解了。"],
    [38, "guwen-gwj-35", "public-domain", "穆王将征犬戎祭公谋父谏曰「不可先王耀德不观兵夫兵戢而时动动则威观则玩玩则无震是故周文公之颂曰『载戢干戈载櫜弓矢我求懿德肆于时夏允王保之』先王之于民也茂正其德而厚其性阜其财求而利其器用明利害之乡以文修之使务利而避害怀德而畏威故能保世以滋大」「昔我先王世后稷以服事虞夏及夏之衰也弃稷不务我先王不窋用失其官而自窜于戎狄之间不敢怠业时序其德纂修其绪修其训典朝夕恪勤守以敦笃奉以忠信奕世载德不忝前人至于武王昭前之光明而加之以慈和事神保民莫不欣喜商王帝辛大恶于民庶民弗忍欣戴武王以致戎于商牧是先王非务武也勤恤民隐而除其害也」「夫先王之制邦内甸服邦外侯服侯卫宾服蛮夷要服戎狄荒服甸服者祭侯服者祀宾服者享要服者贡荒服者王日祭月祀时享岁贡终王先王之训也有不祭则修意有不祀则修言有不享则修文有不贡则修名有不王则修德序成而有不至则修刑于是乎有刑不祭伐不祀征不享让不贡告不王于是乎有刑罚之辟有攻伐之兵有征讨之备有威让之令有文告之辞布令陈辞而又不至则又增修于德无勤民于远是以近无不听远无不服」「今自大毕伯士之终也犬戎氏以其职来王天子曰『予必以不享征之且观之兵』其无乃废先王之训而王几顿乎吾闻犬戎树惇帅旧德而守终纯固其有以御我矣」王不听遂征之得四白狼四白鹿以归自是荒服者不至", "周穆王准备征讨犬戎，祭公谋父劝谏说：「不行。先王彰显德行而不炫耀武力。武力是用来收藏的，按时动用，一动就有威势；炫耀就会被轻慢，被轻慢就没有震慑力。所以周文公的《颂》说：『收藏起干戈，收起弓箭。我求取美好的德行，施行于这华夏，君王确实能保住它。』先王对百姓，是正大他们的德行、丰厚他们的性情，增加他们的财货、便利他们的器用，让他们明白利害的方向，用礼法来治理他们，使他们致力于有利的一面而避开有害的一面，感念德行而畏惧威势，所以能保住世代相传的基业而且越发壮大。\n「从前我们的先王世代做后稷之官，事奉虞舜、夏朝。到夏朝衰微，废弃农官不致力于农业，我们的先王不窋因此失掉官职，自己流窜到戎、狄之间。他不敢懈怠事业，时时申明德行，继承前人的事业，修明教训法典，早晚恭谨勤勉，用敦厚笃实来守住它，用忠信来奉行它。一代代继承德行，不辱没前人。到了武王，昭明前代的功业而又加上慈爱和顺，事奉神灵、保护百姓，没有人不欢喜。商王帝辛对百姓极为邪恶，百姓不能忍受，欢喜拥戴武王，因此在商都郊外的牧野交战。这是先王并非致力于武力，而是勤恳体恤百姓的隐痛、为他们除害。\n「先王的制度：王畿之内是甸服，王畿之外是侯服，侯、卫之地是宾服，蛮、夷之地是要服，戎、狄之地是荒服。甸服的供给日祭，侯服的供给月祀，宾服的供给时享，要服的供给岁贡，荒服的来朝见王。日祭、月祀、时享、岁贡、终身朝见一次，这是先王的训导。有不来日祭的就修明心意，有不来月祀的就修明言辞，有不来时享的就修明文教，有不来岁贡的就修明名分，有不来朝见的就修明德行，这些都做了还有不来的就修明刑罚。于是有惩罚不来日祭的，攻打不来月祀的，征讨不来时享的，责备不来岁贡的，告谕不来朝见的。于是有刑罚的条款，有攻伐的军队，有征讨的准备，有责让的政令，有文告的辞令。颁布政令、陈述辞令之后还不来，就再进一步修明德行，不让百姓在远方劳苦。因此近处的人没有不听从的，远处的人没有不归服的。\n「自从大毕、伯士去世之后，犬戎氏都按他们的职分来朝见。天子说：『我一定要因为不来时享去征讨他们，并且向他们炫耀武力。』这恐怕是废弃先王的训导，王业差不多要败坏了吧？我听说犬戎树敦厚之德，遵循先王的旧德而坚守不移，他们有办法抵御我们了。」\n穆王不听，于是征讨犬戎，只得到四只白狼、四只白鹿回来。从此荒服之地的人不再来朝见。"],
    [39, "guwen-gwj-171", "", "厉王虐国人谤王召公告曰「民不堪命矣」王怒得卫巫使监谤者以告则杀之国人莫敢言道路以目王喜告召公曰「吾能弭谤矣乃不敢言」召公曰「是障之也防民之口甚于防川川壅而溃伤人必多民亦如之是故为川者决之使导为民者宣之使言故天子听政使公卿至于列士献诗瞽献曲史献书师箴瞍赋矇诵百工谏庶人传语近臣尽规亲戚补察瞽史教诲耆艾修之而后王斟酌焉是以事行而不悖民之有口也犹土之有山川也财用于是乎出犹其有原隰衍沃也衣食于是乎生口之宣言也善败于是乎兴行善而备败所以阜财用衣食者也夫民虑之于心而宣之于口成而行之胡可壅也若壅其口其与能几何」王弗听于是国人莫敢出言三年乃流王于彘", "周厉王暴虐，国人都指责他。召公告诉他说：「百姓受不了您的政令了！」厉王发怒，找来卫国的巫师，让他监视指责自己的人。一经告发，就把人杀掉。国人没有谁敢说话，路上相遇只用眼睛示意。\n厉王很高兴，告诉召公说：「我能消除指责了，他们终于不敢说话了。」召公说：「这是堵塞它啊。堵住百姓的嘴，比堵住河水还危险。河水堵塞而溃决，伤人一定很多，百姓也是这样。所以治水的人要疏通河道让它畅通，治理百姓的人要开导他们让他们说话。因此天子处理政事，让公卿直到列士献上讽谏的诗，乐师献上乐曲，史官献上史籍，少师献上箴言，无眸子的盲人吟咏，有眸子的盲人诵读，百工进谏，平民的话传达到天子那里，近臣尽规劝之责，亲戚补过失、察是非，乐师史官教诲，年高望重的人整理，然后天子斟酌取舍，因此政事施行而不违背情理。百姓有嘴，就像土地有山川，财物用度从这里产生；又像那有高原、低地、平坦、肥沃的田地，衣食从这里产生。嘴发表言论，政事的好坏就由此显现。施行好的而防范坏的，这是用来增多财物用度衣食的办法。百姓在心里考虑而在嘴上说出来，考虑成熟就付诸实行，怎么能堵塞呢？如果堵住他们的嘴，那能维持多久呢？」\n厉王不听，于是国人没有谁敢说话。三年之后，就把厉王流放到彘地。"],
    [40, "guwen-gwj-37", "public-domain", "晋文公既定襄王于郏王劳之以地辞请隧焉王弗许曰「昔我先王之有天下也规方千里以为甸服以供上帝山川百神之祀以备百姓兆民之用以待不庭不虞之患其余以均分公侯伯子男使各有宁宇以顺及天地无逢其灾害先王岂有赖焉内官不过九御外官不过九品足以供给神祇而已岂敢厌纵其耳目心腹以乱百度亦唯是死生之服物采章以临长百姓而轻重布之王何异之有」「今天降祸灾于周室余一人仅亦守府又不佞以勤叔父而班先王之大物以赏私德其叔父实应且憎以非余一人余一人岂敢有爱先民有言曰『改玉改行』叔父若能光裕大德更姓改物以创制天下自显庸也而缩取备物以镇抚百姓余一人其流辟于裔土何辞之与有若犹是姬姓也尚将列为公侯以复先王之职大物其未可改也叔父其懋昭明德物将自至余何敢以私劳变前之大章以忝天下其若先王与百姓何何政令之为也若不然叔父有地而隧焉余安能知之」文公遂不敢请受地而还", "晋文公在郏地安定了周襄王的王位之后，襄王用土地慰劳他，文公推辞，请求死后用天子的隧葬礼。襄王不答应，说：「从前我们的先王拥有天下，划定方圆千里的土地作为甸服，用来供给上帝、山川、百神的祭祀，用来备办百姓万民的用度，用来应付不来朝见和有意外的事变。其余的土地平均分给公、侯、伯、子、男，使他们各自有安定的居处，以顺应天地，不遭遇灾害，先王难道有什么私利吗？内宫不过九位女御，外官不过九等品级，足够供给神灵而已，怎敢放纵自己的耳目心腹的欲望来扰乱各种法度？也只有这生死的衣服器物文采，用来君临百姓而分别轻重，此外天子还有什么不同呢？\n「如今上天降祸灾给周王室，我仅仅能守住府库，又不才而使叔父劳苦，如果分出先王的大礼来赏赐私人的恩德，叔父接受了也会憎恶，责备我，我怎敢吝惜？前人有话说：『改了佩玉就改了行步的仪节。』叔父如果能发扬光大德行，更改姓氏、变换制度，来创制天下，自己显扬声名，就取用完备的礼制来镇抚百姓，我即使流放到边远之地，又有什么话可说？如果还是姬姓，还将列在公侯之位，恢复先王的职分，那么这大礼是不能更改的。叔父努力昭明美德，大礼自会到来，我怎敢因为私人的劳绩改变前代的大典章，来辱没天下，那对先王和百姓怎么交代？还怎么施行政令呢？如果不这样，叔父有自己的土地，在那里用隧葬，我怎么能知道呢？」\n文公于是不敢再请求，接受了土地就回去了。"],
    [41, "guwen-gwj-38", "public-domain", "定王使单襄公聘于宋遂假道于陈以聘于楚火朝觌矣道茀不可行也候不在疆司空不视涂泽不陂川不梁野有庾积场功未毕道无列树垦田若蓺膳宰不致饩司里不授馆国无寄寓县无施舍民将筑台于夏氏及陈陈灵公与孔宁仪行父南冠以如夏氏留宾不见单子归告王曰「陈侯不有大咎国必亡」王曰「何故」对曰「夫辰角见而雨毕天根见而水涸本见而草木节解驷见而陨霜火见而清风戒寒故先王之教曰『雨毕而除道水涸而成梁草木节解而备藏陨霜而冬裘具清风至而修城郭宫室』故夏令曰『九月除道十月成梁』其时儆曰『收而场功偫而畚挶营室之中土功其始火之初见期于司里』此先王所以不用财贿而广施德于天下者也」「今陈国火朝觌矣而道路若塞野场若弃泽不陂障川无舟梁是废先王之教也」「周制有之曰『列树以表道立鄙食以守路国有郊牧疆有寓望薮有圃草囿有林池所以御灾也其余无非谷土民无悬耜野无奥草不夺民时不蔑民功有优无匮有逸无罢国有班事县有序民』今陈国道路不可知田在草间功成而不收民罢于逸乐是弃先王之法制也」「周之秩官有之曰『敌国宾至关尹以告行理以节逆之候人为导卿出郊劳门尹除门宗祝执祀司里授馆司徒具徒司空视涂司寇诘奸虞人入材甸人积薪火师监燎水师监濯膳宰致餐廪人献饩司马陈刍工人展车百官各以物至宾入如归是故小大莫不怀爱其贵国之宾至则以班加一等益虔至于王使则皆官正莅事上卿监之若王巡守则君亲监之』今虽朝也不才有分族于周承王命以为过宾于陈而司事莫至是蔑先王之官也」「先王之令有之曰『天道赏善而罚淫故凡我造国无从非彝无即慆淫各守尔典以承天休』今陈侯不念胤续之常弃其伉俪妃嫔而帅其卿佐以淫于夏氏不亦渎姓矣乎陈我大姬之后也弃衮冕而南冠以出不亦简彝乎是又犯先王之令也」「昔先王之教懋帅其德也犹恐殒越若废其教而弃其制蔑其官而犯其令将何以守国居大国之间而无此四者其何以能久」六年单子如楚八年陈侯杀于夏氏九年楚子入陈", "周定王派单襄公到宋国聘问。于是向陈国借路，以便到楚国聘问。大火星在早晨出现，道路杂草丛生不能行走。负责迎候的官员不在边境，司空不察看道路，水泽不加堤防，河上不架桥梁，田野里有露天堆积的谷物，打场的活还没有结束，路旁没有成列的树木，开垦的田地像长满杂草的荒地，膳宰不送来粮食，司里不安排馆舍，都城里没有寄宿之处，县里没有休息的地方。百姓正准备给夏氏筑台。到了陈国，陈灵公同孔宁、仪行父戴着楚国的帽子到夏氏家去，把宾客留在那里不见。\n单襄公回去，报告定王说：「陈侯不遭大祸，国家也必定灭亡。」定王问：「什么缘故？」答道：「角星在早晨出现而雨季结束，天根星出现而河水干涸，氐星出现而草木枝叶脱落，房星出现而降霜，大火星出现而凉风警示寒冷。所以先王的教导说：『雨季结束就修整道路，河水干涸就架设桥梁，草木脱落就准备收藏，降霜就备好冬衣，凉风到来就修整城郭宫室。』所以《夏令》说：『九月修整道路，十月架设桥梁。』那时的警戒说：『收获你的场功，备好你的畚箕铁锹，定星到中天，土功就开始。大火星刚出现，就到司里报到。』这是先王不用钱财，而广泛施德于天下的做法。\n「如今陈国大火星已经在早晨出现，而道路像被堵塞，田野场院像被抛弃，水泽不加堤防，河上无船无桥，这是废弃先王的教导。\n「周朝的旧制有这样的话：『成列种树来标记道路，设立路旁的饮食点来守路。国都有郊外的牧场，边境有寄宿的守望，沼泽有圃囿的草，园囿有林木池塘，这是用来防禦灾害的，其余没有不是五谷之土，百姓没有悬挂不用的农具，田野没有深草。不夺农时，不轻视百姓的劳作。有宽裕而无匮乏，有安逸而无疲惫。国都有分门别类的职事，县里有依次服役的百姓。』如今陈国道路辨认不出，田地掩在草中，农事完成而不收割，百姓因逸乐而疲惫，这是抛弃先王的法制。\n「周朝的《秩官》有这样的话：『同等国家的宾客到来，关尹报告，行理持符节迎接，候人做向导，卿出城慰劳，门尹清扫门庭，宗祝主持祭祀，司里安排馆舍，司徒备办差役，司空察看道路，司寇查办奸邪，虞人送来木材，甸人积聚柴薪，火师监管火烛，水师监管洗涤，膳宰送上饭食，廪人献上粮食，司马陈列草料，工人检查车辆，百官各自送来应备的物品，宾客进来像回到家里。因此大小宾客没有不感念的。如果是贵重国家的宾客到来，就按班次加一等，更加恭敬。至于天子的使者，就都由官长亲自办事，上卿监督。如果是天子巡守，就由国君亲自监督。』如今我虽然不才，但在周室有分族的身份，奉王命作为过路的宾客到陈国，而主管的官员没有一个到来，这是轻慢先王的官制。\n「先王的政令有这样的话：『天道奖赏善良而惩罚淫乱，所以凡是我所建的国家，不要依从不合常法的事，不要接近怠惰淫逸，各守你们的常法，以承受上天的福佑。』如今陈侯不念及子孙相续的常道，抛弃他的配偶妃嫔，却带着他的卿佐到夏氏家去淫乱，不是太亵渎同姓了吗？陈国是我们大姬的后代。抛弃衮冕而戴着楚国的帽子出去，不是太简易常法了吗？这又是违犯先王的政令。\n「从前先王的教导，是勉力遵循他们的德行，还怕有失误。如果废弃他们的教导、抛弃他们的制度、轻慢他们的官制、违犯他们的政令，将凭什么守住国家？处在大国之间，而没有这四样，怎么能长久呢？」\n六年，单襄公到楚国。八年，陈侯在夏氏家被杀。九年，楚王攻入陈国。"],
    [42, "guwen-gwj-39", "public-domain", "海鸟曰爰居止于鲁东门之外臧文仲使国人祭之展禽曰「越哉臧孙之为政也夫祀国之大节也而节政之所成也故慎制祀以为国典今无故而加典非政之宜也」「夫圣王之制祀也法施于民则祀之以死勤事则祀之以劳定国则祀之能御大灾则祀之能捍大患则祀之非是族也不在祀典昔烈山氏之有天下也其子曰柱能殖百谷百蔬夏之兴也周弃继之故祀以为稷共工氏之伯九有也其子曰后土能平九土故祀以为社黄帝能成命百物以明民共财颛顼能修之帝喾能序三辰以固民尧能单均刑法以仪民舜勤民事而野死鲧障洪水而殛死禹能以德修鲧之功契为司徒而民辑冥勤其官而水死汤以宽治民而除其邪稷勤百谷而山死文王以文昭武王去民之秽故有虞氏禘黄帝而祖颛顼郊尧而宗舜夏后氏禘黄帝而祖颛顼郊鲧而宗禹商人禘舜而祖契郊冥而宗汤周人禘喾而郊稷祖文王而宗武王幕能帅颛顼者也有虞氏报焉杼能帅禹者也夏后氏报焉上甲微能帅契者也商人报焉高圉大王能帅稷者也周人报焉凡禘郊祖宗报此五者国之典祀也」「加之以社稷山川之神皆有功烈于民者也及前哲令德之人所以为明质也及天之三辰民所以瞻仰也及地之五行所以生殖也及九州名山川泽所以出财用也非是不在祀典」「今海鸟至己不知而祀之以为国典难以言仁且知矣夫仁者讲功而知者处物无功而祀之非仁也不知而不能问非知也今兹海其有灾乎夫广川之鸟兽恒知避其灾也」是岁也海多大风冬暖文仲闻柳下季之言曰「信吾过也季子之言不可不法也」使书以为三策", "有只海鸟叫爰居，停在鲁国东门之外。臧文仲让国人去祭祀它。展禽说：「臧孙治理政事太迂阔了！祭祀是国家的大法度；而法度是政事成功的凭借。所以要谨慎地制定祭祀之礼作为国家的典制。如今无故增加典制，不是政事所应有的。\n「圣王制定祭祀，是：法制施行于百姓的就祭祀他，为国事勤劳而死的就祭祀他，用劳绩安定国家的就祭祀他，能抵御大灾害的就祭祀他，能抵御大祸患的就祭祀他。不属于这一类，就不在祭祀的典制之内。从前烈山氏拥有天下，他的儿子叫柱，能种植各种谷物蔬菜；夏朝兴起时，周弃继承他，所以祭祀他们为稷神。共工氏称霸九州，他的儿子叫后土，能平治九州的土地，所以祭祀他为社神。黄帝能成就万物之名，使百姓明白、共用财货，颛顼能继承他。帝喾能排列日月星来安定百姓，尧能尽力平均刑法来作为百姓的表率，舜为百姓的事勤劳而死在野外，鲧堵塞洪水而被杀，禹能用德行继承鲧的功业，契做司徒而百姓和睦，冥勤劳职守而被水淹死，汤用宽政治理百姓而除去邪恶，稷勤劳于百谷而死在山上，文王以文德昭明，武王除去百姓的祸害。所以有虞氏禘祭黄帝而以颛顼为祖，郊祭尧而以舜为宗；夏后氏禘祭黄帝而以颛顼为祖，郊祭鲧而以禹为宗；商人禘祭舜而以契为祖，郊祭冥而以汤为宗；周人禘祭喾而郊祭稷，以文王为祖而以武王为宗。幕能遵循颛顼，有虞氏报祭他；杼能遵循禹，夏后氏报祭他；上甲微能遵循契，商人报祭他；高圉、太王能遵循稷，周人报祭他。凡是禘、郊、祖、宗、报，这五种，是国家的典祭。\n「再加上社稷山川的神，都是对百姓有功业的；以及前代哲人、有美德的人，是用来作为明证的；以及天的日月星，是百姓所瞻仰的；以及地的五行，是用来生长万物的；以及九州的名山大川沼泽，是用来出产财物的。不属于这些，就不在祭祀的典制之内。\n「如今海鸟来了，自己不知道却去祭祀它，把它作为国家的典制，很难说是仁而且是智了。仁人讲究功业，智者处置事物。没有功业而祭祀它，不是仁；不知道又不问，不是智。如今海上恐怕有灾祸吧？广阔水面上的鸟兽，常常知道躲避它们的灾害。」\n这一年，海上多有大风，冬天温暖。臧文仲听到柳下季的话，说：「确实是我的过错，季子的话不可以不效法。」让人记下来作为三份简策。"],
    [43, "guwen-gwj-40", "public-domain", "宣公夏滥于泗渊里革断其罟而弃之曰「古者大寒降土蛰发水虞于是乎讲罛罶取名鱼登川禽而尝之寝庙行诸国助宣气也鸟兽孕水虫成兽虞于是乎禁罝罗矠鱼鳖以为夏犒助生阜也鸟兽成水虫孕水虞于是乎禁罝䍡设阱鄂以实庙庖畜功用也且夫山不槎蘖泽不伐夭鱼禁鲲鲕兽长麑䴠鸟翼鷇卵虫舍蚳蝝蕃庶物也古之训也今鱼方别孕不教鱼长又行网罟贪无艺也」公闻之曰「吾过而里革匡我不亦善乎是良罟也为我得法使有司藏之使吾无忘谂」师存侍曰「藏罟不如寘里革于侧之不忘也」", "鲁宣公夏天在泗水的深潭里下网捕鱼，里革割断他的网并扔掉，说：「古时候大寒降临，蛰伏的虫类开始活动，水虞这时就讲习大网、竹篓，捕取大鱼，捞取河中的水产，献到寝庙里祭祀，并在国中施行，这是为了帮助阳气的宣泄。鸟兽怀孕，水虫长成，兽虞这时就禁止张设罗网，只捕取鱼鳖作为夏天的犒劳，这是为了帮助生物的成长。鸟兽长成，水虫怀孕，水虞这时就禁止小网，设置陷阱，用来充实宗庙和厨房，这是为了积蓄功用。况且山上不砍伐新生的枝条，水泽不采伐幼小的草木，捕鱼禁止捕捞鱼苗，捕兽让幼鹿幼麋长大，捕鸟保护雏鸟和鸟卵，捕虫舍弃蚁卵和蝗蝻，这是为了使万物繁衍生息，是古人的训导。如今鱼正在怀卵，不教鱼生长，还使用网罟，是贪得无厌。」\n宣公听了，说：「我有过错，而里革纠正我，不是很好吗！这是张好网，为我得到了法度。让官吏把它收藏起来，使我不忘记这番规谏。」师存陪侍在旁，说：「收藏这网不如把里革安置在身边更能不忘。」"],
    [44, "guwen-gwj-41", "public-domain", "公父文伯退朝朝其母其母方绩文伯曰「以歜之家而主犹绩惧干季孙之怒也其以歜为不能事主乎」其母叹曰「鲁其亡乎使僮子备官而未之闻耶居吾语女昔圣王之处民也择瘠土而处之劳其民而用之故长王天下夫民劳则思思则善心生逸则淫淫则忘善忘善则恶心生沃土之民不材逸也瘠土之民莫不向义劳也是故天子大采朝日与三公九卿祖识地德日中考政与百官之政事师尹维旅牧相宣序民事少采夕月与大史司载纠虔天刑日入监九御使洁奉禘郊之粢盛而后即安诸侯朝修天子之业命昼考其国职夕省其典刑夜儆百工使无慆淫而后即安卿大夫朝考其职昼讲其庶政夕序其业夜庀其家事而后即安士朝受业昼而讲贯夕而习复夜而计过无憾而后即安自庶人以下明而动晦而休无日以怠」「王后亲织玄紞公侯之夫人加之以纮綖卿之内子为大带命妇成祭服列士之妻加之以朝服自庶士以下皆衣其夫社而赋事烝而献功男女效绩愆则有辟古之制也君子劳心小人劳力先王之训也自上以下谁敢淫心舍力」「今我寡也尔又在下位朝夕处事犹恐忘先人之业况有怠惰其何以避辟吾冀而朝夕修我曰『必无废先人』尔今曰『胡不自安』以是承君之官余惧穆伯之绝嗣也」仲尼闻之曰「弟子志之季氏之妇不淫矣」", "公父文伯退朝回来，拜见他的母亲，他母亲正在纺麻。文伯说：「凭我歜这样的家世，主母还亲自纺麻，恐怕会招致季孙发怒，他会以为我不能事奉主母吧！」\n他的母亲叹息说：「鲁国大概要灭亡了吧！让你这样的孩子做官而没有听说过这些道理吗？坐下，我告诉你。从前圣王安置百姓，选择贫瘠的土地让他们居住，使百姓劳苦而后使用他们，所以能长久地统治天下。百姓劳苦就会思考，思考就会产生善心；安逸就会放荡，放荡就会忘记善良，忘记善良就会产生坏心。肥沃土地上的百姓不成材，是因为安逸；贫瘠土地上的百姓没有不向义的，是因为劳苦。所以天子在春分时穿大采礼服朝拜日神，与三公、九卿熟悉土地的德性；白天考察政事，与百官处理政务，师尹、众士、牧、相宣扬并安排百姓的事务；秋分时穿少采礼服夕拜月神，与太史、司载恭敬地观察上天的法度；日落时监察九嫔，让她们洁净地奉上禘祭、郊祭的祭品，然后才安歇。诸侯早晨修治天子的业命，白天考察国内的职事，傍晚省察典章刑法，夜里警戒百官，使他们不怠惰放荡，然后才安歇。卿大夫早晨考察自己的职守，白天讲习各种政务，傍晚依次整理自己的事务，夜里处理家事，然后才安歇。士人早晨接受学业，白天讲习贯通，傍晚复习，夜里省察过错直到没有遗憾，然后才安歇。从庶人以下，天亮就劳作，天黑就休息，没有一天懈怠。\n「王后亲自织冠上的玄紞，公侯夫人还要加做纮、綖，卿的妻子做大带，命妇做成祭服，列士的妻子还要加做朝服，从庶士以下，都要给丈夫做衣服。春社时分配事务，冬祭时献上成果，男女都效力立功，有过失就要受罚，这是自古的制度。君子劳心，小人劳力，这是先王的训导。从上到下，谁敢放纵心意、舍弃努力？\n「如今我守寡，你又在低下的职位上，早晚处理事务，还怕忘记先人的功业。何况有怠惰，那怎么避免刑罚？我希望你早晚告诫我，说：『一定不要废弃先人的事业。』你如今却说：『为什么不自己安逸些？』凭这样的态度承担国君的官职，我害怕穆伯要断绝后嗣了。」\n孔子听说了这件事，说：「弟子们记住，季氏家的妇人是不放纵的。」"],
    [45, "guwen-gwj-42", "public-domain", "叔向见韩宣子宣子忧贫叔向贺之宣子曰「吾有卿之名而无其实无以从二三子吾是以忧子贺我何故」对曰「昔栾武子无一卒之田其宫不备其宗器宣其德行顺其宪则使越于诸侯诸侯亲之戎狄怀之以正晋国行刑不疚以免于难及桓子骄泰奢侈贪欲无艺略则行志假货居贿宜及于难而赖武之德以没其身及怀子改桓之行而修武之德可以免于难而离桓之罪以亡于楚夫郤昭子其富半公室其家半三军恃其富宠以泰于国其身尸于朝其宗灭于绛不然夫八郤五大夫三卿其宠大矣一朝而灭莫之哀也唯无德也今吾子有栾武子之贫吾以为能其德矣是以贺若不忧德之不建而患货之不足将吊不暇何贺之有」宣子拜稽首焉曰「起也将亡赖子存之非起也敢专承之其自桓叔以下嘉吾子之赐」", "叔向去见韩宣子，宣子正为贫穷忧愁，叔向却向他道贺。宣子说：「我有卿的名位，却没有卿的实惠，没有能力同各位卿大夫交往，我因此忧愁，你向我道贺是什么缘故？」\n叔向答道：「从前栾武子没有一百顷的田，他家里连祭器都不齐备，但他宣扬德行，遵循法度，使名声远播于诸侯。诸侯亲近他，戎、狄怀念他，因此使晋国走上正轨。他施行刑罚没有差错，因此免于祸难。到了桓子，骄纵奢侈，贪欲没有限度，违犯法度、任意行事，放贷牟利、囤积财货，本该遭祸，却倚仗武子的德行，得以善终。到了怀子，改变桓子的行为，修明武子的德行，本可以免于祸难，却遭到桓子罪过的连累，逃到楚国。至于郤昭子，他的财富抵得上半个公室，他家的兵员抵得上半个三军，倚仗富有和受宠，在国内骄纵，结果他的尸体陈列在朝廷，他的宗族在绛地被灭。不然，那八个郤氏，有五位大夫、三位卿，受宠够大的了，一朝被灭，没有人哀怜，就是因为没有德行。如今您有栾武子那样的贫穷，我以为您能具备他的德行了，所以道贺。如果不忧愁德行不能建立，而忧虑财货不足，那要哀悼都来不及，还有什么可道贺的？」\n宣子下拜，叩头说：「我韩起将要灭亡了，依靠您得以保全。不但我韩起一个人敢独自承受，从桓叔以下的后人，都要感念您的赐予。」"],
    [46, "guwen-gwj-43", "public-domain", "王孙圉聘于晋定公飨之赵简子鸣玉以相问于王孙圉曰「楚之白珩犹在乎」对曰「然」简子曰「其为宝也几何矣」曰「未尝为宝楚之所宝者曰观射父能作训辞以行事于诸侯使无以寡君为口实又有左史倚相能道训典以叙百物以朝夕献善败于寡君使寡君无忘先王之业又能上下说于鬼神顺道其欲恶使神无有怨痛于楚国又有薮曰云连徒洲金木竹箭之所生也龟珠角齿皮革羽毛所以备赋以戒不虞者也所以共币帛以宾享于诸侯者也若诸侯之好币具而导之以训辞有不虞之备而皇神相之寡君其可以免罪于诸侯而国民保焉此楚国之宝也若夫白珩先王之玩也何宝之焉」「圉闻国之宝六而已明王圣人能制议百物以辅相国家则宝之玉足以庇荫嘉谷使无水旱之灾则宝之龟足以宪臧否则宝之珠足以御火灾则宝之金足以御兵乱则宝之山林薮泽足以备财用则宝之若夫哗嚣之美楚虽蛮夷不能宝也」", "王孙圉到晋国聘问，晋定公设宴款待他。赵简子佩玉鸣响地做傧相，问王孙圉说：「楚国的白珩还在吗？」王孙圉答道：「在。」简子说：「它作为宝物，价值多少呢？」王孙圉答道：「我们不曾把它当作宝物。楚国所珍视的，是观射父，他能撰写训诫辞令，用来在诸侯之间办事，使别人没有拿我们国君做话柄的。又有左史倚相，能陈述训典，用来条理各种事物，早晚向我们国君进献善恶成败，使我们国君不忘记先王的功业；又能使上上下下都取悦鬼神，顺应它们的喜恶，使神灵对楚国没有怨恨。又有沼泽叫云连徒洲，是金、木、竹、箭出产的地方。龟甲、珍珠、兽角、象牙、兽皮、皮革、羽毛，用来备办兵赋，以防备意外；用来供给币帛，以招待和馈赠诸侯。如果诸侯的友好礼品齐备，又用训辞来引导，有防备意外的储备，又有大神保佑，我们国君就可以免罪于诸侯，而国家和百姓也得以保全。这些才是楚国的宝物。至于白珩，是先王的玩物，有什么可宝的呢？\n「我听说国家的宝物只有六样。明王圣人能制定评议各种事物，用来辅佐国家，就珍视他；玉足以庇护嘉谷，使没有水旱的灾害，就珍视它；龟甲足以显示善恶，就珍视它；珍珠足以抵御火灾，就珍视它；金属足以抵御兵乱，就珍视它；山林沼泽足以备办财用，就珍视它。至于喧哗炫耀的美玉，楚国虽是蛮夷，也不能把它当作宝物。」"],
    [47, "guwen-gwj-44", "public-domain", "吴王夫差起师伐越越王勾践起师逆之大夫种乃献谋曰「夫吴之与越唯天所授王其无庸战夫申胥华登简服吴国之士于甲兵而未尝有所挫也夫一人善射百夫决拾胜未可成也夫谋必素见成事焉而后履之不可以授命王不如设戎约辞行成以喜其民以广侈吴王之心吾以卜之于天天若弃吴必许吾成而不吾足也将必宽然有伯诸侯之心焉既罢弊其民而天夺之食安受其烬乃无有命矣」越王许诺乃命诸稽郢行成于吴曰「寡君勾践使下臣郢不敢显然布币行礼敢私告于下执事曰昔者越国见祸得罪于天王天王亲趋玉趾以心孤勾践而又有宥赦之君王之于越也繄起死人而肉白骨也孤不敢忘天灾其敢忘君王之大赐乎今勾践申祸无良草鄙之人敢忘天王之大德而思边垂之小怨以重得罪于下执事勾践用帅二三之老亲委重罪顿颡于边」「今君王不察盛怒属兵将残伐越国越国固贡献之邑也君王不以鞭箠使之而辱军士使寇令焉勾践请盟一介嫡女执箕帚以晐姓于王宫一介嫡男奉槃匜以随诸御春秋贡献不解于王府天王岂辱裁之亦征诸侯之礼也」「夫谚曰『狐埋之而狐搰之是以无成功』今天王既封植越国以明闻于天下而又刈亡之是天王之无成劳也虽四方之诸侯则何实以事吴敢使下臣尽辞唯天王秉利度义焉」", "吴王夫差发兵攻打越国，越王勾践发兵迎击。大夫文种于是献计说：「吴国和越国，都由上天授予。大王不必交战。申胥、华登挑选训练的吴国士卒，还不曾受过挫折。一个人善射，一百个人跟着拉弓，胜负还难以预料。谋划一定要预见到事情能成，然后才去做，不能轻易拼上性命。大王不如设下军阵，用谦卑的言辞去求和，使他们的百姓欢喜，使吴王的心更加骄纵。我以此向上天占卜，上天如果抛弃吴国，一定会答应我们求和而不把我们放在心上，一定会放宽心地有称霸诸侯的野心。等到他们疲惫了百姓，上天又夺去他们的粮食，我们就可以安然收拾他们的残局，吴国就没有天命了。」\n越王答应了，于是派诸稽郢到吴国求和，说：「我们国君勾践派下臣郢来，不敢公开陈列礼物行礼，谨私下告诉您的执事说：从前越国遭到祸患，得罪了天王。天王亲自举步，心里疏远勾践，却又加以宽赦。君王对越国，真是使死人复活、使白骨长肉啊。勾践不敢忘记天降的灾祸，怎敢忘记君王的大恩？如今勾践重遭祸患、没有善行，我这草野鄙陋的人，怎敢忘记天王的大德，而念及边境上的小怨，以致重新得罪于执事？勾践因此率领几个老臣，亲自承担重罪，在边境上叩头。\n「如今君王不加体察，盛怒之下调集军队，将要残害攻打越国。越国本来是向您进贡的城邑，君王不用鞭子驱使，却屈尊让军士们实行讨伐的号令。勾践请求结盟：送上一个嫡女，让她拿着箕帚在王宫里供职；送上一个嫡男，让他奉着槃匜跟随侍从；春秋两季进贡，不怠慢王室的府库。天王何不屈尊裁断？这也是征召诸侯的礼仪啊。\n「谚语说：『狐狸埋下东西，狐狸又把它挖出来，所以没有成功。』如今天王既已扶植越国，昭明于天下，却又割除灭亡它，这是天王没有成就的功劳。即使四方的诸侯，又拿什么来事奉吴国呢？谨派下臣把话说完，请天王权衡利益、考虑道义吧！」"],
    [48, "guwen-gwj-45", "public-domain", "吴王夫差乃告诸大夫曰「孤将有大志于齐吾将许越成而无拂吾虑若越既改吾又何求若其不改反行吾振旅焉」申胥谏曰「不可许也夫越非实忠心好吴也又非慑畏吾兵甲之强也大夫种勇而善谋将还玩吴国于股掌之上以得其志夫固知君王之盖威以好胜也故婉约其辞以从逸王志使淫乐于诸夏之国以自伤也使吾甲兵钝弊民人离落而日以憔悴然后安受吾烬夫越王好信以爱民四方归之年谷时熟日长炎炎及吾犹可以战也为虺弗摧为蛇将若何」吴王曰「大夫奚隆于越越曾足以为大虞乎若无越则吾何以春秋曜吾军士」乃许之成将盟越王又使诸稽郢辞曰「以盟为有益乎前盟口血未干足以结信矣以盟为无益乎君王舍甲兵之威以临使之而胡重于鬼神而自轻也」吴王乃许之荒成不盟", "吴王夫差于是告诉各位大夫说：「我将对齐国有大的图谋，我准备答应越国的求和，你们不要违背我的打算。如果越国已经改正，我还要求什么？如果它不改正，等我回来，再整顿军队去讨伐。」\n申胥劝谏说：「不能答应。越国并不是真心实意地亲善吴国，也不是害怕我们兵甲的强大。大夫文种勇敢而善于谋划，将要把吴国玩弄于股掌之上，来达成他的心愿。他本来就知道君王爱好威势、争强好胜，所以用委婉的言辞，来放纵君王的心意，让您对中原各国寻欢作乐，自己伤害自己。使我们的兵甲钝弊，百姓离散，一天天憔悴，然后安然收拾我们的残局。越王讲求信义、爱护百姓，四方归附他，年成按时丰收，国势日益兴盛。趁我们还可以作战的时候，小蛇不打死，长成大蛇怎么办？」\n吴王说：「大夫为什么这样抬高越国？越国难道值得如此忧虑吗？如果没有越国，我拿什么在春秋两季向军士炫耀？」于是答应了越国的求和。\n将要结盟时，越王又派诸稽郢推辞说：「认为结盟有益吗？先前结盟时涂在嘴上的血还没有干，已经足够确立信用了。认为结盟无益吗？君王放下兵甲的威势来统御命令我们，为什么看重鬼神而看轻自己呢？」吴王于是答应，只是口头达成和议，没有举行结盟仪式。"],
    [49, "guwen-gwj-157", "public-domain", "元年者何君之始年也春者何岁之始也王者孰谓谓文王也曷为先言王而后言正月王正月也何言乎王正月大一统也公何以不言即位成公意也何成乎公之意公将平国而反之桓曷为反之桓桓幼而贵隐长而卑其为尊卑也微国人莫知隐长又贤诸大夫扳隐而立之隐于是焉而辞立则未知桓之将必得立也且如桓立则恐诸大夫之不能相幼君也故凡隐之立为桓立也隐长又贤何以不宜立立適以长不以贤立子以贵不以长桓何以贵母贵也母贵则子何以贵子以母贵母以子贵", "「元年」是什么意思？是国君即位的头一年。「春」是什么意思？是一年的开始。「王」指的是谁？指的是周文王。为什么先说「王」而后说「正月」？因为这是周王所颁的正月。为什么要说「王正月」？是为了推崇天下的大一统。\n隐公为什么不说即位？是为了成全隐公的心意。怎样成全隐公的心意呢？隐公打算治理好国家之后再把它交还给桓公。为什么要交还给桓公？因为桓公年幼而地位尊贵，隐公年长而地位卑微。他们的尊卑差别很细微，国都的人不知道。隐公年长又贤能，众大夫拥立隐公为君。隐公如果在这里推辞不即位，那就不知道桓公将来一定能立为国君；况且如果桓公立为国君，又怕众大夫不能辅佐年幼的君主。所以隐公的即位，是为了桓公而即位的。隐公年长又贤能，为什么不应该立为国君？立嫡子凭年长不凭贤能，立庶子凭母亲尊贵不凭年长。桓公为什么尊贵？因为母亲尊贵。母亲尊贵，儿子为什么就尊贵？儿子凭母亲而尊贵，母亲凭儿子而尊贵。"],
    [50, "guwen-gwj-158", "public-domain", "外平不书此何以书大其平乎己也何大乎其平乎己庄王围宋军有七日之粮尔尽此不胜将去而归尔于是使司马子反乘堙而窥宋城宋华元亦乘堙而出见之司马子反曰「子之国何如」华元曰「惫矣」曰「何如」曰「易子而食之析骸而炊之」司马子反曰「嘻甚矣惫虽然吾闻之也围者柑马而秣之使肥者应客是何子之情也」华元曰「吾闻之君子见人之厄则矜之小人见人之厄则幸之吾见子之君子也是以告情于子也」司马子反曰「诺勉之矣吾军亦有七日之粮尔尽此不胜将去而归尔」揖而去之反于庄王庄王曰「何如」司马子反曰「惫矣」曰「何如」曰「易子而食之析骸而炊之」庄王曰「嘻甚矣惫虽然吾今取此然后而归尔」司马子反曰「不可臣已告之矣军有七日之粮尔」庄王怒曰「吾使子往视之子曷为告之」司马子反曰「以区区之宋犹有不欺人之臣可以楚而无乎是以告之也」庄王曰「诺舍而止虽然吾犹取此然后归尔」司马子反曰「然则君请处于此臣请归尔」庄王曰「子去我而归吾孰与处于此吾亦从子而归尔」引师而去之故君子大其平乎己也此皆大夫也其称人何贬曷为贬平者在下也", "鲁国以外的讲和是不记载的，这件事为什么记载？是为了赞扬他们自己主动讲和。为什么赞扬他们自己主动讲和？楚庄王包围宋国，军中只有七天的粮食了，吃完这些还不能取胜，就要离开回国了。于是派司马子反登上土山窥探宋国的城池。宋国的华元也登上土山出来见他。司马子反说：「你们的国家怎么样？」华元说：「疲惫极了！」问：「怎么样呢？」回答说：「交换孩子来吃，劈开骨头来烧火做饭。」司马子反说：「唉！疲惫得太过分了！虽然如此，我听说过，包围别人的人要让马嘴里衔着东西来喂它，派肥壮的马给客人看，您为什么把实情说出来呢？」华元说：「我听说，君子看见别人的困厄就怜悯他，小人看见别人的困厄就幸灾乐祸。我看您是君子，所以把实情告诉您。」司马子反说：「好，努力吧！我的军中也只有七天的粮食了，吃完这些还不能取胜，就要离开回国了。」作揖然后离去。\n司马子反回到庄王那里。庄王说：「怎么样？」司马子反说：「疲惫极了！」问：「怎么样呢？」回答说：「交换孩子来吃，劈开骨头来烧火做饭。」庄王说：「唉！疲惫得太过分了！虽然如此，我现在还是要攻下这座城，然后才回去。」司马子反说：「不行。我已经告诉他们了，军中也只有七天的粮食了。」庄王发怒说：「我派你去看看情况，你为什么告诉他们？」司马子反说：「凭一个小小的宋国，尚且有不欺骗别人的臣子，难道楚国可以没有吗？所以告诉了他们。」庄王说：「好。那就做营寨住下来。虽然如此，我还是要在攻下这座城之后回去。」司马子反说：「那么请君王留在这里，请让我回去。」庄王说：「你丢下我回去，我同谁留在这里？我也跟你一起回去吧。」于是率领军队离开了。所以君子赞扬他们自己主动讲和。他们二人都是大夫，这里称「人」是为什么？是贬抑。为什么贬抑？因为讲和是出在下位的人身上。"],
    [51, "guwen-gwj-159", "public-domain", "吴无君无大夫此何以有君有大夫贤季子也何贤乎季子让国也其让国奈何谒也余祭也夷昧也与季子同母者四季子弱而才兄弟皆爱之同欲立之以为君谒曰「今若是迮而与季子国季子犹不受也请无与子而与弟弟兄迭为君而致国乎季子」皆曰「诺」故诸为君者皆轻死为勇饮食必祝曰「天苟有吴国尚速有悔于予身」故谒也死余祭也立余祭也死夷昧也立夷昧也死则国宜之季子者也季子使而亡焉僚者长庶也即之季子使而反至而君之尔阖庐曰「先君之所以不与子国而与弟者凡为季子故也将从先君之命与则国宜之季子者也如不从先君之命与则我宜立者也僚恶得为君乎」于是使专诸刺僚而致国乎季子季子不受曰「尔弑吾君吾受尔国是吾与尔为篡也尔杀吾兄吾又杀尔是父子兄弟相杀终身无已也」去之延陵终身不入吴国故君子以其不受为义以其不杀为仁贤季子则吴何以有君有大夫以季子为臣则宜有君者也札者何吴季子之名也春秋贤者不名此何以名许夷狄者不一而足也季子者所贤也曷为不足乎季子许人臣者必使臣许人子者必使子也", "吴国没有国君、没有大夫，这里为什么有国君、有大夫？是为了赞扬季子。为什么赞扬季子？因为他辞让君位。他辞让君位是怎么一回事？谒、余祭、夷昧与季子是同母的四兄弟。季子年幼而有才能，兄弟们都喜爱他，都想立他为君。谒说：「现在如果这样仓促地把吴国交给季子，季子还是不会接受的。请不要传给儿子而传给弟弟，兄弟轮流做国君，最终把国家交给季子。」大家都说：「好。」所以那些做国君的都看轻死、勇于赴死，饮食时必定祷告说：「上天如果要让吴国存在，就请赶快把灾祸降到我身上。」所以谒死了，余祭即位。余祭死了，夷昧即位。夷昧死了，那么国家就应该归季子。季子出使在外逃亡了。僚是庶出的长子，就即位了。季子出使回来，回来后就以僚为君。阖庐说：「先君之所以不把国家传给儿子而传给弟弟，都是为了季子的缘故。如果遵从先君的命令，那么国家应归季子；如果不遵从先君的命令，那么我应该即位。僚怎么能做国君呢？」于是派专诸刺杀僚，而把国家交给季子。季子不接受，说：「你杀了我的国君，我接受你的国家，这就是我同你一起篡位。你杀了我的兄长，我又杀你，这是父子兄弟互相残杀，终身没有完结。」于是离开到延陵，终身不进入吴国国都。所以君子认为他不接受君位是义，认为他不杀人、杀人是仁。\n赞扬季子，那么吴国为什么就有国君、有大夫？因为把季子看作臣子，就应该有国君。札是什么？是吴国季子的名。《春秋》对贤者不称名，这里为什么称名？因为称许夷狄，不能一次就完全给足。季子是所赞扬的人，为什么对季子还有不足？因为称许做人臣的就要让他尽臣道，称许做人子的就要让他尽子道。"],
    [52, "guwen-gwj-1", "public-domain", "初郑武公娶于申曰武姜生庄公及共叔段庄公寤生惊姜氏故名曰「寤生」遂恶之爱共叔段欲立之亟请于武公公弗许及庄公即位为之请制公曰「制岩邑也虢叔死焉佗邑唯命」请京使居之谓之京城大叔祭仲曰「都城过百雉国之害也先王之制大都不过参国之一中五之一小九之一今京不度非制也君将不堪」公曰「姜氏欲之焉辟害」对曰「姜氏何厌之有不如早为之所无使滋蔓蔓难图也蔓草犹不可除况君之宠弟乎」公曰「多行不义必自毙子姑待之」既而大叔命西鄙北鄙贰于己公子吕曰「国不堪贰君将若之何欲与大叔臣请事之若弗与则请除之无生民心」公曰「无庸将自及」大叔又收贰以为己邑至于廪延子封曰「可矣厚将得众」公曰「不义不昵厚将崩」大叔完聚缮甲兵具卒乘将袭郑夫人将启之公闻其期曰「可矣」命子封帅车二百乘以伐京京叛大叔段段入于鄢公伐诸鄢五月辛丑大叔出奔共书曰「郑伯克段于鄢」段不弟故不言弟如二君故曰克称郑伯讥失教也谓之郑志不言出奔难之也遂寘姜氏于城颍而誓之曰「不及黄泉无相见也」既而悔之颍考叔为颍谷封人闻之有献于公公赐之食食舍肉公问之对曰「小人有母皆尝小人之食矣未尝君之羹请以遗之」公曰「尔有母遗繄我独无」颍考叔曰「敢问何谓也」公语之故且告之悔对曰「君何患焉若阙地及泉隧而相见其谁曰不然」公从之公入而赋「大隧之中其乐也融融」姜出而赋「大隧之外其乐也泄泄」遂为母子如初君子曰「颍考叔纯孝也爱其母施及庄公诗曰『孝子不匮永锡尔类』其是之谓乎」", "当初，郑武公从申国娶了妻子，名叫武姜。她生了庄公和共叔段。庄公是倒着生下来的，惊了姜氏，所以取名「寤生」，姜氏因此讨厌他。她偏爱共叔段，想立他为太子，多次向武公请求，武公没有答应。\n到庄公即位后，姜氏替共叔段请求把制地封给他。庄公说：「制是险要的地方，虢叔就死在那里。别的城邑，唯命是从。」姜氏又请求京城，庄公让共叔段住在那里，人们称他为京城太叔。\n祭仲说：「都邑的城墙超过三百丈，是国家的祸害。先王的制度：大城不超过国都的三分之一，中等的不超过五分之一，小的不超过九分之一。如今京城的规模不合制度，您将受不了。」庄公说：「姜氏要这样，怎能避开祸害？」祭仲答道：「姜氏哪里会满足？不如早点安排他，别让祸患蔓延。一蔓延就难对付了。野草蔓延尚且难以清除，何况您受宠的弟弟呢？」庄公说：「多做不义的事，必定自取灭亡。你暂且等着看。」\n不久太叔命令西部和北部的边邑也听命于自己。公子吕说：「国家不能有两个君主，您打算怎么办？要把君位让给太叔，我就去侍奉他；如果不给，就请除掉他，别让百姓生二心。」庄公说：「不必，他会自食其果。」\n太叔又把两属的地方收作自己的城邑，一直扩展到廪延。子封说：「可以动手了，他的地盘大了就会得到更多人心。」庄公说：「对君不义、对兄不亲，地盘大了也会崩溃。」\n太叔修治城郭、聚集百姓，整治铠甲兵器，备好步兵战车，准备偷袭郑国国都。姜氏将为他打开城门。庄公得知了他动手的日期，说：「可以了！」命子封率领战车二百乘去攻打京城。京城的人背叛了太叔段，段逃到鄢地。庄公又攻打鄢。五月辛丑日，太叔逃奔到共国。\n《春秋》记作「郑伯克段于鄢」：段不守弟弟的本分，所以不说「弟」；如同两个国君相争，所以用「克」；称「郑伯」，是讥讽他没有尽到教诲之责；说这是郑伯的本意，不写段「出奔」，是因为难以措辞。\n于是庄公把姜氏安置在城颍，并对她发誓说：「不到黄泉，不再相见！」不久又后悔了。\n颍考叔是颍谷管理疆界的官，听说了这件事，就献给庄公一些礼物。庄公赐他吃饭。他吃的时候把肉留下。庄公问他为什么，他答道：「小人有母亲，小人的食物她都尝过，只是没有尝过您赏的肉羹。请让我带回去给她。」庄公说：「你有母亲可以送，我偏偏没有！」颍考叔说：「敢问这是什么意思？」庄公把缘故告诉他，并说自己后悔了。颍考叔答道：「您忧虑什么呢？如果挖地挖到泉水，在隧道里相见，谁会说不行呢？」庄公听从了。庄公进入隧道赋诗：「大隧之中，其乐也融融。」姜氏出来赋诗：「大隧之外，其乐也泄泄。」于是母子像当初一样。\n君子说：「颍考叔是纯正的孝子。爱他的母亲，又推及庄公。《诗经》说：『孝子的孝心没有穷尽，永远赐给你的同类。』说的就是这样的事吧！」"],
    [53, "guwen-gwj-160", "public-domain", "非国而曰灭重夏阳也虞无师其曰师何也以其先晋不可以不言师也其先晋何也为主乎灭夏阳也夏阳者虞虢之塞邑也灭夏阳而虞虢举矣虞之为主乎灭夏阳何也晋献公欲伐虢荀息曰「君何不以屈产之乘垂棘之璧而借道乎虞也」公曰「此晋国之宝也如受吾币而不借吾道则如之何」荀息曰「此小国之所以事大国也彼不借吾道必不敢受吾币如受吾币而借吾道则是我取之中府而藏之外府取之中厩而置之外厩也」公曰「宫之奇存焉必不使受之也」荀息曰「宫之奇之为人也达心而懦又少长于君达心则其言略懦则不能强谏少长于君则君轻之且夫玩好在耳目之前而患在一国之后此中知以上乃能虑之臣料虞君中知以下也」公遂借道而伐虢宫之奇谏曰「晋国之使者其辞卑而币重必不便于虞」虞公弗听遂受其币而借之道宫之奇又谏曰「语曰『唇亡则齿寒』其斯之谓与」挈其妻子以奔曹献公亡虢五年而后举虞荀息牵马操璧而前曰「璧则犹是也而马齿加长矣」", "不是一个国家却说是「灭」，是重视夏阳。虞国没有军队，这里说「师」是为什么？因为它在晋国前面，不可以不说「师」。它在晋国前面是为什么？因为它是灭亡夏阳的主谋。夏阳，是虞国、虢国的边塞城邑。灭亡了夏阳，虞国、虢国就可以拿下了。虞国是灭亡夏阳的主谋，怎么讲？晋献公想要讨伐虢国，荀息说：「君王为什么不用屈地出产的马匹、垂棘出产的玉璧去向虞国借路呢？」献公说：「这是晋国的宝物。如果接受了我的礼物却不借给我路，那怎么办？」荀息说：「这正是小国用来事奉大国的做法。他不借给我路，就一定不敢接受我的礼物。如果接受了我的礼物又借给我路，那就是我从内府取出而藏在外国府库，从内厩取出而放在外国马厩。」献公说：「宫之奇还在那里，一定不会让他接受的。」荀息说：「宫之奇的为人，心里通达却懦弱，又从小在虞君身边长大。心里通达，说话就简略；懦弱，就不能强谏；从小在国君身边长大，国君就轻视他。况且玩好之物就在眼前，而祸患在一国之后，这是中等以上智慧的人才能考虑到的。我料想虞君的智慧在中等以下。」献公于是借道而讨伐虢国。宫之奇谏阻说：「晋国的使者，言辞谦卑而礼物厚重，一定对虞国不利。」虞公不听，于是接受了他的礼物而借给他道路。宫之奇又谏阻说：「俗语说：『嘴唇没有了，牙齿就会寒冷。』说的就是这种情况吧！」于是带着妻儿逃奔到曹国。\n献公灭掉了虢国，五年之后又拿下了虞国。荀息牵着马、拿着玉璧上前说：「玉璧还是原来的样子，而马的牙齿却长多了。」"],
    [55, "guwen-gwj-162", "public-domain", "曾子寝疾病乐正子春坐于床下曾元曾申坐于足童子隅坐而执烛童子曰「华而睆大夫之箦与」子春曰「止」曾子闻之瞿然曰「呼」曰「华而睆大夫之箦与」曾子曰「然斯季孙之赐也我未之能易也元起易箦」曾元曰「夫子之病革矣不可以变幸而至于旦请敬易之」曾子曰「尔之爱我也不如彼君子之爱人也以德细人之爱人也以姑息吾何求哉吾得正而毙焉斯已矣」举扶而易之反席未安而没", "曾子卧病，病得很重。乐正子春坐在床下，曾元、曾申坐在脚边，一个童仆坐在角落里拿着蜡烛。\n童仆说：「这样华美光洁，是大夫用的竹席吧？」子春说：「住口！」曾子听见了，惊起说：「呼！」童仆又说：「这样华美光洁，是大夫用的竹席吧？」曾子说：「是的。这是季孙赐给我的，我没能把它换掉。元，起来换席子！」曾元说：「夫子的病已经很重了，不可以移动。如果能挨到天亮，再敬请您换吧。」曾子说：「你爱我不如他。君子爱人是用德行，小人爱人是用姑息迁就。我还求什么呢？我能合乎正道而死，这就够了。」于是抬起他换了席子。回到席上还没躺稳就去世了。"],
    [56, "guwen-gwj-163", "public-domain", "有子问于曾子曰「问丧于夫子乎」曰「闻之矣『丧欲速贫死欲速朽』」有子曰「是非君子之言也」曾子曰「参也闻诸夫子也」有子又曰「是非君子之言也」曾子曰「参也与子游闻之」有子曰「然然则夫子有为言之也」曾子以斯言告于子游子游曰「甚哉有子之言似夫子也昔者夫子居于宋见桓司马自为石椁三年而不成夫子曰『若是其靡也死不如速朽之愈也』死之欲速朽为桓司马言之也南宫敬叔反必载宝而朝夫子曰『若是其货也丧不如速贫之愈也』丧之欲速贫为敬叔言之也」曾子以子游之言告于有子有子曰「然吾固曰非夫子之言也」曾子曰「子何以知之」有子曰「夫子制于中都四寸之棺五寸之椁以斯知不欲速朽也昔者夫子失鲁司寇将之荆盖先之以子夏又申之以冉有以斯知不欲速贫也」", "有子问曾子说：「你向夫子问过关于丧礼的事吗？」曾子说：「听说过：『丧失了官职就该快点贫穷，死了就该快点腐朽。』」有子说：「这不是君子说的话。」曾子说：「我参是从夫子那里听来的。」有子又说：「这不是君子说的话。」曾子说：「我和子游一起听到的。」有子说：「是的。那么夫子是有缘故才这样说的。」\n曾子把这些话告诉子游。子游说：「有子的话真像夫子啊！从前夫子住在宋国，看见桓司马自己为自己做石椁，三年还没有做成。夫子说：『像这样奢侈，死了还不如快点腐朽的好。』死了想快点腐朽，是针对桓司马说的。南宫敬叔回到鲁国，必定装着宝物去朝见。夫子说：『像这样贪财，失了官还不如快点贫穷的好。』失了官想快点贫穷，是针对敬叔说的。」\n曾子把子游的话告诉有子。有子说：「是的。我本来就说这不是夫子的话。」曾子说：「你怎么知道的？」有子说：「夫子在当中都宰时，规定四寸厚的棺、五寸厚的椁，由此知道他不希望快点腐朽。从前夫子失掉鲁国司寇的职位，将要到楚国去，先派子夏去，又派冉有去，由此知道他不希望快点贫穷。」"],
    [58, "guwen-gwj-165", "public-domain", "知悼子卒未葬平公饮酒师旷李调侍鼓钟杜蒉自外来闻钟声曰「安在」曰「在寝」杜蒉入寝历阶而升酌曰「旷饮斯」又酌曰「调饮斯」又酌堂上北面坐饮之降趋而出平公呼而进之曰「蒉曩者尔心或开予是以不与尔言尔饮旷何也」曰「子卯不乐知悼子在堂斯其为子卯也大矣旷也太师也不以诏是以饮之也」「尔饮调何也」曰「调也君之亵臣也为一饮一食忘君之疾是以饮之也」「尔饮何也」曰「蒉也宰夫也非刀匕是共又敢与知防是以饮之也」平公曰「寡人亦有过焉酌而饮寡人」杜蒉洗而扬觯公谓侍者曰「如我死则必毋废斯爵也」至于今既毕献斯扬觯谓之杜举", "知悼子去世，还没有下葬，晋平公饮酒作乐，师旷、李调陪侍，敲钟奏乐。杜蒉从外面进来，听见钟声，问：「国君在哪里？」回答说：「在寝宫。」杜蒉走进寝宫，沿着台阶上去。斟了一杯酒，说：「师旷，喝这杯！」又斟一杯，说：「李调，喝这杯！」又斟一杯，在堂上朝北坐下自己喝了。然后下堂，快步走出去。\n平公叫住他让他进来，说：「杜蒉！刚才你心里或许是要开导我，所以我没有同你说话。你让师旷喝酒，是为什么？」回答说：「子日卯日不奏乐。知悼子的灵柩还在堂上，这比子日卯日的忌讳更大。师旷是太师，却不把这件事告诉您，所以罚他喝酒。」「你让李调喝酒，是为什么？」回答说：「李调是国君的近臣。为了一点饮食，忘了国君的过失，所以罚他喝酒。」「你自己喝酒，是为什么？」回答说：「我杜蒉是宰夫，不专门供给刀匕餐具，却敢参与了解、防止过失的事，所以罚自己喝酒。」平公说：「寡人也有过错。斟一杯酒罚寡人！」杜蒉洗净酒杯举起献上。平公对侍者说：「如果我死了，一定不要废弃这只酒杯。」直到今天，献酒完毕之后，就举起酒杯，称为「杜举」。"],
    [59, "guwen-gwj-166", "public-domain", "晋献文子成室晋大夫发焉张老曰「美哉轮焉美哉奂焉歌于斯哭于斯聚国族于斯」文子曰「武也得歌于斯哭于斯聚国族于斯是全要领以从先大夫于九京也」北面再拜稽首君子谓之善颂善祷", "晋国的献文子新屋落成，晋国的大夫都来参加典礼。张老说：「真美啊，这样高大！真美啊，这样众多！可以在这里祭祀歌唱，可以在这里居丧哭泣，可以在这里聚集宗族。」文子说：「我赵武能够在这里祭祀歌唱，在这里居丧哭泣，在这里聚集宗族，这就是能保全腰领、跟随先大夫葬到九京去。」于是朝北再拜叩头。君子说这是善于祝颂、善于祈祷。"],
    [60, "guwen-gwj-194", "", "臣伏见天后时有同州下邽人徐元庆者父爽为县吏赵师韫所杀卒能手刃父仇束身归罪当时谏臣陈子昂建议诛之而旌其闾且请编之于令永为国典臣窃独过之臣闻礼之大本以防乱也若曰无为贼虐凡为子者杀无赦刑之大本亦以防乱也若曰无为贼虐凡为治者杀无赦其本则合其用则异旌与诛莫得而并焉诛其可旌兹谓滥黩刑甚矣旌其可诛兹谓僭坏礼甚矣果以是示于天下传于后代趋义者不知所向违害者不知所立以是为典可乎盖圣人之制穷理以定赏罚本情以正褒贬统于一而已矣向使刺谳其诚伪考正其曲直原始而求其端则刑礼之用判然离矣何者若元庆之父不陷于公罪师韫之诛独以其私怨奋其吏气虐于非辜州牧不知罪刑官不知问上下蒙冒吁号不闻而元庆能以戴天为大耻枕戈为得礼处心积虑以冲仇人之胸介然自克即死无憾是守礼而行义也执事者宜有惭色将谢之不暇而又何诛焉其或元庆之父不免于罪师韫之诛不愆于法是非死于吏也是死于法也法其可仇乎仇天子之法而戕奉法之吏是悖骜而凌上也执而诛之所以正邦典而又何旌焉且其议曰「人必有子子必有亲亲亲相仇其乱谁救」是惑于礼也甚矣礼之所谓仇者盖其冤抑沉痛而号无告也非谓抵罪触法陷于大戮而曰「彼杀之我乃杀之」不议曲直暴寡胁弱而已其非经背圣不亦甚哉周礼「调人掌司万人之仇」「凡杀人而义者令勿仇仇之则死」「有反杀者邦国交仇之」又安得亲亲相仇也春秋公羊传曰「父不受诛子复仇可也父受诛子复仇此推刃之道复仇不除害」今若取此以断两下相杀则合于礼矣且夫不忘仇孝也不爱死义也元庆能不越于礼服孝死义是必达理而闻道者也夫达理闻道之人岂其以王法为敌仇者哉议者反以为戮黩刑坏礼其不可以为典明矣请下臣议附于令有断斯狱者不宜以前议从事谨议", "臣看到天后武则天时，同州下邽有个叫徐元庆的人，父亲徐爽被县吏赵师韫所杀，他终于亲手杀了父亲的仇人，然后自缚投案认罪。当时谏臣陈子昂建议处死他而在他的里巷表彰，并且请求编入法令，永远作为国家的典章。臣私下独认为这是错的。\n臣听说礼的根本，是用来防止祸乱的。如果说不要行凶虐害，那么凡是做儿子的杀了人就不可赦免。刑的根本，也是用来防止祸乱的。如果说不要行凶虐害，那么凡是治理百姓的人杀了人就不可赦免。它们的根本是一致的，它们的运用则不同，表彰与处死不能并用。处死应该表彰的，这就叫滥刑，亵渎刑法太严重了。表彰应该处死的，这就叫僭越，败坏礼制太严重了。如果把这昭示天下，传到后代，趋赴道义的人不知方向，躲避祸害的人不知立身，把这作为典章可以吗？圣人的制度，穷究事理来定赏罚，根据实情来正褒贬，统一于一个道理罢了。\n假使当初审讯查明它的真假，考察校正它的曲直，追溯本源而探求它的起因，那么刑礼的运用，就判然分开了。为什么呢？如果徐元庆的父亲，没有犯公罪，赵师韫杀他，只是因为他的私怨，逞其官吏的威势，虐害无辜，州牧不知道治罪，刑官不知道过问，上下蒙蔽，呼号不被听闻；而徐元庆能把与仇人共戴天看作大耻，把枕着兵器睡觉看作合礼，处心积虑，来直刺仇人的胸膛，坚忍自克，即使死了也没有遗憾，这是守礼而行义。执事的人应该有惭愧之色，谢罪还来不及，又为什么要处死他呢？\n如果徐元庆的父亲，不能免于罪，赵师韫杀他，没有违背法律，那么不是死于官吏之手，而是死于法律。法律难道可以仇恨吗？仇恨天子的法律，而杀害执法的官吏，这是悖逆傲慢而凌犯君上。抓起来处死他，是用来端正国家的典章，又为什么要表彰呢？\n况且那个建议说：「人一定有儿子，儿子一定有父母，亲亲相仇，那祸乱谁来救？」这是被礼弄糊涂得太厉害了。礼所说的仇，是说那冤屈压抑沉痛而呼号无处申诉的；不是说抵罪触法，陷于大戮的。却说「他杀了人，我就杀他」。不论曲直，只是暴虐孤寡威胁弱小罢了。它违背经典、背离圣人，不也太严重了吗！\n《周礼》：「调人，掌管调解万民的仇怨。」「凡是杀人而合乎义的，命令不要报仇，报仇的就处死。」「有反过来杀人的，诸侯各国共同仇视他。」又怎么会有亲亲相仇呢？《春秋公羊传》说：「父亲不被处死（而被害），儿子报仇是可以的。父亲被处死，儿子报仇，这是互相残杀之道，报仇不能除去祸害。」如今如果取这一点来判断两下相杀，就合于礼了。况且不忘仇恨，是孝；不吝惜死，是义。徐元庆能不逾越礼，服行孝道、死于道义，这一定是通达事理而闻道的人。通达事理闻道的人，难道会把王法当作敌仇吗？议论的人反以为要处死他，亵渎刑法败坏礼制，不可以作为典章，是明白的了。\n请求把臣的议论附于法令。有判决这类案件的，不应该按照先前的议论办事。谨议。"],
    [61, "guwen-gwj-195", "", "古之传者有言成王以桐叶与小弱弟戏曰「以封汝」周公入贺王曰「戏也」周公曰「天子不可戏」乃封小弱弟于唐吾意不然王之弟当封邪周公宜以时言于王不待其戏而贺以成之也不当封邪周公乃成其不中之戏以地以人与小弱者为之主其得为圣乎且周公以王之言不可苟焉而已必从而成之邪设有不幸王以桐叶戏妇寺亦将举而从之乎凡王者之德在行之何若设未得其当虽十易之不为病要于其当不可使易也而况以其戏乎若戏而必行之是周公教王遂过也吾意周公辅成王宜以道从容优乐要归之大中而已必不逢其失而为之辞又不当束缚之驰骤之使若牛马然急则败矣且家人父子尚不能以此自克况号为君臣者邪是直小丈夫𡙇𡙇者之事非周公所宜用故不可信或曰封唐叔史佚成之", "古代的传记有这样的话：周成王把桐叶给小弟弟开玩笑，说：「拿这个封你。」周公进去祝贺。成王说：「是开玩笑。」周公说：「天子不可开玩笑。」于是把小弟弟封在唐。\n我认为不是这样。成王的弟弟应当受封吗，周公就应该及时对成王说，不必等他开玩笑就去祝贺而促成它。不应当受封吗，周公竟然促成他不适当的玩笑，把土地和人民交给小弟弟让他做君主，他能算是圣人吗？况且周公认为天子的话不可随便罢了，一定要跟着促成它吗？假设有不幸，成王拿桐叶和妇人宦官开玩笑，也将会全都照办吗？\n大凡君王的德行，在于实行得怎么样。假使不合当，即使改十次也不算毛病；关键在于合当，不可使它更改，何况是拿它开玩笑呢！如果开玩笑也一定要实行，这是周公教成王遂成过错。\n我认为周公辅佐成王，应该用道，从容和乐，总之归于大中罢了，一定不会迎合他的过失而为他找说辞。又不应该束缚他，驱使他，使他像牛马一样，急了就会坏事。况且家人父子尚且不能用这个来约束自己，何况号称君臣的呢！这只是一个浅薄小丈夫拘谨琐碎的事，不是周公所应做的，所以不可信。\n有人说：封唐叔，是史佚促成的。"],
    [62, "guwen-gwj-196", "", "凡大人之道有三一曰正蒙难二曰法授圣三曰化及民殷有仁人曰箕子实具兹道以立于世故孔子述六经之旨尤殷勤焉当纣之时大道悖乱天威之动不能戒圣人之言无所用进死以并命诚仁矣无益吾祀故不为委身以存祀诚仁矣与亡吾国故不忍具是二道有行之者矣是用保其明哲与之俯仰晦是谟范辱于囚奴昏而无邪隤而不息故在易曰「箕子之明夷」正蒙难也及天命既改生人以正乃出大法用为圣师周人得以序彝伦而立大典故在书曰「以箕子归作洪范」法授圣也及封朝鲜推道训俗惟德无陋惟人无远用广殷祀俾夷为华化及民也率是大道丛于厥躬天地变化我得其正其大人欤於虖当其周时未至殷祀未殄比干已死微子已去向使纣恶未稔而自毙武庚念乱以图存国无其人谁与兴理是固人事之或然者也然则先生隐忍而为此其有志于斯乎唐某年作庙汲郡岁时致祀嘉先生独列于易象作是颂云蒙难以正授圣以谟宗祀用繁夷民其苏宪宪大人显晦不渝圣人之仁道合隆污明哲在躬不陋为奴冲让居礼不盈称孤高而无危卑不可逾非死非去有怀故都时诎而伸卒为世模易象是列文王为徒大明宣昭崇祀式孚", "大凡大人的道有三条：一是守正而蒙受患难，二是把大法传给圣人，三是教化施及百姓。殷朝有仁人叫箕子，实在具备这些道而立于世上。所以孔子叙述六经的旨意，对他尤其殷切。\n在纣王的时候，大道悖乱，天威的震动不能使他警戒，圣人的话没有用处。进谏而死同归于尽，确实是仁，但对我们的祭祀无益，所以不做。委身以保存祭祀，确实是仁，但参与灭亡我的国家，所以不忍心。这两条道，都有实行的人。因此他保全自己的明哲，与世俯仰；隐藏自己的谋略规范，屈辱于囚奴之中。昏暗而不邪恶，困顿而不止息。所以在《易》中说「箕子之明夷」，是守正而蒙难。等到天命已经改变，百姓归于正道，就拿出大法，用作圣人的老师。周人因此能够序列伦常而建立大典。所以在《书》中说「以箕子归作《洪范》」，是把大法传给圣人。等到封于朝鲜，推行道义训导风俗，有德就不嫌陋，有人就不嫌远，因此推广殷的祭祀，使夷人成为华夏，是教化施及百姓。遵循这大道，聚集在他身上，天地变化，我得到它的正，他是大人吧！\n唉！当周朝的时机还未到，殷的祭祀还未灭绝，比干已经死了，微子已经离去，假使纣的罪恶还没有满盈而自己死去，武庚考虑祸乱而图谋保存，国家没有这样的人，谁来复兴治理？这本来是人事中可能发生的。那么先生隐忍而这样做，大概是有志于此吧？\n唐朝某年，在汲郡建庙，按时祭祀。赞赏先生独自列于《易》象，作这篇颂说：\n蒙受患难以守正，把谋略传给圣人。宗庙祭祀因此繁多，夷民因此复苏。显赫的大人，显隐都一改。圣人的仁，与道同其盛衰。明哲在身，不以做奴为陋。谦冲守礼，不自满而称孤。高而不危，卑不可越。不死不去，心怀故都。时势屈而伸展，终于成为世人的楷模。《易》象中列名，与文王为伍。大明宣昭，崇祀诚服。"],
    [63, "guwen-gwj-106", "public-domain", "永州之野产异蛇黑质而白章触草木尽死以啮人无御之者然得而腊之以为饵可以已大风挛踠瘘疠去死肌杀三虫其始太医以王命聚之岁赋其二募有能捕之者当其租入永之人争奔走焉有蒋氏者专其利三世矣问之则曰「吾祖死于是吾父死于是今吾嗣为之十二年几死者数矣」言之貌若甚戚者余悲之且曰「若毒之乎余将告于莅事者更若役复若赋则何如」蒋氏大戚汪然出涕曰「君将哀而生之乎则吾斯役之不幸未若复吾赋不幸之甚也向吾不为斯役则久已病矣自吾氏三世居是乡积于今六十岁矣而乡邻之生日蹙殚其地之出竭其庐之入号呼而转徙饥渴而顿踣触风雨犯寒暑呼嘘毒疠往往而死者相藉也曩与吾祖居者今其室十无一焉与吾父居者今其室十无二三焉与吾居十二年者今其室十无四五焉非死则徙尔而吾以捕蛇独存悍吏之来吾乡叫嚣乎东西隳突乎南北哗然而骇者虽鸡狗不得宁焉吾恂恂而起视其缶而吾蛇尚存则弛然而卧谨食之时而献焉退而甘食其土之有以尽吾齿盖一岁之犯死者二焉其余则熙熙而乐岂若吾乡邻之旦旦有是哉今虽死乎此比吾乡邻之死则已后矣又安敢毒耶」余闻而愈悲孔子曰「苛政猛于虎也」吾尝疑乎是今以蒋氏观之犹信呜呼孰知赋敛之毒有甚是蛇者乎故为之说以俟夫观人风者得焉", "永州的野外出产一种奇异的蛇，黑色的底子白色的花纹，接触到草木，草木都死；如果咬了人，没有能抵御的。然而捉到它晒干做成药饵，可以治愈麻风、痉挛、颈肿、恶疮，除去坏死的肌肉，杀死三种寄生虫。起初，太医奉王命收集它，每年征收两次，招募能捕捉的人，抵当他们的租税。永州的人争相去做这件事。\n有个姓蒋的人，专享这个好处三代了。问他，就说：「我的祖父死在这上面，我的父亲死在这上面，如今我继承这差事十二年，几乎死了好几次了。」说这话时，神色像是很悲伤。\n我为他悲伤，并且说：「你怨恨这差事吗？我将告诉主管的人，更换你的差役，恢复你的赋税，怎么样？」\n蒋氏非常悲伤，流着泪说：「您是哀怜我想让我活下去吗？那么我这差事的不幸，还不如恢复我赋税的不幸厉害。从前我如果不做这差事，那就早已困苦不堪了。自从我家三代住在这个乡里，累积到现在六十年了，而乡邻的生活一天天窘迫。用尽他们土地的出产，耗尽他们家中的收入，哭喊着辗转迁徙，饥渴得倒地，冒着风雨，顶着寒暑，呼吸着毒气，往往死的人相互叠压。从前同我祖父同住的，如今他们的家十户不剩一户；同我父亲同住的，如今十户不剩两三户；同我住了十二年的，如今十户不剩四五户。不是死了就是迁走了，而我因为捕蛇独自存活。凶悍的官吏来到我们乡里，到处叫嚣，到处冲撞，喧哗惊扰，即使鸡狗也不得安宁。我小心地起来，看看那个瓦罐，我的蛇还在，就放心地躺下。小心地喂养它，按时献上去。回来就甘美地吃我土地里的出产，来度过我的余年。大概一年之中冒死的危险两次，其余就快快乐乐，哪里像我的乡邻那样天天有这样的危险呢！如今即使死在这上面，比起我乡邻的死也已经晚了，又怎么敢怨恨呢？」\n我听了更加悲伤。孔子说：「苛政比老虎还凶猛。」我曾经怀疑这话，如今从蒋氏看来，还是可信的。唉！谁知道赋敛的毒害，比这蛇更厉害呢！所以我写了这篇说，来等待那些考察民风的人得到它。"],
    [64, "guwen-gwj-197", "", "郭橐驼不知始何名病偻隆然伏行有类橐驼者故乡人号之「驼」驼闻之曰「甚善名我固当」因舍其名亦自谓「橐驼」云其乡曰丰乐乡在长安西驼业种树凡长安豪富人为观游及卖果者皆争迎取养视驼所种树或移徙无不活且硕茂蚤实以蕃他植者虽窥伺效慕莫能如也有问之对曰「橐驼非能使木寿且孳也以能顺木之天以致其性焉尔凡植木之性其本欲舒其培欲平其土欲故其筑欲密既然已勿动勿虑去不复顾其莳也若子其置也若弃则其天者全而其性得矣故吾不害其长而已非有能硕茂之也不抑耗其实而已非有能蚤而蕃之也他植者则不然根拳而土易其培之也若不过焉则不及苟有能反是者则又爱之太恩忧之太勤旦视而暮抚已去而复顾甚者爪其肤以验其生枯摇其本以观其疏密而木之性日以离矣虽曰爱之其实害之虽曰忧之其实仇之故不我若也吾又何能为哉」问者曰「以子之道移之官理可乎」驼曰「我知种树而已理非吾业也然吾居乡见长人者好烦其令若甚怜焉而卒以祸旦暮吏来而呼曰『官命促尔耕勖尔植督尔获蚤缫而绪蚤织而缕字而幼孩遂而鸡豚』鸣鼓而聚之击木而召之吾小人辍飧饔以劳吏者且不得暇又何以蕃吾生而安吾性耶故病且怠若是则与吾业者其亦有类乎」问者嘻曰「不亦善夫吾问养树得养人术」传其事以为官戒也", "郭橐驼，不知起初叫什么名字。患了驼背，隆起背脊弯腰走路，有点像骆驼，所以乡里人叫他「驼」。驼听到后说：「很好，这样叫我本来恰当。」于是舍弃原名，也自称「橐驼」。他的乡叫丰乐乡，在长安西边。驼以种树为业，凡是长安的富豪人家为了观赏游览以及卖果子的，都争着迎接供养他。看驼所种的树，或者移栽的，没有不活的；而且高大茂盛，早结果实且繁多。其他种树的人虽然窥视效仿，没有能比得上他的。\n有人问他，他回答说：「橐驼并不是能使树木长寿而且繁殖，只是能顺应树木的天性而使它的本性得以发展罢了。大凡种植树木的规律，它的根要舒展，它的培土要平匀，它的土要原来的，它的夯实要紧密。这样做了之后，不要动它不要忧虑它，离开不再回头看。栽种时像对待孩子，放置时像丢弃一样，那么它的天性就保全而它的本性就得到了。所以我不妨害它的生长罢了，并不是有能使它高大茂盛的本领；不抑制损耗它的果实罢了，并不是有能使它早结果、结多的本领。别的种树人却不这样：树根卷曲而土换新的，他们培土，不是过多就是不足。如果有能反过来做的，就又太爱惜它、担忧它太勤，早晨看晚上摸，已经离开又回头看。更过分的用指甲抓破树皮来验证它是活是枯，摇动树根来看土的松紧，而树木的本性就一天天失去了。虽然说是爱它，其实是害它；虽然说是担忧它，其实是仇恨它。所以他们比不上我。我又有什么本领呢！」\n问他的人说：「拿您的道理，移到做官治理上，可以吗？」驼说：「我只会种树罢了，治理，不是我的本行。然而我住在乡里，看到做官的人喜欢烦琐地发布政令，像是很怜爱百姓，而最终因此成祸。早晚官吏来呼喊道：『官府命令催促你们耕地，勉励你们种植，督责你们收获，早点煮茧抽丝，早点织布成缕，养育你们的小孩，喂大你们的鸡猪。』敲鼓聚集他们，敲梆子召唤他们。我们小民停下饭食来慰劳官吏尚且不得空闲，又怎么能繁殖我们的生计而安定我们的本性呢？所以困苦而懈怠。像这样，那么与我种树的行业大概也有相似之处吧？」\n问他的人笑着说：「不也很好吗！我问种树，却得到了养人的方法。」把这件事记下来作为做官的鉴戒。"],
    [65, "guwen-gwj-198", "", "裴封叔之第在光德里有梓人款其门愿佣隙宇而处焉所职寻引规矩绳墨家不居砻斫之器问其能曰「吾善度材视栋宇之制高深圆方短长之宜吾指使而群工役焉舍我众莫能就一宇故食于官府吾受禄三倍作于私家吾收其直太半焉」他日入其室其床阙足而不能理曰「将求他工」余甚笑之谓其无能而贪禄嗜货者其后京兆尹将饰官署余往过焉委群材会众工或执斧斤或执刀锯皆环立向之梓人左持引右执杖而中处焉量栋宇之任视木之能举挥其杖曰「斧」彼执斧者奔而右顾而指曰「锯」彼执锯者趋而左俄而斤者斫刀者削皆视其色俟其言莫敢自断者其不胜任者怒而退之亦莫敢愠焉画宫于堵盈尺而曲尽其制计其毫厘而构大厦无进退焉既成书于上栋曰「某年某月某日某建」则其姓字也凡执用之工不在列余圜视大骇然后知其术之工大矣继而叹曰彼将舍其手艺专其心智而能知体要者欤吾闻劳心者役人劳力者役于人彼其劳心者欤能者用而智者谋彼其智者欤是足为佐天子相天下法矣物莫近乎此也彼为天下者本于人其执役者为徒隶为乡师里胥其上为下士又其上为中士为上士又其上为大夫为卿为公离而为六职判而为百役外薄四海有方伯连率郡有守邑有宰皆有佐政其下有胥吏又其下皆有啬夫版尹以就役焉犹众工之各有执伎以食力也彼佐天子相天下者举而加焉指而使焉条其纲纪而盈缩焉齐其法制而整顿焉犹梓人之有规矩绳墨以定制也择天下之士使称其职居天下之人使安其业视都知野视野知国视国知天下其远迩细大可手据其图而究焉犹梓人画宫于堵而绩于成也能者进而由之使无所德不能者退而休之亦莫敢愠不炫能不矜名不亲小劳不侵众官日与天下之英才讨论其大经犹梓人之善运众工而不伐艺也夫然后相道得而万国理矣相道既得万国既理天下举首而望曰「吾相之功也」后之人循迹而慕曰「彼相之才也」士或谈殷周之理者曰伊傅周召其百执事之勤劳而不得纪焉犹梓人自名其功而执用者不列也大哉相乎通是道者所谓相而已矣其不知体要者反此以恪勤为公以簿书为尊炫能矜名亲小劳侵众官窃取六职百役之事听听于府庭而遗其大者远者焉所谓不通是道者也犹梓人而不知绳墨之曲直规矩之方圆寻引之短长姑夺众工之斧斤刀锯以佐其艺又不能备其工以至败绩用而无所成也不亦谬欤或曰「彼主为室者傥或发其私智牵制梓人之虑夺其世守而道谋是用虽不能成功岂其罪邪亦在任之而已」余曰不然夫绳墨诚陈规矩诚设高者不可抑而下也狭者不可张而广也由我则固不由我则圮彼将乐去固而就圮也则卷其术默其智悠尔而去不屈吾道是诚良梓人耳其或嗜其货利忍而不能舍也丧其制量屈而不能守也栋桡屋坏则曰「非我罪也」可乎哉可乎哉余谓梓人之道类于相故书而藏之梓人盖古之审曲面势者今谓之都料匠云余所遇者杨氏潜其名", "裴封叔的宅第，在光德里。有个木匠来敲门，愿意租借空屋居住。他随身带的只有量尺、圆规曲尺、墨线，家里不放磨刀斧的工具。问他的技能，他说：「我善于估算木材，看房屋的规格，高深方圆长短的适宜，我指挥而众工匠操作。没有我，众人不能建成一座房屋。所以在官府干活，我领三倍的俸禄；在私家干活，我收取工钱的大半。」有一天，我进他的屋子，他的床缺了腿却不能修，说：「将找别的工匠。」我很笑话他，认为他是没有本事却贪图俸禄、嗜好财货的人。\n此后京兆尹要修缮官署，我前去经过那里。堆积着各种木材，会集着众工匠。有的拿着斧头，有的拿着刀锯，都环立向着木匠。木匠左手拿着量尺、右手拿着木杖，站在中间。估量房屋的承重，看木材的能举起什么，挥动他的木杖说「斧！」那些拿斧头的就奔向右；回头指着说「锯！」那些拿锯的就快步向左。一会儿拿斧头的砍，拿刀的削，都看他的脸色，等他的吩咐，没有敢自作决断的。那些不能胜任的，他发怒让他们退下，也没有谁敢怨恨。在墙上画房屋的图样，一尺大小却详尽地画出它的规格，计算它的毫厘而建构大厦，没有差错。建成之后，在上栋写上「某年某月某日某人建」，就是他的姓字。所有操作使用的工匠都不列名。我环视大为惊骇，然后知道他的技术高明广大了。\n接着感叹说：他将舍弃他的手艺，专一他的心智，而能知道事情的体要吧！我听说劳心的人役使别人，劳力的人被人役使。他大概是劳心的人吧！能的人被任用而智的人谋划，他大概是智的人吧！这足以作为辅佐天子、治理天下的法则了。事物没有比这更接近的了。那治理天下的人以人为根本。那些服役的，是徒隶，是乡师、里胥；其上为下士，又其上为中士，为上士；又其上为大夫，为卿，为公。分开为六职，分别为百役。外面直到四海，有方伯、连率。郡有守，邑有宰，都有辅佐政务的人。其下有胥吏，又其下都有啬夫、版尹，来就役，如同众工匠各有手艺来靠力气吃饭。那辅佐天子治理天下的人，举拔而委任，指示而使用，整理纲纪而增减，整顿法制而齐一，如同木匠有规矩、绳墨来定规格。选择天下的士人，使他们称职；安置天下的百姓，使他们安业。看都城就知道野外，看野外就知道国中，看国中就知道天下，远近大小，可以手按图册而推究，如同木匠在墙上画房屋图而成效实现。能的人进用而由着他，使无所感激；不能的人退去而休养，也没有谁敢怨恨。不炫耀才能，不矜夸名声，不亲自做小劳，不侵夺众官的职守，每天与天下的英才讨论大经，如同木匠善于运用众工匠而不夸耀自己的技艺。这样之后相道就得到而万国就治理了。\n相道既已得到，万国既已治理，天下人抬着头望说：「这是我们宰相的功劳。」后人循着事迹仰慕说：「那是宰相的才能。」士人有的谈论殷、周的治理，说伊尹、傅说、周公、召公，那些百官勤劳却不能被记载，如同木匠自己署名记功而操作的工匠不列名。伟大啊宰相！通晓这个道的，就是所谓的宰相罢了。\n那不知道体要的人与此相反：把恭谨勤勉当作公，把文书当作尊贵，炫耀才能矜夸名声，亲自做小劳，侵夺众官，窃取六职百役的事务，在府庭中争辩，而遗漏了大而远的事，这就是所谓不通晓这个道的人。如同木匠不知道绳墨的曲直、规矩的方圆、量尺的长短，姑且夺过众工匠的斧头刀锯来帮助自己的技艺，又不能完备他们的工作，以至于败坏事功而无所成就。不也荒谬吗？\n有人说：「那主持建房的人，倘若有人发挥他的私智，牵制木匠的思虑，夺去他世代相守的规矩而采用路上人的谋划，虽然不能成功，难道是他的罪吗？也在于任用他罢了。」我说：不是这样。绳墨确实陈设，规矩确实设置，高的不能压下来，窄的不能撑宽。由我就能牢固，不由我就倒塌。他将乐意去掉牢固而趋就倒塌，那么我就收起我的技术，沉默我的智慧，悠然离去，不使我的道屈服，这才是真正好的木匠。如果贪图他的财利，忍而不能舍弃，丧失自己的规格，屈而不能守，栋梁弯曲房屋毁坏，却说「不是我的罪」，可以吗，可以吗？\n我认为木匠的道与宰相相似，所以写下来收藏。木匠，大概是古代审察曲直、度量形势的人，如今叫做都料匠。我所遇到的那个人，姓杨，名潜。"],
    [66, "guwen-gwj-107", "public-domain", "灌水之阳有溪焉东流入于潇水或曰冉氏尝居也故姓是溪为冉溪或曰可以染也名之以其能故谓之染溪余以愚触罪谪潇水上爱是溪入二三里得其尤绝者家焉古有愚公谷今予家是溪而名莫能定土之居者犹龂龂然不可以不更也故更之为愚溪愚溪之上买小丘为愚丘自愚丘东北行六十步得泉焉又买居之为愚泉愚泉凡六穴皆出山下平地盖上出也合流屈曲而南为愚沟遂负土累石塞其隘为愚池愚池之东为愚堂其南为愚亭池之中为愚岛嘉木异石错置皆山水之奇者以余故咸以愚辱焉夫水智者乐也今是溪独见辱于愚何哉盖其流甚下不可以灌溉又峻急多坻石大舟不可入也幽邃浅狭蛟龙不屑不能兴云雨无以利世而适类于余然则虽辱而愚之可也宁武子「邦无道则愚」智而为愚者也颜子「终日不违如愚」睿而为愚者也皆不得为真愚今余遭有道而违于理悖于事故凡为愚者莫我若也夫然则天下莫能争是溪余得专而名焉溪虽莫利于世而善鉴万类清莹秀澈锵鸣金石能使愚者喜笑眷慕乐而不能去也余虽不合于俗亦颇以文墨自慰漱涤万物牢笼百态而无所避之以愚辞歌愚溪则茫然而不违昏然而同归超鸿蒙混希夷寂寥而莫我知也于是作八愚诗纪于溪石上", "灌水的北面有一条溪，向东流入潇水。有人说：冉氏曾在这里住过，所以用姓称这溪为冉溪。有人说：可以用它染色，以它的功用命名，所以叫它染溪。我因为愚笨而犯罪，被贬到潇水边，喜爱这条溪，往里走二三里，找到其中特别好的地方安了家。古代有愚公谷，如今我家在这条溪边，而名字不能确定，当地居民还争辩不休，不可以不改，所以改称它为愚溪。\n在愚溪之上，买了一处小丘，叫愚丘。从愚丘向东北走六十步，找到一眼泉，又买下居住，叫愚泉。愚泉共有六个泉眼，都从山下平地涌出，大概是向上冒的。汇合成流曲折向南，叫愚沟。于是挑土堆石，堵住狭窄处，叫愚池。愚池的东面是愚堂，南面是愚亭，池中叫愚岛。好的树木奇异的石头交错布置，都是山水中奇特的，因为我的缘故，都用愚的名字玷辱了。\n水，是智者所喜爱的。如今这条溪独独被愚玷辱，为什么呢？因为它水流很低，不能用来灌溉；又险峻湍急，多沙洲石头，大船不能进入；幽深浅狭，蛟龙不屑居住，不能兴云下雨。没有什么利于世，而恰好同我相似，那么即使玷辱而称它为愚，也是可以的。\n宁武子「国家无道就装愚」，是明智而装愚；颜子「整天不违逆像愚人」，是聪慧而装愚。都不能算是真愚。如今我遭遇有道的时代，却违背道理，违背事理，所以凡是称愚的都不如我。这样，那么天下没有人能争这条溪，我得以独占而命名它。\n溪虽然没有什么利于世，却善于照见万物，清莹秀澈，像金石一样铿锵作响，能使愚者喜笑眷恋，快乐得不愿离开。我虽然不合世俗，也颇能以文墨自慰，洗涤万物，包罗百态，而无所回避。用愚拙的文辞歌唱愚溪，就茫然不违，昏然同归，超脱于混沌，混同于虚寂，寂寥而没有人知道我。于是作《八愚诗》，记在溪石上。"],
    [67, "guwen-gwj-199", "", "将为穹谷嵁岩渊池于郊邑之中则必辇山石沟涧壑陵绝险阻疲极人力乃可以有为也然而求天作地生之状咸无得焉逸其人因其地全其天昔之所难今于是乎在永州实惟九疑之麓其始度土者环山为城有石焉翳于奥草有泉焉伏于土涂蛇虺之所蟠狸鼠之所游茂树恶木嘉葩毒卉乱杂而争植号为秽墟韦公之来既逾月理甚无事望其地且异之始命芟其芜行其涂积之丘如蠲之浏如既焚既酾奇势迭出清浊辨质美恶异位视其植则清秀敷舒视其蓄则溶漾纡馀怪石森然周于四隅或列或跪或立或仆窍穴逶邃堆阜突怒乃作栋宇以为观游凡其物类无不合形辅势效伎于堂庑之下外之连山高原林麓之崖间厕隐显迩延野绿远混天碧咸会于谯门之内已乃延客入观继以宴娱或赞且贺曰「见公之作知公之志公之因土而得胜岂不欲因俗以成化公之择恶而取美岂不欲除残而佑仁公之蠲浊而流清岂不欲废贪而立廉公之居高以望远岂不欲家抚而户晓夫然则是堂也岂独草木土石水泉之适欤山原林麓之观欤将使继公之理者视其细知其大也」宗元请志诸石措诸屋漏以为二千石楷法", "要在城郊之中造出深谷高岩深池，就一定要用车搬运山石，开凿涧壑，越过险阻，耗尽人力，才可以有所作为。然而要求天造地设的样子，都得不到。使百姓安逸，顺应地势，保全天然，从前所难的，如今在这里有了。\n永州实在在九疑山下。起初测量土地的人，环绕山建城。有石头，被深草遮蔽；有泉水，被泥土埋没。是毒蛇蟠居的地方，狐鼠游走的地方。茂盛的树和恶劣的树，美好的花和有毒的草，杂乱而争相生长，号称荒秽的废墟。\n韦公来到，过了一个月，治理得很有闲暇。望见这块地，而且觉得它奇异。才命令割除杂草，疏通道路。堆积的像山丘，疏浚的清澈。焚烧之后又疏导，奇特的形势层出。清浊分辨了质地，美恶换了位置。看那些种植的，就清秀舒展；看那些蓄积的，就荡漾曲折。怪石森然，环绕四周。有的排列有的跪伏，有的站立有的倒下，洞穴深邃，土丘突起。于是建造房屋，用来观赏游览。凡是那些物类，没有不合乎形势辅助地势，在堂庑之下献技。外面的连山高原，林麓的山崖，交错隐显，近的延展田野的绿色，远的混同天空的碧色，都汇聚在谯门之内。\n然后延请客人进来观赏，接着设宴娱乐。有人称赞并且祝贺说：「看到公的作为，知道公的志向。公顺应土地而得到胜景，难道不是想顺应风俗来成就教化？公选择美善而除去丑恶，难道不是想除去残暴而保佑仁德？公除去污浊而疏通清流，难道不是想废弃贪婪而树立廉洁？公站在高处远望，难道不是想安抚家家户户使之明白？这样的话，那么这座堂，难道只是草木土石水泉的适宜吗？山原林麓的观赏吗？将使继承公治理的人，看这些细小的事，知道那些大的道理。」\n宗元请求把它记在石上，放在屋角，作为二千石官吏的楷模。"],
    [69, "guwen-gwj-109", "public-domain", "自西山道口径北逾黄茅岭而下有二道其一西出寻之无所得其一少北而东不过四十丈土断而川分有积石横当其垠其上为睥睨梁欐之形其旁出堡坞有若门焉窥之正黑投以小石洞然有水声其响之激越良久乃已环之可上望甚远无土壤而生嘉树美箭益奇而坚其疏数偃仰类智者所施设也噫吾疑造物者之有无久矣及是愈以为诚有又怪其不为之于中州而列是夷狄更千百年不得一售其伎是固劳而无用神者傥不宜如是则其果无乎或曰「以慰夫贤而辱于此者」或曰「其气之灵不为伟人而独为是物故楚之南少人而多石」是二者余未信之", "从西山道口一直向北，越过黄茅岭往下走，有两条路：其中一条向西伸出去，找它没有什么发现；其中一条稍偏北而向东，不过四十丈，土地断裂而河流分流，有堆积的石头横在它的边际。它上面呈现出城墙梁栋的形状，旁边突出像堡坞，有个像门的地方。往里看正黑，投进小石头，洞然有水声，那声音激越，很久才停。绕着它可以上去，望得很远，没有土壤却长出好树美竹，更加奇特而坚实，它们疏密俯仰，像是智者所布置的。\n唉！我怀疑造物者的有无已经很久了。到了这里，越发认为确实有。又奇怪它不把这些放在中州，却陈列在这夷狄之地，经历千百年得不到一次显示它的技艺，这实在是劳而无用。神灵或许不该这样，那么它果然没有吗？有人说：「是用来安慰那些贤能而被辱没在这里的人。」有人说：「这里气的灵秀，不聚为伟人，而独独聚为这些东西，所以楚地之南人少而石多。」这两种说法，我都不信。"],
    [71, "guwen-gwj-110", "public-domain", "天道不言而品物亨岁功成者何谓也四时之吏五行之佐宣其气矣圣人不言而百姓亲万邦宁者何谓也三公论道六卿分职张其教矣是知君逸于上臣劳于下法乎天也古之善相天下者自咎夔至房魏可数也是不独有其德亦皆务于勤耳况夙兴夜寐以事一人卿大夫犹然况宰相乎朝廷自国初因旧制设宰臣待漏院于丹凤门之右示勤政也至若北阙向曙东方未明相君启行煌煌火城相君至止哕哕鸾声金门未辟玉漏犹滴撤盖下车于焉以息待漏之际相君其有思乎其或兆民未安思所泰之四夷未附思所来之兵革未息何以弭之田畴多芜何以辟之贤人在野我将进之佞臣立朝我将斥之六气不和灾眚荐至愿避位以禳之五刑未措欺诈日生请修德以厘之忧心忡忡待旦而入九门既启四聪甚迩相君言焉时君纳焉皇风于是乎清夷苍生以之而富庶若然则总百官食万钱非幸也宜也其或私仇未复思所逐之旧恩未报思所荣之子女玉帛何以致之车马器玩何以取之奸人附势我将陟之直士抗言我将黜之三时告灾上有忧色构巧词以悦之群吏弄法君闻怨言进谄容以媚之私心慆慆假寐而坐九门既开重瞳屡回相君言焉时君惑焉政柄于是乎隳哉帝位以之而危矣若然则死下狱投远方非不幸也亦宜也是知一国之政万人之命悬于宰相可不慎欤复有无毁无誉旅进旅退窃位而苟禄备员而全身者亦无所取焉棘寺小吏王禹偁为文请志院壁用规于执政者", "天道不说话，而万物亨通、一年的农功成就，说的是什么呢？是四时的官吏、五行的辅佐，宣导它的气。圣人不说话，而百姓亲附、万邦安宁，说的是什么呢？是三公讨论道，六卿分掌职守，张扬他的教化。由此可知君主在上面安逸，臣子在下面勤劳，是效法上天。古代善于辅佐天下的人，从皋陶、夔到房玄龄、魏征，可以数出来。这不仅是他们有德行，也都致力于勤劳。何况早起晚睡，来事奉一个人，卿大夫尚且如此，何况宰相呢！\n朝廷从开国之初沿袭旧制，在丹凤门右边设立宰臣待漏院，表示勤于政事。至于北面宫阙迎着曙光，东方还未明亮，宰相启程，火城辉煌；宰相到来，鸾铃哕哕。宫门还没有开，玉漏还在滴，撤去车盖下车，在这里休息。待漏的时候，宰相大概有所思考吧？\n或者想到万民还未安定，思考怎样使他们安定；四夷还未归附，思考怎样招来他们；战争还未停息，怎样平息它；田畴多有荒芜，怎样开辟它；贤人在野，我要进荐他；佞臣在朝，我要斥退他；六气不和，灾异屡至，愿意让位来禳除它们；五刑还未搁置不用，欺诈天天产生，请修明德行来治理它们。忧心忡忡，等待天明而入朝。九门已经打开，四面的听闻很近。宰相说话，当时的君主采纳。于是皇风清平，百姓因此富庶。如果这样，那么统领百官、食禄万钱，不是侥幸，而是应该的。\n或者想到私仇未报，思考怎样驱逐他；旧恩未报，思考怎样使他荣耀；子女玉帛，怎样取得；车马器玩，怎样获取；奸邪的人依附权势，我将提升他；正直的人直言抗辩，我将贬黜他；三时报告灾情，皇上有忧愁之色，编造巧妙的言辞来使他高兴；群吏玩弄法律，君主听到怨言，就献上谄媚之态来讨好。私心滔滔，坐着打盹。九门已经打开，君主的双眼屡次回顾。宰相说话，当时的君主被迷惑。于是政权败坏，帝位因此危险了！如果这样，那么死于下狱、被投远方，不是不幸，也是应该的。\n由此可知一国的政事、万人的性命，都悬在宰相身上，能不慎重吗！还有那种没有毁谤也没有赞誉，跟着众人进退，窃据职位而苟取俸禄，充数而保全自身的人，也没有什么可取的。\n大理寺小吏王禹偁写这篇文章，请刻在待漏院的墙壁上，用来规劝执政的人。"],
    [72, "guwen-gwj-111", "public-domain", "黄冈之地多竹大者如椽竹工破之刳去其节用代陶瓦比屋皆然以其价廉而工省也子城西北隅雉堞圮毁蓁莽荒秽因作小楼二间与月波楼通远吞山光平挹江濑幽阒辽敻不可具状夏宜急雨有瀑布声冬宜密雪有碎玉声宜鼓琴琴调虚畅宜咏诗诗韵清绝宜围棋子声丁丁然宜投壶矢声铮铮然皆竹楼之所助也公退之暇披鹤氅戴华阳巾手执周易一卷焚香默坐消遣世虑江山之外第见风帆沙鸟烟云竹树而已待其酒力醒茶烟歇送夕阳迎素月亦谪居之胜概也彼齐云落星高则高矣井干丽谯华则华矣止于贮妓女藏歌舞非骚人之事吾所不取吾闻竹工云「竹之为瓦仅十稔若重覆之得二十稔」噫吾以至道乙未岁自翰林出滁上丙申移广陵丁酉又入西掖戊戌岁除日有齐安之命己亥闰三月到郡四年之间奔走不暇未知明年又在何处岂惧竹楼之易朽乎幸后之人与我同志嗣而葺之庶斯楼之不朽也咸平二年八月十五日记", "黄冈这地方多竹，大的像椽子。竹工剖开它，挖去竹节，用来代替陶瓦。家家户户都这样，因为它价钱便宜而省工。\n子城的西北角，城墙坍塌毁坏，杂草丛生荒芜污秽，于是建了两间小楼，同月波楼相通。远望可以吞纳山光，平视可以汲取江流，幽静深远，不能一一描述。夏天适合急雨，有瀑布的声音；冬天适合密雪，有碎玉的声音。适合弹琴，琴调虚畅；适合吟诗，诗韵清绝；适合下围棋，棋子声丁丁；适合投壶，箭声铮铮：都是竹楼所助成的。\n办完公事闲暇时，披着鹤氅，戴着华阳巾，手拿《周易》一卷，焚香默坐，消解世俗的思虑。江山之外，只见风帆沙鸟、烟云竹树罢了。等到酒力醒来，茶烟散去，送走夕阳，迎来素月，也是贬谪生活中的胜景。\n那齐云楼、落星楼，高是高了；井干楼、丽谯楼，华美是华美了。只是用来藏妓女、蓄歌舞，不是风雅之士的事，我不取。\n我听竹工说：「竹子做瓦，只能用十年；如果重叠覆盖，可以用二十年。」唉！我在至道乙未年，从翰林院出任滁州，丙申年调任广陵，丁酉年又入西掖，戊戌年除夕，有齐安的命令，己亥年闰三月到郡。四年之间，奔走不停，不知道明年又在哪里，难道还怕竹楼容易朽坏吗？希望后世的人同我志同道合，继续修缮它，或许这座楼可以不朽。\n咸平二年八月十五日记。"],
    [73, "guwen-gwj-112", "public-domain", "洛阳处天下之中挟殽黾之阻当秦陇之襟喉而赵魏之走集盖四方必争之地也天下当无事则已有事则洛阳必先受兵予故尝曰洛阳之盛衰天下治乱之候也方唐贞观开元之间公卿贵戚开馆列第于东都者号千有余邸及其乱离继以五季之酷其池塘竹树兵车蹂践废而为丘墟高亭大榭烟火焚燎化而为灰烬与唐共灭而俱亡者无余处矣予故尝曰园圃之兴废洛阳盛衰之候也且天下之治乱候于洛阳之盛衰而知洛阳之盛衰候于园圃之兴废而得则洛阳名园记予岂徒然哉呜呼公卿大夫方进于朝放乎一己之私意以自为而忘天下之治忽欲退享此乐得乎唐之末路是已", "洛阳处在天下的中央，倚仗殽山、黾厄的险阻，正当秦、陇的襟喉，又是赵、魏往来的要冲，是四方必争的地方。天下太平也就罢了，一旦有事，那么洛阳一定先受兵灾。所以我曾经说：洛阳的盛衰，是天下治乱的征兆。\n当唐贞观、开元之间，公卿贵戚在东都开设馆舍、排列宅第的，号称一千多所。等到它战乱流离，接着是五代之酷，那些池塘竹树，被兵车践踏，荒废成为丘墟；高亭大榭，被烟火焚烧，化为灰烬，同唐朝一起灭亡的，没有一处留下了。所以我曾经说：园圃的兴废，是洛阳盛衰的征兆。\n况且天下的治乱，从洛阳的盛衰来观察就可以知道；洛阳的盛衰，从园圃的兴废来观察就可以得到。那么《洛阳名园记》，我难道是白写的吗？\n唉！公卿大夫正进用于朝廷，放纵自己一人的私意而任意作为，忘记了天下的治乱，想要退隐享受这种快乐，能得到吗？唐朝的末路就是这样。"],
    [74, "guwen-gwj-113", "public-domain", "先生汉光武之故人也相尚以道及帝握赤符乘六龙得圣人之时臣妾亿兆天下孰加焉惟先生以节高之既而动星象归江湖得圣人之清泥涂轩冕天下孰加焉惟光武以礼下之在蛊之上九众方有为而独「不事王侯高尚其事」先生以之在屯之初九阳德方亨而能「以贵下贱大得民也」光武以之盖先生之心出乎日月之上光武之量包乎天地之外微先生不能成光武之大微光武岂能遂先生之高哉而使贪夫廉懦夫立是大有功于名教也仲淹来守是邦始构堂而奠焉乃复为其后者四家以奉祠事又从而歌曰「云山苍苍江水泱泱先生之风山高水长」", "严先生是汉光武帝的旧交。他们以道义互相推重。到光武帝掌握赤符、乘六龙、得圣人之时，臣妾亿兆，天下谁能超过他？只有先生以节操高于他。后来先生感动星象，归隐江湖，得圣人之清。把官爵看作泥土，天下谁能超过他？只有光武帝以礼相待而居于他之下。\n在《蛊》卦的上九，众人都将有作为，而独独「不事奉王侯，以自己所做的事为高」，先生就是这样。在《屯》卦的初九，阳德正亨通，而能「以尊贵居卑贱之下，大得民心」，光武帝就是这样。先生的心，超出日月之上；光武帝的气量，包容天地之外。没有先生不能成就光武帝的宏大，没有光武帝怎么能成就先生的高洁呢？而使贪婪的人廉洁、懦弱的人自立，这对名教是有大功的。\n范仲淹来做这个州的太守，才建造祠堂来祭奠他，于是免除他后代的四家赋税，来供奉祭祀之事。又跟着歌颂说：「云山苍苍，江水泱泱，先生之风，山高水长！」"],
    [75, "guwen-gwj-114", "public-domain", "庆历四年春滕子京谪守巴陵郡越明年政通人和百废具兴乃重修岳阳楼增其旧制刻唐贤今人诗赋于其上属予作文以记之予观夫巴陵胜状在洞庭一湖衔远山吞长江浩浩汤汤横无际涯朝晖夕阴气象万千此则岳阳楼之大观也前人之述备矣然则北通巫峡南极潇湘迁客骚人多会于此览物之情得无异乎若夫霪雨霏霏连月不开阴风怒号浊浪排空日星隐耀山岳潜形商旅不行樯倾楫摧薄暮冥冥虎啸猿啼登斯楼也则有去国怀乡忧谗畏讥满目萧然感极而悲者矣至若春和景明波澜不惊上下天光一碧万顷沙鸥翔集锦鳞游泳岸芷汀兰郁郁青青而或长烟一空皓月千里浮光跃金静影沉璧渔歌互答此乐何极登斯楼也则有心旷神怡宠辱偕忘把酒临风其喜洋洋者矣嗟夫予尝求古仁人之心或异二者之为何哉不以物喜不以己悲居庙堂之高则忧其民处江湖之远则忧其君是进亦忧退亦忧然则何时而乐耶其必曰「先天下之忧而忧后天下之乐而乐」乎噫微斯人吾谁与归时六年九月十五日", "庆历四年春天，滕子京被贬做巴陵郡太守。到了第二年，政事顺利、百姓和睦，各种荒废的事业都兴办起来，于是重新修建岳阳楼，扩大它原有的规模，把唐代名家和当代人的诗赋刻在它上面，嘱托我写文章来记述这件事。\n我看那巴陵的美景，全在洞庭湖上。它含着远山，吞着长江，浩浩荡荡，广阔无边；早晨阳光照耀，傍晚阴云笼罩，气象万千。这就是岳阳楼的雄伟景象，前人的记述已经很详尽了。既然这样，那么它北面通向巫峡，南面直到潇水湘水，降职的官员和诗人，大多在这里聚会，观览景物的心情，能没有不同吗？\n至于阴雨连绵，接连几个月不放晴，阴风怒号，浑浊的浪头冲向天空；日月星辰隐没了光辉，山岳潜藏了形体；商人旅客不能通行，桅杆倾倒船桨折断；傍晚天色昏暗，老虎长啸猿猴悲啼。登上这座楼，就有离开国都、怀念家乡，担心谗言、害怕讥讽，满眼萧条，感慨到极点而悲伤的了。\n至于春风和暖、阳光明媚，波澜不起，上下天色湖光，一片碧绿广阔无边；沙鸥飞翔聚集，美丽的鱼儿游来游去；岸上的芷草和小洲上的兰花，香气浓郁颜色青翠。有时大片的烟雾完全消散，皎洁的月光一泻千里，浮动的光闪耀着金色，静静的月影像沉下的玉璧；渔歌互相应答，这种快乐哪有穷尽！登上这座楼，就心胸开阔精神愉快，荣耀和屈辱一起忘掉，端着酒杯迎着清风，那是喜气洋洋的了。\n唉！我曾经探求古代仁人的心境，或许不同于以上两种表现。为什么呢？他们不因外物而喜，不因自己而悲。在朝廷做官就为百姓忧虑；退处江湖就为君主忧虑。这样进也忧虑，退也忧虑。那么什么时候才快乐呢？他们一定会说：「在天下人忧愁之前先忧愁，在天下人快乐之后才快乐」吧！唉！如果没有这种人，我同谁一道呢？\n写于庆历六年九月十五日。"],
    [76, "guwen-gwj-115", "public-domain", "古者谏无官自公卿大夫至于工商无不得谏者汉兴以来始置官夫以天下之政四海之众得失利病萃于一官使言之其为任亦重矣居是官者常志其大舍其细先其急后其缓专利国家而不为身谋彼汲汲于名者犹汲汲于利也其间相去何远哉天禧初真宗诏置谏官六员责其职事庆历中钱君始书其名于版光恐久而漫灭嘉祐八年刻著于石后之人将历指其名而议之曰「某也忠某也诈某也直某也曲」呜呼可不惧哉", "古时候谏议没有专职官员，从公卿大夫到工匠商人，没有不能进谏的。汉朝兴起以来，才开始设置专职官员。以天下的政事、四海的民众，得失利弊，都汇集到一个官员身上让他说出来，这个责任也算重了。担任这个官职的人，应当常记着大事，舍弃细枝末节；先做急迫的，后做舒缓的；专求有利于国家而不为自身打算。那些汲汲追求名声的人，就像汲汲追求利益的人一样。这中间的差距何止很远呢！\n天禧初年，真宗下诏设置谏官六员，规定他们的职事。庆历年间，钱君才把他们的名字写在板上。我恐怕时间久了会磨灭，嘉祐八年，刻在石上。后世的人将逐一指着他们的名字议论说：「某人是忠，某人是诈，某人是直，某人是曲。」唉！能不恐惧吗！"],
    [77, "guwen-gwj-116", "public-domain", "范文正公苏人也平生好施与择其亲而贫疏而贤者咸施之方贵显时置负郭常稔之田千亩号曰义田以养济群族之人日有食岁有衣嫁娶凶葬皆有赡择族之长而贤者主其计而时共出纳焉日食人一升岁衣人一缣嫁女者五十千再嫁者三十千娶妇者三十千再娶者十五千葬者如再嫁之数葬幼者十千族之聚者九十口岁入给稻八百斛以其所入给其所聚沛然有余而无穷屏而家居俟代者与焉仕而居官者罢莫给此其大较也初公之未贵显也尝有志于是矣而力未逮者二十年既而为西帅及参大政于是始有禄赐之入而终其志公既殁后世子孙修其业承其志如公之存也公虽位充禄厚而贫终其身殁之日身无以为敛子无以为丧惟以施贫活族之义遗其子而已昔晏平仲敝车羸马桓子曰「是隐君之赐也」晏子曰「自臣之贵父之族无不乘车者母之族无不足于衣食者妻之族无冻馁者齐国之士待臣而举火者三百余人如此而为隐君之赐乎彰君之赐乎」于是齐侯以晏子之觞而觞桓子予尝爱晏子好仁齐侯知贤而桓子服义也又爱晏子之仁有等级而言有次第也先父族次母族次妻族而后及其疏远之贤孟子曰「亲亲而仁民仁民而爱物」晏子为近之今观文正之义贤于平仲其规模远举又疑过之呜呼世之都三公位享万钟禄其邸第之雄车舆之饰声色之多妻孥之富止乎一己而已而族之人不得其门而入者岂少哉况于施贤乎其下为卿为大夫为士廪稍之充奉养之厚止乎一己而已而族之人操壶瓢为沟中瘠者又岂少哉况于他人乎是皆公之罪人也公之忠义满朝廷事业满边隅功名满天下后世必有史官书之者予可无录也独高其义因以遗其世云", "范文正公是苏州人。平生喜好施与，选择亲族中贫穷的、疏族中贤能的，都施与他们。\n当他显贵的时候，购置近城常年丰收的田一千亩，号称义田，用来赡养救济全族的人。每天有饭食，每年有衣服，嫁娶丧葬都有供给。选择族中年长而贤能的人主持账目，按时一同出入核算。每天吃饭每人一升，每年穿衣每人一匹细绢，嫁女给五十千，再嫁给三十千，娶媳妇给三十千，再娶给十五千，丧葬的如同再嫁之数，葬幼儿给十千。聚居的族人九十口，每年收入供给稻谷八百斛。用它所收入的，供给所聚居的，沛然有余而无穷。退居在家等待补缺的人也给予，做官在职的就停止不给。这是它的大概。\n起初，公还没有显贵时，曾经有志于此，而力量达不到的有二十年。后来做西路的统帅，又参与大政，于是才有俸禄赏赐的收入，从而完成他的志愿。公去世后，后世子孙继续他的事业，承继他的志愿，像公在世时一样。公虽然职位高俸禄厚，却终身贫穷。去世的时候，身上没有东西用来入殓，儿子没有钱办丧事。只把施舍贫穷、养活族人的道义留给他的儿子罢了。\n从前晏平仲乘坐破车瘦马，桓子说：「这是隐藏国君的赏赐。」晏子说：「自从我显贵以来，父亲的族人，没有不乘车的；母亲的族人，没有衣食不足的；妻子的族人，没有挨冻受饿的；齐国的士人，等着我才能生火做饭的有三百多人。像这样，是隐藏国君的赏赐呢？还是彰显国君的赏赐呢？」于是齐侯拿晏子的酒杯，来罚桓子。我曾经喜爱晏子好仁，齐侯知贤，而桓子服义。又喜爱晏子的仁有等级，而言辞有次第。先父族，次母族，次妻族，然后才及于疏远的贤者。孟子说：「亲爱亲人而仁爱百姓，仁爱百姓而爱惜万物。」晏子近似于此。如今看文正公的义，胜过晏平仲，他的规模远大，又恐怕超过他。\n唉！世上居三公之位、享万钟俸禄的人，他们府第的雄伟、车马的装饰、声色的众多、妻儿的富足，只限于自己罢了；而族人不得其门而入的，难道少吗？何况施与贤者呢！其下做卿、做大夫、做士的，俸禄的充足、奉养的丰厚，只限于自己罢了；而族人拿着壶瓢成为沟中饿死的尸骨的，又难道少吗？何况对别人呢！这些都是文正公的罪人。\n公的忠义充满朝廷，事业充满边隅，功名充满天下，后世必定有史官记载，我可以不记录。只是推崇他的义，因而把它留给后世。"],
    [78, "guwen-gwj-117", "public-domain", "皇帝二十有三年制诏州县立学惟时守令有哲有愚有屈力殚虑祗顺德意有假官借师苟具文书或连数城亡诵弦声倡而不和教尼不行三十有二年范阳祖君无择知袁州始至进诸生知学宫阙状大惧人材放失儒效阔疏亡以称上意旨通判颍川陈君侁闻而是之议以克合相旧夫子庙狭隘不足改为乃营治之东厥土燥刚厥位面阳厥材孔良殿堂门庑黝垩丹漆举以法故生师有舍庖廪有次百尔器备并手偕作工善吏勤晨夜展力越明年成舍菜且有日盱江李觏谂于众曰惟四代之学考诸经可见已秦以山西鏖六国欲帝万世刘氏一呼而关门不守武夫健将卖降恐后何耶诗书之道废人惟见利而不闻义焉耳孝武乘丰富世祖出戎行皆孳孳学术俗化之厚延于灵献草茅危言者折首而不悔功烈震主者闻命而释兵群雄相视不敢去臣位尚数十年教道之结人心如此今代遭圣神尔袁得圣君俾尔由庠序践古人之迹天下治则谭礼乐以陶吾民一有不幸尤当仗大节为臣死忠为子死孝使人有所法且有所赖是惟朝家教学之意若其弄笔墨以徼利达而已岂徒二三子之羞抑亦为国者之忧", "皇帝二十三年，下诏州县设立学校。当时的太守县令，有明智的有愚昧的。有的竭尽力量劳心费神，恭敬地顺承德意；有的借用官舍、借助师资，苟且具备文书。有的连绵几座城，没有诵读弦歌之声。倡导而不应和，教化受阻不能施行。\n三十二年，范阳祖无择君做袁州知州。刚到任，就召见诸生，知道学宫缺坏的情况，非常害怕人才散失、儒学功效疏阔，无法称合皇上的意旨。通判颍川陈侁君，听到后就赞同他，商议得以相合。察看旧夫子庙狭窄不足改建，于是在州治东面营建。那里土地干燥刚硬，位置面向南方，材料很好。殿堂门廊，涂饰黑白丹漆，都按法度。所以学生老师有房舍，厨房仓库有次序。各种器具齐备，众人一齐动手。工匠精良官吏勤勉，早晚出力，过了一年建成。\n祭孔的日期将到，盱江李觏劝告众人说：四代的学校，考察经书就可以见到。秦朝凭山西之地鏖战六国，想万世称帝，刘氏一呼而函谷关的门就守不住，武夫健将争先恐后地卖国投降，为什么呢？《诗》《书》的道废弃，人们只看见利而听不到义罢了。孝武帝凭借丰厚的国力，世祖出身行伍，都勤勉于学术。风俗教化的淳厚，延续到灵帝、献帝。草野危言的人，被杀头而不悔；功业震动君主的人，听到命令就交出兵权。群雄互相观望，不敢离开臣子的位置，还维持了几十年。教化维系人心到这种程度。如今的朝代遭遇圣神之君，你们袁州得到圣明的君主，使你们能从学校实践古人的行迹。天下大治，就谈论礼乐来陶冶我们的百姓；一旦有不幸，更应当仗持大节，做臣子的死于忠，做儿子的死于孝，使人们有所效法，而且有所依靠。这就是朝廷教学的本意。至于舞弄笔墨来求取利禄通达罢了，哪里只是你们几个人的羞耻，也是治理国家的人的忧患。"],
    [79, "guwen-gwj-118", "public-domain", "臣闻朋党之说自古有之惟幸人君辨其君子小人而已大凡君子与君子以同道为朋小人与小人以同利为朋此自然之理也然臣谓小人无朋惟君子则有之其故何哉小人所好者禄利也所贪者财货也当其同利之时暂相党引以为朋者伪也及其见利而争先或利尽而交疏则反相贼害虽其兄弟亲戚不能相保故臣谓小人无朋其暂为朋者伪也君子则不然所守者道义所行者忠信所惜者名节以之修身则同道而相益以之事国则同心而共济终始如一此君子之朋也故为人君者但当退小人之伪朋用君子之真朋则天下治矣尧之时小人共工驩兜等四人为一朋君子八元八恺十六人为一朋舜佐尧退四凶小人之朋而进元恺君子之朋尧之天下大治及舜自为天子而皋夔稷契等二十二人并列于朝更相称美更相推让凡二十二人为一朋而舜皆用之天下亦大治书曰「纣有臣亿万惟亿万心周有臣三千惟一心」纣之时亿万人各异心可谓不为朋矣然纣以亡国周武王之臣三千人为一大朋而周用以兴后汉献帝时尽取天下名士囚禁之目为党人及黄巾贼起汉室大乱后方悔悟尽解党人而释之然已无救矣唐之晚年渐起朋党之论及昭宗时尽杀朝之名士或投之黄河曰「此辈清流可投浊流」而唐遂亡矣夫前世之主能使人人异心不为朋莫如纣能禁绝善人为朋莫如汉献帝能诛戮清流之朋莫如唐昭宗之世然皆乱亡其国更相称美推让而不自疑莫如舜之二十二臣舜亦不疑而皆用之然而后世不诮舜为二十二人朋党所欺而称舜为聪明之圣者以能辨君子与小人也周武之世举其国之臣三千人共为一朋自古为朋之多且大莫如周然周用此以兴者善人虽多而不厌也嗟呼兴亡治乱之迹为人君者可以鉴矣", "我听说朋党的说法，自古就有，只希望君主辨明他们是君子还是小人罢了。大凡君子与君子因同道而结为朋党，小人与小人因同利而结为朋党，这是自然的道理。\n然而我认为小人没有朋党，只有君子才有。这是什么缘故呢？小人所喜好的是俸禄利益，所贪图的是财货。当他们利益相同时，暂时互相援引结为朋党的，是假的；等到看见利益就争先，或者利益尽了交情就疏远，就反过来互相残害，即使是他们的兄弟亲戚，也不能互相保全。所以我说小人没有朋党，他们暂时结为朋党的，是假的。君子却不是这样。他们所坚守的是道义，所实行的是忠信，所珍惜的是名节。用这些来修养自身，就同道而互相补益；用这些来事奉国家，就同心而共同成事；始终如一，这是君子的朋党。所以做君主的，只应当斥退小人的假朋党，任用君子的真朋党，那么天下就治理好了。\n尧的时候，小人共工、驩兜等四人结为一朋，君子八元、八恺十六人结为一朋。舜辅佐尧，斥退四凶小人的朋党，进用八元、八恺君子的朋党，尧的天下大为太平。到舜自己做天子，皋、夔、稷、契等二十二人一齐列于朝廷，互相称赞，互相推让，共二十二人结为一朋，而舜都任用他们，天下也大为太平。《尚书》说：「纣有臣亿万，但有亿万条心；周有臣三千，只有一条心。」纣的时候，亿万人各怀异心，可以说是不结朋党了，然而纣因此亡国。周武王的臣子，三千人结成一个大朋党，而周因此兴盛。后汉献帝时，把天下的名士全部逮捕囚禁，看作党人。到黄巾贼起，汉室大乱，后来才悔悟，把党人全部解除释放，然而已经无法挽救了。唐朝的晚年，渐渐兴起朋党的论调。到昭宗时，把朝中的名士全部杀掉，有的投入黄河，说：「这些清流，可以投进浊流。」而唐朝就灭亡了。\n前代的君主，能使人人各怀异心不结朋党的，没有比得上纣的；能禁绝好人结为朋党的，没有比得上汉献帝的；能诛杀清流朋党的，没有比得上唐昭宗之世的；然而都使他们的国家动乱灭亡。互相称赞推让而不自相猜疑的，没有比得上舜的二十二位臣子，舜也不猜疑而都任用他们；然而后世不讥笑舜被二十二人的朋党所欺骗，而称赞舜是聪明的圣人，因为他能辨明君子和小人。周武王的时候，把全国的三千臣子共结为一朋，自古结朋党之多且大，没有比得上周的；然而周因此兴盛，是因为好人虽多而不厌弃。\n唉！兴盛衰亡治理动乱的迹象，做君主的，可以借鉴了。"],
    [80, "guwen-gwj-119", "public-domain", "信义行于君子而刑戮施于小人刑入于死者乃罪大恶极此又小人之尤甚者也宁以义死不苟幸生而视死如归此又君子之尤难者也方唐太宗之六年录大辟囚三百余人纵使还家约其自归以就死是以君子之难能期小人之尤者以必能也其囚及期而卒自归无后者是君子之所难而小人之所易也此岂近于人情哉或曰罪大恶极诚小人矣及施恩德以临之可使变而为君子盖恩德入人之深而移人之速有如是者矣曰太宗之为此所以求此名也然安知夫纵之去也不意其必来以冀免所以纵之乎又安知夫被纵而去也不意其自归而必获免所以复来乎夫意其必来而纵之是上贼下之情也意其必免而复来是下贼上之心也吾见上下交相贼以成此名也乌有所谓施恩德与夫知信义者哉不然太宗施德于天下于兹六年矣不能使小人不为极恶大罪而一日之恩能使视死如归而存信义此又不通之论也然则何为而可曰纵而来归杀之无赦而又纵之而又来则可知为恩德之致尔然此必无之事也若夫纵而来归而赦之可偶一为之尔若屡为之则杀人者皆不死是可为天下之常法乎不可为常者其圣人之法乎是以尧舜三王之治必本于人情不立异以为高不逆情以干誉", "信义行于君子，而刑罚杀戮施加于小人。刑罚到了死刑，就是罪大恶极，这又是小人中特别严重的。宁愿为义而死，不苟且偷生，而视死如归，这又是君子中特别难得的。\n在唐太宗贞观六年，收录死囚三百多人，放他们回家，约定他们自己回来就死。这是用君子都难以做到的，期求小人中特别恶劣的人一定做到。那些囚犯到了期限终于自己回来没有迟到的，这是君子都难以做到的，而小人却容易做到。这难道近于人情吗？\n有人说：罪大恶极，确实是小人了；等到用恩德施加于他们，可以使他们变为君子。大概恩德深入人心之深、改变人之快，有这样的事。我说：太宗这样做，是为了求这个名声。然而怎么知道放他们走的时候，不是料想他们一定会来以希求赦免，所以才放他们的呢？又怎么知道被放走的人，不是料想自己回去一定会被赦免，所以才回来的呢？料想他们一定会来而放他们，是君上窥测臣下的心思；料想一定会被赦免而回来，是臣下窥测君上的心思。我看上下互相窥测而成就这个名声，哪里有所谓的施恩德和知信义呢？不然的话，太宗向天下施德，到现在六年了，不能使小人不犯极恶大罪，而一天的恩德，却能使他们视死如归而守信义，这又是说不通的论调。\n那么怎么做才可以呢？答：放他们而他们回来，杀掉不予赦免；然后再放，然后再回来，就可以知道是恩德所致了。然而这是绝不会有的事。至于放他们而回来就赦免，可以偶尔做一次。如果屡次这样做，那么杀人的都不死，这可以作为天下的常法吗？不能作为常法，难道是圣人的法吗？所以尧、舜、三王的治理，一定本于人情，不标新立异以为高，不违背人情来求取名誉。"],
    [81, "guwen-gwj-120", "public-domain", "予少以进士游京师因得尽交当世之贤豪然犹以谓国家臣一四海休兵革养息天下以无事者四十年而智谋雄伟非常之士无所用其能者往往伏而不出山林屠贩必有老死而世莫见者欲从而求之不可得其后得吾亡友石曼卿曼卿为人廓然有大志时人不能用其材曼卿亦不屈以求合无所放其意则往往从布衣野老酣嬉淋漓颠倒而不厌予疑所谓伏而不见者庶几狎而得之故尝喜从曼卿游欲因以阴求天下奇士浮屠秘演者与曼卿交最久亦能遗外世俗以气节相高二人欢然无所间曼卿隐于酒秘演隐于浮屠皆奇男子也然喜为歌诗以自娱当其极饮大醉歌吟笑呼以适天下之乐何其壮也一时贤士皆愿从其游予亦时至其室十年之间秘演北渡河东之济郓无所合困而归曼卿已死秘演亦老病嗟夫二人者予乃见其盛衰则予亦将老矣夫曼卿诗辞清绝尤称秘演之作以为雅健有诗人之意秘演状貌雄杰其胸中浩然既习于佛无所用独其诗可行于世而懒不自惜已老胠其橐尚得三四百篇皆可喜者曼卿死秘演漠然无所向闻东南多山水其巅崖崛峍江涛汹涌甚可壮也遂欲往游焉足以知其老而志在也于其将行为叙其诗因道其盛时以悲其衰庆历二年十二月二十八日庐陵欧阳修序", "我年轻时以进士身份游历京城，因而得以尽交当世的贤豪。然而还认为国家统一四海，停止战争，养育天下使无所事事已经四十年，而智谋雄伟、非同寻常的士人，无处施展他们的才能，往往隐伏不出，山林屠贩之中，必定有老死而世人见不到的，想跟从寻找他们而不能得到。此后得到我已故的朋友石曼卿。曼卿为人，开阔有大志，当时的人不能任用他的才能，曼卿也不屈节以求迎合。没有地方寄托他的心意，就往往同布衣野老酣畅嬉戏，淋漓颠倒而不厌倦。我疑心所谓隐伏不见的人，也许可以亲近而得到，所以曾经喜欢跟曼卿交游，想借此暗中寻求天下的奇士。\n僧人秘演，同曼卿交往最久，也能超脱世俗，以气节相高。二人欢然没有隔阂。曼卿隐于酒，秘演隐于佛门，都是奇男子。然而喜欢作诗歌自娱，当他们痛饮大醉，歌唱笑呼，来尽天下的快乐，多么豪壮啊！一时的贤士，都愿意跟他交游，我也时常到他的住处。十年之间，秘演北渡黄河，东到济州、郓州，没有遇合，困顿而归。曼卿已死，秘演也年老多病。唉！这两个人，我竟看到他们的盛衰，那么我也将要老了！\n曼卿的诗辞清绝，尤其称许秘演的作品，认为雅健有诗人的意趣。秘演形貌雄杰，胸中浩然，既已习佛，无处施展，只有他的诗可以流传于世，而他却懒于自惜。已经年老，打开他的行囊，还得到三四百篇，都是可喜的。\n曼卿死后，秘演茫然无所归向。听说东南多山水，那里的山崖高峻，江涛汹涌，很可以壮观，于是想去游历。足以知道他人虽老而志还在。在他将出发时，我为他的诗作序，因而叙述他盛时的情景以悲叹他的衰老。\n庆历二年十二月二十八日，庐陵欧阳修序。"],
    [82, "guwen-gwj-19", "public-domain", "晋侯不见郑伯以为贰于楚也郑子家使执讯而与之书以告赵宣子曰「寡君即位三年召蔡侯而与之事君九月蔡侯入于敝邑以行敝邑以侯宣多之难寡君是以不得与蔡侯偕十一月克减侯宣多而随蔡侯以朝于执事十二年六月归生佐寡君之嫡夷以请陈侯于楚而朝诸君十四年七月寡君又朝以蒇陈事十五年五月陈侯自敝邑往朝于君往年正月烛之武往朝夷也八月寡君又往朝以陈蔡之密迩于楚而不敢贰焉则敝邑之故也虽敝邑之事君何以不免」「在位之中一朝于襄而再见夷与孤之二三臣相及于绛虽我小国则蔑以过之矣今大国曰『尔未逞吾志』敝邑有亡无以加焉古人有言曰『畏首畏尾身其余几』又曰『鹿死不择音』小国之事大国也德则其人也不德则其鹿也铤而走险急何能择命之罔极亦知亡矣将悉敝赋以待于鯈唯执事命之文公二年六月壬申朝于齐四年为齐侵蔡亦获成于楚居大国之间而从于强令岂其罪也大国若弗图无所逃命」晋巩朔行成于郑赵穿公婿池为质焉", "晋灵公不肯会见郑穆公，认为他同楚国勾结。郑国的子家派执讯官送信给赵宣子，说：「我们国君即位三年，就召请蔡侯一同事奉贵国国君。九月，蔡侯进入敝国准备前往晋国。敝国因为侯宣多的祸难，我们国君因此不能同蔡侯同行。十一月，除掉侯宣多，就随蔡侯去朝见贵国的执事。十二年六月，归生辅佐我们国君的嫡子夷，到楚国去请求陈侯，然后朝见贵国国君。十四年七月，我们国君又去朝见，以完成陈国的事。十五年五月，陈侯从敝国前往朝见贵国国君。去年正月，烛之武前往朝见，那是为着太子的缘故。八月，我们国君又去朝见。陈、蔡两国紧挨着楚国，却不敢有二心，这都是敝国的缘故。虽然敝国这样事奉贵国国君，为什么还不能免于罪责呢？\n「我们国君在位期间，一次朝见襄公，两次朝见贵国国君。太子夷和我们几个臣子接连到绛都去。虽然我们是小国，但也没有能超过这样的了。如今大国说：『你们还没有满足我的心意。』敝国只有灭亡，再没有可以增加的了。古人有话说：『畏首畏尾，身上还剩多少？』又说：『鹿死的时候不选择荫蔽的地方。』小国事奉大国，大国若施恩德，小国就像人一样恭顺；若不施恩德，小国就像鹿一样狂奔。狂奔冒险，紧急时哪里还能选择？贵国的命令没有止境，我们也知道要灭亡了，将把敝国的全部兵赋带到鯈地等待，只听执事的命令。文公二年六月壬申日，我们国君曾朝见齐国。四年，为齐国攻打蔡国，也同楚国讲和。处在两国之间，只能听从强国的命令，难道是我们的罪过吗？大国如果不加体谅，我们无处可逃。」\n晋国的巩朔到郑国讲和，赵穿、公婿池留在郑国做人质。"],
    [83, "guwen-gwj-20", "public-domain", "楚子伐陆浑之戎遂至于洛观兵于周疆定王使王孙满劳楚子楚子问鼎之大小轻重焉对曰「在德不在鼎昔夏之方有德也远方图物贡金九牧铸鼎象物百物而为之备使民知神奸故民入川泽山林不逢不若螭魅罔两莫能逢之用能协于上下以承天休桀有昏德鼎迁于商载祀六百商纣暴虐鼎迁于周德之休明虽小重也其奸回昏乱虽大轻也天祚明德有所厎止成王定鼎于郏鄏卜世三十卜年七百天所命也周德虽衰天命未改鼎之轻重未可问也」", "楚庄王攻打陆浑之戎，于是到达洛水，在周王室的边境上陈兵示威。周定王派王孙满去慰劳楚庄王。楚庄王问起九鼎的大小轻重。王孙满答道：「在于德行而不在于鼎。从前夏朝正有德行的时候，远方把各种物象画成图献来，九州的牧长贡献铜，铸成鼎并把物象铸在上面，各种物品都齐备，让百姓知道什么是神、什么是奸邪。所以百姓进入河川、沼泽、山林，不会遇到不吉利的东西。魑魅魍魉，都不能碰上他们。因此能够上下协和，承受上天的福佑。夏桀昏乱无德，鼎迁到商朝，商朝享有六百年。商纣暴虐，鼎又迁到周朝。德行美好光明，鼎虽然小也是重的；国君奸邪昏乱，鼎虽然大也是轻的。上天赐福给有明德的人，也是有期限的。成王把鼎安放在郏鄏，占卜得知传国三十代、享国七百年，这是上天所命令的。周朝的德行虽然衰微，天命还没有改变。鼎的轻重，是不可以问的。」"],
    [84, "guwen-gwj-21", "public-domain", "晋师从齐师入自丘舆击马陉齐侯使宾媚人赂以纪甗玉磬与地不可则听客之所为宾媚人致赂晋人不可曰「必以萧同叔子为质而使齐之封内尽东其亩」对曰「萧同叔子非他寡君之母也若以匹敌则亦晋君之母也吾子布大命于诸侯而曰必质其母以为信其若王命何且是以不孝令也诗曰『孝子不匮永锡尔类』若以不孝令于诸侯其无乃非德类也乎」「先王疆理天下物土之宜而布其利故诗曰『我疆我理南东其亩』今吾子疆理诸侯而曰『尽东其亩』而已唯吾子戎车是利无顾土宜其无乃非先王之命也乎反先王则不义何以为盟主其晋实有阙」「四王之王也树德而济同欲焉五伯之霸也勤而抚之以役王命今吾子求合诸侯以逞无疆之欲诗曰『敷政优优百禄是遒』子实不优而弃百禄诸侯何害焉不然寡君之命使臣则有辞矣曰『子以君师辱于敝邑不腆敝赋以犒从者畏君之震师徒桡败吾子惠徼齐国之福不泯其社稷使继旧好唯是先君之敝器土地不敢爱子又不许请收合余烬背城借一敝邑之幸亦云从也况其不幸敢不唯命是听』」鲁卫谏曰「齐疾我矣其死亡者皆亲昵也子若不许仇我必甚唯子则又何求子得其国宝我亦得地而纾于难其荣多矣齐晋亦唯天所授岂必晋」晋人许之对曰「群臣帅赋舆以为鲁卫请若苟有以借口而复于寡君君之惠也敢不唯命是听」禽郑自师逆公秋七月晋师及齐国佐盟于爰娄使齐人归我汶阳之田", "晋军追赶齐军，从丘舆进入齐国，攻打马陉。齐顷公派宾媚人用纪国的甗、玉磬和土地去求和，如果晋国不答应，就听凭他们怎么办。宾媚人送上礼物，晋国人不同意，说：「一定要用萧同叔子做人质，并且让齐国境内的田垄全部改成东西向。」宾媚人答道：「萧同叔子不是别人，是我们国君的母亲。如果以地位相等而论，也是晋国国君的母亲。您向诸侯颁布重大的命令，却说一定要拿对方的母亲做人质才算信用，那对周王的命令怎么交代？况且这是用不孝来号令诸侯。《诗经》说：『孝子的孝心没有穷尽，永远赐给你的同类。』如果用不孝来号令诸侯，那恐怕不是用德行来示范同类吧？\n「先王划分疆界、治理天下，顺应土地的适宜，来分布它的利益，所以《诗经》说：『我划定疆界，我治理田亩，南向或东向都可以。』如今您来划分诸侯的疆界，却说『田垄全部改成东西向』，只是对您的兵车有利，不顾土地的适宜，恐怕这不是先王的命令吧？违背先王就是不义，凭什么做盟主？晋国确实有缺失。\n「四王之所以能王天下，是因为树立德行而满足共同的愿望；五霸之所以能称霸，是因为勤劳地安抚诸侯，来执行周王的命令。如今您寻求会合诸侯，来满足无止境的欲望。《诗经》说：『施政宽和，百种福禄就会聚集。』您实在不宽和，反而抛弃百种福禄，诸侯对您又有什么妨害呢？如果不这样，我们国君命令使臣时是有话说的，说：『您带领军队屈尊光临敝国，敝国用不丰厚的兵赋来犒劳您的随从。因为畏惧您的威势，我们的军队挫败了。您若能赐福给齐国，不使它的社稷灭亡，让它继续旧日的友好，那么先君留下的破旧器物和土地，我们不敢吝惜。您若又不答应，请让我们收拾残兵，背靠城墙决一死战。敝国如果侥幸得胜，也会服从贵国；何况不幸失败，怎敢不听从命令？』」\n鲁国、卫国劝谏说：「齐国恨我们了！它死去的都是亲近的人。您如果不答应，它恨我们会更厉害。您又要求什么呢？您得到它的国宝，我们也得到土地，而且解除了祸难，这荣耀够多了。齐国、晋国也都由上天授予命运，难道一定是晋国？」\n晋国人答应了，回答道：「我们群臣率领兵车为鲁国、卫国请求，如果能有借口回复我们国君，就是您的恩惠了。怎敢不听从命令？」禽郑从军中迎接鲁成公。\n秋天七月，晋军和齐国的国佐在爰娄订立盟约，让齐国人归还我国汶阳的田地。"],
    [86, "guwen-gwj-23", "public-domain", "夏四月戊午晋侯使吕相绝秦曰「昔逮我献公及穆公相好戮力同心申之以盟誓重之以昏姻天祸晋国文公如齐惠公如秦无禄献公即世穆公不忘旧德俾我惠公用能奉祀于晋又不能成大勋而为韩之师亦悔于厥心用集我文公是穆之成也」「文公躬擐甲胄跋履山川逾越险阻征东之诸侯虞夏商周之胤而朝诸秦则亦既报旧德矣郑人怒君之疆埸我文公帅诸侯及秦国郑秦大夫不询于我寡君擅及郑盟诸侯疾之将致命于秦文公恐惧绥静诸侯秦师克还无害则是我有大造于西也」「无禄文公即世穆为不吊蔑死我君寡我襄公迭我殽地奸绝我好伐我保城殄灭我费滑散离我兄弟挠乱我同盟倾覆我国家我襄公未忘君之旧勋而惧社稷之陨是以有殽之师犹愿赦罪于穆公穆公弗听而即楚谋我天诱其衷成王陨命穆公是以不克逞志于我」「穆襄即世康灵即位康公我之自出又欲阙翦我公室倾覆我社稷帅我蟊贼以来荡摇我边疆我是以有令狐之役康犹不悛入我河曲伐我涑川俘我王官翦我羁马我是以有河曲之战东道之不通则是康公绝我好也」「及君之嗣也我君景公引领西望曰『庶抚我乎』君亦不惠称盟利吾有狄难入我河县焚我箕郜芟夷我农功虔刘我边垂我是以有辅氏之聚」「君亦悔祸之延而欲徼福于先君献穆使伯车来命我景公曰『吾与女同好弃恶复修旧德以追念前勋』言誓未就景公即世我寡君是以有令狐之会君又不祥背弃盟誓白狄及君同州君之仇雠而我之昏姻也君来赐命曰『吾与女伐狄』寡君不敢顾昏姻畏君之威而受命于吏君有二心于狄曰『晋将伐女』狄应且憎是用告我楚人恶君之二三其德也亦来告我曰『秦背令狐之盟而来求盟于我昭告昊天上帝秦三公楚三王曰「余虽与晋出入余唯利是视」不穀恶其无成德是用宣之以惩不壹』」「诸侯备闻此言斯是用痛心疾首昵就寡人寡人帅以听命唯好是求君若惠顾诸侯矜哀寡人而赐之盟则寡人之愿也其承宁诸侯以退岂敢徼乱君若不施大惠寡人不佞其不能以诸侯退矣敢尽布之执事俾执事实图利之」", "夏天四月戊午日，晋厉公派吕相去同秦国断绝邦交，说：\n「从前我们献公和穆公互相友好，同心协力，用盟誓来申明，又用婚姻来加深。上天降祸给晋国，文公逃到齐国，惠公逃到秦国。不幸献公去世。穆公不忘旧日的恩德，使我们惠公能在晋国主持祭祀。但又不能成就大功，反而有了韩原之战。穆公后来心中后悔，因而成就了我们的文公。这是穆公的成全。\n「文公亲自穿上铠甲头盔，跋涉山川，越过险阻，征讨东方的诸侯，让虞、夏、商、周的后代去朝见秦国，这也就是报答了旧日的恩德了。郑国人侵犯您的边境，我们文公率领诸侯和秦国围攻郑国。秦国大夫不向我们寡君咨询，擅自同郑国结盟。诸侯对此痛恨，要同秦国拼命。文公害怕，安抚诸侯，秦军得以安然回国，没有受到损害，这就是我们对西方有大功。\n「不幸文公去世，穆公不来吊唁，轻视我们死去的国君，欺侮我们襄公，突然进犯我们的殽地，断绝我们的友好，攻打我们的城堡，灭掉我们的费滑，离散我们的兄弟之邦，扰乱我们的同盟，颠覆我们的国家。我们襄公没有忘记您旧日的功勋，但害怕国家倾覆，所以有了殽之战。战后还希望在穆公那里得到赦免，穆公不听，反而同楚国谋划对付我们。上天开导他的心意，楚成王被杀，穆公因此不能在我们这里得逞。\n「穆公、襄公去世，康公、灵公即位。康公是我们晋国女子所生，又想削弱我们的公室，颠覆我们的国家，率领我们的蟊贼，来扰乱我们的边疆。我们因此有令狐之战。康公还不悔改，侵入我们的河曲，攻打我们的涑川，俘虏我们的王官，剪除我们的羁马。我们因此有河曲之战。东去的道路不通，就是康公断绝我们的友好造成的。\n「到您继承君位，我们国君景公伸长脖子向西眺望说：『也许会来安抚我们吧！』您也不肯施惠结盟，反而乘我们有狄人的祸难，侵入我们的河县，焚烧我们的箕地、郜地，铲除我们的庄稼，屠杀我们的边民。我们因此有辅氏之战。\n「您也后悔祸患的延续，想要向先君献公、穆公求福，派伯车来命令我们景公说：『我与你同心和好、抛弃怨恨，重新修明旧日的恩德，以追念从前的功勋。』誓言还没有完成，景公去世，我们寡君因此有令狐之会。您又不怀好意，背弃盟誓。白狄与您同在一州，是您的仇敌，却是我们的姻亲。您来赐下命令说：『我与你一同攻打狄人。』寡君不敢顾念姻亲，畏惧您的威势，接受了官吏的命令。您却对狄人怀有二心，说：『晋国将要攻打你们。』狄人表面答应而心中憎恨，因此来告诉我们。楚国人厌恶您反复无常的德行，也来告诉我们说：『秦国背弃令狐之盟，而来向我们请求结盟，明告昊天上帝、秦国三公、楚国三王说：「我虽然同晋国有往来，但我只看利益。」我厌恶他没有恒定的德行，因此把它宣布出来，以惩戒不专一的人。』\n「诸侯都听到了这些话，因此痛心疾首，亲近我们国君。我们国君率领他们来听候您的命令，只是寻求和好。您若肯施惠顾念诸侯，哀怜我们国君，赐予盟约，那就是我们寡君的愿望。我们就会安抚诸侯退兵，怎敢求取祸乱？您若不施大恩，我们国君不才，就无法带领诸侯退兵了。谨把全部实情禀告您的执事，请执事切实考虑怎样有利。」"],
    [87, "guwen-gwj-24", "public-domain", "会于向为吴谋楚故也范宣子数吴之不德也以退吴人执莒公子务娄以其通楚使也将执戎子驹支范宣子亲数诸朝曰「来姜戎氏昔秦人迫逐乃祖吾离于瓜州乃祖吾离被苫盖蒙荆棘以来归我先君我先君惠公有不腆之田与女剖分而食之今诸侯之事我寡君不如昔者盖言语漏泄则职女之由诘朝之事尔无与焉与将执女」对曰「昔秦人负恃其众贪于土地逐我诸戎惠公蠲其大德谓我诸戎是四岳之裔胄也毋是翦弃赐我南鄙之田狐狸所居豺狼所嗥我诸戎除翦其荆棘驱其狐狸豺狼以为先君不侵不叛之臣至于今不贰昔文公与秦伐郑秦人窃与郑盟而舍戍焉于是乎有殽之师晋御其上戎亢其下秦师不复我诸戎实然譬如捕鹿晋人角之诸戎掎之与晋踣之戎何以不免自是以来晋之百役与我诸戎相继于时以从执政犹殽志也岂敢离逷今官之师旅无乃实有所阙以携诸侯而罪我诸戎我诸戎饮食衣服不与华同贽币不通言语不达何恶之能为不与于会亦无瞢焉」赋青蝇而退宣子辞焉使即事于会成恺悌也", "诸侯在向地会盟，是为了替吴国谋划对付楚国。范宣子责备吴国无德，以此让吴国人退出去。拘捕了莒国公子务娄，因为他同楚国的使者有往来。还要拘捕戎子驹支。范宣子在朝廷上亲自数落他，说：「过来！姜戎氏！从前秦国人把你的祖先吾离逼迫驱逐到瓜州，你的祖先吾离披着草苫、冒着荆棘，来归附我们的先君。我们的先君惠公有不多的田地，同你剖分而食。如今诸侯事奉我们寡君不如从前，大概是因为言语泄漏，这就是你的责任。明天早晨的会盟，你不要参加！如果参加，就把你抓起来！」\n驹支答道：「从前秦国人倚仗人多，贪图土地，驱逐我们各部戎人。惠公发扬他的大德，说我们各部戎人是四岳的后代，不要把它们剪除抛弃。赐给我们南部边境的田地，那是狐狸居住、豺狼嚎叫的地方。我们各部戎人除掉那里的荆棘，赶走狐狸豺狼，做你们先君不侵犯不叛离的臣属，直到今天没有二心。从前文公同秦国攻打郑国，秦国人私下同郑国结盟并留下戍守的军队，于是有了殽之战。晋国在上边抵御，戎人在下边抗拒，秦军全军覆没，实在是我们戎人的功劳。好比捕鹿，晋国人抓住它的角，戎人拖住它的腿，同晋国人一起把它打倒。戎人为什么不能免于罪责？从那以后，晋国的各种战役，我们戎人相继按时参加，跟从执政，仍像殽之战时的心意，怎敢疏远离弃？如今贵国官府的军队，恐怕确实有缺失，以致诸侯离心，却来怪罪我们戎人！我们戎人的饮食衣服，同华夏不一样，礼物不相往来，言语不通，能做什么坏事呢？不参加会盟，也不会有什么失意。」于是赋《青蝇》这首诗后退下。\n范宣子向他道歉，让他参加会盟的事务，以成全和乐平易的君子之风。"],
    [88, "guwen-gwj-25", "public-domain", "晋侯问叔向之罪于乐王鲋对曰「不弃其亲其有焉」于是祁奚老矣闻之乘驲而见宣子曰「诗曰『惠我无疆子孙保之』书曰『圣有谟勋明征定保』夫谋而鲜过惠训不倦者叔向有焉社稷之固也犹将十世宥之以劝能者今壹不免其身以弃社稷不亦惑乎鲧殛而禹兴伊尹放大甲而相之卒无怨色管蔡为戮周公右王若之何其以虎也弃社稷子为善谁敢不勉多杀何为」宣子说与之乘以言诸公而免之不见叔向而归叔向亦不告免焉而朝", "晋平公向乐王鲋询问叔向的罪状。乐王鲋答道：「他不会抛弃自己的亲人，大概有牵连吧。」这时祁奚已经告老，听说了这件事，就乘着驿车来见范宣子，说：「《诗经》说：『赐给我无穷的恩惠，子孙要保住它。』《尚书》说：『圣人有谋略功勋，应当明察并加以保护。』谋划而少有差错、施惠教诲而不厌倦，叔向具备这些，是国家的柱石，即使十代之后也应赦免他的后代，用来勉励有才能的人。如今一次不免他的罪，就抛弃了国家的柱石，不是太糊涂了吗？鲧被杀而禹兴起；伊尹放逐太甲又辅佐他，太甲始终没有怨恨之色；管叔、蔡叔被杀，周公仍辅佐成王。怎么能因为羊舌虎就抛弃国家柱石呢？您行善，谁敢不努力？多杀人做什么？」\n范宣子高兴了，同他同车，向平公进言而赦免了叔向。祁奚没有见叔向就回去了，叔向也没有去向祁奚道谢就上朝了。"],
    [89, "guwen-gwj-26", "public-domain", "范宣子为政诸侯之币重郑人病之二月郑伯如晋子产寓书于子西以告宣子曰「子为晋国四邻诸侯不闻令德而闻重币侨也惑之侨闻君子长国家者非无贿之患而无令名之难夫诸侯之贿聚于公室则诸侯贰若吾子赖之则晋国贰诸侯贰则晋国坏晋国贰则子之家坏何没没也将焉用贿」「夫令名德之舆也德国家之基也有基无坏无亦是务乎有德则乐乐则能久诗云『乐只君子邦家之基』有令德也夫『上帝临女无贰尔心』有令名也夫恕思以明德则令名载而行之是以远至迩安毋宁使人谓子『子实生我』而谓『子浚我以生』乎象有齿以焚其身贿也」宣子说乃轻币", "范宣子执政，诸侯朝聘的贡品很重。郑国人为此苦恼。二月，郑简公去晋国。子产托子西带信给范宣子，说：「您治理晋国，四邻诸侯没有听到您的美德，却听到贡品很重，我对此感到迷惑。我听说君子治理国家的，不担忧没有财物，而担忧没有好名声。诸侯的财物聚集在公室，诸侯就会离心。如果您据为己有，晋国就会离心。诸侯离心，晋国就会败坏；晋国离心，您的家族就会败坏。为什么这样糊涂呢！要财物做什么？\n「好名声是装载德行的车子；德行是国家的根基。有根基才不会败坏，不应当致力于这个吗？有德行就快乐，快乐就能长久。《诗经》说：『快乐的君子，是国家的根基。』这是说他有美德啊！又说：『上帝看着你，不要有二心。』这是说他有好名声啊！用推己及人的心去彰明德行，好名声就会载着德行传播，因此远方的人来归附，近处的人安居。何不如让人说『是您养育了我』，而不是说『您榨取我来养活自己』呢？大象因为牙齿而毁掉自身，就是因为象牙是财宝啊。」\n范宣子高兴了，于是减轻了贡品。"],
    [90, "guwen-gwj-27", "public-domain", "崔武子见棠姜而美之遂取之庄公通焉崔子弑之晏子立于崔氏之门外其人曰「死乎」曰「独吾君也乎哉吾死也」曰「行乎」曰「吾罪也乎哉吾亡也」曰「归乎」曰「君死安归君民者岂以陵民社稷是主臣君者岂为其口实社稷是养故君为社稷死则死之为社稷亡则亡之若为己死而为己亡非其私昵谁敢任之且人有君而弑之吾焉得死之而焉得亡之将庸何归」门启而入枕尸股而哭兴三踊而出人谓崔子「必杀之」崔子曰「民之望也舍之得民」", "崔武子见到棠姜觉得她美丽，就娶了她。齐庄公同棠姜私通。崔武子就杀了庄公。\n晏子站在崔氏门外，随从说：「为他殉死吗？」晏子说：「难道只是我一个人的国君吗，我为什么要死？」随从说：「逃走吗？」晏子说：「是我的罪过吗，我为什么要逃？」随从说：「回去吗？」晏子说：「国君死了，回到哪里去呢？做百姓君主的人，难道是用来欺凌百姓的吗？是要主持国家的。做国君臣子的人，难道是为了自己的俸禄吗？是要养护国家的。所以国君为国家而死，就为他而死；为国家而逃亡，就为他而逃亡。如果为自己的私事而死、为自己的私事而亡，不是他私下宠爱的人，谁敢承担这样的责任？况且别人有国君却把他杀了，我怎么能为他而死？又怎么能为他而逃？将回到哪里去呢？」\n崔氏的大门打开，晏子进去，把头枕在尸体的大腿上痛哭。然后站起来，顿足三次后走出去。有人对崔武子说：「一定要杀掉他！」崔武子说：「他是百姓所仰望的人，放了他能得到民心。」"],
    [91, "guwen-gwj-28", "public-domain", "吴公子札来聘请观于周乐使工为之歌周南召南曰「美哉始基之矣犹未也然勤而不怨矣」为之歌邶鄘卫曰「美哉渊乎忧而不困者也吾闻卫康叔武公之德如是是其卫风乎」为之歌王曰「美哉思而不惧其周之东乎」为之歌郑曰「美哉其细已甚民弗堪也是其先亡乎」为之歌齐曰「美哉泱泱乎大风也哉表东海者其大公乎国未可量也」为之歌豳曰「美哉荡乎乐而不淫其周公之东乎」为之歌秦曰「此之谓夏声夫能夏则大大之至也其周之旧乎」为之歌魏曰「美哉沨沨乎大而婉险而易行以德辅此则明主也」为之歌唐曰「思深哉其有陶唐氏之遗民乎不然何忧之远也非令德之后谁能若是」为之歌陈曰「国无主其能久乎」自郐以下无讥焉为之歌小雅曰「美哉思而不贰怨而不言其周德之衰乎犹有先王之遗民焉」为之歌大雅曰「广哉熙熙乎曲而有直体其文王之德乎」为之歌颂曰「至矣哉直而不倨曲而不屈迩而不逼远而不携迁而不淫复而不厌哀而不愁乐而不荒用而不匮广而不宣施而不费取而不贪处而不底行而不流五声和八风平节有度守有序盛德之所同也」见舞象箾南籥者曰「美哉犹有憾」见舞大武者曰「美哉周之盛也其若此乎」见舞韶濩者曰「圣人之弘也而犹有惭德圣人之难也」见舞大夏者曰「美哉勤而不德非禹其谁能修之」见舞韶箾者曰「德至矣哉大矣如天之无不帱也如地之无不载也虽甚盛德其蔑以加于此矣观止矣若有他乐吾不敢请已」", "吴国公子季札来鲁国聘问，请求观赏周朝的乐舞。\n鲁国派乐工为他歌唱《周南》《召南》，季札说：「美啊！王业的根基已经开始奠定了，但还没有完成，不过百姓勤劳而不怨恨。」\n为他歌唱《邶风》《鄘风》《卫风》，季札说：「美啊，深远啊！忧愁而不困窘。我听说卫康叔、武公的德行就是这样，这大概是《卫风》吧？」\n为他歌唱《王风》，季札说：「美啊！思虑而不畏惧，大概是周室东迁之后的乐歌吧？」\n为他歌唱《郑风》，季札说：「美啊！但它的音节过于细碎，百姓受不了。这大概是它先亡国的征兆吧？」\n为他歌唱《齐风》，季札说：「美啊，宏大啊！真是大国的风范啊！为东海一带表率的，大概就是太公吧？国家的前途不可限量。」\n为他歌唱《豳风》，季札说：「美啊，坦荡啊！快乐而不过分，大概是周公东征时的乐歌吧？」\n为他歌唱《秦风》，季札说：「这就叫做夏声。能保有华夏的气象就会强大，强大到极点，大概是周朝旧地的乐歌吧？」\n为他歌唱《魏风》，季札说：「美啊，婉转悠扬！宏大而婉转，险急而易于推行，如果用德行来辅助，就是明主了。」\n为他歌唱《唐风》，季札说：「思虑深远啊！大概有陶唐氏的遗民吧？不然，为什么忧愁得这样深远呢？不是美德的后代，谁能像这样？」\n为他歌唱《陈风》，季札说：「国家没有君主，怎么能长久呢？」从《郐风》以下就没有评论了。\n为他歌唱《小雅》，季札说：「美啊！思虑而没有二心，怨恨而不说出，大概是周德衰微时的乐歌吧？不过还有先王的遗民在。」\n为他歌唱《大雅》，季札说：「宽广啊，和乐啊！曲折而有正直的体度，大概是文王的德行吧？」\n为他歌唱《颂》，季札说：「好到极点了！正直而不倨傲，曲折而不屈服，亲近而不逼迫，疏远而不背离，迁徙而不邪乱，反复而不厌倦，哀伤而不忧愁，欢乐而不荒淫，使用而不匮乏，宽广而不张扬，施予而不耗费，索取而不贪婪，静止而不停滞，流动而不泛滥。五声和谐，八风平正，节拍有法度，顺序有次第，这是盛德之人所共有的。」\n看到跳《象箾》《南籥》的舞蹈，季札说：「美啊！不过还有遗憾。」看到跳《大武》的，说：「美啊！周朝的盛况，大概就像这样吧？」看到跳《韶濩》的，说：「圣人多么伟大啊！不过还有惭愧的德行，可见做圣人真难啊。」看到跳《大夏》的，说：「美啊！勤劳而不自以为有德，不是禹，谁能做到呢？」看到跳《韶箾》的，说：「德行达到极点了！伟大啊，像天一样无所不覆盖，像地一样无所不承载，即使有更高的盛德，也无法在此之上再增加了。观赏到此为止了！如果还有别的乐舞，我也不敢再请求了。」"],
    [92, "guwen-gwj-29", "public-domain", "公薨之月子产相郑伯以如晋晋侯以我丧故未之见也子产使尽坏其馆之垣而纳车马焉士文伯让之曰「敝邑以政刑之不修寇盗充斥无若诸侯之属辱在寡君者何是以令吏人完客所馆高其闬闳厚其墙垣以无忧客使今吾子坏之虽从者能戒其若异客何以敝邑之为盟主缮完葺墙以待宾客若皆毁之其何以共命寡君使匄请命」对曰「以敝邑褊小介于大国诛求无时是以不敢宁居悉索敝赋以来会时事逢执事之不闲而未得见又不获闻命未知见时不敢输币亦不敢暴露其输之则君之府实也非荐陈之不敢输也其暴露之则恐燥湿之不时而朽蠹以重敝邑之罪侨闻文公之为盟主也宫室卑庳无观台榭以崇大诸侯之馆馆如公寝库厩缮修司空以时平易道路圬人以时塓馆宫室诸侯宾至甸设庭燎仆人巡宫车马有所宾从有代巾车脂辖隶人牧圉各瞻其事百官之属各展其物公不留宾而亦无废事忧乐同之事则巡之教其不知而恤其不足宾至如归无宁灾患不畏寇盗而亦不患燥湿今铜鞮之宫数里而诸侯舍于隶人门不容车而不可逾越盗贼公行而天疠不戒宾见无时命不可知若又勿坏是无所藏币以重罪也敢请执事将何命之有丧亦犹敝邑之有丧也若能荐陈则修垣而入是君之惠也敢不荐陈」文伯复命赵文子曰「信我实不德而以隶人之垣以赢诸侯是吾罪也」使士文伯谢不敏焉晋侯见郑伯有加礼厚其宴好而归之乃筑诸侯之馆叔向曰「辞之不可以已也如是夫子产有辞诸侯赖之若之何其释辞也诗曰『辞之辑矣民之协矣辞之怿矣民之莫矣』其知之矣」", "鲁襄公去世那一个月，子产辅佐郑简公到晋国去，晋平公因为鲁国有丧事，没有接见他们。子产派人把招待宾客的馆舍围墙全部拆毁，把车马放进去。\n士文伯责备他说：「敝国因为政事刑罚没有修明，盗贼充斥，无法安置屈尊来见我们国君的诸侯属官，所以命令官吏修缮宾客住的馆舍，加高大门，加厚围墙，使宾客使者没有忧虑。如今您把它拆了，虽然您的随从能够戒备，别的宾客怎么办？敝国作为盟主，修缮围墙来接待宾客。如果都拆毁，怎么供应宾客的需求？我们国君派我来请教。」\n子产答道：「因为敝国狭小，处在大国之间，大国随时索取，因此不敢安居，搜罗敝国全部兵赋，前来朝会。正遇上执事不得空闲，未能见到；又没有听到命令，不知道什么时候能见。不敢献上礼物，也不敢让它暴露在外。如果献上，就是国君府库里的东西，不经过陈列的仪式，不敢献上。如果让它暴露在外，又怕燥湿不时而腐朽虫蛀，加重敝国的罪过。我听说文公做盟主的时候，宫室低矮狭小，没有观台台榭，而把诸侯的馆舍修得高大。馆舍像国君的寝宫，库房马厩修缮完好，司空按时修平道路，泥瓦匠按时粉刷馆舍宫室。诸侯宾客到来，甸人设置庭中的火把，仆人巡守馆舍，车马有停放的地方，宾客的随从有人替代，巾车给车轴加油，隶人、牧人、圉人各自照管自己的事。百官的属员各人陈列自己的物品。文公不滞留宾客，也不荒废事务。忧乐与宾客相同，有事就去巡查，教导他们不知道的，体恤他们不足的。宾客到来像回到家里，哪里还有灾患？不怕盗贼，也不怕燥湿。如今铜鞮的宫室绵延数里，而诸侯住在隶人的房子里，大门容不下车，又不能翻越。盗贼公然横行，而天灾疫病不加防备。宾客进见没有一定的时候，命令也不知道何时下达。如果再不高好招待，就没有地方存放礼物，以致加重罪过。谨请执事指教：将命令我们怎么做？鲁国有丧事，也如同敝国有丧事一样。如果能够陈列献上，我们就修好围墙进去，这是国君的恩惠。怎敢不陈列献上？」\n士文伯回去复命。赵文子说：「说得对。我们实在没有德行，用隶人的围墙来接待诸侯，这是我们的罪过。」派士文伯去道歉，说自己不明事理。\n晋平公接见郑简公，礼仪更加隆重，宴飨更加丰厚，然后送他回国。于是建筑接待诸侯的馆舍。\n叔向说：「辞令不可以废弃，就是这样啊！子产善于辞令，诸侯依靠他，怎么能废弃辞令呢？《诗经》说：『辞令和睦，百姓就协和；辞令喜悦，百姓就安定。』他懂得这个道理了。」"],
    [93, "guwen-gwj-30", "public-domain", "子皮欲使尹何为邑子产曰「少未知可否」子皮曰「愿吾爱之不吾叛也使夫往而学焉夫亦愈知治矣」子产曰「不可人之爱人求利之也今吾子爱人则以政犹未能操刀而使割也其伤实多子之爱人伤之而已其谁敢求爱于子子于郑国栋也栋折榱崩侨将厌焉敢不尽言子有美锦不使人学制焉大官大邑身之所庇也而使学者制焉其为美锦不亦多乎侨闻学而后入政未闻以政学者也若果行此必有所害譬如田猎射御贯则能获禽若未尝登车射御则败绩厌覆是惧何暇思获」子皮曰「善哉虎不敏吾闻君子务知大者远者小人务知小者近者我小人也衣服附在吾身我知而慎之大官大邑所以庇身也我远而慢之微子之言吾不知也他日我曰『子为郑国我为吾家以庇焉其可也』今而后知不足自今请虽吾家听子而行」子产曰「人心之不同如其面焉吾岂敢谓子面如吾面乎抑心所谓危亦以告也」子皮以为忠故委政焉子产是以能为郑国", "子皮想让尹何治理封邑。子产说：「他太年轻，不知道行不行。」子皮说：「他为人谨慎，我喜欢他，他不会背叛我。让他去那里学习，他也就会更懂得治理了。」子产说：「不行。人爱护别人，总是谋求对他有利。如今您爱护别人却把政事交给他，好比还不会拿刀就让他去割东西，那伤害一定很多。您爱护别人，却只是伤害他罢了，谁还敢向您求取爱护？您对于郑国，是栋梁。栋梁折断椽子崩塌，我也会被压在下面，怎敢不把话说完？您有美丽的锦缎，不会让人拿它去学裁剪。大官、大邑，是自身所依托的，却让学习的人去治理。它比起美丽的锦缎，不是重要得多吗？我听说先学习然后从政，没有听说拿政事来学习的。如果真的这样做，一定会有危害。好比打猎，射箭驾车熟练了，才能猎获禽兽；如果从来没有登上车射过箭、驾过车，就只担心翻车被压，哪里还有心思去想猎获？」\n子皮说：「说得好啊！我确实不聪明。我听说君子致力于懂得大的、远的事，小人致力于懂得小的、近的事。我就是小人。衣服穿在我身上，我知道爱惜它；大官、大邑是用来庇护自身的，我却疏远而轻慢它。没有您这番话，我还不知道。从前我说：『您治理郑国，我治理我的家族，用来庇护自身，大概可以了。』从今以后才知道这不够。从今天起我请求，即使是我的家族，也听您的话去做。」\n子产说：「人心各不相同，就像人的面孔一样。我怎敢说您的面孔和我的面孔一样呢？不过心里觉得危险的事，也就告诉了您。」\n子皮认为子产忠诚，所以把政事托付给他。子产因此能够治理郑国。"],
    [94, "guwen-gwj-31", "public-domain", "郑徐吾犯之妹美公孙楚聘之矣公孙黑又使强委禽焉犯惧告子产子产曰「是国无政非子之患也唯所欲与」犯请于二子请使女择焉皆许之子晳盛饰入布币而出子南戎服入左右射超乘而出女自房观之曰「子晳信美矣抑子南夫也夫夫妇妇所谓顺也」适子南氏子晳怒既而櫜甲以见子南欲杀之而取其妻子南知之执戈逐之及冲击之以戈子晳伤而归告大夫曰「我好见之不知其有异志也故伤」大夫皆谋之子产曰「直钧幼贱有罪罪在楚也」乃执子南而数之曰「国之大节有五女皆奸之畏君之威听其政尊其贵事其长养其亲五者所以为国也今君在国女用兵焉不畏威也奸国之纪不听政也子晳上大夫女嬖大夫而弗下之不尊贵也幼而不忌不事长也兵其从兄不养亲也君曰『余不女忍杀宥女以远』勉速行乎无重而罪」五月庚辰郑放游楚于吴", "郑国徐吾犯的妹妹很美丽，公孙楚已经下了聘礼，公孙黑又派人强行送去聘礼。徐吾犯害怕，告诉了子产。子产说：「这是国家没有政令，不是您的祸患。只凭她愿意嫁给谁。」徐吾犯向两个人请求，让女子自己选择。两人都答应了。子晳盛装而入，陈列聘礼后退出。子南穿着军服进来，左右射箭，然后跳跃登车而出。女子从房中观看，说：「子晳确实美丽，不过子南才是真正的丈夫。丈夫像丈夫、妻子像妻子，这才是顺理。」于是嫁给子南家。子晳发怒，随后把甲藏在衣中去见子南，想杀死他而夺取他的妻子。子南知道了，拿起戈追赶他，追到大路上，用戈击打他。子晳受伤回去，告诉大夫们说：「我好意去见他，不知道他有别的意图，所以受了伤。」\n大夫们都在商议这件事。子产说：「两人理由相当，年幼而地位低的有罪，罪在公孙楚。」于是拘捕子南并数落他说：「国家的大节有五条，你都违犯了。畏惧国君的威势，听从他的政令，尊敬地位高的，事奉年长的，供养亲属，这五条是治理国家的根本。如今国君在国中，你动用兵器，是不畏威势；违犯国家的纲纪，是不听政令；子晳是上大夫，你是宠幸的大夫，却不居于他之下，是不尊敬地位高的；年幼而不忌惮，是不事奉年长的；用兵器对付你的堂兄，是不供养亲属。国君说：『我不忍心杀你，赦免你到远方去。』努力吧，赶快走，不要加重你的罪过！」\n五月庚辰日，郑国把游楚放逐到吴国。"],
    [95, "guwen-gwj-32", "public-domain", "楚子狩于州来次于颍尾使荡侯潘子司马督嚣尹午陵尹喜帅师围徐以惧吴楚子次于乾溪以为之援雨雪王皮冠秦复陶翠被豹舄执鞭以出仆析父从右尹子革夕王见之去冠被舍鞭与之语曰「昔我先王熊绎与吕伋王孙牟燮父禽父并事康王四国皆有分我独无有今吾使人于周求鼎以为分王其与我乎」对曰「与君王哉昔我先王熊绎辟在荆山筚路蓝缕以处草莽跋涉山林以事天子唯是桃弧棘矢以共御王事齐王舅也晋及鲁卫王母弟也楚是以无分而彼皆有今周与四国服事君王将唯命是从岂其爱鼎」王曰「昔我皇祖伯父昆吾旧许是宅今郑人贪赖其田而不我与我若求之其与我乎」对曰「与君王哉周不爱鼎郑敢爱田」王曰「昔诸侯远我而畏晋今我大城陈蔡不羹赋皆千乘子与有劳焉诸侯其畏我乎」对曰「畏君王哉是四国者专足畏也又加之以楚敢不畏君王哉」工尹路请曰「君王命剥圭以为鏚柲敢请命」王入视之析父谓子革「吾子楚国之望也今与王言如响国其若之何」子革曰「摩厉以须王出吾刃将斩矣」王出复语左史倚相趋过王曰「是良史也子善视之是能读三坟五典八索九丘」对曰「臣尝问焉昔穆王欲肆其心周行天下将皆必有车辙马迹焉祭公谋父作祈招之诗以止王心是以获没于祗宫臣问其诗而不知也若问远焉其焉能知之」王曰「子能乎」对曰「能其诗曰『祈招之愔愔式昭德音思我王度式如玉式如金形民之力而无醉饱之心』」王揖而入馈不食寝不寐数日不能自克以及于难仲尼曰「古也有志『克己复礼仁也』信善哉楚灵王若能如是岂其辱于乾溪」", "楚灵王在州来打猎，驻扎在颍尾，派荡侯、潘子、司马督、嚣尹午、陵尹喜率领军队围攻徐国来威慑吴国。楚灵王驻扎在乾溪，作为他们的后援。下雪了，灵王戴着皮帽，穿着秦国进贡的复陶羽衣，披着翠羽披风，穿着豹皮鞋，拿着鞭子出来。仆析父跟随着。右尹子革晚上来进见，灵王见他，摘下帽子、脱下披风、放下鞭子，同他谈话，说：「从前我们的先王熊绎，同吕伋、王孙牟、燮父、禽父一起事奉康王，四国都有分赐的宝器，唯独我们没有。如今我派人到周朝去，请求把鼎赐给我作为分器，周王会给我吗？」子革答道：「会给君王的！从前我们先王熊绎，僻处在荆山，驾着柴车、穿着破衣，住在草莽之中。跋山涉水，来事奉天子。只是用桃木弓、棘木箭，来供给王室使用。齐国是周王的舅家；晋国和鲁国、卫国是周王同母兄弟的国家。楚国因此没有分器，而他们都有。如今周朝和四国都服事君王，将会唯命是从，怎么会吝惜鼎呢？」灵王说：「从前我皇祖伯父昆吾，住在旧许之地。如今郑国人贪图那里的田地，不肯给我。我如果去索求，他们会给我吗？」子革答道：「会给君王的！周朝都不吝惜鼎，郑国怎敢吝惜田地？」灵王说：「从前诸侯疏远我而畏惧晋国，如今我大规模修筑陈、蔡、不羹的城墙，兵赋都有一千乘，你也有功劳。诸侯会畏惧我吗？」子革答道：「会畏惧君王的！这四个地方，就足以让人畏惧了，再加上楚国，怎敢不畏惧君王呢？」\n工尹路请示说：「君王命令剖开圭玉来做斧柄的装饰，谨请指示。」灵王进去看。析父对子革说：「您是楚国有名望的人！如今同君王说话像回声一样随声附和，国家怎么办？」子革说：「磨快了刀等着，君王出来，我的刀刃就要砍下去了。」\n灵王出来，又谈起来。左史倚相快步走过。灵王说：「这是个好史官，你好好看待他。他能读《三坟》《五典》《八索》《九丘》。」子革答道：「我曾经问过他。从前周穆王想放纵自己的心意，周游天下，要让各处都留下他的车辙马迹。祭公谋父作了《祈招》这首诗，来阻止穆王的心意，因此穆王得以在祗宫善终。我问他这首诗，他不知道。如果问更远的事，他怎么能知道呢？」灵王说：「你能知道吗？」子革答道：「能。那诗说：『祈招安和，用来昭明德音。思念我们君王的风度，像玉一样温润，像金一样坚贞。要度量百姓的力量，而不要有醉饱之心。』」灵王拱手作揖而进去，送上饭不吃，躺下睡不着，好几天不能克制自己，终于遭了祸难。\n孔子说：「古时有记载：『克制自己，使言行合于礼，就是仁。』确实说得好啊！楚灵王如果能够这样，怎么会在乾溪受辱呢？」"],
    [96, "guwen-gwj-33", "public-domain", "郑子产有疾谓子大叔曰「我死子必为政唯有德者能以宽服民其次莫如猛夫火烈民望而畏之故鲜死焉水懦弱民狎而玩之则多死焉故宽难」疾数月而卒大叔为政不忍猛而宽郑国多盗取人于萑苻之泽大叔悔之曰「吾早从夫子不及此」兴徒兵以攻萑苻之盗尽杀之盗少止仲尼曰「善哉政宽则民慢慢则纠之以猛猛则民残残则施之以宽宽以济猛猛以济宽政是以和诗曰『民亦劳止汔可小康惠此中国以绥四方』施之以宽也『毋从诡随以谨无良式遏寇虐惨不畏明』纠之以猛也『柔远能迩以定我王』平之以和也又曰『不竞不絿不刚不柔布政优优百禄是遒』和之至也」及子产卒仲尼闻之出涕曰「古之遗爱也」", "郑国的子产有病，对子大叔说：「我死后，你一定执政。只有有德行的人能够用宽和政策使百姓服从，其次没有比严厉更好的了。火性猛烈，百姓望着就害怕，所以很少有人被烧死；水性柔弱，百姓轻慢而玩弄它，就有很多人被淹死，所以施行宽政是难的。」病了几个月后去世。\n大叔执政，不忍心严厉而施行宽政。郑国盗贼很多，在萑苻的水泽里劫掠行人。大叔后悔了，说：「我如果早听从夫子的话，不会到这一步。」于是发动步兵去攻打萑苻的盗贼，全部杀掉，盗贼稍微止息。\n孔子说：「说得好啊！政事宽大百姓就轻慢，轻慢就用严厉来纠正。严厉百姓就受伤害，受伤害就施行宽大。用宽大调剂严厉，用严厉调剂宽大，政事因此和谐。《诗经》说：『百姓也很劳苦了，大概可以稍稍安康。施惠于这中原之地，来安定四方。』这是施行宽大。又说：『不要听信诡诈善变的人，以谨防不良之徒。遏止掠夺残暴，他们从来不怕光明。』这是用严厉来纠正。又说：『安抚远方，亲善近处，来安定我们的君王。』这是用和谐来平治。又说：『不争强不急躁，不刚强不柔弱，施政宽和，百种福禄就会聚集。』这是和谐的极致。」\n到子产去世，孔子听到消息，流着泪说：「他是古代遗留下来的仁爱之人啊。」"],
    [97, "guwen-gwj-34", "public-domain", "吴子使来儆师伐齐秋及齐平九月臧宾如如齐莅盟齐闾丘明来莅盟且逆季姬以归嬖冬十二月齐侯鲁侯盟于黄齐侯使请战曰「子周之胤也将以为已荣乎」答曰「君之惠也寡人愿焉若惠顾前好徼福于周公太公使两国之民相就也寡人之愿也若君不施大惠寡人不佞其不能以诸侯退矣」吴子使来儆师伐齐", "吴王派人来通告鲁国出兵一起攻打齐国。秋天，鲁国与齐国讲和。九月，臧宾如到齐国参加盟会。齐国的闾丘明来鲁国参加盟会，并且迎接季姬回国，季姬受到宠爱。\n冬天十二月，齐侯、鲁侯在黄地结盟。齐侯派人请求交战，说：「您是周室的后代，将要以此自认为荣耀吗？」鲁国答道：「这是您的恩惠，我很愿意。如果肯施惠顾念从前的友好，向周公、太公求福，使两国的百姓互相亲近，那就是我的愿望。如果您不施大恩，我不才，就无法带着诸侯退兵了。」\n吴王派人来通告鲁国出兵一起攻打齐国。"],
    [98, "guwen-gwj-62", "public-domain", "太史公曰学者多称五帝尚矣然尚书独载尧以来而百家言黄帝其文不雅驯荐绅先生难言之孔子所传宰予问五帝德及帝系姓儒者或不传余尝西至空桐北过涿鹿东渐于海南浮江淮矣至长老皆各往往称黄帝尧舜之处风教固殊焉总之不离古文者近是予观春秋国语其发明五帝德帝系姓章矣顾弟弗深考其所表见皆不虚书缺有间矣其轶乃时时见于他说非好学深思心知其意固难为浅见寡闻道也余并论次择其言尤雅者故著为本纪书首", "太史公说：学者多称说五帝，已经很久远了。但《尚书》只记载尧以来，而诸子百家讲黄帝，文字不典雅不顺畅，士大夫先生们难以说清。孔子所传的宰予问《五帝德》和《帝系姓》，儒者有的不传习。我曾经西到空桐，北过涿鹿，东临大海，南渡江淮，所到之处，年长的人往往各自称说黄帝、尧、舜的地方，风俗教化本来就不同。总之，不背离古文记载的比较接近事实。我看《春秋》《国语》，它们阐发《五帝德》《帝系姓》很明显，只是没有深入考察，它们所表述的都不是虚假的。《尚书》残缺有缺漏，它散失的内容常常见于其他记载。不是好学深思、心里明白其中意思的人，本来就难以对见识浅陋、见闻不广的人说明。我一并论列编次，选择其中言辞特别典雅的，所以写成《五帝本纪》放在全书之首。"],
    [99, "guwen-gwj-63", "public-domain", "太史公曰吾闻之周生曰「舜目盖重瞳子」又闻项羽亦重瞳子羽岂其苗裔邪何兴之暴也夫秦失其政陈涉首难豪杰蜂起相与并争不可胜数然羽非有尺寸乘势起陇亩之中三年遂将五诸侯灭秦分裂天下而封王侯政由羽出号为「霸王」位虽不终近古以来未尝有也及羽背关怀楚放逐义帝而自立怨王侯叛己难矣自矜功伐奋其私智而不师古谓霸王之业欲以力征经营天下五年卒亡其国身死东城尚不觉寤而不自责过矣乃引「天亡我非用兵之罪也」岂不谬哉", "太史公说：我听周生说「舜的眼睛大概是双瞳孔」，又听说项羽也是双瞳孔。项羽难道是舜的后代吗？为什么兴起得这样突然！秦朝政治失当，陈涉首先发难，豪杰蜂拥而起，互相争雄，数不胜数。然而项羽没有尺寸的根基，乘势从田野中兴起，三年之内，就率领五国诸侯灭掉秦朝，分裂天下，封王封侯，政令由项羽发出，号称「霸王」，地位虽然没有保持到底，但近古以来还不曾有过。等到项羽背弃关中、怀念楚地，放逐义帝而自立，却埋怨诸侯背叛自己，这就难了。他自我夸耀功劳，施展个人的聪明而不效法古人，认为霸王的功业，只要用武力征伐就能经营天下，五年终于亡国，身死东城，还不觉悟、不责备自己，这就错了。竟然说「是上天要灭亡我，不是我用兵的罪过」，难道不是荒谬吗！"],
    [100, "guwen-gwj-64", "public-domain", "太史公读秦楚之际曰初作难发于陈涉虐戾灭秦自项氏拨乱诛暴平定海内卒践帝祚成于汉家五年之间号令三嬗自生民以来未有受命若斯之亟也昔虞夏之兴积善累功数十年德洽百姓摄行政事考之于天然后在位汤武之王乃由契后稷修仁行义十余世不期而会孟津八百诸侯犹以为未可其后乃放弑秦起襄公章于文缪献孝之后稍以蚕食六国百有余载至始皇乃能并冠带之伦以德若彼用力如此盖一统若斯之难也秦既称帝患兵革不休以有诸侯也于是无尺土之封堕坏名城销锋镝锄豪桀维万世之安然王迹之兴起于闾巷合从讨伐轶于三代乡秦之禁适足以资贤者为驱除难耳故愤发其所为天下雄安在无土不王此乃传之所谓大圣乎岂非天哉岂非天哉非大圣孰能当此受命而帝者乎", "太史公读秦楚之际的历史，说：最初发难，起于陈涉；暴虐地灭掉秦朝，出自项氏；拨乱诛暴、平定海内，终于登上天子之位，成于汉家。五年之间，号令三次转移，自从有百姓以来，没有承受天命像这样急促的。\n从前虞、夏的兴起，积累善行功业几十年，德行润泽百姓，代理政事，向上天验证，然后才即位。汤、武称王，是由契、后稷修仁行义十几代，不约而同到孟津会合的诸侯有八百个，还认为不可以，其后才放逐、诛杀。秦从襄公兴起，在文公、穆公时彰明，献公、孝公之后，逐渐蚕食六国，一百多年，到始皇才能兼并冠带之国的华夏。以德行那样积累，用武力这样经营，统一竟是如此艰难。\n秦既已称帝，忧患战事不休，是因为有诸侯，于是没有一尺土地的封赐，毁坏名城的城墙，销毁兵器，铲除豪杰，想维持万世的安定。然而王业的兴起，起于闾巷，合纵讨伐，超过三代，从前秦朝的禁令，恰恰足以帮助贤者为天下驱除祸难罢了。所以愤发而成为天下的雄主，哪里在于没有封土就不能称王呢。这就是古书所说的「大圣」吧？难道不是天意吗，难道不是天意吗！不是大圣谁能担当这样的受命而称帝呢？"],
    [101, "guwen-gwj-65", "public-domain", "太史公曰古者人臣功有五品以德立宗庙定社稷曰勋以言曰劳用力曰功明其等曰伐积日曰阅封爵之誓曰「使河如带泰山若厉国以永宁爰及苗裔」始未尝不欲固其根本而枝叶稍陵夷衰微也余读高祖侯功臣察其首封所以失之者曰异哉所闻书曰「协和万国」迁于夏商或数千岁盖周封八百幽厉之后见于春秋尚书有唐虞之侯伯历三代千有余载自全以蕃卫天子岂非笃于仁义奉上法哉汉兴功臣受封者百有余人天下初定故大城名都散亡户口可得而数者十二三是以大侯不过万家小者五六百户后数世民咸归乡里户益息萧曹绛灌之属或至四万小侯自倍富厚如之子孙骄溢忘其先淫嬖至太初百年之间见侯五余皆坐法陨命亡国耗矣罔亦少密焉然皆身无兢兢于当世之禁云居今之世志古之道所以自镜也未必尽同帝王者各殊礼而异务要以成功为统纪岂可绲乎观所以得尊宠及所以废辱亦当世得失之林也何必旧闻于是谨其终始表见其文颇有所不尽本末著其明疑者阙之后有君子欲推而列之得以览焉", "太史公说：古时人臣的功勋有五个品级：用德行建立宗庙、安定社稷的叫勋，用言辞立功的叫劳，用力气立功的叫功，明确等级的叫伐，积累时日的叫阅。封爵的誓词说：「即使黄河细得像衣带，泰山小得像磨刀石，封国也永远安宁，延及子孙后代。」起初未尝不想巩固根本，而枝叶却逐渐衰败了。\n我读高祖所封功臣的记载，考察他们最初受封、后来失去封国的原因，说：同我所听说的多么不同啊！《尚书》说「协和万国」，延续到夏、商，有的几千年。周朝封了八百国，幽王、厉王之后，还见于《春秋》。《尚书》有唐、虞的侯伯，经历三代一千多年，仍能保全自己以护卫天子，难道不是笃行仁义、奉行天子法度的缘故吗？汉朝兴起，功臣受封的一百多人。天下刚刚平定，大城名都的人口散亡，户口能统计的只有十分之二三，所以大侯不过万户，小的五六百户。过了几代，百姓都回到乡里，户口更加繁息，萧何、曹参、绛侯、灌婴这些人有的封户到四万，小侯也成倍增长，富厚程度也相应增长。子孙骄纵过度，忘记祖先，淫逸宠嬖。到太初年间一百年之间，保持侯爵的只有五个，其余都因犯法丧命亡国，衰败了。法网也稍微严密了些，但都是自身没有小心谨慎对待当世的禁令。\n处在今天，追想古代的道理，是用来照见自己，未必完全相同。帝王各自礼制不同、事务相异，总要以成功为纲纪，怎么可以混同呢？观察他们所以得到尊宠以及所以被废弃屈辱的原因，也是当世得失的丛集，何必一定要依据旧闻？于是我谨慎地记录他们的始末，列表呈现他们的文字，也有许多不能详尽的本来，写明明确的，可疑的就空缺。后世若有君子，想推求而列举，可以借此阅览。"],
    [102, "guwen-gwj-66", "public-domain", "太史公曰诗有之「高山仰止景行行止」虽不能至然心乡往之余读孔氏书想见其为人适鲁观仲尼庙堂车服礼器诸生以时习礼其家余祗回留之不能去云天下君王至于贤人众矣当时则荣没则已焉孔子布衣传十余世学者宗之自天子王侯中国言六艺者折中于夫子可谓至圣矣", "太史公说：《诗经》里有这样的话：「高山仰望，大道行走。」虽然不能到达，但心里向往它。我读孔子的书，想见他的为人。到鲁国，观看仲尼的庙堂、车服、礼器，儒生们按时在他家里演习礼仪，我恭敬地徘徊留连不忍离去。天下的君王乃至贤人很多，在世时荣耀，死后就算了。孔子是平民，传了十几代，学者都尊崇他。从天子王侯起，中国讲六艺的人都以夫子为准则，可以说是至圣了！"],
    [103, "guwen-gwj-67", "public-domain", "自古受命帝王及继体守文之君非独内德茂也盖亦有外戚之助焉夏之兴也以涂山而桀之放也用末喜殷之兴也以有娀而纣之杀也嬖妲己周之兴也以姜原及大任而幽王之禽也淫于褒姒故易基乾坤诗始关雎书美釐降春秋讥不亲迎夫妇之际人道之大伦也礼之用唯婚姻为兢兢夫乐调而四时和阴阳之变万物之统也可不慎与人能弘道无如命何甚哉妃匹之爱君不能得之于臣父不能得之于子况卑下乎既欢合矣或不能成子姓能成子姓矣或不能要其终岂非命也哉孔子罕称命盖难言之也非通幽明之变恶能识乎性命哉", "自古承受天命的帝王以及继承先业、恪守成法的君主，不只是内在德行美好，大概也有外戚的帮助。夏朝兴起靠涂山氏，而桀被放逐是因为末喜；殷朝兴起靠有娀氏，而纣被杀是因为宠爱妲己；周朝兴起靠姜原和大任，而幽王被擒是因为淫于褒姒。所以《周易》以《乾》《坤》为基，《诗经》以《关雎》开篇，《尚书》赞美尧把女儿嫁给舜，《春秋》讥刺不亲自迎亲。夫妇之间，是人道的重大伦常。礼的运用，唯有婚姻最为谨慎。音乐协调而四时和顺，阴阳的变化，是万物的统绪。可以不慎重吗？人能弘扬道，对命运却无可奈何。深啊，夫妇相爱，国君不能从臣下那里得到，父亲不能从儿子那里得到，何况地位卑下的人呢！已经欢爱结合了，有的不能生育子嗣；能生育子嗣了，有的不能保全到最后，难道不是命运吗？孔子很少谈命，大概是因为难以说清。不通晓幽明的变化，怎么能认识性命呢？"],
    [104, "guwen-gwj-68", "public-domain", "夫学者载籍极博犹考信于六艺诗书虽缺然虞夏之文可知也尧将逊位让于虞舜舜禹之间岳牧咸荐乃试之于位典职数十年功用既兴然后授政示天下重器王者大统传天下若斯之难也而说者曰尧让天下于许由许由不受耻之逃隐及夏之时有卞随务光者此何以称焉太史公曰余登箕山其上盖有许由冢云孔子序列古之仁圣贤人如吴太伯伯夷之伦详矣余以所闻由光义至高其文辞不少概见何哉孔子曰「伯夷叔齐不念旧恶怨是用希」「求仁得仁又何怨乎」余悲伯夷之意睹轶诗可异焉其传曰伯夷叔齐孤竹君之二子也父欲立叔齐及父卒叔齐让伯夷伯夷曰「父命也」遂逃去叔齐亦不肯立而逃之国人立其中子于是伯夷叔齐闻西伯昌善养老盍往归焉及至西伯卒武王载木主号为文王东伐纣伯夷叔齐叩马而谏曰「父死不葬爰及干戈可谓孝乎以臣弑君可谓仁乎」左右欲兵之太公曰「此义人也」扶而去之武王已平殷乱天下宗周而伯夷叔齐耻之义不食周粟隐于首阳山采薇而食之及饿且死作歌其辞曰「登彼西山兮采其薇矣以暴易暴兮不知其非矣神农虞夏忽焉没兮我安适归矣于嗟徂兮命之衰矣」遂饿死于首阳山由此观之怨邪非邪或曰「天道无亲常与善人」若伯夷叔齐可谓善人者非邪积仁洁行如此而饿死且七十子之徒仲尼独荐颜渊为好学然回也屡空糟糠不厌而卒蚤夭天之报施善人其何如哉盗蹠日杀不辜肝人之肉暴戾恣睢聚党数千人横行天下竟以寿终是遵何德哉此其尤大彰明较著者也若至近世操行不轨专犯忌讳而终身逸乐富厚累世不绝或择地而蹈之时然后出言行不由径非公正不发愤而遇祸灾者不可胜数也余甚惑焉傥所谓天道是邪非邪子曰「道不同不相为谋」亦各从其志也故曰「富贵如可求虽执鞭之士吾亦为之如不可求从吾所好」「岁寒然后知松柏之后凋」举世混浊清士乃见岂以其重若彼其轻若此哉「君子疾没世而名不称焉」贾子曰「贪夫徇财烈士徇名夸者死权众庶冯生」「同明相照同类相求」「云从龙风从虎圣人作而万物睹」伯夷叔齐虽贤得夫子而名益彰颜渊虽笃学附骥尾而行益显岩穴之士趋舍有时若此类名堙灭而不称悲夫闾巷之人欲砥行立名者非附青云之士恶能施于后世哉", "学者所见的书籍极为广博，还要从六艺中考核证实。《诗》《书》虽然残缺，但虞、夏的文字还是可以知道的。尧将退位，让位给虞舜，舜、禹之间，四方诸侯之长和州牧都推荐，于是让他在位上试用，任职几十年，功业已经建立，然后才授给政权。这是表示天下是重器、王者是大统，传天下是这样艰难。而游说的人说尧把天下让给许由，许由不接受，以之为耻而逃走隐居。到夏朝时，有卞随、务光这样的人。这又怎么称说呢？太史公说：我登上箕山，那上面据说有许由的坟墓。孔子依次叙述古代的仁圣贤人，如吴太伯、伯夷这一类很详细。我据所听到的，许由、务光的义行极高，但他们的文辞事迹却很少见到，为什么呢？\n孔子说：「伯夷、叔齐不记旧怨，因此怨恨很少。」「求仁而得仁，又有什么怨呢？」我悲伤伯夷的心意，看到逸诗又觉得奇怪。他的传记说：\n伯夷、叔齐是孤竹君的两个儿子。父亲想立叔齐，到父亲去世，叔齐让给伯夷。伯夷说：「这是父亲的命令。」于是逃走。叔齐也不肯即位而逃走。国人立了中间的儿子。于是伯夷、叔齐听说西伯昌善于奉养老人，何不去归附他。到了那里，西伯已经去世，武王载着木主，尊号为文王，向东讨伐纣。伯夷、叔齐拉住马缰劝谏说：「父亲死了不埋葬，就动起干戈，可说是孝吗？以臣子杀君主，可说是仁吗？」左右的人想对他们动武。太公说：「这是义人。」扶他们离开。武王平定殷朝的动乱后，天下都尊奉周朝，而伯夷、叔齐以此为耻，守义不吃周朝的粮食，隐居在首阳山，采薇菜吃。到饿得快死时，作了一首歌。歌词说：「登上那西山啊，采那里的薇菜。用暴虐代替暴虐啊，不知道那是错的。神农、虞、夏忽然而逝啊，我该归向哪里？唉，去吧，命运衰微了！」于是饿死在首阳山。\n由此看来，是有怨呢还是没有怨呢？\n有人说：「天道没有亲疏，常常帮助善人。」像伯夷、叔齐，可以说是善人呢，还是不是呢？这样积累仁德、清洁品行却饿死！而且七十个弟子中，仲尼独独称赞颜渊好学。但颜回常常穷困，连糟糠都吃不饱，终于早死。上天报答善人，又怎么样呢？盗跖天天杀害无辜，吃人的肝肉，残暴放纵，聚集党徒几千人在天下横行，竟然寿终，这是遵循什么德行呢？这些是尤其重大明显的例子。至于近世，行为不轨、专门触犯忌讳的人，却终身安逸快乐，富贵丰厚，几代不断。有的人选择地方才走，到时候才说话，不走小路，不是公正的事不发愤，却遭遇祸灾的，数不胜数。我很迷惑，倘若所谓的天道，是对呢还是不对呢？\n孔子说：「主张不同，不能互相谋划」，也就是各随其志。所以说：「富贵如果可求，即使是执鞭的差役，我也去做。如果不可求，就随我的爱好。」「到了严寒，才知道松柏最后凋零。」举世混浊，清白的士人才显现出来。难道因为把富贵看得那样重，把清名看得这样轻吗？\n「君子痛恨死后名声不被人称道。」贾谊说：「贪夫为财而死，烈士为名而死，夸耀的人为权而死，普通百姓只求活着。」「同类的东西互相映照，同类的东西互相寻求。」「云跟从龙，风跟从虎，圣人出现而万物显露。」伯夷、叔齐虽然贤能，得到夫子的称许而名声更加彰显；颜渊虽然好学，附在骥尾上而德行更加显著。隐居岩穴的士人，进退有时，像这一类名声埋没而不被称道的，可悲啊！闾巷中的人，想要砥砺品行、树立名声的，不依附青云之士，怎么能流传于后世呢！"],
    [105, "guwen-gwj-69", "public-domain", "管仲夷吾者颍上人也少时常与鲍叔牙游鲍叔知其贤管仲贫困常欺鲍叔鲍叔终善遇之不以为言已而鲍叔事齐公子小白管仲事公子纠及小白立为桓公公子纠死管仲囚焉鲍叔遂进管仲管仲既用任政于齐齐桓公以霸九合诸侯一匡天下管仲之谋也管仲曰「吾始困时尝与鲍叔贾分财利多自与鲍叔不以我为贪知我贫也吾尝为鲍叔谋事而更穷困鲍叔不以我为愚知时有利不利也吾尝三仕三见逐于君鲍叔不以我为不肖知我不遭时也吾尝三战三走鲍叔不以我为怯知我有老母也公子纠败召忽死之吾幽囚受辱鲍叔不以我为无耻知我不羞小节而耻功名不显于天下也生我者父母知我者鲍子也」鲍叔既进管仲以身下之子孙世禄于齐有封邑者十余世常为名大夫天下不多管仲之贤而多鲍叔能知人也管仲既任政相齐以区区之齐在海滨通货积财富国强兵与俗同好恶故其称曰「仓廪实而知礼节衣食足而知荣辱上服度则六亲固四维不张国乃灭亡下令如流水之原令顺民心」故论卑而易行俗之所欲因而予之俗之所否因而去之其为政也善因祸而为福转败而为功贵轻重慎权衡桓公实怒少姬南袭蔡管仲因而伐楚责包茅不入贡于周室桓公实北征山戎而管仲因而令燕修召公之政于柯之会桓公欲背曹沫之约管仲因而信之诸侯由是归齐故曰「知与之为取政之宝也」管仲富拟于公室有三归反坫齐人不以为侈管仲卒齐国遵其政常强于诸侯后百余年而有晏子焉晏平仲婴者莱之夷维人也事齐灵公庄公景公以节俭力行重于齐既相齐食不重肉妾不衣帛其在朝君语及之即危言语不及之即危行国有道即顺命无道即衡命以此三世显名于诸侯越石父贤在缧绁中晏子出遭之涂解左骖赎之载归弗谢入闺久之越石父请绝晏子戄然摄衣冠谢曰「婴虽不仁免子于厄何子求绝之速也」石父曰「不然吾闻君子诎于不知己而信于知己者方吾在缧绁中彼不知我也夫子既已感寤而赎我是知己知己而无礼固不如在缧绁之中」晏子于是延入为上客晏子为齐相出其御之妻从门间而窥其夫其夫为相御拥大盖策驷马意气扬扬甚自得也既而归其妻请去夫问其故妻曰「晏子长不满六尺身相齐国名显诸侯今者妾观其出志念深矣常有以自下者今子长八尺乃为人仆御然子之意自以为足妾是以求去也」其后夫自抑损晏子怪而问之御以实对晏子荐以为大夫太史公曰吾读管氏牧民山高乘马轻重九府及晏子春秋详哉其言之也既见其著书欲观其行事故次其传至其书世多有之是以不论论其轶事管仲世所谓贤臣然孔子小之岂以为周道衰微桓公既贤而不勉之至王乃称霸哉语曰「将顺其美匡救其恶故上下能相亲也」岂管仲之谓乎方晏子伏庄公尸哭之成礼然后去岂所谓「见义不为无勇」者邪至其谏说犯君之颜此所谓「进思尽忠退思补过」者哉假令晏子而在余虽为之执鞭所忻慕焉", "管仲名夷吾，是颍上人。年轻时常常和鲍叔牙交往，鲍叔牙知道他有才能。管仲贫困，常常欺骗鲍叔，鲍叔始终待他很好，不把这些说出来。后来鲍叔事奉齐公子小白，管仲事奉公子纠。到小白立为桓公，公子纠死了，管仲被囚禁。鲍叔于是推荐管仲。管仲被任用后，在齐国执政，齐桓公因此称霸，多次会合诸侯，一举匡正天下，都是管仲的谋略。\n管仲说：「我起初穷困时，曾和鲍叔经商，分财利时常多给自己，鲍叔不认为我贪心，知道我家贫。我曾为鲍叔谋事却使他更加困窘，鲍叔不认为我愚笨，知道时机有有利和不利。我曾三次做官三次被国君驱逐，鲍叔不认为我无能，知道我没遇上好时机。我曾三次作战三次逃走，鲍叔不认为我胆怯，知道我有老母。公子纠失败，召忽为他而死，我被囚禁受辱，鲍叔不认为我无耻，知道我不以小节为羞而以功名不显于天下为耻。生我的是父母，了解我的是鲍叔啊。」\n鲍叔推荐管仲之后，自己甘居他之下。子孙世代在齐国享受俸禄，有封邑的十几代，常常是著名的大夫。天下人不称赞管仲的贤能而称赞鲍叔能够了解人。\n管仲既已执政做齐相，凭着小小的齐国处在海滨，流通货物、积聚财富，富国强兵，与世俗同好恶。所以他说：「粮仓充实才知道礼节，衣食充足才知道荣辱，君上奉行法度则六亲稳固。礼义廉耻四维不伸张，国家就会灭亡。下达政令像流水的源头，使政令顺从民心。」所以他的议论浅近而容易施行。世俗所想要的，就顺着给予；世俗所反对的，就顺着除去。\n他处理政事，善于因祸为福，转败为功。重视事物的轻重，谨慎地权衡。桓公实际上是恼怒少姬，南下袭击蔡国，管仲就趁机攻打楚国，责备楚国不向周室进贡包茅。桓公实际上是北征山戎，管仲就趁机让燕国修明召公的政教。在柯地的会盟上，桓公想背弃曹沫的盟约，管仲就趁机使桓公守信，诸侯因此归附齐国。所以说：「知道给予就是取得，这是为政的宝贝。」\n管仲的富有比拟公室，有三归之台、反爵之坫，齐国人不认为他奢侈。管仲去世后，齐国遵循他的政令，常常比诸侯强大。一百多年后有晏子。\n晏平仲名婴，是莱地夷维人。他事奉齐灵公、庄公、景公，以节俭力行受到齐国人的敬重。做了齐相后，吃饭不重肉，妾不穿丝帛。他在朝廷上，国君说到他，就直言；没说及他，就正行。国家有道，就顺从命令；无道，就权衡命令。因此三代都显名于诸侯。\n越石父贤能，被囚禁在绳索中。晏子外出，在路上遇到他，解下左边的骖马赎了他，载他回家。晏子没有告辞，就进了内室。过了很久，越石父请求绝交。晏子惊愕，整理衣冠谢罪说：「我虽然不仁，但使您免于困厄，为什么您要这么快求绝交呢？」越石父说：「不是这样。我听说君子在不知己的人面前受屈，在知己的人面前得到伸展。当我在绳索中的时候，他们不了解我。您既然已经感悟而赎我，就是知己；对知己而无礼，倒不如仍在绳索之中。」晏子于是请他进来奉为上客。\n晏子做齐相，外出，他车夫的妻子从门缝里偷看她的丈夫。她的丈夫为相驾车，拥着大车盖，赶着四匹马，意气扬扬，非常得意。回来后，他的妻子请求离去。丈夫问她缘故。妻子说：「晏子身高不到六尺，身做齐相，名声显于诸侯。刚才我看他外出，志念深远，常常有自居人下的神气。如今你身高八尺，却做人家的仆从车夫，而你的心意却自以为满足，我因此请求离去。」此后她丈夫自我抑制。晏子觉得奇怪就问他，车夫如实回答。晏子推荐他做了大夫。\n太史公说：我读管氏的《牧民》《山高》《乘马》《轻重》《九府》，以及《晏子春秋》，它们说得多么详尽啊。既已看到他们著的书，想观察他们的行事，所以编次他们的传记。至于他们的书，世上多有流传，因此不再论说，只论他们的轶事。\n管仲是世人所称的贤臣，但孔子轻视他。难道是因为周道衰微，桓公既然贤明，管仲却不勉励他施行王道，而只是称霸吗？俗话说「顺应他的美德，匡救他的过错，所以上下能够互相亲近」。大概说的就是管仲吧？\n当晏子伏在庄公尸体上痛哭，完成礼仪然后离开，难道就是所谓的「见义不为是没有勇气」吗？至于他谏说，冒犯国君的脸色，这就是所谓「进朝想着尽忠，退朝想着补过」的人吧！假如晏子还在，我即使为他执鞭赶车，也是我所欣喜仰慕的。"],
    [106, "guwen-gwj-70", "school", "屈原者名平楚之同姓也为楚怀王左徒博闻强志明于治乱娴于辞令入则与王图议国事以出号令出则接遇宾客应对诸侯王甚任之上官大夫与之同列争宠而心害其能怀王使屈原造为宪令屈平属草稿未定上官大夫见而欲夺之屈平不与因谗之曰「王使屈平为令众莫不知每一令出平伐其功曰以为『非我莫能为』也」王怒而疏屈平屈平疾王听之不聪也谗谄之蔽明也邪曲之害公也方正之不容也故忧愁幽思而作离骚「离骚」者犹离忧也夫天者人之始也父母者人之本也人穷则反本故劳苦倦极未尝不呼天也疾痛惨怛未尝不呼父母也屈平正道直行竭忠尽智以事其君谗人间之可谓穷矣信而见疑忠而被谤能无怨乎屈平之作离骚盖自怨生也屈平既绌其后秦欲伐齐齐与楚从亲惠王患之乃令张仪佯去秦厚币委质事楚曰「秦甚憎齐齐与楚从亲楚诚能绝齐秦愿献商於之地六百里」楚怀王贪而信张仪遂绝齐使使如秦受地张仪诈之曰「仪与王约六里不闻六百里」楚使怒去归告怀王怀王怒大兴师伐秦秦发兵击之大破楚师于丹淅斩首八万虏楚将屈匄遂取楚之汉中地怀王乃悉发国中兵以深入击秦战于蓝田魏闻之袭楚至邓楚兵惧自秦归而齐竟怒不救楚楚大困明年秦割汉中地与楚以和楚王曰「不愿得地愿得张仪而甘心焉」张仪闻乃曰「以一仪而当汉中地臣请往如楚」如楚又因厚币用事者臣靳尚而设诡辩于怀王之宠姬郑袖怀王竟听郑袖复释去张仪是时屈平既疏不复在位使于齐顾反谏怀王曰「何不杀张仪」怀王悔追张仪不及其后诸侯共击楚大破之杀其将唐眜时秦昭王与楚婚欲与怀王会怀王欲行屈平曰「秦虎狼之国不可信不如毋行」怀王稚子子兰劝王行「奈何绝秦欢」怀王卒行入武关秦伏兵绝其后因留怀王以求割地怀王怒不听亡走赵赵不内复之秦竟死于秦而归葬长子顷襄王立以其弟子兰为令尹楚人既咎子兰以劝怀王入秦而不反也屈平既嫉之虽放流眷顾楚国系心怀王不忘欲反冀幸君之一悟俗之一改也其存君兴国而欲反覆之一篇之中三致志焉然终无可奈何故不可以反卒以此见怀王之终不悟也令尹子兰闻之大怒卒使上官大夫短屈原于顷襄王顷襄王怒而迁之屈原至于江滨被发行吟泽畔颜色憔悴形容枯槁渔父见而问之曰「子非三闾大夫欤何故而至此」屈原曰「举世混浊而我独清众人皆醉而我独醒是以见放」渔父曰「夫圣人者不凝滞于物而能与世推移举世混浊何不随其流而扬其波众人皆醉何不餔其糟而啜其醨何故怀瑾握瑜而自令见放为」屈原曰「吾闻之新沐者必弹冠新浴者必振衣人又谁能以身之察察受物之汶汶者乎宁赴常流而葬乎江鱼腹中耳又安能以皓皓之白而蒙世俗之温蠖乎」乃作怀沙之赋于是怀石遂自投汨罗以死屈原既死之后楚有宋玉唐勒景差之徒者皆好辞而以赋见称然皆祖屈原之从容辞令终莫敢直谏其后楚日以削数十年竟为秦所灭", "屈原，名平，是楚国王族的同姓。他做楚怀王的左徒。见闻广博，记忆力强，明白国家治乱的道理，熟悉外交辞令。对内与怀王商议国事，发布号令；对外接待宾客，应对诸侯。怀王很信任他。\n上官大夫与屈原同朝为官，想争得宠幸，心里嫉妒他的才能。怀王让屈原制定法令，屈原起草的稿子还没定稿。上官大夫看见了想夺取它，屈原不给，于是进谗言说：「大王让屈原制定法令，没有人不知道。每一条法令出台，屈原就夸耀自己的功劳，说『除了我没有人能做』。」怀王发怒，疏远了屈原。\n屈原痛心怀王听不进去忠言，谗谄之人蒙蔽了明智，邪恶之人损害了公正，端方正直的人不被容纳，所以忧愁深思而写下《离骚》。「离骚」就是遭遇忧患的意思。天是人的起源，父母是人的根本。人处境困窘就会追念根本，所以劳苦困倦到极点，没有不呼喊上天的；病痛忧伤，没有不呼喊父母的。屈原行为正直，竭尽忠诚和智慧来侍奉他的君主，谗人从中挑拨，可以说处境困窘了。诚信却被怀疑，忠贞却被诽谤，能没有怨愤吗？屈原写作《离骚》，大概是从怨愤中产生的。\n屈原被罢黜之后，秦国想要攻打齐国，齐国与楚国合纵相亲。秦惠王为此忧虑，就派张仪假装离开秦国，带着厚礼呈献信物侍奉楚国，说：「秦国非常憎恨齐国，而齐国和楚国合纵相亲。楚国如果真能与齐国绝交，秦国愿意献出商於之地六百里。」楚怀王贪心而相信张仪，于是与齐国绝交，派使者到秦国接受土地。张仪狡赖说：「我与楚王约定的是六里，没听说六百里。」楚国使者愤怒离去，回去报告怀王。怀王发怒，大举兴兵攻打秦国。秦国发兵迎击，在丹水、淅水一带大败楚军，斩杀八万人，俘虏楚将屈匄，于是夺取了楚国的汉中之地。怀王于是动员国内全部兵力，深入攻打秦国，在蓝田交战。魏国听说后，偷袭楚国直到邓地。楚军恐惧，从秦国撤兵回来。而齐国终究因为怨恨不肯救楚，楚国非常困窘。\n第二年，秦国割让汉中之地与楚国讲和。楚王说：「不愿得到土地，只愿得到张仪才甘心。」张仪听说后，就说：「用我一个人来抵汉中之地，请让我到楚国去。」到了楚国，又用厚礼买通当权的大臣靳尚，并在怀王的宠姬郑袖面前施展诡辩。怀王终究听信郑袖，又放走了张仪。这时屈原已被疏远，不再在位，出使齐国，回来后就劝谏怀王说：「为什么不杀张仪？」怀王后悔了，派人追张仪，没有追上。\n此后诸侯共同攻打楚国，大败楚军，杀了楚将唐眜。\n当时秦昭王与楚国联姻，想与怀王会面。怀王想前往，屈原说：「秦国是虎狼一样的国家，不可信任，不如不去。」怀王的小儿子子兰劝怀王前往：「怎么能断绝与秦国的友好！」怀王终于去了。进入武关，秦国的伏兵截断了他的后路，于是扣留怀王，要求割地。怀王愤怒，不肯答应。逃到赵国，赵国不肯接纳。又回到秦国，终于死在秦国，灵柩送回楚国安葬。\n怀王的长子顷襄王即位，让他的弟弟子兰做令尹。楚国人因为子兰劝怀王入秦而不能回来而责怪他。屈原也痛恨子兰，虽然被流放，仍眷恋楚国，心系怀王，不忘想回去，希望君主能醒悟一次，风俗能改变一次。他思念君主、振兴国家，想扭转局面，在一篇作品中再三表达这种心意。然而终究无可奈何，所以不能回去。终于由此看出怀王始终没有醒悟。\n令尹子兰听说后大怒，终于让上官大夫在顷襄王面前说屈原的坏话。顷襄王发怒，把屈原放逐了。\n屈原到了江边，披散着头发在水边边走边吟，面色憔悴，形体枯瘦。渔父看见他问道：「您不是三闾大夫吗？为什么到了这里？」屈原说：「整个世道都混浊而我独自清白，众人都昏醉而我独自清醒，因此被放逐。」渔父说：「圣人不受外物的拘束，而能随世俗推移。整个世道混浊，为什么不随波逐流、推波助澜？众人都昏醉，为什么不吃酒糟、喝薄酒？为什么要怀藏美玉般的品德，而使自己被放逐呢？」屈原说：「我听说，刚洗过头的人一定要弹去帽上的灰，刚洗过澡的人一定要抖去衣上的尘。又有谁能让自己干净的身体，去沾染外物的污浊呢！我宁可跳进江水葬身鱼腹，又怎能让洁白之身，蒙受世俗的尘垢呢！」于是写下《怀沙》之赋。接着抱着石头，投汨罗江而死。\n屈原死后，楚国有宋玉、唐勒、景差这些人，都爱好文辞而以赋著称；但都效法屈原的从容辞令，终究没有人敢直言劝谏。此后楚国日益削弱，几十年后，终于被秦国所灭。"],
    [107, "guwen-gwj-71", "public-domain", "孔子曰「导之以政齐之以刑民免而无耻导之以德齐之以礼有耻且格」老氏称「上德不德是以有德下德不失德是以无德法令滋章盗贼多有」太史公曰信哉是言也法令者治之具而非制治清浊之源也昔天下之网尝密矣然奸伪萌起其极也上下相遁至于不振当是之时吏治若救火扬沸非武健严酷恶能胜其任而愉快乎言道德者溺其职矣故曰「听讼吾犹人也必也使无讼乎」「下士闻道大笑之」非虚言也汉兴破觚而为圜斫雕而为朴网漏于吞舟之鱼而吏治烝烝不至于奸黎民艾安由是观之在彼不在此", "孔子说：「用政令来引导，用刑罚来整治，百姓只求免罪而没有羞耻之心。用德行来引导，用礼教来整治，百姓就有羞耻之心而且归服。」老子说：「上德的人不自以为有德，因此有德；下德的人唯恐失德，因此无德。法令越分明，盗贼越多。」太史公说：这话说得对啊！法令是治理的工具，而不是决定政治清明或浑浊的本源。从前天下的法网曾经很严密，然而奸邪虚伪萌生，到了极点，上下互相逃避，以致一蹶不振。在这个时候，官吏治理如同救火扬汤，不用强健严酷的手段，怎么能胜任而愉快呢？讲道德的人，就失职了。所以说「审理诉讼，我和别人一样，一定要使没有诉讼才好」。「下等的士人听到道就大笑」。这不是空话。\n汉朝兴起，破除棱角使它变圆，去掉雕饰使它质朴，法网宽疏得能漏过吞舟的大鱼，而官吏治绩蒸蒸日上，不至于奸邪，百姓安定。由此看来，在于德行而不在于法令。"],
    [108, "guwen-gwj-72", "public-domain", "韩子曰「儒以文乱法而侠以武犯禁」二者皆讥而学士多称于世云至如以术取宰相卿大夫辅翼其世主功名俱著于春秋固无可言者及若季次原宪闾巷人也读书怀独行君子之德义不苟合当世当世亦笑之故季次原宪终身空室蓬户褐衣疏食不厌死而已四百余年而弟子志之不倦今游侠其行虽不轨于正义然其言必信其行必果已诺必诚不爱其躯赴士之厄困既已存亡死生矣而不矜其能羞伐其德盖亦有足多者焉且缓急人之所时有也太史公曰昔者虞舜窘于井廪伊尹负于鼎俎傅说匿于傅险吕尚困于棘津夷吾桎梏百里饭牛仲尼畏匡菜色陈蔡此皆学士所谓有道仁人也犹然遭此灾况以中材而涉乱世之末流乎其遇害何可胜道哉鄙人有言曰「何知仁义已飨其利者为有德」故伯夷丑周饿死首阳山而文武不以其故贬王跖蹻暴戾其徒诵义无穷由此观之「窃钩者诛窃国者侯侯之门仁义存」非虚言也今拘学或抱咫尺之义久孤于世岂若卑论侪俗与世沉浮而取荣名哉而布衣之徒设取予然诺千里诵义为死不顾世此亦有所长非苟而已也故士穷窘而得委命此岂非人之所谓贤豪间者邪诚使乡曲之侠予季次原宪比权量力效功于当世不同日而论矣要以功见言信侠客之义又曷可少哉古布衣之侠靡得而闻已近世延陵孟尝春申平原信陵之徒皆因王者亲属藉于有土卿相之富厚招天下贤者显名诸侯不可谓不贤者矣比如顺风而呼声非加疾其势激也至如闾巷之侠修行砥名声施于天下莫不称贤是为难耳然儒墨皆排摈不载自秦以前匹夫之侠湮灭不见余甚恨之以余所闻汉兴有朱家田仲王公剧孟郭解之徒虽时扞当世之文罔然其私义廉洁退让有足称者名不虚立士不虚附至如朋党宗强比周设财役贫豪暴侵凌孤弱恣欲自快游侠亦丑之余悲世俗不察其意而猥以朱家郭解等令与暴豪之徒同类而共笑之也", "韩非子说：「儒者用文辞扰乱法度，而侠士用武力违犯禁令。」两者都受到讥议，而学士多被世人所称道。至于用权术取得宰相卿大夫之位，辅佐当世的君主，功名都记载在史册上，本来就没有什么可说的。至于像季次、原宪，是闾巷中人，读书怀有独行君子的德行，守义不与当世苟合，当世的人也讥笑他们。所以季次、原宪终身住在空室蓬户之中，粗布衣服、粗劣饭食都吃不饱。他们死去已经四百多年，而弟子们传述他们不知疲倦。如今的游侠，他们的行为虽然不合于正义，但他们说话必定守信，行事必定果决，已经许诺必定真诚，不爱惜自己的身体，奔赴士人的困厄，已经使将亡的得存、将死的得生，却不夸耀自己的能力，羞于自陈自己的恩德，大概也有值得称赞的地方。\n况且缓急之事，是人时常会有的。太史公说：从前虞舜在井廪中困窘，伊尹背着鼎俎，傅说隐遁在傅险，吕尚困在棘津，管仲戴上枷锁，百里奚喂牛，仲尼在匡地受到惊吓，在陈、蔡面有菜色。这些都是学士所说的有道仁人，尚且遭遇这样的灾难，何况以中等之才而置身乱世的末流呢？他们遇害的事哪里说得完呢！\n鄙俗的人有话说：「哪里知道什么仁义，已经享受到他的好处的人就认为他有德。」所以伯夷以周朝为耻，饿死在首阳山，而文王、武王不因此被贬损王号；盗跖、庄蹻残暴，他们的党徒却无穷地诵说他们的义。由此看来，「偷钩的被杀，偷国的封侯，诸侯之门就有仁义存在」，这不是空话。\n如今拘泥于所学的人，或者抱着咫尺的义理，长久孤立于世俗，哪里比得上降低论调、混同流俗，与世沉浮而取得荣名呢！而布衣之徒，讲究取予和然诺，千里之外都诵说他们的义，为别人去死而不管世俗，这也是有所长的，不是苟且而已。所以士人在穷困窘迫时能托付性命，这难道不是人们所说的贤豪之士吗？假使乡曲的侠士，同季次、原宪比较权位力量，对当世建立功业，是不能同日而论的。但要以功业显现、言语守信来衡量，侠客的义又怎么可以轻视呢！\n古代布衣的侠士，已经无法听到了。近世的延陵、孟尝、春申、平原、信陵这些人，都凭借王者的亲属，依靠有封土的卿相的富厚，招揽天下的贤者，显名于诸侯，不能说不是贤者。好比顺风呼喊，声音并没有更响，是形势激荡的。至于闾巷中的侠士，修养品行、砥砺名声，声名传遍天下，没有人不称他们贤能，这才是难的。然而儒家、墨家都排斥他们，不予记载。秦朝以前，平民的侠士，湮灭不见，我很遗憾。据我所听到的，汉朝兴起有朱家、田仲、王公、剧孟、郭解这些人，虽然时常触犯当世的法网，但他们的私义廉洁退让，有值得称道的地方。名声不是凭空建立的，士人也不会凭空依附。至于结党营私、宗族豪强互相勾结，设置财货役使贫民，豪强暴力侵凌孤弱，放纵私欲自我快意，游侠也鄙视他们。我悲伤世俗不明察他们的心意，就轻率地把朱家、郭解等人同暴豪之徒同类看待而一起讥笑。"],
    [109, "guwen-gwj-73", "public-domain", "孔子曰「六艺于治一也礼以节人乐以发和书以道事诗以达意易以神化春秋以义」太史公曰天道恢恢岂不大哉谈言微中亦可以解纷淳于髡者齐之赘婿也长不满七尺滑稽多辩数使诸侯未尝屈辱齐威王之时喜隐好为淫乐长夜之饮沉湎不治委政卿大夫百官荒乱诸侯并侵国且危亡在于旦暮左右莫敢谏淳于髡说之以隐曰「国中有大鸟止王之庭三年不蜚又不鸣王知此鸟何也」王曰「此鸟不飞则已一飞冲天不鸣则已一鸣惊人」于是乃朝诸县令长七十二人赏一人诛一人奋兵而出诸侯振惊皆还齐侵地威行三十六年语在田完世家中威王八年楚大发兵加齐齐王使淳于髡之赵请救兵赍金百斤车马十驷淳于髡仰天大笑冠缨索绝王曰「先生少之乎」髡曰「何敢」王曰「笑岂有说乎」髡曰「今者臣从东方来见道傍有禳田者操一豚蹄酒一盂祝曰『瓯窭满篝汙邪满车五谷蕃熟穰穰满家』臣见其所持者狭而所欲者奢故笑之」于是齐威王乃益赍黄金千镒白璧十双车马百驷髡辞而行至赵赵王与之精兵十万革车千乘楚闻之夜引兵而去威王大说置酒后宫召髡赐之酒问曰「先生能饮几何而醉」对曰「臣饮一斗亦醉一石亦醉」威王曰「先生饮一斗而醉恶能饮一石哉其说可得闻乎」髡曰「赐酒大王之前执法在傍御史在后髡恐惧俯伏而饮不过一斗径醉矣若亲有严客髡帣鞲鞠侍酒于前时赐余沥奉觞上寿数起饮不过二斗径醉矣若朋友交游久不相见卒然相睹欢然道故私情相语饮可五六斗径醉矣若乃州闾之会男女杂坐行酒稽留六博投壶相引为曹握手无罚目眙不禁前有堕珥后有遗簪髡窃乐此饮可八斗而醉二三日暮酒阑合尊促坐男女同席履舄交错杯盘狼藉堂上烛灭主人留髡而送客罗襦襟解微闻芗泽当此之时髡心最欢能饮一石故曰酒极则乱乐极则悲万事尽然言不可极极之而衰」以讽谏焉齐王曰「善」乃罢长夜之饮以髡为诸侯主客宗室置酒髡尝在侧", "孔子说：「六艺对于治理国家是一样的。《礼》用来节制人，《乐》用来抒发和谐，《书》用来陈述政事，《诗》用来表达心意，《易》用来神妙变化，《春秋》用来明辨道义。」太史公说：天道广阔，难道不宏大吗！谈笑之间稍稍切中事理，也可以排解纠纷。\n淳于髡是齐国的赘婿。身高不到七尺，滑稽多辩，多次出使诸侯，不曾受到屈辱。齐威王的时候喜欢隐语，喜好作过度享乐、通宵饮酒，沉湎其中不治理政事，把政事委托给卿大夫。百官荒乱，诸侯都来侵犯，国家将要危亡，就在旦夕之间，左右没有人敢进谏。淳于髡用隐语劝他说：「国中有一只大鸟，停在大王的庭院里，三年不飞也不叫，大王知道这鸟是什么吗？」威王说：「这鸟不飞则已，一飞就冲上青天；不鸣则已，一鸣就使人吃惊。」于是召见各县令长七十二人，赏了一个人，杀了一个人，发兵而出。诸侯震惊，都把侵占齐国的土地归还。威势施行了三十六年。这件事记载在《田完世家》里。\n威王八年，楚国大举发兵进犯齐国。齐王派淳于髡到赵国请求救兵，带黄金百斤、车马十驷。淳于髡仰天大笑，把帽带都笑断了。威王说：「先生嫌少吗？」淳于髡说：「怎么敢！」威王说：「笑难道有什么说法吗？」淳于髡说：「今天我从未方来，看见路旁有个祈求田神的人，拿着一只猪蹄、一杯酒，祝祷说：『高地的收成装满篓，低地的收成装满车，五谷丰登，满家满囤。』我看见他拿出来的少而想要的多，所以笑他。」于是齐威王就增加到黄金千镒、白璧十双、车马百驷。淳于髡辞别出发，到了赵国。赵王给他精兵十万、革车千乘。楚国听说了，连夜退兵而去。\n威王非常高兴，在后宫设酒，召淳于髡赐他酒喝。问道：「先生能喝多少才醉？」淳于髡答道：「我喝一斗也醉，喝一石也醉。」威王说：「先生喝一斗就醉，怎么能喝一石呢！其中的道理可以讲给我听吗？」淳于髡说：「在大王面前赐酒，执法官在旁边，御史在后面，我恐惧地俯伏着喝，不过一斗就醉了。如果是父母有尊贵的客人，我卷起袖子、弯腰跪着，在面前侍酒，时时赐我剩下的酒，我举杯祝寿，多次起身，喝不过二斗就醉了。如果是朋友交游，很久不见，突然相遇，高兴地叙旧，私下谈心，喝五六斗就醉了。至于乡里之间的聚会，男女杂坐，行酒停留，玩六博、投壶，互相招引结伴，握手不受惩罚，注目不遭禁止，前面有掉落的耳环，后面有遗落的发簪，我私下喜欢这种场合，喝八斗才有两三分醉。天色已晚，酒席将散，合并酒杯、促膝而坐，男女同席，鞋子交错，杯盘狼藉，堂上的蜡烛熄灭，主人留下我而送走别的客人，丝绸短袄解开衣襟，微微闻到香气，在这种时候，我心里最快活，能喝一石。所以说酒到极点就昏乱，乐到极点就悲伤；万事都是这样，说的是不可以到极点，到极点就会衰败。」用它来讽谏。齐王说：「好。」于是停止通宵饮酒，让淳于髡做诸侯的主客。宗室设酒，淳于髡常在旁边。"],
    [110, "guwen-gwj-74", "public-domain", "老子曰「至治之极邻国相望鸡狗之声相闻民各甘其食美其服安其俗乐其业至老死不相往来」必用此为务挽近世涂民耳目则几无行矣太史公曰夫神农以前吾不知已至若诗书所述虞夏以来耳目欲极声色之好口欲穷刍豢之味身安逸乐而心夸矜势能之荣使俗之渐民久矣虽户说以眇论终不能化故善者因之其次利道之其次教诲之其次整齐之最下者与之争夫山西饶材竹谷纑旄玉石山东多鱼盐漆丝声色江南出楠梓姜桂金锡连丹沙犀玳瑁珠玑齿革龙门碣石北多马牛羊旃裘筋角铜铁则千里往往山出棋置此其大较也皆中国人民所喜好谣俗被服饮食奉生送死之具也故待农而食之虞而出之工而成之商而通之此宁有政教发征期会哉人各任其能竭其力以得所欲故物贱之征贵贵之征贱各劝其业乐其事若水之趋下日夜无休时不召而自来不求而民出之岂非道之所符而自然之验邪周书曰「农不出则乏其食工不出则乏其事商不出则三宝绝虞不出则财匮少」财匮少而山泽不辟矣此四者民所衣食之原也原大则饶原小则鲜上则富国下则富家贫富之道莫之夺予而巧者有余拙者不足故太公望封于营丘地潟卤人民寡于是太公劝其女功极技巧通鱼盐则人物归之繦至而辐凑故齐冠带衣履天下海岱之间敛袂而往朝焉其后齐中衰管子修之设轻重九府则桓公以霸九合诸侯一匡天下而管氏亦有三归位在陪臣富于列国之君是以齐富强至于威宣也故曰「仓廪实而知礼节衣食足而知荣辱」礼生于有而废于无故君子富好行其德小人富以适其力渊深而鱼生之山深而兽往之人富而仁义附焉富者得势益彰失势则客无所之以而不乐夷狄益甚谚曰「千金之子不死于市」此非空言也故曰「天下熙熙皆为利来天下壤壤皆为利往」夫千乘之王万家之侯百室之君尚犹患贫而况匹夫编户之民乎", "老子说：「至治的极致，邻国互相望得见，鸡狗的声音互相听得到，百姓各自觉得自己的饮食甘美，觉得自己的衣服华美，安于自己的风俗，乐于自己的职业，直到老死不相往来。」如果一定要以此作为追求，用来闭塞近世百姓的耳目，那几乎行不通了。\n太史公说：神农以前的事，我不知道。至于《诗》《书》所叙述的虞、夏以来，耳目要穷尽声色的美好，口要穷尽肉食的滋味，身体安于逸乐，而心里夸耀权势才能的荣耀。这种习俗浸染百姓已经很久了，即使挨家挨户用高妙的道理去劝说，终究不能感化。所以最好的办法是顺其自然，其次是因势利导，再次是教诲，再次是整齐法度，最下等的是与民争利。\n太行山以西富有木材、竹子、谷物、纑麻、旄牛尾、玉石；太行山以东多鱼、盐、漆、丝、音乐女色；江南出产楠木、梓木、姜、桂、金、锡、铅、朱砂、犀角、玳瑁、珍珠、象牙、皮革；龙门、碣石以北多马、牛、羊、毡裘、筋、角；铜、铁则千里之间往往从山中产出，像棋子一样分布：这是大概的情况。这些都是中国人民所喜好的，是风俗中穿衣饮食、养生送死所需的东西。所以要靠农民耕种供食，靠虞人开发山泽，靠工匠制成器物，靠商人流通货物。这难道有政令教化征发期会吗？人们各自发挥自己的能力，竭尽自己的力量，来得到自己想要的东西。所以物价贱就预示着要贵，贵就预示着要贱，各人勉力自己的职业，乐于自己的事务，像水往低处流，日夜没有停息，不召而自来，不求而百姓自己产出。难道不是与道相符、自然的验证吗？\n《周书》说：「农民不生产就缺乏粮食，工匠不生产就缺乏器物，商人不流通就三宝断绝，虞人不开发就财货匮乏。」财货匮乏，山林水泽就不能开辟了。这四者，是百姓衣食的本源。本源大就富饶，本源小就贫乏。上可以富国，下可以富家。贫富的道理，没有谁能剥夺或给予，而灵巧的人有余，笨拙的人不足。所以太公望封在营丘，土地盐碱，人口稀少，于是太公勉励女子从事纺织，极尽技巧，流通鱼盐，于是人和物都归附他，像绳索相连、车辐聚集。所以齐国冠带衣履遍布天下，海岱之间的人都敛袖前往朝见。此后齐国中途衰败，管仲整顿它，设置轻重九府，于是桓公因此称霸，九合诸侯，一匡天下；而管氏也有三归之台，地位在陪臣，财富比列国之君还多。因此齐国富强直到威王、宣王。\n所以说：「粮仓充实才知道礼节，衣食充足才知道荣辱。」礼产生于富有而废弃于贫穷。所以君子富有，喜好施行他的德行；小人富有，得以舒展他的力量。渊深而鱼生在其中，山深而兽往那里去，人富而仁义依附于他。富有的人得势就更加显赫，失势则门客无处可去，因此而不再快乐。夷狄更是如此。谚语说：「千金的子弟，不死在街市上。」这不是空话。所以说：「天下熙熙，都为利而来；天下攘攘，都为利而往。」那千乘之国的王、万家之邑的侯、百室之家的君，尚且还忧虑贫穷，何况匹夫编户的百姓呢！"],
    [111, "guwen-gwj-75", "public-domain", "太史公曰「先人有言『自周公卒五百岁而有孔子孔子卒后至于今五百岁有能绍明世正易传继春秋本诗书礼乐之际』意在斯乎意在斯乎小子何敢让焉」上大夫壶遂曰「昔孔子何为而作春秋哉」太史公曰「余闻董生曰『周道衰废孔子为鲁司寇诸侯害之大夫壅之孔子知言之不用道之不行也是非二百四十二年之中以为天下仪表贬天子退诸侯讨大夫以达王事而已矣』子曰『我欲载之空言不如见之于行事之深切著明也』夫春秋上明三王之道下辨人事之纪别嫌疑明是非定犹豫善善恶恶贤贤贱不肖存亡国继绝世补敝起废王道之大者也易著天地阴阳四时五行故长于变礼经纪人伦故长于行书记先王之事故长于政诗记山川溪谷禽兽草木牝牡雌雄故长于风乐乐所以立故长于和春秋辩是非故长于治人是故礼以节人乐以发和书以道事诗以达意易以道化春秋以道义拨乱世反之正莫近于春秋春秋文成数万其指数千万物之散聚皆在春秋春秋之中弑君三十六亡国五十二诸侯奔走不得保其社稷者不可胜数察其所以皆失其本已故易曰『失之毫厘差以千里』故曰『臣弑君子弑父非一旦一夕之故也其渐久矣』故有国者不可以不知春秋前有谗而弗见后有贼而不知为人臣者不可以不知春秋守经事而不知其宜遭变事而不知其权为人君父而不通于春秋之义者必蒙首恶之名为人臣子而不通于春秋之义者必陷篡弑之诛死罪之名其实皆以为善为之不知其义被之空言而不敢辞夫不通礼义之旨至于君不君臣不臣父不父子不子夫君不君则犯臣不臣则诛父不父则无道子不子则不孝此四行者天下之大过也以天下之大过予之则受而弗敢辞故春秋者礼义之大宗也夫礼禁未然之前法施已然之后法之所为用者易见而礼之所为禁者难知」壶遂曰「孔子之时上无明君下不得任用故作春秋垂空文以断礼义当一王之法今夫子上遇明天子下得守职万事既具咸各序其宜夫子所论欲以何明」太史公曰「唯唯否否不然余闻之先人曰『伏羲至纯厚作易八卦尧舜之盛尚书载之礼乐作焉汤武之隆诗人歌之春秋采善贬恶推三代之德褒周室非独刺讥而已也』汉兴以来至明天子获符瑞封禅改正朔易服色受命于穆清泽流罔极海外殊俗重译款塞请来献见者不可胜道臣下百官力诵圣德犹不能宣尽其意且士贤能而不用有国者之耻主上明圣而德不布闻有司之过也且余尝掌其官废明圣盛德不载灭功臣世家贤大夫之业不述堕先人所言罪莫大焉余所谓述故事整齐其世传非所谓作也而君比之于春秋谬矣」于是论次其文七年而太史公遭李陵之祸幽于缧绁乃喟然而叹曰「是余之罪也夫是余之罪也夫身毁不用矣」退而深惟曰「夫诗书隐约者欲遂其志之思也昔西伯拘羑里演周易孔子厄陈蔡作春秋屈原放逐著离骚左丘失明厥有国语孙子膑脚而论兵法不韦迁蜀世传吕览韩非囚秦说难孤愤诗三百篇大抵贤圣发愤之所为作也此人皆意有所郁结不得通其道也故述往事思来者」于是卒述陶唐以来至于麟止自黄帝始", "太史公说：「先人说过：『周公去世五百年而有孔子。孔子去世后到现在五百年，有能继承清明之世，正定《易传》，续作《春秋》，本于《诗》《书》《礼》《乐》之际的人吗？』用意就在这里吧！用意就在这里吧！我怎么敢推让呢。」\n上大夫壶遂说：「从前孔子为什么作《春秋》呢？」太史公说：「我听董生说：『周道衰废，孔子做鲁国司寇，诸侯忌害他，大夫阻塞他。孔子知道自己的话不被采用，道不能施行，于是评论二百四十二年之间的事，作为天下的准则，贬斥天子，斥退诸侯，声讨大夫，以通达王事罢了。』孔子说：『我想把道理空言记载下来，不如体现在行事之中更加深切明白。』《春秋》上明三王之道，下辨人事的纲纪，区别嫌疑，明辨是非，决断犹豫，扬善憎恶，尊贤贱不肖，保存亡国，延续绝世的家族，补救弊病、振兴废弛，这是王道的大事。《易》著明天地阴阳四时五行，所以长于变化；《礼》纲纪人伦，所以长于实行；《书》记载先王的事迹，所以长于政事；《诗》记载山川溪谷禽兽草木牝牡雌雄，所以长于风教；《乐》是快乐所由建立的，所以长于和谐；《春秋》辨明是非，所以长于治人。所以《礼》用来节制人，《乐》用来抒发和谐，《书》用来陈述政事，《诗》用来表达心意，《易》用来讲变化，《春秋》用来讲道义。拨乱世使之回到正道，没有比《春秋》更切近的了。《春秋》文字数万，要旨数千。万物的聚散都在《春秋》之中。《春秋》中，弑君的有三十六起，亡国的有五十二个，诸侯奔走而不能保住自己社稷的数不胜数。考察其中的原因，都是失去了根本。所以《易》说『失之毫厘，差以千里』。所以说『臣弑君，子弑父，不是一朝一夕的缘故，是逐渐发展很久了』。所以拥有国家的人不可以不知道《春秋》，否则前面有谗言而看不见，后面有贼人而不知道。做臣子的不可以不知道《春秋》，否则守着常规的事而不知道变通，遭遇变故而不知道权变。做君父而不通晓《春秋》大义的，必定蒙受首恶的名声。做臣子而不通晓《春秋》大义的，必定陷入篡位弑君的被杀之罪、死罪的名声。其实他们都自以为是善，做了却不知道其中的义，被加上空言罪名而不敢推辞。不通晓礼义的要旨，就会君不君、臣不臣、父不父、子不子。君不君就会被侵犯，臣不臣就会被诛杀，父不父就没有道，子不子就不孝。这四种行为，是天下的大过。把天下的大过加给他，就只能接受而不敢推辞。所以《春秋》是礼义的大宗。礼在事情发生之前禁止，法在事情发生之后施行；法所起的作用容易看见，而礼所起的禁止作用难以知道。」\n壶遂说：「孔子的时候，上面没有明君，下面不能得到任用，所以作《春秋》，留下空文来裁断礼义，充当一代王者的法度。如今您上遇明明天子，下能守住职位，万事已经具备，都各得其宜，您所论述的，想表明什么呢？」\n太史公说：「嗯嗯，不不，不是这样。我听先人说：『伏羲极为纯厚，作《易》八卦。尧、舜的盛德，《尚书》记载它，礼乐由此兴作。汤、武的兴隆，诗人歌颂它。《春秋》采善贬恶，推重三代的德行，褒扬周室，并不只是讥刺而已。』汉朝兴起以来，直到明明天子，获得符瑞，封禅，改历法，变服色，受命于上天，恩泽流布无穷，海外异俗，辗转翻译前来叩关，请求来献见的，说不完。臣下百官尽力诵说圣德，还不能完全表达他们的心意。况且士人贤能而不被任用，是拥有国家者的耻辱；主上明圣而德行不能传布闻知，是有关官吏的过失。况且我曾经掌管这个官职，废弃明圣的盛德不予记载，埋没功臣世家贤大夫的功业不予叙述，毁坏先人的话，罪过没有比这更大的了。我所说的只是记述旧事，整理他们的世传，不是所谓的创作，而您把它比作《春秋》，错了。」\n于是论列编次他的文字。七年后太史公遭遇李陵之祸，被囚禁在绳索中。于是喟然叹息说：「这是我的罪过啊！这是我的罪过啊！身体毁损不被任用了。」退下来深思说：「《诗》《书》之所以隐约其辞，是想表达他们心志的思考。从前西伯被拘羑里，推演《周易》；孔子困厄陈、蔡，作《春秋》；屈原被放逐，著《离骚》；左丘失明，才有《国语》；孙子被膑脚，而论兵法；吕不韦迁到蜀地，世上流传《吕览》；韩非被囚秦国，有《说难》《孤愤》；《诗》三百篇，大抵是贤圣发愤所作。这些人都是心中有郁结，不能通畅地实现他们的道，所以追述往事，思念来者。」于是终于叙述陶唐以来，直到获麟为止，从黄帝开始。"],
    [112, "guwen-gwj-76", "public-domain", "古者富贵而名摩灭不可胜记唯倜傥非常之人称焉盖西伯拘而演周易仲尼厄而作春秋屈原放逐乃赋离骚左丘失明厥有国语孙子膑脚兵法修列不韦迁蜀世传吕览韩非囚秦说难孤愤诗三百篇大底圣贤发愤之所为作也此人皆意有所郁结不得通其道故述往事思来者乃如左丘无目孙子断足终不可用退而论书策以舒其愤思垂空文以自见仆窃不逊近自托于无能之辞网罗天下放失旧闻略考其行事综其终始稽其成败兴坏之纪上计轩辕下至于兹为十表本纪十二书八章世家三十列传七十凡百三十篇亦欲以究天人之际通古今之变成一家之言草创未就会遭此祸惜其不成是以就极刑而无愠色仆诚以著此书藏之名山传之其人通邑大都则仆偿前辱之责虽万被戮岂有悔哉然此可为智者道难为俗人言也且负下未易居下流多谤议仆以口语遇遭此祸重为乡党所戮笑以污辱先人亦何面目复上父母之丘墓乎虽累百世垢弥甚耳是以肠一日而九回居则忽忽若有所亡出则不知其所往每念斯耻汗未尝不发背沾衣也身直为闺阁之臣宁得自引深藏于岩穴邪故且从俗浮沉与时俯仰以通其狂惑今少卿乃教以推贤进士无乃与仆私心剌谬乎今虽欲自雕琢曼辞以自饰无益于俗不信适足取辱耳要之死日然后是非乃定书不能悉意略陈固陋", "古时候富贵而名声磨灭的人，多得数不清，只有卓越不凡的人才被后世称道。周文王被拘禁而推演《周易》；孔子受困厄而写作《春秋》；屈原被放逐，才赋写《离骚》；左丘明失明，才有《国语》；孙膑被剜去膝盖骨，《兵法》才编著出来；吕不韦被贬到蜀地，世上才流传《吕览》；韩非被囚于秦，才有《说难》《孤愤》；《诗经》三百篇，大都是圣贤发愤而作的。这些人都是心中有郁结，不能实现自己的主张，所以追述往事、寄望将来的人。至于像左丘明没有眼睛、孙膑断了双脚，终究不能为世所用，就退而著书立说，来抒发他们的愤懑，想留下文章来表现自己。\n我私下不自量力，近来用无能的文辞，搜集天下散失的旧闻，大略考订他们的行事，综合他们的始末，考察他们成败兴衰的规律，上从黄帝算起，下到今天，写成十表、本纪十二篇、书八章、世家三十篇、列传七十篇，共一百三十篇。也是想借此探究天与人的关系，通晓古今的变化，成为一家之言。草稿还没完成，就遭了这桩祸事；我痛惜它没有写成，所以受了极刑也没有怨怒的神色。我确实想靠写这本书，藏在名山之中，传给能理解的人，流传到通都大邑，那么我就偿还了以前受辱的债，即使被杀一万次，哪里会后悔呢！然而这话只能对明智的人说，难以对俗人讲啊！\n况且背着罪名的人不易安处，地位低下的人多遭谤议。我因言谈遭遇这场灾祸，深为乡里所羞辱耻笑，又污辱了先人，还有什么脸面再去上父母的坟墓呢？即使过了一百代，耻辱只会更深罢了！所以我愁肠一天要转九回，在家就恍恍惚惚像丢了什么，出门就不知该往哪里去。每当想到这种耻辱，汗没有不从背上冒出、沾湿衣服的！我自身不过是宫闱中的臣仆，怎么能自己引退、深藏在山洞里呢？所以只好随俗浮沉，随时俯仰，以此抒发我心中的狂惑。如今少卿竟教我去推举贤才、引荐士人，恐怕与我的心意太相违背了吧？现在即使想自我修饰，用美言来装点，也没有用，世俗不会相信，恰好自取羞辱罢了。总之，到死的那一天，是非才有定论。书信不能尽述心意，姑且大略陈述我的浅陋之见。"],
    [113, "classic-gw-115", "public-domain", "古之学者必有师师者所以传道受业解惑也人非生而知之者孰能无惑惑而不从师其为惑也终不解矣生乎吾前其闻道也固先乎吾吾从而师之生乎吾后其闻道也亦先乎吾吾从而师之吾师道也夫庸知其年之先后生于吾乎是故无贵无贱无长无少道之所存师之所存也嗟乎师道之不传也久矣欲人之无惑也难矣古之圣人其出人也远矣犹且从师而问焉今之众人其下圣人也亦远矣而耻学于师是故圣益圣愚益愚巫医乐师百工之人不耻相师士大夫之族曰师曰弟子云者则群聚而笑之问之则曰「彼与彼年相若也道相似也位卑则足羞官盛则近谀」呜呼师道之不复可知矣巫医乐师百工之人君子不齿今其智乃反不能及其可怪也欤圣人无常师孔子师郯子苌弘师襄老聃郯子之徒其贤不及孔子孔子曰三人行则必有我师是故弟子不必不如师师不必贤于弟子闻道有先后术业有专攻如是而已", "古代求学的人一定有老师。老师，是用来传授道理、教授学业、解答疑难问题的。人不是生下来就懂得道理的，谁能没有疑惑？有了疑惑却不跟从老师学习，那些成为疑难的问题，就始终得不到解答了。出生在我前面的人，他懂得道理本来就比我早，我跟从他并以他为师；出生在我后面的人，如果他懂得道理也比我早，我也跟从他并以他为师。我学习的是道理，哪里用得着知道他生年比我早还是晚呢？因此无论地位贵贱，无论年纪大小，道理存在的地方，就是老师存在的地方。\n唉！从师学习的风尚不流传已经很久了！想要人没有疑惑就很难了！古代的圣人，他们超出一般人很远了，尚且跟从老师请教；如今的一般人，他们低于圣人也很远了，却以向老师学习为耻。因此圣人更加圣明，愚人更加愚昧。\n巫医、乐师和各种工匠，不以互相学习为耻。士大夫这类人，一听到有人称「老师」称「弟子」，就成群聚在一起讥笑人家。问他们为什么这样，就说：「他和他年龄差不多，道德学问也差不多，以地位低的人为师就感到羞耻，以官职高的人为师就近乎谄媚。」唉！从师学习的风尚不能恢复，由此就可以知道了。巫医、乐师和各种工匠，是士大夫们所瞧不起的，如今士大夫的见识竟反而比不上他们，真是奇怪啊！\n圣人没有固定的老师。孔子曾以郯子、苌弘、师襄、老聃为师。郯子这些人，他们的贤能都比不上孔子。孔子说：三个人同行，里面一定有可以当我老师的人。所以学生不一定不如老师，老师不一定比学生贤能，懂得道理有早有晚，学问技艺各有各的专门研究，如此罢了。"],
    [114, "guwen-gwj-180", "", "国子先生晨入太学招诸生立馆下诲之曰「业精于勤荒于嬉行成于思毁于随方今圣贤相逢治具毕张拔去凶邪登崇畯良占小善者率以录名一艺者无不庸爬罗剔抉刮垢磨光盖有幸而获选孰云多而不扬诸生业患不能精无患有司之不明行患不能成无患有司之不公」言未既有笑于列者曰「先生欺余哉弟子事先生于兹有年矣先生口不绝吟于六艺之文手不停披于百家之编纪事者必提其要纂言者必钩其玄贪多务得细大不捐焚膏油以继晷恒兀兀以穷年先生之业可谓勤矣觝排异端攘斥佛老补苴罅漏张皇幽眇寻坠绪之茫茫独旁搜而远绍障百川而东之回狂澜于既倒先生之于儒可谓有劳矣沉浸醲郁含英咀华作为文章其书满家上规姚姒浑浑无涯下逮庄骚太史所录子云相如同工异曲先生之于文可谓闳其中而肆其外矣少始知学勇于敢为长通于方左右具宜先生之于为人可谓成矣然而公不见信于人私不见助于友跋前疐后动辄得咎暂为御史遂窜南夷三年博士冗不见治命与仇谋取败几时冬暖而儿号寒年丰而妻啼饥头童齿豁竟死何裨不知虑此而反教人为」先生曰「吁子来前夫大木为杗细木为桷欂栌侏儒椳闑扂楔各得其宜施以成室者匠氏之工也玉札丹砂赤箭青芝牛溲马勃败鼓之皮俱收并蓄待用无遗者医师之良也登明选公杂进巧拙纡馀为妍卓荦为杰校短量长惟器是适者宰相之方也昔者孟轲好辩孔道以明辙环天下卒老于行荀卿守正大论是弘逃谗于楚废死兰陵是二儒者吐辞为经举足为法绝类离伦优入圣域其遇于世何如也今先生学虽勤而不繇其统言虽多而不要其中文虽奇而不济于用行虽修而不显于众犹且月费俸钱岁靡廪粟子不知耕妇不知织乘马从徒安坐而食踵常途之促促窥陈编以盗窃然而圣主不加诛宰臣不见斥兹非其幸欤动而得谤名亦随之投闲置散乃分之宜若夫商财贿之有亡计班资之崇庳忘己量之所称指前人之瑕疵是所谓诘匠氏之不以杙为楹而訾医师以昌阳引年欲进其豨苓也」", "国子先生早晨走进太学，召集学生站在学馆下，教导他们说：「学业靠勤奋而精进，因嬉戏而荒废；德行靠思考而成就，因随俗而败坏。如今圣君贤臣相遇，法度全都建立。除去凶险邪恶的人，提拔尊崇才德优良的人。有一点长处的大都加以录用，有一技之名的没有不被任用的。搜罗挑选，刮垢磨光。大概有侥幸而被选中的，谁说人才多而不能显扬？学生们只担心学业不能精进，不要担心主管官吏不明察；只担心德行不能成就，不要担心主管官吏不公正。」\n话没说完，有人在行列中笑着说：「先生在骗我们吧！弟子跟从先生，到现在有年头了。先生口里不停地吟诵六经的文章，手里不停地翻阅诸子百家的书。记事的必定提取它的要点，立论的必定探求它的深意。贪求多得，大小不弃。点着油灯接续白昼，常常勤勤恳恳地度过一年。先生的学业，可以说勤奋了。抵制排斥异端，排斥佛老。弥补缺漏，阐发幽微。寻找茫茫失传的道统，独自旁搜远绍。阻挡百川使它东流，挽回已倒的狂澜。先生对于儒学，可以说有功劳了。沉浸在浓郁的书香中，咀嚼英华，写作文章，书堆满屋。上取法虞夏，浑厚无涯；下及《庄子》《离骚》，太史公的记述；扬雄、司马相如，同工异曲。先生对于文章，可以说内容宏富而文辞奔放了。少年时开始懂得学习，勇于实践；长大后通晓事理，左右都合宜。先生的为人，可以说成熟了。然而为公不被别人信任，为私不被朋友帮助。进退两难，一动就得罪。刚做御史，就被贬到南夷。做了三年博士，闲散而不见治绩。命运与仇敌合谋，什么时候才能不败？冬天暖和儿子却喊冷，年成丰收妻子却啼饥。头发脱光头秃齿缺，到死有什么益处。不知道考虑这些，反而来教训别人吗？」\n先生说：「唉，你到前面来！大木料做栋梁，小木料做屋椽，斗拱短柱，门枢门闩门栓门楔，各自得到适宜的用处，用来建成房屋的，是工匠的技术。地榆朱砂，天麻青芝，牛尿马勃，破鼓的皮，全都收集储藏，等待取用而不遗漏的，是医师的高明。选拔光明公正，巧拙并进，婉转为美，卓越为杰，比较长短，量才适用的，是宰相的方法。从前孟轲喜好辩论，孔子的学说因此彰明，车辙环绕天下，终于老死在奔走途中。荀卿恪守正道，宏扬大论，从楚国逃避谗言，被废而死葬在兰陵。这两位儒者，说出的话成为经典，一举一动成为法则，超绝同类，优异而进入圣人的境界，他们在世上的遭遇又如何呢？如今先生我学业虽然勤奋却不遵循系统，言论虽然多却不切中要害，文章虽然奇特却无济于实用，德行虽然修养却不显扬于众人。尚且每月耗费俸钱，每年浪费官粮；儿子不知道耕种，妻子不知道纺织；骑马带着仆从，安坐而吃饭。循着平常的路拘谨前行，窥看旧书而剽窃。然而圣明的君主不加责罚，宰相不加斥退，这难道不是侥幸吗？一动就遭诽谤，名声也跟着来。被弃置闲散，是分内应得的。至于计较财物的有无，谋算品级的高低，忘记自己的分量是否相称，指责前人的缺点，这就如同责问工匠不用小木桩做柱子，讥讽医师用昌蒲延年，想让他用猪苓一样。」"],
    [115, "guwen-gwj-181", "", "圬之为技贱且劳者也有业之其色若自得者听其言约而尽问之王其姓承福其名世为京兆长安农夫天宝之乱发人为兵持弓矢十三年有官勋弃之来归丧其土田手镘衣食馀三十年舍于市之主人而归其屋食之当焉视时屋食之贵贱而上下其圬之佣以偿之有馀则以与道路之废疾饿者焉又曰「粟稼而生者也若布与帛必蚕绩而后成者也其他所以养生之具皆待人力而后完也吾皆赖之然人不可遍为宜乎各致其能以相生也故君者理我所以生者也而百官者承君之化者也任有大小惟其所能若器皿焉食焉而怠其事必有天殃故吾不敢一日舍镘以嬉夫镘易能可力焉又诚有功取其直虽劳无愧吾心安焉夫力易强而有功也心难强而有智也用力者使于人用心者使人亦其宜也吾特择其易为而无愧者取焉嘻吾操镘以入富贵之家有年矣有一至者焉又往过之则为墟矣有再至三至者焉而往过之则为墟矣问之其邻或曰噫刑戮也或曰身既死而其子孙不能有也或曰死而归之官也吾以是观之非所谓食焉怠其事而得天殃者邪非强心以智而不足不择其才之称否而冒之者邪非多行可愧知其不可而强为之者邪将富贵难守薄功而厚飨之者邪抑丰悴有时一去一来而不可常者邪吾之心悯焉是故择其力之可能者行焉乐富贵而悲贫贱我岂异于人哉」又曰「功大者其所以自奉也博妻与子皆养于我者也吾能薄而功小不有之可也又吾所谓劳力者若立吾家而力不足则心又劳也一身而二任焉虽圣者不可为也」愈始闻而惑之又从而思之盖贤者也盖所谓独善其身者也然吾有讥焉谓其自为也过多其为人也过少其学杨朱之道者邪杨之道不肯拔我一毛而利天下而夫人以有家为劳心不肯一动其心以畜其妻子其肯劳其心以为人乎哉虽然其贤于世之患不得之而患失之者以济其生之欲贪邪而亡道以丧其身者其亦远矣又其言有可以警余者故余为之传而自鉴焉", "粉刷墙壁作为一种技艺，是卑贱而且劳苦的。有从事这种职业的，他的神色却好像很自得。听他的话，简要而透彻。问他，姓王，名承福，世代是京兆长安的农夫。天宝之乱时，征发百姓当兵。他拿着弓箭十三年，有官职勋位，却抛弃了回家。丧失了土地，靠手持抹子度日，过了三十年。住在街市的主人家里，而付给他房租饭钱。看当时房租饭钱的贵贱，来增减他粉刷的工钱以偿付；有剩余，就送给路上的残废疾病饥饿的人。\n他又说：「粟米，是耕种才生出来的；至于布和帛，一定得养蚕纺织才能做成；其他用来养生的东西，都要靠人力才能完备。我都依赖它们。然而人不可能什么都做，应该各自尽自己的能力来互相养活。所以君主，是治理我们赖以生存的事的人；而百官，是秉承君主教化的人。责任有大小，只看他的能力，如同器皿一样。吃人家的饭却懈怠人家的事，一定有天降的灾祸，所以我不敢一天放下抹子去嬉戏。那抹子容易学会，可以靠力气，又确实有功效，取它的工钱，虽然劳苦却无愧，我心里安稳。力气容易勉强而有功效，心思难以勉强而有智慧。用力的被人役使，用心的役使人，也是应该的。我特意选择那容易做又无愧的来做。\n唉！我拿着抹子出入富贵人家有年头了。有去过一次的，再经过那里，就成了废墟；有去过两次三次的，再经过那里，也都成了废墟。问他们的邻居，有的说：唉！被刑罚杀掉了。有的说：本人已经死了，而他的子孙不能保有。有的说：死了以后归公了。我由此看来，不就是所谓吃了人家的饭却懈怠人家的事而遭天降灾祸的吗？不是勉强用心智而才智不足、不选择称不称自己的才能而冒任的吗？不是多做可愧的事、知道不可以却勉强去做的吗？还是富贵难以守住、功劳薄而享受厚呢？或者是兴盛憔悴各有定时、一去一来而不恒定呢？我心里怜悯他们，因此选择我力所能及的事来做。喜欢富贵而悲叹贫贱，我难道与别人不同吗？」\n他又说：「功劳大的，他用来供养自己的也多。妻子和儿女，都是靠我养的，我能力薄功劳小，没有他们也可以。再说我是所谓劳力的人，如果成了家而力气不足，那么心又要操劳。一个人担两份责任，即使是圣人也不能做到。」\n我起初听了感到疑惑，接着又思考，这大概是位贤者，大概是所谓独善其身的人。然而我有批评：说他为自己太多，为别人太少。他大概是学杨朱之道的人吧？杨朱之道，不肯拔自己一根毛而有利于天下。而这个人把有家看作劳心，不肯动一点心去养活妻儿，他肯劳心为别人吗？虽然如此，他比世上那些患得患失、用来满足自己生存的欲望、贪婪邪恶而不顾道义、以致丧失自身的人贤明多了。再说他的话，有可以警惕我的，所以我为他作传而用来鉴戒自己。"],
    [116, "guwen-gwj-182", "", "愈与李贺书劝贺举进士贺举进士有名与贺争名者毁之曰「贺父名晋肃贺不举进士为是劝之举者为非」听者不察也和而唱之同然一辞皇甫湜曰「若不明白子与贺且得罪」愈曰「然」律曰「二名不偏讳」释之者曰「谓若言『徵』不称『在』言『在』不称『徵』是也」律曰「不讳嫌名」释之者曰「谓若『禹』与『雨』『邱』与『蓲』之类是也」今贺父名晋肃贺举进士为犯二名律乎为犯嫌名律乎父名晋肃子不得举进士若父名仁子不得为人乎夫讳始于何时作法制以教天下者非周公孔子欤周公作诗不讳孔子不偏讳二名春秋不讥不讳嫌名康王钊之孙实为昭王曾参之父名晳曾子不讳昔周之时有骐期汉之时有杜度此其子宜如何讳将讳其嫌遂讳其姓乎将不讳其嫌者乎汉讳武帝名彻为通不闻又讳车辙之辙为某字也讳吕后名雉为野鸡不闻又讳治天下之治为某字也今上章及诏不闻讳浒势秉机也惟宦官宫妾乃不敢言谕及机以为触犯士君子言语行事宜何所法守也今考之于经质之于律稽之以国家之典贺举进士为可邪为不可邪凡事父母得如曾参可以无讥矣作人得如周公孔子亦可以止矣今世之士不务行曾参周公孔子之行而讳亲之名则务胜于曾参周公孔子亦见其惑也夫周公孔子曾参卒不可胜胜周公孔子曾参乃比于宦者宫妾则是宦者宫妾之孝于其亲贤于周公孔子曾参者邪", "我给李贺写信，劝李贺考进士。李贺考进士有了名声，与李贺争名的人诋毁他，说：「李贺的父亲名叫晋肃，李贺不考进士才对，劝他考的人不对。」听的人不加审察，随声附和，异口同声。皇甫湜说：「如果不辩白清楚，您和李贺都将获罪。」我说：「是的。」\n律令说：「两个字的名字不单个避讳。」解释的人说：「是说像说『徵』不说『在』，说『在』不说『徵』这样。」律令说：「不避讳读音相近的字。」解释的人说：「是说像『禹』与『雨』、『邱』与『蓲』这类。」如今李贺的父亲名叫晋肃，李贺考进士，是犯了两个字名字的律令呢？还是犯了读音相近字的律令呢？父亲名叫晋肃，儿子就不能考进士；如果父亲名叫仁，儿子就不能做人了吗？\n避讳从什么时候开始？制定礼法来教化天下的，不是周公孔子吗？周公作诗不避讳，孔子对两个字的名字不单个避讳，《春秋》不讥刺不避讳读音相近的字。康王钊的孙子，就是昭王。曾参的父亲名叫晳，曾子不避讳「昔」。周代有骐期，汉代有杜度，他们的儿子应该怎样避讳？是要避讳读音相近的字，就连姓也避讳吗？还是不避讳读音相近的字呢？汉代避讳武帝的名「彻」改为「通」，没听说又避讳车辙的「辙」为某字；避讳吕后的名「雉」改为「野鸡」，没听说又避讳治天下的「治」为某字。如今上奏章和诏书，没听说避讳「浒」「势」「秉」「机」，只有宦官宫女，才不敢说「谕」和「机」，认为触犯。\n士君子的言语行事，应该效法遵守什么呢？如今考证经典，质证律令，考核国家的典章，李贺考进士是可以呢？还是不可以呢？\n凡是事奉父母，能像曾参，就可以不受讥议了；做人能像周公孔子，也就可以止步了。如今的士人，不致力于践行曾参周公孔子的德行，而避讳父母的名字，却务求胜过曾参周公孔子，也可见他们的糊涂了！周公孔子曾参终究不能胜过，要胜过周公孔子曾参，就与宦官宫女相比，那么宦官宫女对父母的孝，比周公孔子曾参还贤明吗？"],
    [117, "guwen-gwj-183", "", "或问谏议大夫阳城于愈「可以为有道之士乎哉学广而闻多不求闻于人也行古人之道居于晋之鄙晋之鄙人薰其德而善良者几千人大臣闻而荐之天子以为谏议大夫人皆以为华阳子不色喜居于位五年矣视其德如在野彼岂以富贵移易其心哉」愈应之曰「是易所谓恒其德贞而夫子凶者也恶得为有道之士乎哉在易蛊之上九云『不事王侯高尚其事』蹇之六二则曰『王臣蹇蹇匪躬之故』夫亦以所居之时不一而所蹈之德不同也若蛊之上九居无用之地而致匪躬之节以蹇之六二在王臣之位而高不事之心则冒进之患生旷官之刺兴志不可则而尤不终无也今阳子在位不为不久矣闻天下之得失不为不熟矣天子待之不为不加矣而未尝一言及于政视政之得失若越人视秦人之肥瘠忽焉不加喜戚于其心问其官则曰谏议也问其禄则曰下大夫之秩秩也问其政则曰我不知也有道之士固如是乎哉且吾闻之有官守者不得其职则去有言责者不得其言则去今阳子以为得其言乎哉得其言而不言与不得其言而不去无一可者也阳子将为禄仕乎古之人有云仕不为贫而有时乎为贫谓禄仕者也宜乎辞尊而居卑辞富而居贫若抱关击柝者可也盖孔子尝为委吏矣尝为乘田矣亦不敢旷其职必曰会计当而已矣必曰牛羊遂而已矣若阳子之秩禄不为卑且贫章章明矣而如此其可乎哉」或曰「否非若此也夫阳子恶讪上者恶为人臣招其君之过而以为名者故虽谏且议使人不得而知焉书曰『尔有嘉谋嘉猷则入告尔后于内尔乃顺之于外曰斯谋斯猷惟我后之德』夫阳子之用心亦若此者」愈应之曰「若阳子之用心如此滋所谓惑者矣入则谏其君出不使人知者大臣宰相者之事非阳子之所宜行也夫阳子本以布衣隐于蓬蒿之下主上嘉其行谊擢在此位官以谏为名诚宜有以奉其职使四方后代知朝廷有直言骨鲠之臣天子有不僭赏从谏如流之美庶岩穴之士闻而慕之束带结发愿进于阙下而伸其辞说致吾君于尧舜熙鸿号于无穷也若书所谓则大臣宰相之事非阳子之所宜行也且阳子之心将使君人者恶闻其过乎是启之也」或曰「阳子之不求闻而人闻之不求用而君用之不得已而起守其道而不变何子过之深也」愈曰「自古圣人贤士皆非有求于闻用也闵其时之不平人之不乂得其道不敢独善其身而必以兼济天下也孜孜矻矻死而后已故禹过家门不入孔席不暇暖而墨突不得黔彼二圣一贤者岂不知自安佚之为乐哉诚畏天命而悲人穷也夫天授人以贤圣才能岂使自有余而已诚欲以补其不足者也耳目之于身也耳司闻而目司见听其是非视其险易然后身得安焉圣贤者时人之耳目也时人者圣贤之身也且阳子之不贤则将役于贤以奉其上矣若果贤则固畏天命而闵人穷也恶得以自暇逸乎哉」或曰「吾闻君子不欲加诸人而恶讦以为直者若吾子之论直则直矣无乃伤于德而费于辞乎好尽言以招人过国武子之所以见杀于齐也吾子其亦闻乎」愈曰「君子居其位则思死其官未得位则思修其辞以明其道我将以明道也非以为直而加人也且国武子不能得善人而好尽言于乱国是以见杀传曰『惟善人能受尽言』谓其闻而能改之也子告我曰阳子可以为有道之士也今虽不能及已阳子将不得为善人乎哉」", "有人问我关于谏议大夫阳城：「他可以算是有道之士吗？学问广博而见闻多，不求被人知道。践行古人的道，住在晋地边鄙。晋地边鄙的人，受他德行熏陶而变得善良的有近千人。大臣听说后推荐他，天子让他做谏议大夫。人们都认为荣耀，阳子脸上却没有喜色。在位五年了，看他的德行，还像在民间时一样，他难道会因富贵而改变心志吗？」\n我回答说：「这就是《易经》所说的恒守其德、贞固不移，而夫子认为有凶险的人，怎么能算有道之士呢？《易经·蛊》的上九说：『不事奉王侯，以自己所做的事为高尚。』《蹇》的六二则说：『王臣艰难忠贞，不是为了自身。』这也是因为所处的时势不同，而所践行的德也不同。如果《蛊》的上九，处在无所任用的地位，却表现出奋不顾身的节操；以《蹇》的六二，处在王臣的地位，却崇尚不事王侯的心志，那么冒进求官的祸患就产生，荒废职守的讥刺就兴起。心志不可效法，而过失终究不能没有。如今阳子在位，不算不久了；了解天下的得失，不算不熟了；天子对待他，不算不优厚了。却不曾有一句话涉及政事。看待政事的得失，像越人看待秦人的胖瘦，漠不关心，心里没有喜悦或忧伤。问他的官，就说是谏议；问他的俸禄，就说是下大夫的品级；问他的政事，就说我不知道。有道之士，原来是这样吗？况且我听说：有官职的人，不能尽其职就离开；有进言之责的人，不能尽言就离开。如今阳子认为能尽言吗？能尽言却不言，与不能尽言却不离开，两者没有一样是可以的。阳子是为了俸禄做官吗？古人说过：做官不是为贫穷，而有时是为贫穷。说的是为俸禄做官的人。那就应该辞尊居卑，辞富居贫，像守门打更的人那样才行。孔子曾做过管仓库的小吏，曾做过管牛羊的小吏，也不敢荒废职守，一定要说账目清楚才行，一定要说牛羊肥壮才行。像阳子这样的品级俸禄，不算卑下贫穷，非常明白，却这样做，可以吗？」\n有人说：「不对，不是这样。阳子厌恶讥刺君上的人，厌恶身为臣子却张扬君主的过错来求名的人。所以虽然进谏论议，却使人不能知道。《尚书》说：『你有好的谋略好的办法，就进去在宫内告诉你的君主，你在外面便顺从，说这些谋略这些办法，都是我们君主的德行。』阳子的用心，也像这样。」\n我回答说：「如果阳子的用心是这样，那就更是所谓糊涂了。进去劝谏君主，出来不让人知道，这是大臣宰相的事，不是阳子所应做的。阳子本来是平民隐居民间，主上赞赏他的品行，提拔到这个位子，官职以谏为名，确实应该有以尽职，使四方后代知道朝廷有直言刚正的臣子，天子有不滥赏、从谏如流的美德。或许山野之士，听说后仰慕他，束带结发，愿意到朝廷来陈述自己的主张，使我们的君主成为尧舜，使宏大的名号光照无穷。至于《尚书》所说的，那是大臣宰相的事，不是阳子所应做的。再说阳子的心思，将会使君主厌恶听到自己的过错吗？这是诱导啊。」\n有人说：「阳子不求被知道而人们知道他，不求被任用而君主任用他，不得已才出仕，守着自己的道而不改变，您为什么责备得这么深呢？」\n我说：「自古以来的圣人贤士，都不是有求于被知道被任用。他们怜悯时世不太平、百姓不安定，得到道，不敢独善其身，而一定要兼济天下。勤勤恳恳，到死才止。所以禹经过家门不进去，孔子连坐席都来不及坐暖，墨子连烟囱都来不及熏黑。那两位圣人一位贤人，难道不知道自身安逸是快乐吗？实在是敬畏天命而悲悯百姓困穷。上天把贤圣才能授给人，难道是让他自己有余而已，实在是想要他用来补别人的不足。耳目对于身体，耳管听而目管看，听它的对错，看它的安危，然后身体才能安宁。圣贤，是时人的耳目；时人，是圣贤的身体。再说阳子如果不贤，就将被贤者役使来侍奉他的君主了；如果真的贤，那就本该敬畏天命而怜悯百姓困穷。怎么能自己偷闲安逸呢？」\n有人说：「我听说君子不想凌驾于别人之上，厌恶揭发别人来显示自己正直。像您这样的议论，直是直了，恐怕伤害德行又浪费言辞吧？喜好畅所欲言而招致别人过错，是国武子在齐国被杀的原因。您大概也听说过吧？」\n我说：「君子处在那个位子，就要想到为职守而死；没有得到位子，就要想到修饰自己的言辞来阐明道。我是要用它阐明道，不是用它显示正直来凌驾别人。再说国武子不能得到善人，却喜欢在乱国畅所欲言，所以被杀。《传》说：『只有善人能接受尽言。』是说听到后能改正。您告诉我：阳子可以算有道之士。如今虽然还赶不上，阳子难道就不能做善人吗？」"],
    [118, "guwen-gwj-184", "", "二月十六日前乡贡进士韩愈谨再拜言相公阁下向上书及所著文后待命凡十有九日不得命恐惧不敢逃遁不知所为乃复敢自纳于不测之诛以求毕其说而请命于左右愈闻之蹈水火者之求免于人也不惟其父兄子弟之慈爱然后呼而望之也将有介于其侧者虽其所憎怨苟不至乎欲其死者则将大其声疾呼而望其仁之也彼介于其侧者闻其声而见其事不惟其父兄子弟之慈爱然后往而全之也虽有所憎怨苟不至乎欲其死者则将狂奔尽气濡手足焦毛发救之而不辞也若是者何哉其势诚急而其情诚可悲也愈之强学力行有年矣愚不惟道之险夷行且不息以蹈于穷饿之水火其既危且亟矣大其声而疾呼矣阁下其亦闻而见之矣其将往而全之欤抑将安而不救欤有来言于阁下者曰有观溺于水而爇于火者有可救之道而终莫之救也阁下且以为仁人乎哉不然若愈者亦君子之所宜动心者也或谓愈子言则然矣宰相则知子矣如时不可何愈窃谓之不知言者诚其材能不足当吾贤相之举耳若所谓时者固在上位者之为耳非天之所为也前五六年时宰相荐闻尚有自布衣蒙抽擢者与今岂异时哉且今节度观察使及防御营田诸小使等尚得自举判官无间于已仕未仕者况在宰相吾君所尊敬者而曰不可乎古之进人者或取于盗或举于管库今布衣虽贱犹足以方于此情隘辞蹙不知所裁亦惟少垂怜焉愈再拜", "二月十六日，前乡贡进士韩愈，恭敬地再拜进言宰相阁下：\n先前呈上书信和所写的文章，此后等待任命共十九天，没有得到回复。我恐惧而不敢逃避，不知该怎么办。于是又敢把自己交给不可预测的责罚，来求得把话说完，向您请示。\n我听说：遭遇水火的人向人求救，不只是因为父兄子弟的慈爱，才呼喊指望他们。只要有在旁边的人，纵然是自己憎恶怨恨的人，只要不至于想让自己死的，就会大声疾呼指望他发善心。那在旁边的人，听到他的声音看到他的情形，不只是因为父兄子弟的慈爱，才去保全他。纵然有憎恶怨恨，只要不至于想让他死的，就会狂奔尽气，湿了手足，烧焦毛发，去救他而不推辞。这样是为什么呢？因为他的处境实在危急而他的情形实在可悲。\n我努力求学、勉力实行已有年头了。愚昧地不顾道的险夷，前行而不停止，以致陷于穷困饥饿的水火之中，既危险又急迫了，正大声疾呼了。阁下大概也听到见到了吧，是打算去保全我呢？还是安然不救呢？有人来对阁下说：有人看到溺水被烧的人，有可以救援的办法，却终究不去救，阁下会认为他是仁人吗？不是这样的话，像我这样的人，也是君子所应该动心的。\n有人对我说：你的话是对了，宰相也了解你了，可是时机不允许怎么办？我私下认为这是不懂话的人。如果真是他的才能不足以承当我贤相的举荐，那就算了。至于所谓时机，本来就是在上位的人造成的，不是上天造成的。前五六年时，宰相荐举，还有从平民被提拔的，与现在难道时机不同吗？况且如今的节度使、观察使，以及防御、营田等小使，尚且能自己举荐判官，不论已做官未做官；何况宰相，是我们君主所尊敬的人，却说不行吗？古代进用人才的，有的从盗贼中取用，有的从管仓库的人中举荐，如今平民虽然卑贱，还足以比得上这些。心情窘迫言辞急迫，不知如何裁度，只希望稍微垂怜。韩愈再拜。"],
    [119, "guwen-gwj-185", "", "三月十六日前乡贡进士韩愈谨再拜言相公阁下愈闻周公之为辅相其急于见贤也方一食三吐其哺方一沐三握其发天下之贤才皆已举用奸邪谗佞欺负之徒皆已除去四海皆已无虞九夷八蛮之在荒服之外者皆已宾贡天灾时变昆虫草木之妖皆已销息天下之所谓礼乐刑政教化之具皆已修理风俗皆已敦厚动植之物风雨霜露之所沾被者皆已得宜休征嘉瑞麟凤龟龙之属皆已备至而周公以圣人之才凭叔父之亲其所辅理承化之功又尽章章如是其所求进见之士岂复有贤于周公者哉不惟不贤于周公而已岂复有贤于时百执事者哉岂复有所计议能补于周公之化者哉然而周公求之如此其急惟恐耳目有所不闻见思虑有所未及以负成王托周公之意不得于天下之心如周公之心设使其时辅理承化之功未尽章章如是而非圣人之才而无叔父之亲则将不暇食与沐矣岂特吐哺握发为勤而止哉维其如是故于今颂成王之德而称周公之功不衰今阁下为辅相亦近耳天下之贤才岂尽举用奸邪谗佞欺负之徒岂尽除去四海岂尽无虞九夷八蛮之在荒服之外者岂尽宾贡天灾时变昆虫草木之妖岂尽销息天下之所谓礼乐刑政教化之具岂尽修理风俗岂尽敦厚动植之物风雨霜露之所沾被者岂尽得宜休征嘉瑞麟凤龟龙之属岂尽备至其所求进见之士虽不足以希望盛德至比于百执事岂尽出其下哉其所称说岂尽无所补哉今虽不能如周公吐哺握发亦宜引而进之察其所以而去就之不宜默默而已也愈之待命四十馀日矣书再上而志不得通足三及门而阍人辞焉惟其昏愚不知逃遁故复有周公之说焉阁下其亦察之古之士三月不仕则相吊故出疆必载质然所以重于自进者以其于周不可则去之鲁于鲁不可则去之齐于齐不可则去之宋之郑之秦之楚也今天下一君四海一国舍乎此则夷狄矣去父母之邦矣故士之行道者不得于朝则山林而已矣山林者士之所独善自养而不忧天下者之所能安也如有忧天下之心则不能矣故愈每自进而不知愧焉书亟上足数及门而不知止焉宁独如此而已惴惴焉惟不得出大贤之门下是惧亦惟少垂察焉渎冒威尊惶恐无已愈再拜", "三月十六日，前乡贡进士韩愈，恭敬地再拜进言宰相阁下：\n我听说周公做辅相时，他急于见到贤才，正在吃饭就三次吐出口中的食物，正在洗头就三次握住头发。天下的贤才，都已举用；奸邪谗佞欺侮负心的人，都已除去；四海都已无忧；在荒服之外的九夷八蛮，都已宾服纳贡；天灾时变、昆虫草木的妖异，都已销声息迹；天下所谓礼乐刑政教化的措施，都已整治修明；风俗都已敦厚；动植物、风雨霜露所沾润的，都已得宜；吉祥的征兆、麒麟凤凰龟龙之类，都已齐备到来。而周公以圣人的才能，凭借叔父的亲近，他所辅佐治理、承受教化的功绩，又都是这样明显。他所求进见的人士，难道还有比周公更贤的吗？不只是不比周公更贤而已，难道还有比当时百官更贤的吗？难道还有所谋划议论、能补益周公教化的吗？然而周公求贤这样急切，只怕耳目有听不到看不到的，思虑有想不到的，以致辜负成王托付周公的心意，不能得到天下人的心。像周公的心，假使当时辅佐治理、承受教化的功绩，并不都这样明显，而且没有圣人的才能，又没有叔父的亲近，那么将会连吃饭洗头都来不及，难道只是吐哺握发算勤勉而已吗？正因如此，所以至今颂扬成王的德行，称道周公的功绩而不衰。\n如今阁下做辅相也差不多。天下的贤才，难道都举用了？奸邪谗佞欺侮负心的人，难道都除去了？四海难道都无忧了？在荒服之外的九夷八蛮，难道都宾服纳贡了？天灾时变、昆虫草木的妖异，难道都销声息迹了？天下所谓礼乐刑政教化的措施，难道都整治修明了？风俗难道都敦厚了？动植物、风雨霜露所沾润的，难道都得宜了？吉祥的征兆、麒麟凤凰龟龙之类，难道都齐备到来了？他所求进见的人士，虽然不足以期望盛德，至于与百官相比，难道都出于他们之下吗？他们所陈述的，难道都无所补益吗？如今即使不能像周公那样吐哺握发，也应该引进他们，考察他们的情况而决定去留，不应该默默而已。\n我等待任命，已经四十多天了。书信两次呈上，而心志不能通达。脚三次到门前，而守门人推辞。只因我昏昧愚钝，不知逃避，所以又有关于周公的一番议论。阁下大概也会明察。古代的士人，三个月不做官就互相慰问，所以离开国境一定要带上见面礼。然而他们之所以看重自我推荐，是因为在周不行，就离开到鲁；在鲁不行，就离开到齐；在齐不行，就离开到宋、到郑、到秦、到楚。如今天下只有一个君主，四海只有一个国家，舍弃这里就是夷狄了，就是离开父母之邦了。所以士人中奉行道义的，不能在朝廷得志，就只好退居山林而已。山林，是士人独善自养、不忧天下的人所能安处的。如果有忧天下的心，就不能了。所以我常常自我推荐而不觉惭愧，书信屡次呈上，脚多次到门前，而不知停止。难道只是这样而已，还惴惴不安只怕不能出自大贤的门下。也希望稍微垂察。冒犯威严，惶恐不已。韩愈再拜。"],
    [120, "guwen-gwj-186", "", "七月三日将仕郎守国子四门博士韩愈谨奉书尚书阁下士之能享大名显当世者莫不有先达之士负天下之望者为之前焉士之能垂休光照后世者亦莫不有后进之士负天下之望者为之后焉莫为之前虽美而不彰莫为之后虽盛而不传是二人者未始不相须也然而千百载乃一相遇焉岂上之人无可援下之人无可推欤何其相须之殷而相遇之疏也其故在下之人负其能不肯谄其上上之人负其位不肯顾其下故高材多戚戚之穷盛位无赫赫之光是二人者之所为皆过也未尝干之不可谓上无其人未尝求之不可谓下无其人愈之诵此言久矣未尝敢以闻于人侧闻阁下抱不世之才特立而独行道方而事实卷舒不随乎时文武唯其所用岂愈所谓其人哉抑未闻后进之士有遇知于左右获礼于门下者岂求之而未得邪将志存乎立功而事专乎报主虽遇其人未暇礼邪何其宜闻而久不闻也愈虽不材其自处不敢后于恒人阁下将求之而未得欤古人有言请自隗始愈今者惟朝夕刍米仆赁之资是急不过费阁下一朝之享而足也如曰吾志存乎立功而事专乎报主虽遇其人未暇礼焉则非愈之所敢知也世之龌龊者既不足以语之磊落奇伟之人又不能听焉则信乎命之穷也谨献旧所为文一十八首如赐览观亦足以知其志之所存愈恐惧再拜", "七月三日，将仕郎、守国子四门博士韩愈，恭敬地呈书信给尚书阁下：\n士人能够享有大名、显扬当世的，无不是有先达之士、背负天下声望的人做他的前导；士人能够留下美好的光辉、照耀后世的，也无不是有后进之士、背负天下声望的人做他的后继。没有前导，虽然美好也不显扬；没有后继，虽然盛大也不流传。这两种人，未曾不互相等待。然而千百年才相遇一次。难道是上位的人没有可以援引的，下位的人没有可以推举的吗？为什么他们互相等待如此殷切而相遇如此稀少呢？原因在于下位的人自负其能不肯谄媚上位的人，上位的人自负其位不肯顾念下位的人。所以高才的人多忧愁困穷，高位的人没有显赫的光辉。这两种人的作为都有过错。不曾去求取，不能说上位没有那样的人；不曾去寻求，不能说下位没有那样的人。我念这些话很久了，不曾敢对人说。\n我听说阁下怀有不世之才，特立独行，道义方正而行事切实，进退不随世俗，文武唯其所用，难道就是我所说的人吗？可是没有听说后进之士，有被您赏识、在门下受到礼遇的，难道是寻求而没有得到吗？还是志向在于立功，而专事于报答君主，虽然遇到这样的人，也没有闲暇礼遇呢？为什么本该听到却久久听不到呢？\n我虽然没有才能，但自我期许不敢落后于常人。阁下将要寻求而没有得到吗？古人说过：请从郭隗开始。我如今只急于早晚的草料米粮仆人租赁的费用，不过花费阁下一天的享用就够了。如果说我的志向在于立功，而专事于报答君主，虽然遇到这样的人，也没有闲暇礼遇，那就不是我敢知道的了。世上龌龊的人，既然不足以对他们说，磊落奇伟的人，又不能听，那么就确实是命运困穷了！恭敬地献上过去所写的文章十八首，如果承蒙观看，也足以知道我的志向所在。韩愈恐惧再拜。"],
    [121, "guwen-gwj-187", "", "愈再拜愈之获见于阁下有年矣始者亦尝辱一言之誉贫贱也衣食于奔走不得朝夕继见其后阁下位益尊伺候于门墙者日益进夫位益尊则贱者日隔伺候于门墙者日益进则爱博而情不专愈也道不加修而文日益有名夫道不加修则贤者不与文日益有名则同进者忌始之以日隔之疏加之以不专之望以不与者之心而听忌者之说由是阁下之庭无愈之迹矣去年春亦尝一进谒于左右矣温乎其容若加其新也属乎其言若闵其穷也退而喜也以告于人其后如东京取妻子又不得朝夕继见及其还也亦尝一进谒于左右矣邈乎其容若不察其愚也悄乎其言若不接其情也退而惧也不敢复进今则释然悟翻然悔曰其邈也乃所以怒其来之不继也其悄也乃所以示其意也不敏之诛无所逃避不敢遂进辄自疏其所以并献近所为复志赋以下十首为一卷卷有标轴送孟郊序一首生纸写不加装饰皆有楷字注字处急于自解而谢不能俟更写阁下取其意而略其礼可也愈恐惧再拜", "韩愈再拜：我得以见到阁下有年头了。起初也承蒙您一句赞誉。因贫贱，为衣食奔走，不能朝夕继续相见。此后，阁下的地位越来越尊贵，在门墙外等候的人越来越多。地位越尊贵，贫贱的人就一天天被隔远；等候在门墙外的人越来越多，那么爱就广博而情就不专一。我道义不加修养，而文章越来越有名。道义不加修养，贤者就不赞许；文章越来越有名，同时进用的人就嫉妒。起初因为一天天被隔远的疏远，加上爱不专一的期望，用不赞许的心，而听嫉妒者的话。因此阁下的庭院，就没有我的足迹了。\n去年春天，也曾一次进见您。面容温和，像是新加恩宠；言辞殷切，像是怜悯我困穷。我退下后很欢喜，告诉了别人。此后到东京接妻子儿女，又不能朝夕继续相见。等回来时，也曾一次进见您。面容疏远，像是不了解我的愚钝；言辞静默，像是不接我的话。我退下后很恐惧，不敢再进见。\n如今我恍然醒悟，翻然悔恨说：那疏远，正是恼怒我不继续来；那静默，正是示意他的意思。我愚钝的责罚，无处逃避。不敢径自进见，就自己陈述缘故，并献上近来所写的《复志赋》以下十首为一卷，卷有标轴。《送孟郊序》一首，写在生纸上，不加装饰，都有楷字注字的地方。急于自我解释而谢罪，不能等重新誊写。阁下取它的意思而忽略它的礼数就可以了。韩愈恐惧再拜。"],
    [122, "guwen-gwj-188", "", "月日愈再拜天池之滨大江之濆曰有怪物焉盖非常鳞凡介之品汇匹俦也其得水变化风雨上下于天不难也其不及水盖寻常尺寸之间耳无高山大陵旷途绝险为之关隔也然其穷涸不能自致乎水为獱獭之笑者盖十八九矣如有力者哀其穷而运转之盖一举手一投足之劳也然是物也负其异于众也且曰「烂死于沙泥吾宁乐之若俯首帖耳摇尾而乞怜者非我之志也」是以有力者遇之熟视之若无睹也其死其生固不可知也今又有有力者当其前矣聊试仰首一鸣号焉庸讵知有力者不哀其穷而忘一举手一投足之劳而转之清波乎其哀之命也其不哀之命也知其在命而且鸣号之者亦命也愈今者实有类于是是以忘其疏愚之罪而有是说焉阁下其亦怜察之", "某月某日，韩愈再拜：天池的岸边，大江的岸边，说有怪物，大概不是寻常的鳞甲之类所能相比的。它得到水，变化风雨，上下于天不难；它得不到水，就只在寻常尺寸之间罢了。并没有高山大陵旷野险途作为阻隔，然而它困于干涸，不能自己到水里去，被獱獭讥笑，大概十有八九了。如果有力量的人，怜悯它的困穷而运转它，只是举一次手投一次足的劳苦。然而这东西，仗着自己与众不同，还说：「烂死在沙泥里，我宁愿乐意；至于俯首帖耳、摇尾乞怜，不是我的心志。」所以有力量的人遇到它，仔细看却像没看见。它是死是生，本来不可知。\n如今又有有力量的人在他面前了，姑且试着仰头鸣叫一声，怎么知道有力量的人不怜悯他的困穷，而忘记举手投足的劳苦，把它转到清波中去呢？怜悯他，是命运；不怜悯他，也是命运。知道都在命运，还要鸣叫的，也是命运。\n我如今实在与此相似。因此忘记自己疏狂愚钝的罪过，而有这番议论。阁下大概也会怜悯明察！"],
    [123, "guwen-gwj-99b", "public-domain", "大凡物不得其平则鸣草木之无声风挠之鸣水之无声风荡之鸣其跃也或激之其趋也或梗之其沸也或炙之金石之无声或击之鸣人之于言也亦然有不得已者而后言其歌也有思其哭也有怀凡出乎口而为声者其皆有弗平者乎乐也者郁于中而泄于外者也择其善鸣者而假之鸣金石丝竹匏土革木八者物之善鸣者也维天之于时也亦然择其善鸣者而假之鸣是故以鸟鸣春以雷鸣夏以虫鸣秋以风鸣冬四时之相推夺其必有不得其平者乎其于人也亦然人声之精者为言文辞之于言又其精也尤择其善鸣者而假之鸣其在唐虞咎陶禹其善鸣者也而假以鸣夔弗能以文辞鸣又自假于韶以鸣夏之时五子以其歌鸣伊尹鸣殷周公鸣周凡载于诗书六艺皆鸣之善者也周之衰孔子之徒鸣之其声大而远传曰「天将以夫子为木铎」其弗信矣乎其末也庄周以其荒唐之辞鸣楚大国也其亡也以屈原鸣臧孙辰孟轲荀卿以道鸣者也杨朱墨翟管夷吾晏婴老聃申不害韩非慎到田骈邹衍尸佼孙武张仪苏秦之属皆以其术鸣秦之兴李斯鸣之汉之时司马迁相如扬雄最其善鸣者也其下魏晋氏鸣者不及于古然亦未尝绝也就其善者其声清以浮其节数以急其辞淫以哀其志弛以肆其为言也乱杂而无章将天丑其德莫之顾邪何为乎不鸣其善鸣者也唐之有天下陈子昂苏源明元结李白杜甫李观皆以其所能鸣其存而在下者孟郊东野始以其诗鸣其高出魏晋不懈而及于古其他浸淫乎汉氏矣从吾游者李翱张籍其尤也三子者之鸣信善矣抑不知天将和其声而使鸣国家之盛邪抑将穷饿其身思愁其心肠而使自鸣其不幸邪三子者之命则悬乎天矣其在上也奚以喜其在下也奚以悲东野之役于江南也有若不释然者故吾道其命于天者以解之", "大凡事物得不到它的平衡，就要发出声音：草木本来没有声音，风吹动它就响；水本来没有声音，风激荡它就响。水腾跃起来，是有什么东西激了它；水奔流起来，是有什么东西堵了它；水沸腾起来，是有什么东西烧了它。金石本来没有声音，是有什么东西敲击它才响。人对于言语也是这样：有不得已的缘故然后才说话，他歌唱是有所思念，他哭泣是有所感怀。凡是出于口而成为声音的，大概都是有不平的地方吧！\n音乐，是郁积在心中而发泄到外面的东西，它挑选那些善于发声的物体来借它们发声。金、石、丝、竹、匏、土、革、木这八类，是物体中善于发声的。上天对于四时也是这样，挑选那些善于发声的来借它们发声。所以用鸟来鸣春天，用雷来鸣夏天，用虫来鸣秋天，用风来鸣冬天。四季相互推移替代，其中必定有得不到平衡的地方吧！\n它对于人也是这样：人的声音中最精妙的是言语，而文辞比起言语，又是其中最精妙的，所以尤其要挑选那些善于表达的人来借他们表达。在唐尧、虞舜的时代，咎陶、禹是善于表达的，就借他们来表达。夔不能用文辞表达，便又借《韶》乐来表达。夏朝时，五子用他们的歌来表达。伊尹表达殷朝，周公表达周朝。凡是记载在《诗》《书》六艺里的，都是表达中的优秀者。周朝衰微时，孔子的门徒出来表达，他们的声音宏大而久远。古书上说：「上天将要把孔子当作木铎（来传道警世）。」这难道不可信吗！到了周朝末年，庄周用他荒诞恣肆的文辞来表达。楚国是大国，它灭亡时，靠屈原来表达。臧孙辰、孟轲、荀卿，是用道来表达的人。杨朱、墨翟、管夷吾、晏婴、老聃、申不害、韩非、慎到、田骈、邹衍、尸佼、孙武、张仪、苏秦这些人，都是用他们的学说来表达的。秦朝兴起，李斯出来表达。汉朝时，司马迁、司马相如、扬雄，是最善于表达的人。此后的魏、晋两朝，表达的人比不上古代，然而也未曾断绝；就其中较好的来说，他们的声音清丽而浮泛，节奏繁密而急促，辞藻放荡而悲伤，情志松弛而放纵；他们写出的言论，杂乱而没有条理。大概是上天憎恶他们的德行而不去顾念他们吧？为什么不让那些真正善于表达的人出来表达呢！\n唐朝拥有天下之后，陈子昂、苏源明、元结、李白、杜甫、李观，都用他们所擅长的来表达。其中还活着而地位低下的，孟郊（字东野）开始用他的诗来表达。他的诗超出魏、晋，继续努力不懈便可赶上古人，其余的作品也已接近汉代的水准了。跟随我学习的，以李翱、张籍最为突出。这三人的表达确实很好了，只是不知道上天将要使他们的声音和谐，让他们来歌颂国家的兴盛呢？还是将要使他们穷困饥饿、愁苦内心，让他们来表达自己的不幸呢？这三人的命运，就取决于上天了。他们身居上位有什么可欢喜的，身居下位又有什么可悲伤的！东野到江南去任职，好像有些郁结不乐的样子，所以我说一说他命运取决于上天的道理来宽解他。"],
    [124, "guwen-gwj-189", "", "太行之阳有盘谷盘谷之间泉甘而土肥草木丛茂居民鲜少或曰「谓其环两山之间故曰盘」或曰「是谷也宅幽而势阻隐者之所盘旋」友人李愿居之愿之言曰「人之称大丈夫者我知之矣利泽施于人名声昭于时坐于庙朝进退百官而佐天子出令其在外则树旗旄罗弓矢武夫前呵从者塞途供给之人各执其物夹道而疾驰喜有赏怒有刑才畯满前道古今而誉盛德入耳而不烦曲眉丰颊清声而便体秀外而惠中飘轻裾翳长袖粉白黛绿者列屋而闲居妒宠而负恃争妍而取怜大丈夫之遇知于天子用力于当世者之所为也吾非恶此而逃之是有命焉不可幸而致也穷居而野处升高而望远坐茂树以终日濯清泉以自洁采于山美可茹钓于水鲜可食起居无时惟适之安与其有誉于前孰若无毁于其后与其有乐于身孰若无忧于其心车服不维刀锯不加理乱不知黜陟不闻大丈夫不遇于时者之所为也我则行之伺候于公卿之门奔走于形势之途足将进而趑趄口将言而嗫嚅处秽污而不羞触刑辟而诛戮侥幸于万一老死而后止者其于为人贤不肖何如也」昌黎韩愈闻其言而壮之与之酒而为之歌曰「盘之中维子之宫盘之土可以稼盘之泉可濯可沿盘之阻谁争子所窈而深廓其有容缭而曲如往而复嗟盘之乐兮乐且无殃虎豹远迹兮蛟龙遁藏鬼神守护兮呵禁不祥饮且食兮寿而康无不足兮奚所望膏吾车兮秣吾马从子于盘兮终吾生以徜徉」", "太行山的南面有个盘谷。盘谷之中，泉水甘甜土地肥沃，草木丛生茂密，居民很少。有人说：「因为它是环绕在两山之间的，所以叫盘。」有人说：「这个山谷，位置幽深而地势险阻，是隐士盘桓的地方。」我的朋友李愿住在这里。\n李愿说：「人们所称的大丈夫，我知道了：把利益恩泽施给别人，名声显扬于当时。坐在朝廷上，进退百官，辅佐天子发出号令；他在外面，就树立旗帜，陈列弓箭，武士在前面喝道，随从塞满道路，供给的人各自拿着物品，夹道奔驰。高兴就有赏赐，发怒就有刑罚。才俊站满面前，谈古论今而赞誉盛德，听进耳朵也不厌烦。弯弯的眉毛丰满的面颊，清亮的声音轻盈的体态，外表秀美内里聪慧，飘着轻软的衣襟，掩着长长的衣袖，敷粉画眉的，一排排屋子闲住着，嫉妒得宠自负依靠，争相妍丽求取怜爱。这是大丈夫被天子赏识、在当世施展力气的人的作为。我不是厌恶这些而逃避它，这是有命运的，不能侥幸得到。\n困穷闲居而在野外，登高望远，坐在茂密的树下度过一天，在清泉中洗浴来清洁自己。从山上采来的，甘美可以吃；从水中钓来的，新鲜可以食。起居没有定时，只求舒适安宁。与其在此之前有声誉，哪里比得上在此之后没有诋毁；与其身体有快乐，哪里比得上心里没有忧愁。车马服饰不受束缚，刑罚刀锯不加于身，治乱不知道，贬黜升迁不听闻。这是大丈夫不遇于时的人的作为，我就这样做。\n在公卿的门前等候，在有权势的路上奔走，脚将要进却又迟疑，嘴将要说话却又嗫嚅，处在污秽之中而不羞耻，触犯刑法而被诛杀，希图万分之一的机会，到老死才停止的人，他们为人，贤与不贤怎么样呢？」\n昌黎韩愈听到他的话而认为豪壮，给他酒并为他作歌说：「盘谷之中，是你的宫室；盘谷的土地，可以耕种；盘谷的泉水，可以洗浴可以沿游；盘谷的险阻，谁来争你的住所？幽深而深远，空阔能容；缭绕而曲折，像去了又回来。可叹盘谷的快乐啊，快乐而没有祸殃；虎豹远远避开啊，蛟龙逃走隐藏；鬼神守护啊，呵斥禁止不祥。又饮又食啊长寿安康，没有不满足啊还有什么期望！给我的车轴上油啊喂饱我的马，跟着你到盘谷啊，让我终身自由徜徉。」"],
    [126, "guwen-gwj-191", "", "昔疏广受二子以年老一朝辞位而去于时公卿设供张祖道都门外车数百两道路观者多叹息泣下共言其贤汉史既传其事而后世工画者又图其迹至今照人耳目赫赫若前日事国子司业杨君巨源方以能诗训后进一旦以年满七十亦白丞相去归其乡世常说古今人不相及今杨与二疏其意岂异也予忝在公卿后遇病不能出不知杨侯去时城门外送者几人车几两马几匹道边观者亦有叹息知其为贤与否而太史氏又能张大其事为传继二疏踪迹否不落莫否见今世无工画者而画与不画固不论也然吾闻杨侯之去丞相有爱而惜之者白以为其都少尹不绝其禄又为歌诗以劝之京师之长于诗者亦属而和之又不知当时二疏之去有是事否古今人同不同未可知也中世士大夫以官为家罢则无所于归杨侯始冠举于其乡歌鹿鸣而来也今之归指其树曰「某树吾先人之所种也某水某丘吾童子时所钓游也」乡人莫不加敬诫子孙以杨侯不去其乡为法古之所谓乡先生没而可祭于社者其在斯人欤其在斯人欤", "从前疏广、疏受二人，因为年老，一朝辞去官位而离开。当时公卿摆设供帐，在都门外饯行，车子数百辆。路上观看的人，大多叹息流泪，都称道他们的贤德。汉史已经记载了这件事，而后世擅长绘画的人，又画出他们的形迹，至今照耀人的耳目，显赫得像前几天的事。\n国子司业杨巨源君，正以能诗训导后进，一旦因为年满七十，也禀告丞相离职回到家乡。世人常说古今人不能相比，如今杨君与二疏，他们的心意难道有不同吗？\n我愧居公卿之列，因生病不能出门。不知杨侯离去时，城门外送行的有多少人？车多少辆？马多少匹？路边观看的，也有叹息而知道他是贤者的吗？而太史氏又能否张大这件事，作传接续二疏的事迹呢？不至于落寞吧？如今世上没有擅长绘画的人，画与不画，本来不必论。\n然而我听说杨侯离去时，丞相有爱惜他的，禀告让他做本都少尹，不断绝他的俸禄。又作诗歌来劝勉他，京城擅长诗的人，也相属唱和。又不知当时二疏离去，有这样的事吗？古今人相同不相同，不可知。\n中世的士大夫以官为家，罢官就无处可归。杨侯刚成年，被乡里举荐，唱着《鹿鸣》而来。如今回去，指着那些树说：「某棵树，是我的先人种的；某条水某个山丘，是我童年时钓鱼游玩的地方。」乡人没有不加敬重，告诫子孙把杨侯不离开家乡作为法则。古代所谓乡先生死后可以在社中祭祀的，大概就是这样的人吧！大概就是这样的人吧！"],
    [127, "guwen-gwj-192", "", "河阳军节度御史大夫乌公为节度之三月求士于从事之贤者有荐石先生者公曰「先生何如」曰「先生居嵩邙瀍谷之间冬一裘夏一葛食朝夕饭一盂蔬一盘人与之钱则辞请与出游未尝以事免劝之仕不应坐一室左右图书与之语道理辨古今事当否论人高下事后当成败若河决下流而东注若驷马驾轻车就熟路而王良造父为之先后也若烛照数计而龟卜也」大夫曰「先生有以自老无求于人其肯为某来邪」从事曰「大夫文武忠孝求士为国不私于家方今寇聚于恒师环其疆农不耕收财粟殚亡吾所处地归输之涂治法征谋宜有所出先生仁且勇若以义请而强委重焉其何说之辞」于是撰书词具马币卜日以受使者求先生之庐而请焉先生不告于妻子不谋于朋友冠带出见客拜受书礼于门内宵则沐浴戒行李载书册问道所由告行于常所来往晨则毕至张上东门外酒三行且起有执爵而言者曰「大夫真能以义取人先生真能以道自任决去就为先生别」又酌而祝曰「凡去就出处何常惟义之归遂以为先生寿」又酌而祝曰「使大夫恒无变其初无务富其家而饥其师无甘受佞人而外敬正士无昧于谄言惟先生是听以能有成功保天子之宠命」又祝曰「使先生无图利于大夫而私便其身」先生起拜祝辞曰「敢不敬蚤夜以求从祝规」于是东都之人士咸知大夫与先生果能相与以有成也遂各为歌诗六韵遣愈为之序云", "河阳军节度使、御史大夫乌公，做节度使的第三个月，向幕僚中贤能的人征求人才。有人推荐石先生。乌公说：「先生怎么样？」回答说：「先生住在嵩山、邙山、瀍水、谷水之间，冬天一件皮衣，夏天一件葛衣，早晚吃饭，一盂饭，一盘蔬菜。给人钱，就推辞；请和他出游，从不因事推辞；劝他做官，不答应。坐在一室之中，左右都是图书。和他谈论道理，辨别古今事情的当否，评论人物的高下，事情的成败，像河水决口向下游东流；像四匹马驾着轻车走上熟路，而王良、造父为他驾驭前后；像烛光照耀、数着计算、龟甲占卜一样准确。」御史大夫说：「先生有足以自养老的，不求于人，他肯为我而来吗？」幕僚说：「大夫文武忠孝，为国家求士，不为私家。如今敌寇聚集在恒州，军队环绕它的边境，农民不能耕收，财物粮粟耗尽。我们所处的地方，是转运的通道，治理的办法征战的谋略，应该有所出。先生仁厚而勇敢，如果用道义请他而坚决委以重任，他有什么可推辞的呢？」于是撰写书信，备好马匹币帛，占卜日期以授使者，找到先生的住处去请他。\n先生不告诉妻子儿女，不与朋友商量，穿戴冠带出来见客，在门内拜受书信礼物。夜里就沐浴，准备行李，装载书册，问明路的去向，向平素来往的人告别。早晨就全都到了，在东门外设帐，酒过三巡，将要起身，有拿着酒杯说话的人说：「大夫真能以道义取人，先生真能以道义自任，决定去留。为先生送别。」又斟酒祝告说：「大凡去留进退有什么一定，只归于道义。就用这个为先生祝寿。」又斟酒祝告说：「让大夫永远不改变他的初衷，不务求自家富足而让军队饥饿，不乐意接受谄佞的人而表面敬重正直之士，不被谄媚的话所蒙蔽，只听先生的话，以能够有成就，保全天子的恩宠诏命。」又祝告说：「让先生不向大夫谋求私利，而私自便利自身。」先生起身拜谢祝辞说：「怎敢不早晚恭敬以求遵从祝规。」于是东都的人士，都知道大夫与先生果然能相互配合而有成就。于是各自作歌诗六韵，让我为它作序。"],
    [128, "guwen-gwj-193", "", "伯乐一过冀北之野而马群遂空夫冀北马多天下伯乐虽善知马安能空其群邪解之者曰吾所谓空非无马也无良马也伯乐知马遇其良辄取之群无留良焉苟无良虽谓无马不为虚语矣东都固士大夫之冀北也恃才能深藏而不市者洛之北涯曰石生其南涯曰温生大夫乌公以鈇钺镇河阳之三月以石生为才以礼为罗罗而致之幕下未数月也以温生为才于是以石生为媒以礼为罗又罗而致之幕下东都虽信多才士朝取一人焉拔其尤暮取一人焉拔其尤自居守河南尹以及百司之执事与吾辈二县之大夫政有所不通事有所可疑奚所咨而处焉士大夫之去位而巷处者谁与嬉游小子后生于何考德而问业焉缙绅之东西行过是都者无所礼于其庐若是而称曰大夫乌公一镇河阳而东都处士之庐无人焉岂不可也夫南面而听天下其所托重而恃力者惟相与将耳相为天子得人于朝廷将为天子得文武士于幕下求内外无治不可得也愈縻于兹不能自引去资二生以待老今皆为有力者夺之其何能无介然于怀邪生既至拜公于军门其为吾以前所称为天下贺以后所称为吾致私怨于尽取也留守相公首为四韵诗歌其事愈因推其意而序之", "伯乐一经过冀北的原野，马群就空了。冀北的马比天下各处都多，伯乐虽然善于识马，怎么能使马群空了呢？解释的人说：我所说的空，不是没有马，是没有好马。伯乐识马，遇到好马，就取走它，马群中没有留下好马了。如果没有好马，虽然说没有马，也不算虚话。\n东都，本来是士大夫的冀北。仗恃才能深藏而不出售的，洛水北岸有石生，南岸有温生。御史大夫乌公，带着斧钺镇守河阳的第三个月，认为石生有才，用礼作网罗，网罗来安置在幕府中。不到几个月，又认为温生有才，于是以石生为媒介，用礼作网罗，又网罗来安置在幕府中。东都虽然确实多才士，早晨取一人，选拔其中最优秀的；晚上取一人，选拔其中最优秀的。从留守、河南尹，以及各官署的执事，和我们两县的官员，政事有不通的，事情有可疑的，向谁咨询来处置呢？士大夫离职闲居在巷里的，和谁嬉游？年轻人后辈，向谁考问德行学问呢？缙绅往来经过这个都城的，没有地方到他们家中去拜访。像这样而称说：大夫乌公一镇守河阳，东都处士的家中就没有人了。难道不可以吗？\n君主南面而治理天下，他所托付重任依靠力量的，只有宰相和将帅罢了。宰相为天子在朝廷得到人才，将帅为天子在幕府得到文武士，要求内外治理不好，不可能。我牵累在这里，不能自己引退，依靠两位先生来等待年老。如今都被有力量的人夺去，我怎么能心里没有耿耿于怀呢？温生已经到了，在军门拜见乌公，请他替我把前面所说的，为天下祝贺；把后面所说的，替我表达对尽数取去的私怨。留守相公首先作四韵诗歌咏这件事，我因而推衍他的意思而作序。"],
    [129, "guwen-gwj-104", "public-domain", "年月日季父愈闻汝丧之七日乃能衔哀致诚使建中远具时羞之奠告汝十二郎之灵呜呼吾少孤及长不省所怙惟兄嫂是依中年兄殁南方吾与汝俱幼从嫂归葬河阳既又与汝就食江南零丁孤苦未尝一日相离也吾上有三兄皆不幸早世承先人后者在孙惟汝在子惟吾两世一身形单影只嫂尝抚汝指吾而言曰「韩氏两世惟此而已」汝时尤小当不复记忆吾时虽能记忆亦未知其言之悲也吾年十九始来京城其后四年而归视汝又四年吾往河阳省坟墓遇汝从嫂丧来葬又二年吾佐董丞相于汴州汝来省吾止一岁请归取其孥明年丞相薨吾去汴州汝不果来是年吾佐戎徐州使取汝者始行吾又罢去汝又不果来吾念汝从于东东亦客也不可以久图久远者莫如西归将成家而致汝呜呼孰谓汝遽去吾而殁乎吾与汝俱少年以为虽暂相别终当久相与处故舍汝而旅食京师以求斗斛之禄诚知其如此虽万乘之公相吾不以一日辍汝而就也去年孟东野往吾书与汝曰「吾年未四十而视茫茫而发苍苍而齿牙动摇念诸父与诸兄皆康强而早世如吾之衰者其能久存乎吾不可去汝不肯来恐旦暮死而汝抱无涯之戚也」孰谓少者殁而长者存强者夭而病者全乎呜呼其信然邪其梦邪其传之非其真邪信也吾兄之盛德而夭其嗣乎汝之纯明而不克蒙其泽乎少者强者而夭殁长者衰者而存全乎未可以为信也梦也传之非其真也东野之书耿兰之报何为而在吾侧也呜呼其信然矣吾兄之盛德而夭其嗣矣汝之纯明宜业其家者不克蒙其泽矣所谓天者诚难测而神者诚难明矣所谓理者不可推而寿者不可知矣虽然吾自今年来苍苍者或化而为白矣动摇者或脱而落矣毛血日益衰志气日益微几何不从汝而死也死而有知其几何离其无知悲不几时而不悲者无穷期矣汝之子始十岁吾之子始五岁少而强者不可保如此孩提者又可冀其成立邪呜呼哀哉呜呼哀哉汝去年书云「比得软脚病往往而剧」吾曰「是疾也江南之人常常有之」未始以为忧也呜呼其竟以此而殒其生乎抑别有疾而至斯乎汝之书六月十七日也东野云汝殁以六月二日耿兰之报无月日盖东野之使者不知问家人以月日如耿兰之报不知当言月日东野与吾书乃问使者使者妄称以应之耳其然乎其不然乎今吾使建中祭汝吊汝之孤与汝之乳母彼有食可守以待终丧则待终丧而取以来如不能守以终丧则遂取以来其余奴婢并令守汝丧吾力能改葬终葬汝于先人之兆然后惟其所愿呜呼汝病吾不知时汝殁吾不知日生不能相养以共居殁不能抚汝以尽哀敛不凭其棺窆不临其穴吾行负神明而使汝夭不孝不慈而不得与汝相养以生相守以死一在天之涯一在地之角生而影不与吾形相依死而魂不与吾梦相接吾实为之其又何尤彼苍者天曷其有极自今以往吾其无意于人世矣当求数顷之田于伊颍之上以待余年教吾子与汝子幸其成长吾女与汝女待其嫁如此而已呜呼言有穷而情不可终汝其知也邪其不知也邪呜呼哀哉尚飨", "某年某月某日，叔父韩愈听到你去世消息的第七天，才能含着哀痛表达诚意，派建中远道备办应时的食物祭品，告慰你十二郎的亡灵：\n唉！我幼年丧父，到长大，不知道依靠谁，只有依靠兄嫂。哥哥中年死在南方，我和你都很幼小，跟着嫂嫂把灵柩送回河阳安葬，随后又和你到江南谋生，孤苦零丁，不曾有一天分离。我上面有三个哥哥，都不幸早逝。继承先人后嗣的，在孙辈只有你，在子辈只有我，两代各一人，形单影只。嫂嫂曾经抚着你、指着我说：「韩家两代，只有这两个了！」你当时还很小，应当不再记得；我当时虽然能记得，也不知道她这话的悲伤。\n我十九岁，才来到京城。此后四年，才回去看你。又过四年，我到河阳祭扫坟墓，遇到你送嫂嫂的灵柩来安葬。又过两年，我在汴州辅佐董丞相，你来看我，住了一年，请求回去接取家眷。第二年，丞相去世，我离开汴州，你没有能来。这一年，我在徐州辅佐军务，派去接你的人刚出发，我又被免职离开，你又没有能来。我想到你跟随我在东边，东边也是客居，不能长久。作长远的打算，不如回西边，将安好家再接你来。唉！谁料到你竟突然离开我而死呢！我和你都是少年，以为虽然暂时分别，终究会长久相处，所以我离开你而在京城谋生，以求微薄的俸禄。如果知道会这样，即使有万乘之国的公卿宰相之位，我也不会因此离开你一天而去就任。\n去年，孟东野去你那里，我写信给你说：「我年纪不到四十，而视力模糊，头发花白，牙齿摇动。想到各位父辈和兄长，都是健康强壮却早逝，像我这样衰弱的人，还能长久活着吗？我不能离开，你又不肯来，恐怕我早晚死去，而你要抱着无穷的悲哀。」谁料到年轻的死了而年长的活着，强壮的夭折而多病的保全呢？\n唉！是真的这样呢？是做梦呢？还是传来的消息不真实呢？如果是真的，我哥哥有盛德却使他的后嗣夭折吗？你这样纯正明达却不能蒙受他的福泽吗？年轻的强壮的夭折而死，年长的衰弱的存活保全吗？不能认为这是真的。是做梦，传来的消息不真实吧，那么东野的信、耿兰的报丧，为什么在我身边呢？唉！是真的了！我哥哥有盛德却使他的后嗣夭折了！你这样纯正明达、应该继承家业的人，却不能蒙受他的福泽了！所谓天实在难以推测，而神实在难以明白啊！所谓理不可推究，而寿命不可预知啊！\n虽然如此，我从今年以来，花白的头发有的变成全白了，摇动的牙齿有的脱落了。毛发血脉日益衰败，志气日益微弱，还能不跟着你死去多久呢。死后如果有知觉，那我们分离还能有多久；如果没有知觉，那么我的悲伤也没有多久，而不悲伤的日子就无穷无期了。\n你的儿子才十岁，我的儿子才五岁，年轻强壮的人都不能保全，这样的小孩，又怎么能期望他们成人立业呢？唉，悲哀啊！唉，悲哀啊！\n你去年写信说：「近来得了软脚病，往往发作得很厉害。」我说：「这种病，江南的人常常有。」没有把它当作忧患。唉！难道你竟因此丧命吗？还是另有疾病而到这一步呢？\n你的信，是六月十七日写的。东野说，你死于六月二日；耿兰的报丧没有月日。大概是东野的使者，不知道向家人问明月日；至于耿兰的报丧，不知道应当说明月日。东野给我写信，就问使者，使者随便说一句来应付他罢了。是这样呢？还是不是这样呢？\n如今我派建中祭奠你，慰问你的孤儿和你的乳母。他们有粮食可以守丧，等到丧期终了，就等丧期终了再接他们来；如果不能守到丧期终了，就立刻接他们来。其余奴婢，都让他们为你守丧。我如果有力量能改葬，最终把你葬在先人的墓地，然后随他们的心愿。\n唉！你生病我不知道时间，你去世我不知道日子，活着不能互相供养而共同居住，死了不能抚着你的遗体来尽哀，入殓不能凭吊你的棺木，下葬不能亲临你的墓穴。我的行为辜负了神明，而使你夭折。不孝不慈，而不能同你互相供养着生活、互相守望着死去。一个在天涯，一个在地角，活着时你的影子不能同我的形体相依，死了你的魂魄不能同我的梦相接。这实在是我造成的，又能怨谁呢！那苍苍的天，什么时候才有尽头！\n从今以后，我对人世大概没有心思了！应当在伊水、颍水边上求几顷田地，来度过余年。教导我的儿子和你的儿子，希望他们成人；抚养我的女儿和你的女儿，等到她们出嫁，这样罢了。\n唉！话有说完而情不能终止，你知道呢？还是不知道呢？唉，悲哀啊！请享用祭品吧！"],
    [131, "guwen-gwj-105", "public-domain", "子厚讳宗元七世祖庆为拓跋魏侍中封济阴公曾伯祖奭为唐宰相与褚遂良韩瑗俱得罪武后死高宗朝皇考讳镇以事母弃太常博士求为县令江南其后以不能媚权贵失御史权贵人死乃复拜侍御史号为刚直所与游皆当世名人子厚少精敏无不通达逮其父时虽少年已自成人能取进士第崭然见头角众谓柳氏有子矣其后以博学宏词搜集贤殿正字隽杰廉悍议论证据今古出入经史百子踔厉风发率常屈其座人名声大振一时皆慕与之交诸公要人争欲令出我门下交口荐誉之贞元十九年由蓝田尉拜监察御史顺宗即位拜礼部员外郎遇用事者得罪例出为刺史未至又例贬永州司马居闲益自刻苦务记览为词章泛滥停蓄为深博无涯涘而自肆于山水间元和中尝例召至京师又偕出为刺史而子厚得柳州既至叹曰「是岂不足为政邪」因其土俗为设教禁州人顺赖其俗以男女质钱约不时赎子本相侔则没为奴婢子厚与设方计悉令赎归其尤贫力不能者令书其佣足相当则使归其质观察使下其法于他州比一岁免而归者且千人衡湘以南为进士者皆以子厚为师其经承子厚口讲指画为文词者悉有法度可观其召至京师而复为刺史也中山刘梦得禹锡亦在遣中当诣播州子厚泣曰「播州非人所居而梦得亲在堂吾不忍梦得之穷无辞以白其大人且万无母子俱往理」请于朝将拜疏愿以柳易播虽重得罪死不恨遇有以梦得事白上者梦得于是改刺连州呜呼士穷乃见节义今夫平居里巷相慕悦酒食游戏相征逐诩诩强笑语以相取下握手出肺肝相示指天日涕泣誓生死不相背负真若可信一旦临小利害仅如毛发比反眼若不相识落陷阱不一引手救反挤之又下石焉者皆是也此宜禽兽夷狄所不忍为而其人自视以为得计闻子厚之风亦可以少愧矣子厚前时少年勇于为人不自贵重顾藉谓功业可立就故坐废退既退又无相知有气力得位者推挽故卒死于穷裔材不为世用道不行于时也使子厚在台省时自持其身已能如司马刺史时亦自不斥斥时有人力能举之且必复用不穷然子厚斥不久穷不极虽有出于人其文学辞章必不能自力以致必传于后如今无疑也虽使子厚得所愿为将相于一时以彼易此孰得孰失必有能辨之者子厚以元和十四年十一月八日卒年四十七以十五年七月十日归葬万年先人墓侧子厚有子男二人长曰周六始四岁季曰周七子厚卒乃生女子二人皆幼其得归葬也费皆出观察使河东裴君行立行立有节概重然诺与子厚结交子厚亦为之尽竟赖其力葬子厚于万年之墓者舅弟卢遵遵涿人性谨慎学问不厌自子厚之斥遵从而家焉逮其死不去既往葬子厚又将经纪其家庶几有始终者铭曰「是惟子厚之室既固既安以利其嗣人」", "子厚，名宗元。七世祖柳庆，做北魏的侍中，封济阴公。曾伯祖柳奭，做唐朝宰相，同褚遂良、韩瑗一起得罪武后，死在高宗朝。父亲名镇，因为要侍奉母亲而放弃太常博士，请求到江南做县令；后来因为不能讨好权贵，失掉御史之职；权贵死后，才又被任命为侍御史；以刚直著称，所交往的都是当世名人。\n子厚年少时精敏，没有不通达的。到他父亲时，他虽然年少，已经自立成人，能考取进士，崭露头角。众人都说柳氏有儿子了。此后凭博学宏词，被授集贤殿正字。他俊杰廉正剽悍，议论引证古今，出入经史诸子，议论风发，常常使在座的人折服，名声大振，一时都仰慕同他交往。那些显贵要人，争着想让他出自自己门下，交口推荐称赞他。\n贞元十九年，由蓝田尉任命为监察御史。顺宗即位，任命为礼部员外郎。遇上当权者得罪，照例被贬出为刺史。还没有到任，又照例贬为永州司马。闲居时，更加刻苦，致力于记诵阅览，写作诗文，汪洋开阔、停蓄深厚，深博无边。而自己纵情于山水之间。\n元和年间，曾照例被召到京城，又一同被贬出做刺史，而子厚得柳州。到任后，叹息说：「这里难道不足以施政吗？」按照当地风俗，为他们设立教化禁令，州人顺从依赖。当地风俗用男女作抵押借钱，约定如果不按时赎回，利息和本钱相等，就收为奴婢。子厚为他们设法，都让他们赎回。那些特别贫穷无力赎的，让记下他们的工钱，足够相抵，就使归还他们的抵押品。观察使把这个办法下达其他州，到了一年，免除奴婢而回家的将近千人。衡山湘水以南考进士的，都以子厚为师，那些经过子厚口讲指画写文章的人，都有法度可观。\n他被召到京城又再被贬为刺史时，中山刘梦得禹锡也在被贬之列，应当去播州。子厚流泪说：「播州不是人住的地方，而梦得母亲还在，我不忍心梦得的困窘，没有话向他的母亲说明，而且万无母子同往的道理。」向朝廷请求，将要上疏，愿意用柳州换播州，即使因此重得罪，死也不恨。遇上有人把梦得的事禀告皇上，梦得于是改任连州刺史。唉！士人在困窘时才显出节义。如今那些平居里巷中互相爱慕、酒食游戏互相追随、和颜悦色勉强说笑互相谦让、握手露出肺肝相示、指着天日流泪、发誓生死不相背负、真像可以信任的人；一旦面临小小的利害，仅仅像毛发那样，就翻眼像不认识。落入陷阱，不伸手救一下，反而推挤他，又往下扔石头的，到处都是。这是禽兽夷狄都不忍心做的，而那些人自己看作得计。听到子厚的风范，也可以稍微惭愧了。\n子厚从前年轻，勇于为人，不看重顾惜自己，认为功业可以立刻成就，所以因此遭贬废退。已经贬退，又没有了解他而有气力、有地位的人推举提携，所以终于死在荒远之地，才能不为当世所用，道不能行于当时。假使子厚在台省时，能自己持守，已经能像做司马、刺史时那样，也就自然不会被贬斥；被贬时，有人有力能举荐他，也必定会再被任用而不困窘。然而子厚被贬不久，困窘不到极点，虽然有过人之处，他的文学辞章，必定不能自己努力，以致必定流传后世像今天这样是无疑的。即使让子厚得偿所愿，一时做将相，用那个换这个，哪个得哪个失，必定有能辨别的人。\n子厚在元和十四年十一月八日去世，年四十七岁。在十五年七月十日，归葬于万年先人墓旁。子厚有儿子两人：长子叫周六，才四岁；幼子叫周七，子厚死后才出生。女儿两人，都还幼小。他得以归葬，费用都出自观察使河东裴行立。行立有节操，重然诺，同子厚结交，子厚也为他尽心，终于依靠他的力量。安葬子厚在万年墓地的是舅弟卢遵。卢遵，涿州人，性情谨慎，学问不厌。自从子厚被贬，卢遵跟着他把家安在那里，到他死也没有离开。既已去安葬子厚，又将经营他的家事，大概是有始有终的人。\n铭文说：「这就是子厚的墓室，既坚固又安宁，以利于他的后人。」"],
    [132, "guwen-gwj-173", "", "盖闻王者莫高于周文伯者莫高于齐桓皆待贤人而成名今天下贤者智能岂特古之人乎患在人主不交故也士奚由进今吾以天之灵贤士大夫定有天下以为一家欲其长久世世奉宗庙亡绝也贤人已与我共平之矣而不与吾共安利之可乎贤士大夫有肯从我游者吾能尊显之布告天下使明知朕意御史大夫昌下相国相国酂侯下诸侯王御史中执法下郡守其有意称明德者必身劝为之驾遣诣相国府署行义年有而弗言觉免年老癃病勿遣", "听说称王的没有高过周文王的，称霸的没有高过齐桓公的，他们都依靠贤人而成就功名。现在天下贤人的智慧和才能，难道只比得上古人吗？毛病在于君主不去结交他们，贤士从哪里进用呢？如今我凭借上天的威灵、贤士大夫的力量平定了天下，把它作为一家一姓的产业。希望它长久，世世代代奉守宗庙不断绝。贤人已经和我共同平定了天下，却不和我共同安享利益，可以吗？贤士大夫有肯跟我交往的，我能使他尊贵显达。布告天下，让大家明白我的意思。御史大夫周昌下告相国，相国酂侯萧何下告诸侯王，御史中执法下告郡守，如果有能够称合明德的人，一定要亲自劝勉，为他驾车，送到相国府，登记他的品行、仪表和年龄。有贤才却不报告的，发觉后就免职。年老体弱多病的，不要送来。"],
    [133, "guwen-gwj-174", "", "间者数年比不登又有水旱疾疫之灾朕甚忧之愚而不明未达其咎意者朕之政有所失而行有过与乃天道有不顺地利或不得人事多失和鬼神废不享与何以致此将百官之奉养或费无用之事或多与何其民食之寡乏也夫度田非益寡而计民未加益以口量地其于古犹有余而食之甚不足者其咎安在无乃百姓之从事于末以害农者蕃为酒醪以靡谷者多六畜之食焉者众与细大之义吾未能得其中其与丞相列侯吏二千石博士议之有可以佐百姓者率意远思无有所隐", "近来连年收成不好，又有水旱疾疫的灾害，我非常忧虑。我愚昧不明，没有弄清过错在哪里。猜想是我的政事有失误、行为有过错吗？还是天道有不顺、地利有得不到、人事多有失和、鬼神被废弃不受祭享呢？为什么到了这种地步？或者是百官的奉养有浪费、无用的事情太多呢？为什么百姓的粮食如此匮乏呢！\n计算田地并没有更少，统计人口也没有增加，按人口平均土地，比古代还有余，可是粮食却很不足，这过错在哪里呢？莫非是百姓从事工商末业而损害农业的人多、酿酒而浪费粮食的人多、饲养六畜而吃粮的多吗？这些大小道理，我没有能把握得当。希望和丞相、列侯、二千石的官吏、博士们商议，有可以补助百姓的办法，尽量深入地思考，不要有所隐瞒。"],
    [134, "guwen-gwj-175", "", "雕文刻镂伤农事者也锦绣纂组害女红者也农事伤则饥之本也女红害则寒之原也夫饥寒并至而能无为非者寡矣朕亲耕后亲桑以奉宗庙粢盛祭服为天下先不受献减太官省繇赋欲天下务农蚕素有畜积以备灾害强毋攘弱众毋暴寡老耆以寿终幼孤得遂长今岁或不登民食颇寡其咎安在或诈伪为吏吏以货赂为市渔夺百姓侵牟万民县丞长吏也奸法与盗盗甚无谓也其令二千石各修其职不事官职耗乱者丞相以闻请其罪布告天下使明知朕意", "雕琢刻镂，是损害农事的事；织锦刺绣编组，是损害女红的事。农事受损，是饥饿的根源；女红受损，是寒冷的根源。饥寒一齐到来，能不做坏事的人很少。我亲自耕种，皇后亲自采桑，用来供给宗庙祭祀的谷物和祭服，为天下做表率。不接受进献，减少太官的膳食，减轻徭役赋税，希望天下致力于农桑，平时有积蓄，以防备灾害。强的不侵夺弱的，人多的不欺凌人少的，老人能寿终，幼儿孤儿能长大。\n今年有的地方收成不好，百姓的粮食很少，这过错在哪里呢？或许是奸诈虚伪的人当了官吏，官吏用财货做交易，掠夺百姓，侵吞万民。县丞，是长吏，却枉法而与盗贼同盗，实在没有道理。命令二千石的官吏各自整饬自己的职守。不致力于官职事务、昏乱糊涂的，丞相上报，请求治罪。布告天下，让大家明白我的意思。"],
    [135, "guwen-gwj-176", "", "盖有非常之功必待非常之人故马或奔踶而致千里士或有负俗之累而立功名夫泛驾之马跅弛之士亦在御之而已其令州郡察吏民有茂材异等可为将相及使绝国者", "凡要有非常的功业，一定要依靠非常的人才。所以马有的狂奔踢人却能日行千里，士人有的背负世俗的牵累却能建立功名。那些不受驾驭的马、放纵不羁的士人，也在于如何驾驭罢了。命令州郡考察官吏百姓中有优秀才能、不同寻常、可以担任将相以及出使远方国家的人。"],
    [137, "guwen-gwj-78", "public-domain", "管子曰「仓廪实而知礼节」民不足而可治者自古及今未之尝闻古之人曰「一夫不耕或受之饥一女不织或受之寒」生之有时而用之亡度则物力必屈古之治天下至孅至悉也故其畜积足恃今背本而趋末食者甚众是天下之大残也淫侈之俗日日以长是天下之大贼也残贼公行莫之或止大命将泛莫之振救生之者甚少而靡之者甚多天下财产何得不蹶汉之为汉几四十年矣公私之积犹可哀痛失时不雨民且狼顾岁恶不入请卖爵子既闻耳矣安有为天下阽危者若是而上不惊者世之有饥穰天之行也禹汤被之矣即不幸有方二三千里之旱国胡以相恤卒然边境有急数千百万之众国胡以馈之兵旱相乘天下大屈有勇力者聚徒而衡击罢夫羸老易子而咬其骨政治未毕通也远方之能疑者并举而争起矣乃骇而图之岂将有及乎夫积贮者天下之大命也苟粟多而财有余何为而不成以攻则取以守则固以战则胜怀敌附远何招而不至今殴民而归之农皆著于本使天下各食其力末技游食之民转而缘南亩则畜积足而人乐其所矣可以为富安天下而直为此廪廪也窃为陛下惜之", "管仲说：「粮仓充实才知道礼节。」百姓不足而能治理好的，从古到今，不曾听说过。古人说：「一个男子不耕种，就有人因此挨饿；一个女子不织布，就有人因此受寒。」生产有时间的限制，而消费没有限度，那么物力必然枯竭。古代治理天下，极为细致周详，所以他们的积蓄足以依靠。如今背离根本而趋向末业，吃饭的人很多，这是天下的大害；奢侈的风俗一天天增长，这是天下的大贼。残贼公然横行，没有人去制止；国家命运将要倾覆，没有人去拯救。生产的人很少，而耗费的人很多，天下的财产怎么能不枯竭！\n汉朝建立以来，将近四十年了，公私的积蓄，仍然令人哀痛。误了农时不下雨，百姓就惶恐四顾；年成不好没有收成，就请求卖掉爵位、卖儿卖女，这些都已经听说了。哪有治理天下危险到这种地步而君上不惊慌的呢！\n世上有饥荒有丰收，是自然的运行，禹、汤也遭受过。倘若不幸有方圆二三千里的大旱，国家拿什么去救济？突然边境有紧急情况，数千百万的军队，国家拿什么去供给？兵灾旱灾交相侵袭，天下财力大为枯竭，有勇力的人聚众横行劫击，疲惫瘦弱的人交换孩子来啃他们的骨头。政治还没有完全通达，远方那些怀有二心的人，就会一齐起来争相作乱。到那时才惊骇地设法对付，难道还来得及吗？\n积蓄储备，是天下的大命脉。如果粮食多而财货有余，做什么不能成功？用来进攻就能夺取，用来防守就能坚固，用来作战就能取胜。使敌人归怀、远方归附，招抚谁而不来呢？如今驱使百姓回到农业，都附着于根本，使天下人各自食其力，从事末技、游荡求食的人，转而走向田间，那么积蓄就充足而百姓就安于他们的处所了。本来可以使天下富足安定，却竟然造成这样令人危惧的局面，我私下为陛下惋惜！"],
    [138, "guwen-gwj-79", "public-domain", "圣王在上而民不冻饥者非能耕而食之织而衣之也为开其资财之道也故尧禹有九年之水汤有七年之旱而国亡捐瘠者以畜积多而备先具也今海内为一土地人民之众不避汤禹加以亡天灾数年之水旱而畜积未及者何也地有遗利民有余力生谷之土未尽垦山泽之利未尽出也游食之民未尽归农也民贫则奸邪生贫生于不足不足生于不农不农则不地著不地著则离乡轻家民如鸟兽虽有高城深池严法重刑犹不能禁也夫寒之于衣不待轻暖饥之于食不待甘旨饥寒至身不顾廉耻人情一日不再食则饥终岁不制衣则寒夫腹饥不得食肤寒不得衣虽慈母不能保其子君安能以有其民哉明主知其然也故务民于农桑薄赋敛广畜积以实仓廪备水旱故民可得而有也民者在上所以牧之趋利如水走下四方亡择也夫珠玉金银饥不可食寒不可衣然而众贵之者以上用之故也其为物轻微易藏在于把握可以周海内而亡饥寒之患此令臣轻背其主而民易去其乡盗贼有所劝亡逃者得轻资也粟米布帛生于地长于时聚于力非可一日成也数石之重中人弗胜不为奸邪所利一日弗得而饥寒至是故明君贵五谷而贱金玉今农夫五口之家其服役者不下二人其能耕者不过百亩百亩之收不过百石春耕夏耘秋获冬藏伐薪樵治官府给徭役春不得避风尘夏不得避暑热秋不得避阴雨冬不得避寒冻四时之间亡日休息又私自送往迎来吊死问疾养孤长幼在其中勤苦如此尚复被水旱之灾急政暴赋赋敛不时朝令而暮改当具有者半贾而卖亡者取倍称之息于是有卖田宅鬻子孙以偿责者矣而商贾大者积贮倍息小者坐列贩卖操其奇赢日游都市乘上之急所卖必倍故其男不耕耘女不蚕织衣必文采食必粱肉亡农夫之苦有仟伯之得因其富厚交通王侯力过吏势以利相倾千里游敖冠盖相望乘坚策肥履丝曳缟此商人所以兼并农人农人所以流亡者也今法律贱商人商人已富贵矣尊农夫农夫已贫贱矣故俗之所贵主之所贱也吏之所卑法之所尊也上下相反好恶乖迕而欲国富法立不可得也方今之务莫若使民务农而已矣欲民务农在于贵粟贵粟之道在于使民以粟为赏罚今募天下入粟县官得以拜爵得以除罪如此富人有爵农民有钱粟有所渫夫能入粟以受爵皆有余者也取于有余以供上用则贫民之赋可损所谓损有余补不足令出而民利者也顺于民心所补者三一曰主用足二曰民赋少三曰劝农功今令民有车骑马一匹者复卒三人车骑者天下武备也故为复卒神农之教曰「虽有石城十仞汤池百步带甲百万而亡粟弗能守也」以是观之粟者王者大用政之本务令民入粟受爵至五大夫以上乃复一人耳此其与骑马之功相去远矣爵者上之所擅出于口而亡穷粟者民之所种生于地而不乏夫得高爵与免罪人之所甚欲也使天下人入粟于边以受爵免罪不过三岁塞下之粟必多矣", "圣明的君王在上，而百姓不挨冻受饿，并不是君王能耕种给他们吃、织布给他们穿，而是为他们开辟获取资财的途径。所以尧、禹有九年的水灾，汤有七年的旱灾，而国内没有捐弃瘦弱的人，是因为积蓄多而防备事先具备。如今天下统一，土地人民的众多不亚于汤、禹之时，加上没有连年水旱的天灾，而积蓄却赶不上，为什么呢？因为土地还有未尽的利，百姓还有余力，生长谷物的土地没有完全开垦，山林水泽的利益没有完全开发，游荡求食的人没有完全回到农业。百姓贫穷，奸邪就会产生。贫穷产生于不足，不足产生于不务农，不务农就不会附着于土地，不附着于土地就会离乡轻家，百姓像鸟兽一样，即使有高城深池、严法重刑，还是不能禁止。\n寒冷时对于衣服，不等待轻暖；饥饿时对于食物，不等待甘美；饥寒临身，就不顾廉耻。人之常情，一天不吃两顿饭就饿，一年不做衣服就冷。肚子饿了得不到食物，身上冷了得不到衣服，即使是慈母也不能保住她的儿子，君王又怎么能拥有他的百姓呢！明主知道是这样，所以使百姓致力于农桑，减轻赋税，增加积蓄，来充实粮仓，防备水旱，所以百姓可以拥有。\n百姓，在于君上如何治理他们，他们趋向利益像水往低处流，四方没有选择。珠玉金银，饿了不能吃，冷了不能穿，然而众人都珍视它们，是因为君上使用它们的缘故。它们作为物品轻微容易收藏，拿在手里，可以走遍海内而没有饥寒的忧患。这就使臣子轻易背弃他的君主，百姓轻易离开他的乡里，盗贼受到鼓励，逃亡的人得到轻便的资财。粟米布帛生长在地上，成长需要时间，聚集需要人力，不是一天可以完成的；几石的重量，中等体力的人拿不动，不被奸邪的人所贪图，但一天得不到就饥寒来临。所以明君看重五谷而轻视金玉。\n如今农夫五口之家，服役的不少于两人，能耕种的不超过百亩，百亩的收成不超过百石。春天耕种夏天除草，秋天收获冬天储藏，砍柴打草，修治官府，供给徭役；春天不能避风尘，夏天不能避暑热，秋天不能避阴雨，冬天不能避寒冻，四季之间没有一天休息；还要私自送往迎来，吊唁死者、慰问病人，抚养孤儿、养育幼儿也在其中。勤劳辛苦到这样，还要遭受水旱的灾害，急迫的政令、残暴的赋税，赋敛不按时，早上发布的命令晚上就改。当有东西的人半价卖出，没有的人借加倍的利息，于是有卖田宅、卖子孙来偿还债务的。而商人大的囤积货物、坐收加倍利息，小的设摊贩卖，操纵他们的盈余，天天在都市游走，趁着君上的急需，所卖的必定加倍。所以他们的男子不耕种，女子不养蚕织布，穿衣必定有文采，吃饭必定要细粮肉食；没有农夫的劳苦，却有千百的收入。凭借他们的富厚，结交王侯，势力超过官吏，凭借财力互相倾轧；千里遨游，冠盖相望，乘坚车、驱肥马，穿着丝鞋、拖着白绢。这就是商人兼并农人、农人因此流亡的原因。\n如今法律轻视商人，商人已经富贵了；尊重农夫，农夫已经贫贱了。所以世俗所看重的，正是君主所轻视的；官吏所轻视的，正是法律所尊重的。上下相反，好恶颠倒，而想使国家富强、法令确立，是不可能的。当今的事务，莫过于使百姓从事农业罢了。要使百姓从事农业，在于重视粮食；重视粮食的办法，在于使百姓用粮食来作为赏罚。如今招募天下人向官府交纳粮食，可以封爵，可以免罪。这样，富人有了爵位，农民有了钱，粮食得以流通。能交纳粮食而接受爵位的人，都是有剩余的人；从有剩余的人那里取得，来供给君上使用，那么贫民的赋税可以减少，这就是所谓的损有余补不足，命令发出而百姓受利。顺应民心，所补益的有三样：一是君上的用度充足，二是百姓的赋税减少，三是鼓励农功。\n如今规定百姓有车骑马一匹的，免除三人的兵役。车骑是天下的武备，所以免除兵役。神农的教导说：「即使有十仞高的石城、百步宽的沸水护城河、百万带甲的士兵，而没有粮食，也不能守住。」由此看来，粮食是王者的大用，是政事的根本。规定百姓交纳粮食接受爵位到五大夫以上，才免除一人的兵役，这与车骑的功绩相差太远了。爵位是君上所专有的，出于口而没有穷尽；粮食是百姓所种的，生长在地上而不缺乏。得到高爵和免除罪罚，是人们很想得到的。假使天下人向边塞交纳粮食，来接受爵位、免除罪罚，不过三年，边塞的粮食必定多了。"],
    [139, "guwen-gwj-80", "public-domain", "邹阳从梁孝王游阳为人有智略慷慨不苟合介于羊胜公孙诡之间胜等疾阳恶之孝王孝王怒下阳吏将杀之阳客游以谗见禽恐死而负累乃从狱中上书曰「臣闻忠无不报信不见疑臣常以为然徒虚语耳昔者荆轲慕燕丹之义白虹贯日太子畏之卫先生为秦画长平之事太白蚀昴而昭王疑之夫精变天地而信不谕两主岂不哀哉今臣尽忠竭诚毕议愿知左右不明卒从吏讯为世所疑是使荆轲卫先生复起而燕秦不悟也愿大王孰察之」「昔卞和献宝楚王刖之李斯竭忠胡亥极刑是以箕子佯狂接舆辟世恐遭此患也愿大王孰察卞和李斯之意而后楚王胡亥之听无使臣为箕子接舆所笑臣闻比干剖心子胥鸱夷臣始不信乃今知之愿大王孰察少加怜焉」「谚曰『有白头如新倾盖如故』何则知与不知也故昔樊於期逃秦之燕藉荆轲首以奉丹之事王奢去齐之魏临城自刭以却齐而存魏夫王奢樊於期非新于齐秦而故于燕魏也所以去二国死两君者行合于志而慕义无穷也是以苏秦不信于天下为燕尾生白圭战亡六城为魏取中山何则诚有以相知也苏秦相燕人恶之燕王燕王按剑而怒食以駃騠白圭显于中山人恶之于魏文侯文侯赐以夜光之璧何则两主二臣剖心析肝相信岂移于浮辞哉」「故女无美恶入宫见妒士无贤不肖入朝见嫉昔者司马喜髌脚于宋卒相中山范雎摺胁折齿于魏卒为应侯此二人者皆信必然之画捐朋党之私挟孤独之交故不能自免于嫉妒之人也是以申徒狄蹈雍之河徐衍负石入海不容于世义不苟取比周于朝以移主上之心故百里奚乞食于道路缪公委之以政宁戚饭牛车下而桓公任之以国此二人者岂素宦于朝借誉于左右然后二主用之哉感于心合于行坚如胶漆昆弟不能离岂惑于众口哉故偏听生奸独任成乱昔鲁听季孙之说逐孔子宋任子冉之计囚墨翟夫以孔墨之辩不能自免于谗谀而二国以危何则众口铄金积毁销骨也秦用戎人由余而伯中国齐用越人子臧而强威宣此二国岂系于俗牵于世系奇偏之浮辞哉公听并观垂明当世故意合则胡越为兄弟由余子臧是矣不合则骨肉为仇敌朱象管蔡是矣今人主诚能用齐秦之明后宋鲁之听则五伯不足侔而三王易为也」「是以圣王觉寤捐子之之心而不说田常之贤封比干之后修孕妇之墓故功业覆于天下何则欲善无厌也夫晋文公亲其仇强霸诸侯齐桓公用其仇而一匡天下何则慈仁殷勤诚嘉于心此不可以虚辞借也」「至夫秦用商鞅之法东弱韩魏兵强天下而卒车裂之越用大夫种之谋禽劲吴霸中国而卒诛其身是以孙叔敖三去相而不悔於陵子仲辞三公为人灌园今人主诚能去骄傲之心怀可报之意披心腹见情素堕肝胆施德厚终与之穷达无爱于士则桀之犬可使吠尧跖之客可使刺由而况因万乘之权假圣王之资者乎然则荆轲之湛七族要离之烧妻子岂足道哉」「臣闻明月之珠夜光之璧以暗投人于道路人无不按剑相眄者何则无因而至前也蟠木根柢轮囷离诡而为万乘器者以左右先为之容也故无因而至前虽出随侯之珠夜光之璧犹结怨而不见德故有人先谈则枯木朽株树功而不忘今夫天下布衣穷居之士身在贫贱虽蒙尧舜之术挟伊管之辩怀龙逢比干之意欲尽忠当世之君而素无根柢之容虽极精神欲开忠信辅人主之治则人主必有按剑相眄之迹是使布衣不得为枯木朽株之资也」「是以圣王制世御俗独化于陶钧之上而不牵乎卑辞之语不夺乎众多之口故秦皇帝任中庶子蒙嘉之言以信荆轲之说而匕首窃发周文王猎泾渭载吕尚而归以王天下秦信左右而亡周用乌集而王何则以其能越挛拘之语驰域外之议独观于昭旷之道也今人主沉于谄谀之辞牵于帷裳之制使不羁之士与牛骥同皂此鲍焦所以忿于世而不留富贵之乐也」「臣闻盛饰入朝者不以利污义砥厉名号者不以欲伤行故名号垂于后世德行昭于天下故里名胜母曾子不入邑号朝歌墨子回车今欲使天下恢廓之士诱于威重之权胁于位势之贵回面污行以事谄谀之人而求亲近于左右则士有伏死堀穴岩薮之中耳安肯有尽忠信而趋阙下者哉」书奏梁孝王孝王使人出之卒为上客", "邹阳跟随梁孝王做宾客，邹阳为人有智谋，慷慨而不苟合，处在羊胜、公孙诡之间。羊胜等人忌恨邹阳，在孝王面前说他的坏话。孝王发怒，把邹阳交给狱吏，将要杀他。邹阳客游而因谗言被擒，怕死后还背着罪名，于是从狱中上书说：\n「我听说忠诚没有不报答的，守信不会被怀疑，我常常认为是对的，原来只是空话罢了。从前荆轲仰慕燕丹的义气，白虹贯穿太阳，太子却畏惧他；卫先生为秦国筹划长平之事，太白星侵蚀昴宿，而秦昭王却怀疑他。他们的精诚感动天地而不能使两位君主明白，难道不悲哀吗！如今我尽忠竭诚，把想法说完，希望被了解，但左右的人不明白，终于被交给狱吏审讯，被世人所怀疑，这就是使荆轲、卫先生复活，而燕、秦也不会觉悟。希望大王仔细明察。\n「从前卞和献宝，楚王砍了他的脚；李斯竭尽忠心，胡亥对他施以极刑。所以箕子装疯，接舆避世，是怕遭这样的祸患。希望大王仔细明察卞和、李斯的心意，然后才听信像楚王、胡亥那样的话，不要使我被箕子、接舆所讥笑。我听说比干被剖心，伍子胥被装进皮袋沉江，我起初不信，现在才知道了。希望大王仔细明察，稍加怜悯。\n「谚语说：『有的人到白头还像新交，有的人车盖一倾就像故旧。』为什么呢？是了解与不了解。所以从前樊於期从秦国逃到燕国，把头颅借给荆轲来完成燕丹的事；王奢离开齐国到魏国，在城上自刎来逼退齐军而保全魏国。王奢、樊於期并非对齐、秦是新交而对燕、魏是旧交，他们之所以离开两国而为两君效死，是因为行为合于志向而仰慕道义无穷。所以苏秦不被天下人信任，却对燕国像尾生一样守信；白圭作战失去六城，却为魏国夺取中山。为什么呢？确实有相知的地方。苏秦做燕相，有人向燕王说他的坏话，燕王按剑发怒，却赐给他骏马；白圭在中山显赫，有人向魏文侯说他的坏话，文侯却赐给他夜光璧。为什么呢？两位君主、两位臣子，剖心析肝地互相信任，怎么会因浮言而动呢！\n「所以女子无论美丑，入宫就被嫉妒；士人无论贤与不贤，入朝就被忌恨。从前司马喜在宋国被砍去膝盖骨，终于做了中山的相；范雎在魏国被折断肋骨、打掉牙齿，终于做了应侯。这两个人，都坚信必然的谋划，抛弃朋党的私情，抱着孤独的交情，所以不能自己免除嫉妒之人的中伤。因此申徒狄跳入雍水，徐衍背着石头入海。不被世俗所容，守义不肯苟且结党于朝廷，来动摇君上的心意。所以百里奚在路上讨饭，秦穆公把政事委托给他；宁戚在车下喂牛，齐桓公把国家交给他治理。这两个人，难道是向来在朝中做官、在左右人中借来声誉，然后两位君主才任用他们的吗？是心中感动，行为相合，坚如胶漆，兄弟也不能使他们分离，怎么会受众人之言迷惑呢？所以偏听会产生奸邪，独任会酿成祸乱。从前鲁国听信季孙的话驱逐孔子，宋国采用子冉的计策囚禁墨翟。凭孔子、墨翟的辩才，尚不能自己免除谗谀的中伤，而两国因此危亡。为什么呢？众人的话能熔化金属，积累的毁谤能销蚀骨头。秦国任用戎人由余而称霸中原，齐国任用越人子臧而使威王、宣王时强盛。这两国难道是拘泥于世俗、牵制于世人、受偏颇浮辞的束缚吗？是公正地听取、全面地观察，在当世显扬明智。所以心意相合则胡越也可以成为兄弟，由余、子臧就是这样；不相合则骨肉也会成为仇敌，丹朱、象、管叔、蔡叔就是这样。如今君主如果真能用齐、秦的明察，摈弃宋、鲁的偏听，那么五霸也不值得并列，三王也容易做到了。\n「所以圣王觉悟，抛弃子之那样的心思，而不喜欢田常那样的贤能，封比干的后代，修孕妇的坟墓，所以功业覆盖天下。为什么呢？因为向善没有满足。晋文公亲近他的仇人，因而强霸诸侯；齐桓公任用他的仇人，因而一匡天下。为什么呢？因为慈仁殷勤，诚心嘉美，这不是可以用虚辞假借的。\n「至于秦国采用商鞅的法制，向东削弱韩、魏，兵力强盛于天下，而终于把商鞅车裂；越国采用大夫文种的谋略，擒获强吴，称霸中原，而终于诛杀文种本身。所以孙叔敖三次离开相位而不后悔，於陵子仲辞去三公而为人灌园。如今君主如果真能去掉骄傲之心，怀有可报答之意，披肝沥胆，袒露情意，施以厚德，始终与士人同甘共苦，对士人无所吝惜，那么桀的狗可以使它对尧吠叫，盗跖的门客可以使它去刺杀许由，何况凭借万乘的权柄、借用圣王的资望的人呢？这样，荆轲被诛灭七族、要离被烧死妻子儿女，哪里值得一提呢！\n「我听说明月珠、夜光璧，在黑暗中投给路上的人，人们没有不按剑斜看的。为什么呢？因为它们是无故来到面前的。盘曲的树根，弯曲奇异，却成为万乘之国的器物，是因为左右的人先为它修饰。所以无故来到面前，即使拿出随侯珠、夜光璧，还是会结怨而不被感激；如果有人先称扬，那么枯木朽株也能建立功劳而不被忘记。如今天下布衣穷居的士人，身处贫贱，即使身怀尧、舜的方术，握有伊尹、管仲的辩才，怀有龙逢、比干的忠心，想要尽忠当世的君主，而向来没有像树根那样被修饰的凭借，即使竭尽精神，想要开启忠信，辅佐君主的治理，那么君主必定会有按剑斜看的举动，这就使布衣之士不能成为枯木朽株那样的凭借。\n「所以圣王治理世俗，独自在陶钧之上造化，而不被卑下的言辞所牵制，不被众人的口舌所动摇。所以秦始皇听信中庶子蒙嘉的话而相信荆轲的说辞，于是匕首暗中发出；周文王在泾水、渭水边打猎，载着吕尚回去，因而统一天下。秦信任左右而亡，周任用偶然来投的人而王。为什么呢？因为他们能超越拘执的言辞，驰骋于域外的议论，独自观察于光明广阔的途径。如今君主沉溺于谄谀之辞，被帷帐内的近臣所牵制，使不受拘束的士人同牛马同槽，这就是鲍焦之所以愤恨世俗而不留恋富贵之乐的原因。\n「我听说装饰华美入朝的人不因利而污损义，砥砺名号的人不因欲而伤害品行，所以名号流传于后世，德行昭明于天下，因此里名叫『胜母』，曾子就不进去；城名叫『朝歌』，墨子便调转车头。如今想要使天下胸怀开阔的士人，被威重的权势所诱惑，被位势的贵重所胁迫，掉转面孔、污损品行，去事奉谄谀的人，而求得亲近左右，那么士人只有伏死在洞穴岩泽之中罢了，怎么肯竭尽忠信而奔赴阙下呢！」\n书信上奏梁孝王，孝王派人把他放出来，终于以他为上客。"],
    [140, "guwen-gwj-81", "public-domain", "臣闻物有同类而殊能者故力称乌获捷言庆忌勇期贲育臣之愚窃以为人诚有之兽亦宜然今陛下好陵阻险射猛兽卒然遇逸材之兽骇不存之地犯属车之清尘舆不及还辕人不暇施巧虽有乌获逢蒙之技不能用枯木朽株尽为难矣是胡越起于毂下而羌夷接轸也岂不殆哉虽万全而无患然本非天子之所宜近也且夫清道而后行中路而后驰犹时有衔橛之变而况涉乎蓬蒿驰乎丘坟前有利兽之乐而内无存变之意其为祸也不亦难矣夫轻万乘之重不以为安而乐出于万有一危之涂以为娱臣窃为陛下不取也盖明者远见于未萌而智者避危于无形祸固多藏于隐微而发于人之所忽者也故鄙谚曰「家累千金坐不垂堂」此言虽小可以喻大臣愿陛下之留意幸察", "我听说万物中有同类而能力不同的，所以论力气首称乌获，论敏捷首称庆忌，论勇敢首推孟贲、夏育。我愚昧，私下认为人确实如此，兽也应当如此。如今陛下喜欢登临险阻，射杀猛兽，突然遇到才能超凡的野兽，惊骇于无处可逃的地方，冲犯您随从车驾的清尘，车子来不及掉转车辕，人来不及施展技巧，即使有乌获、逢蒙的技艺也用不上，枯木朽株都会成为障碍。这就是胡越在车轮下兴起、羌夷在车后相接，难道不危险吗！即使万全无患，本来也不是天子所应当接近的。\n况且清道之后才出行，在路中央才奔驰，还时常有马嚼子脱落的变故，何况跋涉于蓬蒿之间，奔驰于丘陵坟冢之上，前面有贪得野兽的快乐，心中却没有防备变故的意识，那么招致祸患不也就难免了吗！轻视万乘之尊的重位而不以为安，反而乐于出现在万分之一危险的路上以为娱乐，我私下认为陛下不该这样做。\n明智的人在事情还没有萌发时就远见，聪明的人在危险还没有形成时就避开，祸患本来多隐藏在隐微之处，而发生在人们所忽略的时候。所以俗谚说：「家里积有千金，不坐在堂屋的垂檐下。」这话虽小，可以说明大道理。希望陛下留意体察。"],
    [141, "guwen-gwj-82", "public-domain", "子卿足下勤宣令德策名清时荣问休畅幸甚幸甚远托异国昔人所悲望风怀想能不依依昔者不遗远辱还答慰诲勤勤有逾骨肉陵虽不敏能不慨然自从初降以至今日身之穷困独坐愁苦终日无睹但见异类韦韝毳幕以御风雨膻肉酪浆以充饥渴举目言笑谁与为欢胡地玄冰边土惨裂但闻悲风萧条之声凉秋九月塞外草衰夜不能寐侧耳远听胡笳互动牧马悲鸣吟啸成群边声四起晨坐听之不觉泪下嗟乎子卿陵独何心能不悲哉与子别后益复无聊上念老母临年被戮妻子无辜并为鲸鲵身负国恩为世所悲子归受荣我留受辱命也如何身出礼义之乡而入无知之俗违弃君亲之恩长为蛮夷之域伤已令先君之嗣更成戎狄之族又自悲矣功大罪小不蒙明察孤负陵心区区之意每一念至忽然忘生陵不难刺心以自明刎颈以见志顾国家于我已矣杀身无益适足增羞故每攘臂忍辱辄复苟活左右之人见陵如此以为不入耳之欢来相劝勉异方之乐只令人悲增忉怛耳嗟乎子卿人之相知贵相知心前书仓卒未尽所怀故复略而言之昔先帝授陵步卒五千出征绝域五将失道陵独遇战而裹万里之粮帅徒步之师出天汉之外入强胡之域以五千之众对十万之军策疲乏之兵当新羁之马然犹斩将搴旗追奔逐北灭迹扫尘斩其枭帅使三军之士视死如归陵也不才希当大任意谓此时功难堪矣匈奴既败举国兴师更练精兵强逾十万单于临阵亲自合围客主之形既不相如步马之势又甚悬绝疲兵再战一以当千然犹扶乘创痛决命争首死伤积野余不满百而皆扶病不任干戈然陵振臂一呼创病皆起举刃指虏胡马奔走兵尽矢穷人无尺铁犹复徒首奋呼争为先登当此时也天地为陵震怒战士为陵饮血单于谓陵不可复得便欲引还而贼臣教之遂使复战故陵不免耳昔高皇帝以三十万众困于平城当此之时猛将如云谋臣如雨然犹七日不食仅乃得免况当陵者岂易为力哉而执事者云云苟怨陵以不死然陵不死罪也子卿视陵岂偷生之士而惜死之人哉宁有背君亲捐妻子而反为利者乎然陵不死有所为也故欲如前书之言报恩于国主耳诚以虚死不如立节灭名不如报德也昔范蠡不殉会稽之耻曹沫不死三败之辱卒复勾践之仇报鲁国之羞区区之心窃慕此耳何图志未立而怨已成计未从而骨肉受刑此陵所以仰天椎心而泣血也足下又云「汉与功臣不薄」子为汉臣安得不云尔乎昔萧樊囚絷韩彭菹醢晁错受戮周魏见辜其余佐命立功之士贾谊亚夫之徒皆信命世之才抱将相之具而受小人之谗并受祸败之辱卒使怀才受谤能不得展彼二子之遐举谁不为之痛心哉陵先将军功略盖天地义勇冠三军徒失贵臣之意刭身绝域之表此功臣义士所以负戟而长叹者也何谓不薄哉且足下昔以单车之使适万乘之虏遭时不遇至于伏剑不顾流离辛苦几死朔北之野丁年奉使皓首而归老母终堂生妻去帷此天下所希闻古今所未有也蛮貊之人尚犹嘉子之节况为天下之主乎陵谓足下当享茅土之荐受千乘之赏闻子之归赐不过二百万位不过典属国无尺土之封加子之勤而妨功害能之臣尽为万户侯亲戚贪佞之类悉为廊庙宰子尚如此陵复何望哉且汉厚诛陵以不死薄赏子以守节欲使远听之臣望风驰命此实难矣所以每顾而不悔者也陵虽孤恩汉亦负德昔人有言「虽忠不烈视死如归」陵诚能安而主岂复能眷眷乎男儿生以不成名死则葬蛮夷中谁复能屈身稽颡还向北阙使刀笔之吏弄其文墨邪愿足下勿复望陵嗟乎子卿夫复何言相去万里人绝路殊生为别世之人死为异域之鬼长与足下生死辞矣幸谢故人勉事圣君足下胤子无恙勿以为念努力自爱时因北风复惠德音李陵顿首", "子卿足下：您勤勉地宣扬美德，在清明的时代立身扬名，美好的名声远播，非常值得庆幸。远托异国，是古人所悲伤的事，遥望风范、怀念思念，怎能不依依不舍？从前承您不弃，远远地蒙您回信，慰问教诲殷勤恳切，胜过骨肉之情，我虽然不聪敏，怎能不感慨？\n自从当初投降，直到今天，身处困顿，独自坐着愁苦。整天什么也看不见，只看到异族。披着皮衣、住着毡帐，来防风雨；吃膻肉、喝酪浆，来充饥渴。举目谈笑，同谁为欢？胡地坚冰，边土惨裂，只听见悲风萧条的声音。凉秋九月，塞外草衰。夜里不能入睡，侧耳远听，胡笳互相应和，牧马悲鸣，吟啸成群，边地的声音四起。早晨坐着听这些，不觉泪下。唉，子卿，我独自是什么心肠，怎能不悲伤呢！\n与您分别之后，更加无聊，上念老母，年老被杀；妻子无辜，一同被沉入水中；自身辜负国恩，被世人所悲叹。您回去享受荣耀，我留下承受屈辱，命运又能怎样？我出身于礼义之乡，却进入无知的习俗；背弃君亲的恩情，长久处在蛮夷之地，伤心啊！让先君的后嗣，更变成戎狄的族类，又自己悲伤了。功劳大而罪过小，不被明察，辜负了我区区的心意。每每一想到此，忽然忘了活着。我不难刺心来自我表明，刎颈来显示志向，只是国家对我已经断绝，杀身没有益处，恰好增加羞辱，所以每每捋袖忍辱，就又苟且活着。左右的人，见我这样，拿一些不入耳的欢乐，来劝勉我。异方的快乐，只令人悲伤，增加忧伤罢了。\n唉，子卿，人的相知，贵在知心，前一封信仓促，没有说尽心中所想，所以再简略地说说。\n从前先帝授予我步兵五千，出征极远的区域。五位将领迷失道路，我独自遭遇战斗，带着万里的粮食，率领徒步的军队，走出天汉之外，进入强胡的地域；以五千的人众，对抗十万的军队；驱策疲惫的士兵，抵挡新上嚼子的战马。然而还能斩将拔旗，追击败退的敌人，灭迹扫尘，斩其骁将，使三军的将士，视死如归。我没有才能，很少担当大任，心想这个时候，功劳难以胜任了。匈奴战败之后，举国兴兵，再练精兵，强兵超过十万。单于临阵，亲自合围。客主的形势，已经不相称；步兵与骑兵的态势，又非常悬殊。疲惫的士兵再次作战，一人抵挡千人，然而还扶着伤痛，拼死争先。死伤遍野，剩下的不到百人，而且都带着病，拿不动兵器，然而我振臂一呼，受伤生病的人都站起来，举刀指向敌人，胡马奔逃。兵器用尽箭矢射完，人没有一寸铁器，还空手奋勇呼喊，争着先登。在这个时候，天地为我震怒，战士为我饮血。单于说不能再得到我，便想撤退，而叛臣教他，就使他再次来战，所以我不能幸免。\n从前高皇帝以三十万的人众，被困在平城。在这个时候，猛将如云，谋臣如雨，然而还七天没吃上饭，仅仅得以脱免。何况对付我的人，难道容易用力吗？而当事的人议论纷纷，只是埋怨我不去死。然而我不死，是罪过；子卿看我，难道是偷生之士、惜死之人吗？难道有背弃君亲、抛弃妻子反而是为了利益的吗？然而我不死，是有所作为的，所以想如前一封信所说的，向国主报恩罢了。实在是因为白白送死不如建立节操，泯灭名声不如报答恩德。从前范蠡不为会稽之耻殉死，曹沫不为三败之辱而死，终于报了勾践的仇，洗了鲁国的羞，我区区的心意，私下仰慕这个。哪里想到志向还没有建立而怨恨已经形成，计策还没有施行而骨肉已经受刑，这就是我仰天锤心而泣血的原因。\n足下又说：「汉朝对待功臣不薄。」您是汉朝的臣子，怎么能不这样说呢？从前萧何、樊哙被囚禁，韩信、彭越被剁成肉酱，晁错被杀，周勃、魏其侯被治罪。其余辅佐天命、建立功勋的士人，贾谊、周亚夫这些人，都是确实有命世之才，怀有将相的才干，却遭受小人的谗言，都受到祸败的屈辱，终于使怀才的人受谤，才能不能施展。那两个人的远行，谁不替他们痛心呢？我的先将军，功业谋略覆盖天地，义气勇敢冠绝三军，只是失了贵臣的心意，就在极远之地自刎。这就是功臣义士负戟长叹的原因。怎么能说是不薄呢？\n况且足下从前以单车之使，到万乘的敌国，遭遇不好的时运，以至于伏剑不顾；流离辛苦，几乎死在朔北的荒野。壮年出使，白头才回来；老母死于家中，妻子改嫁。这是天下少有的传闻，古今所没有的。蛮貊的人尚且称赞您的节操，何况做天下之主的人呢？我认为足下应当享受封土的推荐，接受千乘的赏赐。听说您回来，赏赐不过二百万，职位不过典属国，没有一尺的封土，来酬报您的辛劳。而妨害功臣、嫉妒贤能的人，都成了万户侯；亲戚贪佞之流，都成了朝廷的宰相。您尚且如此，我又指望什么呢？\n况且汉朝以不死重罚我，以守节薄赏您，想要使远方听命的臣子望风奔命，这实在难了。这就是我每每回顾而不后悔的原因。我虽然辜负了恩德，汉朝也亏负了德义。前人有话说：「即使忠诚而不激烈，也能视死如归。」我确实能安于死，而君主难道还能眷念我吗？男儿活着不能成名，死了就葬在蛮夷之中，谁还能屈身叩头，回到北方的宫阙，让刀笔吏玩弄他们的文墨呢？希望您不要再指望我了。\n唉，子卿，还有什么可说呢？相距万里，人隔路殊。活着是另一世的人，死了是异域的鬼。永远同您生死告别了。希望代我问候故人，勉力事奉圣君。足下的儿子平安，不要挂念。努力保重，有机会趁着北风，再赐给我好的音信。李陵顿首。"],
    [146, "guwen-gwj-83", "public-domain", "先帝创业未半而中道崩殂今天下三分益州疲弊此诚危急存亡之秋也然侍卫之臣不懈于内忠志之士忘身于外者盖追先帝之殊遇欲报之于陛下也诚宜开张圣听以光先帝遗德恢弘志士之气不宜妄自菲薄引喻失义以塞忠谏之路也宫中府中俱为一体陟罚臧否不宜异同若有作奸犯科及为忠善者宜付有司论其刑赏以昭陛下平明之理不宜偏私使内外异法也侍中侍郎郭攸之费祎董允等此皆良实志虑忠纯是以先帝简拔以遗陛下愚以为宫中之事事无大小悉以咨之然后施行必能裨补阙漏有所广益将军向宠性行淑均晓畅军事试用于昔日先帝称之曰能是以众议举宠为督愚以为营中之事悉以咨之必能使行阵和睦优劣得所亲贤臣远小人此先汉所以兴隆也亲小人远贤臣此后汉所以倾颓也先帝在时每与臣论此事未尝不叹息痛恨于桓灵也侍中尚书长史参军此悉贞良死节之臣愿陛下亲之信之则汉室之隆可计日而待也臣本布衣躬耕于南阳苟全性命于乱世不求闻达于诸侯先帝不以臣卑鄙猥自枉屈三顾臣于草庐之中咨臣以当世之事由是感激遂许先帝以驱驰后值倾覆受任于败军之际奉命于危难之间尔来二十有一年矣先帝知臣谨慎故临崩寄臣以大事也受命以来夙夜忧叹恐托付不效以伤先帝之明故五月渡泸深入不毛今南方已定兵甲已足当奖率三军北定中原庶竭驽钝攘除奸凶兴复汉室还于旧都此臣所以报先帝而忠陛下之职分也至于斟酌损益进尽忠言则攸之祎允之任也愿陛下托臣以讨贼兴复之效不效则治臣之罪以告先帝之灵若无兴德之言则责攸之祎允等之慢以彰其咎陛下亦宜自谋以咨诹善道察纳雅言深追先帝遗诏臣不胜受恩感激今当远离临表涕零不知所言", "先帝开创的事业还没完成一半就中途去世了，如今天下三分，益州困乏，这实在是危急存亡的时刻。然而侍卫的臣子在宫中不懈怠，忠诚有志的将士在外舍身忘死，是因为追念先帝的特殊恩遇，想要报答陛下。实在应该广开言路，来发扬先帝留下的美德，振奋志士的气概，不应该随便看轻自己，说话不合道理，以致堵塞忠臣进谏的道路。\n皇宫中和朝廷中都是一体，奖惩功过、评论好坏，不应该有差别。如果有做坏事犯法或尽忠行善的，应该交给主管官员评定刑罚奖赏，来显示陛下公正严明的治理，不应该偏袒徇私，使宫内宫外法度不同。\n侍中、侍郎郭攸之、费祎、董允等人，都是善良诚实、心志忠贞纯正的人，所以先帝选拔他们留给陛下。我认为宫中的事，无论大小，都拿来询问他们，然后施行，一定能弥补缺漏，有所增益。\n将军向宠，性情品行善良公正，通晓军事，从前试用过，先帝称赞他有才能，所以众人推举他做都督。我认为军中的事，都拿来询问他，一定能使军队和睦，才能高的和才能低的各得其所。\n亲近贤臣、疏远小人，这是前汉兴旺的原因；亲近小人、疏远贤臣，这是后汉衰败的原因。先帝在世时，每次与我谈论这件事，没有不为桓帝、灵帝叹息痛恨的。侍中、尚书、长史、参军这些人，都是忠贞善良、能以死报国的臣子，希望陛下亲近他们、信任他们，那么汉室的兴隆，可以计日而待了。\n我本是个平民，在南阳亲自耕田，只求在乱世中保全性命，不求在诸侯中显达。先帝不嫌我出身低微、见识短浅，委屈自己，三次到草庐来拜访我，拿当今的大事询问我，我因此感激，就答应为先帝奔走效力。后来遇到失败，在战败之际接受任命，在危难之间奉命出使，从那时到现在二十一年了。\n先帝知道我谨慎，所以临终把大事托付给我。接受任命以来，日夜忧愁叹息，怕托付的事情没有成效，以致损害先帝的英明，所以五月渡过泸水，深入不毛之地。如今南方已经平定，兵甲已经充足，应当勉励率领三军，北上平定中原，希望竭尽我平庸的才能，铲除奸凶，复兴汉室，迁回旧都。这是我用来报答先帝、尽忠陛下的职分。至于权衡得失、进献忠言，那是郭攸之、费祎、董允的责任。\n希望陛下把讨伐奸贼、复兴汉室的任务托付给我，没有成效就治我的罪，来告慰先帝的在天之灵。如果没有发扬圣德的言论，就责备郭攸之、费祎、董允等人的怠慢，来揭示他们的过失。陛下也应该自己谋划，询问治国的好办法，明察接纳正确的言论，深切追念先帝的遗诏。我受恩感激不尽。\n如今将要远离，面对这份表章涕泪交流，不知道说了什么。"],
    [147, "guwen-gwj-84", "public-domain", "先帝深虑汉贼不两立王业不偏安故托臣以讨贼也以先帝之明量臣之才固知臣伐贼才弱敌强也然不伐贼王业亦亡惟坐而待亡孰与伐之是故托臣而弗疑也臣受命之日寝不安席食不甘味思惟北征宜先入南故五月渡泸深入不毛并日而食臣非不自惜也顾王业不可得偏全于蜀都故冒危难以奉先帝之遗意也而议者谓为非计今贼适疲于西又务于东兵法乘劳此进趋之时也谨陈其事如左高帝明并日月谋臣渊深然涉险被创危然后安今陛下未及高帝谋臣不如良平而欲以长计取胜坐定天下此臣之未解一也刘繇王朗各据州郡论安言计动引圣人群疑满腹众难塞胸今岁不战明年不征使孙策坐大遂并江东此臣之未解二也曹操智计殊绝于人其用兵也仿佛孙吴然困于南阳险于乌巢危于祁连逼于黎阳几败北山殆死潼关然后伪定一时尔况臣才弱而欲以不危而定之此臣之未解三也曹操五攻昌霸不下四越巢湖不成任用李服而李服图之委任夏侯而夏侯败亡先帝每称操为能犹有此失况臣驽下何能必胜此臣之未解四也自臣到汉中中间期年耳然丧赵云阳群马玉阎芝丁立白寿刘郃邓铜等及曲长屯将七十余人突将无前賨叟青羌散骑武骑一千余人此皆数十年之内所纠合四方之精锐非一州之所有若复数年则损三分之二也当何以图敌此臣之未解五也今民穷兵疲而事不可息事不可息则住与行劳费正等而不及早图之欲以一州之地与贼持久此臣之未解六也夫难平者事也昔先帝败军于楚当此时曹操拊手谓天下已定然后先帝东连吴越西取巴蜀举兵北征夏侯授首此操之失计而汉事将成也然后吴更违盟关羽毁败秭归蹉跌曹丕称帝凡事如是难可逆见臣鞠躬尽力死而后已至于成败利钝非臣之明所能逆睹也", "先帝深深忧虑汉朝与曹贼不能两立，王业不能偏安一隅，所以把讨贼的事托付给我。凭先帝的明察，衡量我的才能，本来就知道我讨伐曹贼，是才能弱小而敌人强大。然而不讨伐曹贼，王业也要灭亡；只是坐着等待灭亡，同讨伐曹贼相比又怎么样呢？所以先帝托付我而毫无疑虑。我接受任命的时候，睡不安枕，食不甘味。想到要北征，应该先平定南方。所以五月渡过泸水，深入不毛之地，两天才吃一天的饭。我不是不爱惜自己，只是王业不能在蜀都偏安保全，所以冒着危难，来奉行先帝的遗愿。而议论的人说这是错误的计策。如今曹贼正好在西方疲惫，又在东方用兵，兵法说要趁敌人疲劳，这是进攻的时机。谨陈述这些事情如下：\n高皇帝明察可比日月，谋臣深谋远虑，然而还跋涉险阻、身受创伤，先危而后安。如今陛下比不上高皇帝，谋臣不如张良、陈平，却想用长远的计策取胜，安坐着平定天下，这是我的第一个不理解。\n刘繇、王朗各自占据州郡，谈论安危、陈述计策，动辄引用圣人，群臣满腹疑惑，众难塞胸，今年不作战，明年不出征，使孙策安然壮大，终于兼并江东，这是我的第二个不理解。\n曹操的智谋计策远超常人，他用兵，仿佛孙武、吴起，然而在南阳被困，在乌巢遇险，在祁连危险，在黎阳受逼，几乎败于北山，几乎死在潼关，然后才伪定一时罢了。何况我才能薄弱，却想不冒危险就平定天下，这是我的第三个不理解。\n曹操五次攻打昌霸而没有攻下，四次越过巢湖而没有成功，任用李服而李服图谋他，委任夏侯渊而夏侯渊败亡，先帝常常称曹操有才能，尚且有这样的失误，何况我驽钝低下，怎么能一定取胜？这是我的第四个不理解。\n从我到汉中，中间不过一年罢了，却丧失了赵云、阳群、马玉、阎芝、丁立、白寿、刘郃、邓铜等人以及曲长、屯将七十多人，突将、无前、賨叟、青羌、散骑、武骑一千多人。这些都是几十年之内所纠集的四方精锐，不是一州所能有的；如果再过了几年，就会损失三分之二，拿什么去对付敌人？这是我的第五个不理解。\n如今百姓穷困、士兵疲惫，而战事不能停止；战事不能停止，那么驻守和出战的劳费正好相等。却不趁早图谋，想以一州之地同曹贼长久相持，这是我的第六个不理解。\n难以料定的，是事情。从前先帝在楚地战败，在这个时候，曹操拍手，说天下已经平定。然而先帝东联吴越，西取巴蜀，举兵北征，夏侯渊被杀，这是曹操失算而汉室的事业将要成功了。然而后来吴国又违背盟约，关羽覆败，秭归受挫，曹丕称帝。凡事都是这样，难以逆料预见。我鞠躬尽力，死而后已，至于成功失败、顺利艰难，不是我的明察所能逆料的。"],
    [148, "guwen-gwj-133", "public-domain", "轼每读诗至鸱鸮读书至君奭常窃悲周公之不遇及观史见孔子厄于陈蔡之间而弦歌之声不绝颜渊仲由之徒相与问答夫子曰「『匪兕匪虎率彼旷野』吾道非邪吾何为于此」颜渊曰「夫子之道至大故天下莫能容虽然不容何病不容然后见君子」夫子油然而笑曰「回使尔多财吾为尔宰」夫天下虽不能容而其徒自足以相乐如此乃今知周公之富贵有不如夫子之贫贱夫以召公之贤以管蔡之亲而不知其心则周公谁与乐其富贵而夫子之所与共贫贱者皆天下之贤才则亦足以乐乎此矣轼七八岁时始知读书闻今天下有欧阳公者其为人如古孟轲韩愈之徒而又有梅公者从之游而与之上下其议论其后益壮始能读其文词想见其为人意其飘然脱去世俗之乐而自乐其乐也方学为对偶声律之文求升斗之禄自度无以进见于诸公之间来京师逾年未尝窥其门今年春天下之士群至于礼部执事与欧阳公实亲试之轼不自意获在第二既而闻之执事爱其文以为有孟轲之风而欧阳公亦以其能不为世俗之文也而取焉是以在此非左右为之先容非亲旧为之请属而向之十余年间闻其名而不得见者一朝为知己退而思之人不可以苟富贵亦不可以徒贫贱有大贤焉而为其徒则亦足恃矣苟其侥一时之幸从车骑数十人使闾巷小民聚观而赞叹之亦何以易此乐也传曰「不怨天不尤人」盖「优哉游哉可以卒岁」执事名满天下而位不过五品其容色温然而不怒其文章宽厚敦朴而无怨言此必有所乐乎斯道也轼愿与闻焉", "我每次读《诗经》读到《鸱鸮》，读《尚书》读到《君奭》，常常私下悲伤周公没有遇到知己。等到看史书，看见孔子困厄在陈、蔡之间，而弹琴唱歌的声音不断，颜渊、仲由这些人互相问答。夫子说：「『不是犀牛不是老虎，却行走在旷野上』，我的主张错了吗，我为什么到了这里？」颜渊说：「夫子的主张极其宏大，所以天下没有能容纳的。虽然如此，不容纳有什么可忧虑的，不容纳然后才显出君子。」夫子欣然笑着说：「回啊，假使你有许多财产，我给你做管家。」天下虽然不能容纳，而他的门徒自己足以如此互相快乐。如今才知道周公的富贵，有不如夫子的贫贱的地方。以召公的贤能，以管叔、蔡叔的亲近，却不知道他的心意，那么周公同谁共享他的富贵呢？而夫子与之共贫贱的，都是天下的贤才，那也就足以以此为乐了。\n我七八岁时，才知道读书，听说如今天下有欧阳公这个人，他的为人像古代的孟轲、韩愈一类人。又有梅公同他交游，和他反复讨论议论。此后我渐渐长大，才能读他们的文词，想象他们的为人，猜想他们飘然脱去世俗的快乐而自乐其乐。当时正学作对偶声律的文章，求取微薄的俸禄，自己估量没有可以进见诸公的机会。来到京城一年多，不曾窥看他们的门。今年春天，天下的士人成群到礼部，执事同欧阳公亲自考试他们。我自己没有料到，得以列在第二。随后听说，执事喜爱我的文章，认为有孟轲的风范。而欧阳公也因为我能够不作世俗之文而录取我。所以到了这里。这不是左右的人为我事先疏通，不是亲戚故旧为我请托，而是从前十几年间听到名声而不能见到的人，一朝成为知己。退下来想想，人不可以苟且富贵，也不可以白白贫贱。有大贤在那里而做他的门徒，也就足以依靠了。如果侥幸于一时的幸遇，跟随车骑几十人，使里巷小民聚集观看而赞叹，又怎么能换得这种快乐呢！\n古书上说：「不怨天，不尤人。」大概「优游自得，可以度过一年」。执事名满天下，而官位不过五品，他的容貌温和而不发怒，他的文章宽厚敦朴而没有怨言，这一定是有可乐于此道的。我希望听闻。"],
    [149, "guwen-gwj-134", "public-domain", "亭以雨名志喜也古者有喜则以名物示不忘也周公得禾以名其书汉武得鼎以名其年叔孙胜狄以名其子其喜之大小不齐其示不忘一也予至扶风之明年始治官舍为亭于堂之北而凿池其南引流种树以为休息之所是岁之春雨麦于岐山之阳其占为有年既而弥月不雨民方以为忧越三月乙卯乃雨甲子又雨民以为未足丁卯大雨三日乃止官吏相与庆于庭商贾相与歌于市农夫相与忭于野忧者以喜病者以愈而吾亭适成于是举酒于亭上以属客而告之曰「五日不雨可乎曰五日不雨则无麦十日不雨可乎曰十日不雨则无禾无麦无禾岁且荐饥狱讼繁兴而盗贼滋炽则吾与二三子虽欲优游以乐于此亭其可得耶今天不遗斯民始旱而赐之以雨使吾与二三子得相与优游而乐于此亭者皆雨之赐也其又可忘耶」既以名亭又从而歌之曰「使天而雨珠寒者不得以为襦使天而雨玉饥者不得以为粟一雨三日伊谁之力民曰太守太守不有归之天子天子曰不然归之造物造物不自以为功归之太空太空冥冥不可得而名吾以名吾亭」", "亭子用雨来命名，是为了记录喜事。古时候有喜事，就用它来给事物命名，表示不忘。周公得到嘉禾，用它命名他的书；汉武帝得到宝鼎，用它命名他的年号；叔孙战胜狄人，用它命名他的儿子。那喜事的大小不同，但表示不忘是一样的。\n我到扶风的第二年，才开始修治官舍。在堂的北面建亭，在南面凿池，引水种树，作为休息的地方。这一年的春天，在岐山南面天上落下麦子，占卜的结果是丰年。随后整月不下雨，百姓正为此忧愁。过了三个月，乙卯日才下雨，甲子日又下雨，百姓认为还不够。丁卯日下大雨，三天才停。官吏在庭中互相庆贺，商人在市上互相歌唱，农夫在田野中互相拍手，忧愁的人因此欢喜，生病的人因此痊愈，而我的亭子恰好建成。\n于是在亭上举酒，来劝客并告诉他们说：「五天不下雨可以吗？说：五天不下雨就没有麦子。十天不下雨可以吗？说：十天不下雨就没有禾苗。没有麦子没有禾苗，年成将要连年饥荒，狱讼频繁兴起，而盗贼更加猖獗。那么我和你们几位，虽然想优游地在这亭上快乐，能得到吗？如今上天不遗弃这里的百姓，刚旱就赐给他们雨，使我和你们几位得以一起优游地在这亭上快乐，都是雨的恩赐。又怎么能忘记呢？」\n既已用来命名亭子，又跟着歌唱说：「假使天落下珍珠，寒冷的人不能拿它做短袄；假使天落下美玉，饥饿的人不能拿它当粮食。一场雨下了三天，是谁的力量？百姓说是太守。太守不占有，归功于天子。天子说不是这样，归功于造物者。造物者不自以为有功，归功于太空。太空渺茫，不能得而命名。我就用它来命名我的亭子。」"],
    [150, "guwen-gwj-135", "public-domain", "国于南山之下宜若起居饮食与山接也四方之山莫高于终南而都邑之丽山者莫近于扶风以至近求最高其势必得而太守之居未尝知有山焉虽非事之所以损益而物理有不当然者此凌虚之所为筑也方其未筑也太守陈公杖履逍遥于其下见山之出于林木之上者累累如人之旅行于墙外而见其髻也曰「是必有异」使工凿其前为方池以其土筑台高出于屋之檐而止然后人之至于其上者恍然不知台之高而以为山之踊跃奋迅而出也公曰「是宜名凌虚」以告其从事苏轼而求文以为记轼复于公曰「物之废兴成毁不可得而知也昔者荒草野田霜露之所蒙翳狐虺之所窜伏方是时岂知有凌虚台耶废兴成毁相寻于无穷则台之复为荒草野田皆不可知也尝试与公登台而望其东则秦穆之祈年橐泉也其南则汉武之长杨五柞而其北则隋之仁寿唐之九成也计其一时之盛宏杰诡丽坚固而不可动者岂特百倍于台而已哉然而数世之后欲求其仿佛而破瓦颓垣无复存者既已化为禾黍荆棘丘墟陇亩矣而况于此台欤夫台犹不足恃以长久而况于人事之得丧忽往而忽来者欤而或者欲以夸世而自足则过矣盖世有足恃者而不在乎台之存亡也」既以言于公退而为之记", "在南山之下建立州治，似乎起居饮食都同山相接。四方的山，没有比终南更高的；而靠近山的都邑，没有比扶风更近的。以最近去求最高，那情势必定能得。而太守的居处，却不曾知道有山在那里。虽然这不是政事损益的原因，而事物的道理有不应当如此的，这就是凌虚台之所以建造的缘故。\n当它还没有建造时，太守陈公拄杖漫步在台下。看见从林木之上露出的山峰，层层叠叠像人在墙外行走而只看见他的发髻，说：「这里一定有奇特之处。」派工匠在它前面凿一个方池，用那土筑台，高出屋椽就停止。然后人到了它上面，恍然不知道台的高，而以为山踊跃奋迅地出来。公说：「这应当命名为凌虚。」把它告诉他的属吏苏轼，而求文来作记。\n苏轼回复公说：「事物的废兴成毁，不能得知。从前是荒草野田，霜露所覆盖，狐狸毒蛇所潜藏。在这个时候，哪里知道有凌虚台呢？废兴成毁，互相更替无穷，那么台再变成荒草野田，都是不可知的。试着同公登台眺望，它东面是秦穆公的祈年宫、橐泉宫，它南面是汉武帝的长杨宫、五柞宫，它北面是隋朝的仁寿宫、唐朝的九成宫。估量它们一时的盛况，宏杰奇丽，坚固不可动摇，难道只是百倍于这台而已呢！然而几代之后，想寻找它们的仿佛，而破瓦颓垣不再存在，已经化为禾黍荆棘、丘墟田亩了，何况这座台呢！台尚且不足以依靠以长久，何况人事的得失，忽往忽来的呢？而有人想以它夸耀于世而自我满足，那就错了。大概世上有足以依靠的，而不在于台的存亡。」\n既已向公说了，退下来写这篇记。"],
    [151, "guwen-gwj-136", "public-domain", "凡物皆有可观苟有可观皆有可乐非必怪奇伟丽者也哺糟啜醨皆可以醉果蔬草木皆可以饱推此类也吾安往而不乐夫所为求褔而辞祸者以褔可喜而祸可悲也人之所欲无穷而物之可以足吾欲者有尽美恶之辨战乎中而去取之择交乎前则可乐者常少而可悲者常多是谓求祸而辞褔夫求祸而辞褔岂人之情也哉物有以盖之矣彼游于物之内而不游于物之外物非有大小也自其内而观之未有不高且大者也彼挟其高大以临我则我常眩乱反复如隙中之观斗又乌知胜负之所在是以美恶横生而忧乐出焉可不大哀乎予自钱塘移守胶西释舟楫之安而服车马之劳去雕墙之美而庇采椽之居背湖山之观而行桑麻之野始至之日岁比不登盗贼满野狱讼充斥而斋厨索然日食杞菊人固疑予之不乐也处之期年而貌加丰发之白者日以反黑予既乐其风俗之淳而其吏民亦安予之拙也于是治其园圃洁其庭宇伐安丘高密之木以修补破败为苟完之计而园之北因城以为台者旧矣稍葺而新之时相与登览放意肆志焉南望马耳常山出没隐见若近若远庶几有隐君子乎而其东则庐山秦人卢敖之所从遁也西望穆陵隐然如城郭师尚父齐桓公之遗烈犹有存者北俯潍水慨然太息思淮阴之功而吊其不终台高而安深而明夏凉而冬温雨雪之朝风月之夕予未尝不在客未尝不从撷园蔬取池鱼酿秫酒瀹脱粟而食之曰乐哉游乎方是时予弟子由适在济南闻而赋之且名其台曰超然以见予之无所往而不乐者盖游于物之外也", "万物都有可观之处。如果有可观之处，就都有可乐之处，不必一定是怪奇伟丽的。吃酒糟、喝薄酒，都可以醉；果蔬草木，都可以饱。以此类推，我去哪里而不快乐呢？\n人们之所以求福而避祸，是因为福可喜而祸可悲。人的欲望无穷，而可以满足我欲望的事物有限。美恶的辨别在心中交战，而取舍的选择在面前交错，那么可乐的常常少，而可悲的常常多，这叫做求祸而避福。求祸而避福，难道是人的常情吗？是外物有所蒙蔽罢了。那些人游于物的内部，而不游于物的外部。物并没有大小，从它的内部来看，没有不高且大的。那些人仗着他们的高大大而临视我，那么我就常常眩乱反复，像从缝隙中看争斗，又怎么知道胜负在哪里呢？所以美恶横生，而忧乐由此而出，能不大大悲哀吗！\n我从钱塘调任胶西太守，舍弃舟楫的安逸，而承受车马的劳苦；离开雕墙的华美，而遮蔽于采椽的居处；背离湖山的景观，而行于桑麻的田野。刚到的时候，年成连年不丰收，盗贼满野，狱讼充斥，而斋厨空空，每天吃枸杞菊花。人们本来疑心我不快乐。处了一年，而容貌更加丰润，头发白的，一天天变黑。我既喜爱这里风俗的淳厚，而这里的官吏百姓也安于我的笨拙。于是整治园圃，清洁庭宇，砍伐安丘、高密的树木，来修补破败，作苟且完备的打算。园的北面，依城筑台已经旧了，稍加修缮而更新它。时常一起登临观览，纵情任性。南望马耳山、常山，出没隐现，若近若远，大概有隐君子吧？它的东面是庐山，是秦人卢敖逃隐的地方。西望穆陵，隐约如城郭，师尚父、齐桓公的遣烈，还有存在的。北俯潍水，慨然叹息，思念淮阴侯的功绩，而哀悼他不得善终。台高而安稳，深而明亮，夏凉而冬温。雨雪的早晨，风月的晚上，我不曾不在，客也不曾不跟从。采摘园中的蔬菜，取池中的鱼，酿高粱酒，煮糙米而吃，说：快乐啊，游览啊！\n在这个时候，我的弟弟子由正好在济南，听到就为它作赋，并且命名这座台叫超然。以此可见我无所往而不快乐，大概是因为游于物的外部。"],
    [152, "guwen-gwj-137", "public-domain", "熙宁十年秋彭城大水云龙山人张君之草堂水及其半扉明年春水落迁于故居之东东山之麓升高而望得异境焉作亭于其上彭城之山冈岭四合隐然如大环独缺其西一面而山人之亭适当其缺春夏之交草木际天秋冬雪月千里一色风雨晦明之间俯仰百变山人有二鹤甚驯而善飞旦则望西山之缺而放焉纵其所如或立于陂田或翔于云表暮则傃东山而归故名之曰放鹤亭郡守苏轼时从宾佐僚吏往见山人饮酒于斯亭而乐之揖山人而告之曰「子知隐居之乐乎虽南面之君未可与易也易曰『鸣鹤在阴其子和之』诗曰『鹤鸣于九皋声闻于天』盖其为物清远闲放超然于尘埃之外故易诗人以比贤人君子隐德之士狎而玩之宜若有益而无损者然卫懿公好鹤则亡其国周公作酒诰卫武公作抑戒以为荒惑败乱无若酒者而刘伶阮籍之徒以此全其真而名后世嗟夫南面之君虽清远闲放如鹤者犹不得好好之则亡其国而山林遁世之士虽荒惑败乱如酒者犹不能为害而况于鹤乎由此观之其为乐未可以同日而语也」山人欣然而笑曰「有是哉」乃作放鹤招鹤之歌曰「鹤飞去兮西山之缺高翔而下览兮择所适翻然敛翼宛将集兮忽何所见矫然而复击独终日于涧谷之间兮啄苍苔而履白石鹤归来兮东山之阴其下有人兮黄冠草屦葛衣而鼓琴躬耕而食兮其余以汝饱归来归来兮西山不可以久留」元丰元年十一月初八日记", "熙宁十年秋天，彭城发大水。云龙山人张君的草堂，水没到门扇的一半。第二年春天，水退，迁到故居的东面、东山的山麓。登高眺望，找到一处奇异的境地，在它上面建亭。彭城的山，冈岭四面合围，隐约像一个大环，只缺西面一面，而山人的亭，恰好正当那个缺口。春夏之交，草木连接到天；秋冬雪月，千里一色；风雨明暗之间，俯仰百变。山人有两只鹤，很驯服而善于飞翔，早晨就望着西山的缺口放它们出去，任凭它们到哪里，有的立在坡田，有的翱翔在云外；傍晚就向着东山回来。所以命名它叫放鹤亭。\n郡守苏轼，时常跟宾客僚属去看山人，在这亭上饮酒而快乐。向山人作揖并告诉他说：「您知道隐居的快乐吗？即使是南面称君的人，也不能同它交换。《易经》说：『鹤在树荫下鸣叫，它的同类应和它。』《诗经》说：『鹤在沼泽中鸣叫，声音传到天上。』大概它作为一种动物，清远闲放，超然于尘埃之外，所以《易经》《诗经》的作者拿它比贤人君子。有隐德的人，亲近而玩赏它，似乎有益而无损，然而卫懿公喜好鹤就亡了他的国。周公作《酒诰》，卫武公作《抑》戒，认为荒惑败乱，没有像酒那样的；而刘伶、阮籍这些人，以此保全他们的真性而闻名后世。唉！南面称君的人，即使清远闲放如鹤的，尚且不能喜好，喜好它就亡了他的国；而山林遁世的人，即使荒惑败乱如酒的，尚且不能为害，何况对鹤呢？由此看来，那快乐不可以同日而语。」\n山人欣然而笑说：「有这样的事啊！」于是作放鹤、招鹤的歌说：「鹤飞去啊西山的缺口，高飞而下望啊选择所要去的地方。翻然收敛翅膀，仿佛将要停集啊，忽然看见了什么，矫健地又振翅。独自整日在涧谷之间啊，啄苍苔而踏白石。鹤归来啊，东山的北面。那下面有人啊，戴着黄冠、穿着草鞋，披着葛衣而弹琴。亲自耕种而食啊，剩余的让你吃饱。归来归来啊，西山不可以久留。」\n元丰元年十一月初八日记。"],
    [153, "guwen-gwj-138", "public-domain", "水经云「彭蠡之口有石钟山焉」郦元以为下临深潭微风鼓浪水石相搏声如洪钟是说也人常疑之今以钟磬置水中虽大风浪不能鸣也而况石乎至唐李渤始访其遗踪得双石于潭上扣而聆之南声函胡北音清越枹止响腾余韵徐歇自以为得之矣然是说也余尤疑之石之铿然有声者所在皆是也而此独以钟名何哉元丰七年六月丁丑余自齐安舟行适临汝而长子迈将赴饶之德兴尉送之至湖口因得观所谓石钟者寺僧使小童持斧于乱石间择其一二扣之硿硿焉余固笑而不信也至其夜月明独与迈乘小舟至绝壁下大石侧立千尺如猛兽奇鬼森然欲搏人而山上栖鹘闻人声亦惊起磔磔云霄间又有若老人咳且笑于山谷中者或曰此鹳鹤也余方心动欲还而大声发于水上噌吰如钟鼓不绝舟人大恐徐而察之则山下皆石穴罅不知其浅深微波入焉涵澹澎湃而为此也舟回至两山间将入港口有大石当中流可坐百人空中而多窍与风水相吞吐有窾坎镗鞳之声与向之噌吰者相应如乐作焉因笑谓迈曰「汝识之乎噌吰者周景王之无射也窾坎镗鞳者魏庄子之歌钟也古之人不余欺也」事不目见耳闻而臆断其有无可乎郦元之所见闻殆与余同而言之不详士大夫终不肯以小舟夜泊绝壁之下故莫能知而渔工水师虽知而不能言此世所以不传也而陋者乃以斧斤考击而求之自以为得其实余是以记之盖叹郦元之简而笑李渤之陋也", "《水经》说：「彭蠡湖的入口有座石钟山。」郦道元认为它下面临着深潭，微风激起波浪，水与石相击，声音像洪钟。这个说法，人们常常怀疑它。如今把钟磬放在水中，即使大风大浪也不能响，何况石头呢！到唐朝李渤才寻访它的遗迹，在潭上找到两块石头，敲击而听它，南边的声音重浊，北边的声音清越，鼓槌停了响声还在腾起，余音慢慢消失。他自以为得到了真相。然而这个说法，我尤其怀疑它。石头能铿然作响的，到处都有，而这座山独以钟命名，为什么呢？\n元丰七年六月丁丑日，我从齐安乘船到临汝，而长子苏迈将赴任饶州德兴县尉，送他到湖口，因而得以观看所谓石钟的。寺僧派小童拿着斧头，在乱石间选一两块敲击，硿硿地响。我本来笑着不相信。到了夜里月明，独自同苏迈乘小船，到绝壁下面。大石侧立千尺，像猛兽奇鬼，森然想要扑人；而山上栖息的鹘鸟，听到人声也惊起，磔磔地叫着冲上云霄；又有像老人在山谷中咳并且笑的，有人说这是鹳鹤。我正心惊想回去，而大声从水上发出，噌吰地像钟鼓不停。船夫非常恐惧。慢慢地观察它，原来山下都是石洞石缝，不知它的深浅，微波涌入，激荡澎湃而发出这声音。船回到两山之间，将要进入港口，有大石正当水流中间，可以坐一百人，中间空而多孔，同风水互相吞吐，有窾坎镗鞳的声音，同刚才的噌吰互相应和，像音乐奏起。于是笑着对苏迈说：「你知道吗？噌吰的声音，是周景王的无射钟；窾坎镗鞳的声音，是魏庄子的歌钟。古人没有欺骗我啊！」\n事情不亲眼见到亲耳听到，就主观判断它有还是无，可以吗？郦道元所见到听到的，大概同我一样，而说得不详细；士大夫终究不肯乘小船夜里停泊在绝壁之下，所以没有人能知道；而渔夫船工虽然知道却不能说明。这就是世上不能流传的原因。而浅陋的人竟用斧头敲击来探求它，自以为得到真相。我因此记下这件事，是叹郦道元的简略，而笑李渤的浅陋。"],
    [154, "guwen-gwj-141", "public-domain", "匹夫而为百世师一言而为天下法是皆有以参天地之化关盛衰之运其生也有自来其逝也有所为故申吕自岳降傅说为列星古今所传不可诬也孟子曰「我善养吾浩然之气」是气也寓于寻常之中而塞乎天地之间卒然遇之则王公失其贵晋楚失其富良平失其智贲育失其勇仪秦失其辩是孰使之然哉其必有不依形而立不恃力而行不待生而存不随死而亡者矣故在天为星辰在地为河岳幽则为鬼神而明则复为人此理之常无足怪者自东汉以来道丧文弊异端并起历唐贞观开元之盛辅以房杜姚宋而不能救独韩文公起布衣谈笑而麾之天下靡然从公复归于正盖三百年于此矣文起八代之衰道济天下之溺忠犯人主之怒而勇夺三军之帅此岂非参天地关盛衰浩然而独存者乎盖尝论天人之辨以谓人无所不至惟天不容伪智可以欺王公不可以欺豚鱼力可以得天下不可以得匹夫匹妇之心故公之精诚能开衡山之云而不能回宪宗之惑能驯鳄鱼之暴而不能弭皇甫镈李逢吉之谤能信于南海之民庙食百世而不能使其身一日安于朝廷之上盖公之所能者天也其所不能者人也始潮人未知学公命进士赵德为之师自是潮之士皆笃于文行延及齐民至于今号称易治信乎孔子之言「君子学道则爱人小人学道则易使也」潮人之事公也饮食必祭水旱疾疫凡有求必祷焉而庙在刺史公堂之后民以出入为艰前守欲请诸朝作新庙不果元祐五年朝散郎王君涤来守是邦凡所以养士治民者一以公为师民既悦服则出令曰「愿新公庙者听」民欢趋之卜地于州城之南七里期年而庙成或曰「公去国万里而谪于潮不能一岁而归没而有知其不眷恋于潮也审矣」轼曰「不然公之神在天下者如水之在地中无所往而不在也而潮人独信之深思之至焄蒿凄怆若或见之譬如凿井得泉而曰水专在是岂理也哉」元丰七年诏封公昌黎伯故榜曰「昌黎伯韩文公之庙」潮人请书其事于石因作诗以遗之使歌以祀公", "一个平民而成为百世的师表，一句话而成为天下的法则。这都是有用来参助天地的化育、关系盛衰的命运的，他们的出生有来由，他们的逝去有作为。所以申伯、吕侯从山岳降生，傅说成为列星，古今相传，不可诬蔑。孟子说：「我善于培养我的浩然之气。」这种气，寄寓在寻常之中，而充塞于天地之间。突然遇到它，那么王公失去他们的尊贵，晋、楚失去他们的富有，张良、陈平失去他们的智谋，孟贲、夏育失去他们的勇力，张仪、苏秦失去他们的辩才。是谁使它这样呢？那必定有不依赖形体而存在，不依靠力量而运行，不等待生存而存在，不随着死亡而消亡的东西。所以在天上就是星辰，在地上就是河岳，幽暗处就是鬼神，而显明时就又是人。这是常理，不足为怪。\n自从东汉以来，道丧失、文凋弊，异端一齐兴起。经历唐贞观、开元的盛世，用房玄龄、杜如晦、姚崇、宋璟辅佐而不能挽救。只有韩文公从平民中兴起，谈笑而指挥它们，天下随风而从公，重新回到正道，到现在大概三百年了。文章振兴八代的衰弊，道义救济天下的沉溺；忠诚触犯人主的愤怒，而勇气夺取三军的帅位。这难道不是参助天地、关系盛衰、浩然而独自存在的吗？\n曾经论说天与人的分别，认为人没有什么做不到，只有天不容许虚伪。智谋可以欺骗王公，不可以欺骗小猪小鱼；力量可以得到天下，不可以得到匹夫匹妇的心。所以公的精诚，能打开衡山的云雾，却不能挽回宪宗的迷惑；能驯服鳄鱼的凶暴，却不能止息皇甫镈、李逢吉的诽谤；能取信于南海的百姓，庙食百世，却不能使他自己在朝廷上有一天安身。大概公所能的是天，他所不能的是人。\n起初潮州人不知道学习，公命进士赵德做他们的老师。从此潮州的士人，都致力于文章德行，延及平民，到现在，号称容易治理。确实啊孔子的话：「君子学了道就爱人，小人学了道就容易驱使。」潮州人事奉公，饮食必定祭祀，水旱疾疫，凡有祈求必定祷告。而庙在刺史公堂的后面，百姓觉得进出艰难。前任太守想向朝廷请求建新庙，没有成功。元祐五年，朝散郎王涤君来做这个州的太守。凡是用来养士治民的，一律以公为师。百姓既已悦服，就出令说：「愿意新建公庙的听便。」百姓欢欣趋赴，在州城南面七里卜地，满一年而庙建成。\n有人说：「公离开国都万里，而被贬到潮州，不到一年就回去，死后如果有知，他不眷恋潮州是很明白的。」我说：「不是这样。公的神在天下的，像水在地下，无所往而不在。而潮州人独独信得深、思念得切，祭祀时仿佛见到他。比如凿井得到泉水，就说水只在这里，难道合理吗？」元丰七年，下诏封公为昌黎伯，所以匾额题为「昌黎伯韩文公之庙」。潮州人请求把这件事写在石上，于是作诗送给他们，让他们歌唱来祭祀公。"],
    [155, "guwen-gwj-207", "", "臣等猥以空疏备员讲读圣明天纵学问日新臣等才有限而道无穷心欲言而口不逮以此自愧莫知所为窃谓人臣之纳忠譬如医者之用药药虽进于医手方多传于古人若已经效于世间不必皆从于己出伏见唐宰相陆贽才本王佐学为帝师论深切于事情言不离于道德智如子房而文则过辩如贾谊而术不疏上以格君心之非下以通天下之志但其不幸仕不遇时德宗以苛刻为能而贽谏之以忠厚德宗以猜疑为术而贽劝之以推诚德宗好用兵而贽以消兵为先德宗好聚财而贽以散财为急至于用人听言之法治边御将之方罪己以收人心改过以应天道去小人以除民患惜名器以待有功如此之流未易悉数可谓进苦口之药石针害身之膏肓使德宗尽用其言则贞观可得而复臣等每退自西阁即私相告言以陛下圣明必喜贽议论但使圣贤之相契即如臣主之同时昔冯唐论颇牧之贤则汉文为之太息魏相条晁董之对则孝宣以致中兴若陛下能自得师则莫若近取诸贽夫六经三史诸子百家非无可观皆足为治但圣言幽远末学支离譬如山海之崇深难以一二而推择如贽之论开卷了然聚古今之精英实治乱之龟鉴臣等欲取其奏议稍加校正缮写进呈愿陛下置之坐隅如见贽面反覆熟读如与贽言必能发圣性之高明成治功于岁月臣等不胜区区之意取进止", "臣等空疏无能，充数担任讲读。陛下圣明出于天授，学问日日更新。臣等才能有限而道理无穷，心里想说而口才不及，因此自愧，不知该怎么办。臣私下认为人臣进献忠诚，譬如医生用药，药虽然从医生手里递出，药方大多传自古人。如果已经在世间见效，不必都由自己开出。臣看到唐宰相陆贽，才能本是帝王的辅佐，学问可做帝王的老师。议论深切于事情，言语不离于道德。智慧像张良，而文采超过他；辩才像贾谊，而方法不疏阔。上用来纠正君主心性的过失，下用来通达天下的心志。只是他不幸，做官不逢时机。德宗以苛刻为能，而陆贽用忠厚劝谏他；德宗以猜疑为术，而陆贽用推诚劝勉他；德宗喜好用兵，而陆贽以消除兵事为先；德宗喜好积聚财货，而陆贽以散财为急。至于用人和听言的方法，治理边境驾驭将帅的方略，用罪己来收人心，用改过来应天道，除去小人来消除民患，爱惜名器来等待有功的人，如此之类，不容易全部列举。可以说是进献苦口的药石，针刺危害身体的膏肓。假使德宗完全采用他的话，那么贞观之治可以得到恢复。\n臣等每次从西阁退下，就私下相告，凭陛下的圣明，一定喜欢陆贽的议论。只要圣君贤臣相合，就像君臣同时一样。从前冯唐论廉颇、李牧的贤能，汉文帝为之叹息；魏相陈述晁错、董仲舒的对答，孝宣帝因此实现中兴。如果陛下能自己求得老师，就不如就近取陆贽。六经三史，诸子百家，不是没有可观的，都足以用来治国。但圣人的话幽远，末流的学问支离，譬如山海的崇高深广，难以一二推求选择。像陆贽的议论，开卷就明白。聚集古今的精华，实在是治乱的龟鉴。臣等想取他的奏议，稍加校正，抄写进呈。希望陛下放在座旁，如同见到陆贽的面；反复熟读，如同与陆贽交谈。一定能启发圣性的高明，在岁月中成就治功。臣等不胜区区之意。听候取舍。"],
    [156, "guwen-gwj-139", "school", "壬戌之秋七月既望苏子与客泛舟游于赤壁之下清风徐来水波不兴举酒属客诵明月之诗歌窈窕之章少焉月出于东山之上徘徊于斗牛之间白露横江水光接天纵一苇之所如凌万顷之茫然浩浩乎如冯虚御风而不知其所止飘飘乎如遗世独立羽化而登仙于是饮酒乐甚扣舷而歌之歌曰「桂棹兮兰桨击空明兮溯流光渺渺兮予怀望美人兮天一方」客有吹洞箫者倚歌而和之其声呜呜然如怨如慕如泣如诉余音袅袅不绝如缕舞幽壑之潜蛟泣孤舟之嫠妇苏子愀然正襟危坐而问客曰「何为其然也」客曰「『月明星稀乌鹊南飞』此非曹孟德之诗乎西望夏口东望武昌山川相缪郁乎苍苍此非孟德之困于周郎者乎方其破荆州下江陵顺流而东也舳舻千里旌旗蔽空酾酒临江横槊赋诗固一世之雄也而今安在哉况吾与子渔樵于江渚之上侣鱼虾而友麋鹿驾一叶之扁舟举匏樽以相属寄蜉蝣于天地渺沧海之一粟哀吾生之须臾羡长江之无穷挟飞仙以遨游抱明月而长终知不可乎骤得托遗响于悲风」苏子曰「客亦知夫水与月乎逝者如斯而未尝往也盈虚者如彼而卒莫消长也盖将自其变者而观之则天地曾不能以一瞬自其不变者而观之则物与我皆无尽也而又何羡乎且夫天地之间物各有主苟非吾之所有虽一毫而莫取惟江上之清风与山间之明月耳得之而为声目遇之而成色取之无禁用之不竭是造物者之无尽藏也而吾与子之所共适」客喜而笑洗盏更酌肴核既尽杯盘狼籍相与枕藉乎舟中不知东方之既白", "壬戌年的秋天，七月十六日，我和客人乘船游览于赤壁之下。清风缓缓吹来，水波不起。举酒劝客，诵读明月的诗，歌唱窈窕的篇章。一会儿，月亮从东山上升起，徘徊在斗宿牛宿之间。白露横亘江面，水光连接天空。任凭一片苇叶般的小船所去，凌越万顷的茫然。浩浩荡荡像凭空驾风，而不知它停在哪里；飘飘然像脱离尘世独立，羽化成仙。\n于是饮酒非常快乐，敲着船舷唱歌。歌词说：「桂树做的棹啊兰木做的桨，划开空明的江水啊逆流而上。渺远啊我的情怀，遥望美人啊在天的那一方。」客人中有吹洞箫的，依着歌声应和。那声音呜呜然，像哀怨像思慕，像哭泣像诉说，余音袅袅，不断如丝缕。使深谷中潜伏的蛟龙起舞，使孤舟中的寡妇哭泣。\n我神色改变，整好衣襟端坐，问客人说：「为什么这样呢？」客人说：「『月明星稀，乌鹊南飞』，这不是曹孟德的诗吗？西望夏口，东望武昌，山川缭绕，郁郁苍苍，这不是孟德被周郎困住的地方吗？当他攻破荆州，攻下江陵，顺流东下时，战船千里，旌旗遮蔽天空，面对长江斟酒，横着长矛赋诗，本来是一世的英雄，如今在哪里呢？何况我和你在江边洲上打鱼砍柴，以鱼虾为伴侣、以麋鹿为朋友，驾着一片苇叶般的小船，举着葫芦杯互相劝酒。像蜉蝣一样寄身于天地，渺小得像沧海中的一粒粟。哀叹我生命的短暂，羡慕长江的无穷。携飞仙而遨游，抱明月而长存。知道不能骤然得到，只好把余音寄托在悲风之中。」\n我说：「你也知道水和月吗？流逝的像这样，而并没有真正流去；盈虚的像那样，而终究没有消长。大概从它变化的一面看，那么天地连一瞬间都不能保持不变；从它不变的一面看，那么万物和我都是无穷的，又羡慕什么呢！况且天地之间，万物各有主人，如果不是我所有的，即使一根毫毛也不能取。只有江上的清风，和山间的明月，耳朵听到就成为声音，眼睛遇到就成为颜色，取它没有禁忌，用它不会枯竭，这是造物者的无穷宝藏，而我和你所共同享有的。」\n客人高兴地笑了，洗杯重新斟酒。菜肴果品已经吃完，杯盘凌乱。互相枕靠着睡在船中，不知道东方已经发白。"],
    [157, "guwen-gwj-140", "public-domain", "是岁十月之望步自雪堂将归于临皋二客从予过黄泥之坂霜露既降木叶尽脱人影在地仰见明月顾而乐之行歌相答已而叹曰「有客无酒有酒无肴月白风清如此良夜何」客曰「今者薄暮举网得鱼巨口细鳞状似松江之鲈顾安所得酒乎」归而谋诸妇妇曰「我有斗酒藏之久矣以待子不时之需」于是携酒与鱼复游于赤壁之下江流有声断岸千尺山高月小水落石出曾日月之几何而江山不可复识矣予乃摄衣而上履巉岩披蒙茸踞虎豹登虬龙攀栖鹘之危巢俯冯夷之幽宫盖二客不能从焉划然长啸草木震动山鸣谷应风起水涌予亦悄然而悲肃然而恐凛乎其不可留也反而登舟放乎中流听其所止而休焉时夜将半四顾寂寥适有孤鹤横江东来翅如车轮玄裳缟衣戛然长鸣掠予舟而西也须臾客去予亦就睡梦一道士羽衣蹁跹过临皋之下揖予而言曰「赤壁之游乐乎」问其姓名俯而不答「呜呼噫嘻我知之矣畴昔之夜飞鸣而过我者非子也耶」道士顾笑予亦惊寤开户视之不见其处", "这一年十月十五日，从雪堂步行，将回临皋。两位客人跟我经过黄泥坂。霜露已经降下，树叶全部脱落。人影在地上，抬头看见明月，环顾而喜爱它，边走边唱互相应答。随后叹息说：「有客没有酒，有酒没有菜，月白风清，这样的良夜怎么办？」客人说：「今天傍晚，撒网得鱼，大嘴细鳞，形状像松江的鲈鱼。但到哪里去找酒呢？」回去同妻子商量。妻子说：「我有一斗酒，收藏很久了，来等待你临时的需要。」于是带着酒和鱼，再到赤壁之下游览。江流有声，断岸千尺。山高月小，水落石出。才过了多少日子，而江山已经不能再认出来了。\n我于是提起衣襟上岸，踏着险峻的山岩，拨开丛生的草木，蹲坐在像虎豹的怪石上，登上像虬龙的古树，攀上栖鹘的高巢，俯看水神冯夷的深宫。两位客人不能跟从。我划然长啸，草木震动，山鸣谷应，风起水涌。我也悄然悲伤，肃然恐惧，凛然觉得不可久留。返回登上船，任凭它驶到中流，听它停下就休息。这时将近半夜，四顾寂寥。恰好有孤鹤，横穿江面从东飞来，翅膀像车轮，黑裙白衣，戛然长鸣，掠过我的船向西飞去。\n一会儿客人离去，我也就睡下。梦见一位道士，穿着羽衣翩翩，经过临皋之下，向我作揖说：「赤壁之游快乐吗？」问他姓名，低着头不回答。「唉呀！我知道了。从前那夜，飞鸣着从我这里过去的，不是你吗？」道士回头笑，我也惊醒。开门看，不见他在哪里。"],
    [158, "guwen-gwj-208", "", "天可必乎贤者不必贵仁者不必寿天不可必乎仁者必有后二者将安取衷哉吾闻之申包胥曰「人定者胜天天定亦能胜人」世之论天者皆不待其定而求之故以天为茫茫善者以怠恶者以肆盗跖之寿孔颜之厄此皆天之未定者也松柏生于山林其始也困于蓬蒿厄于牛羊而其终也贯四时阅千岁而不改者其天定也善恶之报至于子孙则其定也久矣吾以所见所闻考之而其可必也审矣国之将兴必有世德之臣厚施而不食其报然后其子孙能与守文太平之主共天下之福故兵部侍郎晋国王公显于汉周之际历事太祖太宗文武忠孝天下望以为相而公卒以直道不容于时盖尝手植三槐于庭曰「吾子孙必有为三公者」已而其子魏国文正公相真宗皇帝于景德祥符之间朝廷清明天下无事之时享其福禄荣名者十有八年今夫寓物于人明日而取之有得有否而晋公修德于身责报于天取必于数十年之后如持左契交手相付吾是以知天之果可必也吾不及见魏公而见其子懿敏公以直谏事仁宗皇帝出入侍从将帅三十余年位不满其德天将复兴王氏也欤何其子孙之多贤也世有以晋公比李栖筠者其雄才直气真不相上下而栖筠之子吉甫其孙德裕功名富贵略与王氏等而忠恕仁厚不及魏公父子由此观之王氏之福盖未艾也懿敏公之子巩与吾游好德而文以世其家吾以是铭之铭曰呜呼休哉魏公之业与槐俱萌封植之勤必世乃成既相真宗四方砥平归视其家槐阴满庭吾侪小人朝不及夕相时射利皇恤厥德庶几侥幸不种而获不有君子其何能国王城之东晋公所庐郁郁三槐惟德之符呜呼休哉", "天可以断定吗？贤者不一定显贵，仁者不一定长寿。天不可以断定吗？仁者一定有后代。二者将怎么取其中呢？我听申包胥说：「人定能胜天，天定也能胜人。」世上论天的人，都不等它定就求取，所以认为天茫茫难知。善人因此懈怠，恶人因此放肆。盗跖长寿，孔子、颜回困厄，这都是天还没有定的时候。松柏生在山林，起初困于蓬蒿，受制于牛羊；而到最后，贯穿四季、经历千岁而不改变的，是它的天定了。善恶的报应，至于子孙，那么它定下来已经很久了。我用所见所闻来考察，那可以断定是很明白的。\n国家将要兴盛，一定有世代积德的臣子，厚施恩惠而不享他的报答，然后他的子孙能与守成的太平君主共天下这福。已故兵部侍郎晋国王公，显达于后汉、后周之际，历事太祖、太宗，文武忠孝，天下期望他做宰相，而王公终于因直道不被时世所容。他曾亲手在庭中种下三棵槐树，说：「我的子孙一定有做三公的。」后来他的儿子魏国文正公，在景德、祥符年间做真宗皇帝的宰相，正当朝廷清明、天下无事的时候，享受福禄荣名十八年。如今把东西寄放在别人那里，第二天去取，有得的有不得的；而晋公在自身修养德行，向上天求报，必取于数十年之后，如同拿着左契，交手相付。我因此知道天的确可以断定。\n我没能见到魏公，而见到他的儿子懿敏公，以直言进谏事奉仁宗皇帝，出入侍从将帅三十多年，官位与其德行不相称。天将要复兴王氏吧！为什么他的子孙这样多贤才呢？世上有拿晋公比李栖筠的，他的雄才直气，真不相上下。而李栖筠的儿子李吉甫，他的孙子李德裕，功名富贵，大致与王氏相等；而忠恕仁厚，不及魏公父子。由此看来，王氏的福大概还没有止尽。\n懿敏公的儿子王巩与我交游，好德而有文采，以承继他的家世，我因此为他作铭。铭说：唉，美啊！魏公的功业，与槐树一同萌发。培植的辛勤，一定要到下一代才成。既已辅相真宗，四方太平。回来看看他的家，槐荫满庭。我们这些小人，早晨还顾不上晚上，窥伺时机谋取利益，哪顾得上他的德行？只希望侥幸，不种而收获。没有君子，怎么能立国？王城的东边，是晋公的居所。郁郁三槐，是德行的符信。唉，美啊！"],
    [159, "guwen-gwj-209", "", "方山子光黄间隐人也少时慕朱家郭解为人闾里之侠皆宗之稍壮折节读书欲以此驰骋当世然终不遇晚乃遁于光黄间曰岐亭庵居蔬食不与世相闻弃车马毁冠服徒步往来山中人莫识也见其所著帽方屋而高曰「此岂古方山冠之遗像乎」因谓之方山子余谪居于黄过岐亭适见焉曰「呜呼此吾故人陈慥季常也何为而在此」方山子亦矍然问余所以至此者余告之故俯而不答仰而笑呼余宿其家环堵萧然而妻子奴婢皆有自得之意余既耸然异之独念方山子少时使酒好剑用财如粪土前十有九年余在岐山见方山子从两骑挟二矢游西山鹊起于前使骑逐而射之不获方山子怒马独出一发得之因与余马上论用兵及古今成败自谓一世豪士今几日耳精悍之色犹见于眉间而岂山中之人哉然方山子世有勋阀当得官使从事于其间今已显闻而其家在洛阳园宅壮丽与公侯等河北有田岁得帛千匹亦足以富乐皆弃不取独来穷山中此岂无得而然哉余闻光黄间多异人往往阳狂垢污不可得而见方山子傥见之欤", "方山子，是光州、黄州之间的隐士。年轻时仰慕朱家、郭解的为人，乡里的侠士都尊崇他。稍壮年，改变志节读书，想以此驰骋于当世，然而终究不遇。晚年就隐遁于光州、黄州之间，叫岐亭的地方。住草庵吃素食，不与世人往来。抛弃车马，毁弃冠服，徒步往来山中，没有人认识他。见他戴的帽子，方形高耸，说：「这难道是古代方山冠遗留的样子吗？」因此叫他方山子。\n我被贬居住在黄州，经过岐亭，恰好见到他。我说：「唉！这是我的老朋友陈慥字季常啊，为什么在这里？」方山子也吃惊地问我来这里的原因。我告诉了他缘故。他低头不回答，抬头大笑，叫我住在他家。四壁空荡，而妻子奴婢都有自得的神气。我既已惊异地看待他。\n独自回想方山子少年时，纵酒好剑，用钱如粪土。十九年前，我在岐山，见方山子带着两个骑从，挟着两支箭，游西山。鹊鸟在前面飞起，让骑从去追射，没有射到。方山子催马独自冲出，一箭射中。于是和我在马上谈论用兵以及古今成败，自称一代豪士。如今才几天，精悍的神色，还在眉间显现，难道是山中的人吗？\n然而方山子家世有勋功，应当得到官职，如果从事官场，如今已经显达闻名。而他的家在洛阳，园宅壮丽，与公侯相等。河北有田，每年得帛千匹，也足以富足快乐。都抛弃不取，独独来到穷山之中，这难道是没有心得而这样的吗？\n我听说光州、黄州之间多奇人，往往装疯污浊，不能见到，方山子或许见到过他们吧？"],
    [160, "classic-gw-116", "public-domain", "六国破灭非兵不利战不善弊在赂秦赂秦而力亏破灭之道也或曰六国互丧率赂秦耶曰不赂者以赂者丧盖失强援不能独完故曰弊在赂秦也秦以攻取之外小则获邑大则得城较秦之所得与战胜而得者其实百倍诸侯之所亡与战败而亡者其实亦百倍则秦之所大欲诸侯之所大患固不在战矣思厥先祖父暴霜露斩荆棘以有尺寸之地子孙视之不甚惜举以予人如弃草芥今日割五城明日割十城然后得一夕安寝起视四境而秦兵又至矣然则诸侯之地有限暴秦之欲无厌奉之弥繁侵之愈急故不战而强弱胜负已判矣至于颠覆理固宜然古人云「以地事秦犹抱薪救火薪不尽火不灭」此言得之呜呼以赂秦之地封天下之谋臣以事秦之心礼天下之奇才并力西向则吾恐秦人食之不得下咽也悲夫有如此之势而为秦人积威之所劫日削月割以趋于亡为国者无使为积威之所劫哉", "六国的灭亡，不是因为武器不锋利，仗打得不好，弊病在于贿赂秦国。贿赂秦国，自己的国力就亏损，这就是灭亡的原因。有人说：六国相继灭亡，都是因为贿赂秦国吗？回答是：不贿赂秦国的国家因为贿赂秦国的国家而灭亡，因为失去了强大的援助，不能单独保全自己。所以说弊病在于贿赂秦国。\n秦国除了用战争夺取土地以外，小的能得到邑镇，大的能得到城池。比较秦国受贿赂所得到的土地，与战胜而得到的土地，实际上要多到百倍；诸侯贿赂秦国所丧失的土地，与战败所丧失的土地，实际上也要多到百倍。那么秦国最大的欲望，诸侯最大的祸患，本来就不在于战争了。回想他们的祖辈父辈，冒着霜露，披荆斩棘，才得到很少的土地。子孙对待这些土地却不很爱惜，拿来送给别人，好像丢弃小草一样。今天割让五座城，明天割让十座城，然后才能得到一夜的安稳觉。可是第二天起来看看四周边境，秦国的军队又到了。既然这样，那么诸侯的土地有限，强暴的秦国的欲望没有满足，诸侯送给秦国的越多，秦国侵犯得就越急。所以不用作战，谁强谁弱谁胜谁负就已经分清楚了。最终走向灭亡，道理本来就应该这样。古人说：「用土地侍奉秦国，就好像抱着柴去救火，柴不烧完，火就不会熄灭。」这话说对了。\n唉！如果六国用贿赂秦国的土地封赏天下的谋臣，用侍奉秦国的心意礼遇天下的奇才，合力向西对付秦国，那么我恐怕秦国人吃饭都不能咽下去。可悲啊！有这样的形势，却被秦国积久而成的威势所胁迫，天天削减，月月割让，以至于走向灭亡。治理国家的人不要被积久而成的威势所胁迫啊！"],
    [161, "classic-gw-128", "public-domain", "太尉执事辙生好为文思之至深以为文者气之所形然文不可以学而能气可以养而致孟子曰「我善养吾浩然之气」今观其文章宽厚宏博充乎天地之间称其气之小大太史公行天下周览四海名山大川与燕赵间豪俊交游故其文疏荡颇有奇气此二子者岂尝执笔学为如此之文哉其气充乎其中而溢乎其貌动乎其言而见乎其文而不自知也辙生十有九年矣其居家所与游者不过其邻里乡党之人所见不过数百里之间无高山大野可登览以自广百氏之书虽无所不读然皆古人之陈迹不足以激发其志气恐遂汩没故决然舍去求天下奇闻壮观以知天地之广大过秦汉之故都恣观终南嵩华之高北顾黄河之奔流慨然想见古之豪杰至京师仰观天子宫阙之壮与仓廪府库城池苑囿之富且大也而后知天下之巨丽见翰林欧阳公听其议论之宏辩观其容貌之秀伟与其门人贤士大夫游而后知天下之文章聚乎此也太尉以才略冠天下天下之所恃以无忧四夷之所惮以不敢发入则周公召公出则方叔召虎而辙也未之见焉且夫人之学也不志其大虽多而何为辙之来也于山见终南嵩华之高于水见黄河之大且深于人见欧阳公而犹以为未见太尉也故愿得观贤人之光耀闻一言以自壮然后可以尽天下之大观而无憾者矣", "太尉阁下：我生性喜欢写文章，思考这件事很深入。我认为文章是人的气质的显现，然而文章不是单靠学习就能写好的，气质却可以通过修养而得到。孟子说：「我善于培养我的浩然之气。」现在看他的文章，宽厚宏博，充塞于天地之间，与他的气质的大小相称。太史公司马迁走遍天下，遍览四海的名山大川，和燕、赵一带的豪杰交游，所以他的文章疏放洒脱，颇有奇伟之气。这两个人，难道曾经执笔学习写这样的文章吗？他们的气质充满内心而流露于外貌，发之于言语而表现为文章，自己却并不知道。\n我已经十九岁了。在家时所交往的，不过是邻里乡党的人；所见过的不过是几百里之间的事物，没有高山旷野可以登临游览来开阔自己的心胸；诸子百家的书，虽然没有不读的，然而都是古人的陈迹，不足以激发自己的志气。我担心就此沉沦埋没，所以断然离开家乡，去寻求天下的奇闻壮观，来了解天地的广大。经过秦、汉的故都，尽情观赏终南山、嵩山、华山的高峻，向北眺望黄河的奔流，感慨地想象古代豪杰的风采。到了京城，仰望皇帝宫殿的壮丽，以及粮仓、府库、城池、苑囿的富足和宏大，然后才知道天下的雄伟壮丽。见到翰林欧阳公，听他的议论宏辩，看他的容貌秀伟，和他的门人贤士大夫交游，然后才知道天下的文章都聚集在这里。\n太尉凭才干谋略为天下第一，天下人依靠您而无忧，四方夷狄畏惧您而不敢发难，在朝廷就像周公、召公，出征就像方叔、召虎，可是我还没有见到您。况且人的学习，如果不立志于大的方面，即使学得多又有什么用呢？我这次来，在山方面见到了终南山、嵩山、华山的高峻，在水方面见到了黄河的广大和深邃，在人方面见到了欧阳公，却还认为没有见到太尉。所以希望能看到贤人的风采，听您一句话来激励自己，然后才可以算穷尽了天下的大观而没有遗憾了。"],
    [162, "guwen-gwj-211", "", "江出西陵始得平地其流奔放肆大南合湘沅北合汉沔其势益张至于赤壁之下波流浸灌与海相若清河张君梦得谪居齐安即其庐之西南为亭以览观江流之胜而余兄子瞻名之曰「快哉」盖亭之所见南北百里东西一舍涛澜汹涌风云开阖昼则舟楫出没于其前夜则鱼龙悲啸于其下变化倏忽动心骇目不可久视今乃得玩之几席之上举目而足西望武昌诸山冈陵起伏草木行列烟消日出渔夫樵父之舍皆可指数此其所以为「快哉」者也至于长洲之滨故城之墟曹孟德孙仲谋之所睥睨周瑜陆逊之所骋骛其流风遗迹亦足以称快世俗昔楚襄王从宋玉景差于兰台之宫有风飒然至者王披襟当之曰「快哉此风寡人所与庶人共者耶」宋玉曰「此独大王之雄风耳庶人安得共之」玉之言盖有讽焉夫风无雌雄之异而人有遇不遇之变楚王之所以为乐与庶人之所以为忧此则人之变也而风何与焉士生于世使其中不自得将何往而非病使其中坦然不以物伤性将何适而非快今张君不以谪为患窃会计之余功而自放山水之间此其中宜有以过人者将蓬户瓮牖无所不快而况乎濯长江之清流揖西山之白云穷耳目之胜以自适也哉不然连山绝壑长林古木振之以清风照之以明月此皆骚人思士之所以悲伤憔悴而不能胜者乌睹其为快也哉元丰六年十一月朔日赵郡苏辙记", "长江流出西陵峡，才得到平地，它的水流奔放浩大。南面汇合湘水、沅水，北面汇合汉水、沔水，它的气势更加扩张。到了赤壁之下，波涛浸灌，与大海相似。清河张梦得君贬居齐安，在他的住所西南建亭，用来观赏江流的胜景，而我的哥哥子瞻给它命名为「快哉」。\n在亭中所见的，南北百里，东西三十里。波涛汹涌，风云开合。白天船只在它前面出没，夜里鱼龙在它下面悲啸。变化迅速，动心骇目，不能久看。如今却能在几席之上赏玩，举目就可看尽。向西望武昌的群山，冈陵起伏，草木成行，烟雾消散太阳出来，渔夫樵夫的茅舍，都可以一一指点。这就是它成为「快哉」的原因。至于长洲的岸边，故城的废墟，是曹孟德、孙仲谋所窥视的，周瑜、陆逊所驰骋的，他们的流风遗迹，也足以使世俗称快。\n从前楚襄王带着宋玉、景差在兰台之宫，有风飒飒吹来，襄王敞开衣襟迎着它，说：「快哉这风！这是我与百姓共有的吧？」宋玉说：「这只是大王的雄风罢了，百姓怎么能共有呢！」宋玉的话大概有讽喻。风没有雌雄的差异，而人有遇与不遇的变化。楚王之所以为乐，与百姓之所以为忧，这是人的变化，与风有什么关系呢？士人生在世上，如果内心不能自得，将往哪里而不困苦？如果内心坦然，不因外物伤害本性，将往哪里而不快乐？\n如今张君不把贬谪当作忧患，偷取办理公务的余暇，而放任自己于山水之间，这他内心应该有超过别人的地方。即使住在蓬门瓮牖之中，也没有不快乐的；何况在长江的清流中洗浴，与西山的白云作揖，穷尽耳目的胜景来自我适意呢！不然，连绵的山峦绝壑，长林古木，用清风来吹动它，用明月来照耀它，这都是诗人忧思之士悲伤憔悴而不能承受的，哪里看得出它是快乐呢！\n元丰六年十一月初一，赵郡苏辙记。"],
    [163, "guwen-gwj-212", "", "去秋人还蒙赐书及所撰先大父墓碑铭反覆观诵感与惭并夫铭志之著于世义近于史而亦有与史异者盖史之于善恶无所不书而铭者盖古之人有功德材行志义之美者惧后世之不知则必铭而见之或纳于庙或存于墓一也苟其人之恶则于铭乎何有此其所以与史异也其辞之作所以使死者无有所憾生者得致其严而善人喜于见传则勇于自立恶人无有所纪则以愧而惧至于通材达识义烈节士嘉言善状皆见于篇则足为后法警劝之道非近乎史其将安近及世之衰为人之子孙者一欲褒扬其亲而不本乎理故虽恶人皆务勒铭以夸后世立言者既莫之拒而不为又以其子孙之情也书其恶焉则人情之所不得于是乎铭始不实后之作铭者常观其人苟托之非人则书之非公与是则不足以行世而传后故千百年来公卿大夫至于里巷之士莫不有铭而传者盖少其故非他托之非人书之非公与是故也然则孰为其人而能尽公与是欤非畜道德而能文章者无以为也盖有道德者之于恶人则不受而铭之于众人则能辨焉而人之行有情善而迹非有意奸而外淑有善恶相悬而不可以实指有实大于名有名侈于实犹之用人非畜道德者恶能辨之不惑议之不徇不惑不徇则公且是矣而其辞之不工则世犹不传于是又在其文章兼胜焉故曰非畜道德而能文章者无以为也岂非然哉然畜道德而能文章者虽或并世而有亦或数十年或一二百年而有之其传之难如此其遇之难又如此若先生之道德文章固所谓数百年而有者也先祖之言行卓卓幸遇而得铭其公与是其传世行后无疑也而世之学者每观传记所书古人之事至于所可感则往往衋然不知涕之流落也况其子孙也哉况巩也哉其追睎祖德而思所以传之之由则知先生推一赐于巩而及其三世其感与报宜若何而图之抑又思若巩之浅薄滞拙而先生进之先祖之屯蹶否塞以死而先生显之则世之魁闳豪杰不世出之士其谁不愿进于门潜遁幽抑之士其谁不有望于世善谁不为而恶谁不愧以惧为人之父祖者孰不欲教其子孙为人之子孙者孰不欲宠荣其父祖此数美者一归于先生既拜赐之辱且敢进其所以然所谕世族之次敢不承教而加详焉愧甚不宣巩再拜", "去年秋天人回来，承蒙赐信以及所撰先祖父的墓碑铭。反复观诵，感激与惭愧并集。铭志的显扬于世，意义近于史，而也有与史不同的地方。史对于善恶，无所不书；而铭，是古代有功德材行志义之美的人，怕后世不知道，就一定刻铭来显扬。有的纳入庙中，有的存在墓里，是一样的。如果那人是恶人，那么在铭里有什么可写？这就是它与史不同的地方。铭辞的写作，是用来使死者没有遗憾，生者能表达他的敬意。而善人乐于被传扬，就勇于自立；恶人没有什么可记载，就因此羞愧恐惧。至于通才达识，义烈节士，美好的言辞善良的行状，都见于篇中，就足以成为后世的法则。警戒劝勉的道理，不是近于史，又将近于什么呢？\n到了世道衰微，做人家子孙的，一味想褒扬他的亲人，而不根据道理。所以即使是恶人，都力求刻铭，来向后世夸耀。立言的人既不拒绝而不写，又因为他子孙的情面，写上他的恶，就是人情所不能的，于是铭开始不实。后来作铭的人，常常观察那人。如果托付的不是合适的人，那么写出来不公正不真实，就不足以行世传后。所以千百年来，公卿大夫至于里巷之士，没有不有铭的，而传下来的大概很少。它的原因不是别的，是托付的不是合适的人，写出来不公正不真实的缘故。\n那么谁是合适的人而能完全公正真实呢？不是蓄养道德而擅长文章的人不能做到。有道德的人对于恶人，就不接受而为他作铭，对于众人就能辨别。而人的行为，有情善而事迹不善的，有内心奸邪而外表善良的，有善恶相差而不能实指的，有实大于名的，有名过于实的。如同用人，不是蓄养道德的人，怎能辨别得不迷惑，议论得不徇私？不迷惑不徇私，就公正真实了。而他的文辞不工，那么世上还是不能流传。于是又在于他的文章兼胜。所以说不是蓄养道德而擅长文章的人不能做到。难道不是这样吗？\n然而蓄养道德而擅长文章的人，虽然或许同时代有，也或许数十年或一二百年才有。它传世的难如此，它相遇的难又如此。像先生的道德文章，本来就是所谓数百年才有的。先祖的言行卓绝，幸而遇到而得到铭，它的公正真实，它的传世行后是无疑的。而世上的学者，每次看传记所写古人的事，到了可感动的地方，就往往伤痛得不知涕泪流落，何况他的子孙呢？何况曾巩呢？追念仰慕祖德而思考所以传扬的缘故，就知道先生推一份恩赐给曾巩而施及三代。那感激与报答，应该怎样来谋划呢？\n又想到像曾巩的浅薄滞拙，而先生提拔他；先祖的困顿不通而死，而先生显扬他。那么世上魁伟豪杰不世出的士人，谁不愿意进到门下？潜隐幽抑的士人，谁不对世道有望？善谁不去做，而恶谁不羞愧恐惧？做人家父祖的，谁不想教导他的子孙？做人家子孙的，谁不想使他的父祖荣耀？这几种美德，都归于先生。既已拜受恩赐的屈辱，且敢陈述其中的缘故。所告知的世族次序，怎敢不承教而更加详审呢？惭愧得很，不尽所言。曾巩再拜。"],
    [164, "guwen-gwj-213", "", "赵郡苏轼余之同年友也自蜀以书至京师遗余称蜀之士曰黎生安生者既而黎生携其文数十万言安生携其文亦数千言辱以顾余读其文诚闳壮隽伟善反复驰骋穷尽事理而其材力之放纵若不可极者也二生固可谓魁奇特起之士而苏君固可谓善知人者也顷之黎生补江陵府司法参军将行请予言以为赠余曰「余之知生既得之于心矣乃将以言相求于外邪」黎生曰「生与安生之学于斯文里之人皆笑以为迂阔今求子之言盖将解惑于里人」余闻之自顾而笑夫世之迂阔孰有甚于予乎知信乎古而不知合乎世知志乎道而不知同乎俗此余所以困于今而不自知也世之迂阔孰有甚于予乎今生之迂特以文不近俗迂之小者耳患为笑于里之人若余之迂大矣使生持吾言而归且重得罪庸讵止于笑乎然则若余之于生将何言哉谓余之迂为善则其患若此谓为不善则有以合乎世必违乎古有以同乎俗必离乎道矣生其无急于解里人之惑则于是焉必能择而取之遂书以赠二生并示苏君以为何如也", "赵郡苏轼，是我的同年好友。他从蜀地写信到京城给我，称赞蜀地的士人叫黎生、安生的。不久黎生带着他的文章数十万字，安生带着他的文章也有数千字，屈尊来看我。读他们的文章，确实宏壮俊伟，善于反复驰骋，穷尽事理；而他们才力的放纵，像不可穷尽。二生固然可以说是魁奇特出之士，而苏君固然可以说是善于知人的人。\n不久，黎生补任江陵府司法参军，将要出行，请我写几句话作为赠言。我说：「我对二生的了解，已经在心里得到了，却还要用言语向外求取吗？」黎生说：「我和安生学这种文章，乡里的人都笑我们迂阔。如今求您的赠言，是想用来向乡里人解惑。」我听了，看看自己而笑了。\n世上迂阔的，谁比得上我呢？只知道信奉古人，而不知道迎合当世；只知道志于道，而不知道同于流俗。这就是我困于今日而不自知的原因。世上迂阔的，谁比得上我呢？如今二生的迂，只是因为文章不近流俗，是迂的小者罢了，忧虑的是被乡里人笑话。像我的迂就大了，假使二生拿着我的话回去，将要更加获罪，岂止是被笑话呢？那么像我对于二生，将说什么呢？说我的迂是好的，那么它的祸患如此；说是不好的，那么有以迎合当世，一定违背古人，有以同于流俗，一定背离道了。二生不要急于解乡里人的疑惑，那么在这里一定能选择而取舍。于是写下来赠给二生，并给苏君看，认为怎么样呢。"],
    [165, "guwen-gwj-214", "", "世皆称孟尝君能得士士以故归之而卒赖其力以脱于虎豹之秦嗟乎孟尝君特鸡鸣狗盗之雄耳岂足以言得士不然擅齐之强得一士焉宜可以南面而制秦尚何取鸡鸣狗盗之力哉夫鸡鸣狗盗之出其门此士之所以不至也", "世人都称孟尝君能招致士人，士人因此归附他，而终于依靠他们的力量从虎豹般的秦国逃脱。唉！孟尝君不过是鸡鸣狗盗之徒的首领罢了，哪里够得上说能得士？不是这样的话，凭齐国的强大，得到一个真正的士人，就应该可以南面称王而制服秦国，还何必取用鸡鸣狗盗的力量呢？鸡鸣狗盗之徒出于他的门下，这就是真正的士人不来的原因。"],
    [166, "guwen-gwj-215", "", "江之南有贤人焉字子固非今所谓贤人者予慕而友之淮之南有贤人焉字正之非今所谓贤人者予慕而友之二贤人者足未尝相过也口未尝相语也辞币未尝相接也其师若友岂尽同哉予考其言行其不相似者何其少也曰学圣人而已矣学圣人则其师若友必学圣人者圣人之言行岂有二哉其相似也适然予在淮南为正之道子固正之不予疑也还江南为子固道正之子固亦以为然予又知所谓贤人者既相似又相信不疑也子固作怀友一首遗予其大略欲相扳以至乎中庸而后已正之盖亦常云尔夫安驱徐行轥中庸之庭而造于其堂舍二贤人者而谁哉予昔非敢自必其有至也亦愿从事于左右焉尔辅而进之其可也噫官有守私有系会合不可以常也作同学一首别子固以相警且相慰云", "江南有位贤人，字子固，不是如今所谓的贤人，我仰慕而与他交友。淮南有位贤人，字正之，不是如今所谓的贤人，我仰慕而与他交友。这两位贤人，脚未曾互相拜访，口未曾互相交谈，书信礼物未曾互相往来。他们的师友，难道都相同吗？我考察他们的言行，其中不相似的，多么少啊！回答说：学习圣人罢了。学习圣人，那么他们的师友，一定是学习圣人的。圣人的言行，难道有两个吗？他们的相似是当然的。\n我在淮南，向正之说起子固，正之不怀疑我。回到江南，向子固说起正之，子固也认为对。我又知道所谓贤人，既相似，又相信不疑。\n子固作《怀友》一首赠我，大略想互相援引以达到中庸然后才止。正之大概也常这样说。安稳地驾车慢慢行走，碾过中庸的庭院，而进入它的堂室，除了这两位贤人还有谁呢？我从前不敢自必能有达到，也愿意在左右从事罢了。辅助而推进它，大概可以。\n唉！官职有职守，私事有牵累，会合不能常有。作《同学一首别子固》，来互相警戒并且互相安慰。"],
    [167, "classic-gw-117", "public-domain", "褒禅山亦谓之华山唐浮图慧褒始舍于其址而卒葬之以故其后名之曰褒禅今所谓慧空禅院者褒之庐冢也距其院东五里所谓华山洞者以其乃华山之阳名之也距洞百余步有碑仆道其文漫灭独其为文犹可识曰花山今言华如华实之华者盖音谬也其下平旷有泉侧出而记游者甚众所谓前洞也由山以上五六里有穴窈然入之甚寒问其深则其好游者不能穷也谓之后洞余与四人拥火以入入之愈深其进愈难而其见愈奇有怠而欲出者曰「不出火且尽」遂与之俱出盖余所至比好游者尚不能十一然视其左右来而记之者已少盖其又深则其至又加少矣方是时余之力尚足以入火尚足以明也既其出则或咎其欲出者而余亦悔其随之而不得极夫游之乐也于是余有叹焉古人之观于天地山川草木虫鱼鸟兽往往有得以其求思之深而无不在也夫夷以近则游者众险以远则至者少而世之奇伟瑰怪非常之观常在于险远而人之所罕至焉故非有志者不能至也有志矣不随以止也然力不足者亦不能至也有志与力而又不随以怠至于幽暗昏惑而无物以相之亦不能至也然力足以至焉于人为可讥而在己为有悔尽吾志也而不能至者可以无悔矣其孰能讥之乎此余之所得也", "褒禅山也称为华山。唐代和尚慧褒当初在这里筑舍定居，死后就葬在这里；因为这个缘故，后人就称此山为褒禅山。现在人们所说的慧空禅院，就是慧褒的弟子在慧褒墓旁盖的屋舍。距离那禅院东边五里，是人们所说的华山洞，因为它在华山的南面而这样命名。距离山洞一百多步，有一块石碑倒在路旁，上面的文字已经模糊不清，只有从它残存的字迹中还可以辨认出「花山」二字。现在把「华」读为「华实」的「华」，原来是读音错了。\n由此向下的那个山洞平坦而空阔，有一股山泉从旁边涌出，在这里游览、题记的人很多，这就是人们所说的前洞。由山路向上走五六里，有一个洞穴，幽深昏暗，走进去感到寒气逼人，问它的深度，就是那些喜欢游览的人也不能走到尽头，人们称它为后洞。我和四个人拿着火把走进去，进洞越深，前进越困难，然而见到的景象越奇特。有松懈懈怠想要退出去的伙伴说：「再不出去，火把就要烧完了。」于是跟他一起退了出来。大概我所到达的地方，比那些喜欢游览的人来比，还不到十分之一，然而看看那左右的石壁，来到这里题字记游的人已经很少了。大概那洞内更深的地方，到达的人就更少了。当决定从洞中退出的时候，我的体力还足够前进，火把还足够照明。我们出洞以后，就有人责怪那个主张退出去的人，我也后悔自己跟他出来，而未能极尽游洞的乐趣。\n于是我有所感慨。古人观察天地、山川、草木、虫鱼、鸟兽，往往有所得，是因为他们探究、思考得深入而且广泛。那平坦而又近的地方，前来游览的人便多；危险而又远的地方，前来游览的人便少。但是世上奇妙雄伟、珍异奇特、非同寻常的景象，常常在那险阻而又僻远的地方，是人们很少到达的，所以没有志向的人是不能到达的。有了志向，也不随从别人而停止前进，但是体力不够的人，也是不能到达的。有了志向和体力，又不随从别人而有所懈怠，到了那幽深昏暗、令人迷惑的地方却没有外物来帮助他，也不能到达。然而体力足以到达却没有到达，在别人看来是可以讥笑的，在自己来说也是有所悔恨的；尽了自己的主观努力而未能达到，便可以无所悔恨，难道谁还能讥笑他吗？这就是我这次游山的收获。"],
    [168, "guwen-gwj-216", "", "君讳平字秉之姓许氏余尝谱其世家所谓今泰州海陵县主簿者也君既与兄元相友爱称天下而自少卓荦不羁善辩说与其兄俱以智略为当世大人所器宝元时朝廷开方略之选以招天下异能之士而陕西大帅范文正公郑文肃公争以君所为书以荐于是得召试为太庙斋郎已而选泰州海陵县主簿贵人多荐君有大才可试以事不宜弃之州县君亦尝慨然自许欲有所为然终不得一用其智能以卒噫其可哀也已士固有离世异俗独行其意骂讥笑侮困辱而不悔彼皆无众人之求而有所待于后世者也其龃龉固宜若夫智谋功名之士窥时俯仰以赴势物之会而辄不遇者乃亦不可胜数辩足以移万物而穷于用说之时谋足以夺三军而辱于右武之国此又何说哉嗟乎彼有所待而不悔者其知之矣君年五十九以嘉祐某年某月某甲子葬真州之扬子县甘露乡某所之原夫人李氏子男瑰不仕璋真州司户参军琦太庙斋郎琳进士女子五人已嫁二人进士周奉先泰州泰兴县令陶舜元铭曰有拔而起之莫挤而止之呜呼许君而已于斯谁或使之", "君名平，字秉之，姓许。我曾编次他的家世，就是如今所谓泰州海陵县主簿的人。君既与哥哥许元以友爱著称天下，而从少年时就卓荦不羁，善于辩说，与他的哥哥都因智略被当世的大人所器重。宝元年间，朝廷开设方略之选，来招揽天下有异能的人士，而陕西大帅范文正公、郑文肃公，争着把君所写的书来推荐，因此得以召试，做太庙斋郎，不久选为泰州海陵县主簿。权贵多推荐君有大才，可以用事来试，不应该弃置在州县。君也曾慷慨自许，想有所作为。然而终究不能一用他的智能就去世了。唉！真是可哀啊。\n士人固然有离世异俗，独行其意，遭受骂讥、笑侮、困辱而不悔的。他们都没有众人的欲求，而有所期待于后世，他们与世不合是当然的。至于智谋功名之士，窥伺时机俯仰，去迎合权势事物的机会，而每每不遇的，却也数不胜数。辩才足以移易万物，却在需要游说的时代困穷；谋略足以夺取三军，却在崇尚武功的国家受辱，这又怎么说呢？唉！那些有所期待而不悔的人，大概是知道的了。\n君年五十九，在嘉祐某年某月某日，葬在真州扬子县甘露乡某处的原野。夫人李氏。子男：许瑰，不做官；许璋，真州司户参军；许琦，太庙斋郎；许琳，进士。女子五人，已嫁二人，嫁给进士周奉先、泰州泰兴县令陶舜元。\n铭说：有人提拔而举起他，没有谁排挤而阻止他。唉，许君！就此中止，是谁使他这样呢？"],
    [169, "guwen-gwj-142", "public-domain", "西南山水惟川蜀最奇然去中州万里陆有剑阁栈道之险水有瞿塘滟滪之虞跨马行则竹间山高者累旬日不见其巅际临上而俯视绝壑万仞杳莫测其所穷肝胆为之悼栗水行则江石悍利波恶涡诡舟一失势尺寸辄糜碎土沉下饱鱼鳖其难至如此故非仕有力者不可以游非材有文者纵游无所得非壮强者多老死于其地嗜奇之士恨焉天台陈君庭学能为诗由中书左司掾屡从大将北征有劳擢四川都指挥司照磨由水道至成都成都川蜀之要地扬子云司马相如诸葛武侯之所居英雄俊杰战攻驻守之迹诗人文士游眺饮射赋咏歌呼之所庭学无不历览既览必发为诗以纪其景物时世之变于是其诗益工越三年以例自免归会予于京师其气愈充其语愈壮其志意愈高盖得于山水之助者侈矣予甚自愧方予少时尝有志于出游天下顾以学未成而不暇及年壮方可出而四方兵起无所投足逮今圣主兴而宇内定极海之际合为一家而予齿益加耄矣欲如庭学之游尚可得乎然吾闻古之贤士若颜回原宪皆坐守陋室蓬蒿没户而志意常充然有若囊括于天地者此其故何也得无有出于山水之外者乎庭学其试归而求焉苟有所得则以告予予将不一愧而已也", "西南的山水，只有川蜀最奇特。然而离中州万里，陆路有剑阁栈道的险阻，水路有瞿塘、滟滪的忧虑。骑马而行，那么竹林高山，接连几十天看不到它的顶端。登上去俯视，绝壁万仞，深不可测到底，肝胆为之战栗。水路而行，那么江石凶猛锋利，波涛险恶、漩涡诡谲，船一旦失势尺寸，就粉碎沉没，下去喂饱鱼鳖。它的难到如此。所以不是做官而有力量的，不可以游；不是有才而有文采的，纵使游也没有收获；不是强壮的人，大多老死在那里。嗜好奇异的人为之遗憾。\n天台的陈庭学君，能作诗，由中书左司掾，屡次跟从大将北征，有功劳，被提升为四川都指挥司照磨，经水路到成都。成都，是川蜀的要地，扬子云、司马相如、诸葛武侯所居住的地方，英雄俊杰战攻驻守的遗迹，诗人文士游览饮酒射箭赋诗歌唱的地方，庭学没有不遍览的。既已游览必定发为诗，来记录那里景物时世的变化，于是他的诗更加工巧。过了三年，按例自请免官归乡，在京城会到我。他的气更加充沛，他的话更加豪壮，他的志意更加高远，大概得于山水的帮助很多。\n我很觉惭愧，当我年少时，曾经有志于出游天下，只因学业未成而没有空闲。到年壮才可以出去，而四方兵起，无处落脚。直到如今圣主兴起而宇内安定，极海之际，合为一家，而我的年纪更加老了。想如庭学那样游览，还能得到吗？\n然而我听说古代的贤士，像颜回、原宪，都坐守陋室，蓬蒿没门，而志意常常充沛，好像囊括天地一样。这是什么缘故呢？莫非有出于山水之外的东西吗？庭学大概可以回去寻求它？如果有所得，就告诉我，我将不止惭愧一次而已。"],
    [170, "guwen-gwj-143", "public-domain", "金陵为帝王之州自六朝迄于南唐类皆偏据一方无以应山川之王气逮我皇帝定鼎于兹始足以当之由是声教所暨罔间朔南存神穆清与天同体虽一豫一游亦可为天下后世法京城之西北有狮子山自卢龙蜿蜒而来长江如虹贯蟠绕其下上以其地雄胜诏建楼于巅与民同游观之乐遂锡嘉名为「阅江」云登览之顷万象森列千载之秘一旦轩露岂非天造地设以俟大一统之君而开千万世之伟观者欤当风日清美法驾幸临升其崇椒凭阑遥瞩必悠然而动遐思见江汉之朝宗诸侯之述职城池之高深关阨之严固必曰「此朕栉风沐雨战胜攻取之所致也」中夏之广益思有以保之见波涛之浩荡风帆之上下番舶接迹而来庭蛮琛联肩而入贡必曰「此朕德绥威服覃及外内之所及也」四陲之远益思所以柔之见两岸之间四郊之上耕人有炙肤皲足之烦农女有捋桑行馌之勤必曰「此朕拔诸水火而登于衽席者也」万方之民益思有以安之触类而思不一而足臣知斯楼之建皇上所以发舒精神因物兴感无不寓其致治之思奚止阅夫长江而已哉彼临春结绮非弗华矣齐云落星非不高矣不过乐管弦之淫响藏燕赵之艳姬一旋踵间而感慨系之臣不知其为何说也虽然长江发源岷山委蛇七千余里而始入海白涌碧翻六朝之时往往倚之为天堑今则南北一家视为安流无所事乎战争矣然则果谁之力欤逢掖之士有登斯楼而阅斯江者当思帝德如天荡荡难名与神禹疏凿之功同一罔极忠君报上之心其有不油然而兴者耶臣不敏奉旨撰记欲上推宵旰图治之切者勒诸贞珉他若留连光景之辞皆略而不陈惧亵也", "金陵是帝王之州。从六朝直到南唐，大抵都偏据一方，没有能承应山川的王气。直到我们皇帝，在这里定都，才足以承当它。因此声教所到，不分南北；存神穆清，与天同体。即使一次游乐，也可以为天下后世效法。京城的西北有狮子山，从卢龙蜿蜒而来。长江像白虹贯穿，盘绕在它下面。皇上因为这地方雄胜，下诏在山顶建楼，同百姓共享游览观光的快乐，于是赐美名为「阅江」。\n登临观览之际，万象森列，千年的隐秘，一旦显露。难道不是天造地设，来等待大一统的君主，而开启千万世的伟观吗？当风日清美，御驾幸临，登上高顶，凭栏远望，必定悠然而生遐想。看见江汉的朝宗，诸侯的述职，城池的高深，关隘的严固，必定说：「这是我栉风沐雨、战胜攻取所得到的。」中夏的广大，更加想着怎样保全它。看见波涛的浩荡，风帆的上下，外国船舶接踵而来朝，蛮邦珍宝联肩而入贡，必定说：「这是我以德安抚、以威慑服，遍及内外所达到的。」四陲的遥远，更加想着怎样安抚它。看见两岸之间、四郊之上，耕田的人有晒破皮肤、冻裂双脚的烦劳，农女有采摘桑叶、送饭到田的辛勤，必定说：「这是我把他们从水火中救出、而使他们安居的人。」万方的百姓，更加想着怎样安定他们。触类而思，不一而足。臣知道这座楼的建造，是皇上用来抒发精神，因物兴感，无不寄寓他致力于治理的思虑，哪里只是观看长江而已呢！\n那临春阁、结绮阁，不是不华美；齐云楼、落星楼，不是不高峻。不过是耽乐管弦的淫靡之音，藏纳燕赵的美艳姬妾，一转眼间就令人感慨，臣不知道它有什么可说的。虽然如此，长江发源岷山，蜿蜒七千余里才入海，白浪翻涌、碧波翻滚，六朝的时候，往往依靠它作为天堑。如今则南北一家，把它看作安流，用不着战争了。那么究竟是谁的力量呢？儒士之中，有登上这座楼而观看这条江的，应当想到皇上的德行如天，浩荡难以名状，同神禹疏凿的功绩一样无穷。忠君报上的心，难道会有不油然而生的吗？\n臣不聪敏，奉旨撰写这篇记。想要向上推崇皇上日夜图治的恳切，刻在美石上。至于其他流连光景的言辞，都省略不陈，怕亵渎。"],
    [171, "guwen-gwj-144", "public-domain", "东陵侯既废过司马季主而卜焉季主曰「君侯何卜也」东陵侯曰「久卧者思起久蛰者思启久懑者思嚏吾闻之蓄极则泄闷极则达热极则风壅极则通一冬一春靡屈不伸一起一伏无往不复仆窃有疑愿受教焉」季主曰「若是则君侯已喻之矣又何卜为」东陵侯曰「仆未究其奥也愿先生卒教之」季主乃言曰「呜呼天道何亲惟德之亲鬼神何灵因人而灵夫蓍枯草也龟枯骨也物也人灵于物者也何不自听而听于物乎且君侯何不思昔者也有昔者必有今日是故碎瓦颓垣昔日之歌楼舞馆也荒榛断梗昔日之琼蕤玉树也露蚕风蝉昔日之凤笙龙笛也鬼磷萤火昔日之金缸华烛也秋荼春荠昔日之象白驼峰也丹枫白荻昔日之蜀锦齐纨也昔日之所无今日有之不为过昔日之所有今日无之不为不足是故一昼一夜华开者谢一秋一春物故者新激湍之下必有深潭高丘之下必有浚谷君侯亦知之矣何以卜为」", "东陵侯被废黜之后，去拜访司马季主而占卜。季主说：「君侯占卜什么呢？」东陵侯说：「长久躺卧的人想起来，长久蛰伏的人想开启，长久烦闷的人想打喷嚏。我听说：蓄积到极点就会宣泄，郁闷到极点就会通达，炎热到极点就会起风，壅塞到极点就会畅通。一冬一春，没有屈而不伸的；一起一伏，没有去而不返的。我私下有疑惑，希望接受指教。」季主说：「像这样，那么君侯已经明白了，又占卜什么呢？」东陵侯说：「我没有探究它的奥秘，希望先生最终指教我。」\n季主于是说：「唉！天道亲近谁？只亲近有德的人；鬼神有什么灵验？因人而灵验。那蓍草，是枯草；龟甲，是枯骨，都是物。人是比物灵的，为什么不听自己而听于物呢？况且君侯为什么不想想从前呢？有从前就必定有今天。所以碎瓦颓垣，是从前的歌楼舞馆；荒榛断梗，是从前的琼花玉树；露中的蚕、风中的蝉，是从前的凤笙龙笛；鬼火萤光，是从前的金缸华烛；秋荼春荠，是从前的象白驼峰；丹枫白荻，是从前的蜀锦齐纨。从前所没有的，今天有了不算过分；从前所有的，今天没有了不算不足。所以一昼一夜，开花的结果凋谢；一秋一春，旧的去新的来。激流之下，必定有深潭；高丘之下，必定有深谷。君侯也知道这个了，为什么还占卜呢？」"],
    [172, "guwen-gwj-145", "public-domain", "杭有卖果者善藏柑涉寒暑不溃出之烨然玉质而金色置于市贾十倍人争鬻之予贸得其一剖之如有烟扑口鼻视其中则干若败絮予怪而问之曰「若所市于人者将以实笾豆奉祭祀供宾客乎将炫外以惑愚瞽也甚矣哉为欺也」卖者笑曰「吾业是有年矣吾赖是以食吾躯吾售之人取之未闻有言而独不足子所乎世之为欺者不寡矣而独我也乎吾子未之思也今夫佩虎符坐皋比者洸洸乎干城之具也果能授孙吴之略耶峨大冠拖长绅者昂昂乎庙堂之器也果能建伊皋之业耶盗起而不知御民困而不知救吏奸而不知禁法斁而不知理坐糜廪粟而不知耻观其坐高堂骑大马醉醇醴而饫肥鲜者孰不巍巍乎可畏赫赫乎可象也又何往而不金玉其外败絮其中也哉今子是之不察而以察吾柑」予默默无以应退而思其言类东方生滑稽之流岂其愤世疾邪者耶而托于柑以讽耶", "杭州有个卖水果的人，善于贮藏柑子，经历寒暑不腐烂。拿出来光灿灿的，玉一样的质地、金一样的颜色。放在市场上，价钱十倍，人们争着买它。\n我买到其中一个，剖开它，像有烟扑向口鼻，看它里面，却干得像破棉絮。我奇怪地问他说：「你所卖给人的，是打算用来盛在笾豆里、供奉祭祀、招待宾客呢？还是炫耀外表来迷惑愚人和盲人呢？太过分了，你这样欺骗！」\n卖的人笑着说：「我干这一行有年头了，我靠这个养活自己。我卖它，人买它，没有听到有话说，而单单不满足您吗？世上做欺骗的事不少了，难道只有我吗？您没有想过。如今佩着虎符、坐在虎皮上的人，雄赳赳像是捍卫国家的将才，果真能传授孙武、吴起的谋略吗？戴着高冠、拖着长带的人，气昂昂像是朝廷的栋梁，果真能建立伊尹、皋陶的功业吗？盗贼兴起而不知道抵御，百姓困苦而不知道救助，官吏奸邪而不知道禁止，法度败坏而不知道治理，坐着耗费俸米而不知道羞耻。看他们坐在高堂，骑着大马，醉饮美酒而饱食肥鲜，谁不巍巍然可畏、赫赫然可效法呢？又哪里不是金玉其外、败絮其中呢？如今您不察这些，却来察我的柑子！」\n我默默地无话可答。退下来想想他的话，类似东方朔滑稽之流。难道他是愤世嫉邪的人吗？而借柑子来讽喻吗？"],
    [173, "guwen-gwj-146", "public-domain", "虑天下者常图其所难而忽其所易备其所可畏而遗其所不疑然而祸常发于所忽之中而乱常起于不足疑之事岂其虑之未周与盖虑之所能及者人事之宜然而出于智力之所不及者天道也当秦之世而灭诸侯一天下而其心以为周之亡在乎诸侯之强耳变封建而为郡县方以为兵革可不复用天子之位可以世守而不知汉帝起陇亩之中而卒亡秦之社稷汉惩秦之孤立于是大建庶孽而为诸侯以为同姓之亲可以相继而无变而七国萌篡弑之谋武宣以后稍剖析之而分其势以为无事矣而王莽卒移汉祚光武之惩哀平魏之惩汉晋之惩魏各惩其所由亡而为之备而其亡也皆出于所备之外唐太宗闻武氏之杀其子孙求人于疑似之际而除之而武氏日侍其左右而不悟宋太祖见五代方镇之足以制其君尽释其兵权使力弱而易制而不知子孙卒困于敌国此其人皆有出人之智盖世之才其于治乱存亡之几思之详而备之审矣虑切于此而祸兴于彼终至乱亡者何哉盖智可以谋人而不可以谋天良医之子多死于病良巫之子多死于鬼岂工于活人而拙于谋子也哉乃工于谋人而拙于谋天也古之圣人知天下后世之变非智虑之所能周非法术之所能制不敢肆其私谋诡计而唯积至诚用大德以结乎天心使天眷其德若慈母之保赤子而不忍释故其子孙虽有至愚不肖者足以亡国而天卒不忍遽亡之此虑之远者也夫苟不能自结于天而欲以区区之智笼络当世之务而必后世之无危亡此理之所必无者而岂天道哉", "考虑天下的人，常常谋划他所难的，而忽略他所易的；防备他所可畏的，而遗漏他所不疑的。然而祸患常常发生在所忽略之中，而变乱常常起于不值得怀疑的事。难道是他的考虑不周全吗？大概考虑所能达到的，是人事所应当如此；而超出智力所不能达到的，是天意。\n在秦朝的时候，灭掉诸侯，统一天下。而它心中认为周朝的灭亡在于诸侯的强大罢了，于是把封建改为郡县。正以为兵器可以不再使用，天子的位置可以世代守住，却不知道汉帝从田野中兴起，而终于灭亡了秦朝的社稷。汉朝吸取秦朝孤立的教训，于是大封庶子为诸侯，以为同姓的亲情可以相继而没有变故，而七国萌生篡位弑君的图谋。武帝、宣帝以后，逐渐分割它们而分散它们的势力，以为没有事了，而王莽终于篡夺了汉朝的帝位。光武帝吸取哀帝、平帝的教训，魏吸取汉的教训，晋吸取魏的教训，各自吸取所由灭亡的原因而加以防备。而它们的灭亡，都出于所防备之外。唐太宗听说武氏将杀他的子孙，就搜求形迹可疑的人而除去，而武氏天天侍候在他左右却不醒悟。宋太祖看到五代藩镇足以挟制他们的君主，就全部解除他们的兵权，使力量弱小容易控制，却不知道子孙终于受困于敌国。这些人都超出常人的智慧、盖世的才能，他们对于治乱存亡的几微，考虑得详尽、防备得周到了。考虑切于这里而祸患发生在那里，终于至于动乱灭亡，为什么呢？大概智谋可以用来谋划人，而不可以用来谋划天。\n良医的儿子，多死于病；良巫的儿子，多死于鬼。难道是擅长救活别人而拙于为自己的儿子谋划吗？是擅长谋划人而拙于谋划天。\n古代的圣人，知道天下后世的变化，不是智虑所能周全，不是法术所能控制，不敢放纵自己的私谋诡计，而只有积累至诚、施行大德来结连天心，使上天眷顾他的德行，像慈母保护婴儿一样不忍放下。所以他的子孙，即使有极其愚笨不成器的足以亡国，而上天终于不忍心骤然使它灭亡。这是考虑得深远的人。如果不能自己结连于天，而想用区区智谋笼络当世的事务，而必定要使后世没有危亡，这是道理上必定没有的，难道是天道吗！"],
    [174, "guwen-gwj-147", "public-domain", "士君子立身事主既名知己则当竭尽智谋忠告善道销患于未形保治于未然俾身全而主安生为名臣死为上鬼垂光百世照耀简策斯为美也苟遇知己不能扶危于未乱之先而乃捐躯殒命于既败之后钓名沽誉眩世炫俗由君子观之皆所不取也盖尝因而论之豫让臣事智伯及赵襄子杀智伯让为之报仇声名烈烈虽愚夫愚妇莫不知其为忠臣义士也呜呼让之死固忠矣惜乎处死之道有未忠者存焉何也观其漆身吞炭谓其友曰「凡吾所以为此者将以愧天下后世之为人臣怀二心者也」谓非忠可乎及观其斩衣三跃襄子责以不死于中行氏而独死于智伯让应曰「中行氏以众人待我我故以众人报之智伯以国士待我我故以国士报之」即此而论让有余憾矣段规之事韩康任章之事魏献未闻以国士待之也而规也章也力劝其主从智伯之请与之地以骄其志而速其亡也郄疵之事智伯亦未尝以国士待之也而疵能察韩魏之情以谏智伯虽不用其言以至灭亡而疵之智谋忠告已无愧于心也让既自谓智伯待以国士矣国士济国之士也当伯请地无厌之日纵欲荒暴之时为让者正宜陈力就列谆谆然而告之曰「诸侯大夫各安分地无相侵夺古之制也今无故而取地于人人不与而吾之忿心必生与之则吾之骄心以起忿必争争必败骄必傲傲必亡」谆切恳至谏不从再谏之再谏不从三谏之三谏不从移其伏剑之死死于是日伯虽顽冥不灵感其至诚庶几复悟和韩魏释赵围保全智宗守其祭祀若然则让虽死犹生也岂不胜于斩衣而死乎让于此时曾无一语开悟主心视伯之危亡犹越人视秦人之肥瘠也袖手旁观坐待成败国士之报曾若是乎智伯既死而乃不胜血气之悻悻甘自附于刺客之流如鱼之醉于饵乌之亡于贪王孙贾之死而无所补况欲以垂光百世乎虽然以国士而论豫让固不足以当矣彼朝为仇敌暮为君臣腆然而自得者又让之罪人也噫", "士君子立身处世、事奉君主，既然称为知己，就应当竭尽智谋，忠告善道，消弭祸患于未形成之时，保全治平于未变乱之前，使自身保全而君主安宁。活着是名臣，死了是上等的鬼，光辉照耀百世，光耀史册，这才是美好的。如果遇到知己，不能扶助危难于未乱之前，却捐躯殒命于已经失败之后；钓名沽誉，眩惑世人，从君子的角度看，都是不可取的。\n曾经因此论说过：豫让做智伯的臣子，到赵襄子杀死智伯，豫让为他报仇。声名烈烈，即使是愚夫愚妇也没有不知道他是忠臣义士的。唉！豫让的死固然忠诚了，可惜他处死的方式有不忠的地方存在。为什么呢？看他漆身吞炭，对他的朋友说：「我之所以这样做，是要使天下后世做臣子而怀有二心的人惭愧。」说他不忠可以吗？等看到他斩衣三跃，襄子责备他不为中行氏而死，却独独为智伯而死。豫让回答说：「中行氏以一般人待我，所以我以一般人报答他；智伯以国士待我，所以我以国士报答他。」就此而论，豫让有遗憾了。\n段规事奉韩康子，任章事奉魏献子，没有听说以国士待他们，而段规、任章，竭力劝他们的君主顺从智伯的请求，给他土地来使他的志气骄纵，而加速他的灭亡。郄疵事奉智伯，也不曾以国士待他；而郄疵能察知韩、魏的情况来劝谏智伯。虽然不被采用他的话，以至于灭亡，而郄疵的智谋忠告，已经无愧于心。豫让既然自己说智伯以国士待他，国士，是救国之士。当智伯索求土地没有满足之日、放纵欲望荒淫暴虐之时，作为豫让，正应当施展才力、就任职位，谆谆地告诉他说：「诸侯大夫，各安于自己的封地，不要互相侵夺，这是自古的制度。如今无故向人索取土地，人不给，那么我们的忿怒之心必定产生；给了，那么我们的骄纵之心就会兴起。忿怒必定争斗，争斗必定失败；骄纵必定傲慢，傲慢必定灭亡。」谆切恳至，劝谏不听，再劝谏；再劝谏不听，第三次劝谏；三次劝谏不听，就把那伏剑而死的事移前，死在当天。智伯即使顽固不灵，感于他的至诚，也许重新醒悟。与韩、魏和好，解除对赵的围困，保全智氏宗族，守住他们的祭祀。如果这样，那么豫让虽然死了也如同活着，难道不胜过斩衣而死吗？豫让在这个时候，竟没有一句话开悟君主的心，看待智伯的危亡，像越人看待秦人的肥瘦一样。袖手旁观，坐待成败，国士的报答，竟是这样吗？智伯既已死了，才忍不住血气的悻悻，甘心自附于刺客之流，像鱼醉于饵，乌死于贪，王孙贾死了而无所补益，何况想光辉照耀百世呢？\n虽然如此，以国士而论，豫让固然不足以承当；那些早晨还是仇敌、晚上就成君臣，厚着脸皮而自得的人，又是豫让的罪人。唉！"],
    [175, "guwen-gwj-148", "public-domain", "易之泰曰「上下交而其志同」其否曰「上下不交而天下无邦」盖上之情达于下下之情达于上上下一体所以为「泰」下之情壅阏而不得上闻上下间隔虽有国而无国矣所以为「否」也交则泰不交则否自古皆然而不交之弊未有如近世之甚者君臣相见止于视朝数刻上下之间章奏批答相关接刑名法度相维持而已非独沿袭故事亦其地势使然何也国家常朝于奉天门未尝一日废可谓勤矣然堂陛悬绝威仪赫奕御史纠仪鸿胪举不如法通政司引奏上特视之谢恩见辞惴惴而退上何尝治一事下何尝进一言哉此无他地势悬绝所谓堂上远于万里虽欲言无由言也愚以为欲上下之交莫若复古内朝之法盖周之时有三朝库门之外为正朝询谋大臣在焉路门之外为治朝日视朝在焉路门之内曰内朝亦曰燕朝玉藻云「君日出而视朝退适路寝听政」盖视朝而见群臣所以正上下之分听政而适路寝所以通远近之情汉制大司马左右前后将军侍中散骑诸吏为中朝丞相以下至六百石为外朝唐皇城之北南三门曰承天元正冬至受万国之朝贡则御焉盖古之外朝也其北曰太极门其西曰太极殿朔望则坐而视朝盖古之正朝也又北曰两仪门其内曰两仪殿常日听朝而视事盖古之内朝也宋时常朝则文德殿五日一起居则垂拱殿正旦冬至圣节称贺则大庆殿赐宴则紫宸殿或集英殿试进士则崇政殿侍从以下五日一员上殿谓之轮对则必入陈时政利害内殿引见亦或赐坐或免穿靴盖亦三朝之遗意焉盖天有三垣天子象之正朝象太极也外朝象天市也内朝象紫微也自古然矣国朝圣节正旦冬至大朝会则奉天殿即古之正朝也常日则奉天门即古之外朝也而内朝独缺然非缺也华盖谨身武英等殿岂非内朝之遗制乎洪武中如宋濂刘基永乐以来如杨士奇杨荣等日侍左右大臣蹇义夏元吉等常奏对便殿于斯时也岂有壅隔之患哉今内朝未复临御常朝之后人臣无复进见三殿高閟鲜或窥焉故上下之情壅而不通天下之弊由是而积孝宗晚年深有慨于斯屡召大臣于便殿讲论天下事方将有为而民之无禄不及睹至治之美天下至今以为恨矣惟陛下远法圣祖近法孝宗尽刬近世壅隔之弊常朝之外即文华武英二殿仿古内朝之意大臣三日或五日一次起居侍从台谏各一员上殿轮对诸司有事咨决上据所见决之有难决者与大臣面议之不时引见群臣凡谢恩辞见之类皆得上殿陈奏虚心而问之和颜色而道之如此人人得以自尽陛下虽深居九重而天下之事灿然毕陈于前外朝所以正上下之分内朝所以通远近之情如此岂有近时壅隔之弊哉唐虞之时明目达聪嘉言罔伏野无遗贤亦不过是而已", "《易经》的《泰》卦说：「上下沟通而志同道合。」它的《否》卦说：「上下不沟通而天下无国。」大概上面的情况传达到下面，下面的情况传达到上面，上下一体，所以是「泰」。下面的情况阻塞而不能让上面听到，上下隔绝，即使有国家也如同没有国家了，所以是「否」。沟通就泰，不沟通就否，自古都是这样，而不沟通的弊病，没有像近世这样严重的。君臣相见，只在视朝的几刻钟；上下之间，靠章奏批答相关接，靠刑名法度相维持罢了。不只是沿袭旧例，也是地势使它这样。为什么呢？国家常在奉天门上朝，不曾一天废止，可以说是勤了。然而朝堂的台阶高峻，威仪赫赫，御史纠察礼仪，鸿胪举报不合法的，通政司引奏，皇上只看看，谢恩见辞，惴惴而退，皇上何尝处理一件事，臣下何尝进一句话呢？这没有别的，是因为地势悬绝，所谓堂上远于万里，虽然想说话也无从说起。\n我认为想要上下沟通，不如恢复古代内朝的制度。大概周朝的时候有三朝：库门之外是正朝，咨询谋划大臣在那里；路门之外是治朝，每日视朝在那里；路门之内叫内朝，也叫燕朝。《玉藻》说：「国君日出而视朝，退到路寝听政。」大概视朝接见群臣，是用来端正上下的名分；听政而到路寝，是用来沟通远近的情况。汉朝的制度：大司马、左右前后将军、侍中、散骑、诸吏为中朝，丞相以下到六百石为外朝。唐朝皇城的北面，南面三门叫承天门，元旦、冬至接受万国的朝贡，就在那里临朝，大概是古代的外朝。它北面叫太极门，西面叫太极殿，初一十五就坐着视朝，大概是古代的正朝。再北面叫两仪门，里面叫两仪殿，平日听朝处理政事，大概是古代的内朝。宋朝时日常朝会在文德殿，五天一问候在垂拱殿，元旦、冬至、圣节称贺在大庆殿，赐宴在紫宸殿或集英殿，考试进士在崇政殿。侍从以下，五天一名上殿，叫做轮对，就必定入内陈述时政的利害。内殿引见，也有的赐坐，有的免穿靴，大概也是三朝的遗意。大概天有三垣，天子取法它。正朝，取法太极；外朝，取法天市；内朝，取法紫微。自古就是这样。\n本朝圣节、元旦、冬至大朝会在奉天殿，就是古代的正朝。平日则在奉天门，就是古代的外朝。而内朝独独缺失。然而并不是缺失，华盖、谨身、武英等殿，难道不是内朝的遗制吗？洪武年间如宋濂、刘基，永乐以来如杨士奇、杨荣等，天天侍候左右，大臣蹇义、夏元吉等，常在便殿奏对。在这个时候，哪里有壅塞隔绝的忧患呢？如今内朝没有恢复，临御常朝之后，臣下不能再进见，三殿高深闭锁，很少能窥见。所以上下的情况壅塞而不通，天下的弊病由此积累。孝宗晚年，对此深有感慨，屡次召大臣到便殿，讲论天下事。正要有所作为，而百姓没有福分，来不及看到至治的美好，天下至今以此为恨。\n希望陛下远效圣祖，近效孝宗，尽除近世壅塞隔绝的弊病。常朝之外，就到文华、武英二殿，仿照古代内朝的意思，大臣三天或五天问候一次，侍从、台谏各一员上殿轮对；各司有事咨询决断，皇上根据所见决断，有难以决断的，同大臣当面商议。不时引见群臣，凡是谢恩辞见之类，都能上殿陈述。虚心地询问他们，和颜悦色地引导他们，这样，人人都能尽言。陛下虽然深居九重，而天下的事鲜明地全部呈现在面前。外朝是用来端正上下的名分，内朝是用来沟通远近的情况。这样，哪里有近时壅塞隔绝的弊病呢？唐、虞的时候，目明耳聪，嘉言不被埋没，野外没有遗漏的贤人，也不过如此而已。"],
    [177, "guwen-gwj-150", "public-domain", "灵博之山有象祠焉其下诸苗夷之居者咸神而祠之宣慰安君因诸苗夷之请新其祠屋而请记于予予曰「毁之乎其新之也」曰「新之」「新之也何居乎」曰「斯祠之肇也盖莫知其原然吾诸蛮夷之居是者自吾父吾祖溯曾高而上皆尊奉而禋祀焉举而不敢废也」予曰「胡然乎有鼻之祀唐之人盖尝毁之象之道以为子则不孝以为弟则傲斥于唐而犹存于今坏于有鼻而犹盛于兹土也胡然乎」我知之矣君子之爱若人也推及于其屋之乌而况于圣人之弟乎哉然则祠者为舜非为象也意象之死其在干羽既格之后乎不然古之骜桀者岂少哉而象之祠独延于世吾于是盖有以见舜德之至入人之深而流泽之远且久也象之不仁盖其始焉耳又乌知其终之不见化于舜也书不云乎「克谐以孝烝烝乂不格奸」「瞽瞍亦允若」则已化而为慈父象犹不弟不可以为谐进治于善则不至于恶不抵于奸则必入于善信乎象盖已化于舜矣孟子曰「天子使吏治其国象不得以有为也」斯盖舜爱象之深而虑之详所以扶持辅导之者之周也不然周公之圣而管蔡不免焉斯可以见象之见化于舜故能任贤使能而安于其位泽加于其民既死而人怀之也诸侯之卿命于天子盖周官之制其殆仿于舜之封象欤吾于是盖有以信人性之善天下无不可化之人也然则唐人之毁之也据象之始也今之诸苗之奉之也承象之终也斯义也吾将以表于世使知人之不善虽若象焉犹可以改而君子之修德及其至也虽若象之不仁而犹可以化之也", "灵博山上，有象的祠庙。山下居住的众苗夷，都把他当神来祭祀。宣慰使安君，因众苗夷的请求，翻新了祠庙，而请我作记。我说：「是毁掉它呢？还是翻新它呢？」回答说：「翻新它。」「翻新它，是什么缘故呢？」回答说：「这座祠庙的创始，大概没有人知道它的原委。然而我们众蛮夷住在这里的，从我父亲、我祖父上溯到曾祖、高祖以上，都尊奉而祭祀他，推行而不敢废止。」我说：「为什么这样呢？有鼻的祭祀，唐朝的人曾经毁掉它。象的德行，做儿子则不孝，做弟弟则傲慢。在唐朝被斥毁，却还存留到今天；在有鼻被毁坏，却还兴盛在这块土地上。为什么这样呢？」\n我知道了：君子爱那个人，推及到他屋上的乌鸦，何况是圣人的弟弟呢？那么祭祀是为了舜，不是为了象。料想像的死，大概在干羽已经感化之后吧？不然，古代傲慢凶暴的人难道少吗？而象的祠庙独独延续在世上。我因此有以看出舜德的至极，深入人心之深，而流泽的远且久。\n象的不仁，大概是他起初罢了，又怎么知道他的最终没有被舜感化呢？《尚书》不是说吗：「能和谐以孝，厚厚地自治，不至于奸邪。」「瞽瞍也诚信和顺了。」那么已经感化成为慈父。象如果还不恭顺，就不可以说是和谐。进治于善，就不至于恶；不陷于奸，就必定归于善。确实啊，象大概已经被舜感化了！孟子说：「天子派官吏治理他的国，象不能有所作为。」这大概是舜爱象之深而考虑之详，所以扶持辅导他的周全。不然，以周公的圣明，而管叔、蔡叔不免于叛乱。这可以看出象被舜感化，所以能任用贤能而安于他的位置，恩泽加于他的百姓，死后而人们怀念他。诸侯的卿，由天子任命，大概是《周官》的制度，它恐怕是仿照舜封象的做法吧？\n我因此有以相信人性的善，天下没有不能感化的人。那么唐朝人毁掉它，是根据象的起初；如今众苗人奉祀他，是承接象的最终。这个道理，我将要表显于世上，使人知道人的不善，即使像象那样，还可以改；而君子修养德行，到了极致，即使像象的不仁，也还可以感化他。"],
    [178, "guwen-gwj-151", "public-domain", "维正德四年秋月三日有吏目云自京来者不知其名氏携一子一仆将之任过龙场投宿土苗家予从篱落间望见之阴雨昏黑欲就问讯北来事不果明早遣人觇之已行矣薄午有人自蜈蚣坡来云「一老人死坡下傍两人哭之哀」予曰「此必吏目死矣伤哉」薄暮复有人来云「坡下死者二人傍一人坐叹」询其状则其子又死矣明早复有人来云「见坡下积尸三焉」则其仆又死矣呜呼伤哉念其暴骨无主将二童子持畚锸往瘗之二童子有难色然予曰「嘻吾与尔犹彼也」二童闵然涕下请往就其傍山麓为三坎埋之又以只鸡饭三盂嗟吁涕洟而告之曰呜呼伤哉繄何人繄何人吾龙场驿丞余姚王守仁也吾与尔皆中土之产吾不知尔郡邑尔乌乎来为兹山之鬼乎古者重去其乡游宦不逾千里吾以窜逐而来此宜也尔亦何辜乎闻尔官吏目耳俸不能五斗尔率妻子躬耕可有也乌为乎以五斗而易尔七尺之躯又不足而益以尔子与仆乎呜呼伤哉尔诚恋兹五斗而来则宜欣然就道乌为乎吾昨望见尔容蹙然盖不任其忧者夫冲冒雾露扳援崖壁行万峰之顶饥渴劳顿筋骨疲惫而又瘴疠侵其外忧郁攻其中其能以无死乎吾固知尔之必死然不谓若是其速又不谓尔子尔仆亦遽然奄忽也皆尔自取谓之何哉吾念尔三骨之无依而来瘗耳乃使吾有无穷之怆也呜呼伤哉纵不尔瘗幽崖之狐成群阴壑之虺如车轮亦必能葬尔于腹不致久暴露尔尔既已无知然吾何能为心乎自吾去父母乡国而来此三年矣历瘴毒而苟能自全以吾未尝一日之戚戚也今悲伤若此是吾为尔者重而自为者轻也吾不宜复为尔悲矣吾为尔歌尔听之歌曰连峰际天兮飞鸟不通游子怀乡兮莫知西东莫知西东兮维天则同异域殊方兮环海之中达观随寓兮奚必予宫魂兮魂兮无悲以恫又歌以慰之曰与尔皆乡土之离兮蛮之人言语不相知兮性命不可期吾苟死于兹兮率尔子仆来从予兮吾与尔遨以嬉兮骖紫彪而乘文螭兮登望故乡而嘘唏兮吾苟获生归兮尔子尔仆尚尔随兮无以无侣为悲兮道旁之冢累累兮多中土之流离兮相与呼啸而徘徊兮餐风饮露无尔饥兮朝友麋鹿暮猿与栖兮尔安尔居兮无为厉于兹墟兮", "正德四年秋天某月三日，有一个自称从京城来的吏目，不知道他的姓名，带着一个儿子一个仆人，将去上任，经过龙场，投宿在土苗家里。我从篱笆间望见他，阴雨昏黑，想前去问北方来的事，没有成。第二天早上，派人去看他，已经走了。近中午，有人从蜈蚣坡来，说：「一个老人死在坡下，旁边两个人哭得很哀伤。」我说：「这一定是吏目死了。伤心啊！」近傍晚，又有人来说：「坡下死的有两个人，旁边一个人坐着叹息。」问那情形，那么他的儿子又死了。第二天早上，又有人来说：「看见坡下堆积的尸体有三具。」那么他的仆人又死了。唉，伤心啊！\n想到他们暴露尸骨没有归属，带着两个童仆拿畚箕铁锹去埋葬他们。两个童仆面有难色。我说：「唉！我和你们同他们一样啊！」两个童仆怜悯地流下泪，请求前往。就着那旁边的山麓挖了三个坑，埋葬他们。又用一只鸡、三碗饭，叹息流泪而告慰他们说：\n唉，伤心啊！你是谁？你是谁？我是龙场驿丞余姚王守仁。我和你都出生于中土，我不知道你的郡邑，你为什么来做这座山的鬼呢？古代的人看重离开乡里，游宦不超过千里。我因为被贬窜而来这里，是应该的。你又有什么罪呢？听说你的官职不过是吏目，俸禄不到五斗，你带着妻子亲自耕种也可以有。为什么用五斗米换你的七尺之躯？还不满足，又加上你的儿子和仆人呢？唉，伤心啊！你如果确实贪恋这五斗米而来，就应该欣然上路，为什么我昨天望见你的面容忧愁，像是承受不住那忧愁呢？冲冒雾露，攀援崖壁，行走在万峰之顶，饥渴劳顿，筋骨疲惫，而又瘴疠侵袭他的外面，忧郁攻伐他的内心，能不死吗？我本来知道你一定死，然而不料像这样快，又不料你的儿子、你的仆人也突然死去！都是你自取的，说你什么呢！\n我念你们三具尸骨无依而来埋葬罢了，竟使我有无穷的悲痛。唉，伤心啊！纵然不埋葬你们，幽暗的山崖上狐狸成群，阴暗的山谷里毒蛇像车轮，也一定能埋葬你们在腹中，不至于长久暴露你们。你既已没有知觉，然而我怎么能忍心呢？自从我离开父母乡国而来这里，三年了，经历瘴毒而能苟且自全，因为我不曾有一天忧愁。如今悲伤到这样，是我为你着想得重，而为自己着想得轻了。我不应该再为你悲伤了。我为你唱歌，你听吧。\n歌词说：连绵的山峰接着天啊，飞鸟不通。游子怀乡啊，不知西东。不知西东啊，只有天是相同的。异域殊方啊，都在环海之中。达观随遇而安啊，何必一定在自己的家。魂啊魂啊，不要悲伤而哀痛！\n又唱歌来安慰他们说：同你都是离乡的人啊，蛮人的言语不相通啊。性命不可预期，我如果死在这里啊，带着你的儿子仆人，来跟从我啊。我和你遨游嬉戏啊，驾驭紫彪乘坐文螭啊，登高望故乡而叹息啊。我如果能够活着回去啊，你的儿子你的仆人，还跟着你啊，不要因为没有伴侣而悲伤啊！路旁的坟墓累累啊，多是中土的流离之人啊，一起呼啸徘徊啊。餐风饮露，不会让你饥饿啊。早晨以麋鹿为友，傍晚与猿猴同栖啊。你安于你的居处啊，不要在这废墟作祟啊！"],
    [180, "guwen-gwj-152", "public-domain", "数千里外得长者时赐一书以慰长想即亦甚幸矣何至更辱馈遗则不才益将何以报焉书中情意甚殷即长者之不忘老父知老父之念长者深也至以「上下相孚才德称位」语不才则不才有深感焉夫才德不称固自知之矣至于不孚之病则尤不才为甚且今世之所谓孚者何哉日夕策马候权者之门门者故不入则甘言媚词作妇人状袖金以私之即门者持刺入而主者又不即出见立厩中仆马之间恶气袭衣裾即饥寒毒热不可忍不去也抵暮则前所受赠金者出报客曰「相公倦谢客矣客请明日来」即明日又不敢不来夜披衣坐闻鸡鸣即起盥栉走马抵门门者怒曰「为谁」则曰「昨日之客来」则又怒曰「何客之勤也岂有相公此时出见客乎」客心耻之强忍而与言曰「亡奈何矣姑容我入」门者又得所赠金则起而入之又立向所立厩中幸主者出南面召见则惊走匍匐阶下主者曰「进」则再拜故迟不起起则上所上寿金主者故不受则固请主者故固不受则又固请然后命吏内之则又再拜又故迟不起起则五六揖始出出揖门者曰「官人幸顾我他日来幸亡阻我也」门者答揖大喜奔出马上遇所交识即扬鞭语曰「适自相公家来相公厚我厚我」且虚言状即所交识亦心畏相公厚之矣相公又稍稍语人曰「某也贤某也贤」闻者亦心计交赞之此世所谓上下相孚也长者谓仆能之乎前所谓权门者自岁时伏腊一刺之外即经年不往也间道经其门则亦掩耳闭目跃马疾走过之若有所追逐者斯则仆之褊衷以此长不见悦于长吏仆则愈益不顾也每大言曰「人生有命吾惟守分尔」长者闻此得无厌其为迂乎乡园多故不能不动客子之愁至于长者之抱才而困则又令我怆然有感天之与先生者甚厚亡论长者不欲轻弃之即天意亦不欲长者之轻弃之也幸宁心哉", "相隔数千里，得到长者时常赐给我一封信，来安慰我长久的思念，也就很幸运了；何至于更有辱您赠送礼物，那么我更将拿什么来报答呢？信中情意很殷切，就是长者不忘我的老父，知道我的老父思念长者的深切。至于用「上下相互信任、才德与职位相称」来称许我，那我就深有感触了。才德不相称，本来自己知道；至于不能取信于上的毛病，那在我身上尤其严重。\n况且如今世上所谓的取信是什么呢？早晚赶马，守候在权贵门前。看门的人故意不让进，就说甜言蜜语，做出女人的样子，袖子里藏着银子私下给他。即使看门的人拿着名帖进去，而主人又不马上出来接见。站在马棚里仆人马匹之间，恶气侵袭衣襟，即使饥寒毒热不能忍受，也不离开。到了傍晚，那么先前接受赠银的人出来，告诉客人说：「相公疲倦了，谢绝客人了。客人请明天来。」到了明天，又不敢不来。夜里披衣坐着，听到鸡叫，就起来洗脸梳头，骑马到门。看门的人怒问：「是谁？」就说：「昨天的客人来了。」就又怒说：「什么客人这样勤快！哪有相公这个时候出来见客的？」客人心里感到耻辱，勉强忍耐着同他说：「没有办法了，暂且让我进去吧。」看门的人又得到赠银，就起身让他进去。又站在先前站过的马棚里。幸而主人出来，面朝南召见他，就惊慌地跑过去伏在台阶下。主人说：「进来！」就拜了两拜，故意迟迟不起，起来就献上所要进的祝寿银子。主人故意不接受，就坚持请求；主人故意坚决不接受，就又一次坚持请求。然后命小吏收下，就又一次拜了两拜，又故意迟迟不起，起来就作揖五六次，才出去。出去后，向看门的人作揖说：「官人幸而关照我！以后来，希望不要阻拦我！」看门的人回礼，他大喜奔出。在马上遇到相识的人，就扬起马鞭说：「刚从相公家来，相公厚待我，厚待我！」并且虚假地描述情形。就是他的相识，也心里畏惧相公厚待他了。相公又渐渐地对人说：「某人贤能，某人贤能。」听到的人也心里盘算着交相称赞他。这就是世上所谓的上下相互信任，长者说我能这样做吗？\n前面所说的权贵之门，除了年节伏腊送一张名帖之外，就整年不去。偶尔路过他的门口，也就捂着耳朵闭着眼睛，催马快跑过去，像有追赶的人。这就是我的心胸狭隘，因此长久不被长官喜欢，我却越发不顾。每每大言说：「人生有命，我只守本分罢了！」长者听到这话，恐怕要嫌我迂阔吧？\n乡园多变故，不能不触动客子的愁思。至于长者怀才而困顿，就又使我怆然有感。上天给先生的很多，不要说长者不想轻易抛弃它，就是天意也不想让长者轻易抛弃它，希望您安心啊！"],
    [181, "guwen-gwj-153", "public-domain", "吴长洲二县在郡治所分境而治而郡西诸山皆在吴县其最高者穹窿阳山邓尉西脊铜井而灵岩吴之故宫在焉尚有西子之遗迹若虎丘剑池及天平尚方支硎皆胜地也而太湖汪洋三万六千顷七十二峰沉浸其间则海内之奇观矣余同年友魏君用晦为吴县未及三年以高第召入为给事中君之为县有惠爱百姓扳留之不能得而君亦不忍于其民由是好事者绘吴山图以为赠夫令之于民诚重矣令诚贤也其地之山川草木亦被其泽而有荣也令诚不贤也其地之山川草木亦被其殃而有辱也君于吴之山川盖增重矣异时吾民将择胜于岩峦之间尸祝于浮屠老子之宫也固宜而君则亦既去矣何复惓惓于此山哉昔苏子瞻称韩魏公去黄州四十余年而思之不忘至以为思黄州诗子瞻为黄人刻之于石然后知贤者于其所至不独使其人之不忍忘而已亦不能自忘于其人也君今去县已三年矣一日与余同在内庭出示此图展玩太息因命余记之噫君之于吾吴有情如此如之何而使吾民能忘之也", "吴县、长洲二县，在郡治所在地，分境而治。而郡西的群山，都在吴县。其中最高的，是穹窿、阳山、邓尉、西脊、铜井，而灵岩山，吴国的故宫在那里，还有西施的遗迹。至于虎丘、剑池以及天平、尚方、支硎，都是胜地。而太湖汪洋三万六千顷，七十二峰沉浸其中，就是海内的奇观了。\n我的同年友魏用晦君做吴县县令，不到三年，以考核优等召入做给事中。君做县令有惠爱，百姓挽留他而不能得，而君也不忍心离开他的百姓，因此好事的人画了《吴山图》来赠送他。\n县令对于百姓，确实重要了。县令如果贤能，那地方的山川草木也蒙受他的恩泽而有荣光；县令如果不贤，那地方的山川草木也遭受他的祸殃而有耻辱。君对于吴地的山川，大概是增加了分量了。将来我们百姓将在山岩之间选择胜地，在佛寺、道观里祭祀他，本来就是应该的。而君则也已经离开了，为什么还眷眷于此山呢？从前苏子瞻称韩魏公离开黄州四十多年而思念不忘，以至于作《思黄州》诗，子瞻为黄州人把它刻在石上。然后知道贤者对于他所到之处，不只是使那里的人不忍忘记而已，也不能自己忘记那里的人。\n君如今离开吴县已经三年了。一天，同我在内庭，拿出这幅图，展玩叹息，于是命我记下它。唉！君对于我们吴地，有情如此，怎么能使我们的百姓忘记他呢？"],
    [182, "guwen-gwj-154", "public-domain", "予以罪废无所归扁舟南游旅于吴中始僦舍以处时盛夏蒸燠土居皆褊狭不能出气思得高爽虚辟之地以舒所怀不可得也一日过郡学东顾草树郁然崇阜广水不类乎城中并水得微径于杂花修竹之间东趋数百步有弃地纵广合五六十寻三向皆水也杠之南其地益阔旁无民居左右皆林木相亏蔽访诸旧老云钱氏有国近戚孙承祐之池馆也坳隆胜势遗意尚存予爱而徘徊遂以钱四万得之构亭北碕号「沧浪」焉前竹后水水之阳又竹无穷极澄川翠干光影会合于轩户之间尤与风月为相宜予时榜小舟幅巾以往至则洒然忘其归觞而浩歌踞而仰啸野老不至鱼鸟共乐形骸既适则神不烦观听无邪则道以明返思向之汩汩荣辱之场日与锱铢利害相磨戛隔此真趣不亦鄙哉噫人固动物耳情横于内而性伏必外寓于物而后遣寓久则溺以为当然非胜是而易之则悲而不开惟仕宦溺人为至深古之才哲君子有一失而至于死者多矣是未知所以自胜之道予既废而获斯境安于冲旷不与众驱因之复能乎内外失得之原沃然有得笑闵万古尚未能忘其所寓目用是以为胜焉", "我因罪被废黜，无处可归。乘小船南游，旅居吴中，才租了房子住下。当时盛夏闷热，当地的居室都狭小，不能透气，想找高爽空旷的地方，来舒展我的胸怀，不能得到。\n一天路过郡学，向东望去草树茂盛，高丘广水，不像城里。沿着水边在杂花修竹之间找到一条小路。向东走几百步，有一块弃地，纵横共五六十寻，三面都是水。小桥的南面，那地方更加开阔，旁边没有民居，左右都是林木互相遮蔽。访问那些老人，说钱氏建国时，是近戚孙承祐的池馆。高低起伏的胜景，遗留的意态还在。我喜爱而徘徊，就用四万钱买到它，在北面曲折处建亭，号「沧浪」。前有竹后有水，水的北面又是竹，无穷无极。清澈的水流翠绿的竹干，光影会合在轩窗之间，尤其同风月相宜。\n我时常划着小船，裹着幅巾前往，到了就洒然忘记回去。举杯而长歌，蹲坐而仰啸，野老不来，鱼鸟同乐。形体既已安适那么精神就不烦扰，观听没有邪僻那么道就显明；回想从前在汩汩的荣辱场中，每天同锱铢利害相磨击，隔开这真趣，不也很鄙陋吗！\n唉！人本来是动物罢了。情感横亘于内而本性隐伏，必定要外寄于物而后才能排遣。寄托久了就沉溺，以为理所当然；不是胜过这个而改变它，就悲哀而不能开解。只有仕宦沉溺人最深。古代的才哲君子，有一失而至于死的很多，这是不知道自我克服的道理。我既然被废黜而获得这个境地，安于冲淡旷达，不与众人在名利场奔驰，因此又能明了内外得失的根源，沃然有得，笑悯万古。还不能忘记他所寄托于目的事物，就用这个来作为胜过。"],
    [183, "guwen-gwj-155", "public-domain", "青霞沈君由锦衣经历上书诋宰执宰执深疾之方力构其罪赖天子仁圣特薄其谴徙之塞上当是时君之直谏之名满天下已而君累然携妻子出家塞上会北敌数内犯而帅府以下束手闭垒以恣敌之出没不及飞一镞以相抗甚且及敌之退则割中土之战没者与野行者之馘以为功而父之哭其子妻之哭其夫兄之哭其弟者往往而是君既上愤疆埸之日弛而又下痛诸将士日菅刈我人民以蒙国家也故数呜咽欷歔而以其所忧郁发之于诗歌文章以泄其怀即集中所载诸篇是也君故以直谏为重于时而其所著为诗歌文章又多所讥刺稍稍传播上下震恐始出死力相煽构而君之祸作矣君既没而中朝之士虽不敢讼其事而一时阃寄所寄与夫乡大夫之贤者咸痛君之不用而追慕其为人故其平生所为诗歌文章遂盛行于世某童子时即闻君名而窃尝读其诗想见其人以为古之狂士若君者盖不可少也及余入仕而君已没不及见而君之婿黄君谦之与余为同年进士以其集请序余读而叹曰君之诗悲壮激切读之使人慨然有英雄流涕之思君虽不幸而其所为传世而行后者则亦足矣然余又闻君之在塞上尝以故人邑子之丧夜行失道坠马伤足竟以是卒悲夫君之死可以见其为人矣君以万死一生之身处至危极苦之地而犹能以其诗鸣此岂非所谓固穷之士耶孔子曰「志士不忘在沟壑勇士不忘丧其元」君之谓欤是为序", "青霞沈君，由锦衣卫经历上书诋毁宰执，宰执非常恨他。正竭力罗织他的罪状，依赖天子的仁圣，特地减轻他的惩处，把他迁到塞上。在这个时候，君的直谏之名满天下。随后君疲惫地携着妻子儿女，把家安在塞上。正逢北敌屡次内犯，而帅府以下，束手关闭营垒，来听任敌人的出没，连一支箭都不敢射出去抵抗。甚至到敌人退去，就割取中土阵亡的和野外行走者的首级来请功。而父亲哭儿子、妻子哭丈夫、兄长哭弟弟的，到处都是。君既在上愤慨疆场的日益废弛，又在下痛心众将士天天像割草一样杀害我们的百姓来蒙骗国家，所以屡次呜咽欷歔，而把他所忧郁的发为诗歌文章，来宣泄他的怀抱，就是文集所载的诸篇。\n君本来以直谏为当时所重，而他所写的诗歌文章，又多有讥刺，渐渐传播开来，上下震惊恐惧。于是出死力互相煽动罗织，而君的祸患就发生了。君既已去世，而朝中的士人虽然不敢陈述他的事，而一时受任边寄的人，与乡大夫中的贤者，都痛心君的不被任用，而追慕他的为人。所以他平生所作的诗歌文章，就盛行于世。\n我童子时，就听到君的名字，而私下曾读他的诗，想象他的为人，认为古代狂士像君这样的，是不可少的。等我入仕，而君已经去世，来不及见面。而君的女婿黄谦之君，同我是同年进士，拿他的文集请我作序。我读了叹息说：君的诗，悲壮激切，读它使人感慨，有英雄流泪的思绪。君虽然不幸，而他所用来传世行于后世的，也就足够了。\n然而我又听说君在塞上，曾因故人同乡的死丧，夜里行走迷失道路，坠马伤足，终于因此去世。可悲啊！君的死，可以看出他的为人了。君以万死一生的身体，处在最危险极苦的地方，而还能以他的诗鸣响，这难道不是所谓的固穷之士吗？孔子说：「志士不忘记死在沟壑，勇士不忘记丧失头颅。」说的就是君吧！于是作这篇序。"],
    [185, "guwen-gwj-217", "", "徐渭字文长为山阴诸生声名籍甚薛公蕙校越时奇其才有国士之目然数奇屡试辄蹶中丞胡公宗宪闻之客诸幕文长每见则葛衣乌巾纵谈天下事胡公大喜是时公督数边兵威镇东南介胄之士膝语蛇行不敢举头而文长以部下一诸生傲之议者方之刘真长杜少陵云会得白鹿属文长作表表上永陵喜公以是益奇之一切疏记皆出其手文长自负才略好奇计谈兵多中视一世士无可当意者然竟不偶文长既已不得志于有司遂乃放浪麴糵恣情山水走齐鲁燕赵之地穷览朔漠其所见山奔海立沙起云行雨鸣树偃幽谷大都人物鱼鸟一切可惊可愕之状一一皆达之于诗其胸中又有勃然不可磨灭之气英雄失路托足无门之悲故其为诗如嗔如笑如水鸣峡如种出土如寡妇之夜哭羁人之寒起虽其体格时有卑者然匠心独出有王者气非彼巾帼而事人者所敢望也文有卓识气沉而法严不以模拟损才不以议论伤格韩曾之流亚也文长既雅不与时调合当时所谓骚坛主盟者文长皆叱而奴之故其名不出于越悲夫喜作书笔意奔放如其诗苍劲中姿媚跃出欧阳公所谓「妖韶女老自有余态」者也间以其余旁溢为花鸟皆超逸有致卒以疑杀其继室下狱论死张太史元汴力解乃得出晚年愤益深佯狂益甚显者至门或拒不纳时携钱至酒肆呼下隶与饮或自持斧击破其头血流被面头骨皆折揉之有声或以利锥锥其两耳深入寸余竟不得死周望言晚岁诗文益奇无刻本集藏于家余同年有官越者托以抄录今未至余所见者徐文长集阙编二种而已然文长竟以不得志于时抱愤而卒石公曰先生数奇不已遂为狂疾狂疾不已遂为囹圄古今文人牢骚困苦未有若先生者也虽然胡公间世豪杰永陵英主幕中礼数异等是胡公知有先生矣表上人主悦是人主知有先生矣独身未贵耳先生诗文崛起一扫近代芜秽之习百世而下自有定论胡为不遇哉梅客生尝寄余书曰「文长吾老友病奇于人人奇于诗」余谓文长无之而不奇者也无之而不奇斯无之而不奇也悲夫", "徐渭，字文长，是山阴的诸生，声名很大。薛蕙公做浙江考官时，惊奇他的才能，有国士的评价。然而命运不顺，屡次考试都失败。中丞胡宗宪公听说他，请他做幕客。文长每次进见，就穿葛衣戴乌巾，纵谈天下大事，胡公大喜。当时胡公督率几路边兵，威镇东南，披甲的将士，跪着说话像蛇一样爬行，不敢抬头；而文长以部下一个诸生的身份对他傲慢，议论的人把他比作刘真长、杜少陵。恰好得到白鹿，嘱托文长作表，表呈上，世宗皇帝很高兴。胡公因此更加惊奇他，一切奏疏文书，都出自他的手。\n文长自负才略，喜好奇计，谈兵多能说中，看一世的士人没有能中意的。然而终究不遇。文长既已在考官那里不得志，于是就放浪于酒，纵情于山水，走遍齐鲁燕赵之地，穷览北方沙漠。他所见到的山奔海立、沙起云行、雨鸣树倒、幽谷大都、人物鱼鸟，一切可惊可愕的情状，一一都表达在诗里。他胸中又有勃然不可磨灭的气，英雄失路、无门托足的悲，所以他作诗，像嗔怒像嘻笑，像水在峡谷中鸣响，像种子出土，像寡妇在夜里哭泣，像羁旅之人在寒冷中起身。虽然它的体格时时有卑下的，然而匠心独出，有王者之气，不是那些像妇女一样侍奉人的所敢企望的。文章有卓识，气沉而法严，不因模拟损害才气，不因议论伤害格调，是韩愈、曾巩一流。文长既已素来不与时调相合，当时所谓诗坛盟主的，文长都呵斥而奴视他们，所以他的名声不出越地。可悲啊！\n喜好写字，笔意奔放像他的诗，苍劲中姿媚跃出，就是欧阳公所说的「妖冶的女子年老，还有余态」。间或用他的余力，旁溢为花鸟，都超逸有风致。\n终于因疑心杀了他的继室，下狱判死。张元汴太史尽力解救，才得以出狱。晚年愤恨更深，装疯更厉害，显贵的人到门前，有时拒不接纳。时常带着钱到酒店，叫仆役一起喝酒。有时自己拿斧头击破自己的头，血流满面，头骨都折了，揉它有声。有时用利锥刺自己的两耳，深进一寸多，竟然没有死。周望说：晚年诗文更奇，没有刻本，集子藏在家里。我的同年有在越地做官的，托他抄录，至今没有送到。我所见到的，只有《徐文长集》《阙编》两种而已。然而文长终究因为在当时不得志，抱愤而死。\n石公说：先生命运不顺不已，就成狂疾；狂疾不已，就入监狱。古今文人牢骚困苦，没有像先生的。虽然如此，胡公是隔世的豪杰，世宗是英主，幕中礼数特殊，这是胡公知道有先生了；表呈上，君主高兴，这是君主知道有先生了。只是自身没有显贵罢了。先生的诗文崛起，一扫近代芜秽的习气，百世之后，自有定论，怎么说不遇呢？梅客生曾寄信给我说：「文长是我的老友，病奇于人，人奇于诗。」我说文长是无处不奇的人。无处不奇，这就是无处不奇。可悲啊！"],
    [186, "guwen-gwj-218", "", "五人者盖当蓼洲周公之被逮激于义而死焉者也至于今郡之贤士大夫请于当道即除魏阉废祠之址以葬之且立石于其墓之门以旌其所为呜呼亦盛矣哉夫五人之死去今之墓而葬焉其为时止十有一月耳夫十有一月之中凡富贵之子慷慨得志之徒其疾病而死死而湮没不足道者亦已众矣况草野之无闻者欤独五人之皦皦何也予犹记周公之被逮在丁卯三月之望吾社之行为士先者为之声义敛赀财以送其行哭声震动天地缇骑按剑而前问「谁为哀者」众不能堪抶而仆之是时以大中丞抚吴者为魏之私人周公之逮所由使也吴之民方痛心焉于是乘其厉声以呵则噪而相逐中丞匿于溷藩以免既而以吴民之乱请于朝按诛五人曰颜佩韦杨念如马杰沈扬周文元即今之傫然在墓者也然五人之当刑也意气扬扬呼中丞之名而詈之谈笑以死断头置城上颜色不少变有贤士大夫发五十金买五人之头而函之卒与尸合故今之墓中全乎为五人也嗟乎大阉之乱缙绅而能不易其志者四海之大有几人欤而五人生于编伍之间素不闻诗书之训激昂大义蹈死不顾亦曷故哉且矫诏纷出钩党之捕遍于天下卒以吾郡之发愤一击不敢复有株治大阉亦逡巡畏义非常之谋难于猝发待圣人之出而投缳道路不可谓非五人之力也由是观之则今之高爵显位一旦抵罪或脱身以逃不能容于远近而又有剪发杜门佯狂不知所之者其辱人贱行视五人之死轻重固何如哉是以蓼洲周公忠义暴于朝廷赠谥美显荣于身后而五人亦得以加其土封列其姓名于大堤之上凡四方之士无有不过而拜且泣者斯固百世之遇也不然令五人者保其首领以老于户牖之下则尽其天年人皆得以隶使之安能屈豪杰之流扼腕墓道发其志士之悲哉故予与同社诸君子哀斯墓之徒有其石也而为之记亦以明死生之大匹夫之有重于社稷也贤士大夫者冏卿因之吴公太史文起文公孟长姚公也", "这五个人，是在蓼洲周公被逮捕时，激于义愤而死的人。到了如今，本郡的贤士大夫向当权者请求，就清理魏阉废祠的旧址来安葬他们，并且在墓门立石，来表彰他们的作为。唉，也盛大了！\n这五个人的死，离如今建墓安葬，时间只有十一个月罢了。在这十一个月之中，凡是富贵人家的子弟，慷慨得志的人，患病而死，死了就湮没不足称道的，也已经很多了；何况乡野间无名的人呢？唯独这五个人光明显赫，为什么呢？\n我还记得周公被逮捕，是在丁卯年三月十五日。我们社里品行能做士人表率的人，为他伸张正义，募集钱财来送他上路，哭声震动天地。缇骑按着剑上前，问「谁在哀哭？」众人不能忍受，打他们把他们打倒在地。当时以大中丞身份巡抚吴地的是魏忠贤的党羽，周公的逮捕就是由他主使的；吴地的百姓正痛恨他，于是趁他严厉呵斥，就鼓噪着追赶他。中丞躲进厕所的篱笆里才免于难。不久以吴民作乱上报朝廷，追查杀掉五个人，叫颜佩韦、杨念如、马杰、沈扬、周文元，就是如今一起躺在墓里的人。\n然而这五个人受刑时，意气扬扬，喊着中丞的名字骂他，谈笑着死去。断下的头挂在城上，脸色没有一点改变。有贤士大夫拿出五十金，买下五个人的头装在匣子里，终于与尸体合葬。所以如今的墓中是完整的五个人。\n唉！大宦官作乱时，缙绅能不改志节的，四海之大，有几个人呢？而这五个人生在平民之间，素来没有听过诗书的训导，却激昂于大义，赴死不回头，又是什么缘故呢？况且假诏纷出，钩党的逮捕遍于天下，终于因为我们郡的发愤一击，不敢再有株连治罪；大宦官也迟疑畏惧大义，非常的阴谋难以突然发动，等到圣人出来就在路上自缢，不能说不是这五个人的力量。\n由此看来，那么如今的高爵显位，一旦犯罪，有的脱身逃跑，不能被远近容纳，而又有剪发闭门、装疯不知去向的，他们辱人贱行，与这五个人的死相比，轻重究竟如何呢？因此蓼洲周公，忠义显露于朝廷，赠谥美显，荣耀于身后；而这五个人也得以加高坟冢，在大堤之上列出姓名，凡是四方之士没有不经过而拜且哭的，这当然是百世的际遇。不然，让这五个人保住首级老死在门窗之下，那么尽他们的天年，人人都能奴役他们，怎么能使豪杰之流折服，在墓道上扼腕，发抒志士的悲慨呢？所以我和同社诸君子哀叹这墓空有那块石头，而为它作记，也是用来表明死生的大义，匹夫之重于国家。\n贤士大夫，是冏卿吴因之公，太史文文起公，姚孟长公。"],
    [187, "guwen-gwj-121", "public-domain", "予闻世谓诗人少达而多穷夫岂然哉盖世所传诗者多出于古穷人之辞也凡士之蕴其所有而不得施于世者多喜自放于山巅水涯之外见虫鱼草木风云鸟兽之状类往往探其奇怪内有忧思感愤之郁积其兴于怨刺以道羁臣寡妇之所叹而写人情之难言盖愈穷则愈工然则非诗之能穷人殆穷者而后工也予友梅圣俞少以荫补为吏累举进士辄抑于有司困于州县凡十余年年今五十犹从辟书为人之佐郁其所蓄不得奋见于事业其家宛陵幼习于诗自为童子出语已惊其长老既长学乎六经仁义之说其为文章简古纯粹不求苟说于世世之人徒知其诗而已然时无贤愚语诗者必求之圣俞圣俞亦自以其不得志者乐于诗而发之故其平生所作于诗尤多世既知之矣而未有荐于上者昔王文康公尝见而叹曰「二百年无此作矣」虽知之深亦不果荐也若使其幸得用于朝廷作为雅颂以歌咏大宋之功德荐之清庙而追商周鲁颂之作者岂不伟欤奈何使其老不得志而为穷者之诗乃徒发于虫鱼物类羁愁感叹之言世徒喜其工不知其穷之久而将老也可不惜哉圣俞诗既多不自收拾其妻之兄子谢景初惧其多而易失也取其自洛阳至于吴兴已来所作次为十卷予尝嗜圣俞诗而患不能尽得之遽喜谢氏之能类次也辄序而藏之其后十五年圣俞以疾卒于京师余既哭而铭之因索于其家得其遗稿千余篇并旧所藏掇其尤者六百七十七篇为一十五卷呜呼吾于圣俞诗论之详矣故不复云庐陵欧阳修序", "我听说世人说诗人少显达而多穷困，难道是这样吗？大概世上所流传的诗，多出于古代穷困之人的言辞。凡是士人蕴藏他所有的，而不能施展于世，多喜欢自己放浪于山巅水边之处，看见虫鱼草木风云鸟兽的形状种类，往往探究它们的奇特，内心有忧思感愤的郁积，激发为怨恨讥刺，来陈述羁旅之臣、寡妇之所叹，而写出人情中难以言说的。大概越穷困就越工巧。那么不是诗能使人穷困，大概是穷困之后才能工巧。\n我的朋友梅圣俞，年少时凭恩荫补为吏，屡次应举进士，总是被有关官员压抑，困于州县，共十多年。年纪如今五十，还接受征辟的文书，做别人的幕僚佐吏，郁积他所蕴藏的，不能在事业上奋发展现。他家在宛陵，幼年学习作诗，自从做童子，出口的话已经使年长的人惊讶。长大以后，学习六经仁义之说。他写文章，简古纯粹，不求苟且取悦于世。世上的人只知道他的诗罢了。然而当时无论贤愚，谈诗的一定向圣俞求教；圣俞也把自己不得志的，乐于在诗中抒发。所以他平生所作，在诗上尤其多。世人已经知道了，却没有向皇上推荐他的。从前王文康公曾见到而叹息说：「二百年没有这样的作品了！」虽然了解得很深，也没有终于推荐。假使他幸运地得到朝廷任用，写作雅颂，来歌颂大宋的功德，进献于清庙，而追及商、周、鲁颂的作者，难道不伟大吗！怎么使他到老不得志，而写穷困者的诗，只是发为虫鱼物类、羁旅愁思感叹的言辞。世人只喜欢他的工巧，不知道他穷困之久而且将要老了！能不惋惜吗！\n圣俞的诗既然多，自己不收拾。他妻子的侄儿谢景初，怕诗多而容易散失，取他从洛阳到吴兴以来所作的，编次为十卷。我曾经嗜爱圣俞的诗，而苦于不能全部得到，就高兴谢氏能够分类编次，于是作序而收藏它。\n此后十五年，圣俞因病在京城去世，我既哭吊而为他作铭，于是向他家索求，得到他的遗稿一千多篇，连同旧日所收藏的，选取其中特别好的六百七十七篇，编为十五卷。唉！我对圣俞的诗论述得很详尽了，所以不再说。\n庐陵欧阳修序。"],
    [188, "guwen-gwj-122", "public-domain", "予尝有幽忧之疾退而闲居不能治也既而学琴于友人孙道滋受宫声数引久而乐之不知其疾之在体也夫琴之为技小矣及其至也大者为宫细者为羽操弦骤作忽然变之急者凄然以促缓者舒然以和如崩崖裂石高山出泉而风雨夜至也如怨夫寡妇之叹息雌雄雍雍之相鸣也其忧深思远则舜与文王孔子之遗音也悲愁感愤则伯奇孤子屈原忠臣之所叹也喜怒哀乐动人必深而纯古淡泊与夫尧舜三代之言语孔子之文章易之忧患诗之怨刺无以异其能听之以耳应之以手取其和者道其堙郁写其幽思则感人之际亦有至者焉予友杨君好学有文累以进士举不得志及从荫调为尉于剑浦区区在东南数千里外是其心固有不平者且少又多疾而南方少医药风俗饮食异宜以多疾之体有不平之心居异宜之俗其能郁郁以久乎然欲平其心以养其疾于琴亦将有得焉故予作琴说以赠其行且邀道滋酌酒进琴以为别", "我曾经有幽忧之疾，退居闲处，不能治好。后来向友人孙道滋学琴，学了宫声几首曲子，时间久了就喜欢它，不知道疾病还在身上。琴作为一种技艺是小的，但到了极致，大的为宫，细的为羽，拨弦骤然奏起，忽然变化，急促的凄然而紧张，舒缓的舒然而平和，像山崖崩塌、岩石开裂，高山涌出泉水，而风雨夜里到来。像怨夫寡妇的叹息，雌雄鸟和谐地互相鸣叫。它的忧深思远，就是舜和文王、孔子的遗音；悲愁感愤，就是伯奇孤子、屈原忠臣的叹息。喜怒哀乐，感动人必定很深。而纯古淡泊，同尧舜三代的言语、孔子的文章、《易经》的忧患、《诗经》的怨刺没有不同。能够用耳听它，用手应它，取其中和的，疏导他的郁结，宣泄他的幽思，那么在感动人的地方，也有达到极致的。\n我的朋友杨君，好学有文采，屡次应进士举，不得志。后来依恩荫调任，在剑浦做县尉，区区在东南数千里之外，他的心中本来有不平的。况且年少又多病，而南方缺少医药，风俗饮食不适应。以多病之身，有不平之心，处在不适应的风俗中，他能郁郁地长久吗？然而想要平他的心以养他的病，在琴上也将有所得。所以我写这篇琴说赠送他远行，并且邀请道滋斟酒进琴来作别。"],
    [189, "guwen-gwj-123", "public-domain", "呜呼盛衰之理虽曰天命岂非人事哉原庄宗之所以得天下与其所以失之者可以知之矣世言晋王之将终也以三矢赐庄宗而告之曰「梁吾仇也燕王吾所立契丹与吾约为兄弟而皆背晋以归梁此三者吾遗恨也与尔三矢尔其无忘乃父之志」庄宗受而藏之于庙其后用兵则遣从事以一少牢告庙请其矢盛以锦囊负而前驱及凯旋而纳之方其系燕父子以组函梁君臣之首入于太庙还矢先王而告以成功其意气之盛可谓壮哉及仇雠已灭天下已定一夫夜呼乱者四应仓皇东出未及见贼而士卒离散君臣相顾不知所归至于誓天断发泣下沾襟何其衰也岂独伶人也哉书曰「满招损谦得益」忧劳可以兴国逸豫可以亡身自然之理也故方其盛也举天下之豪杰莫能与之争及其衰也数十伶人困之而身死国灭为天下笑夫祸患常积于忽微而智勇多困于所溺岂独伶人也哉作伶官传", "唉！盛衰的道理，虽说是天命，难道不是人事吗！推究庄宗之所以得到天下，和他之所以失去天下的原因，就可以知道了。\n世人说晋王将死的时候，把三支箭赐给庄宗并告诉他说：「梁国是我的仇敌；燕王是我立的；契丹同我约为兄弟，却都背叛晋国而归附梁国。这三者，是我的遗恨。给你三支箭，你不要忘记你父亲的志向！」庄宗接受并把它藏在庙里。此后用兵，就派从事用一少牢祭告太庙，请出那些箭，装在锦囊里，背着走在前头，等到凯旋就把它放回庙里。\n当他用绳索捆绑燕王父子，用匣子装梁国君臣的首级，进入太庙，把箭还给先王，而把成功禀告先王，他的意气之盛，可以说是豪壮啊！等到仇敌已经消灭，天下已经平定，一个人夜里呼喊，作乱的人四方响应，仓皇向东出逃，还没有见到贼人而士卒离散，君臣相顾，不知归向何处，以至于对天发誓、割断头发，泪下沾湿衣襟，多么衰败啊！难道是只有伶人吗？《尚书》说：「自满招致损害，谦虚得到益处。」忧劳可以使国家兴盛，安逸可以使自身灭亡，这是自然的道理。\n所以当他强盛时，全天下的豪杰，没有能同他争衡的；到他衰败时，几十个伶人围困他，而身死国灭，被天下人耻笑。祸患常常积累于细微，而智勇多被所沉溺的困住，难道只是伶人吗？作《伶官传》。"],
    [191, "guwen-gwj-125", "public-domain", "仕宦而至将相富贵而归故乡此人情之所荣而今昔之所同也盖士方穷时困厄闾里庸人孺子皆得易而侮之若季子不礼于其嫂买臣见弃于其妻一旦高车驷马旗旄导前而骑卒拥后夹道之人相与骈肩累迹瞻望咨嗟而所谓庸夫愚妇者奔走骇汗羞愧俯伏以自悔罪于车尘马足之间此一介之士得志于当时而意气之盛昔人比之衣锦之荣者也惟大丞相魏国公则不然公相人也世有令德为时名卿自公少时已擢高科登显仕海内之士闻下风而望余光者盖亦有年矣所谓将相而富贵皆公所宜素有非如穷厄之人侥幸得志于一时出于庸夫愚妇之不意以惊骇而夸耀之也然则高牙大纛不足为公荣桓圭衮冕不足为公贵惟德被生民而功施社稷勒之金石播之声诗以耀后世而垂无穷此公之志而士亦以此望于公也岂止夸一时而荣一乡哉公在至和中尝以武康之节来治于相乃作昼锦之堂于后圃既又刻诗于石以遗相人其言以快恩仇矜名誉为可薄盖不以昔人所夸者为荣而以为戒于此见公之视富贵为何如而其志岂易量哉故能出入将相勤劳王家而夷险一节至于临大事决大议垂绅正笏不动声色而措天下于泰山之安可谓社稷之臣矣其丰功盛烈所以铭彝鼎而被弦歌者乃邦家之光非闾里之荣也余虽不获登公之堂幸尝窃诵公之诗乐公之志有成而喜为天下道也于是乎书", "做官做到将相，富贵而回故乡，这是人情所引以为荣的，也是古今相同的。大概士人正穷困时，困厄在乡里，庸人小孩，都能轻易地侮辱他。像苏秦不被嫂子以礼相待，朱买臣被妻子抛弃。一旦高车驷马，旗帜在前引导，而骑兵在后簇拥，夹道的人，一同并肩接踵，仰望赞叹；而那些庸夫愚妇，奔走骇汗，羞愧俯伏，在车尘马足之间自悔谢罪。这是一个士人，在当时得志，而意气之盛，从前的人比作衣锦还乡的荣耀。\n只有大丞相魏国公却不是这样。公是相州人，世代有美德，是当时的名卿。从公年少时，已经高中科举，登上显要的官位。海内的士人，听到他的风范、望见他的余光的，大概也有年头了。所谓的将相而富贵，都是公所本来就有的；不像穷困的人，侥幸得志于一时，出于庸夫愚妇的意料之外，用来惊骇而夸耀。那么高大的牙旗大纛，不足以作为公的荣耀；桓圭衮冕，不足以作为公的尊贵。只有德泽遍及生民，而功业施于社稷，刻在金石上，传播在声诗中，来照耀后世而流传无穷，这才是公的志向，而士人也以此期望于公。哪里只是夸耀一时而荣耀一乡呢！\n公在至和年间，曾以武康军节度使的身份，来治理相州，于是在后园建造昼锦堂。接着又把诗刻在石上，留给相州的人。他的诗以快意恩仇、夸耀名誉为可鄙，大概不把从前的人所夸耀的当作荣耀，而把它作为警戒。从这里可以看出公把富贵看作什么，而他的志向难道容易估量吗！所以能出入将相，勤劳王家，而安危如一。至于面临大事，决断大议，垂着大带、端正笏板，不动声色，而把天下置于泰山之安，可以说是社稷之臣了。他的丰功伟烈，所以铭刻在彝鼎上而被之弦歌的，是国家的光荣，不是乡里的荣耀。\n我虽然没有能够登上公的厅堂，却有幸曾经私下诵读公的诗，为公的志向得以实现而高兴，而喜欢向天下人称道。于是写下这篇记。"],
    [192, "guwen-gwj-126", "public-domain", "修既治滁之明年夏始饮滁水而甘问诸滁人得于州南百步之近其上则丰山耸然而特立下则幽谷窈然而深藏中有清泉滃然而仰出俯仰左右顾而乐之于是疏泉凿石辟地以为亭而与滁人往游其间滁于五代干戈之际用武之地也昔太祖皇帝尝以周师破李景兵十五万于清流山下生擒其将皇甫晖姚凤于滁东门之外遂以平滁修尝考其山川按其图记升高以望清流之关欲求晖凤就擒之所而故老皆无在者盖天下之平久矣自唐失其政海内分裂豪杰并起而争所在为敌国者何可胜数及宋受天命圣人出而四海一向之凭恃险阻刬削消磨百年之间漠然徒见山高而水清欲问其事而遗老尽矣今滁介江淮之间舟车商贾四方宾客之所不至民生不见外事而安于畎亩衣食以乐生送死而孰知上之功德休养生息涵煦于百年之深也修之来此乐其地僻而事简又爱其俗之安闲既得斯泉于山谷之间乃日与滁人仰而望山俯而听泉掇幽芳而荫乔木风霜冰雪刻露清秀四时之景无不可爱又幸其民乐其岁物之丰成而喜与予游也因为本其山川道其风俗之美使民知所以安此丰年之乐者幸生无事之时也夫宣上恩德以与民共乐刺史之事也遂书以名其亭焉", "我治理滁州的第二年夏天，才喝到滁水而觉得甘甜。问滁州的人，在州南一百步的近处找到。它上面是丰山，高耸独立；下面是幽谷，幽深隐藏；中间有清泉，涌然而上冒。俯仰左右，环顾而喜爱它。于是疏通泉流、开凿山石，开辟地方建亭，而同滁州的人往来游览其间。\n滁州在五代战乱之际，是用兵之地。从前太祖皇帝，曾用后周的军队在清流山下击破李景的十五万兵，在滁州东门之外活捉他的将领皇甫晖、姚凤，于是平定滁州。我曾经考察那里的山川，依照图记，登高眺望清流关，想找到皇甫晖、姚凤被擒的地方。而故老都不在了，大概天下太平已经很久了。自从唐朝失去政柄，海内分裂，豪杰并起争夺，所在成为敌国的，哪里数得清呢？到宋朝承受天命，圣人出来而四海统一。从前所凭恃的险阻，都被铲削消磨，百年之间，茫茫然只见山高而水清。想问那些事，而遗老都没有了。如今滁州处在江淮之间，舟车商贾、四方宾客所不到，百姓生来见不到外面的事，而安于田亩衣食，以乐生送死。而谁知道皇上的功德，休养生息，滋润养育于百年之深呢。\n我来到这里，喜欢这里地方偏僻而政事简少，又喜爱这里风俗的安闲。既然在山谷之间得到这眼泉，就每天同滁州的人仰头望山，俯首听泉。采摘幽香的花草而荫蔽于乔木之下，风霜冰雪，刻露清秀，四季的景色，没有不可爱的。又庆幸这里的百姓因年成丰收而快乐，而喜欢同我游览。于是推究这里的山川，称道这里风俗的美好，使百姓知道之所以能安享这丰年之乐，是侥幸生于没有事的时代。\n宣扬皇上的恩德，来同百姓共享快乐，是刺史的职事。于是写下来并以此命名这座亭。"],
    [193, "guwen-gwj-127", "school", "环滁皆山也其西南诸峰林壑尤美望之蔚然而深秀者琅琊也山行六七里渐闻水声潺潺而泻出于两峰之间者酿泉也峰回路转有亭翼然临于泉上者醉翁亭也作亭者谁山之僧智仙也名之者谁太守自谓也太守与客来饮于此饮少辄醉而年又最高故自号曰醉翁也醉翁之意不在酒在乎山水之间也山水之乐得之心而寓之酒也若夫日出而林霏开云归而岩穴暝晦明变化者山间之朝暮也野芳发而幽香佳木秀而繁阴风霜高洁水落而石出者山间之四时也朝而往暮而归四时之景不同而乐亦无穷也至于负者歌于途行者休于树前者呼后者应伛偻提携往来而不绝者滁人游也临溪而渔溪深而鱼肥酿泉为酒泉香而酒洌山肴野蔌杂然而前陈者太守宴也宴酣之乐非丝非竹射者中弈者胜觥筹交错起坐而喧哗者众宾欢也苍颜白发颓然乎其间者太守醉也已而夕阳在山人影散乱太守归而宾客从也树林阴翳鸣声上下游人去而禽鸟乐也然而禽鸟知山林之乐而不知人之乐人知从太守游而乐而不知太守之乐其乐也醉能同其乐醒能述以文者太守也太守谓谁庐陵欧阳修也", "环绕滁州的都是山。它西南的各个山峰，树林山谷尤其优美。望去草木茂盛而幽深秀丽的，是琅琊山。沿着山路走六七里，渐渐听到水声潺潺，而从两峰之间倾泻出来的，是酿泉。山峰回环、道路转弯，有个亭子像鸟张开翅膀一样高踞在泉上的，是醉翁亭。建造亭子的是谁？是山里的僧人智仙。给它命名的是谁？太守用自己的号来命名。太守同宾客来这里饮酒，喝得少就醉，而年纪又最大，所以自号醉翁。醉翁的意趣不在酒，而在山水之间。山水的快乐，领会在心里而寄托在酒上。\n至于太阳出来而林间的雾气散开，云气归来而岩洞昏暗，明暗变化的，是山间的早晨和傍晚。野花开放而幽香，好树秀丽而浓荫，风霜高洁，水位下落而石头露出的，是山间的四季。早晨前往，傍晚归来，四季的景色不同，而快乐也无穷。\n至于背着东西的人在路上唱歌，行路的人在树下休息，前面的人呼唤，后面的人应答，弯腰驼背的、牵着小孩的，往来不断的，是滁州人在游览。到溪边钓鱼，溪水深而鱼肥；用酿泉的水酿酒，泉水香而酒清；山里的野味野菜，杂然摆在前面的，是太守的宴席。宴饮酣畅的快乐，不是丝也不是竹，投壶的投中了，下棋的赢了，酒杯和酒筹交错，起来坐下而喧哗的，是众宾客的欢乐。苍老的面容、花白的头发，颓然倒在其中的，是太守喝醉了。\n不久夕阳在山，人影散乱，太守回去而宾客跟从。树林阴暗，鸟声上下，游人离去而禽鸟快乐。然而禽鸟知道山林的快乐，而不知道人的快乐；人们知道跟从太守游览而快乐，而不知道太守以他们的快乐为快乐。醉了能同他们一起快乐，醒了能用文章记述的，是太守。太守是谁？是庐陵的欧阳修。"],
    [194, "guwen-gwj-128", "public-domain", "欧阳子方夜读书闻有声自西南来者悚然而听之曰「异哉」初淅沥以萧飒忽奔腾而砰湃如波涛夜惊风雨骤至其触于物也鏦鏦铮铮金铁皆鸣又如赴敌之兵衔枚疾走不闻号令但闻人马之行声予谓童子「此何声也汝出视之」童子曰「星月皎洁明河在天四无人声声在树间」予曰「噫嘻悲哉此秋声也胡为而来哉盖夫秋之为状也其色惨淡烟霏云敛其容清明天高日晶其气栗冽砭人肌骨其意萧条山川寂寥故其为声也凄凄切切呼号愤发丰草绿缛而争茂佳木葱茏而可悦草拂之而色变木遭之而叶脱其所以摧败零落者乃其一气之余烈夫秋刑官也于时为阴又兵象也于行用金是谓天地之义气常以肃杀而为心天之于物春生秋实故其在乐也商声主西方之音夷则为七月之律商伤也物既老而悲伤夷戮也物过盛而当杀」「嗟乎草木无情有时飘零人为动物惟物之灵百忧感其心万事劳其形有动于中必摇其精而况思其力之所不及忧其智之所不能宜其渥然丹者为槁木黟然黑者为星星奈何以非金石之质欲与草木而争荣念谁为之戕贼亦何恨乎秋声」童子莫对垂头而睡但闻四壁虫声唧唧如助予之叹息", "欧阳子正在夜里读书，听到有声音从西南方传来，惊惧地听着，说：「奇怪啊！」起初淅沥而萧飒，忽然奔腾而砰湃，像波涛夜里惊起，风雨骤然而至。它接触到物体，鏦鏦铮铮，金铁都鸣响；又像奔赴敌阵的士兵，衔枚疾走，听不到号令，只听见人马行走的声音。我对童子说：「这是什么声音？你出去看看。」童子说：「星月皎洁，银河在天，四处没有人声，声音在树间。」\n我说：「唉，悲伤啊！这是秋声，为什么而来呢？大概秋天的形状：它的颜色惨淡，烟雾弥漫、云气收敛；它的容貌清明，天空高远、日光明亮；它的气息凛冽，刺人肌骨；它的意态萧条，山川寂寥。所以它发出的声音，凄凄切切，呼号愤发。丰茂的草碧绿繁密而争相茂盛，美好的树木葱茏而可爱；草被它拂过就变色，树遇到它就落叶。它之所以摧败零落，是它一气之余的威力。秋天，是刑官，在时令上属阴；又是兵象，在五行中用金。这叫做天地的义气，常常以肃杀为心。上天对于万物，春天生长秋天结果，所以它在音乐上，商声是西方的音，夷则是七月的律。商，就是伤，万物既已衰老就悲伤；夷，就是戮，万物过于繁盛就应当杀。\n「唉！草木无情，尚有飘零的时候。人是动物，是万物之灵；百种忧愁感动他的心，万种事务劳累他的形；心中有所触动，必然摇动他的精神。何况思虑他的力量所不及，忧虑他的智慧所不能；当然会使他红润的容颜变成枯木，乌黑的头发变成花白。怎么能以不是金石的身躯，想同草木争荣？想一想是谁在残害自己，又何必怨恨秋声呢！」\n童子没有回答，垂着头睡了。只听见四壁虫声唧唧，像在助我的叹息。"],
    [195, "guwen-gwj-129", "public-domain", "维治平四年七月日具官欧阳修谨遣尚书都省令史李敭至于太清以清酌庶羞之奠致祭于亡友曼卿之墓下而吊之以文曰呜呼曼卿生而为英死而为灵其同乎万物生死而复归于无物者暂聚之形不与万物共尽而卓然其不朽者后世之名此自古圣贤莫不皆然而著在简册者昭如日星呜呼曼卿吾不见子久矣犹能仿佛子之平生其轩昂磊落突兀峥嵘而埋藏于地下者意其不化为朽壤而为金玉之精不然生长松之千尺产灵芝而九茎奈何荒烟野蔓荆棘纵横风凄露下走磷飞萤但见牧童樵叟歌吟而上下与夫惊禽骇兽悲鸣踯躅而咿嘤今固如此更千秋而万岁兮安知其不穴藏狐貉与鼯鼪此自古圣贤亦皆然兮独不见夫累累乎旷野与荒城呜呼曼卿盛衰之理吾固知其如此而感念畴昔悲凉凄怆不觉临风而陨涕者有愧夫太上之忘情尚飨", "治平四年七月某日，具官欧阳修，谨派尚书都省令史李敭，到太清，用清酒和各种食物祭奠，致祭于亡友曼卿的墓下，并用文章吊念他。说：\n唉，曼卿！生为英杰，死为神灵。那同万物一样有生有死、而回归于无物的，是暂时聚合的形体；不同万物共同消亡、而卓然不朽的，是后世的名声。这是自古圣贤，没有不是这样，而记载在典籍上的，明亮如日月星辰。\n唉，曼卿！我见不到你很久了，还能仿佛记得你的一生。你那轩昂磊落、突兀峥嵘，而埋藏在地下的，想来不会化为腐土，而会成为金玉的精华。不然，就生长千尺的松树，产出九茎的灵芝。为什么荒烟野蔓，荆棘纵横；风凄露下，走磷飞萤！只见牧童樵夫，歌唱着上下；和那惊鸟骇兽，悲鸣徘徊而咿嘤。如今固然是这样，再过千秋万岁啊，怎么知道不会成为狐貉和鼯鼪的洞穴？这是自古圣贤也都如此啊，难道没有看见那旷野和荒城中累累的坟墓！\n唉，曼卿！盛衰的道理，我本来知道是这样，而感念往昔，悲凉凄怆，不觉临风而落泪，有愧于太上之忘情。请享用祭品吧！"],
    [196, "guwen-gwj-130", "public-domain", "呜呼惟我皇考崇公卜吉于泷冈之六十年其子修始克表于其阡非敢缓也盖有待也修不幸生四岁而孤太夫人守节自誓居穷自力于衣食以长以教俾至于成人太夫人告之曰「汝父为吏廉而好施与喜宾客其俸禄虽薄常不使有余曰『毋以是为我累』故其亡也无一瓦之覆一垄之植以庇而为生吾何恃而能自守邪吾于汝父知其一二以有待于汝也自吾为汝家妇不及事吾姑然知汝父之能养也汝孤而幼吾不能知汝之必有立然知汝父之必将有后也吾之始归也汝父免于母丧方逾年岁时祭祀则必涕泣曰『祭而丰不如养之薄也』间御酒食则又涕泣曰『昔常不足而今有余其何及也』吾始一二见之以为新免于丧适然耳既而其后常然至其终身未尝不然吾虽不及事姑而以此知汝父之能养也汝父为吏尝夜烛治官书屡废而叹吾问之则曰『此死狱也我求其生不得尔』吾曰『生可求乎』曰『求其生而不得则死者与我皆无恨也矧求而有得邪以其有得则知不求而死者有恨也夫常求其生犹失之死而世常求其死也』回顾乳者剑汝而立于旁因指而叹曰『术者谓我岁行在戌将死使其言然吾不及见儿之立也后当以我语告之』其平居教他子弟常用此语吾耳熟焉故能详也其施于外事吾不能知其居于家无所矜饰而所为如此是真发于中者邪呜呼其心厚于仁者邪此吾知汝父之必将有后也汝其勉之夫养不必丰要于孝利虽不得博于物要其心之厚于仁吾不能教汝此汝父之志也」修泣而志之不敢忘先公少孤力学咸平三年进士及第为道州判官泗绵二州推官又为泰州判官享年五十有九葬沙溪之泷冈太夫人姓郑氏考讳德仪世为江南名族太夫人恭俭仁爱而有礼初封福昌县太君进封乐安安康彭城三郡太君自其家少微时治其家以俭约其后常不使过之曰「吾儿不能苟合于世俭薄所以居患难也」其后修贬夷陵太夫人言笑自若曰「汝家故贫贱也吾处之有素矣汝能安之吾亦安矣」自先公之亡二十年修始得禄而养又十有二年列官于朝始得赠封其亲又十年修为龙图阁直学士尚书吏部郎中留守南京太夫人以疾终于官舍享年七十有二又八年修以非才入副枢密遂参政事又七年而罢自登二府天子推恩褒其三世盖自嘉祐以来逢国大庆必加宠锡皇曾祖府君累赠金紫光禄大夫太师中书令曾祖妣累封楚国太夫人皇祖府君累赠金紫光禄大夫太师中书令兼尚书令祖妣累封吴国太夫人皇考崇公累赠金紫光禄大夫太师中书令兼尚书令皇妣累封越国太夫人今上初郊皇考赐爵为崇国公太夫人进号魏国于是小子修泣而言曰「呜呼为善无不报而迟速有时此理之常也惟我祖考积善成德宜享其隆虽不克有于其躬而赐爵受封显荣褒大实有三朝之锡命是足以表见于后世而庇赖其子孙矣」乃列其世谱具刻于碑既又载我皇考崇公之遗训太夫人之所以教而有待于修者并揭于阡俾知夫小子修之德薄能鲜遭时窃位而幸全大节不辱其先者其来有自熙宁三年岁次庚戌四月辛酉朔十有五日乙亥男推诚保德崇仁翊戴功臣观文殿学士特进行兵部尚书知青州军州事兼管内劝农使充京东东路安抚使上柱国乐安郡开国公食邑四千三百户食实封一千二百户修表", "唉！我的先父崇公，卜葬于泷冈之后六十年，他的儿子修才能在墓道上立碑表。不是敢拖延，是因为有所等待。\n修不幸，出生四岁就失去了父亲。太夫人守节自誓，家境穷困，自己努力于衣食，来抚养来教育，使他直到成人。太夫人告诉我说：「你父亲做官廉洁，而喜好施与，喜欢宾客。他的俸禄虽然微薄，常常不让它有剩余，说：『不要因为这个成为我的牵累。』所以他去世时，没有一片瓦覆盖、一垄地种植来庇护而生活，我依靠什么能够自守呢？我对你父亲，知道一二，来等待你。自从我做你家的媳妇，来不及事奉我的婆婆，然而知道你父亲能孝养。你孤苦而年幼，我不能知道你一定会有成就，然而知道你父亲一定会有后人。我刚嫁来的时候，你父亲除去母丧才过一年，年节祭祀，就一定流泪说：『祭祀丰厚，不如生前微薄的奉养。』间或用酒食，就又流泪说：『从前常常不足，如今有余，哪里还来得及呢！』我起初一两次见到，以为是刚除丧偶然如此。后来就常常如此，直到他终身，没有不这样。我虽然没有来得及事奉婆婆，而因此知道你父亲能孝养。你父亲做官，曾在夜里点烛处理公文，多次放下而叹息。我问他，就说：『这是死刑案件，我寻求使他活而不得罢了。』我说：『生可以求得吗？』他说：『寻求使他活而不得，那么死者和我就都没有遗憾了；何况寻求而有所得呢？因为有所得，就知道不寻求而死者有遗憾。常常寻求使他活，还难免失误处死，而世上的人常常寻求处死他。』回头看见乳母抱着你站在旁边，于是指着你叹息说：『术士说我在戌年将死，假使他的话对，我来不及看见儿子成人了，以后应当把我的话告诉他。』他平时教导别的子弟，常用这些话，我听熟了，所以能详细知道。他施于外面的事，我不能知道；他在家里，没有什么矜持粉饰，而所作所为如此，是真正发自内心的吧。唉！他的心对仁是厚重的吧，这就是我知道你父亲一定会有后人的缘故。你要勉力啊！奉养不必丰厚，要紧的是孝；利益虽然不能遍及万物，要紧的是他的心对仁厚重。我不能教导你，这是你父亲的志向。」修哭着记住它，不敢忘记。\n先父年少丧父而努力学习，咸平三年进士及第，做道州判官，泗州、绵州两州推官，又做泰州判官。享年五十九岁，葬在沙溪的泷冈。太夫人姓郑，父亲名德仪，世代是江南的名族。太夫人恭敬节俭、仁爱而有礼，起初封福昌县太君，进封乐安、安康、彭城三郡太君。从家境微贱时起，就以俭约治家，后来常常不让超过，说：「我的儿子不能苟合于世，俭薄是用来处患难的。」后来修被贬夷陵，太夫人言笑自若，说：「你家本来就贫贱，我处之已经习惯了。你能安于它，我也就安了。」\n从先父去世二十年，修才得到俸禄而奉养。又过十二年，在朝廷做官，才能追赠封赐他的亲人。又过十年，修做龙图阁直学士、尚书吏部郎中，留守南京。太夫人因病在官舍去世，享年七十二岁。又过八年，修凭不才入副枢密，于是参预政事。又过七年而罢免。自从登上二府，天子推恩，褒奖他的三代。大概从嘉祐以来，遇上国家大庆，必定加以恩宠赏赐。曾祖府君累赠金紫光禄大夫、太师、中书令；曾祖妣累封楚国太夫人。祖府君累赠金紫光禄大夫、太师、中书令兼尚书令；祖妣累封吴国太夫人。先父崇公累赠金紫光禄大夫、太师、中书令兼尚书令；先母累封越国太夫人。当今皇上初次郊祀，先父赐爵为崇国公，太夫人进号魏国。\n于是小子修哭着说：「唉！行善没有不报答的，而迟早有一定的时候，这是常理。我的祖辈父辈，积善成德，应当享有它的隆盛，虽然不能在他们自身享有，而赐爵受封，显荣褒大，确实有三朝的赐命。这足以表见于后世，而庇护他们的子孙了。」于是排列他的世谱，全部刻在碑上。接着又记载我父亲崇公的遗训、太夫人之所以教导而等待于修的，一并揭示在墓道上。使人们知道我修德薄能少，遭遇时运窃居高位，而侥幸保全大节、不辱没先人的原因，是有来由的。\n熙宁三年岁次庚戌四月辛酉朔十五日乙亥，男推诚保德崇仁翊戴功臣、观文殿学士、特进行兵部尚书、知青州军州事、兼管内劝农使、充京东东路安抚使、上柱国、乐安郡开国公、食邑四千三百户、食实封一千二百户修上表。"],
    [197, "guwen-gwj-200", "", "管仲相威公霸诸侯攘夷狄终其身齐国富强诸侯不敢叛管仲死竖刁易牙开方用威公薨于乱五公子争立其祸蔓延讫简公齐无宁岁夫功之成非成于成之日盖必有所由起祸之作不作于作之日亦必有所由兆故齐之治也吾不曰管仲而曰鲍叔及其乱也吾不曰竖刁易牙开方而曰管仲何则竖刁易牙开方三子彼固乱人国者顾其用之者威公也夫有舜而后知放四凶有仲尼而后知去少正卯彼威公何人也顾其使威公得用三子者管仲也仲之疾也公问之相当是时也吾意以仲且举天下之贤者以对而其言乃不过曰「竖刁易牙开方三子非人情不可近」而已呜呼仲以为威公果能不用三子矣乎仲与威公处几年矣亦知威公之为人矣乎威公声不绝于耳色不绝于目而非三子者则无以遂其欲彼其初之所以不用者徒以有仲焉耳一日无仲则三子者可以弹冠而相庆矣仲以为将死之言可以絷威公之手足耶夫齐国不患有三子而患无仲有仲则三子者三匹夫耳不然天下岂少三子之徒哉虽威公幸而听仲诛此三人而其余者仲能悉数而去之耶呜呼仲可谓不知本者矣因威公之问举天下之贤者以自代则仲虽死而齐国未为无仲也夫何患三子者不言可也五霸莫盛于威文文公之才不过威公其臣又皆不及仲灵公之虐不如孝公之宽厚文公死诸侯不敢叛晋晋袭文公之余威犹得为诸侯之盟主百余年何者其君虽不肖而尚有老成人焉威公之薨也一败涂地无惑也彼独恃一管仲而仲则死矣夫天下未尝无贤者盖有有臣而无君者矣威公在焉而曰天下不复有管仲者吾不信也仲之书有记其将死论鲍叔宾胥无之为人且各疏其短是其心以为数子者皆不足以托国而又逆知其将死则其书诞谩不足信也吾观史䲡以不能进蘧伯玉而退弥子瑕故有身后之谏萧何且死举曹参以自代大臣之用心固宜如此也夫国以一人兴以一人亡贤者不悲其身之死而忧其国之衰故必复有贤者而后可以死彼管仲者何以死哉", "管仲辅佐齐桓公，称霸诸侯，排斥夷狄，终其一生齐国富强，诸侯不敢背叛。管仲死后，竖刁、易牙、开方被任用，桓公死在祸乱中，五个公子争位，祸乱蔓延，直到简公，齐国没有安宁的年份。\n功业的成就，不是成就于成功的那一天，一定有其起因；祸乱的发生，不发生在发生的那一天，也一定有其征兆。所以齐国的治理，我不说是管仲，而说是鲍叔。到了它的祸乱，我不说是竖刁、易牙、开方，而说是管仲。为什么呢？竖刁、易牙、开方三人，他们固然是祸乱别国的人，但任用他们的，是桓公。有舜然后知道流放四凶，有孔子然后知道除去少正卯。那桓公是什么人呢？但使桓公能够任用三人的，是管仲。\n管仲病重时，桓公问他谁做相。在这个时候，我以为管仲将举出天下的贤者来回答，而他的话不过是说「竖刁、易牙、开方三人，不合人情，不可亲近」罢了。唉！管仲以为桓公果真能不用三人吗？管仲与桓公相处几年了，也知道桓公的为人了吧？桓公耳边不断音乐，眼前不断女色，如果没有这三人，就无法满足他的欲望。他起初之所以不用，只是因为还有管仲罢了。一旦没有管仲，那么三人就可以弹冠相庆了。管仲以为将死的话，可以束缚桓公的手足吗？齐国不怕有三人，而怕没有管仲。有管仲，那么三人，只是三个匹夫罢了。不然，天下难道缺少三人的同类吗？即使桓公幸而听管仲，杀了这三人，而其余的，管仲能全部数出来去掉吗？唉！管仲可以说是不知道根本的人了。趁着桓公的问，举出天下的贤者来自代，那么管仲虽然死了，而齐国也不算没有管仲。何必忧虑三人呢？不说也可以。\n五霸没有比齐桓公、晋文公更盛的。文公的才能，不超过桓公，他的臣子又都比不上管仲。晋灵公的暴虐，不如齐孝公的宽厚。文公死后，诸侯不敢背叛晋国。晋国承袭文公的余威，还能做诸侯的盟主一百多年。为什么呢？它的君主虽然不贤，而还有老成持重的人。桓公死时，一败涂地，不奇怪，他单单依靠一个管仲，而管仲却死了。\n天下未尝没有贤者，大概有有臣而无君的。桓公在时，说天下不再有管仲那样的人，我不信。管仲的书，有记载他将死时评论鲍叔、宾胥无的为人，并且分别指出他们的短处。这是他心里认为这几个人，都不足以托付国家，而又预知自己将死，那么他的书荒诞虚妄不足信。我看史䲡，因为不能进用蘧伯玉而斥退弥子瑕，所以有身后的谏言。萧何将死，举荐曹参来自代。大臣的用心，本来应该这样。国家因一人而兴盛，因一人而灭亡。贤者不悲伤自身的死，而忧虑国家的衰败，所以一定还要有贤者，然后才可以死。那管仲，是怎么死的呢？"],
    [198, "guwen-gwj-201", "", "事有必至理有固然惟天下之静者乃能见微而知著月晕而风础润而雨人人知之人事之推移理势之相因其疏阔而难知变化而不可测者孰与天地阴阳之事而贤者有不知其故何也好恶乱其中而利害夺其外也昔者山巨源见王衍曰「误天下苍生者必此人也」郭汾阳见卢杞曰「此人得志吾子孙无遗类矣」自今而言之其理固有可见者以吾观之王衍之为人容貌言语固有以欺世而盗名者然不忮不求与物浮沉使晋无惠帝仅得中主虽衍百千何从而乱天下乎卢杞之奸固足以败国然而不学无文容貌不足以动人言语不足以眩世非德宗之鄙暗亦何从而用之由是言之二公之料二子亦容有未必然也今有人口诵孔老之言身履夷齐之行收召好名之士不得志之人相与造作言语私立名字以为颜渊孟轲复出而阴贼险狠与人异趣是王衍卢杞合而为一人也其祸岂可胜言哉夫面垢不忘洗衣垢不忘浣此人之至情也今也不然衣臣虏之衣食犬彘之食囚首丧面而谈诗书此岂其情也哉凡事之不近人情者鲜不为大奸慝竖刁易牙开方是也以盖世之名而济其未形之患虽有愿治之主好贤之相犹将举而用之则其为天下患必然而无疑者非特二子之比也孙子曰「善用兵者无赫赫之功」使斯人而不用也则吾言为过而斯人有不遇之叹孰知祸之至于此哉不然天下将被其祸而吾获知言之名悲夫", "事情有必然到来的，道理有本来如此的。只有天下静心的人，才能从细微处看到显著。月亮有晕就会刮风，柱础湿润就会下雨，人人都知道。人事的推移，情理的互相因循，那疏阔难知、变化不可测的，与天地阴阳的事相比如何？而贤者有不知道的，原因是什么呢？是好恶扰乱了他的内心，而利害剥夺了他的外在。\n从前山巨源见到王衍说：「误天下苍生的，一定是这个人！」郭汾阳见到卢杞说：「这个人得志，我的子孙就没有遗类了！」从今天来说，那道理本来有可以看出的。在我看来，王衍的为人，容貌言语，本来有可以欺世盗名的，但不嫉妒不贪求，随波逐流。假使晋朝没有惠帝，只得到一个中等君主，即使有千百个王衍，从哪里去乱天下呢？卢杞的奸邪，本来足以败坏国家，然而不学无术，容貌不足以动人，言语不足以惑世，不是德宗的浅陋昏庸，又从哪里任用他呢？由此说来，二公预料二人，也或许有未必一定如此的。\n如今有人口诵孔子、老子的话，身行伯夷、叔齐的操守，收召好名之士、不得志的人，一起造作言语，私自树立名号，认为是颜渊、孟轲复出，而阴险狠毒，与众人旨趣不同。这是王衍、卢杞合为一人，他的祸患难道可以说尽吗？脸上脏了不忘洗，衣服脏了不忘洗，这是人的至情。如今却不然，穿奴仆的衣服，吃猪狗的食物，像囚犯一样蓬头、像居丧一样垢面，却谈论诗书，这难道是他们的真情吗？凡是事情不近人情的，很少不是大奸大恶，竖刁、易牙、开方就是这样的。凭着盖世的名声，来助成他尚未形成的祸患，即使有愿意治国的君主、喜好贤才的宰相，还将举用他，那么他成为天下的祸患，是必然无疑的，不只是那两人的同类可比。\n孙子说：「善于用兵的人，没有显赫的功劳。」假使这个人不被任用，那么我的话就是错的，而这个人会有不遇的叹息，谁知道祸患会到这种地步呢？不然，天下将遭受他的祸患，而我获得知言的名声，可悲啊！"],
    [200, "guwen-gwj-203", "", "至和元年秋蜀人传言有寇至边边军夜呼野无居人妖言流闻京师震惊方命择帅天子曰「毋养乱毋助变众言朋兴朕志自定外乱不作变且中起不可以文令又不可以武竞惟朕一二大吏孰为能处兹文武之间其命往抚朕师」乃推曰「张公方平其人」天子曰「然」公以亲辞不可遂行冬十一月至蜀至之日归屯军撤守备使谓郡县「寇来在吾无尔劳苦」明年正月朔旦蜀人相庆如他日遂以无事又明年正月相告留公像于净众寺公不能禁眉阳苏洵言于众曰「未乱易治也既乱易治也有乱之萌无乱之形是谓将乱将乱难治不可以有乱急亦不可以无乱弛惟是元年之秋如器之欹未坠于地惟尔张公安坐于其旁颜色不变徐起而正之既正油然而退无矜容为天子牧小民不倦惟尔张公尔繄以生惟尔父母且公尝为我言『民无常性惟上所待人皆曰蜀人多变于是待之以待盗贼之意而绳之以绳盗贼之法重足屏息之民而以碪斧令于是民始忍以其父母妻子之所仰赖之身而弃之于盗贼故每每大乱夫约之以礼驱之以法惟蜀人为易至于急之而生变虽齐鲁亦然吾以齐鲁待蜀人而蜀人亦自以齐鲁之人待其身若夫肆意于法律之外以威劫齐民吾不忍为也』呜呼爱蜀人之深待蜀人之厚自公而前吾未始见也」皆再拜稽首曰「然」苏洵又曰「公之恩在尔心尔死在尔子孙其功业在史官无以像为也且公意不欲如何」皆曰「公则何事于斯虽然于我心有不释焉今夫平居闻一善必问其人之姓名与其乡里之所在以至于其长短大小美恶之状甚者或诘其平生所嗜好以想见其为人而史官亦书之于其传意使天下之人思之于心则存之于目存之于目故其思之于心也固由此观之像亦不为无助」苏洵无以诘遂为之记公南京人为人慷慨有大节以度量雄天下天下有大事公可属系之以诗曰天子在祚岁在甲午西人传言有寇在垣庭有武臣谋夫如云天子曰嘻命我张公公来自东旗纛舒舒西人聚观于巷于涂谓公暨暨公来于于公谓西人「安尔室家无敢或讹讹言不祥往即尔常春尔条桑秋尔涤场」西人稽首公我父兄公在西囿草木骈骈公宴其僚伐鼓渊渊西人来观祝公万年有女娟娟闺闼闲闲有童哇哇亦既能言昔公未来期汝弃捐禾麻芃芃仓庾崇崇嗟我妇子乐此岁丰公在朝廷天子股肱天子曰归公敢不承作堂严严有庑有庭公像在中朝服冠缨西人相告无敢逸荒公归京师公像在堂", "至和元年秋天，蜀人传言有敌寇到边境。边军夜里惊呼，野外没有居民。妖言流传，京城震惊。正要任命主帅，天子说：「不要养成祸乱，不要助长变故。众说纷起，我的主意自己定。外乱不发生，变故将从中而起。不可用文告命令，又不可用武力争胜，只有我的一两个大吏，谁能处在文武之间，就派他前往安抚我的军队。」于是推举说：「张公方平是这样的人。」天子说：「好。」张公以奉养双亲推辞，不允许，于是出发。冬十一月到蜀。到达那天，让屯驻的军队回去，撤除守备，派人对郡县说：「敌寇来了我在这里，不用你们劳苦。」第二年正月初一早晨，蜀人像往常一样互相庆贺，于是平安无事。又过一年正月，众人相告要在净众寺留张公的画像，张公不能禁止。\n眉阳苏洵对众人说：「未乱容易治理，已乱也容易治理，有乱的萌芽、没有乱的形迹，这叫将乱，将乱难治，不可以因为有乱而急躁，也不可以因为无乱而松弛。这元年秋天，像器物倾斜，还没有落地。只有你们的张公安坐旁边，神色不变，慢慢起来扶正它。扶正之后，自然退下，没有骄矜之色。为天子治理小民而不倦，只有你们的张公。你们因此得以生存，他就是你们的父母。况且张公曾对我说：『百姓没有固定的习性，只看上面对待他们的方式。人们都说蜀人多变，于是用对待盗贼的心意对待他们，用约束盗贼的法令约束他们，把重足屏息、恐惧不安的百姓，用刑具来管制。于是百姓才忍心把父母妻儿所仰赖的身体，抛弃给盗贼，所以常常大乱。如果用礼来约束，用法来驱使，只有蜀人最为容易。至于逼急了而生变，即使是齐鲁也是这样。我用对待齐鲁人的方式对待蜀人，而蜀人也自己用齐鲁人的标准要求自身。至于在法律之外肆意妄为，用威势胁迫平民，我不忍心做。』唉！爱蜀人之深、待蜀人之厚，从张公以前，我从未见过。」众人都再拜叩头说：「是这样。」\n苏洵又说：「张公的恩德在你们心里，你们死后在你们子孙心里，他的功业在史官那里，不必画像。况且张公的意思不想，怎么办？」众人都说：「张公哪里在乎这个？虽然如此，在我们心里有所放不下。如今平常听到一件善事，一定要问那人的姓名和他的乡里所在，以至于他长短大小美丑的样子，甚至有人追问他一生的嗜好，来想象他的为人。而史官也把它写在传里，意思是使天下的人，在心里思念他，就存想在他的眼里；存想在他眼里，所以他在心里思念也牢固。由此看来，画像也不是没有帮助。」苏洵无法反驳，于是为他作记。\n张公，南京人，为人慷慨有大节，以度量称雄天下。天下有大事，张公可以托付。系以诗说：\n天子在位，岁在甲午。西人传言，有寇在墙。朝廷有武臣，谋士如云。天子说唉，命我张公。张公来自东方，旗帜舒展。西人聚观，在巷在路。说公刚强，公来安舒。公对西人说：「安你们的家室，不要有讹言。讹言不祥，去恢复你们的常态。春天修剪桑树，秋天打扫谷场。」西人叩头，公是我们的父兄。公在西园，草木茂盛。公宴他的僚属，击鼓深深。西人来观看，祝公万年。有女子美好，闺门安闲。有孩童哇哇，也已能说话。从前公未来，料想你们被抛弃。禾麻茂盛，仓廪高耸。可叹我们的妻儿，乐享这丰收之年。公在朝廷，是天子的股肱。天子说归来，公敢不承命？建堂庄严，有廊有庭。公的画像在中间，朝服冠缨。西人相告，不敢安逸荒废。公回京师，公的画像在堂。"],
    [201, "guwen-gwj-204", "", "尧舜禹汤文武成康之际何其爱民之深忧民之切而待天下以君子长者之道也有一善从而赏之又从而咏歌嗟叹之所以乐其始而勉其终有一不善从而罚之又从而哀矜惩创之所以弃其旧而开其新故其吁俞之声欢休惨戚见于虞夏商周之书成康既没穆王立而周道始衰然犹命其臣吕侯而告之以祥刑其言忧而不伤威而不怒慈爱而能断恻然有哀怜无辜之心故孔子犹有取焉传曰「赏疑从与所以广恩也罚疑从去所以慎刑也」当尧之时皋陶为士将杀人皋陶曰「杀之」三尧曰「宥之」三故天下畏皋陶执法之坚而乐尧用刑之宽四岳曰「鲧可用」尧曰「不可鲧方命圮族」既而曰「试之」何尧之不听皋陶之杀人而从四岳之用鲧也然则圣人之意盖亦可见矣书曰「罪疑惟轻功疑惟重与其杀不辜宁失不经」呜呼尽之矣可以赏可以无赏赏之过乎仁可以罚可以无罚罚之过乎义过乎仁不失为君子过乎义则流而入于忍人故仁可过也义不可过也古者赏不以爵禄刑不以刀锯赏之以爵禄是赏之道行于爵禄之所加而不行于爵禄之所不加也刑之以刀锯是刑之威施于刀锯之所及而不施于刀锯之所不及也先王知天下之善不胜赏而爵禄不足以劝也知天下之恶不胜刑而刀锯不足以裁也是故疑则举而归之于仁以君子长者之道待天下使天下相率而归于君子长者之道故曰忠厚之至也诗曰「君子如祉乱庶遄已君子如怒乱庶遄沮」夫君子之已乱岂有异术哉时其喜怒而无失乎仁而已矣春秋之义立法贵严而责人贵宽因其褒贬之义以制赏罚亦忠厚之至也", "尧、舜、禹、汤、文、武、成、康的时候，爱民何其深，忧民何其切，而用君子长者的道理对待天下！有一件善事，就加以奖赏，又从而咏歌赞叹它，这是用来使他乐于开始而勉励他坚持到底。有一件不善的事，就加以责罚，又从而哀怜惩戒它，这是用来使他抛弃旧恶而开导新善。所以他们叹息赞许的声音，欢乐喜悦惨痛悲伤，见于虞、夏、商、周的书中。成、康既已去世，穆王即位，而周道开始衰微，然而还命令他的臣子吕侯，把善用刑罚的道理告诉他。他的话忧虑而不哀伤，威严而不愤怒，慈爱而能决断，恻然有哀怜无辜的心，所以孔子还有所取。\n《传》说：「奖赏有疑问就跟着给予，这是用来推广恩德；责罚有疑问就跟着免除，这是用来谨慎用刑。」在尧的时候，皋陶做士官。将要杀人，皋陶说「杀了他」三次，尧说「宽恕他」三次。所以天下敬畏皋陶执法的坚决，而乐于尧用刑的宽大。四岳说：「鲧可以用。」尧说：「不可，鲧违抗命令、毁灭族类。」过后却说：「试试他。」为什么尧不听皋陶的杀人，而听从四岳的用鲧呢？那么圣人的意思，大概也可以看出了。\n《书》说：「罪有疑问只从轻，功有疑问只从重。与其杀无辜的人，宁可失于不合常规。」唉，说尽了！可以奖赏，可以不奖赏，奖赏他就过于仁；可以责罚，可以不责罚，责罚他就过于义。过于仁，不失为君子；过于义，就流于残忍的人。所以仁可以过，义不可以过。\n古时候奖赏不用爵禄，刑罚不用刀锯。用爵禄奖赏，这是奖赏的道理施行于爵禄所加的地方，而不施行于爵禄所不加的地方。用刀锯刑罚，这是刑罚的威力施行于刀锯所及的地方，而不施行于刀锯所不及的地方。先王知道天下的善事赏不胜赏，而爵禄不足以劝勉；知道天下的恶事罚不胜罚，而刀锯不足以制裁。所以有疑问就一概归于仁，用君子长者的道理对待天下，使天下人相继归于君子长者的道理。所以说：忠厚到极点了。\n《诗》说：「君子如果赐福，祸乱差不多很快就止息。君子如果发怒，祸乱差不多很快就阻止。」君子止息祸乱，难道有特别的办法吗？适时地表示他的喜怒，而不失于仁罢了。《春秋》的大义，立法贵在严格，而责人贵在宽厚。根据它的褒贬的大义来制定赏罚，也是忠厚到极点了。"],
    [202, "guwen-gwj-205", "", "汉用陈平计间疏楚君臣项羽疑范增与汉有私稍夺其权增大怒曰「天下事大定矣君王自为之愿赐骸骨归卒伍」归未至彭城疽发背死苏子曰增之去善矣不去羽必杀增独恨其不早耳然则当以何事去增劝羽杀沛公羽不听终以此失天下当于是去耶曰否增之欲杀沛公人臣之分也羽之不杀犹有君人之度也增曷为以此去哉易曰「知几其神乎」诗曰「相彼雨雪先集维霰」增之去当于羽杀卿子冠军时也陈涉之得民也以项燕扶苏项氏之兴也以立楚怀王孙心而诸侯叛之也以弑义帝且义帝之立增为谋主矣义帝之存亡岂独为楚之盛衰亦增之所与同祸福也未有义帝亡而增独能久存者也羽之杀卿子冠军也是弑义帝之兆也其弑义帝则疑增之本也岂必待陈平哉物必先腐也而后虫生之人必先疑也而后谗入之陈平虽智安能间无疑之主哉吾尝论义帝天下之贤主也独遣沛公入关而不遣项羽识卿子冠军于稠人之中而擢以为上将不贤而能如是乎羽既矫杀卿子冠军义帝必不能堪非羽弑帝则帝杀羽不待智者而后知也增始劝项梁立义帝诸侯以此服从中道而弑之非增之意也夫岂独非其意将必力争而不听也不用其言而杀其所立羽之疑增必自此始矣方羽杀卿子冠军增与羽比肩而事义帝君臣之分未定也为增计者力能诛羽则诛之不能则去之岂不毅然大丈夫也哉增年已七十合则留不合则去不以此时明去就之分而欲依羽以成功陋矣虽然增高帝之所畏也增不去项羽不亡呜呼增亦人杰也哉", "汉王用了陈平的计谋，离间疏远楚国的君臣。项羽怀疑范增与汉王有私交，逐渐剥夺他的权力。范增大怒说：「天下大事已经定局了，君王自己去做吧，希望赏赐我这把老骨头回乡里。」回去还没到彭城，背上毒疮发作而死。苏子说：范增离去，是好的。不离去，项羽一定会杀范增。只遗憾他不早些罢了。\n那么应当因什么事离去？范增劝项羽杀沛公，项羽不听，终于因此失去天下，应当在这时离去吗？答：不是。范增想杀沛公，是做人臣的本分；项羽不杀，还有做君主的度量。范增何必因此离去呢？《易》说：「知道事情的几微，大概就是神吧！」《诗》说：「看那下雪，先凝聚的是霰。」范增离去，应当在项羽杀卿子冠军的时候。\n陈涉得到民心，靠的是项燕、扶苏的名义。项氏的兴起，靠的是立楚怀王的孙子心；而诸侯背叛他，是因为弑杀义帝。况且义帝的拥立，范增是主谋。义帝的存亡，难道只是楚国的盛衰，也是范增与之同祸福的。没有义帝死了而范增独能长久存在的。项羽杀卿子冠军，是弑义帝的征兆。他杀义帝，就是怀疑范增的根源，何必等陈平呢？东西一定先腐烂了，然后虫子才生出；人一定先怀疑了，然后谗言才进入。陈平虽然聪明，怎能离间没有疑惑的君主呢？\n我曾评论义帝，是天下的贤主。单单派沛公入关，而不派项羽；在众人中识别卿子冠军，而提拔为上将，不贤能能这样吗？项羽既已假托命令杀了卿子冠军，义帝一定不能忍受。不是项羽杀义帝，就是义帝杀项羽，不必等聪明人然后知道。范增起初劝项梁立义帝，诸侯因此服从。半路上却杀他，不是范增的意思。难道只是不是他的意思，还将一定力争而不被听从。不用他的话，却杀他所拥立的人，项羽怀疑范增一定从这里开始。\n当项羽杀卿子冠军时，范增与项羽并肩事奉义帝，君臣的名分还没有定。替范增打算，力量能杀项羽就杀他，不能就离开。难道不是刚毅的大丈夫吗？范增年纪已经七十，合就留，不合就走，不在这个时候表明去留的分际，却想依靠项羽成就功业，浅陋啊！虽然如此，范增，是高帝所畏惧的人。范增不离去，项羽不会灭亡。唉！范增也是人杰啊！"],
    [203, "guwen-gwj-131", "public-domain", "古之所谓豪杰之士者必有过人之节人情有所不能忍者匹夫见辱拔剑而起挺身而斗此不足为勇也天下有大勇者卒然临之而不惊无故加之而不怒此其所挟持者甚大而其志甚远也夫子房受书于圯上之老人也其事甚怪然亦安知其非秦之世有隐君子者出而试之观其所以微见其意者皆圣贤相与警戒之义而世不察以为鬼物亦已过矣且其意不在书当韩之亡秦之方盛也以刀锯鼎镬待天下之士其平居无罪夷灭者不可胜数虽有贲育无所复施夫持法太急者其锋不可犯而其势未可乘子房不忍忿忿之心以匹夫之力而逞于一击之间当此之时子房之不死者其间不能容发盖亦已危矣千金之子不死于盗贼何者其身之可爱而盗贼之不足以死也子房以盖世之才不为伊尹太公之谋而特出于荆轲聂政之计以侥幸于不死此圯上老人所为深惜者也是故倨傲鲜腆而深折之彼其能有所忍也然后可以就大事故曰「孺子可教也」楚庄王伐郑郑伯肉袒牵羊以逆庄王曰「其君能下人必能信用其民矣」遂舍之勾践之困于会稽而归臣妾于吴者三年而不倦且夫有报人之志而不能下人者是匹夫之刚也夫老人者以为子房才有余而忧其度量之不足故深折其少年刚锐之气使之忍小忿而就大谋何则非有平生之素卒然相遇于草野之间而命以仆妾之役油然而不怪者此固秦皇之所不能惊而项籍之所不能怒也观夫高祖之所以胜而项籍之所以败者在能忍与不能忍之间而已矣项籍唯不能忍是以百战百胜而轻用其锋高祖忍之养其全锋而待其弊此子房教之也当淮阴破齐而欲自王高祖发怒见于词色由此观之犹有刚强不忍之气非子房其谁全之太史公疑子房以为魁梧奇伟而其状貌乃如妇人女子不称其志气呜呼此其所以为子房欤", "古代所谓的豪杰之士，一定有超过常人的节操。人情有不能忍受的，匹夫受到侮辱，拔剑而起，挺身而斗，这不足以称为勇。天下有大勇的人，突然面临而不惊慌，无故加于身上而不发怒，这是因为他所抱负的很大，而他的志向很远。\n张子房在圯上老人那里接受兵书，这件事很奇怪。然而又怎么知道不是秦朝时有隐君子出来试探他呢？看他用来隐约显示意思的，都是圣贤互相警戒的道理，而世人不明察，以为是鬼物，也已经过分了。况且他的用意不在书。当韩国灭亡、秦朝正强盛时，用刀锯鼎镬来对待天下的士人，那些平居无罪被夷灭的，数不胜数。即使有孟贲、夏育，也无处施展。执法太急的，它的锋芒不可触犯，而它的形势不可利用。子房忍不住愤恨之心，以匹夫的力量，在一击之间逞能。在这个时候，子房没有死，其间的差距容不下一根头发，也已经危险了！千金的子弟，不死在盗贼手里。为什么呢？因为他的身体值得爱惜，而盗贼不值得为他去死。子房以盖世的才能，不去做伊尹、太公那样的谋划，而偏偏出于荆轲、聂政那样的计策，来侥幸不死，这是圯上老人所深深惋惜的。所以傲慢无礼而深深地折挫他。他能有所忍耐，然后才能成就大事，所以说：「这孩子可以教导了。」\n楚庄王攻打郑国，郑伯肉袒牵羊来迎接。庄王说：「他的国君能屈居人下，一定能信任任用他的百姓。」于是放过他。勾践被困在会稽，而归为吴国的臣妾，三年而不倦怠。况且有报仇的志向，而不能屈居人下的，是匹夫的刚强。那位老人，认为子房才能有余，而忧虑他的度量不足，所以深深折挫他少年的刚锐之气，使他忍住小的愤怒而成就大的谋划。为什么呢？并非有平生的交情，突然在草野之间相遇，而命令他做仆妾的差役，他却坦然不以为怪，这本来就是秦始皇所不能惊吓、项籍所不能激怒的。\n看高祖之所以胜利，而项籍之所以失败，就在于能忍与不能忍之间罢了。项籍只因不能忍，所以百战百胜而轻易使用他的锋芒；高祖忍住，养全他的锋芒而等待对方的疲弊，这是子房教他的。当淮阴侯攻破齐国而想自己称王，高祖发怒，表现在言词脸色上。由此看来，他还有刚强不能忍的气性，不是子房谁能成全他？\n太史公疑心子房应是魁梧奇伟的人，而他的状貌却像妇人女子，与他的志气不相称。唉！这正是他之所以为子房吧！"],
    [204, "guwen-gwj-206", "", "非才之难所以自用者实难惜乎贾生王者之佐而不能自用其才也夫君子之所取者远则必有所待所就者大则必有所忍古之贤人皆负可致之才而卒不能行其万一者未必皆其时君之罪或者其自取也愚观贾生之论如其所言虽三代何以远过得君如汉文犹且以不用死然则是天下无尧舜终不可有所为耶仲尼圣人历试于天下苟非大无道之国皆欲勉强扶持庶几一日得行其道将之荆先之以冉有申之以子夏君子之欲得其君如此其勤也孟子去齐三宿而后出昼犹曰「王其庶几召我」君子之不忍弃其君如此其厚也公孙丑问曰「夫子何为不豫」孟子曰「方今天下舍我其谁哉而吾何为不豫」君子之爱其身如此其至也夫如此而不用然后知天下果不足与有为而可以无憾矣若贾生者非汉文之不能用生生之不能用汉文也夫绛侯亲握天子玺而授之文帝灌婴连兵数十万以决刘吕之雌雄又皆高帝之旧将此其君臣相得之分岂特父子骨肉手足哉贾生洛阳之少年欲使其一朝之间尽弃其旧而谋其新亦已难矣为贾生者上得其君下得其大臣如绛灌之属优游浸渍而深交之使天子不疑大臣不忌然后举天下而惟吾之所欲为不过十年可以得志安有立谈之间而遽为人痛哭哉观其过湘为赋以吊屈原纡郁愤闷趯然有远举之志其后以自伤哭泣至于夭绝是亦不善处穷者也夫谋之一不见用则安知终不复用也不知默默以待其变而自残至此呜呼贾生志大而量小才有余而识不足也古之人有高世之才必有遗俗之累是故非聪明睿智不惑之主则不能全其用古今称苻坚得王猛于草茅之中一朝尽斥去其旧臣而与之谋彼其匹夫略有天下之半其以此哉愚深悲生之志故备论之亦使人君得如贾生之臣则知其有狷介之操一不见用则忧伤病沮不能复振而为贾生者亦谨其所发哉", "不是有才能难，而是如何善用自己的才能实在难。可惜啊！贾生，是帝王的辅佐之才，却不能善用自己的才能。\n君子所取的远，就一定有所等待；所成就的大，就一定有所忍耐。古代的贤人，都怀有可以成就功业的才能，而终究不能施行其万分之一的，未必都是当时君主的罪过，或许是他们自取的。\n我看贾生的议论，如果照他所说，即使三代又怎能远超？遇到像汉文帝这样的君主，尚且因不被任用而死。那么如果天下没有尧、舜，就终究不能有所作为吗？孔子是圣人，遍试于天下，只要不是大无道的国家，都想勉强扶持，希望有一天能施行自己的道。将到楚国，先派冉有去，再派子夏去重申。君子想得到他的君主，是这样的勤勉。孟子离开齐国，住了三宿才走出昼邑，还说：「大王大概会召见我。」君子不忍舍弃他的君主，是这样的深厚。公孙丑问：「先生为什么不高兴？」孟子说：「如今天下，除了我还有谁呢？我为什么不高兴？」君子爱惜自身，是这样的周到。这样而还不被任用，然后才知道天下果真不足以有所作为，而可以没有遗憾了。像贾生，不是汉文帝不能任用贾生，而是贾生不能善用汉文帝。\n绛侯亲自握着天子的玉玺而授给汉文帝，灌婴联合数十万军队，来决定刘、吕的胜负，又都是高帝的旧将，他们君臣相得的情分，难道只是父子骨肉手足吗？贾生，是洛阳的少年，想使他们在一旦之间，全部抛弃旧的而谋划新的，也已经很难了。做贾生的，上要得到他的君主，下要得到他的大臣，像绛侯、灌婴这些人，从容浸润而与他们深交，使天子不怀疑，大臣不忌妒，然后举天下只按我所想的去做，不过十年，就可以得志。哪有立谈之间，就急急为人痛哭的呢？看他过湘水作赋来凭吊屈原，郁结愤闷，跃然有远遁的志向。此后因自我哀伤哭泣，以至于夭折。这也是不善于处穷的人。谋划一次不被采用，怎么知道终究不再被采用呢？不知道默默等待变化，而自我摧残到这种地步。唉！贾生志向大而器量小，才能有余而见识不足。\n古代的人，有高出世人的才能，一定有被世俗遗弃的牵累。所以不是聪明睿智不惑的君主，就不能完全发挥他的作用。古今称苻坚从草野中得到王猛，一旦之间把旧臣全都斥退，而与他谋划。他一个匹夫占有天下的一半，大概就是因为这个吧！我深深地悲叹贾生的志向，所以详尽地评论他。也使君主得到像贾生这样的臣子时，就知道他有狷介的操守，一旦不被任用，就忧伤病沮，不能重新振作。而做贾生的，也要谨慎他所发抒的啊！"],
    [205, "guwen-gwj-132", "public-domain", "天下之患最不可为者名为治平无事而其实有不测之忧坐观其变而不为之所则恐至于不可救起而强为之则天下狃于治平之安而不吾信惟仁人君子豪杰之士为能出身为天下犯大难以求成大功此固非勉强期月之间而苟以求名之所能也天下治平无故而发大难之端吾发之吾能收之然后有辞于天下事至而循循焉欲去之使他人任其责则天下之祸必集于我昔者晁错尽忠为汉谋弱山东之诸侯山东诸侯并起以诛错为名而天子不之察以错为之说天下悲错之以忠而受祸不知错有以取之也古之立大事者不惟有超世之才亦必有坚忍不拔之志昔禹之治水凿龙门决大河而放之海方其功之未成也盖亦有溃冒冲突可畏之患惟能前知其当然事至不惧而徐为之图是以得至于成功夫以七国之强而骤削之其为变岂足怪哉错不于此时捐其身为天下当大难之冲而制吴楚之命乃为自全之计欲使天子自将而己居守且夫发七国之难者谁乎己欲求其名安所逃其患以自将之至危与居守之至安己为难首择其至安而遗天子以其至危此忠臣义士所以愤怨而不平者也当此之时虽无袁盎错亦未免于祸何者己欲居守而使人主自将以情而言天子固已难之矣而重违其议是以袁盎之说得行于其间使吴楚反错以身任其危日夜淬砺东向而待之使不至于累其君则天子将恃之以为无恐虽有百盎可得而间哉嗟夫世之君子欲求非常之功则无务为自全之计使错自将而讨吴楚未必无功惟其欲自固其身而天子不悦奸臣得以乘其隙错之所以自全者乃其所以自祸欤", "天下的祸患，最不好办的，是名义上太平无事，而其实有不可预测的忧患。坐着看它的变化，而不做处置，就怕到不可挽救；起来勉强去做，那么天下习惯于太平的安乐，而不相信我们。只有仁人君子豪杰之士，能够挺身而出为天下冒大难，来求成就大功。这本来不是勉强几个月之间、苟且求名的人所能做到的。天下太平，无故而发动大难的端绪；我发动它，我能收束它，然后才能对天下有说辞。事情来了就循循然想躲开它，使别人承担那个责任，那么天下的祸患，必定集中在我身上。\n从前晁错尽忠为汉朝，谋划削弱山东的诸侯。山东诸侯一齐起兵，以诛杀晁错为名。而天子不明察，用晁错来做解说。天下人悲伤晁错因忠而受祸，不知道晁错有自取的原因。\n古代建立大事的人，不仅有超世的才能，也一定有坚忍不拔的志向。从前禹治理洪水，开凿龙门，疏通大河而把它放归大海。当他的功业还没有成功时，大概也有溃决冲撞可畏的祸患。只因能预知它必然如此，事情到来不惧怕，而慢慢地设法对付，所以能够达到成功。凭七国的强大，而骤然削减它们，发生变乱难道值得奇怪吗？晁错不在这个时候舍弃自身，为天下承当大难的冲击，而控制吴、楚的命运，却做自我保全的打算，想让天子亲自领兵而自己留守。况且发动七国祸难的是谁呢？自己想求那个名声，哪里能逃避那个祸患？以亲自领兵的极危险，同留守的极安全相比，自己是祸首，却选择最安全的，而把最危险的留给天子，这是忠臣义士之所以愤怒不平的原因。在这个时候，即使没有袁盎，晁错也难免于祸。为什么呢？自己想留守，却让君主亲自领兵。从人情上说，天子本来已经为难，而又难以违背他的提议。所以袁盎的说法，得以在其中施行。假使吴、楚反叛，晁错以身承担那危险，日夜磨砺，向东等待他们，使事情不至于连累他的君主，那么天子将依靠他而无所恐惧。即使有一百个袁盎，能离间得了吗？\n唉！世上的君子，想求非常之功，就不要致力于自我保全的打算。假使晁错亲自领兵讨伐吴、楚，未必没有功劳。只因他想稳固自身，而天子不高兴，奸臣得以乘他的空隙。晁错用来自我保全的，正是他自取祸患的原因吧！"],
    [206, "guwen-gwj-46", "public-domain", "苏秦始将连横说秦惠王曰「大王之国西有巴蜀汉中之利北有胡貉代马之用南有巫山黔中之限东有殽函之固田肥美民殷富战车万乘奋击百万沃野千里蓄积饶多地势形便此所谓天府天下之雄国也以大王之贤士民之众车骑之用兵法之教可以并诸侯吞天下称帝而治愿大王少留意臣请奏其效」秦王曰「寡人闻之毛羽不丰满者不可以高飞文章不成者不可以诛罚道德不厚者不可以使民政教不顺者不可以烦大臣今先生俨然不远千里而庭教之愿以异日」苏秦曰「臣固疑大王之不能用也昔神农伐补遂黄帝伐涿鹿而禽蚩尤尧伐驩兜舜伐三苗禹伐共工汤伐有夏文王伐崇武王伐纣齐桓任战而伯天下由此观之恶有不战者乎古者使车毂击驰言语相结天下为一约从连横兵革不藏文士并饬诸侯乱惑万端俱起不可胜理科条既备民多伪态书策稠浊百姓不足上下相愁民无所聊明言章理兵甲愈起辩言伟服战攻不息繁称文辞天下不治舌弊耳聋不见成功行义约信天下不亲于是乃废文任武厚养死士缀甲厉兵效胜于战场夫徒处而致利安坐而广地虽古五帝三王五伯明主贤君常欲坐而致之其势不能故以战续之宽则两军相攻迫则杖戟相撞然后可建大功是故兵胜于外义强于内威立于上民服于下今欲并天下凌万乘诎敌国制海内子元元臣诸侯非兵不可今之嗣主忽于至道皆惛于教乱于治迷于言惑于语沉于辩溺于辞以此论之王固不能行也」说秦王书十上而说不行黑貂之裘敝黄金百斤尽资用乏绝去秦而归羸縢履跷负书担囊形容枯槁面目黧黑状有愧色归至家妻不下纴嫂不为炊父母不与言苏秦喟然叹曰「妻不以我为夫嫂不以我为叔父母不以我为子是皆秦之罪也」乃夜发书陈箧数十得太公阴符之谋伏而诵之简练以为揣摩读书欲睡引锥自刺其股血流至足曰「安有说人主不能出其金玉锦绣取卿相之尊者乎」期年揣摩成曰「此真可以说当世之君矣」于是乃摩燕乌集阙见说赵王于华屋之下抵掌而谈赵王大悦封为武安君受相印革车百乘锦绣千纯白璧百双黄金万镒以随其后约从散横以抑强秦故苏秦相于赵而关不通当此之时天下之大万民之众王侯之威谋臣之权皆欲决苏秦之策不费斗粮未烦一兵未战一士未绝一弦未折一矢诸侯相亲贤于兄弟夫贤人在而天下服一人用而天下从故曰式于政不式于勇式于廊庙之内不式于四境之外当秦之隆黄金万镒为用转毂连骑炫熿于道山东之国从风而服使赵大重且夫苏秦特穷巷掘门桑户棬枢之士耳伏轼撙衔横历天下廷说诸侯之王杜左右之口天下莫之能伉将说楚王路过洛阳父母闻之清宫除道张乐设饮郊迎三十里妻侧目而视倾耳而听嫂蛇行匍伏四拜自跪而谢苏秦曰「嫂何前倨而后卑也」嫂曰「以季子之位尊而多金」苏秦曰「嗟乎贫穷则父母不子富贵则亲戚畏惧人生世上势位富厚盖可忽乎哉」", "苏秦起初用连横的策略游说秦惠王，说：「大王的国家，西面有巴、蜀、汉中的物产，北面有胡貉、代地的马匹可用，南面有巫山、黔中的险阻，东面有殽山、函谷关的坚固。田地肥美，百姓富足，战车万辆，勇士百万，沃野千里，积蓄丰厚，地势便利，这就是所谓的天然府库，天下的强国。凭大王的贤明，士民的众多，车骑的效用，兵法的教习，可以兼并诸侯，吞并天下，称帝而统治。希望大王稍加留意，让我陈述它的成效。」\n秦王说：「我听说过：羽毛不丰满的不能高飞；法令不完备的不能施行刑罚；道德不深厚的不能驱使百姓；政教不顺的不能烦劳大臣。如今先生郑重地不远千里来当面指教，希望改日再谈。」\n苏秦说：「我本来就疑虑大王不能采纳。从前神农攻打补遂，黄帝攻打涿鹿而擒获蚩尤，尧攻打驩兜，舜攻打三苗，禹攻打共工，汤攻打夏桀，文王攻打崇国，武王攻打商纣，齐桓公凭借战争而称霸天下。由此看来，哪有不靠战争的呢？古时候使者车毂相击奔驰，用言语互相结盟，天下统一；后来合纵连横，兵甲不能收藏；文士纷纷巧饰言辞，诸侯迷惑混乱；各种事端一齐发生，无法一一治理；法令条文齐备，百姓多有虚伪之态；文书案卷繁杂污浊，百姓却不足；上下互相愁怨，百姓无所依托；明言道理，兵甲反而更起；巧言华服，攻战不休；繁称文辞，天下不安；舌头说破、耳朵听聋，不见成功；施行仁义、缔结信用，天下却不亲近。于是废弃文治而使用武力，厚养敢死之士，缝制铠甲、磨砺兵器，在战场上较量胜负。空手而想获利，安坐而想扩张土地，即使是古代的五帝、三王、五霸，明主贤君，常常想坐着得到，形势也不允许，所以用战争来继续。宽缓时两军互相攻击，紧迫时持戟相撞，然后才能建立大功。所以军队在外取胜，仁义在内强盛；威势在上面树立，百姓在下面服从。如今想要兼并天下，凌驾万乘之国，屈服敌国，控制海内，以百姓为子，以诸侯为臣，不用武力是不行的！如今的继位君主，忽略根本的道理，都被教化所迷惑，被治理所扰乱，被言辞所迷惑，被话语所蛊惑，沉溺于辩说，沉溺于辞令。由此说来，大王本来是不能施行的。」\n游说秦王的书信上了十次而主张不被采纳。黑貂皮衣破了，百斤黄金用尽，资用断绝，只好离开秦国回家。他绑着裹腿、穿着草鞋，背着书、挑着口袋，形容枯槁，面目黧黑，面带羞愧之色。回到家里，妻子不下织机，嫂子不为他做饭，父母不跟他说话。苏秦喟然叹息说：「妻子不把我当丈夫，嫂子不把我当小叔，父母不把我当儿子，这都是秦国的罪过！」于是连夜翻书，摆开几十个书箱，找到太公的《阴符》谋略，伏案诵读，精选提炼、反复揣摩。读书困了想睡，就拿锥子刺自己的大腿，血流到脚上，说：「哪有游说君主不能让他拿出金玉锦绣，获得卿相尊位的呢？」一年后，揣摩成功，说：「这真可以用来游说当代的君主了！」\n于是他就到燕乌集阙，在华丽的屋下进见游说赵王，抵掌而谈。赵王非常高兴，封他为武安君，授予相印，革车百乘，锦绣千匹，白璧百双，黄金万镒，跟在他后面，用来约合纵、散连横，抑制强秦。所以苏秦在赵国做相而函谷关不通。\n在这个时候，天下之大，万民之众，王侯的威势，谋臣的权术，都要由苏秦的策略决定。不费一斗粮食，不烦一兵一卒，不曾作战，不曾断弦，不曾折箭，诸侯就互相亲近，胜过兄弟。贤人在位而天下服从，一人被任用而天下跟从。所以说：要在政事上用功夫，不在勇力上用功夫；要在朝廷之内用功夫，不在四境之外用功夫。当苏秦隆盛的时候，黄金万镒供他使用，车马相连，光彩炫目于道路，崤山以东的国家，随风而服从，使赵国大大贵重起来。\n况且苏秦不过是一个穷巷掘门、桑户棬枢的士人罢了，伏在车前横木上、勒住马嚼子，横行天下，在朝廷上游说诸侯之王，堵住左右人的嘴，天下没有能同他抗衡的。\n将要去游说楚王，路过洛阳。父母听说后，打扫房屋、清扫道路，张设音乐、摆设酒宴，到三十里外郊迎。妻子侧着眼睛看，侧着耳朵听；嫂子像蛇一样匍匐爬行，拜了四拜、自己跪下谢罪。苏秦说：「嫂子为什么先前那样傲慢而后来这样卑下呢？」嫂子说：「因为小叔子地位尊贵而且钱多。」苏秦说：「唉！贫穷时父母不认儿子，富贵时亲戚都畏惧。人生在世，权势地位和富贵，怎么可以忽视呢！」"],
    [207, "guwen-gwj-47", "public-domain", "司马错与张仪争论于秦惠王前司马错欲伐蜀张仪曰「不如伐韩」王曰「请闻其说」对曰「亲魏善楚下兵三川塞轘辕缑氏之口当屯留之道魏绝南阳楚临南郑秦攻新城宜阳以临二周之郊诛周主之罪侵楚魏之地周自知不救九鼎宝器必出据九鼎按图籍挟天子以令天下天下莫敢不听此王业也今夫蜀西僻之国而戎狄之长也敝兵劳众不足以成名得其地不足以为利臣闻『争名者于朝争利者于市』今三川周室天下之市朝也而王不争焉顾争于戎狄去王业远矣」司马错曰「不然臣闻之欲富国者务广其地欲强兵者务富其民欲王者务博其德三资者备而王随之矣今王之地小民贫故臣愿从事于易夫蜀西僻之国也而戎狄之长也而有桀纣之乱以秦攻之譬如使豺狼逐群羊也取其地足以广国也得其财足以富民缮兵不伤众而彼已服矣故拔一国而天下不以为暴利尽西海诸侯不以为贪是我一举而名实两附而又有禁暴止乱之名今攻韩劫天子劫天子恶名也而未必利也又有不义之名而攻天下之所不欲危臣请谒其故周天下之宗室也齐韩周之与国也周自知失九鼎韩自知亡三川则必将二国并力合谋以因于齐赵而求解乎楚魏以鼎与楚以地与魏王不能禁此臣所谓危不如伐蜀之完也」惠王曰「善寡人听子」卒起兵伐蜀十月取之遂定蜀蜀主更号为侯而使陈庄相蜀蜀既属秦益强富厚轻诸侯", "司马错和张仪在秦惠王面前争论。司马错主张攻打蜀国，张仪说：「不如攻打韩国。」惠王说：「请让我听听你的理由。」\n张仪答道：「亲近魏国、交好楚国，出兵三川，堵塞轘辕、缑氏的关口，挡住屯留的道路，让魏国断绝南阳，楚国进逼南郑，秦国攻打新城、宜阳，进逼东西二周的郊外，声讨周王的罪过，侵占楚、魏的土地。周王自知无法挽救，九鼎宝器一定会拿出来。据有九鼎，掌握地图户籍，挟持天子来号令天下，天下没有敢不听从的，这是王业。至于蜀国，是西边偏僻的国家，戎狄的首领，损耗兵力、劳累百姓却不足以成名，得到它的土地也不足以获利。我听说：『争名的在朝廷，争利的在集市。』如今三川、周室，就是天下的集市和朝廷，大王不去争夺，反而去争夺戎狄之地，离王业太远了。」\n司马错说：「不对。我听说：想要国家富足的，一定要扩大它的土地；想要军队强大的，一定要使百姓富足；想要称王的，一定要广施恩德。这三样条件齐备，王业就随之而来。如今大王的土地狭小、百姓贫穷，所以我希望从容易的事做起。蜀国是西边偏僻的国家，戎狄的首领，而且有夏桀、商纣那样的祸乱。用秦国去攻打它，好比让豺狼驱赶羊群。取得它的土地足以扩大国土，得到它的财货足以使百姓富足，整顿军队而不用损伤大众，对方就已经降服了。所以攻取一个国家，天下却不认为残暴；利益遍及西海，诸侯却不认为贪婪。这是我们一举而名利双收，又有禁止暴乱的名声。如今攻打韩国、劫持天子，劫持天子是恶名，而且未必有利，又有不义的名声，去攻打天下人所不愿的，危险！请允许我说明缘故：周朝是天下的宗室；齐国是韩国、周国的盟国。周王自知要失去九鼎，韩王自知要失去三川，就一定使两国合力共谋，依托齐国、赵国，向楚国、魏国求援。把鼎送给楚国，把地送给魏国，大王不能禁止。这就是我所说的危险，不如攻打蜀国周全。」\n惠王说：「好！我听你的。」终于出兵攻打蜀国，十月攻取，于是平定了蜀国。蜀国君主改号为侯，派陈庄去做蜀相。蜀国归属秦国后，秦国更加强大富足，轻视诸侯。"],
    [208, "guwen-gwj-48", "public-domain", "范雎至秦王庭迎谓范雎曰「寡人宜以身受令久矣今者义渠之事急寡人日自请太后今义渠之事已寡人乃得以身受命躬窃闵然不敏敬执宾主之礼」范雎辞让是日见范雎见者无不变色易容者秦王屏左右宫中虚无人秦王跪而请曰「先生何以幸教寡人」范雎曰「唯唯」有间秦王复请范雎曰「唯唯」若是者三秦王跽曰「先生不幸教寡人乎」范雎谢曰「非敢然也臣闻始时吕尚之遇文王也身为渔父而钓于渭阳之滨耳若是者交疏也已一说而立为太师载与俱归者其言深也故文王果收功于吕尚卒擅天下而身立为帝王即使文王疏吕尚而弗与深言是周无天子之德而文武无与成其王也今臣羁旅之臣也交疏于王而所愿陈者皆匡君臣之事处人骨肉之间愿以陈臣之陋忠而未知王心也所以王三问而不对者是也」「臣非有所畏而不敢言也知今日言之于前而明日伏诛于后然臣弗敢畏也大王信行臣之言死不足以为臣患亡不足以为臣忧漆身而为厉被发而为狂不足以为臣耻五帝之圣而死三王之仁而死五伯之贤而死乌获之力而死奔育之勇而死死者人之所必不免也处必然之势可以少有补于秦此臣之所大愿也臣何患乎」「伍子胥橐载而出昭关夜行而昼伏至于菱水无以饵其口膝行蒲伏稽首肉袒鼓腹吹篪乞食于吴市卒兴吴国阖闾为伯使臣得进谋如伍子胥加之以幽囚终身不复见是臣说之行也臣何忧乎箕子接舆漆身而为厉被发而为狂无益于殷楚使臣得同行于箕子接舆可以补所贤之主是臣之大荣也臣又何耻乎」「臣之所恐者独恐臣死之后天下见臣尽忠而身蹶也因以杜口裹足莫肯即秦耳足下上畏太后之严下惑于奸臣之态居深宫之中不离阿保之手终身迷惑无与昭奸大者宗庙灭覆小者身以孤危此臣之所恐耳若夫穷辱之事死亡之患臣弗敢畏也臣死而秦治贤于生也」秦王跽曰「先生是何言也夫秦国僻远寡人愚不肖先生乃幸至此此天以寡人慁先生而存先王之庙也寡人得受命于先生此天所以幸先王而不弃其孤也先生奈何而言若此事无大小上及太后下至大臣愿先生悉以教寡人无疑寡人也」范雎再拜秦王亦再拜", "范雎来到秦国，秦昭王在朝廷上迎接他，对范雎说：「我早就应该亲自接受您的指教了。近来义渠的事情紧急，我每天亲自向太后请示。如今义渠的事情已经了结，我才能够亲自接受您的指教。我自己私下里觉得昏昧不敏，恭敬地行宾主之礼。」范雎推辞谦让。\n这一天昭王接见范雎，见到的人没有不改变脸色的。昭王屏退左右，宫中空无一人。昭王跪着请求说：「先生用什么来指教我呢？」范雎说：「嗯嗯。」过了一会儿，昭王又问，范雎说：「嗯嗯。」像这样三次。昭王长跪说：「先生不肯指教我吗？」\n范雎谢罪说：「不敢这样。我听说当初吕尚遇到文王时，不过是渔父在渭水北岸钓鱼罢了。像这样，交情是疏远的。不久一番交谈就被立为太师，同车一起回去，是因为他的话深入。所以文王果然从吕尚那里收到功效，终于拥有天下，自身成为帝王。假使文王疏远吕尚而不与他深谈，那就是周朝没有天子的德行，文王、武王也就无法成就王业。如今我是寄居在外的臣子，同大王交情疏远，而我所想陈述的，都是匡正君臣的大事、处在别人骨肉之间的事情。我愿献上自己浅陋的忠心，却不知道大王的心意，所以大王三次发问而我不回答，就是这个缘故。\n「我不是有所畏惧而不敢说，明知今天在您面前说了，明天就会在后面被杀，但我也不敢畏惧。大王如果真能施行我的话，死亡不足以成为我的忧患，逃亡不足以成为我的忧愁，漆身成为癞子，披发装疯，也不足以成为我的耻辱。五帝那样圣明也要死，三王那样仁德也要死，五霸那样贤能也要死，乌获那样有力也要死，孟奔、夏育那样勇猛也要死。死是人一定免不了的。处在必然之势中，能够对秦国稍有补益，这就是我最大的愿望，我有什么可忧患的呢？\n「伍子胥装进口袋里逃出昭关，夜里行走白天躲藏，到了菱水，没有东西吃，就跪着爬行，叩头露体，鼓着肚子吹篪，在吴国集市上讨饭，终于使吴国兴盛，阖闾成为霸主。假使我能像伍子胥那样进献谋略，即使被囚禁，终身不再见面，只要我的主张能施行，我有什么可忧愁的呢？箕子、接舆，漆身成为癞子，披发装疯，对殷朝、楚国没有益处。假使我能像箕子、接舆那样行事，而能对贤明的君主有所补益，这就是我最大的荣耀，我又有什么可耻的呢？\n「我所怕的，只是怕我死之后，天下人看到我尽忠而丧命，因而闭口止步，没有人肯到秦国来罢了。您上怕太后的威严，下被奸臣的丑态所迷惑，住在深宫之中，不离开保姆的手，终身迷惑，没有人帮您辨明奸邪。大则宗庙覆灭，小则自身孤立危险，这才是我所怕的。至于困厄屈辱的事，死亡的祸患，我不敢畏惧。我死了而秦国得以治理，胜过活着。」\n昭王长跪说：「先生这是什么话！秦国偏僻遥远，我又愚昧不贤，先生竟有幸来到这里，这是上天让我烦劳先生，来保存先王的宗庙。我能够接受先生的指教，这是上天眷顾先王而不抛弃它的孤儿。先生怎能说这样的话！事情无论大小，上到太后，下到大臣，希望先生全部指教我，不要对我存疑。」范雎拜了两拜，昭王也拜了两拜。"],
    [209, "guwen-gwj-49", "public-domain", "邹忌修八尺有余而形貌昳丽朝服衣冠窥镜谓其妻曰「我孰与城北徐公美」其妻曰「君美甚徐公何能及君也」城北徐公齐国之美丽者也忌不自信而复问其妾曰「吾孰与徐公美」妾曰「徐公何能及君也」旦日客从外来与坐谈问之客曰「吾与徐公孰美」客曰「徐公不若君之美也」明日徐公来孰视之自以为不如窥镜而自视又弗如远甚暮寝而思之曰「吾妻之美我者私我也妾之美我者畏我也客之美我者欲有求于我也」于是入朝见威王曰「臣诚知不如徐公美臣之妻私臣臣之妾畏臣臣之客欲有求于臣皆以美于徐公今齐地方千里百二十城宫妇左右莫不私王朝廷之臣莫不畏王四境之内莫不有求于王由此观之王之蔽甚矣」王曰「善」乃下令「群臣吏民能面刺寡人之过者受上赏上书谏寡人者受中赏能谤讥于市朝闻寡人之耳者受下赏」令初下群臣进谏门庭若市数月之后时时而间进期年之后虽欲言无可进者燕赵韩魏闻之皆朝于齐此所谓战胜于朝廷", "邹忌身高八尺多，容貌光艳美丽。早晨穿戴好衣帽，照着镜子，对他的妻子说：「我与城北徐公相比谁更美？」他的妻子说：「您美得多，徐公怎么能比得上您！」城北徐公是齐国出名的美男子。邹忌不相信自己，又问他的妾：「我与徐公相比谁更美？」妾说：「徐公怎么能比得上您！」第二天，有客人从外面来，邹忌与他坐下交谈，问客人：「我与徐公相比谁更美？」客人说：「徐公不如您美。」\n第二天徐公来了，邹忌仔细端详他，自认为不如；照着镜子看自己，更觉得差得远。晚上躺下思考这件事，说：「我的妻子说我美，是偏爱我；妾说我美，是怕我；客人说我美，是有求于我。」\n于是入朝见齐威王，说：「我确实知道不如徐公美。我的妻子偏爱我，我的妾怕我，我的客人有求于我，都说我比徐公美。如今齐国土地方圆千里，一百二十座城，宫中的妃子和左右近臣没有不偏爱大王的，朝廷的臣子没有不怕大王的，国境之内没有不有求于大王的：由此看来，大王受蒙蔽很深了。」\n威王说：「好。」于是下令：「群臣百姓，能当面指出我的过错的，受上等奖赏；上书劝谏我的，受中等奖赏；能在公共场所议论我的过失、传到我耳中的，受下等奖赏。」\n命令刚下达时，群臣进谏，门前庭院像集市一样；几个月之后，还时不时有人进谏；满一年之后，即使想进言，也没有什么可说的了。燕、赵、韩、魏听说这件事，都来齐国朝见。这就是所谓的在朝廷上战胜别国。"],
    [211, "guwen-gwj-51", "public-domain", "齐人有冯谖者贫乏不能自存使人属孟尝君愿寄食门下孟尝君曰「客何好」曰「客无好也」曰「客何能」曰「客无能也」孟尝君笑而受之曰「诺」左右以君贱之也食以草具居有顷倚柱弹其剑歌曰「长铗归来乎食无鱼」左右以告孟尝君曰「食之比门下之客」居有顷复弹其铗歌曰「长铗归来乎出无车」左右皆笑之以告孟尝君曰「为之驾比门下之车客」于是乘其车揭其剑过其友曰「孟尝君客我」后有顷复弹其剑铗歌曰「长铗归来乎无以为家」左右皆恶之以为贪而不知足孟尝君问「冯公有亲乎」对曰「有老母」孟尝君使人给其食用无使乏于是冯谖不复歌后孟尝君出记问门下诸客「谁习计会能为文收责于薛者乎」冯谖署曰「能」孟尝君怪之曰「此谁也」左右曰「乃歌夫『长铗归来』者也」孟尝君笑曰「客果有能也吾负之未尝见也」请而见之谢曰「文倦于事愦于忧而性懧愚沉于国家之事开罪于先生先生不羞乃有意欲为收责于薛乎」冯谖曰「愿之」于是约车治装载券契而行辞曰「责毕收以何市而反」孟尝君曰「视吾家所寡有者」驱而之薛使吏召诸民当偿者悉来合券券遍合起矫命以责赐诸民因烧其券民称万岁长驱到齐晨而求见孟尝君怪其疾也衣冠而见之曰「责毕收乎来何疾也」曰「收毕矣」「以何市而反」冯谖曰「君云『视吾家所寡有者』臣窃计君宫中积珍宝狗马实外厩美人充下陈君家所寡有者以义耳窃以为君市义」孟尝君曰「市义奈何」曰「今君有区区之薛不拊爱子其民因而贾利之臣窃矫君命以责赐诸民因烧其券民称万岁乃臣所以为君市义也」孟尝君不说曰「诺先生休矣」后期年齐王谓孟尝君曰「寡人不敢以先王之臣为臣」孟尝君就国于薛未至百里民扶老携幼迎君道中孟尝君顾谓冯谖曰「先生所为文市义者乃今日见之」冯谖曰「狡兔有三窟仅得免其死耳今君有一窟未得高枕而卧也请为君复凿二窟」孟尝君予车五十乘金五百斤西游于梁谓梁王曰「齐放其大臣孟尝君于诸侯诸侯先迎之者富而兵强」于是梁王虚上位以故相为上将军遣使者黄金千斤车百乘往聘孟尝君冯谖先驱诫孟尝君曰「千金重币也百乘显使也齐其闻之矣」梁使三反孟尝君固辞不往也齐王闻之君臣恐惧遣太傅赍黄金千斤文车二驷服剑一封书谢孟尝君曰「寡人不祥被于宗庙之祟沉于谄谀之臣开罪于君寡人不足为也愿君顾先王之宗庙姑反国统万人乎」冯谖诫孟尝君曰「愿请先王之祭器立宗庙于薛」庙成还报孟尝君曰「三窟已就君姑高枕为乐矣」孟尝君为相数十年无纤介之祸者冯谖之计也", "齐国有个叫冯谖的人，穷得无法养活自己，托人请求投到孟尝君门下做食客。孟尝君问：「客人有什么爱好？」回答说：「没有什么爱好。」问：「客人有什么才能？」回答说：「没有什么才能。」孟尝君笑着接受了他，说：「好。」\n手下人因为孟尝君看轻他，给他吃粗劣的饭食。过了不久，他靠着柱子敲击他的剑，唱道：「长剑啊，我们回去吧！吃饭没有鱼。」左右的人把这事报告了。孟尝君说：「给他鱼吃，比照门下一般食客的待遇。」过了不久，又敲击剑柄唱道：「长剑啊，我们回去吧！出门没有车。」左右的人都笑他，又报告了。孟尝君说：「给他备车，比照门下有车食客的待遇。」于是冯谖坐上他的车，举着他的剑，去拜访他的朋友说：「孟尝君把我当客人看待了。」后来又过了不久，他又敲击剑柄唱道：「长剑啊，我们回去吧！没有钱养家。」左右的人都厌恶他，认为他贪心不知足。孟尝君问：「冯公还有亲人吗？」回答说：「有位老母亲。」孟尝君派人供给她吃用，不让她短缺。于是冯谖不再唱歌了。\n后来孟尝君出了文告，问门下众客：「谁熟悉会计，能替我到薛地收债？」冯谖署名说：「我能。」孟尝君觉得奇怪，问：「这是谁呀？」左右的人说：「就是唱『长剑归来』的那个人。」孟尝君笑着说：「客人果然有才能！我对不起他，还没有见过他。」便请他来见，致歉说：「我因事务疲倦，因忧愁昏乱，天性又愚笨，沉溺于国家大事，得罪了先生。先生不以为羞，竟愿意替我到薛地收债吗？」冯谖说：「愿意。」于是备好车马、整理行装，载着债券契约出发，告辞说：「债收完了，买些什么回来？」孟尝君说：「看我家缺少什么。」\n冯谖驱车到了薛地，让官吏召集该还债的百姓，都来验对债券。债券全部验完，他站起来，假托孟尝君的命令把债赐还给百姓，随即烧掉了债券，百姓高呼万岁。\n冯谖一路快车回到齐国，清晨就求见。孟尝君奇怪他回来得这么快，穿戴整齐接见他，问：「债收完了吗？怎么回来得这么快！」冯谖说：「收完了。」「买了什么回来？」冯谖说：「您说『看我家缺少什么』。我私下盘算，您宫中堆满珍宝，狗马充满外厩，美人站满下陈。您家缺少的只是「义」罢了！所以我私下替您买了义。」孟尝君说：「买义是怎么回事？」冯谖说：「如今您只有小小的薛地，不把百姓当作子女一样爱护，反而像商人一样从他们身上取利。我私下假托您的命令，把债赐还给百姓，烧掉了债券，百姓高呼万岁。这就是我替您买义的方式。」孟尝君不高兴，说：「好，先生算了吧！」\n过了一年，齐王对孟尝君说：「我不敢把先王的臣子当作自己的臣子。」孟尝君只好回到封地薛。还没到百里，百姓已扶老携幼，在路上迎接他。孟尝君回头对冯谖说：「先生替我买的义，今天见到了。」\n冯谖说：「狡猾的兔子有三个洞穴，才仅仅能免于一死。如今您只有一个洞穴，还不能高枕无忧。请让我替您再挖两个。」孟尝君给他五十辆车、五百斤金，让他西去游说梁国，对梁王说：「齐国放逐他的大臣孟尝君到诸侯国，诸侯先迎接他的，就能国富兵强。」于是梁王空出相位，把原来的相国调为上将军，派使者带黄金千斤、车百乘去聘请孟尝君。冯谖先赶回去，告诫孟尝君说：「千斤黄金是厚重的聘礼，百乘车是显赫的使节。齐国大概已经听说了。」梁国使者往返三次，孟尝君坚决推辞不去。齐王听说后，君臣恐惧，派太傅带着黄金千斤、彩饰的车四马二乘、佩剑一把，封好书信向孟尝君谢罪说：「我不吉利，遭受宗庙降下的灾祸，被谄媚阿谀之臣蒙蔽，得罪了您。我不值得您顾念，只愿您顾念先王的宗庙，姑且回国治理万民吧！」冯谖告诫孟尝君说：「希望您请来先王的祭器，在薛地建立宗庙。」宗庙建成，冯谖回来向孟尝君报告说：「三个洞穴已经完成，您姑且高枕无忧享乐吧。」\n孟尝君做相国几十年，没有细微的祸患，都是冯谖的计谋。"],
    [212, "guwen-gwj-52", "public-domain", "齐王使使者问赵威后书未发威后问使者曰「岁亦无恙耶民亦无恙耶王亦无恙耶」使者不说曰「臣奉使使威后今不问王而先问岁与民岂先贱而后尊贵者乎」威后曰「不然苟无岁何以有民苟无民何以有君故有问舍本而问末者耶」乃进而问之曰「齐有处士曰钟离子无恙耶是其为人也有粮者亦食无粮者亦食有衣者亦衣无衣者亦衣是助王养其民者也何以至今不业也叶阳子无恙乎是其为人哀鳏寡恤孤独振困穷补不足是助王息其民者也何以至今不业也北宫之女婴儿子无恙耶彻其环瑱至老不嫁以养父母是皆率民而出于孝情者也胡为至今不朝也此二士弗业一女不朝何以王齐国子万民乎於陵子仲尚存乎是其为人也上不臣于王下不治其家中不索交诸侯此率民而出于无用者何为至今不杀乎」", "齐王派使者去问候赵威后。书信还没有拆开，威后就问使者说：「今年的收成还好吗？百姓还好吗？大王还好吗？」使者不高兴，说：「我奉使命来问候威后，如今您不先问大王而先问收成和百姓，难道是把卑贱的放在前面而把尊贵的放在后面吗？」威后说：「不是这样。如果没有收成，怎么会有百姓？如果没有百姓，怎么会有国君？所以哪有问话舍弃根本而问末节的道理呢？」\n于是进一步问他说：「齐国有个处士叫钟离子，还好吗？这个人的为人，有粮食的人他给吃的，没有粮食的人他也给吃的；有衣服的人他给穿的，没有衣服的人他也给穿的。这是帮助国君养育百姓的人，为什么至今不给他官职？叶阳子还好吗？这个人的为人，怜悯鳏夫寡妇，体恤孤儿孤老，赈济困苦贫穷，补助不足。这是帮助国君使百姓繁衍生息的人，为什么至今不给他官职？北宫家的女儿婴儿子还好吗？她摘掉耳环玉饰，到老不嫁，来奉养父母。这些都是引导百姓行孝的人，为什么至今不让她入朝受封？这两位士人不受任用，一位女子不入朝，怎么能统治齐国、以万民为子呢？於陵的子仲还在吗？这个人的为人，上不肯做国君的臣子，下不肯治理自己的家，中不肯结交诸侯。这是引导百姓走向无用的人，为什么至今不把他杀掉呢？」"],
    [213, "guwen-gwj-53", "public-domain", "庄辛谓楚襄王曰「君王左州侯右夏侯辇从鄢陵君与寿陵君专淫逸侈靡不顾国政郢都必危矣」襄王曰「先生老悖乎将以为楚国祅祥乎」庄辛曰「臣诚见其必然者也非敢以为国祅祥也君王卒幸四子者不衰楚国必亡矣臣请辟于赵淹留以观之」庄辛去之赵留五月秦果举鄢郢巫上蔡陈之地襄王流掩于城阳于是使人发驺征庄辛于赵庄辛曰「诺」庄辛至襄王曰「寡人不能用先生之言今事至于此为之奈何」庄辛对曰「臣闻鄙语曰『见兔而顾犬未为晚也亡羊而补牢未为迟也』臣闻昔汤武以百里昌桀纣以天下亡今楚国虽小绝长续短犹以数千里岂特百里哉」「王独不见夫蜻蛉乎六足四翼飞翔乎天地之间俛啄蚊虻而食之仰承甘露而饮之自以为无患与人无争也不知夫五尺童子方将调饴胶丝加己乎四仞之上而下为蝼蚁食也」「夫蜻蛉其小者也黄雀因是以俯噣白粒仰栖茂树鼓翅奋翼自以为无患与人无争也不知夫公子王孙左挟弹右摄丸将加己乎十仞之上以其类为招昼游乎茂树夕调乎酸咸倏忽之间坠于公子之手」「夫黄雀其小者也黄鹄因是以游于江海淹乎大沼俯噣鳝鲤仰啮菱衡奋其六翮而凌清风飘摇乎高翔自以为无患与人无争也不知夫射者方将修其碆卢治其缯缴将加己乎百仞之上被礛磻引微缴折清风而抎矣故昼游乎江河夕调乎鼎鼐」「夫黄鹄其小者也蔡灵侯之事因是以南游乎高陂北陵乎巫山饮茹溪之流食湘波之鱼左抱幼妾右拥嬖女与之驰骋乎高蔡之中而不以国家为事不知夫子发方受命乎灵王系己以朱丝而见之也」「蔡灵侯之事其小者也君王之事因是以左州侯右夏侯辇从鄢陵君与寿陵君饭封禄之粟而载方府之金与之驰骋乎云梦之中而不以天下国家为事不知夫穰侯方受命乎秦王填黾塞之内而投己乎黾塞之外」襄王闻之颜色变作身体战栗于是乃以执珪而授之为阳陵君与淮北之地也", "庄辛对楚襄王说：「君王左边是州侯，右边是夏侯，车后跟着鄢陵君和寿陵君，一味地放荡奢侈，不顾国家政事，郢都一定危险了。」襄王说：「先生是老糊涂了呢，还是认为楚国将有妖异之兆呢？」庄辛说：「我确实看到了必然如此，不敢认为是国家的妖异之兆。君王如果始终宠幸那四个人而不减，楚国一定灭亡。请让我到赵国去躲避，停留一段时间来观察。」\n庄辛离开楚国到赵国，留了五个月，秦国果然攻取鄢、郢、巫、上蔡、陈等地，襄王流亡躲到城阳。于是派人派车到赵国召庄辛。庄辛说：「好。」\n庄辛来到，襄王说：「我不能采纳先生的意见，如今事情到了这个地步，怎么办？」庄辛答道：「我听俗语说：『看见兔子才回头唤狗，还不算晚；丢了羊再修补羊圈，还不算迟。』我听说从前汤、武凭百里之地而昌盛，桀、纣拥有天下而灭亡。如今楚国虽然小，截长补短，还有数千里，哪里只有百里呢？\n「大王难道没有见过蜻蜓吗？六只脚四只翅膀，在天地之间飞翔，低头啄食蚊虻，仰头承接甘露来喝，自以为没有祸患，同谁也没有争竞。不知道五尺高的孩童，正在调和糖浆、粘上蛛丝，要把它从四仞高的地方粘下来，掉下去成为蝼蛄蚂蚁的食物。\n「蜻蜓还算是小的，黄雀也是这样。低头啄食白米，仰头栖在茂密的树上，鼓翅奋飞，自以为没有祸患，同谁也没有争竞。不知道公子王孙左手拿着弹弓，右手捏着弹丸，要把它从十仞高的地方打下来，拿它的同类做靶子。白天还在茂密的树上游玩，傍晚就被调上酸咸作料，转眼之间，落到公子的手里。\n「黄雀还算是小的，黄鹄也是这样。在江海里游荡，停在大沼泽里，低头啄食鳝鱼鲤鱼，仰头咀嚼菱角香草，振起六根羽茎，乘着清风，飘摇高飞，自以为没有祸患，同谁也没有争竞。不知道射手正修理石箭头、整理丝绳，要把它从百仞高的地方射下来，被锐利的石镞射中，牵引着细丝，从清风中坠落。所以白天还在江河上游荡，傍晚就被放在鼎鼐里烹调。\n「黄鹄还算是小的，蔡灵侯的事情也是这样。他南游高陂，北登巫山，喝茹溪的水，吃湘江的鱼，左手抱着年轻的妾，右手拥着宠爱的女子，同她们在高蔡之中驰骋，而不把国家政事放在心上。不知道子发正接受楚灵王的命令，用红绳把他绑了去见灵王。\n「蔡灵侯的事情还算是小的，君王的事情也是这样。左边是州侯，右边是夏侯，车后跟着鄢陵君和寿陵君，吃着封地的粮食，载着国库的金钱，同他们在云梦之中驰骋，而不把天下国家放在心上。不知道穰侯正接受秦王的命令，要占领黾塞之内，把您抛到黾塞之外。」\n襄王听了，脸色大变，身体发抖。于是授给他执珪的爵位，封他为阳陵君，并把淮北的土地赐给他。"],
    [214, "guwen-gwj-54", "public-domain", "赵太后新用事秦急攻之赵氏求救于齐齐曰「必以长安君为质兵乃出」太后不肯大臣强谏太后明谓左右「有复言令长安君为质者老妇必唾其面」左师触龙言愿见太后盛气而胥之入而徐趋至而自谢曰「老臣病足曾不能疾走不得见久矣窃自恕恐太后玉体之有所郄也故愿望见」太后曰「老妇恃辇而行」曰「日食饮得无衰乎」曰「恃粥耳」曰「老臣今者殊不欲食乃自强步日三四里少益嗜食和于身」太后曰「老妇不能」太后之色少解左师公曰「老臣贱息舒祺最少不肖而臣衰窃爱怜之愿令补黑衣之数以卫王宫没死以闻」太后曰「敬诺年几何矣」对曰「十五岁矣虽少愿及未填沟壑而托之」太后曰「丈夫亦爱怜其少子乎」对曰「甚于妇人」太后曰「妇人异甚」对曰「老臣窃以为媪之爱燕后贤于长安君」太后曰「君过矣不若长安君之甚」左师公曰「父母之爱子则为之计深远媪之送燕后也持其踵为之泣念悲其远也亦哀之矣已行非弗思也祭祀必祝之祝曰『必勿使反』岂非计久长有子孙相继为王也哉」太后曰「然」左师公曰「今三世以前至于赵之为赵赵王之子孙侯者其继有在者乎」曰「无有」曰「微独赵诸侯有在者乎」曰「老妇不闻也」「此其近者祸及身远者及其子孙岂人主之子孙则必不善哉位尊而无功奉厚而无劳而挟重器多也今媪尊长安君之位而封之以膏腴之地多与之重器而不及今令有功于国一旦山陵崩长安君何以自托于赵老臣以媪为长安君计短也故以为其爱不若燕后」太后曰「诺恣君之所使之」于是为长安君约车百乘质于齐齐兵乃出子义闻之曰「人主之子也骨肉之亲也犹不能恃无功之尊无劳之奉而守金玉之重也而况人臣乎」", "赵太后刚刚执政，秦国急攻赵国。赵国向齐国求救。齐国说：「一定要用长安君做人质，才出兵。」太后不肯，大臣们极力劝谏。太后明确地对左右说：「有再敢说让长安君做人质的，老太婆一定把唾沫吐在他脸上！」\n左师触龙说希望进见。太后怒气冲冲地等着他。触龙进去后慢慢地小步走，到了跟前自己谢罪说：「老臣脚有病，竟不能快走，很久不能来拜见了。我私下宽恕自己，又怕太后的身体有所不适，所以希望来见见。」太后说：「老太婆靠坐车行走。」触龙说：「每天的饮食该没有减少吧？」太后说：「靠喝粥罢了。」触龙说：「老臣近来很不想吃东西，就自己勉强走走，每天三四里，稍稍增加了食欲，身体也舒服些。」太后说：「老太婆做不到。」太后的脸色稍微缓和了。\n左师公说：「老臣的贱子舒祺，年纪最小，不成材。而我已衰老，私下疼爱他。希望能让他补上黑衣卫士的名额，来保卫王宫，我冒死来禀告。」太后说：「好的。年纪多大了？」触龙答道：「十五岁了。虽然年幼，希望趁我还没有入土就把他托付给您。」太后说：「男人也疼爱小儿子吗？」触龙答道：「比女人还厉害。」太后说：「女人更加厉害。」触龙答道：「老臣私下认为您疼爱燕后胜过长安君。」太后说：「您错了，不如疼爱长安君那样厉害。」\n左师公说：「父母疼爱子女，就要为他们作长远的打算。您送燕后出嫁时，握着她的脚跟为她哭泣，想着她远嫁而悲伤，也是哀怜她了。她走了以后，不是不想念，祭祀时一定为她祝祷，祝祷说：『一定不要让她被送回来。』这难道不是为她作长远的打算，希望她的子孙相继做王吗？」太后说：「是的。」\n左师公说：「如今往上数三代以前，直到赵国建立的时候，赵王的子孙封侯的，他们的继承人还有在的吗？」太后说：「没有。」触龙说：「不只是赵国，其他诸侯的子孙还有在的吗？」太后说：「老太婆没有听说过。」触龙说：「这就是近的灾祸落到自己身上，远的落到子孙身上。难道是国君的子孙就一定不好吗？是因为地位尊贵而没有功勋，俸禄丰厚而没有劳绩，却拥有许多贵重宝物。如今您抬高长安君的地位，封给他肥沃的土地，多给他贵重宝物，却不趁现在让他为国家立功。一旦您去世，长安君凭什么在赵国立足？老臣认为您为长安君打算得太短浅了，所以认为您对他的疼爱不如对燕后。」太后说：「好，任凭您指派他吧。」于是为长安君准备了一百辆车子，送他到齐国做人质，齐国的军队才出动。\n子义听说这件事，说：「国君的儿子，是骨肉至亲，尚且不能倚仗没有功勋的尊贵、没有劳绩的俸禄，来守住金玉这样的重宝，何况做臣子的呢？」"],
    [215, "guwen-gwj-55", "public-domain", "秦围赵之邯郸魏安釐王使将军晋鄙救赵畏秦止于荡阴不进魏王使客将军辛垣衍间入邯郸因平原君谓赵王曰「秦所以急围赵者前与齐闵王争强为帝已而复归帝以齐故今齐闵王益弱方今唯秦雄天下此非必贪邯郸其意欲求为帝赵诚发使尊秦昭王为帝秦必喜罢兵去」平原君犹豫未有所决此时鲁仲连适游赵会秦围赵闻魏将欲令赵尊秦为帝乃见平原君曰「事将奈何矣」平原君曰「胜也何敢言事百万之众折于外今又内围邯郸而不能去魏王使客将军辛垣衍令赵帝秦今其人在是胜也何敢言事」鲁连曰「始吾以君为天下之贤公子也吾乃今然后知君非天下之贤公子也梁客辛垣衍安在吾请为君责而归之」平原君曰「胜请为绍介而见之于先生」平原君遂见辛垣衍曰「东国有鲁连先生其人在此胜请为绍介而见之于将军」辛垣衍曰「吾闻鲁连先生齐国之高士也衍人臣也使事有职吾不愿见鲁连先生也」平原君曰「胜已泄之矣」辛垣衍许诺鲁连见辛垣衍而无言辛垣衍曰「吾视居此围城之中者皆有求于平原君者也今吾视先生之玉貌非有求于平原君者曷为久居此围城之中而不去也」鲁连曰「世以鲍焦无从容而死者皆非也今众人不知则为一身彼秦者弃礼义而上首功之国也权使其士虏使其民彼则肆然而为帝过而遂正于天下则连有赴东海而死矣吾不忍为之民也所为见将军者欲以助赵也」辛垣衍曰「先生助之奈何」鲁连曰「吾将使梁及燕助之齐楚则固助之矣」辛垣衍曰「燕则吾请以从矣若乃梁则吾乃梁人也先生恶能使梁助之耶」鲁连曰「梁未睹秦称帝之害故也使梁睹秦称帝之害则必助赵矣」辛垣衍曰「秦称帝之害将奈何」鲁仲连曰「昔齐威王尝为仁义矣率天下诸侯而朝周周贫且微诸侯莫朝而齐独朝之居岁余周烈王崩诸侯皆吊齐后往周怒赴于齐曰『天崩地坼天子下席东藩之臣田婴齐后至则斮之』威王勃然怒曰『叱嗟而母婢也』卒为天下笑故生则朝周死则叱之诚不忍其求也彼天子固然其无足怪」辛垣衍曰「先生独未见夫仆乎十人而从一人者宁力不胜智不若耶畏之也」鲁仲连曰「然梁之比于秦若仆耶」辛垣衍曰「然」鲁仲连曰「然则吾将使秦王烹醢梁王」辛垣衍怏然不悦曰「嘻亦太甚矣先生之言也先生又恶能使秦王烹醢梁王」鲁仲连曰「固也吾将言之昔者九侯鄂侯文王纣之三公也九侯有子而好献之于纣纣以为恶醢九侯鄂侯争之强辩之疾故脯鄂侯文王闻之喟然而叹故拘之牖里之库百日欲令之死曷为与人俱称王卒就脯醢之地齐闵王将之鲁夷维子执策而从谓鲁人曰『子将何以待吾君』鲁人曰『吾将以十太牢待子之君』夷维子曰『子安取礼而来待吾君彼吾君者天子也天子巡狩诸侯辟舍纳于筦键摄衽抱几视膳于堂下天子已食退而听朝也』鲁人投其籥不果纳不得入于鲁将之薛假涂于邹当是时邹君死闵王欲入吊夷维子谓邹之孤曰『天子吊主人必将倍殡柩设北面于南方然后天子南面吊也』邹之群臣曰『必若此吾将伏剑而死』故不敢入于邹邹鲁之臣生则不得事养死则不得饭含然且欲行天子之礼于邹鲁之臣不果纳」「今秦万乘之国梁亦万乘之国交有称王之名睹其一战而胜欲从而帝之是使三晋之大臣不如邹鲁之仆妾也且秦无已而帝则且变易诸侯之大臣彼将夺其所谓不肖而予其所谓贤夺其所憎而与其所爱彼又将使其子女谗妾为诸侯妃姬处梁之宫梁王安得晏然而已乎而将军又何以得故宠乎」于是辛垣衍起再拜谢曰「始以先生为庸人吾乃今日而知先生为天下之士也吾请去不敢复言帝秦」秦将闻之为却军五十里适会公子无忌夺晋鄙军以救赵击秦秦军引而去于是平原君欲封鲁仲连鲁仲连辞让者三终不肯受平原君乃置酒酒酣起前以千金为鲁连寿鲁连笑曰「所贵于天下之士者为人排患释难解纷乱而无所取也即有所取者是商贾之事也而连不忍为也」遂辞平原君而去终身不复见", "秦军围攻赵国的邯郸。魏安釐王派将军晋鄙去救赵国。晋鄙畏惧秦国，停留在荡阴，不再前进。魏王派客居魏国的将军辛垣衍从小路进入邯郸，通过平原君对赵王说：「秦国之所以急攻赵国，是因为从前同齐闵王争强称帝，后来又把帝号归还，是因为齐国的缘故。如今齐闵王更加衰弱，当今只有秦国称雄天下，这次不一定是要贪图邯郸，它的用意是想求取帝号。赵国如果真派使者去尊秦昭王为帝，秦国一定高兴，撤兵离去。」平原君犹豫不决。\n这时鲁仲连恰好客游赵国，遇上秦军围赵。听说魏国将要让赵国尊秦为帝，就去见平原君说：「事情打算怎么办？」平原君说：「我赵胜怎么敢谈论国事！百万大军在外折损，如今又被围困邯郸而不能解围。魏王派客将军辛垣衍来让赵国尊秦为帝，如今那个人还在这里，我赵胜怎么敢谈论国事！」鲁仲连说：「起初我以为您是天下贤明的公子，我现在才知道您不是天下贤明的公子。魏国的客人辛垣衍在哪里？请让我替您责问他，让他回去。」平原君说：「请让我为您介绍，让他来见先生。」\n平原君于是去见辛垣衍说：「东边齐国有位鲁仲连先生，他正在这里，请让我介绍他来见将军。」辛垣衍说：「我听说鲁仲连先生是齐国的高士。我是臣子，出使有职守，我不愿见鲁仲连先生。」平原君说：「我已经透露了。」辛垣衍答应了。\n鲁仲连见辛垣衍却不说话。辛垣衍说：「我看住在这座被围城中的人，都是有求于平原君的。如今我看先生的仪表，不像有求于平原君的人，为什么长久留在这座围城中而不离开呢？」鲁仲连说：「世人认为鲍焦是气量狭小而死的，都不对。如今众人不了解他，以为他是为了自己。那秦国，是抛弃礼义、崇尚斩首之功的国家，用权术驱使士人，把百姓当作俘虏。它如果放肆地称帝，进而统治天下，那我鲁仲连只有跳进东海去死了，我不忍心做它的百姓！我之所以来见将军，是想帮助赵国。」\n辛垣衍说：「先生怎么帮助赵国？」鲁仲连说：「我将让魏国和燕国帮助赵国，齐国、楚国本来就帮助赵国了。」辛垣衍说：「燕国我且认为会听从。至于魏国，我就是魏国人，先生怎么能让魏国帮助赵国呢？」鲁仲连说：「魏国是没有看到秦称帝的害处罢了。如果让魏国看到秦称帝的害处，就一定会帮助赵国。」\n辛垣衍说：「秦称帝的害处会怎样？」鲁仲连说：「从前齐威王曾经行仁义，率领天下诸侯去朝拜周王。周室贫穷衰微，诸侯没有去朝拜的，只有齐国去朝拜。过了一年多，周烈王去世，诸侯都去吊唁，齐国去晚了。周室发怒，向齐国报丧说：『天崩地裂，天子离席。东方藩臣田婴齐来晚了，就该斩！』威王勃然大怒说：『呸！你母亲是婢女！』终于被天下人耻笑。所以周王活着时去朝拜，死后却咒骂，实在是受不了他的苛求。那天子的作为本来就是这样，不足为怪。」\n辛垣衍说：「先生难道没见过仆人吗？十个人跟从一个人，难道是力气不如、智慧不如吗？是怕他。」鲁仲连说：「对。魏国同秦国相比，就像仆人吗？」辛垣衍说：「是的。」鲁仲连说：「那么我将让秦王把魏王煮成肉酱。」辛垣衍很不高兴，说：「唉！先生的话太过分了！先生又怎么能让秦王把魏王煮成肉酱？」\n鲁仲连说：「当然，我会说明。从前九侯、鄂侯、文王是商纣的三公。九侯有个女儿很美，进献给纣，纣认为她丑恶，就把九侯剁成肉酱。鄂侯极力争辩，言辞激烈，所以把鄂侯做成肉干。文王听说，长声叹息，因此被拘禁在牖里的仓库一百天，想让他死。为什么同别人一样称王，却落得做成肉干肉酱的地步呢？齐闵王将到鲁国去，夷维子拿着马鞭跟随，对鲁国人说：『你们将用什么来接待我们的国君？』鲁国人说：『我们将用十份太牢来接待您的国君。』夷维子说：『你们哪里拿这样的礼节来接待我们国君？我们的国君是天子。天子巡狩，诸侯要腾出宫舍，交出钥匙，提起衣襟、抱着几案，在堂下侍候用膳，天子吃完，才退下去听政。』鲁国人把城门钥匙扔下，不肯接纳。闵王没能进入鲁国。将到薛地去，向邹国借路。这时邹国国君去世，闵王想进去吊唁。夷维子对邹国的遗孤说：『天子来吊唁，主人一定要把灵柩换个方向，在南面设北面的位置，然后天子朝南吊唁。』邹国的群臣说：『一定要这样，我们就要伏剑自尽。』所以闵王不敢进入邹国。邹、鲁的臣子，国君活着时不能奉养，死后不能含饭，然而还想要他们对邹、鲁的臣子行天子的礼，结果不被接纳。\n「如今秦国是万乘之国，魏国也是万乘之国，都有称王的名分。看到秦国打了一场胜仗，就想跟从着尊它为帝，这是使三晋的大臣不如邹、鲁的仆妾啊。而且秦国一旦无所顾忌地称帝，就会更换诸侯的大臣，它将夺去它认为不贤的给认为贤的，夺去它所憎恨的给所喜爱的。它还会让它的女儿和进谗言的妾做诸侯的妃姬，住在魏国的宫里，魏王怎么能安然无事呢？而将军又怎么能保住原有的宠信呢？」\n于是辛垣衍站起来，拜了两拜谢罪说：「起初我以为先生是庸人，我现在才知道先生是天下之士。请让我离开，不敢再谈尊秦为帝了。」\n秦将听说这件事，为此退军五十里。恰好遇上公子无忌夺取晋鄙的军队来救赵、攻击秦军，秦军撤退离去。\n于是平原君想封赏鲁仲连，鲁仲连再三推辞，终于不肯接受。平原君于是设酒宴，酒兴正浓时，起身向前，用千金为鲁仲连祝寿。鲁仲连笑着说：「天下之士所看重的，是替人排除祸患、释解危难、排解纠纷而不取报酬。如果有所取，那就是商人的事，我鲁仲连不忍心做。」于是辞别平原君离去，终身不再相见。"],
    [216, "guwen-gwj-56", "public-domain", "梁王魏婴觞诸侯于范台酒酣请鲁君举觞鲁君兴避席择言曰「昔者帝女令仪狄作酒而美进之禹禹饮而甘之遂疏仪狄绝旨酒曰『后世必有以酒亡其国者』齐桓公夜半不嗛易牙乃煎敖燔炙和调五味而进之桓公食之而饱至旦不觉曰『后世必有以味亡其国者』晋文公得南之威三日不听朝遂推南之威而远之曰『后世必有以色亡其国者』楚王登强台而望崩山左江而右湖以临彷徨其乐忘死遂盟强台而弗登曰『后世必有以高台陂池亡其国者』今主君之尊仪狄之酒也主君之味易牙之调也左白台而右闾须南威之美也前夹林而后兰台强台之乐也有一于此足以亡其国今主君兼此四者可无戒与」梁王称善相属", "梁惠王魏婴在范台宴请诸侯，酒兴正浓时，请鲁共公举杯。鲁共公起身，离开座位选择言辞说：「从前，尧的女儿让仪狄造酒，酒味很美，进献给禹，禹喝了觉得甘美，于是疏远仪狄，戒绝美酒，说：『后世一定有因酒而亡国的。』齐桓公半夜里觉得不饱，易牙就煎烤烹调，调和五味进献，桓公吃了很饱，到天亮都没有察觉，说：『后世一定有因美味而亡国的。』晋文公得到美女南之威，三天不上朝听政，于是推开南之威疏远她，说：『后世一定有因女色而亡国的。』楚王登上强台眺望崩山，左边是长江右边是洞庭湖，面临彷徨之水，快乐得忘了死，于是在强台立誓不再登临，说：『后世一定有因高台池塘而亡国的。』如今主君的酒，就是仪狄的酒；主君的美味，就是易牙的烹调；左边白台右边闾须，就是南威那样的美女；前面夹林后面兰台，就是强台那样的快乐。这四样里有一件，就足以亡国。如今主君兼有这四样，能不警戒吗！」\n梁惠王连声称好。"],
    [217, "guwen-gwj-172", "", "信陵君杀晋鄙救邯郸破秦人存赵国赵王自郊迎唐雎谓信陵君曰「臣闻之曰事有不可知者有不可不知者有不可忘者有不可不忘者」信陵君曰「何谓也」对曰「人之憎我也不可不知也吾憎人也不可得而知也人之有德于我也不可忘也吾有德于人也不可不忘也今君杀晋鄙救邯郸破秦人存赵国此大德也今赵王自郊迎卒然见赵王臣愿君之忘之也」信陵君曰「无忌谨受教」", "信陵君杀了晋鄙，救了邯郸，打败了秦军，保全了赵国，赵王亲自到郊外迎接。\n唐雎对信陵君说：「我听说过这样的话：事情有不可以知道的，有不可以不知道的；有不可以忘记的，有不可以不忘记的。」信陵君说：「这是什么意思呢？」唐雎答道：「别人憎恨我，不可以不知道；我憎恨别人，不可以让人知道。别人对我有恩德，不可以忘记；我对别人有恩德，不可以不忘记。如今您杀了晋鄙，救了邯郸，打败了秦军，保全了赵国，这是大恩德。如今赵王亲自到郊外迎接，突然见到赵王，我希望您忘掉这件事。」信陵君说：「无忌恭敬地接受您的教导。」"],
    [218, "guwen-gwj-57", "public-domain", "秦王使人谓安陵君曰「寡人欲以五百里之地易安陵安陵君其许寡人」安陵君曰「大王加惠以大易小甚善虽然受地于先王愿终守之弗敢易」秦王不说安陵君因使唐雎使于秦秦王谓唐雎曰「寡人以五百里之地易安陵安陵君不听寡人何也且秦灭韩亡魏而君以五十里之地存者以君为长者故不错意也今吾以十倍之地请广于君而君逆寡人者轻寡人与」唐雎对曰「否非若是也安陵君受地于先王而守之虽千里不敢易也岂直五百里哉」秦王怫然怒谓唐雎曰「公亦尝闻天子之怒乎」唐雎对曰「臣未尝闻也」秦王曰「天子之怒伏尸百万流血千里」唐雎曰「大王尝闻布衣之怒乎」秦王曰「布衣之怒亦免冠徒跣以头抢地耳」唐雎曰「此庸夫之怒也非士之怒也夫专诸之刺王僚也彗星袭月聂政之刺韩傀也白虹贯日要离之刺庆忌也仓鹰击于殿上此三子者皆布衣之士也怀怒未发休祲降于天与臣而将四矣若士必怒伏尸二人流血五步天下缟素今日是也」挺剑而起秦王色挠长跪而谢之曰「先生坐何至于此寡人谕矣夫韩魏灭亡而安陵以五十里之地存者徒以有先生也」", "秦王派人对安陵君说：「我想用五百里的土地交换安陵，安陵君该答应我吧！」安陵君说：「大王施予恩惠，用大的换小的，很好；虽然如此，我从先王那里继承了这块土地，愿意终身守住它，不敢交换！」秦王不高兴。安陵君于是派唐雎出使秦国。\n秦王对唐雎说：「我用五百里的土地交换安陵，安陵君不答应我，为什么？况且秦国灭掉韩国、魏国，而安陵君凭五十里的地方保存下来，是因为我把安陵君看作忠厚长者，所以不打他的主意。如今我用十倍的土地请安陵君扩充领土，他却违背我的意思，是轻视我吗？」唐雎答道：「不，不是这样。安陵君从先王那里继承土地而守住它，即使千里也不敢交换，岂止五百里呢？」\n秦王勃然大怒，对唐雎说：「你也曾听说过天子发怒吗？」唐雎答道：「我没有听说过。」秦王说：「天子发怒，尸体倒伏百万，流血千里。」唐雎说：「大王曾听说过平民发怒吗？」秦王说：「平民发怒，不过是摘掉帽子、光着脚，用头撞地罢了。」唐雎说：「这是庸人发怒，不是士人发怒。专诸刺杀王僚时，彗星冲犯月亮；聂政刺杀韩傀时，白虹贯穿太阳；要离刺杀庆忌时，苍鹰扑击殿上。这三个人都是平民中的士人，怀怒未发，征兆已从天而降，加上我将成为第四个了。如果士人一定要发怒，倒下两具尸体、血流五步，天下人穿白戴孝，今天就是这样。」他拔出剑站了起来。\n秦王脸色沮丧，直身跪着道歉说：「先生请坐！何至于这样！我明白了：韩国、魏国灭亡，而安陵凭五十里的地方保存下来，只是因为有先生啊。」"],
    [219, "guwen-gwj-58", "public-domain", "昌国君乐毅为燕昭王合五国之兵而攻齐下七十余城尽郡县之以属燕三城未下而燕昭王死惠王即位用齐人反间疑乐毅而使骑劫代之将乐毅奔赵赵封以为望诸君齐田单诈骑劫卒败燕军复收七十余城以复齐燕王悔惧赵用乐毅乘燕之弊以伐燕燕王乃使人让乐毅且谢之曰「先王举国而委将军将军为燕破齐报先王之仇天下莫不振动寡人岂敢一日而忘将军之功哉会先王弃群臣寡人新即位左右误寡人寡人之使骑劫代将军为将军久暴露于外故召将军且休计事将军过听以与寡人有隙遂捐燕而归赵将军自为计则可矣而亦何以报先王之所以遇将军之意乎」望诸君乃使人献书报燕王曰「臣不佞不能奉承先王之教以顺左右之心恐抵斧质之罪以伤先王之明而又害于足下之义故遁逃奔赵自负以不肖之罪故不敢为辞说今王使使者数之罪臣恐侍御者之不察先王之所以畜幸臣之理而又不白于臣之所以事先王之心故敢以书对」「臣闻贤圣之君不以禄私其亲功多者授之不以官随其爱能当者处之故察能而授官者成功之君也论行而结交者立名之士也臣以所学者观之先王之举措有高世之心故假节于魏王而以身得察于燕先王过举擢之乎宾客之中而立之乎群臣之上不谋于父兄而使臣为亚卿臣自以为奉令承教可以幸无罪矣故受命而不辞」「先王命之曰『我有积怨深怒于齐不量轻弱而欲以齐为事』臣对曰『夫齐霸国之余教而骤胜之遗事也闲于兵甲习于战攻王若欲攻之则必举天下而图之举天下而图之莫径于结赵矣且又淮北宋地楚魏之所同愿也赵若许约楚魏尽力四国攻之齐可大破也』先王曰『善』臣乃口受令具符节南使臣于赵顾返命起兵随而攻齐以天之道先王之灵河北之地随先王举而有之于济上济上之军奉令击齐大胜之轻卒锐兵长驱至国齐王逃遁走莒仅以身免珠玉财宝车甲珍器尽收入燕大吕陈于元英故鼎反乎历室齐器设于宁台蓟丘之植植于汶篁自五伯以来功未有及先王者也先王以为惬于志故裂地而封之使得比小国诸侯臣窃不自知自以为奉命承教可幸无罪是以受命不辞」「臣闻贤圣之君功立而不废故著于春秋蚤知之士名成而不毁故称于后世若先王之报怨雪耻夷万乘之强国收八百岁之蓄积及至弃群臣之日余教未衰执政任事之臣修法令慎庶孽施及乎萌隶皆可以教后世」「臣闻之善作者不必善成善始者不必善终昔伍子胥说听乎阖闾故吴王远迹至于郢夫差弗是也赐之鸱夷而浮之江故吴王夫差不悟先论之可以立功故沉子胥而弗悔子胥不蚤见主之不同量故入江而不改夫免身全功以明先王之迹者臣之上计也离毁辱之非堕先王之名者臣之所大恐也临不测之罪以幸为利者义之所不敢出也」「臣闻古之君子交绝不出恶声忠臣之去也不洁其名臣虽不佞数奉教于君子矣恐侍御者之亲左右之说而不察疏远之行也故敢以书报唯君之留意焉」", "昌国君乐毅为燕昭王联合五国的军队攻打齐国，攻下七十多座城，都设为郡县归属燕国。还有三座城没有攻下，而燕昭王去世了。燕惠王即位，齐国人用反间计，使惠王怀疑乐毅，派骑劫代替他统兵。乐毅逃奔赵国，赵王封他为望诸君。齐国的田单诈骗骑劫，终于打败燕军，收复七十多座城，恢复了齐国。\n燕惠王后悔，怕赵国任用乐毅乘燕国疲惫来攻打燕国。惠王于是派人责备乐毅，并向他道歉说：「先王把整个国家委托给将军，将军为燕国打败齐国，报了先王的仇，天下没有不震动的，我怎敢一天忘记将军的功劳呢！正碰上先王抛弃群臣去世，我刚刚即位，左右的人误了我。我派骑劫代替将军，是因为将军长期在外风吹日晒，所以召将军回来暂且休息并商议事情。将军误听传言，因此和我有了隔阂，就抛弃燕国投奔赵国。将军为自己打算是可以的，可是又拿什么报答先王对待将军的心意呢？」\n望诸君于是派人献上书信回复燕王说：\n「我不才，不能奉行先王的教导，来顺从左右的心意，怕触犯斧质之罪，以致损害先王的明察，又伤害您的道义，所以逃避奔往赵国。我身负不贤的罪过，所以不敢为自己辩说。如今大王派使者来数落我的罪过，我怕侍御的人不明察先王之所以养育宠信我的道理，又不明白我之所以事奉先王的心意，所以敢用书信回答。\n「我听说贤明的君主，不拿俸禄偏私自己的亲信，功劳多的就授给他；不拿官职随顺自己的喜爱，能胜任的就安排他。所以考察才能而授予官职的，是成就功业的君主；衡量德行而结交的，是树立名声的士人。我凭所学来看，先王的举措，有高出世人的心意，所以我借魏王的名义出使，得以亲自受到燕国的考察。先王过分抬举我，把我从宾客中提拔起来，安置在群臣之上，不跟父兄商议，就让我做亚卿。我自以为奉行命令、承受教导，可以侥幸没有罪过，所以接受任命而不推辞。\n「先王命令我说：『我对齐国有积久的怨恨深怒，不自量力地薄弱，想要把齐国作为讨伐的对象。』我回答说：『齐国，有霸国遗留的教化，又有屡次战胜的余威，熟悉兵甲，惯于战攻。大王如果想要攻打它，就一定要发动天下各国来图谋它。发动天下各国来图谋它，没有比联合赵国更直接的了。况且淮北、宋地，是楚国、魏国同样想得到的。赵国如果答应结盟，楚国、魏国尽力，四国一起攻打，齐国就可以大破。』先王说：『好。』我于是当面接受命令，备好符节，向南出使赵国。回来复命后，随即起兵攻打齐国。凭上天的眷顾、先王的威灵，黄河以北的土地，随先王一举而占领到济水边上。济水边上的军队，奉令追击齐军，大胜。轻装的精锐士卒，长驱直入齐国国都。齐王逃走跑到莒地，仅以身免。珠玉财宝、车甲珍器，全部收归燕国。大吕钟陈列在元英宫，旧鼎归还到历室，齐国乐器设置在宁台。蓟丘所种的作物，种在汶水的竹田里。自五霸以来，功业没有能赶得上先王的。先王认为满足了心意，所以分地封赏我，使我能比于小国诸侯。我私下不自量，自以为奉行命令、承受教导，可以侥幸没有罪过，所以接受任命而不推辞。\n「我听说贤明的君主，功业建立而不废弃，所以记载在《春秋》里；有先见之明的士人，名声成就而不毁坏，所以称颂于后世。像先王那样报仇雪耻，平定万乘的强国，收取八百年的积蓄，直到抛弃群臣去世的时候，遗留的教化没有衰败，执政任事的臣子，修明法令，谨慎地对待庶子，恩惠遍及百姓，都可以教导后世。\n「我听说，善于开创的不一定善于完成，有好的开端的不一定有好的结局。从前伍子胥的话被阖闾采纳，所以吴王能远征到郢都；夫差不赞成他的主张，赐给他鸱夷皮袋，把他沉入江中。所以吴王夫差不明白先前的议论可以建立功业，所以把子胥沉江而不后悔；子胥不能及早看出君主的气量不同，所以被投入江中也不改变。保全自身、保全功业，来彰明先王的业绩，是我的上策。遭受毁谤侮辱的非难，败坏先王的名声，是我最害怕的。面对不可预测的罪过，侥幸图利，是道义上所不敢做的。\n「我听说古代的君子，绝交也不说难听的话；忠臣离去，也不为自己洗刷名声。我虽然不才，也曾多次受到君子的教导。怕侍御的人亲近左右的说法，而不明察被疏远者的行为。所以敢用书信回复，希望君王留意。」"],
    [220, "guwen-gwj-59", "public-domain", "臣闻吏议逐客窃以为过矣昔穆公求士西取由余于戎东得百里奚于宛迎蹇叔于宋求丕豹公孙支于晋此五子者不产于秦而穆公用之并国二十遂霸西戎孝公用商鞅之法移风易俗民以殷盛国以富强百姓乐用诸侯亲服获楚魏之师举地千里至今治强惠王用张仪之计拔三川之地西并巴蜀北收上郡南取汉中包九夷制鄢郢东据成皋之险割膏腴之壤遂散六国之从使之西面事秦功施到今昭王得范雎废穰侯逐华阳强公室杜私门蚕食诸侯使秦成帝业此四君者皆以客之功由此观之客何负于秦哉向使四君却客而不内疏士而不用是使国无富利之实而秦无强大之名也今陛下致昆山之玉有随和之宝垂明月之珠服太阿之剑乘纤离之马建翠凤之旗树灵鼍之鼓此数宝者秦不生一焉而陛下说之何也必秦国之所生然后可则是夜光之璧不饰朝廷犀象之器不为玩好郑卫之女不充后宫而骏良駃騠不实外厩江南金锡不为用西蜀丹青不为采所以饰后宫充下陈娱心意说耳目者必出于秦然后可则是宛珠之簪傅玑之珥阿缟之衣锦绣之饰不进于前而随俗雅化佳冶窈窕赵女不立于侧也夫击瓮叩缶弹筝搏髀而歌呼呜呜快耳者真秦之声也郑卫桑间昭虞武象者异国之乐也今弃击瓮叩缶而就郑卫退弹筝而取昭虞若是者何也快意当前适观而已矣今取人则不然不问可否不论曲直非秦者去为客者逐然则是所重者在乎色乐珠玉而所轻者在乎人民也此非所以跨海内制诸侯之术也臣闻地广者粟多国大者人众兵强则士勇是以太山不让土壤故能成其大河海不择细流故能就其深王者不却众庶故能明其德是以地无四方民无异国四时充美鬼神降福此五帝三王之所以无敌也今乃弃黔首以资敌国却宾客以业诸侯使天下之士退而不敢西向裹足不入秦此所谓「藉寇兵而赍盗粮」者也夫物不产于秦可宝者多士不产于秦而愿忠者众今逐客以资敌国损民以益仇内自虚而外树怨于诸侯求国无危不可得也", "臣听说官吏们商议驱逐客卿，我私下认为这是错的。从前秦穆公寻求贤士，西边从戎地取得由余，东边从宛地得到百里奚，从宋国迎来蹇叔，从晋国招来丕豹、公孙支。这五个人都不生在秦国，而穆公任用他们，并吞了二十个国家，于是称霸西戎。孝公采用商鞅的变法，移风易俗，人民因此殷实，国家因此富强，百姓乐于效力，诸侯亲近归服，俘获楚、魏的军队，攻取千里土地，至今安定强盛。惠王采用张仪的计策，攻取三川之地，西面并吞巴、蜀，北面收取上郡，南面取得汉中，囊括九夷，控制鄢、郢，东面占据成皋的险要，割取肥沃的土地，于是拆散六国的合纵，让他们向西侍奉秦国，功业延续到今天。昭王得到范雎，废掉穰侯，驱逐华阳君，加强王室的权力，堵塞权臣的私门，像蚕吃桑叶一样逐步侵占诸侯，使秦国成就帝业。这四位君主，都靠客卿的功劳。由此看来，客卿有什么对不起秦国的呢！假如这四位君主拒绝客卿而不接纳，疏远贤士而不任用，这就会使国家没有富强的实绩，秦国也没有强大的名声了。\n如今陛下得到昆山的美玉，拥有随侯珠、和氏璧这样的珍宝，悬挂明月之珠，佩带太阿之剑，乘坐纤离之马，竖起翠凤之旗，架起灵鼍之鼓。这几种宝物，秦国一样也不出产，而陛下却喜欢它们，为什么？如果一定要秦国出产的才可以用，那么夜光之璧就不该装饰朝廷，犀角象牙的器物就不该赏玩，郑、卫的美女就不该充入后宫，骏马良驹就不该养在外厩，江南的金锡就不该使用，西蜀的丹青就不该采来作颜料。如果用来装饰后宫、充当下陈、娱乐心意、悦人耳目的，一定要出产于秦国才可以，那么宛珠的簪子、镶珠的耳饰、东阿的白绢衣服、锦绣的装饰就不会进献到面前，而追随时尚、美丽窈窕的赵国女子也不会侍立在身边了。敲瓮击缶、弹筝拍腿，呜呜地唱歌以快人耳目的，才是真正的秦国音乐；郑、卫、桑间之音和《昭》《虞》《武》《象》这些乐曲，都是别国的音乐。如今抛弃敲瓮击缶而听郑、卫之音，放下弹筝而取《昭》《虞》，这是为什么？不过是为了眼前痛快、看着舒服罢了。如今用人却不是这样，不问可否，不论曲直，不是秦国人就赶走，是客卿就驱逐。如此说来，所看重的只是色、乐、珠、玉，所轻视的却是人民。这不是用来跨海内、制诸侯的办法啊。\n我听说土地广的粮食多，国家大的人口众，兵器锋利士兵就勇敢。所以泰山不拒绝土壤，才能成就它的高大；河海不挑剔细流，才能成就它的深广；君王不排斥百姓，才能彰明他的德行。因此地不分四方，民不分异国，四季丰美，鬼神降福，这正是五帝三王无敌于天下的原因。如今却抛弃百姓去帮助敌国，驱逐宾客去让他国成就功业，使天下的贤士退缩而不敢向西来，裹足不入秦国，这就是所谓「借给贼寇兵器、送给盗贼粮食」的做法。\n物品不产于秦国而可宝贵的很多；贤士不生于秦国而愿意效忠的很多。如今驱逐客卿去帮助敌国，损害百姓去增益仇人，对内使自己空虚，对外与诸侯结怨，要使国家没有危险，是办不到的。"],
    [221, "guwen-gwj-60", "public-domain", "屈原既放三年不得复见竭知尽忠而蔽障于谗心烦虑乱不知所从乃往见太卜郑詹尹曰「余有所疑愿因先生决之」詹尹乃端策拂龟曰「君将何以教之」屈原曰「吾宁悃悃款款朴以忠乎将送往劳来斯无穷乎宁诛锄草茅以力耕乎将游大人以成名乎宁正言不讳以危身乎将从俗富贵以媮生乎宁超然高举以保真乎将哫訾栗斯喔咿儒儿以事妇人乎宁廉洁正直以自清乎将突梯滑稽如脂如韦以洁楹乎宁昂昂若千里之驹乎将氾氾若水中之凫与波上下偷以全吾躯乎宁与骐骥亢轭乎将随驽马之迹乎宁与黄鹄比翼乎将与鸡鹜争食乎此孰吉孰凶何去何从世溷浊而不清蝉翼为重千钧为轻黄钟毁弃瓦釜雷鸣谗人高张贤士无名吁嗟默默兮谁知吾之廉贞」詹尹乃释策而谢曰「夫尺有所短寸有所长物有所不足智有所不明数有所不逮神有所不通用君之心行君之意龟策诚不能知此事」", "屈原已经被放逐，三年不能再见到楚王。他竭尽智慧、尽忠行事，却被谗言所阻隔。心中烦乱，不知该怎么办。于是去见太卜郑詹尹说：「我有所疑惑，希望靠先生来决断。」郑詹尹于是摆正蓍草、拂拭龟甲，说：「您将用什么来指教我呢？」\n屈原说：「我是宁愿诚恳朴实、忠诚老实呢？还是去迎来送往、没完没了呢？宁愿锄除杂草、努力耕作呢？还是去游说权贵、成就名声呢？宁愿直言不讳、危害自身呢？还是随从流俗、富贵偷生呢？宁愿超然高举、保全真性呢？还是阿谀奉承、强颜欢笑去事奉妇人呢？宁愿廉洁正直、保持清白呢？还是圆滑应酬、像油脂熟皮一样去打磨光洁呢？宁愿昂昂然像千里马呢？还是浮浮然像水中的野鸭，随波上下、苟且保全我的身躯呢？宁愿同骐骥并驾呢？还是跟随劣马的足迹呢？宁愿同黄鹄比翼呢？还是同鸡鸭争食呢？这些哪个吉利哪个凶险？该舍弃什么、跟从什么？世道混浊不清：蝉翼被看作重的，千钧被看作轻的；黄钟被毁弃，瓦釜却雷鸣；谗人趾高气扬，贤士默默无闻。唉，沉默啊，谁能知道我的廉洁忠贞？」\n郑詹尹于是放下蓍草谢罪说：「尺有所短，寸有所长；事物有所不足，智慧有所不明；术数有所不及，神灵有所不通。用您的心，行您的意。龟甲蓍草实在不能知道这些事。」"],
    [223, "guwen-gwj-9", "public-domain", "四年春齐侯以诸侯之师侵蔡蔡溃遂伐楚楚子使与师言曰「君处北海寡人处南海唯是风马牛不相及也不虞君之涉吾地也何故」管仲对曰「昔召康公命我先君太公曰『五侯九伯女实征之以夹辅周室』赐我先君履东至于海西至于河南至于穆陵北至于无棣尔贡包茅不入王祭不共无以缩酒寡人是征昭王南征而不复寡人是问」对曰「贡之不入寡君之罪也敢不共给昭王之不复君其问诸水滨」师进次于陉夏楚子使屈完如师师退次于召陵齐侯陈诸侯之师与屈完乘而观之齐侯曰「岂不穀是为先君之好是继与不穀同好何如」对曰「君惠徼福于敝邑之社稷辱收寡君寡君之愿也」齐侯曰「以此众战谁能御之以此攻城何城不克」对曰「君若以德绥诸侯谁敢不服君若以力楚国方城以为城汉水以为池虽众无所用之」屈完及诸侯盟", "鲁僖公四年春天，齐桓公率领诸侯的军队侵犯蔡国。蔡国溃败，于是攻打楚国。\n楚成王派人到齐军中说：「您住在北方，我住在南方，即使牛马发情狂奔也不会彼此到达。没想到您竟踏入我的土地，是什么缘故？」管仲回答说：「从前召康公命令我们的先君太公说：『五等诸侯、九州之长，你都可以征伐他们，来辅佐周王室。』赐给我们先君可以征伐的范围：东到大海，西到黄河，南到穆陵，北到无棣。你们应当进贡的包茅不送来了，周王祭祀时供应不上，没有东西用来滤酒，我为此来征讨。昭王南征没有回去，我为此来问罪。」楚国使者答道：「贡品没有送来，是我们国君的罪过，岂敢不供给。至于昭王没有回去，您还是到水边去问吧。」\n齐军前进，驻扎在陉地。\n夏天，楚成王派屈完到齐军中去。齐军后撤，驻扎在召陵。齐桓公把诸侯的军队摆开，与屈完同乘一辆车观看。齐桓公说：「难道是为了我吗？是为了继承先君的友好关系。与我建立友好，怎么样？」屈完答道：「承您赐福于敝国的社稷，屈尊接纳我们的国君，这正是我们国君的愿望。」齐桓公说：「用这样多的军队作战，谁能抵挡？用这样多的军队攻城，哪座城攻不下？」屈完答道：「您若用德行来安抚诸侯，谁敢不服？您若用武力，楚国以方城山为城墙，以汉水为护城河，军队虽多，也没有用处。」\n屈完与诸侯订立了盟约。"],
    [224, "guwen-gwj-156", "public-domain", "齐宣王问曰「齐桓晋文之事可得闻乎」孟子对曰「仲尼之徒无道桓文之事者是以后世无传焉臣未之闻也无以则王乎」曰「德何如则可以王矣」曰「保民而王莫之能御也」曰「若寡人者可以保民乎哉」曰「可」曰「何由知吾可也」曰「臣闻之胡龁曰王坐于堂上有牵牛而过堂下者王见之曰『牛何之』对曰『将以衅钟』王曰『舍之吾不忍其觳觫若无罪而就死地』对曰『然则废衅钟与』曰『何可废也以羊易之』不识有诸」曰「有之」曰「是心足以王矣百姓皆以王为爱也臣固知王之不忍也」王曰「然诚有百姓者齐国虽褊小吾何爱一牛即不忍其觳觫若无罪而就死地故以羊易之也」曰「王无异于百姓之以王为爱也以小易大彼恶知之王若隐其无罪而就死地则牛羊何择焉」王笑曰「是诚何心哉我非爱其财而易之以羊也宜乎百姓之谓我爱也」曰「无伤也是乃仁术也见牛未见羊也君子之于禽兽也见其生不忍见其死闻其声不忍食其肉是以君子远庖厨也」王说曰「诗云『他人有心予忖度之』夫子之谓也夫我乃行之反而求之不得吾心夫子言之于我心有戚戚焉此心之所以合于王者何也」曰「有复于王者曰『吾力足以举百钧而不足以举一羽明足以察秋毫之末而不见舆薪』则王许之乎」曰「否」「今恩足以及禽兽而功不至于百姓者独何与然则一羽之不举为不用力焉舆薪之不见为不用明焉百姓之不见保为不用恩焉故王之不王不为也非不能也」曰「不为者与不能者之形何以异」曰「挟太山以超北海语人曰『我不能』是诚不能也为长者折枝语人曰『我不能』是不为也非不能也故王之不王非挟太山以超北海之类也王之不王是折枝之类也老吾老以及人之老幼吾幼以及人之幼天下可运于掌诗云『刑于寡妻至于兄弟以御于家邦』言举斯心加诸彼而已故推恩足以保四海不推恩无以保妻子古之人所以大过人者无他焉善推其所为而已矣今恩足以及禽兽而功不至于百姓者独何与权然后知轻重度然后知长短物皆然心为甚王请度之」「抑王兴甲兵危士臣构怨于诸侯然后快于心与」王曰「否吾何快于是将以求吾所大欲也」曰「王之所大欲可得闻与」王笑而不言曰「为肥甘不足于口与轻暖不足于体与抑为采色不足视于目与声音不足听于耳与便嬖不足使令于前与王之诸臣皆足以供之而王岂为是哉」曰「否吾不为是也」曰「然则王之所大欲可知已欲辟土地朝秦楚莅中国而抚四夷也以若所为求若所欲犹缘木而求鱼也」王曰「若是其甚与」曰「殆有甚焉缘木求鱼虽不得鱼无后灾以若所为求若所欲尽心力而为之后必有灾」曰「可得闻与」曰「邹人与楚人战则王以为孰胜」曰「楚人胜」曰「然则小固不可以敌大寡固不可以敌众弱固不可以敌强海内之地方千里者九齐集有其一以一服八何以异于邹敌楚哉盖亦反其本矣今王发政施仁使天下仕者皆欲立于王之朝耕者皆欲耕于王之野商贾皆欲藏于王之市行旅皆欲出于王之涂天下之欲疾其君者皆欲赴愬于王其若是孰能御之」王曰「吾惛不能进于是矣愿夫子辅吾志明以教我我虽不敏请尝试之」曰「无恒产而有恒心者惟士为能若民则无恒产因无恒心苟无恒心放辟邪侈无不为已及陷于罪然后从而刑之是罔民也焉有仁人在位罔民而可为也是故明君制民之产必使仰足以事父母俯足以畜妻子乐岁终身饱凶年免于死亡然后驱而之善故民之从之也轻今也制民之产仰不足以事父母俯不足以畜妻子乐岁终身苦凶年不免于死亡此惟救死而恐不赡奚暇治礼义哉王欲行之则盍反其本矣五亩之宅树之以桑五十者可以衣帛矣鸡豚狗彘之畜无失其时七十者可以食肉矣百亩之田勿夺其时八口之家可以无饥矣谨庠序之教申之以孝悌之义颁白者不负戴于道路矣老者衣帛食肉黎民不饥不寒然而不王者未之有也」", "齐宣王问：「齐桓公、晋文公称霸的事，可以讲给我听听吗？」孟子回答：「孔子的门徒没有谈论齐桓公、晋文公的事的，所以后世没有流传，我没有听说过。如果一定要说，那就说说称王天下吧？」宣王说：「要有怎样的德行才可以称王天下呢？」孟子说：「安抚百姓而称王天下，没有人能阻挡。」宣王说：「像我这样的人，能够安抚百姓吗？」孟子说：「能。」宣王说：「凭什么知道我能呢？」孟子说：「我听胡龁说：大王坐在堂上，有人牵着牛从堂下走过，大王看见了，问：『牛牵到哪里去？』那人答：『要用它祭钟。』大王说：『放了吧！我不忍心看它发抖的样子，像这样没有罪过却要被送到死地。』那人说：『那么就废掉祭钟的仪式吗？』大王说：『怎么可以废掉呢？用羊换它！』不知有这回事吗？」宣王说：「有的。」孟子说：「这样的心肠就足以称王天下了。百姓都以为大王是吝啬，我本来就知道大王是不忍心。」\n宣王说：「是的，确实有这样的百姓。齐国虽然狭小，我怎么会吝惜一头牛？只是不忍心它发抖，像没有罪过而被送到死地，所以用羊换它。」孟子说：「大王不要怪百姓以为您吝啬。用小换大，他们怎么知道其中的缘故？大王如果哀怜它没有罪过而走向死地，那么牛和羊又有什么分别呢？」宣王笑着说：「这究竟是什么心思呢？我并不是吝惜财物才用羊换的，百姓说我吝啬也是应该的。」孟子说：「没有关系，这就是行仁的方法，因为您看见了牛而没有看见羊。君子对于禽兽，看见它活着，就不忍心看它死去；听见它的叫声，就不忍心吃它的肉。所以君子要远离厨房。」\n宣王高兴地说：「《诗》里说：『别人有什么心思，我能揣度到。』说的就是夫子您啊。我做了这件事，回过头来推求，却说不清自己的心思。夫子您说出来，让我心里很有感触。这种心思之所以合于王道，是为什么呢？」孟子说：「如果有人向大王报告：『我的力气足以举起三千斤，却举不起一根羽毛；眼力足以看清秋天鸟兽新毛的末梢，却看不见一车柴草。』那么大王会相信吗？」宣王说：「不会。」孟子说：「如今您的恩德足以施及禽兽，而功德却到不了百姓，偏偏是为什么呢？这样看来，一根羽毛举不起，是因为不肯用力；一车柴草看不见，是因为不肯用眼；百姓得不到安抚，是因为不肯施恩。所以大王不能称王天下，是不去做，不是做不到。」\n宣王说：「不去做和做不到的表现，有什么不同？」孟子说：「挟着泰山跳过北海，对别人说『我做不到』，这是真的做不到。为老人折一根树枝，对别人说『我做不到』，这是不去做，不是做不到。所以大王不能称王天下，不属于挟泰山跳北海这一类；大王不能称王天下，是属于折树枝这一类。敬爱自家的老人，从而推及别人的老人；爱护自家的孩子，从而推及别人的孩子，天下就可以在手掌上运转了。《诗》里说：『先给妻子做榜样，再推及兄弟，进而治理家族和国家。』说的就是把这样的心推及到别处罢了。所以推广恩德足以安抚四海，不推广恩德连妻子儿女都保不住。古代的人之所以大大超过别人，没有别的原因，只是善于推行自己的所作所为罢了。如今您的恩德足以施及禽兽，而功德却到不了百姓，偏偏是为什么呢？称一称，才知道轻重；量一量，才知道长短。万物都是这样，人心更是如此。请大王考虑一下！」\n「难道大王要发动战争，使将士陷入危险，同诸侯结下怨仇，然后心里才痛快吗？」宣王说：「不，我怎么会以此为快呢？我是想借此求得我最想得到的东西。」孟子说：「大王最想得到的东西，可以说给我听听吗？」宣王笑而不答。孟子说：「是为了肥美的食物不够吃吗？轻暖的衣服不够穿吗？还是为了艳丽的色彩不够看吗？美妙的音乐不够听吗？宠幸的近臣不够使唤吗？大王的群臣都足以供给这些，大王难道是为了这些吗？」宣王说：「不，我不是为了这些。」孟子说：「那么大王最想得到的东西就可以知道了：是想开辟疆土，使秦、楚来朝，君临中原而安抚四方各族。以您这样的作为，去求您这样的欲望，就像爬上树去捉鱼一样。」\n宣王说：「有这样严重吗？」孟子说：「恐怕比这还严重。爬上树捉鱼，虽然捉不到鱼，却没有后患；以您这样的作为，去求您这样的欲望，尽心尽力地去做，以后必定有灾祸。」宣王说：「可以说给我听听吗？」孟子说：「邹国人和楚国人交战，大王认为谁会胜？」宣王说：「楚国人胜。」孟子说：「这样看来，小国本来不可以与大国为敌，人少的本来不可以与人多的为敌，弱小的本来不可以与强大的为敌。天下的土地，方圆千里的有九块，齐国总共只占了其中一块；以一块去征服八块，和邹国与楚国为敌有什么不同呢？还是回到根本上来吧。如今大王发布政令、施行仁政，使天下的士人都想在您的朝廷上做官，耕田的人都想在您的田野里耕种，商人都想把货物存放在您的集市上，旅客都想取道您的道路，天下痛恨自己国君的人，都想跑来向您申诉。果真这样，谁能阻挡呢？」\n宣王说：「我昏昧，不能达到这样的地步。希望夫子辅助我的心志，明白地教导我。我虽然不聪敏，也请让我试一试。」孟子说：「没有固定产业而有恒心的人，只有士人才能做到。至于百姓，没有固定产业，就没有恒心。如果没有恒心，就会放荡邪僻、胡作非为，什么都干得出来。等到陷入罪网，然后跟着加以刑罚，这是陷害百姓。哪有仁人处在君位，却可以陷害百姓的呢？所以贤明的君主规定百姓的产业，一定使他们上足以侍奉父母，下足以养活妻儿，丰年终身吃饱，荒年免于死亡；然后引导他们向善，百姓也就容易听从了。\n如今规定百姓的产业，上不足以侍奉父母，下不足以养活妻儿，丰年终身困苦，荒年免不了死亡。这样连救死都怕来不及，哪里还有闲工夫讲求礼义呢？大王想要施行，何不回到根本上来呢。五亩的宅地，种上桑树，五十岁的人就可以穿丝绸了；鸡猪狗等家畜，不错过繁殖的时节，七十岁的人就可以吃肉了；百亩的田地，不要耽误农时，八口之家就可以不挨饿了；认真办好学校的教育，反复用孝顺父母、敬爱兄长的道理教导他们，头发花白的老人就不会在路上背着顶着东西了。老人穿丝绸、吃肉，百姓不饥不寒，这样还不能称王天下的，是没有的事。」"],
    [225, "guwen-gwj-92", "public-domain", "伪临朝武氏者性非和顺地实寒微昔充太宗下陈曾以更衣入侍洎乎晚节秽乱春宫潜隐先帝之私阴图后房之嬖入门见嫉蛾眉不肯让人掩袖工谗狐媚偏能惑主践元后于翚翟陷吾君于聚麀加以虺蜴为心豺狼成性近狎邪僻残害忠良杀姊屠兄弑君鸩母神人之所共疾天地之所不容犹复包藏祸心窥窃神器君之爱子幽之于别宫贼之宗盟委之以重任呜呼霍子孟之不作朱虚侯之已亡燕啄皇孙知汉祚之将尽龙漦帝后识夏庭之遽衰敬业皇唐旧臣公侯冢子奉先君之成业荷本朝之厚恩宋微子之兴悲良有以也袁君山之流涕岂徒然哉是用气愤风云志安社稷因天下之失望顺宇内之推心爰举义旗以清妖孽南连百越北尽三河铁骑成群玉轴相接海陵红粟仓储之积靡穷江浦黄旗匡复之功何远班声动而北风起剑气冲而南斗平喑呜则山岳崩颓叱咤则风云变色以此制敌何敌不摧以此图功何功不克公等或居汉地或叶周亲或膺重寄于话言或受顾命于宣室言犹在耳忠岂忘心一抔之土未干六尺之孤何托倘能转祸为福送往事居共立勤王之勋无废旧君之命凡诸爵赏同指山河若其眷恋穷城徘徊歧路坐昧先几之兆必贻后至之诛请看今日之域中竟是谁家之天下", "伪临朝的武则天，性情不和顺，出身实在寒微。从前充作太宗的妃嫔，曾因更衣而入侍。到了后来，秽乱春宫。隐藏先帝的私情，暗中图谋后宫的宠幸。一入宫门就嫉妒，蛾眉不肯让人；掩袖善于进谗，狐媚偏偏能迷惑君主。登上元后的位置穿上翚翟之服，使我们的君主陷入聚麀之耻。加上虺蜴一样的心肠，豺狼一样的本性，亲近邪僻，残害忠良，杀姊屠兄，弑君鸩母。这是神人所共同憎恨，天地所不能容忍的。她还包藏祸心，窥窃帝位。君主的爱子，被幽禁在别宫；贼人的宗族同盟，委以重任。唉！霍光不再出现，朱虚侯已经亡故。燕啄皇孙，知道汉朝的国运将要终尽；龙涎帝后，看出夏朝的朝廷突然衰败。\n我徐敬业是皇唐旧臣，公侯的长子。遵奉先君的成业，承受本朝的厚恩。宋微子的兴悲，确实有缘故；袁君山的流泪，难道是徒然的吗！因此义气愤激风云，立志安定社稷。因天下人的失望，顺宇内的推戴之心，于是举起义旗，来清除妖孽。南连百越，北尽三河，铁骑成群，玉轴相接。海陵的红粟，仓储的积蓄无穷；江浦的黄旗，匡复的功业不远。战鼓声动而北风起，剑气冲霄而南斗平。怒吼则山岳崩颓，叱咤则风云变色。用这个来制服敌人，什么敌人不能摧毁；用这个来图谋功业，什么功业不能成功！\n诸位或者身处汉地，或者是周室的至亲，或者在外交言辞中承受重任，或者在宣室接受遗命。话还在耳边，忠心难道忘了吗？一抔之土还没有干，六尺的孤儿托付给谁？倘若能转祸为福，送别死者、事奉生者，共同建立勤王的功勋，不废弃旧君的遗命，那么所有爵赏，一同指山河为誓。如果眷恋穷困的城池，徘徊于歧路，坐失先机的征兆，必定留下后至的诛罚。请看今日的国中，究竟是谁家的天下！"],
    [227, "guwen-gwj-149", "public-domain", "经常道也其在于天谓之命其赋于人谓之性其主于身谓之心心也性也命也一也通人物达四海塞天地亘古今无有乎弗具无有乎弗同无有乎或变者也是常道也其应乎感也则为恻隐为羞恶为辞让为是非其见于事也则为父子之亲为君臣之义为夫妇之别为长幼之序为朋友之信是恻隐也羞恶也辞让也是非也是亲也义也序也别也信也一也皆所谓心也性也命也通人物达四海塞天地亘古今无有乎弗具无有乎弗同无有乎或变者也是常道也以言其阴阳消息之行焉则谓之易以言其纪纲政事之施焉则谓之书以言其歌咏性情之发焉则谓之诗以言其条理节文之著焉则谓之礼以言其欣喜和平之生焉则谓之乐以言其诚伪邪正之辨焉则谓之春秋是阴阳消息之行也以至于诚伪邪正之辨也一也皆所谓心也性也命也通人物达四海塞天地亘古今无有乎弗具无有乎弗同无有乎或变者也夫是之谓六经六经者非他吾心之常道也是故易也者志吾心之阴阳消息者也书也者志吾心之纪纲政事者也诗也者志吾心之歌咏性情者也礼也者志吾心之条理节文者也乐也者志吾心之欣喜和平者也春秋也者志吾心之诚伪邪正者也君子之于六经也求之吾心之阴阳消息而时行焉所以尊易也求之吾心之纪纲政事而时施焉所以尊书也求之吾心之歌咏性情而时发焉所以尊诗也求之吾心之条理节文而时著焉所以尊礼也求之吾心之欣喜和平而时生焉所以尊乐也求之吾心之诚伪邪正而时辨焉所以尊春秋也盖昔者圣人之扶人极忧后世而述六经也犹之富家者之父祖虑其产业库藏之积其子孙者或至于遗忘散失卒困穷而无以自全也而记籍其家之所有以贻之使之世守其产业库藏之积而享用焉以免于困穷之患故六经者吾心之记籍也而六经之实则具于吾心犹之产业库藏之实积种种色色具存于其家其记籍者特名状数目而已而世之学者不知求六经之实于吾心而徒考索于影响之间牵制于文义之末硁硁然以为是六经矣是犹富家之子孙不务守视享用其产业库藏之实积日遗忘散失至为窭人丐夫而犹嚣嚣然指其记籍曰「斯吾产业库藏之积也」何以异于是呜呼六经之学其不明于世非一朝一夕之故矣尚功利崇邪说是谓乱经习训诂传记诵没溺于浅闻小见以涂天下之耳目是谓侮经侈淫辞竞诡辩饰奸心盗行逐世垄断而犹自以为通经是谓贼经若是者是并其所谓记籍者而割裂弃毁之矣宁复知所以为尊经也乎越城旧有稽山书院在卧龙西冈荒废久矣郡守渭南南君大吉既敷政于民则慨然悼末学之支离将进之以圣贤之道于是使山阴令吴君瀛拓书院而一新之又为尊经之阁于其后曰「经正则庶民兴庶民兴斯无邪慝矣」阁成请予一言以谂多士予既不获辞则为记之若是呜呼世之学者得吾说而求诸其心焉其亦庶乎知所以为尊经也矣", "经，是常道。它在天上叫做命，它赋予人叫做性，它主宰身叫做心。心、性、命，是一回事。贯通人物，遍达四海，充塞天地，终贯古今，没有不具备的，没有不相同的，没有或改变的，这就是常道。它应于感触，就是恻隐、羞恶、辞让、是非；它显现在事情上，就是父子的亲、君臣的义、夫妇的别、长幼的序、朋友的信。这恻隐、羞恶、辞让、是非，这亲、义、序、别、信，是一回事，都是所谓的心、性、命。贯通人物，遍达四海，充塞天地，终贯古今，没有不具备的，没有不相同的，没有或改变的，这就是常道。\n就它讲阴阳消长的运行来说，就叫做《易》；就它讲纲纪政事的施行来说，就叫做《书》；就它讲歌咏性情的抒发来说，就叫做《诗》；就它讲条理节文的显著来说，就叫做《礼》；就它讲欣喜平和的产生来说，就叫做《乐》；就它讲诚伪邪正的辨别来说，就叫做《春秋》。这阴阳消长的运行，直到诚伪邪正的辨别，是一回事，都是所谓的心、性、命。贯通人物，遍达四海，充塞天地，终贯古今，没有不具备的，没有不相同的，没有或改变的。这就叫做六经。六经不是别的，是我心的常道。\n所以《易》，是记录我心的阴阳消长的；《书》，是记录我心的纲纪政事的；《诗》，是记录我心的歌咏性情的；《礼》，是记录我心的条理节文的；《乐》，是记录我心的欣喜平和的；《春秋》，是记录我心的诚伪邪正的。君子对于六经，求我心的阴阳消长而按时施行，是用来尊《易》；求我心的纲纪政事而按时施行，是用来尊《书》；求我心的歌咏性情而按时抒发，是用来尊《诗》；求我心的条理节文而按时显著，是用来尊《礼》；求我心的欣喜平和而按时产生，是用来尊《乐》；求我心的诚伪邪正而按时辨别，是用来尊《春秋》。\n从前圣人扶立人伦的准则、忧念后世而著述六经，好比富家的父祖，忧虑那产业库藏的积蓄，他的子孙或许至于遗忘散失，终于困穷而无从自全，于是记录他家所有的东西留给他们，使他们世代守住那产业库藏的积蓄而享用，以免于困穷的忧患。所以六经，是我心的记录簿，而六经的实体都具备在我心中，好比产业库藏的实有积蓄，种种色色，都存在他家里，那记录簿，只是名目数目而已。而世上的学者，不知道在我心中寻求六经的实体，却只在影响之间考索，拘泥于文义的末节，硁硁然以为这就是六经了。这好比富家的子孙，不致力于守视享用那产业库藏的实有积蓄，一天天遗忘散失，以至于成为穷人和乞丐，却还嚣嚣然指着他的记录簿说：「这是我的产业库藏的积蓄！」同这有什么不同呢？\n唉！六经之学，它不显明于世上，不是一朝一夕的缘故了。崇尚功利，崇奉邪说，这叫做乱经；习训诂，专门记诵，沉溺于浅薄的见闻，来涂塞天下的耳目，这叫做侮经；侈谈淫辞，争竞诡辩，掩饰奸心盗行，追逐世俗、垄断利益，却还自以为通晓经书，这叫做贼经。像这样的人，是连那所谓的记录簿都割裂弃毁了，难道还知道为什么尊经吗？\n越城旧有稽山书院，在卧龙西冈，荒废很久了。郡守渭南南大吉君，既已施政于民，就慨然哀悼末学的支离，将要用圣贤之道来引导他们，于是派山阴县令吴瀛君扩建书院并使之焕然一新，又在它后面建尊经阁，说：「经正了百姓就兴起；百姓兴起，就没有邪恶了。」阁建成，请我说一句话来劝告众士人。我既不能推辞，就写了这样一篇记。唉！世上的学者，得到我的说法而在自己心中寻求它，那也就差不多知道为什么尊经了。"],
    [228, "guwen-gwj-219", "", "出成都南门左为万里桥西折纤秀长曲所见如连环如玦如带如规如钩色如鉴如琅玕如绿沉瓜窈然深碧潆回城下者皆浣花溪委也然必至草堂而后浣花有专名则以少陵浣花居在焉耳行三四里为青羊宫溪时远时近竹柏苍然隔岸阴森者尽溪平望如荠水木清华神肤洞达自宫以西流汇而桥者三相距各不半里舁夫云通灌县或所云「江从灌口来」是也人家住溪左则溪蔽不时见稍断则复见溪如是者数处缚柴编竹颇有次第桥尽一亭树道左署曰「缘江路」过此则武侯祠祠前跨溪为板桥一覆以水槛乃睹「浣花溪」题榜过桥一小洲横斜插水间如梭溪周之非桥不通置亭其上题曰「百花潭水」由此亭还度桥过梵安寺始为杜工部祠像颇清古不必求肖想当尔尔石刻像一附以本传何仁仲别驾署华阳时所为也碑皆不堪读钟子曰杜老二居浣花清远东屯险奥各不相袭严公不死浣溪可老患难之于朋友大矣哉然天遣此翁增夔门一段奇耳穷愁奔走犹能择胜胸中暇整可以应世如孔子微服主司城贞子时也时万历辛亥十月十七日出城欲雨顷之霁使客游者多由监司郡邑招饮冠盖稠浊磬折喧溢迫暮趣归是日清晨偶然独往楚人钟惺记", "出成都南门，左边是万里桥。向西曲折纤秀长曲，所见到的像连环、像玉玦、像带子、像圆规、像钩子，颜色像镜子、像美玉、像绿沉瓜，幽深碧绿、萦回城下的，都是浣花溪的支流。然而一定到草堂，然后浣花才有专名，那是因为少陵的浣花草堂在那里罢了。\n走三四里是青羊宫，溪时远时近。竹柏苍翠、隔岸阴森的，布满溪边，平望像荠菜。水木清华，神肤通达。从青羊宫以西，水流汇合处架桥的有三座，相距各不到半里。抬轿的人说通灌县，或许所说的「江从灌口来」就是这样。\n人家住在溪左，溪就被遮蔽不常看见；稍一断开就又看见溪。像这样的有几处，捆柴编竹，颇有序次。桥走尽，一座亭子立在路左，题写「缘江路」。过了这里就是武侯祠。祠前横跨溪水有一座板桥，上面盖着水槛，才看到「浣花溪」的题榜。过桥，一个小洲横斜插在水中像梭子，溪水环绕它，没有桥不通。在它上面建亭，题写「百花潭水」。由此亭返回，过桥，经梵安寺，才是杜工部祠。画像很清古，不必求像，想来应当如此。一尊石刻像，附以本传，是何仁仲别驾代理华阳时所作。碑文都不能读了。\n钟子说：杜老的两处居所，浣花清远，东屯险奥，各不相袭。严公不死，浣花溪可以养老，患难对于朋友太重要了！然而上天派这位老人增添夔门一段奇景罢了。穷愁奔走，还能选择胜景，胸中宽闲整齐，可以应世，如同孔子微服住在司城贞子家时一样。\n当时是万历辛亥年十月十七日。出城时将下雨，不久放晴。使者游客，多由监司郡邑招饮，冠盖拥挤杂乱，躬身喧哗，到傍晚就急急回去。这天清晨，偶然独自前往。楚人钟惺记。"],
    [229, "guwen-gwj-220", "", "初四日兀坐听雪溜竟日初五日平明从天都峰坳中北下二里石壁岈然其下莲花洞正与前坑石笋对峙一坞幽然别澄源下山至前岐路侧向莲花峰而趋一路奇峭险仄皆身历其境初六日天色甚朗觅导者各携筇上山过慈光寺从左上石峰环夹其中石级为积雪所平一望如玉疏木茸茸中仰见群峰盘结天都独巍然上挺数里级愈峻雪愈深其阴处冻雪成冰坚滑不容着趾余独前持杖凿冰得一孔置前趾再凿一孔以移后趾从行者俱循此法得度上至平冈则莲花云门诸峰争奇竞秀若为天都拥卫者由此而入绝巇危崖尽皆怪松悬结高者不盈丈低仅数寸平顶短鬣盘根虬干愈短愈老愈小愈奇不意奇山中又有此奇品也初七日天都峰已登独莲花未上莲花峰居黄山之中独出诸峰上四面岩壁环耸遇朝阳霁色鲜映层发令人狂叫欲舞初八日由接引崖踏雪下历险数处下至坑中又直上三里从石间得一径上莲花峰四望空碧即天都亦俯首矣盖是峰居黄山之中独出诸峰之上即天都亦俯首矣各峰四面嶙峋如一朵菡萏出水余登其上恍若置身天表自念生平之游此为最矣初九日循山北行仰见天都峰森然觉黄山诸峰之胜已尽于此然黄山绝顶大悲顶为最而莲花为奇余既两登莲花复一登天都探其幽奇各极妙境每遇奇峰怪石必攀跻而上揣摹其形务穷其变凡山之峻险窈窕无不领略焉是行也以峰名者前后共历数十峰皆历历可指余游黄山凡四日而阴晴变态一日之内顷刻不同如有奇峰以览其胜则又大快", "初四日，整天独自坐着听雪融化流下。\n初五日，天亮时，从天都峰的山坳中向北下二里，石壁深险。它下面有莲花洞，正与前坑的石笋对峙，一片山坞幽深。告别澄源，下山到前面的岔路旁，向着莲花峰快步走去。一路奇特陡峭险仄，都亲身经历。\n初六日，天色很晴朗。找向导各自带着竹杖上山，经过慈光寺。从左边上去，石峰环绕夹峙，其中的石阶被积雪填平，一望如玉。稀疏的树木细茸茸中，抬头看见群峰盘结，天都峰独巍然上挺。走了几里，石阶越陡，雪越深，那背阴处冻雪成冰，坚硬滑溜不容落脚。我独自向前，拿着杖凿冰，凿出一个孔放下前脚趾，再凿一个孔，来移后脚趾。跟从的人都照这个办法得以通过。上到平冈，那么莲花、云门诸峰，争奇竞秀，像是为天都峰拥卫的。从这里进去，绝壁危崖，全都是怪松悬结。高的不满一丈，低的只有几寸，平顶短鬣，盘根虬干，越短越老，越小越奇，没想到奇山中又有这样奇特的品种！\n初七日，天都峰已经登过，只有莲花峰没有上。莲花峰在黄山之中，独出于诸峰之上。四面岩壁环绕耸立，遇到朝阳晴色，鲜明映照层层发出，令人狂叫想跳舞。\n初八日，从接引崖踏雪而下，经历几处险境。下到坑中，又直上三里，从石间找到一条小径，上莲花峰。四望空碧，即使天都峰也俯首了。这峰居于黄山之中，独出于诸峰之上，即使天都峰也俯首了。各峰四面嶙峋，像一朵荷花出水。我登上它，恍若置身天外。自想生平的游历，这次是最好的了。\n初九日，沿着山向北走，仰见天都峰森然，觉得黄山诸峰的胜景，已经尽在这里了。\n然而黄山的绝顶，大悲顶最高，而莲花峰最奇。我既两次登莲花峰，又一次登天都峰，探求它们的幽奇，各自穷尽妙境。每遇到奇峰怪石，一定攀爬而上，揣摩它的形状，务必穷尽它的变化，凡是山的峻险窈窕，没有不领略的。\n这次出行，以峰命名的，前后共经历数十峰，都历历可指。我游黄山，共四天，而阴晴变化，一天之内，顷刻不同。如果有奇峰来观赏它的胜景，那就又大快人心了。"],
    [230, "guwen-gwj-222", "", "余读东京梦华录武林旧事记当时演史小说者数十人自此以来其姓名不可得闻乃近年共称柳敬亭之说书柳敬亭者扬之泰州人本姓曹年十五犷悍无赖犯法当死变姓柳之盱眙市中为人说书已能倾动其市人久之过江云间有儒生莫后光见之曰「此子机变可使以其技鸣」于是谓之曰「说书虽小技然必句性情习方俗如优孟摇头而歌而后可以得志」敬亭退而凝神定气简练揣摩期月而诣莫生生曰「子之说能使人欢咍嗢噱矣」又期月生曰「子之说能使人慷慨涕泣矣」又期月生喟然曰「子言未发而哀乐具乎其前使人之性情不能自主盖进乎技矣」由是之扬之杭之金陵名达于缙绅间华堂旅会闲亭独坐争延之使奏其技无不当于心称善也宁南南下皖帅欲结欢宁南致敬亭于幕府宁南以为相见之晚使参机密军中亦不敢以说书目敬亭宁南不知书所有文檄幕下儒生设意修词援古证今极力为之宁南皆不悦而敬亭耳剽口熟从委巷活套中来者无不与宁南意合尝奉命至金陵是时朝中皆畏宁南闻其使人来莫不倾动加礼宰执以下俱使之南面上坐称柳将军敬亭亦无所不安也其市井小人昔与敬亭尔汝者从道旁私语「此故吾侪同说书者也今富贵若此」亡何国变宁南死敬亭丧失其资略尽贫困如故时始复上街头理其故业敬亭既在军中久其豪猾大侠杀人亡命流离遇合破家失国之事无不身亲见之且五方土音乡俗好尚习见习闻每发一声使人闻之或如刀剑铁骑飒然浮空或如风号雨泣鸟悲兽骇亡国之恨顿生檀板之声无色有非莫生之言可尽者矣", "我读《东京梦华录》《武林旧事记》，当时演史小说的人有几十个。从这以来，他们的姓名不能知道了。而近年共同称道柳敬亭的说书。\n柳敬亭，是扬州泰州人，本姓曹。十五岁时，粗野强横无赖，犯法当死，改姓柳，到盱眙市中给人说书，已经能倾倒打动那市里的人。久了，过江，松江有儒生莫后光见到他，说：「这年轻人机敏善变，可以使他的技艺闻名。」于是对他说：「说书虽然是小的技艺，但一定要切合性情，熟悉地方风俗，像优孟摇头而歌，然后才能得志。」敬亭回去后凝神定气，精练揣摩，满一个月去见莫生。莫生说：「你的说书，能使人欢笑逗乐了。」又满一个月，莫生说：「你的说书，能使人慷慨流泪了。」又满一个月，莫生感叹说：「你话还没出口而哀乐已经在他的前面，使人的性情不能自主，大概是进于技艺之上的了。」由此到扬州，到杭州，到金陵，名声达于缙绅之间。华堂集会，闲亭独坐，都争着请他演奏技艺，没有不称心的。\n宁南侯南下，皖帅想结好宁南侯，把敬亭送到幕府致敬。宁南侯认为相见过晚，让他参与机密。军中也不敢把说书看待敬亭。宁南侯不识字，所有文书檄文，幕下儒生设意修词，援古证今，极力去做，宁南侯都不喜欢。而敬亭耳闻口熟，从里巷活套中来的，没有不与宁南侯心意相合的。曾奉命到金陵，当时朝中都畏惧宁南侯，听说他派人来，没有不倾动加礼的，宰执以下都让他南面而坐，称柳将军，敬亭也没有不安。那些市井小人从前与敬亭你我相称的，在路旁私语：「这是我们从前一起说书的人，如今富贵到这样！」\n不久国家变故，宁南侯死。敬亭丧失他的资财几乎尽了，贫困像从前一样，才又上街头重操旧业。敬亭既已在军中久了，那些豪猾大侠、杀人亡命、流离遇合、破家失国的事，没有不亲身见到的，而且各地方言，乡俗好尚，习见习闻，每次发出一声，使人听了，有的像刀剑铁骑，飒然浮空，有的像风号雨泣，鸟悲兽骇，亡国之恨顿时生出，檀板的声音都失了色，有不是莫生的话所能说尽的。"],
    [231, "guwen-gwj-223", "", "有生之初人各自私也人各自利也天下有公利而莫或兴之有公害而莫或除之有人者出不以一己之利为利而使天下受其利不以一己之害为害而使天下释其害此其人之勤劳必千万于天下之人夫以千万倍之勤劳而己又不享其利必非天下之人情所欲居也故古之人君量而不欲入者许由务光是也入而又去之者尧舜是也初不欲入而不得去者禹是也岂古之人有所异哉好逸恶劳亦犹夫人之情也后之为人君者不然以为天下利害之权皆出于我我以天下之利尽归于己以天下之害尽归于人亦无不可使天下之人不敢自私不敢自利以我之大私为天下之大公始而惭焉久而安焉视天下为莫大之产业传之子孙受享无穷汉高帝所谓「某业所就孰与仲多」者其逐利之情不觉溢之于辞矣此无他古者以天下为主君为客凡君之所毕世而经营者为天下也今也以君为主天下为客凡天下之无地而得安宁者为君也是以其未得之也荼毒天下之肝脑离散天下之子女以博我一人之产业曾不惨然曰「我固为子孙创业也」其既得之也敲剥天下之骨髓离散天下之子女以奉我一人之淫乐视为当然曰「此我产业之花息也」然则为天下之大害者君而已矣向使无君人各得自私也人各得自利也呜呼岂设君之道固如是乎古者天下之人爱戴其君比之如父拟之如天诚不为过也今也天下之人怨恶其君视之如寇仇名之为独夫固其所也而小儒规规焉以君臣之义无所逃于天地之间至桀纣之暴犹谓汤武不当诛之而妄传伯夷叔齐无稽之事使兆人万姓崩溃之血肉曾不异夫腐鼠岂天地之大于兆人万姓之中独私其一人一姓乎是故武王圣人也孟子之言圣人之言也后世之君欲以如父如天之空名禁人之窥伺者皆不便于其言至废孟子而不立非导源于小儒乎虽然使后之为君者果能保此产业传之无穷亦无怪乎其私之也既以产业视之人之欲得产业谁不如我摄缄縢固扃鐍一人之智力不能胜天下欲得之者之众远者数世近者及身其血肉之崩溃在其子孙矣昔人愿世世无生帝王家而毅宗之语公主亦曰「若何为生我家」痛哉斯言回思创业时其欲得天下之心有不废然摧沮者乎是故明乎为君之职分则唐虞之世人人能让许由务光非绝尘也不明乎为君之职分则市井之间人人可欲许由务光所以旷后世而不闻也然君之职分难明以俄顷淫乐不易无穷之悲虽愚者亦明之矣", "人生之初，人人各自为己，人人各自为利，天下有公利而没有谁来兴办它，有公害而没有谁来除去它。有这样的人出来，不把一己的利益当作利益，而使天下人享受那利益；不把一己的祸害当作祸害，而使天下人免除那祸害。这样的人的勤劳一定千万倍于天下的人。以千万倍的勤劳，而自己又不享受那利益，一定不是天下人的常情所愿处的。所以古代的人君，衡量而不愿就位的，是许由、务光；就位而又离去的，是尧、舜；起初不愿就位而不能离去的，是禹。难道古人有什么不同吗？好逸恶劳，也还是人的常情。\n后世做人君的却不这样，认为天下利害的权都出于我，我把天下的利益都归给自己，把天下的祸害都归给别人，也没有什么不可；使天下的人不敢为己，不敢为利，用我的大私作为天下的大公。起初还惭愧，久了就安之若素，把天下看作莫大的产业，传给子孙，享受无穷。汉高帝所说的「我的产业成就，与老二相比谁多」，那追逐利益的心情，不觉流露于言辞了。这没有别的，古时以天下为主，君为客，凡是君用尽一生所经营的，都为天下。如今以君为主，天下为客，凡是天下没有地方得到安宁的，都为君。所以他没有得到时，荼毒天下人的肝脑，离散天下人的子女，来博取我一人的产业，竟不惨然，说：「我本来是为子孙创业。」他既已得到时，敲剥天下人的骨髓，离散天下人的子女，来供奉我一人的淫乐，看作当然，说：「这是我产业的利息。」那么成为天下的大害的，只是君罢了。假使没有君，人人得以各自为己，人人得以各自为利。唉，难道设立君的道理本来就是这样吗！\n古时天下的人爱戴他们的君，比作父亲，拟作上天，确实不算过分。如今天下的人怨恨厌恶他们的君，看作仇敌，称他为独夫，本来是应该的。而小儒拘谨地认为君臣的大义无逃于天地之间，至于桀、纣的暴虐，还说汤、武不应当诛杀他们，而妄传伯夷、叔齐无稽的事，使亿万百姓崩溃的血肉，竟与腐鼠没有什么不同。难道天地之大，在亿万百姓之中，单单私爱他一人一姓吗？所以武王是圣人，孟子的话，是圣人的话。后世的君，想用如父如天的空名禁止别人窥伺的，都不便用那些话，以至于废除孟子而不立，不是导源于小儒吗！\n虽然如此，假使后世做君的，果真能保住这产业，传之无穷，也无怪乎他私有了。既已把天下看作产业，那么人想得到产业，谁不和我一样？绑紧绳索，加固门锁，一人的智力，不能胜过天下想得到它的人的众多，远的几代，近的及身，那血肉的崩溃，就在他的子孙了。从前的人愿世世代代不生在帝王家，而毅宗对公主说，也说：「你为什么生在我家！」这话痛啊！回想创业时，他想得天下的心，有不颓然沮丧的吗？所以明白做君的职分，那么唐、虞的时代，人人能让，许由、务光不是绝尘；不明白做君的职分，那么市井之间，人人可以贪求，许由、务光之所以后世不再听闻。然而君的职分难以明白，用片刻的淫乐，不换无穷的悲哀，即使愚笨的人也明白的。"],
    [232, "guwen-gwj-224", "", "旧中涓范君养民以崇祯十七年夏自京师徒步入华山为黄冠数年始克结庐于西峰之左名曰复庵华下之贤士大夫多与之游环山之人皆信而礼之而范君固非方士者流也幼而读书好楚辞诸子及经史多所涉猎为东宫伴读方李自成之挟东宫二王以出也范君知其必且西奔于是弃其家走之关中将尽厥职焉乃东宫不知所之而范君为黄冠矣太华之山悬崖之巅有松可荫有地可蔬有泉可汲不税于官不隶于宫观之籍华下之人或助之材以创是庵而居之有屋三楹东向以迎日出余尝一宿其庵开户而望大河之东雷首之山苍然突兀伯夷叔齐之所采薇而饿者若揖让乎其间固范君之所慕而为之者也自是而南则商山之岭也信国文公高阳孙公之所从出也又从而北则五台之山宋参知政事楚国公王公之说元主以不杀者故范君之所为拳拳也乃其一念之诚遂能与天地之正气相为感召则范君今日之庵其亦有不随山河而俱往者乎予读其记感其志为之记", "前朝宦官范养民君，在崇祯十七年夏天，从京城徒步进入华山做道士。几年后，才能够在西峰的左边建起草庐，名叫复庵。华山的贤士大夫多与他交游，环山的人都信服而尊敬他。\n而范君本来不是方士之流。幼年读书，喜好《楚辞》；诸子以及经史多有涉猎。做东宫伴读，当李自成挟持东宫二王出逃时，范君知道他们一定会向西奔，于是抛弃他的家跑到关中，将要尽他的职分。然而东宫不知去向，而范君就做了道士。\n太华之山，悬崖的顶端，有松可以遮荫，有地可以种菜，有泉可以汲取，不向官府纳税，不归入宫观的册籍。华山的人有的资助他材料，来创建这庵居住。有屋三间，向东来迎接日出。\n我曾在他的庵中住过一夜。开门望去，黄河的东面，雷首山苍翠突兀，是伯夷叔齐采薇而饿死的地方，像在揖让于其间，本来是范君所仰慕而效法的。从这里向南，就是商山的山岭，是信国文公、高阳孙公所从出的地方。又从这里向北，就是五台山，是宋朝参知政事、楚国公王公劝说元主不要杀人的地方，所以是范君所拳拳在念的。\n而他一念的真诚，就能与天地的正气相为感召，那么范君今日的庵，大概也有不随山河而俱往的吧？\n我读他的记，感慨他的志，为他作记。"],
    [233, "guwen-gwj-226", "", "江天一字文石徽州歙县人少丧父事其母及抚弟天表具有至性尝语人曰「士不立品者必无文章」前明崇祯间县令傅岩奇其才每试辄拔置第一年三十六始得补诸生家贫屋败躬畚土筑垣以居覆瓦不完盛暑则暴酷日中雨至淋漓蛇伏或张敝盖自蔽家人且怨且叹而天一挟书吟诵自若也天一游淮安淮安阎生某故与天一友会阎生家横被诬构天一为辨其冤得白而天一之在狱也亦以是脱大兵既破江南诸州县多起兵拒守天一与其友张某倡议拒守未几而败天一被执慷慨语人曰「吾自束发受书知有君臣之义今事已至此吾死耳」遂与某俱被戮先是天一尝被逮赖其友营救得免至是又为其友所连而天一不以尤也曰「吾固愿为之死何尤焉」初天一之友张某者亦奇士与天一善与之同死天表之被赦君之母弟亦以君故得全论曰天一虽不同然独以文行重乡里方其被执人皆惜之谓天一之才使得位施功必有过人者然卒以不屈死岂非命哉惟其信义著于乡故能从容就义而不悔此亦足以不朽矣", "江天一，字文石，徽州歙县人。年少丧父，事奉他的母亲，以及抚养弟弟江天表，都有至性。曾对人说：「士人不树立品行的，一定没有文章。」前明崇祯年间，县令傅岩惊奇他的才能，每次考试都选拔他列为第一。年三十六岁，才得以补为诸生。家贫屋坏，亲自用畚箕挑土筑墙来居住。覆盖的瓦不完备，盛暑就暴露在酷日中。下雨时，淋得湿透像蛇一样伏着，有时张开破伞遮蔽自己。家人又怨又叹，而天一拿着书吟诵自如。\n天一游历淮安，淮安的阎生某人，本来与天一是朋友，恰逢阎生家横遭诬陷，天一为他辩解冤屈，得以昭雪。而天一在狱中，也因此脱免。\n清兵既已攻破江南，各州县多起兵拒守。天一与他的朋友张某，倡议拒守，不久失败。天一被捉，慷慨对人说：「我自从束发读书，知道有君臣的大义，如今事情已到这种地步，我死罢了！」于是与某人一起被杀。\n在这之前，天一曾被逮捕，靠他的朋友营救得以免罪。到这时，又被他的朋友牵连，而天一不因此责怪，说：「我本来就愿为他死，责怪什么呢？」\n起初，天一的朋友张某，也是奇士，与天一交好，与他同死。江天表被赦免，君的母弟，也因君的缘故得以保全。\n评论说：天一虽然未得志，然单单因文章品行被乡里看重。当他被捉时，人们都惋惜他，说天一的才能，如果得到位置施展功业，一定有超过常人的。然而终究因不屈而死，难道不是命吗？只因他的信义显于乡里，所以能从容就义而不悔，这也足以不朽了。"],
    [234, "guwen-gwj-227", "", "季子礼既倦于游将归而葺吾庐以居吾庐在宁都之翠微峰盖创于明之崇祯先征君之所经营而吾兄弟之所尝读书其中者也庐之胜曰翠微之峰峰之高出于云表其巅平旷可容数百人四望诸山皆培塿也其下有大池冬夏不涸林木蓊然多竹箭松杉之属吾兄弟既以世乱避地隐此凡数年而后去及乱定而吾兄弟或出而仕或散处四方庐遂荒废季子之归也乃即其旧址而营之为屋若干楹堂室庖湢皆具又以其隙地为圃为池植花木竹石之属凡庐之所以为胜者皆复其旧而视昔加丽焉吾闻而喜之夫季子之才可以出而仕矣而顾为此岂其志之所欲哉盖亦有不得已焉尔然而庐之胜与其兄弟之所以读书其中者其遗风余韵犹有存者季子居之而吾兄弟之志亦可以少慰矣古之人有言乐天知命故不忧季子之为此其亦乐天知命也夫吾庐之可乐其在斯乎其为是说以复之", "季弟魏礼，既已厌倦漫游，将回去修缮我的草庐来居住。我的草庐在宁都的翠微峰，是明朝崇祯年间创建的，是先征君所经营的，而我的兄弟曾在那里读书。\n草庐的胜景，叫翠微峰。峰的高，出于云外，它的顶上平坦空旷，可以容纳数百人。四望群山，都是小土堆。它下面有大池，冬夏不干。林木茂密，多竹箭松杉之类。\n我的兄弟既因世道动乱，避地隐居在这里，共几年而后离去。等到动乱平定，我的兄弟有的出仕，有的分散在四方，草庐就荒废了。\n季弟的归来，就原来的旧址而营造它，盖屋若干间，堂室厨房浴室，都齐备。又用它的空地，做园圃做池塘，种植花木竹石之类。凡是草庐所以为胜景的，都恢复了旧观，而且比从前更加美丽。\n我听了很高兴。以季弟的才能，可以出来做官了，却做这个，难道是他心志所想的吗？大概也有不得已罢了。然而草庐的胜景，和他兄弟所以在这里读书的，那遗风余韵，还有留存。季弟住在这里，而我的兄弟的志向，也可以稍稍安慰了。\n古人有话说：乐天知命，所以不忧愁。季弟这样做，大概也是乐天知命吧？我的草庐的快乐，大概就在这里吧！作这番议论来回复他。"],
    [235, "guwen-gwj-228", "", "顺治二年乙酉四月江都围急督相史忠烈公知势不可为集诸将而语之曰「吾誓与城为殉然仓皇中不可落于敌人之手以死谁为我临期成此大节者」副将军史德威慨然任之忠烈喜曰「吾尚未有子汝当以同姓为吾后吾上书太夫人谱汝诸孙中」二十五日城陷忠烈拔刀自裁诸将果争前抱持之忠烈大呼德威德威流涕不能执刃遂为诸将所拥而行至小东门大兵如林而至马副使鸣騄任太守民育及诸将刘都督肇基等皆死忠烈乃瞠目曰「我史阁部也」被执至南门和硕豫亲王以先生呼之劝之降忠烈大骂而死初忠烈遗言「我死当葬梅花岭上」至是德威求公之骨不可得乃以衣冠葬之或曰「城之破也有亲见忠烈青衣乌帽乘白马出天宁门投江死者未尝殒于城中也」自有是言大江南北遂谓忠烈未死已而英霍山师大起皆托忠烈之名仿佛陈涉之称项燕吴中孙公兆奎以起兵不克执至白下经略洪承畴与之有旧问曰「先生在兵间审知故扬州阁部史公果死耶抑未死耶」孙公答曰「经略从北来审知故松山殉难督师洪公果死耶抑未死耶」承畴大恚急呼麾下驱出斩之呜呼神仙诡诞之说谓颜太师以兵解文少保亦以悟大光明法蝉蜕实未尝死不知忠义者圣贤家法其气浩然常留天地之间何必出世入世之面目神仙之说所谓为蛇画足即如忠烈遗骸不可问矣百年而后予登岭上与客述忠烈遗言无不泪下如雨想见当日围城光景此即忠烈之面目宛然可遇是不必问其果解脱否也而况冒其未死之名者哉墓旁有丹徒钱烈女之冢亦以乙酉在扬凡五死而得绝时告其父母火之无留骨秽地扬人葬之于此江右王猷定关中黄遵岩粤东屈大均为作传铭哀词予登岭上与客述忠烈遗言无不泪下如雨", "顺治二年乙酉四月，江都被围紧急。督相史忠烈公知道形势不可为，召集诸将对他们说：「我发誓与城同殉，然而仓皇之中不能落在敌人手里而死，谁为我到临期成就这大节的？」副将军史德威慷慨地承担了。忠烈高兴说：「我还没有儿子，你应当以同姓做我的后人。我上书太夫人，把你记入诸孙之中。」\n二十五日，城陷，忠烈拔刀自杀。诸将果然争着上前抱住他。忠烈大呼德威，德威流泪，不能拿刀，于是被诸将簇拥而行。到小东门，清兵如林而来，马副使鸣騄、任太守民育以及诸将刘都督肇基等都死了。忠烈才瞪着眼说：「我是史阁部。」被捉到南门，和硕豫亲王用先生称呼他，劝他投降。忠烈大骂而死。起初，忠烈遗言：「我死后应当葬在梅花岭上。」到这时，德威找公的尸骨找不到，就用衣冠安葬他。\n有人说：「城破时，有人亲眼看见忠烈穿青衣戴乌帽，骑白马，出天宁门投江而死，不曾死在城中。」自从有了这话，大江南北，就说忠烈没有死。不久英山、霍山的义师大起，都假托忠烈的名义，仿佛陈涉假托项燕。\n吴中孙兆奎公因起兵不胜，被捉到南京。经略洪承畴与他有旧交，问他说：「先生在军队中，确实知道原扬州阁部史公果真死了呢，还是没死呢？」孙公答道：「经略从北方来，确实知道原松山殉难的督师洪公果真死了呢，还是没死呢？」承畴大怒，急呼部下把他驱出斩了。\n唉！神仙诡诞的说法，说颜太师因兵解，文少保也因悟大光明法而蝉蜕，其实不曾死。不知道忠义是圣贤的家法，那气浩然，常留在天地之间，何必论出世入世的面目！神仙的说法，是所谓为蛇画足。就像忠烈的遗骸，不可查问了，百年之后，我登上岭上，与客人讲述忠烈的遗言，没有不泪下如雨的，想见当日围城的光景，这就是忠烈的面目仿佛可以遇见，这不必问他果真解脱与否，何况假冒他没死的名义的呢？\n墓旁有丹徒钱烈女的坟，也是乙酉年在扬州，共死了五次才得绝命，当时告诉她的父母火化她，不要留骨在这秽地，扬州人安葬她在这里。江右王猷定、关中黄遵岩、粤东屈大均都为她作传铭哀词。\n我登上岭上，与客人讲述忠烈的遗言，没有不泪下如雨的。"],
    [236, "guwen-gwj-229", "", "芋老人者慈水祝渡人也子佣出独与妪居渡口一日有书生避雨檐下衣湿袖单影乃益瘦老人延入坐知从郡城就童子试归老人略知书与语久命妪煮芋以进尽一器再进生为之饱笑曰「他日不忘老人芋也」雨止别去十余年书生用甲第为相国偶命厨者进芋辍箸叹曰「何向者祝渡老人之芋之香而甘也」使人访其夫妇载以来丞尉闻之谓老人与相国有旧邀见讲钧礼子不佣矣至京相国慰劳曰「不忘老人芋今乃烦尔妪一煮芋也」已而妪煮芋进相国亦辍箸曰「何向者之香而甘也」老人前曰「犹是芋也而向者之香且甘者非调和之有异时位之移人也相公昔自郡城走数十里困于雨不择食矣今日堂有炼珍朝分尚食张筵列鼎尚何芋是甘乎老人犹喜相公之止于芋也老人老矣所闻实多村南有夫妇守贫者织纺井臼佐读勤苦幸获名成遂宠妾媵弃其妇致郁郁死是芋视乃妇也城东有甲乙同学者一砚一灯一窗一榻晨起不辨衣履乙先得举登仕路闻甲落魄笑不顾交以绝是芋视乃友也更闻谁氏子读书时愿他日得志廉干如古人某忠孝如古人某及为吏以污贿不饬罢是芋视乃学也是犹可言也老人邻有西塾闻其师为弟子说前代事有将相有卿尹有刺史守令或绾黄纡紫或揽辔褰帷一旦事变中起衅孽外乘辄屈膝叩首迎款惟恐或后竟以宗庙社稷身名君宠无不同于芋焉然则世之以今日而忘昔日者岂独一箸间哉」老人语未毕相国遽惊谢曰「老人知道者」厚资而遣之于是芋老人之名大著赞曰「老人能于倾盖不意作缘相国奇已不知相国何似能不愧老人之言否然就其不忘一芋固已贤夫并老人而芋视之者特怪老人虽知书又何长于言至是岂果知道者欤或传闻之过实耶嗟夫天下有缙绅士大夫所不能言而野老鄙夫能言者往往而然」", "芋老人，是慈水祝渡人。儿子外出做佣工，只与老妻住在渡口。一天，有个书生在屋檐下避雨，衣服湿了袖子单薄，身影就更加瘦弱。老人请他进来坐，知道他从郡城参加童子试回来。老人略懂诗书，与他谈了很久，叫老妻煮芋进献。吃完一器，再进，书生因此吃饱，笑着说：「他日不会忘记老人的芋。」雨停了，告别而去。\n十多年后，书生因科举甲第做了相国，偶然让厨子进芋，他停下筷子叹息说：「为什么从前祝渡老人的芋那样香而甜呢！」派人访求那对夫妇，用车子载来。县丞、县尉听说，说老人与相国有旧交，邀请相见行平等的礼节，儿子不再做佣工了。\n到了京城，相国慰劳说：「不忘老人的芋，如今就烦你的老妻煮一次芋。」不久老妻煮芋进献，相国也停下筷子说：「为什么从前的香而甜呢！」老人上前说：「还是这芋，而从前的香且甜，不是调和有不同，是时势、地位改变了人。相公从前从郡城走几十里，困于雨中，不择食物；如今堂上有精美的食品，朝廷分赐膳食，摆开筵席列着鼎，还怎么觉得芋甜呢？老人还高兴相公只是限于芋。老人老了，所听到的实在多：村南有夫妇守贫的，织布纺纱汲水舂米，资助读书勤苦，侥幸获得功名成就，就宠爱妾媵，抛弃他的妻子，以致她忧郁而死，这是把芋看待他的妻子。城东有甲乙同学的，共用一砚、一灯、一窗、一榻，早晨起来不辨谁的衣服鞋子，乙先中举，踏上仕途，听说甲落魄，笑着不顾，交情因此断绝，这是把芋看待他的朋友。又听说谁家的儿子，读书时，愿他日得志，廉洁干练像古人某人，忠孝像古人某人，等到做官，因贪污受贿不检点而被罢免，这是把芋看待他的学问。这还可以说；老人的邻居有西塾，听塾师为弟子讲前代的事，有将、相，有卿、尹，有刺史、守、令，有的系着金印穿着紫绶，有的揽缰绳撩车帷，一旦事变从中而起，祸患从外而来，就屈膝叩头迎接归附，惟恐落后，竟然把宗庙、社稷、身名、君宠，都同于芋一样。那么世上因今天而忘记从前的，难道只在一筷之间吗！」\n老人的话没说完，相国急忙惊谢说：「老人是知道道的！」丰厚地资助送他走。于是芋老人的名声大著。\n赞说：「老人能在偶然相遇中意外地与相国结缘，奇了！不知相国怎么样，能不愧对老人的话吗？然而就他不忘一芋来说，本来已经贤于那些连老人也把芋看待的人。只是奇怪老人虽然懂诗书，又怎么擅长言谈到这种地步，难道真是知道道的吗？或者是传闻言过其实呢？唉！天下有缙绅士大夫所不能说的，而村野鄙夫能说的，往往如此。」"],
    [237, "guwen-gwj-230", "", "京中有善口技者会宾客大宴于厅事之东北角施八尺屏障口技人坐屏障中一桌一椅一扇一抚尺而已众宾团坐少顷但闻屏障中抚尺一下满坐寂然无敢哗者遥闻深巷中犬吠便有妇人惊觉欠伸其夫呓语既而儿醒大啼夫亦醒妇抚儿乳儿含乳啼妇拍而呜之又一大儿醒絮絮不止当是时妇手拍儿声口中呜声儿含乳啼声大儿初醒声夫叱大儿声一时齐发众妙毕备满坐宾客无不伸颈侧目微笑默叹以为妙绝未几夫齁声起妇拍儿亦渐拍渐止微闻有鼠作作索索盆器倾侧妇梦中咳嗽宾客意少舒稍稍正坐忽一人大呼「火起」夫起大呼妇亦起大呼两儿齐哭俄而百千人大呼百千儿哭百千犬吠中间力拉崩倒之声火爆声呼呼风声百千齐作又夹百千求救声曳屋许许声抢夺声泼水声凡所应有无所不有虽人有百手手有百指不能指其一端人有百口口有百舌不能名其一处也于是宾客无不变色离席奋袖出臂两股战战几欲先走忽然抚尺一下群响毕绝撤屏视之一人一桌一椅一扇一抚尺而已", "京城里有个擅长口技的人。适逢宾客大宴，在厅事的东北角，设置八尺屏障，口技人坐在屏障中，只有一桌、一椅、一扇、一抚尺罢了。众宾客围坐。一会儿，只听得屏障中抚尺一拍，满座寂静，没有敢喧哗的。\n远远听到深巷中狗叫，就有妇人惊醒打哈欠伸懒腰，她的丈夫说梦话。不久孩子醒了，大哭。丈夫也醒了。妇人抚着孩子喂奶，孩子含着奶头哭，妇人拍着孩子哼着哄他。又一个大孩子醒了，絮絮不止。在这个时候，妇人手拍孩子的声音，口中哼的声音，孩子含奶头哭的声音，大孩子刚醒的声音，丈夫叱责大孩子的声音，一时一齐发出，各种妙处都具备。满座宾客没有不伸长脖子，斜着眼睛，微笑，默默赞叹，认为妙极了。\n不久，丈夫的鼾声起了，妇人拍孩子也渐渐拍渐渐停。隐约听到有老鼠作作索索，盆器翻倒，妇人在梦中咳嗽。宾客的心情稍稍舒缓，渐渐坐正。\n忽然一个人大呼「起火」，丈夫起来大呼，妇人也起来大呼。两个孩子一齐哭。一会儿百千人大呼，百千个孩子哭，百千条狗叫。中间有用力拉拽崩塌倒下的声音，火爆的声音，呼呼的风声，百千齐作；又夹杂百千求救的声音，拉塌房屋许许的声音，抢夺的声音，泼水的声音。凡是所应有的，无所不有。即使人有百只手，手有百个指头，不能指出其中的一端；人有百张口，口有百条舌，不能说出其中的一处。于是宾客没有不变了脸色离开座位，捋起袖子露出胳膊，两条腿发抖，几乎想要先跑。\n忽然抚尺一拍，所有的声音都断绝了。撤去屏障一看，只有一个人、一桌、一椅、一扇、一抚尺罢了。"],
    [238, "classic-gw-139", "public-domain", "庚戌十一月予自广陵归与陈子灿同舟子灿年二十八好武事予授以左氏兵谋兵法因问「数游南北逢异人乎」子灿为述大铁椎作大铁椎传大铁椎不知何许人北平陈子灿省兄河南与遇宋将军家宋怀庆青华镇人工技击七省好事者皆来学人以其雄健呼宋将军云宋弟子高信之亦怀庆人多力善射长子灿七岁少同学故尝与过宋将军时座上有健啖客貌甚寝右胁夹大铁椎重四五十斤饮食拱揖不暂去柄铁折叠环复如锁上练引之长丈许与人罕言语语类楚声扣其乡及姓字皆不答既同寝夜半客曰「吾去矣」言讫不见子灿见窗户皆闭惊问信之信之曰「客初至不冠不袜以蓝手巾裹头足缠白布大铁椎外一物无所持而腰多白金吾与将军俱不敢问也」子灿寐而醒客则鼾睡炕上矣一日辞宋将军曰「吾始闻汝名以为豪然皆不足用吾去矣」将军强留之乃曰「吾数击杀响马贼夺其物故仇我久居祸且及汝今夜半方期我决斗某所」宋将军欣然曰「吾骑马挟矢以助战」客曰「止贼能且众吾欲护汝则不快吾意」宋将军故自负且欲观客所为力请客客不得已与偕行将至斗处送将军登空堡上曰「但观之慎弗声令贼知也」时鸡鸣月落星光照旷野百步见人客驰下吹觱篥数声顷之贼二十余骑四面集步行负弓矢从者百许人一贼提刀突奔客客大呼挥椎贼应声落马马首裂众贼环而进客奋椎左右击人马仆地杀三十许人宋将军屏息观之股栗欲堕忽闻客大呼曰「吾去矣」尘滚滚东向驰去后遂不复至", "庚戌年十一月，我从广陵回来，和陈子灿同坐一条船。子灿二十八岁，喜好武艺，我把左氏兵谋兵法教给他，于是问他「你多次游历南北，遇到过异人吗？」子灿为我讲述了大铁椎的事，于是我写了《大铁椎传》。\n大铁椎，不知是哪里人。北平陈子灿到河南探望兄长，在宋将军家遇到他。宋将军是怀庆青华镇人，擅长搏击，七省喜好武艺的人都来向他学习，人们因他雄健，称他宋将军。宋将军的弟子高信之，也是怀庆人，力气大、善射箭，比子灿大七岁，小时候同学，所以曾和子灿一起拜访宋将军。\n当时座上有位很能吃的客人，相貌很丑，右腋下夹着大铁椎，重四五十斤，连饮食拱手作揖时也不暂时放下。椎柄的铁链折叠环绕，像锁上的链条，拉开长一丈左右。他很少和人说话，说话像楚地口音，问他乡里和姓名，都不回答。\n后来同睡一室，半夜，客人说：「我走了！」说完就不见了。子灿见窗户都关着，惊问信之。信之说：「客人刚来时，不戴帽不穿袜，用蓝手巾裹头，脚缠白布，除大铁椎外，不带一件东西，而腰间带着许多银子。我和将军都不敢问。」子灿睡下又醒，客人已经在炕上打着呼噜熟睡了。\n有一天，客人辞别宋将军说：「我起初听说你的名声，以为你是豪杰，然而都不顶用。我走了！」将军极力挽留他，他才说：「我多次击杀响马贼，夺了他们的东西，所以他们恨我。久留，灾祸会连累你。今天半夜，他们正约我在某处决斗。」宋将军高兴地说：「我骑马带箭去助战。」客人说：「别去！贼人有本事而且人多，我要保护你，就不能尽情发挥。」宋将军本自负有本事，又想看客人怎么打，极力请求同去。客人不得已，和他同行。快到决斗处，把将军送上空堡，说：「只在这里看，千万不要出声，免得让贼人知道。」\n当时鸡鸣月落，星光照着旷野，百步之内能看见人。客人奔驰而下，吹了几声觱篥。一会儿，贼人二十多骑从四面聚来，步行背着弓箭跟随的有一百来人。一个贼提刀奔冲向客人，客人大呼挥椎，贼应声落马，马头迸裂。众贼包围上来，客人奋力挥椎左右击打，人仰马翻，杀了三十来人。宋将军屏住呼吸观看，两腿发抖快要掉下来。忽然听到客人大呼：「我走了。」尘土滚滚，向东奔驰而去。此后就不再来了。"],
    [240, "classic-gw-116", "public-domain", "六国破灭非兵不利战不善弊在赂秦赂秦而力亏破灭之道也或曰六国互丧率赂秦耶曰不赂者以赂者丧盖失强援不能独完故曰弊在赂秦也秦以攻取之外小则获邑大则得城较秦之所得与战胜而得者其实百倍诸侯之所亡与战败而亡者其实亦百倍则秦之所大欲诸侯之所大患固不在战矣思厥先祖父暴霜露斩荆棘以有尺寸之地子孙视之不甚惜举以予人如弃草芥今日割五城明日割十城然后得一夕安寝起视四境而秦兵又至矣然则诸侯之地有限暴秦之欲无厌奉之弥繁侵之愈急故不战而强弱胜负已判矣至于颠覆理固宜然古人云「以地事秦犹抱薪救火薪不尽火不灭」此言得之呜呼以赂秦之地封天下之谋臣以事秦之心礼天下之奇才并力西向则吾恐秦人食之不得下咽也悲夫有如此之势而为秦人积威之所劫日削月割以趋于亡为国者无使为积威之所劫哉", "六国的灭亡，不是因为武器不锋利，仗打得不好，弊病在于贿赂秦国。贿赂秦国，自己的国力就亏损，这就是灭亡的原因。有人说：六国相继灭亡，都是因为贿赂秦国吗？回答是：不贿赂秦国的国家因为贿赂秦国的国家而灭亡，因为失去了强大的援助，不能单独保全自己。所以说弊病在于贿赂秦国。\n秦国除了用战争夺取土地以外，小的能得到邑镇，大的能得到城池。比较秦国受贿赂所得到的土地，与战胜而得到的土地，实际上要多到百倍；诸侯贿赂秦国所丧失的土地，与战败所丧失的土地，实际上也要多到百倍。那么秦国最大的欲望，诸侯最大的祸患，本来就不在于战争了。回想他们的祖辈父辈，冒着霜露，披荆斩棘，才得到很少的土地。子孙对待这些土地却不很爱惜，拿来送给别人，好像丢弃小草一样。今天割让五座城，明天割让十座城，然后才能得到一夜的安稳觉。可是第二天起来看看四周边境，秦国的军队又到了。既然这样，那么诸侯的土地有限，强暴的秦国的欲望没有满足，诸侯送给秦国的越多，秦国侵犯得就越急。所以不用作战，谁强谁弱谁胜谁负就已经分清楚了。最终走向灭亡，道理本来就应该这样。古人说：「用土地侍奉秦国，就好像抱着柴去救火，柴不烧完，火就不会熄灭。」这话说对了。\n唉！如果六国用贿赂秦国的土地封赏天下的谋臣，用侍奉秦国的心意礼遇天下的奇才，合力向西对付秦国，那么我恐怕秦国人吃饭都不能咽下去。可悲啊！有这样的形势，却被秦国积久而成的威势所胁迫，天天削减，月月割让，以至于走向灭亡。治理国家的人不要被积久而成的威势所胁迫啊！"],
    [241, "guwen-gwj-50", "public-domain", "齐宣王见颜斶曰「斶前」斶亦曰「王前」宣王不悦左右曰「王人君也斶人臣也王曰『斶前』斶亦曰『王前』可乎」斶对曰「夫斶前为慕势王前为趋士与使斶为慕势不如使王为趋士」王忿然作色曰「王者贵乎士贵乎」对曰「士贵耳王者不贵」王曰「有说乎」斶曰「有昔者秦攻齐令曰『有敢去柳下季垄五十步而樵采者死不赦』令曰『有能得齐王头者封万户侯赐金千镒』由是观之生王之头曾不若死士之垄也」宣王曰「嗟乎君子焉可侮哉寡人自取病耳及今闻君子之言乃今闻细人之行愿请受为弟子且颜先生与寡人游食必太牢出必乘车妻子衣服丽都」颜斶辞去曰「夫玉生于山制则破焉非弗宝贵矣然大璞不完士生乎鄙野推选则禄焉非不得尊遂也然而形神不全斶愿得归晚食以当肉安步以当车无罪以当贵清静贞正以自娱制言者王也尽忠直言者斶也言要道已备矣愿得赐归安行而反臣之邑屋」则再拜而辞去也君子曰「斶知足矣归真反璞则终身不辱也」", "齐宣王召见颜斶，说：「颜斶，过来！」颜斶也说：「大王，过来！」宣王不高兴。左右的人说：「大王是君主，颜斶是臣子。大王说『颜斶过来』，颜斶也说『大王过来』，可以吗？」颜斶答道：「我上前是贪慕权势，大王上前是礼贤下士。与其让我贪慕权势，不如让大王礼贤下士。」\n宣王愤怒地变了脸色说：「是君主尊贵，还是士人尊贵？」颜斶答道：「士人尊贵，君主不尊贵。」宣王说：「有说法吗？」颜斶说：「有。从前秦国攻打齐国，下令说：『有敢到柳下季坟周围五十步内砍柴采摘的，处死不予赦免。』又下令说：『有能得到齐王头颅的，封为万户侯，赐金千镒。』由此看来，活着的君王的头，竟不如死去的士人的坟。」\n宣王说：「唉！君子怎么可以侮辱呢，我是自取其辱罢了！到今天听到君子的话，才知道小人的行为，希望请您收我为弟子。而且颜先生同我交游，吃的一定是太牢，出门一定乘车，妻子儿女衣服华美。」\n颜斶辞谢离去，说：「玉生在山上，加工就被破坏了，并不是不宝贵，只是大块璞玉不再完整。士人生在乡野，推举选拔就得到俸禄，并不是不能尊贵顺遂，只是形神不能保全。我希望能够回去，晚些吃饭当作吃肉，安步当车，没有罪过当作尊贵，清静贞正来自娱。制定言论的是大王，尽忠直言的是我颜斶。要道已经说尽了，希望让我回去，安然走回我家的屋舍。」于是拜了两拜辞别而去。\n君子说：「颜斶是知足的，回归本真、返归质朴，就能终身不受屈辱。」"],
    [242, "guwen-gwj-61", "public-domain", "楚襄王问于宋玉曰「先生其有遗行与何士民众庶不誉之甚也」宋玉对曰「唯然有之愿大王宽其罪使得毕其辞客有歌于郢中者其始曰下里巴人国中属而和者数千人其为阳阿薤露国中属而和者数百人其为阳春白雪国中属而和者不过数十人引商刻羽杂以流徵国中属而和者不过数人而已是其曲弥高其和弥寡」「故鸟有凤而鱼有鲲凤凰上击九千里绝云霓负苍天翱翔乎杳冥之上夫蕃篱之鷃岂能与之料天地之高哉鲲鱼朝发昆仑之墟暴鬐于碣石暮宿于孟诸夫尺泽之鲵岂能与之量江海之大哉」「故非独鸟有凤而鱼有鲲也士亦有之夫圣人瑰意琦行超然独处夫世俗之民又安知臣之所为哉」", "楚襄王问宋玉说：「先生大概有失检的行为吧？为什么士民大众这样不称赞您呢？」\n宋玉答道：「嗯，是的，有这样的事。希望大王宽恕我的罪过，让我把话说完。有客人在郢都唱歌，起初唱《下里》《巴人》，都城里跟着唱的有几千人；唱《阳阿》《薤露》，都城里跟着唱的有几百人；唱《阳春》《白雪》，都城里跟着唱的不过几十人；至于引商刻羽、杂以流徵，都城里跟着唱的不过几个人罢了。这就是曲调越高，能跟着唱的人越少。\n「所以鸟中有凤，鱼中有鲲。凤凰振翅上击九千里，穿过云霓，背负苍天，翱翔在极高远的地方；那篱笆间的鷃雀，怎么能同它计量天地的高远呢？鲲鱼早晨从昆仑山麓出发，在碣石晒鳍，傍晚宿在孟诸；那一尺深水泽里的鲵鱼，怎么能同它计量江海的广大呢？\n「所以不只是鸟中有凤、鱼中有鲲，士人中也有。圣人怀有卓越的心意、奇特的行为，超然独处，那世俗的人，又怎么能知道我的所作所为呢？」"]
    ]
  };
})();
